# Stage ASM 18 (neu auf Basis ASM 17): ODBC-Datenbankzugriff.
# ---------------------------------------------------------------------------
class D64ODBCError(RuntimeError):
    """Fehler beim Aufbau einer ODBC-Verbindung oder Ausfuehren von SQL."""


def _require_d64_pyodbc():
    if _d64_pyodbc is None:
        raise D64ODBCError(
            "ODBC-Unterstuetzung ist nicht installiert. "
            "Bitte 'py -m pip install pyodbc' in derselben Python-Umgebung ausfuehren."
        )
    return _d64_pyodbc


def odbc_python_binding_available() -> bool:
    """True, wenn das Python-Modul pyodbc erfolgreich geladen wurde."""
    return _d64_pyodbc is not None


def odbc_available_drivers() -> List[str]:
    """Liefert die auf dem System registrierten ODBC-Treiber."""
    module = _require_d64_pyodbc()
    try:
        return [str(name) for name in module.drivers()]
    except Exception as exc:
        raise D64ODBCError(f"ODBC-Treiber konnten nicht gelesen werden: {exc}") from exc


def odbc_process_bitness() -> int:
    """Bitness des aktuell laufenden Python-/PyInstaller-Prozesses."""
    return int(struct.calcsize("P") * 8)


def _odbc_registry_installed_drivers_by_bitness() -> Dict[int, set]:
    """Liest installierte Windows-ODBC-Treibernamen getrennt nach 32/64 Bit."""
    result: Dict[int, set] = {32: set(), 64: set()}
    if os.name != "nt":
        return result
    try:
        import winreg
    except ImportError:
        return result

    subkey = r"SOFTWARE\ODBC\ODBCINST.INI\ODBC Drivers"
    flag32 = int(getattr(winreg, "KEY_WOW64_32KEY", 0) or 0)
    flag64 = int(getattr(winreg, "KEY_WOW64_64KEY", 0) or 0)
    views: List[Tuple[int, int]] = []
    if flag32:
        views.append((32, flag32))
    if flag64:
        views.append((64, flag64))
    if not views:
        views.append((odbc_process_bitness(), 0))

    for bitness, view_flag in views:
        try:
            key = winreg.OpenKey(
                winreg.HKEY_LOCAL_MACHINE,
                subkey,
                0,
                winreg.KEY_READ | view_flag,
            )
        except OSError:
            continue
        try:
            index = 0
            while True:
                try:
                    name, state, _kind = winreg.EnumValue(key, index)
                except OSError:
                    break
                index += 1
                driver = str(name or "").strip()
                enabled = str(state or "").strip().casefold()
                if driver and enabled not in ("", "0", "false", "no", "disabled"):
                    result.setdefault(int(bitness), set()).add(driver.casefold())
        finally:
            winreg.CloseKey(key)
    return result


def _odbc_registry_data_sources_detailed() -> List[Tuple[str, str, int, str]]:
    """
    Liest Windows-ODBC-DSNs und ordnet sie einer echten Treiber-Bitness zu.

    Benutzer-DSNs sind auf 64-Bit-Windows ein Sonderfall: Windows kann denselben
    Benutzer-DSN in beiden ODBC-Administratoren anzeigen. Darum darf die Bitness
    bei HKCU *nicht* aus KEY_WOW64_32KEY/64KEY abgeleitet werden. Stattdessen
    wird der im DSN eingetragene Treiber gegen ODBCINST.INI der 32-/64-Bit-
    Treiberregistrierung aufgeloest.

    Rueckgabe: ``[(dsn, driver, bitness, scope), ...]``.
    """
    if os.name != "nt":
        return []
    try:
        import winreg
    except ImportError:
        return []

    ds_subkey = r"SOFTWARE\ODBC\ODBC.INI\ODBC Data Sources"
    drivers_by_bits = _odbc_registry_installed_drivers_by_bitness()
    rows: Dict[Tuple[str, int, str], Tuple[str, str, int, str]] = {}

    def add_dsn(dsn: str, driver: str, bitness: int, scope: str) -> None:
        dsn = str(dsn or "").strip()
        driver = str(driver or "").strip()
        if not dsn or bitness not in (32, 64):
            return
        key = (dsn.casefold(), int(bitness), scope.casefold())
        rows[key] = (dsn, driver, int(bitness), scope)

    def enum_values(root, view_flag: int = 0) -> List[Tuple[str, str]]:
        values: List[Tuple[str, str]] = []
        try:
            key = winreg.OpenKey(root, ds_subkey, 0, winreg.KEY_READ | int(view_flag))
        except OSError:
            return values
        try:
            index = 0
            while True:
                try:
                    name, driver, _kind = winreg.EnumValue(key, index)
                except OSError:
                    break
                index += 1
                dsn = str(name or "").strip()
                drv = str(driver or "").strip()
                if dsn:
                    values.append((dsn, drv))
        finally:
            winreg.CloseKey(key)
        return values

    flag32 = int(getattr(winreg, "KEY_WOW64_32KEY", 0) or 0)
    flag64 = int(getattr(winreg, "KEY_WOW64_64KEY", 0) or 0)
    views: List[Tuple[int, int]] = []
    if flag32:
        views.append((32, flag32))
    if flag64:
        views.append((64, flag64))
    if not views:
        views.append((odbc_process_bitness(), 0))

    # System-DSNs sind wirklich nach Registry-View getrennt.
    for bits, view_flag in views:
        for dsn, driver in enum_values(winreg.HKEY_LOCAL_MACHINE, view_flag):
            # Wenn der Treiber in dieser Architektur nicht installiert ist,
            # handelt es sich meist um einen verwaisten/falsch angelegten DSN.
            known = drivers_by_bits.get(bits, set())
            if driver and known and driver.casefold() not in known:
                continue
            add_dsn(dsn, driver, bits, "System")

    # Benutzer-DSNs NICHT anhand der Registry-View klassifizieren.
    # Einmal lesen und die vorhandenen Treiberarchitekturen aufloesen.
    user_values = enum_values(winreg.HKEY_CURRENT_USER, 0)
    seen_user = set()
    for dsn, driver in user_values:
        ident = (dsn.casefold(), driver.casefold())
        if ident in seen_user:
            continue
        seen_user.add(ident)
        matches = [
            bits for bits in (32, 64)
            if driver and driver.casefold() in drivers_by_bits.get(bits, set())
        ]
        if not matches:
            # Unbekannter/verwaister Treiber: als aktuelle Architektur anzeigen,
            # aber nicht als vermeintlichen 32-Bit-Treiber erfinden.
            matches = [odbc_process_bitness()]
        for bits in matches:
            add_dsn(dsn, driver, bits, "Benutzer")

    return sorted(rows.values(), key=lambda x: (x[0].casefold(), x[2], x[3]))

def odbc_registry_dsn_details(dsn_name: str, bitness: int = 0, scope: str = "") -> Dict[str, str]:
    """Liest die wichtigsten Registry-Werte eines Windows-ODBC-DSN.

    Die Funktion dient nur der Diagnose/Anzeige im SQL Builder. Fuer dBase ist
    insbesondere DBQ/DefaultDir interessant, da dieser Pfad das Verzeichnis
    der DBF-Dateien bezeichnet.
    """
    result: Dict[str, str] = {
        "dsn": str(dsn_name or "").strip(),
        "scope": str(scope or "").strip(),
        "driver": "",
        "dbq": "",
    }
    if os.name != "nt" or not result["dsn"]:
        return result
    try:
        import winreg
    except ImportError:
        return result

    bits = int(bitness or odbc_process_bitness())
    flag = 0
    if bits == 32:
        flag = int(getattr(winreg, "KEY_WOW64_32KEY", 0) or 0)
    elif bits == 64:
        flag = int(getattr(winreg, "KEY_WOW64_64KEY", 0) or 0)

    scope_cf = result["scope"].casefold()
    roots = []
    if scope_cf.startswith("system"):
        roots = [(winreg.HKEY_LOCAL_MACHINE, flag)]
    elif scope_cf.startswith("benutzer") or scope_cf.startswith("user"):
        # Benutzer-DSNs liegen unter HKCU und sind nicht sauber nach Registry-
        # View getrennt. Deshalb ohne WOW64-Flag lesen.
        roots = [(winreg.HKEY_CURRENT_USER, 0)]
    else:
        roots = [
            (winreg.HKEY_CURRENT_USER, 0),
            (winreg.HKEY_LOCAL_MACHINE, flag),
        ]

    subkey = "SOFTWARE\\ODBC\\ODBC.INI\\" + result["dsn"]
    for root, view_flag in roots:
        try:
            key = winreg.OpenKey(root, subkey, 0, winreg.KEY_READ | int(view_flag))
        except OSError:
            continue
        try:
            values: Dict[str, str] = {}
            index = 0
            while True:
                try:
                    name, value, _kind = winreg.EnumValue(key, index)
                except OSError:
                    break
                index += 1
                values[str(name)] = str(value or "")
            for candidate in ("DriverName", "Driver"):
                value = values.get(candidate, "").strip()
                if value:
                    result["driver"] = value
                    break
            # Fuer den Microsoft-dBASE-Treiber sind DBQ/DEFAULTDIR die
            # relevanten Verzeichniswerte. Allgemeine Anzeigenamen wie
            # ``Database=(unbenannt)`` duerfen niemals als Dateipfad gelten.
            invalid_directory_names = {
                "(unbenannt)", "<unbenannt>", "unbenannt",
                "(unbekannt)", "<unbekannt>", "unbekannt",
                "(unnamed)", "<unnamed>", "unnamed",
                "(unknown)", "<unknown>", "unknown",
            }
            for candidate in ("DBQ", "DefaultDir", "Directory", "Path"):
                value = values.get(candidate, "").strip()
                if value and value.casefold() not in invalid_directory_names:
                    result["dbq"] = value
                    break
            result["scope"] = "Benutzer" if root == winreg.HKEY_CURRENT_USER else "System"
            break
        finally:
            winreg.CloseKey(key)
    return result


def odbc_available_data_sources_detailed() -> List[Tuple[str, str, int, str]]:
    """Liefert DSNs mit Treiber, 32/64-Bit-Zuordnung und Scope."""
    sources = _odbc_registry_data_sources_detailed()

    # pyodbc.dataSources() sieht nur die Bitness des aktuellen Prozesses.
    # Es wird als Ergaenzung genutzt, falls ein DSN nicht in der Registry-
    # Abfrage gefunden wurde (z.B. herstellerspezifische Konfiguration).
    module = _d64_pyodbc
    if module is not None:
        try:
            raw = getattr(module, "dataSources", lambda: {})() or {}
            if isinstance(raw, dict):
                current_bits = odbc_process_bitness()
                existing = {(dsn.casefold(), bits) for dsn, _drv, bits, _scope in sources}
                for name, driver in raw.items():
                    dsn = str(name or "").strip()
                    if not dsn:
                        continue
                    ident = (dsn.casefold(), current_bits)
                    if ident not in existing:
                        sources.append((dsn, str(driver or "").strip(), current_bits, "ODBC"))
                        existing.add(ident)
        except Exception:
            pass

    return sorted(sources, key=lambda x: (x[0].casefold(), x[2], x[3]))


def _odbc_registry_data_sources() -> Dict[str, str]:
    """Kompatibilitaets-Wrapper fuer aelteren Code ohne Bitness-Metadaten."""
    result: Dict[str, str] = {}
    for dsn, driver, _bits, _scope in odbc_available_data_sources_detailed():
        result.setdefault(dsn, driver)
    return result


def odbc_available_data_sources() -> List[Tuple[str, str]]:
    """Kompatible DSN-Liste ohne Bitness-Metadaten."""
    result: Dict[str, str] = {}
    for dsn, driver, _bits, _scope in odbc_available_data_sources_detailed():
        result.setdefault(dsn, driver)
    return sorted(result.items(), key=lambda item: item[0].casefold())


def _odbc_bridge_script_path() -> Path:
    """Findet das mitgelieferte PowerShell-ODBC-Bridge-Script."""
    candidates: List[Path] = []
    if getattr(sys, "frozen", False):
        try:
            candidates.append(Path(sys.executable).resolve().parent / "odbc_bitness_bridge.ps1")
        except Exception:
            pass
        bundle = getattr(sys, "_MEIPASS", None)
        if bundle:
            candidates.append(Path(bundle) / "odbc_bitness_bridge.ps1")
    candidates.append(Path(__file__).resolve().parent / "odbc_bitness_bridge.ps1")
    for candidate in candidates:
        if candidate.is_file():
            return candidate
    raise D64ODBCError(
        "ODBC-Bitness-Helper fehlt: odbc_bitness_bridge.ps1 muss neben der Anwendung liegen."
    )


def _odbc_powershell_for_bitness(target_bitness: int) -> Path:
    """Liefert Windows PowerShell in der gewuenschten Prozess-Bitness."""
    if os.name != "nt":
        raise D64ODBCError("Der ODBC-Bitness-Helper ist nur unter Windows verfuegbar.")
    bits = int(target_bitness)
    windir = Path(os.environ.get("WINDIR", r"C:\Windows"))
    current = odbc_process_bitness()

    candidates: List[Path] = []
    if bits == 32:
        # Auf 64-Bit-Windows enthaelt SysWOW64 die 32-Bit-Binaries.
        candidates.append(windir / "SysWOW64" / "WindowsPowerShell" / "v1.0" / "powershell.exe")
        if current == 32:
            candidates.append(windir / "System32" / "WindowsPowerShell" / "v1.0" / "powershell.exe")
    elif bits == 64:
        if current == 32:
            # Sysnative umgeht die Dateisystem-Umleitung eines 32-Bit-Prozesses.
            candidates.append(windir / "Sysnative" / "WindowsPowerShell" / "v1.0" / "powershell.exe")
        candidates.append(windir / "System32" / "WindowsPowerShell" / "v1.0" / "powershell.exe")
    else:
        raise D64ODBCError(f"Unbekannte ODBC-Bitness: {target_bitness}")

    for candidate in candidates:
        if candidate.is_file():
            return candidate
    raise D64ODBCError(
        f"Windows PowerShell ({bits}-Bit) wurde nicht gefunden. Geprueft: "
        + ", ".join(str(p) for p in candidates)
    )


class D64ODBCPowerShellBridgeConnection:
    """
    Bitness-Bridge fuer ODBC.

    Eine 64-Bit-Anwendung kann keine 32-Bit-ODBC-DLL in denselben Prozess
    laden. Deshalb wird fuer eine abweichende DSN-Bitness ein Windows-
    PowerShell-Prozess der Ziel-Bitness gestartet. Dieser benutzt
    System.Data.Odbc und damit die passende native ODBC-Treiberwelt.

    Die Verbindung wird bei ``open()`` getestet. SQL-Aufrufe werden bewusst
    als einzelne Helper-Aufrufe ausgefuehrt; Benutzername/Passwort werden nur
    ueber stdin uebergeben und nicht auf der Kommandozeile sichtbar gemacht.
    """

    def __init__(
        self,
        connection_string: str,
        *,
        target_bitness: int,
        timeout: int = 30,
        autocommit: bool = False,
        data_directory: str = "",
    ) -> None:
        self.connection_string = str(connection_string or "").strip()
        self.target_bitness = int(target_bitness)
        self.timeout = max(1, int(timeout))
        self.autocommit = bool(autocommit)
        self.data_directory = str(data_directory or "").strip()
        self._open = False

    @property
    def is_open(self) -> bool:
        return bool(self._open)

    def _invoke(self, action: str, sql: str = "", parameters: Optional[Sequence[object]] = None) -> Dict[str, object]:
        if not self.connection_string:
            raise D64ODBCError("Die ODBC-Connection-String ist leer.")
        ps_exe = _odbc_powershell_for_bitness(self.target_bitness)
        script = _odbc_bridge_script_path()
        payload = {
            "action": str(action),
            "connection_string": self.connection_string,
            "sql": str(sql or ""),
            "parameters": list(parameters or ()),
            # Der Helper setzt diesen Wert direkt auf
            # System.Data.Odbc.OdbcConnection.ConnectionTimeout.  Wichtig:
            # Der .NET-Standardwert ist 15 s; der aeussere Prozess-Timeout darf
            # deshalb niemals kuerzer als der eigentliche ODBC-Login-Timeout sein.
            "timeout": int(self.timeout),
            # Fuer Desktop-/dBase-Treiber: der SQL-Builder gibt das aktuell
            # gewaehlte DBF-Verzeichnis explizit an. Der 32-Bit-Helper darf
            # damit einen veralteten DBQ-Wert aus der DSN ueberschreiben.
            "data_directory": self.data_directory,
        }
        creationflags = int(getattr(subprocess, "CREATE_NO_WINDOW", 0) or 0)
        try:
            completed = subprocess.run(
                [
                    str(ps_exe),
                    "-NoLogo",
                    "-NoProfile",
                    "-NonInteractive",
                    "-ExecutionPolicy", "Bypass",
                    "-File", str(script),
                ],
                input=json.dumps(payload, ensure_ascii=False),
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                encoding="utf-8",
                errors="replace",
                # PowerShell/CLR-Start braucht zusaetzliche Zeit. Der eigentliche
                # ODBC-Login-Timeout wird *innerhalb* des Helpers gesetzt.
                timeout=max(20, self.timeout + 20),
                creationflags=creationflags,
            )
        except subprocess.TimeoutExpired as exc:
            partial_err = getattr(exc, "stderr", "") or ""
            if isinstance(partial_err, bytes):
                partial_err = partial_err.decode("utf-8", errors="replace")
            partial_err = str(partial_err).strip()
            detail = ""
            if partial_err:
                lines = [line.strip() for line in partial_err.splitlines() if line.strip()]
                # Nur die letzten Diagnosezeilen anzeigen; Zugangsdaten werden vom
                # Helper dort niemals ausgegeben.
                if lines:
                    detail = "\nHelper-Diagnose: " + " | ".join(lines[-4:])
            raise D64ODBCError(
                f"{self.target_bitness}-Bit-ODBC-Helper: Der native ODBC-Aufruf "
                f"hat auch nach {self.timeout} Sekunden nicht geantwortet.{detail}"
            ) from exc
        except Exception as exc:
            raise D64ODBCError(
                f"{self.target_bitness}-Bit-ODBC-Helper konnte nicht gestartet werden: {exc}"
            ) from exc

        output = (completed.stdout or "").strip()
        try:
            result = json.loads(output) if output else {}
        except Exception as exc:
            detail = (completed.stderr or output or "Keine Ausgabe").strip()
            raise D64ODBCError(
                f"{self.target_bitness}-Bit-ODBC-Helper lieferte keine gueltige Antwort: {detail}"
            ) from exc

        if completed.returncode != 0 or not bool(result.get("ok", False)):
            error = str(result.get("error") or completed.stderr or "Unbekannter ODBC-Fehler").strip()
            source_items = result.get("sources") or []
            source_names: List[str] = []
            if isinstance(source_items, list):
                for item in source_items:
                    if isinstance(item, dict):
                        name = str(item.get("name") or "").strip()
                    else:
                        name = str(item or "").strip()
                    if name and name.casefold() not in {x.casefold() for x in source_names}:
                        source_names.append(name)
            diagnostic = ""
            if self.data_directory:
                diagnostic += f"\nVerwendeter DBQ: {self.data_directory}"
            if "IM002" in error.upper():
                if source_names:
                    preview = ", ".join(source_names[:12])
                    if len(source_names) > 12:
                        preview += ", ..."
                    diagnostic = (
                        f"\nVom {self.target_bitness}-Bit-ODBC-Driver-Manager sichtbare DSNs: {preview}"
                    )
                else:
                    diagnostic = (
                        f"\nDer {self.target_bitness}-Bit-ODBC-Driver-Manager meldet keine sichtbare DSN. "
                        "Bitte den DSN im passenden ODBC-Datenquellen-Administrator pruefen."
                    )
            raise D64ODBCError(
                f"{self.target_bitness}-Bit-ODBC-Verbindung fehlgeschlagen: {error}{diagnostic}"
            )
        return result

    def open(self) -> "D64ODBCPowerShellBridgeConnection":
        if self._open:
            return self
        # Zuerst nur Registry/DSN/Treiber pruefen. Das startet noch keinen
        # nativen ODBC-Open-Aufruf und liefert bei alten dBase-Treibern eine
        # deutlich bessere Diagnose (z.B. fehlendes DBQ-Verzeichnis).
        self._invoke("probe")
        self._invoke("test")
        self._open = True
        return self

    def close(self) -> None:
        self._open = False

    def __enter__(self):
        return self.open()

    def __exit__(self, exc_type, exc_value, traceback) -> bool:
        self.close()
        return False

    def execute(
        self,
        sql: str,
        parameters: Optional[Sequence[object]] = None,
        *,
        result_type: str = "list",
        include_columns: bool = False,
        column_separator: str = "\t",
        row_separator: str = "\n",
    ) -> Union[List[List[Any]], str]:
        sql_text = str(sql or "").strip()
        if not sql_text:
            raise D64ODBCError("Der SQL-String ist leer.")
        mode = str(result_type or "list").strip().casefold()
        if mode not in ("list", "string"):
            raise ValueError("result_type muss 'list' oder 'string' sein.")
        if not self._open:
            self.open()

        result = self._invoke("execute", sql_text, parameters)
        columns = [str(x) for x in (result.get("columns") or [])]
        rows = [list(row) for row in (result.get("rows") or [])]
        if not columns:
            rowcount = result.get("rowcount", -1)
            rows = [[rowcount]]

        if mode == "list":
            if include_columns and columns:
                return [columns] + rows
            return rows

        lines: List[str] = []
        if include_columns and columns:
            lines.append(column_separator.join(columns))
        for row in rows:
            lines.append(column_separator.join(_odbc_text_value(value) for value in row))
        return row_separator.join(lines)

def _odbc_text_value(value: object) -> str:
    """Konvertiert einen ODBC-Wert verlustarm in die String-Ausgabe."""
    if value is None:
        return ""
    if isinstance(value, bytes):
        try:
            return value.decode("utf-8")
        except UnicodeDecodeError:
            return value.hex(" ").upper()
    if isinstance(value, (dt.datetime, dt.date, dt.time)):
        return value.isoformat(sep=" ") if isinstance(value, dt.datetime) else value.isoformat()
    return str(value)


class D64ODBCConnection:
    """
    Kleine, wiederverwendbare ODBC-Verbindung fuer den dBase SQL Builder.

    Beispiel::

        with D64ODBCConnection("DSN=MeineDatenbank;UID=user;PWD=pw") as db:
            rows = db.execute("SELECT ID, NAME FROM CUSTOMER", result_type="list")

    result_type="list"   -> List[List[Any]]
    result_type="string" -> tabulatorgetrennter String
    """

    def __init__(
        self,
        connection_string: str,
        *,
        timeout: int = 30,
        autocommit: bool = False,
    ) -> None:
        self.connection_string = str(connection_string or "").strip()
        self.timeout = max(0, int(timeout))
        self.autocommit = bool(autocommit)
        self.connection = None

    @property
    def is_open(self) -> bool:
        return self.connection is not None

    def open(self) -> "D64ODBCConnection":
        if self.connection is not None:
            return self
        if not self.connection_string:
            raise D64ODBCError("Die ODBC-Connection-String ist leer.")
        module = _require_d64_pyodbc()
        try:
            self.connection = module.connect(
                self.connection_string,
                timeout=self.timeout,
                autocommit=self.autocommit,
            )
        except Exception as exc:
            raise D64ODBCError(f"ODBC-Verbindung konnte nicht geoeffnet werden: {exc}") from exc
        return self

    def close(self) -> None:
        connection = self.connection
        self.connection = None
        if connection is not None:
            try:
                connection.close()
            except Exception:
                pass

    def __enter__(self) -> "D64ODBCConnection":
        return self.open()

    def __exit__(self, exc_type, exc_value, traceback) -> bool:
        self.close()
        return False

    def execute(
        self,
        sql: str,
        parameters: Optional[Sequence[object]] = None,
        *,
        result_type: str = "list",
        include_columns: bool = False,
        column_separator: str = "\t",
        row_separator: str = "\n",
    ) -> Union[List[List[Any]], str]:
        """Fuehrt SQL aus und liefert das Resultat als Liste oder String."""
        sql_text = str(sql or "").strip()
        if not sql_text:
            raise D64ODBCError("Der SQL-String ist leer.")

        mode = str(result_type or "list").strip().casefold()
        if mode not in ("list", "string"):
            raise ValueError("result_type muss 'list' oder 'string' sein.")

        if self.connection is None:
            self.open()
        connection = self.connection
        if connection is None:
            raise D64ODBCError("ODBC-Verbindung ist nicht geoeffnet.")

        cursor = None
        try:
            cursor = connection.cursor()
            params = tuple(parameters or ())
            if params:
                cursor.execute(sql_text, *params)
            else:
                cursor.execute(sql_text)

            # SELECT/EXEC mit Resultset
            if cursor.description is not None:
                columns = [str(column[0]) for column in cursor.description]
                rows = [list(row) for row in cursor.fetchall()]

                if mode == "list":
                    if include_columns:
                        return [list(columns)] + rows
                    return rows

                text_rows: List[str] = []
                if include_columns:
                    text_rows.append(column_separator.join(columns))
                text_rows.extend(
                    column_separator.join(_odbc_text_value(value) for value in row)
                    for row in rows
                )
                return row_separator.join(text_rows)

            # INSERT/UPDATE/DELETE/DDL: bei autocommit=False explizit committen.
            if not self.autocommit:
                connection.commit()
            affected = int(cursor.rowcount) if cursor.rowcount is not None else -1
            if mode == "string":
                return str(affected)
            return [[affected]]

        except Exception as exc:
            if connection is not None and not self.autocommit:
                try:
                    connection.rollback()
                except Exception:
                    pass
            raise D64ODBCError(f"ODBC-SQL-Fehler: {exc}\nSQL: {sql_text}") from exc
        finally:
            if cursor is not None:
                try:
                    cursor.close()
                except Exception:
                    pass


def execute_odbc_sql(
    connection_string: str,
    sql: str,
    parameters: Optional[Sequence[object]] = None,
    *,
    result_type: str = "list",
    include_columns: bool = False,
    timeout: int = 30,
    autocommit: bool = False,
    column_separator: str = "\t",
    row_separator: str = "\n",
) -> Union[List[List[Any]], str]:
    """
    One-Shot-Helfer: ODBC verbinden -> SQL ausfuehren -> Verbindung schliessen.

    Beispiel Liste::

        rows = execute_odbc_sql(
            "DSN=MeineDB;UID=user;PWD=secret",
            "SELECT ID, NAME FROM CUSTOMER WHERE ID > ?",
            [10],
            result_type="list",
            include_columns=True,
        )

    Beispiel String::

        text = execute_odbc_sql(
            "DSN=MeineDB",
            "SELECT ID, NAME FROM CUSTOMER",
            result_type="string",
            include_columns=True,
        )
    """
    with D64ODBCConnection(
        connection_string,
        timeout=timeout,
        autocommit=autocommit,
    ) as database:
        return database.execute(
            sql,
            parameters,
            result_type=result_type,
            include_columns=include_columns,
            column_separator=column_separator,
            row_separator=row_separator,
        )


# ---------------------------------------------------------------------------
# Stage ASM 9: robuste Ressourcenauflösung für Skript- und PyInstaller-Betrieb.
#
# Im Frozen-Betrieb zeigt __file__ auf den Bundle-Bereich (bei onedir typischer-
# weise `_internal`). Benutzerdateien wie help/c64.chm dürfen aber auch direkt
# neben d64_dism.exe liegen. Daher wird zuerst neben der EXE, danach im
# PyInstaller-Bundle und zuletzt relativ zum Quellmodul gesucht.
# ---------------------------------------------------------------------------
def d64_runtime_resource_candidates(relative_path: str) -> List[Path]:
    relative = Path(str(relative_path).replace("\\", "/"))
    result: List[Path] = []

    if getattr(sys, "frozen", False):
        try:
            result.append(Path(sys.executable).resolve().parent / relative)
        except Exception:
            pass
        bundle_root = getattr(sys, "_MEIPASS", "")
        if bundle_root:
            try:
                result.append(Path(bundle_root).resolve() / relative)
            except Exception:
                pass

    try:
        result.append(Path(__file__).resolve().parent / relative)
    except Exception:
        pass

    unique: List[Path] = []
    seen = set()
    for candidate in result:
        key = os.path.normcase(os.path.abspath(str(candidate)))
        if key in seen:
            continue
        seen.add(key)
        unique.append(candidate)
    return unique


def d64_resolve_runtime_resource(relative_path: str) -> Path:
    candidates = d64_runtime_resource_candidates(relative_path)
    for candidate in candidates:
        try:
            if candidate.is_file() or candidate.is_dir():
                return candidate
        except OSError:
            continue
    if candidates:
        return candidates[0]
    return Path(relative_path).resolve()


_QTWEBENGINE_PREFLIGHT_CACHE: Optional[Tuple[bool, str]] = None


def d64_qtwebengine_frozen_preflight() -> Tuple[bool, str]:
    """Prüft im PyInstaller-Bundle die für QtWebEngine nötigen Dateien.

    Die Prüfung läuft bewusst vor der Konstruktion von QWebEngineView. Fehlt
    eine native Chromium-Komponente, kann Qt sonst den Prozess beenden, bevor
    Python eine Exception oder einen Traceback erzeugen kann.
    """
    global _QTWEBENGINE_PREFLIGHT_CACHE
    if _QTWEBENGINE_PREFLIGHT_CACHE is not None:
        return _QTWEBENGINE_PREFLIGHT_CACHE
    if not getattr(sys, "frozen", False):
        _QTWEBENGINE_PREFLIGHT_CACHE = (True, "")
        return _QTWEBENGINE_PREFLIGHT_CACHE

    roots: List[Path] = []
    bundle_root = getattr(sys, "_MEIPASS", "")
    if bundle_root:
        roots.append(Path(bundle_root))
    try:
        roots.append(Path(sys.executable).resolve().parent)
    except Exception:
        pass

    def existing_env_file(name: str) -> Optional[Path]:
        value = os.environ.get(name, "").strip()
        if not value:
            return None
        path = Path(value)
        return path if path.is_file() else None

    def existing_env_dir(name: str) -> Optional[Path]:
        value = os.environ.get(name, "").strip()
        if not value:
            return None
        path = Path(value)
        return path if path.is_dir() else None

    process = existing_env_file("QTWEBENGINEPROCESS_PATH")
    resources = existing_env_dir("QTWEBENGINE_RESOURCES_PATH")
    locales = existing_env_dir("QTWEBENGINE_LOCALES_PATH")

    def find_file(filename: str) -> Optional[Path]:
        for root in roots:
            if not root.exists():
                continue
            try:
                for found in root.rglob(filename):
                    if found.is_file():
                        return found
            except OSError:
                continue
        return None

    def find_dir(dirname: str) -> Optional[Path]:
        for root in roots:
            if not root.exists():
                continue
            try:
                for found in root.rglob(dirname):
                    if found.is_dir():
                        return found
            except OSError:
                continue
        return None

    if process is None:
        process = find_file("QtWebEngineProcess.exe")
    if resources is None:
        pak = find_file("qtwebengine_resources.pak")
        if pak is not None:
            resources = pak.parent
    if locales is None:
        locales = find_dir("qtwebengine_locales")

    missing: List[str] = []
    if process is None:
        missing.append("QtWebEngineProcess.exe")
    if resources is None:
        missing.append("qtwebengine_resources.pak / resources-Verzeichnis")
    else:
        for required_name in ("qtwebengine_resources.pak", "icudtl.dat"):
            if not (resources / required_name).is_file():
                missing.append(required_name)
    if locales is None or not any(locales.glob("*.pak")):
        missing.append("qtwebengine_locales/*.pak")

    if missing:
        detail = (
            "Im PyInstaller-Bundle fehlen QtWebEngine-Laufzeitdateien:\n\n- "
            + "\n- ".join(missing)
            + "\n\nBaue die Anwendung mit der mitgelieferten d64_dism.spec "
              "neu und deaktiviere UPX für Qt/WebEngine."
        )
        _QTWEBENGINE_PREFLIGHT_CACHE = (False, detail)
    else:
        _QTWEBENGINE_PREFLIGHT_CACHE = (True, "")
    return _QTWEBENGINE_PREFLIGHT_CACHE

# ---------------------------------------------------------------------------
# Stage 175: Pascal frontend / generated ANTLR parser synchronization.
#
# d64_dism imports the high-level compiler through ``c64pascal``.  In a source
# checkout that module can be found before ``src/asmjit`` on sys.path.  An old
# generated PascalParser.py then causes valid declarations such as
#
#     destructor Destroy; virtual;
#
# to be read as a field named ``virtual`` and produces the misleading
# "mismatched input ';' expecting ':'" diagnostic.
#
# The source grammar in src/asmjit/compiler/grammar is authoritative.  Before a
# Pascal build we prefer that checkout's parsers/pascal directory, validate the
# generated parser, and regenerate it only when grammar and generated output are
# demonstrably out of sync.  No external C/C++ compiler/linker is involved.
# ---------------------------------------------------------------------------
PASCAL_ANTLR_VERSION = "4.13.2"
PASCAL_FRONTEND_SYNC_LAST: Dict[str, object] = {
    "ready": False,
    "reason": "Pascal-Frontend wurde noch nicht geprüft.",
}


def _pascal_path_is_within(path: Path, directory: Path) -> bool:
    try:
        Path(path).resolve().relative_to(Path(directory).resolve())
        return True
    except (OSError, ValueError):
        return False


def _pascal_asmjit_root_candidates(
    source_path: Optional[Path] = None,
) -> Tuple[Path, ...]:
    seeds: List[Path] = []
    if source_path is not None:
        try:
            seeds.append(Path(source_path).expanduser().resolve())
        except OSError:
            seeds.append(Path(source_path).expanduser())
    try:
        seeds.append(Path(__file__).resolve())
    except OSError:
        seeds.append(Path(__file__))
    try:
        seeds.append(Path.cwd().resolve())
    except OSError:
        seeds.append(Path.cwd())

    result: List[Path] = []
    seen = set()
    for seed in seeds:
        current = seed if seed.is_dir() else seed.parent
        for candidate in (current, *current.parents):
            grammar = candidate / "compiler" / "grammar" / "PascalParser.g4"
            parser_dir = candidate / "parsers" / "pascal"
            if not grammar.is_file() or not parser_dir.is_dir():
                continue
            key = str(candidate).casefold()
            if key not in seen:
                seen.add(key)
                result.append(candidate)
            break
    return tuple(result)


def _pascal_grammar_supports_method_directives(grammar_path: Path) -> bool:
    try:
        text = Path(grammar_path).read_text(encoding="utf-8-sig")
    except (OSError, UnicodeError):
        return False
    compact = re.sub(r"\s+", " ", text).casefold()
    return all((
        "methoddirective" in compact,
        "virtual" in compact,
        "override" in compact,
        "constructordeclaration" in compact,
        "destructordeclaration" in compact,
        "methoddirectivelist?" in compact,
    ))


def _pascal_grammar_supports_address_operator(grammar_path: Path) -> bool:
    try:
        text = Path(grammar_path).read_text(encoding="utf-8-sig")
    except (OSError, UnicodeError):
        return False
    return re.search(r"(?m)^\s*AT\s*:\s*['\"]@['\"]\s*;", text) is not None


def _pascal_generated_lexer_supports_address_operator(lexer_path: Path) -> bool:
    try:
        text = Path(lexer_path).read_text(encoding="utf-8-sig")
    except (OSError, UnicodeError):
        return False
    return bool(
        re.search(r"(?m)^\s*AT\s*=\s*\d+", text)
        and ("'@'" in text or '"@"' in text)
    )


def _pascal_generated_parser_supports_method_directives(
    parser_path: Path,
) -> bool:
    try:
        text = Path(parser_path).read_text(encoding="utf-8-sig")
    except (OSError, UnicodeError):
        return False
    return all((
        "RULE_methodDirectiveList" in text,
        "VIRTUAL=" in text,
        "OVERRIDE=" in text,
        "def constructorDeclaration(" in text,
        "def destructorDeclaration(" in text,
        "self.methodDirectiveList()" in text,
    ))


def _pascal_find_antlr4_command() -> Optional[str]:
    candidates = (
        "antlr4.exe",
        "antlr4",
        "antlr4.bat",
        "antlr4.cmd",
    )
    for name in candidates:
        resolved = shutil.which(name)
        if resolved:
            return resolved
    return None


def _pascal_regenerate_repo_parser(asmjit_root: Path) -> Tuple[bool, str]:
    root = Path(asmjit_root).resolve()
    antlr4_command = _pascal_find_antlr4_command()
    if antlr4_command is None:
        return False, (
            "ANTLR4 4.13.2 wurde nicht im PATH gefunden. "
            "Der Parser kann nicht automatisch nachgeneriert werden."
        )

    parser_dir = root / "parsers" / "pascal"
    parser_dir.mkdir(parents=True, exist_ok=True)
    commands = (
        [
            antlr4_command,
            "-v", PASCAL_ANTLR_VERSION,
            "-Dlanguage=Python3",
            "-Xexact-output-dir",
            "-o", str(Path("parsers") / "pascal"),
            str(Path("compiler") / "grammar" / "PascalLexer.g4"),
        ],
        [
            antlr4_command,
            "-v", PASCAL_ANTLR_VERSION,
            "-Dlanguage=Python3",
            "-Xexact-output-dir",
            "-o", str(Path("parsers") / "pascal"),
            "-visitor",
            "-lib", str(Path("parsers") / "pascal"),
            str(Path("compiler") / "grammar" / "PascalParser.g4"),
        ],
    )

    transcript: List[str] = []
    for command in commands:
        try:
            completed = subprocess.run(
                command,
                cwd=str(root),
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                encoding="utf-8",
                errors="replace",
                check=False,
            )
        except OSError as exc:
            return False, f"ANTLR4 konnte nicht gestartet werden: {exc}"
        transcript.append(completed.stdout or "")
        if completed.returncode != 0:
            return False, (
                "ANTLR4 Parser-Erzeugung fehlgeschlagen (Exit "
                f"{completed.returncode}).\n" + "\n".join(transcript).strip()
            )

    # Alte Bytecode-Caches dürfen nicht den frisch erzeugten Parser verdecken.
    cache_dir = parser_dir / "__pycache__"
    if cache_dir.is_dir():
        for pattern in (
            "PascalLexer*.pyc",
            "PascalParser*.pyc",
            "PascalParserVisitor*.pyc",
            "PascalParserListener*.pyc",
        ):
            for cached in cache_dir.glob(pattern):
                try:
                    cached.unlink()
                except OSError:
                    pass
    importlib.invalidate_caches()
    parser_path = parser_dir / "PascalParser.py"
    lexer_path = parser_dir / "PascalLexer.py"
    if not _pascal_generated_parser_supports_method_directives(parser_path):
        return False, (
            "ANTLR4 wurde ausgeführt, der erzeugte PascalParser.py enthält "
            "aber weiterhin keine virtual/override-Methodendirektiven."
        )
    if not _pascal_generated_lexer_supports_address_operator(lexer_path):
        return False, (
            "ANTLR4 wurde ausgeführt, der erzeugte PascalLexer.py erkennt "
            "den Object-Pascal-Adressoperator '@' aber weiterhin nicht."
        )
    return True, "ANTLR4-Pascallexer/-parser 4.13.2 wurden erfolgreich nachgeneriert."


def _pascal_prefer_repo_parser_path(asmjit_root: Path) -> None:
    root = Path(asmjit_root).resolve()
    root_text = str(root)
    sys.path[:] = [
        item for item in sys.path
        if str(item).casefold() != root_text.casefold()
    ]
    sys.path.insert(0, root_text)

    # Ein bereits importiertes Top-Level-Paket ``parsers`` kann einen __path__
    # aus einer älteren Installation besitzen. Den Repo-Pfad vorne ergänzen.
    parsers_package = sys.modules.get("parsers")
    desired_parsers = str(root / "parsers")
    package_path = getattr(parsers_package, "__path__", None)
    if package_path is not None:
        existing = [str(item) for item in package_path]
        if desired_parsers.casefold() not in {
            item.casefold() for item in existing
        }:
            try:
                package_path.insert(0, desired_parsers)
            except (AttributeError, TypeError):
                pass


def _pascal_forget_stale_generated_modules(asmjit_root: Path) -> None:
    root = Path(asmjit_root).resolve()
    expected_dir = root / "parsers" / "pascal"
    # Auch ein Modul aus dem richtigen Pfad kann noch den Bytecode der
    # gerade nachgenerierten alten Version im Speicher halten. Die vier
    # generierten Teilmodule werden deshalb vor der Prüfung immer neu geladen.
    for generated_name in (
        "parsers.pascal.PascalLexer",
        "parsers.pascal.PascalParser",
        "parsers.pascal.PascalParserVisitor",
        "parsers.pascal.PascalParserListener",
    ):
        sys.modules.pop(generated_name, None)
    module_names = (
        "parsers.pascal.PascalLexer",
        "parsers.pascal.PascalParser",
        "parsers.pascal.PascalParserVisitor",
        "parsers.pascal.PascalParserListener",
        "parsers.pascal",
    )
    for name in module_names:
        module = sys.modules.get(name)
        if module is None:
            continue
        module_file = getattr(module, "__file__", None)
        if module_file is None or not _pascal_path_is_within(
            Path(module_file), expected_dir
        ):
            sys.modules.pop(name, None)
    importlib.invalidate_caches()


def _pascal_patch_frontend_parser_bindings(
    frontend_module,
    lexer_class,
    parser_class,
    visitor_class=None,
) -> None:
    targets = [frontend_module]
    compile_function = getattr(
        frontend_module, "compile_pascal_to_assembly", None
    )
    globals_dict = getattr(compile_function, "__globals__", None)
    if isinstance(globals_dict, dict):
        globals_dict["PascalLexer"] = lexer_class
        globals_dict["PascalParser"] = parser_class
        if visitor_class is not None:
            globals_dict["PascalParserVisitor"] = visitor_class

    frontend_name = str(getattr(frontend_module, "__name__", "c64pascal"))
    for name, module in tuple(sys.modules.items()):
        if module is None:
            continue
        if name == frontend_name or name.startswith(frontend_name + "."):
            targets.append(module)

    seen = set()
    for module in targets:
        key = id(module)
        if key in seen:
            continue
        seen.add(key)
        if hasattr(module, "PascalLexer"):
            setattr(module, "PascalLexer", lexer_class)
        if hasattr(module, "PascalParser"):
            setattr(module, "PascalParser", parser_class)
        if visitor_class is not None and hasattr(module, "PascalParserVisitor"):
            setattr(module, "PascalParserVisitor", visitor_class)

    # Einige ältere c64pascal-Stände importieren den Generator als separates
    # Top-Level-Modul. Solche Module tragen nicht zwingend den Namen
    # ``c64pascal.*``. Nur echte PascalParser-Klassen werden hier ersetzt.
    for module in tuple(sys.modules.values()):
        if module is None:
            continue
        old_parser = getattr(module, "PascalParser", None)
        if (
            isinstance(old_parser, type)
            and getattr(old_parser, "__name__", "") == "PascalParser"
            and hasattr(old_parser, "ruleNames")
        ):
            try:
                setattr(module, "PascalParser", parser_class)
            except (AttributeError, TypeError):
                pass
        old_lexer = getattr(module, "PascalLexer", None)
        if (
            isinstance(old_lexer, type)
            and getattr(old_lexer, "__name__", "") == "PascalLexer"
        ):
            try:
                setattr(module, "PascalLexer", lexer_class)
            except (AttributeError, TypeError):
                pass


def prepare_pascal_frontend_for_compile(
    source_path: Optional[Path] = None,
) -> Dict[str, object]:
    """Prefer and validate the repo-local Pascal ANTLR frontend.

    This routine deliberately returns a diagnostic dictionary instead of
    raising. Existing compiler error handling therefore remains untouched.
    """
    info: Dict[str, object] = {
        "ready": False,
        "reason": "Kein src/asmjit-Pascalparser gefunden.",
        "asmjit_root": "",
        "grammar": "",
        "lexer_grammar": "",
        "lexer": "",
        "parser": "",
        "compiler": "",
        "regenerated": False,
    }
    roots = _pascal_asmjit_root_candidates(source_path)
    if not roots:
        PASCAL_FRONTEND_SYNC_LAST.clear()
        PASCAL_FRONTEND_SYNC_LAST.update(info)
        return dict(info)

    root = roots[0]
    grammar_path = root / "compiler" / "grammar" / "PascalParser.g4"
    lexer_grammar_path = root / "compiler" / "grammar" / "PascalLexer.g4"
    parser_path = root / "parsers" / "pascal" / "PascalParser.py"
    lexer_path = root / "parsers" / "pascal" / "PascalLexer.py"
    info["asmjit_root"] = str(root)
    info["grammar"] = str(grammar_path)
    info["lexer_grammar"] = str(lexer_grammar_path)
    info["lexer"] = str(lexer_path)
    info["parser"] = str(parser_path)

    if not _pascal_grammar_supports_method_directives(grammar_path):
        info["reason"] = (
            "Die Repo-Grammatik PascalParser.g4 ist zu alt: "
            "methodDirectiveList mit virtual/override fehlt."
        )
        PASCAL_FRONTEND_SYNC_LAST.clear()
        PASCAL_FRONTEND_SYNC_LAST.update(info)
        return dict(info)

    if not _pascal_grammar_supports_address_operator(lexer_grammar_path):
        info["reason"] = (
            "Die Repo-Grammatik PascalLexer.g4 ist zu alt: "
            "AT : '@'; fehlt."
        )
        PASCAL_FRONTEND_SYNC_LAST.clear()
        PASCAL_FRONTEND_SYNC_LAST.update(info)
        return dict(info)

    parser_current = _pascal_generated_parser_supports_method_directives(
        parser_path
    )
    lexer_current = _pascal_generated_lexer_supports_address_operator(
        lexer_path
    )
    if not (parser_current and lexer_current):
        regenerated, message = _pascal_regenerate_repo_parser(root)
        info["regenerated"] = bool(regenerated)
        if not regenerated:
            info["reason"] = message
            PASCAL_FRONTEND_SYNC_LAST.clear()
            PASCAL_FRONTEND_SYNC_LAST.update(info)
            return dict(info)

    _pascal_prefer_repo_parser_path(root)
    _pascal_forget_stale_generated_modules(root)

    try:
        lexer_module = importlib.import_module(
            "parsers.pascal.PascalLexer"
        )
        parser_module = importlib.import_module(
            "parsers.pascal.PascalParser"
        )
        try:
            visitor_module = importlib.import_module(
                "parsers.pascal.PascalParserVisitor"
            )
            visitor_class = getattr(
                visitor_module, "PascalParserVisitor", None
            )
        except ImportError:
            visitor_class = None
    except ImportError as exc:
        info["reason"] = f"Repo-Pascalparser konnte nicht importiert werden: {exc}"
        PASCAL_FRONTEND_SYNC_LAST.clear()
        PASCAL_FRONTEND_SYNC_LAST.update(info)
        return dict(info)

    loaded_parser_path = Path(
        getattr(parser_module, "__file__", parser_path)
    )
    loaded_lexer_path = Path(
        getattr(lexer_module, "__file__", lexer_path)
    )
    info["parser"] = str(loaded_parser_path)
    info["lexer"] = str(loaded_lexer_path)
    parser_class = getattr(parser_module, "PascalParser", None)
    lexer_class = getattr(lexer_module, "PascalLexer", None)
    if parser_class is None or lexer_class is None:
        info["reason"] = "Repo-PascalLexer/PascalParser-Klasse fehlt."
        PASCAL_FRONTEND_SYNC_LAST.clear()
        PASCAL_FRONTEND_SYNC_LAST.update(info)
        return dict(info)

    rule_names = tuple(getattr(parser_class, "ruleNames", ()) or ())
    if "methodDirectiveList" not in rule_names:
        info["reason"] = (
            "Geladener PascalParser besitzt keine Regel methodDirectiveList."
        )
        PASCAL_FRONTEND_SYNC_LAST.clear()
        PASCAL_FRONTEND_SYNC_LAST.update(info)
        return dict(info)
    if not hasattr(parser_class, "VIRTUAL") or not hasattr(
        parser_class, "OVERRIDE"
    ):
        info["reason"] = (
            "Geladener PascalParser besitzt keine VIRTUAL/OVERRIDE-Tokens."
        )
        PASCAL_FRONTEND_SYNC_LAST.clear()
        PASCAL_FRONTEND_SYNC_LAST.update(info)
        return dict(info)
    if not hasattr(lexer_class, "AT"):
        info["reason"] = (
            "Geladener PascalLexer besitzt kein AT-Token für '@'."
        )
        PASCAL_FRONTEND_SYNC_LAST.clear()
        PASCAL_FRONTEND_SYNC_LAST.update(info)
        return dict(info)

    try:
        frontend_module = importlib.import_module("c64pascal")
    except ImportError as exc:
        info["reason"] = f"c64pascal konnte nicht importiert werden: {exc}"
        PASCAL_FRONTEND_SYNC_LAST.clear()
        PASCAL_FRONTEND_SYNC_LAST.update(info)
        return dict(info)

    _pascal_patch_frontend_parser_bindings(
        frontend_module,
        lexer_class,
        parser_class,
        visitor_class,
    )
    info["compiler"] = str(
        getattr(frontend_module, "__file__", "<c64pascal>")
    )
    info["ready"] = True
    info["reason"] = (
        "Repo-lokaler PascalLexer/PascalParser ist synchron und unterstützt "
        "@ sowie virtual/override."
    )
    PASCAL_FRONTEND_SYNC_LAST.clear()
    PASCAL_FRONTEND_SYNC_LAST.update(info)
    return dict(info)


# ---------------------------------------------------------------------------
# Stage 176: Pascal lexical preprocessor.
#
# Supported comment forms:
#   (* block comment *)
#   // line comment
#   { block comment }
#
# Compiler directives are recognized BEFORE brace-comment stripping, therefore
#   {$define FOO}
# is never mistaken for a normal { ... } comment.
# ---------------------------------------------------------------------------
class PascalPreprocessorError(Exception):
    def __init__(self, message: str, line: int = 0):
        super().__init__(message)
        self.line = int(line or 0)


@dataclass(frozen=True)
class PascalPreprocessResult:
    source: str
    macros: Dict[str, str]
    defined_symbols: Tuple[str, ...]
    directives: Tuple[str, ...]
    warnings: Tuple[str, ...]
    removed_comment_count: int
    original_line_count: int
    output_line_count: int
    link_files: Tuple[str, ...] = ()


def _pascal_pp_key(name: str) -> str:
    return str(name or "").strip().upper()


def _pascal_pp_truthy(value: object) -> bool:
    text = str(value if value is not None else "").strip()
    if not text:
        return True
    folded = text.casefold()
    if folded in {"0", "false", "off", "no", "nil"}:
        return False
    return True


def _pascal_pp_value(value: object):
    text = str(value if value is not None else "").strip()
    if not text:
        return 1
    if len(text) >= 2 and text[0] == "'" and text[-1] == "'":
        return text[1:-1].replace("''", "'")
    if text.startswith("$"):
        try:
            return int(text[1:], 16)
        except ValueError:
            return text
    try:
        return int(text, 0)
    except ValueError:
        return text


def _pascal_pp_tokenize_condition(expression: str) -> List[str]:
    pattern = re.compile(
        r"\s*("
        r"<>|<=|>=|=|<|>|\(|\)|"
        r"\bAND\b|\bOR\b|\bXOR\b|\bNOT\b|\bDEFINED\b|"
        r"\$[0-9A-Fa-f]+|"
        r"\d+|"
        r"'(?:''|[^'])*'|"
        r"[A-Za-z_][A-Za-z0-9_]*"
        r")",
        re.IGNORECASE,
    )
    tokens = []
    pos = 0
    source = str(expression or "")
    while pos < len(source):
        match = pattern.match(source, pos)
        if match is None:
            if source[pos:].strip():
                raise ValueError(
                    "Unbekanntes Token in Pascal-{$if}: "
                    + repr(source[pos:].strip())
                )
            break
        tokens.append(match.group(1))
        pos = match.end()
    return tokens


def _pascal_pp_eval_condition(
    expression: str,
    macros: Dict[str, str],
    defined: set,
) -> bool:
    tokens = _pascal_pp_tokenize_condition(expression)
    index = 0

    def peek() -> Optional[str]:
        return tokens[index] if index < len(tokens) else None

    def take() -> str:
        nonlocal index
        if index >= len(tokens):
            raise ValueError("Unerwartetes Ende der Pascal-Bedingung.")
        value = tokens[index]
        index += 1
        return value

    def atom():
        token = take()
        folded = token.casefold()
        if token == "(":
            value = parse_or()
            if take() != ")":
                raise ValueError("Fehlende ')' in Pascal-Bedingung.")
            return value
        if folded == "defined":
            if peek() == "(":
                take()
                name = take()
                if take() != ")":
                    raise ValueError("defined(...) erwartet ')'.")
            else:
                name = take()
            return _pascal_pp_key(name) in defined
        if token.startswith("'"):
            return _pascal_pp_value(token)
        if token.startswith("$") or token[:1].isdigit():
            return _pascal_pp_value(token)
        key = _pascal_pp_key(token)
        if key in macros:
            return _pascal_pp_value(macros[key])
        if key in defined:
            return 1
        return 0

    def parse_compare():
        left = atom()
        nxt = peek()
        if nxt not in {"=", "<>", "<", ">", "<=", ">="}:
            return bool(left) if isinstance(left, bool) else _pascal_pp_truthy(left)
        op = take()
        right = atom()
        if op == "=":
            return left == right
        if op == "<>":
            return left != right
        try:
            if op == "<":
                return left < right
            if op == ">":
                return left > right
            if op == "<=":
                return left <= right
            if op == ">=":
                return left >= right
        except TypeError:
            ltxt, rtxt = str(left), str(right)
            if op == "<":
                return ltxt < rtxt
            if op == ">":
                return ltxt > rtxt
            if op == "<=":
                return ltxt <= rtxt
            return ltxt >= rtxt
        return False

    def parse_not():
        if (peek() or "").casefold() == "not":
            take()
            return not bool(parse_not())
        return parse_compare()

    def parse_and():
        value = bool(parse_not())
        while (peek() or "").casefold() == "and":
            take()
            rhs = bool(parse_not())
            value = value and rhs
        return value

    def parse_xor():
        value = bool(parse_and())
        while (peek() or "").casefold() == "xor":
            take()
            value = bool(value) ^ bool(parse_and())
        return value

    def parse_or():
        value = bool(parse_xor())
        while (peek() or "").casefold() == "or":
            take()
            rhs = bool(parse_xor())
            value = value or rhs
        return value

    if not tokens:
        return False
    result = bool(parse_or())
    if index != len(tokens):
        raise ValueError(
            "Unerwartete Tokens am Ende der Pascal-Bedingung: "
            + " ".join(tokens[index:])
        )
    return result


def _pascal_pp_expand_identifier(
    identifier: str,
    macros: Dict[str, str],
    explicit_value_macros: set,
    *,
    filename: str,
    line_number: int,
) -> str:
    key = _pascal_pp_key(identifier)
    if key == "__LINE__":
        return str(int(line_number))
    if key == "__FILE__":
        return "'" + str(filename).replace("'", "''") + "'"
    if key == "__DATE__":
        return "'" + dt.datetime.now().strftime("%Y-%m-%d") + "'"
    if key == "__TIME__":
        return "'" + dt.datetime.now().strftime("%H:%M:%S") + "'"
    if key in explicit_value_macros and key in macros:
        return str(macros[key])
    return identifier


def preprocess_pascal_source(
    source: str,
    *,
    filename: str = "<memory>",
    predefined_macros: Optional[Dict[str, object]] = None,
    link_search_paths: Iterable[Path | str] = (),
) -> PascalPreprocessResult:
    """Preprocess Pascal while preserving physical line numbers.

    Directives are blanked to spaces; comments and inactive conditional blocks
    are likewise blanked while every original newline remains present. This
    keeps ANTLR error line numbers aligned with the editor/source file.
    """
    text = str(source or "")
    macros: Dict[str, str] = {}
    defined = set()
    explicit_value_macros = set()
    for name, value in dict(predefined_macros or {}).items():
        key = _pascal_pp_key(name)
        if not key:
            continue
        defined.add(key)
        if value is not None:
            macros[key] = str(value)
            explicit_value_macros.add(key)

    directives: List[str] = []
    warnings: List[str] = []
    link_files: List[str] = []
    normalized_link_search_paths: List[Path] = []
    for _item in link_search_paths or ():
        try:
            _path = Path(_item).expanduser().resolve()
        except (OSError, RuntimeError, ValueError):
            _path = Path(_item).expanduser().absolute()
        if _path not in normalized_link_search_paths:
            normalized_link_search_paths.append(_path)
    conditional_stack: List[Dict[str, object]] = []
    output: List[str] = []
    removed_comments = 0
    index = 0
    line = 1

    def active() -> bool:
        return all(bool(frame.get("active", False)) for frame in conditional_stack)

    def blank_fragment(fragment: str) -> str:
        return "".join("\n" if ch == "\n" else "\r" if ch == "\r" else " " for ch in fragment)

    def process_directive(content: str, line_number: int) -> None:
        body = str(content).strip()
        if body.startswith("$"):
            body = body[1:].strip()
        if not body:
            return
        parts = body.split(None, 1)
        command = parts[0].casefold()
        argument = parts[1].strip() if len(parts) > 1 else ""
        directives.append(f"{line_number}:{body}")

        current_parent = active()
        if command in {"ifdef", "ifndef"}:
            key = _pascal_pp_key(argument.split(None, 1)[0] if argument else "")
            condition = key in defined
            if command == "ifndef":
                condition = not condition
            parent_active = current_parent
            this_active = bool(parent_active and condition)
            conditional_stack.append({
                "parent_active": parent_active,
                "branch_taken": bool(condition) if parent_active else False,
                "active": this_active,
                "else_seen": False,
                "line": line_number,
            })
            return

        if command == "if":
            try:
                condition = _pascal_pp_eval_condition(argument, macros, defined)
            except ValueError as exc:
                raise PascalPreprocessorError(
                    f"Ungültige {{$if}}-Bedingung: {exc}", line_number
                ) from exc
            parent_active = current_parent
            conditional_stack.append({
                "parent_active": parent_active,
                "branch_taken": bool(condition) if parent_active else False,
                "active": bool(parent_active and condition),
                "else_seen": False,
                "line": line_number,
            })
            return

        if command in {"elseif", "elif"}:
            if not conditional_stack:
                raise PascalPreprocessorError(
                    "{$elseif}/{$elif} ohne vorheriges {$if}.", line_number
                )
            frame = conditional_stack[-1]
            if frame.get("else_seen"):
                raise PascalPreprocessorError(
                    "{$elseif} nach {$else} ist nicht erlaubt.", line_number
                )
            parent_active = bool(frame.get("parent_active"))
            already = bool(frame.get("branch_taken"))
            try:
                condition = _pascal_pp_eval_condition(argument, macros, defined)
            except ValueError as exc:
                raise PascalPreprocessorError(
                    f"Ungültige {{$elseif}}-Bedingung: {exc}", line_number
                ) from exc
            frame["active"] = bool(parent_active and not already and condition)
            if parent_active and condition:
                frame["branch_taken"] = True
            return

        if command == "else":
            if not conditional_stack:
                raise PascalPreprocessorError(
                    "{$else} ohne vorheriges {$if}.", line_number
                )
            frame = conditional_stack[-1]
            if frame.get("else_seen"):
                raise PascalPreprocessorError(
                    "Doppeltes {$else}.", line_number
                )
            frame["else_seen"] = True
            parent_active = bool(frame.get("parent_active"))
            frame["active"] = bool(parent_active and not frame.get("branch_taken"))
            if parent_active:
                frame["branch_taken"] = True
            return

        if command in {"endif", "ifend"}:
            if not conditional_stack:
                raise PascalPreprocessorError(
                    "{$endif} ohne vorheriges {$if}.", line_number
                )
            conditional_stack.pop()
            return

        # Non-conditional directives only have an effect in an active branch.
        if not current_parent:
            return

        if command == "define":
            if not argument:
                raise PascalPreprocessorError(
                    "{$define} erwartet einen Symbolnamen.", line_number
                )
            define_parts = argument.split(None, 1)
            key = _pascal_pp_key(define_parts[0])
            defined.add(key)
            if len(define_parts) > 1:
                value = define_parts[1].strip()
                macros[key] = value
                explicit_value_macros.add(key)
            else:
                macros.setdefault(key, "1")
                explicit_value_macros.discard(key)
            return

        if command == "undef":
            key = _pascal_pp_key(argument.split(None, 1)[0] if argument else "")
            defined.discard(key)
            macros.pop(key, None)
            explicit_value_macros.discard(key)
            return

        if command == "error":
            raise PascalPreprocessorError(
                argument or "Pascal-{$error} ausgelöst.", line_number
            )

        if command in {"warning", "warn"}:
            warnings.append(
                f"Zeile {line_number}: {argument or 'Pascal-Warnung'}"
            )
            return

        if command == "info":
            warnings.append(
                f"Info Zeile {line_number}: {argument or 'Pascal-Info'}"
            )
            return

        # Stage 185: FreePascal/Delphi-style Linkdirektiven.
        # {$L foo.o}/{$LINK foo.o} akzeptieren Objekte und Archive;
        # {$LINKLIB foo.a} ist fuer Archive vorgesehen. Relative Namen werden
        # zuerst neben der Quelle und danach in den Projekt-Suchpfaden gesucht.
        if command in {"l", "link", "linklib"}:
            link_name = argument.strip()
            if (
                len(link_name) >= 2
                and link_name[0] == link_name[-1]
                and link_name[0] in {"'", '"'}
            ):
                link_name = link_name[1:-1]
            if not link_name:
                raise PascalPreprocessorError(
                    "{$L}/{$LINK}/{$LINKLIB} erwartet eine Datei.", line_number
                )
            _allowed = {".a", ".lib"} if command == "linklib" else {
                ".o", ".obj", ".a", ".lib"
            }
            _candidate = Path(link_name).expanduser()
            if _candidate.suffix.casefold() not in _allowed:
                raise PascalPreprocessorError(
                    f"{{${body.split(None, 1)[0]}}} erwartet "
                    + (".a/.lib" if command == "linklib" else ".o/.obj/.a/.lib")
                    + f": {link_name}.",
                    line_number,
                )
            _candidates: List[Path] = []
            if _candidate.is_absolute():
                _candidates.append(_candidate)
            else:
                try:
                    _source_path = Path(filename).expanduser()
                    _base_dir = (
                        _source_path.resolve().parent
                        if not str(filename).startswith("<")
                        else Path.cwd()
                    )
                except (OSError, RuntimeError, ValueError):
                    _base_dir = Path.cwd()
                _candidates.append(_base_dir / _candidate)
                for _directory in normalized_link_search_paths:
                    _candidates.append(_directory / _candidate)
            _chosen = next(
                (path for path in _candidates if path.is_file()),
                _candidates[0],
            )
            try:
                link_path = _chosen.resolve()
            except (OSError, RuntimeError):
                link_path = _chosen.absolute()
            key = str(link_path).casefold()
            if all(str(Path(item)).casefold() != key for item in link_files):
                link_files.append(str(link_path))
            return

        # Recognized non-conditional compiler switches are intentionally
        # consumed here so the grammar never mistakes them for {comments}.
        if command in {
            "mode", "modeswitch", "apptype", "codepage", "packrecords",
            "packenum", "push", "pop", "hints", "notes", "warnings",
            "rangechecks", "overflowchecks", "typedaddress", "longstrings",
        }:
            return

        # Includes are left visible to c64pascal because that compiler already
        # owns include-path resolution. Unknown directives are likewise left as
        # whitespace, but reported for traceability.
        if command in {"i", "include"}:
            warnings.append(
                f"Zeile {line_number}: Include-Direktive wird in Stage 176 noch nicht expandiert und wurde ignoriert: {body}"
            )
            return
        warnings.append(
            f"Zeile {line_number}: unbekannte Pascal-Direktive ignoriert: {body}"
        )

    while index < len(text):
        ch = text[index]
        is_active = active()

        # Quoted Pascal string. Doubled '' is an escaped quote.
        if ch == "'":
            start = index
            index += 1
            while index < len(text):
                if text[index] == "'":
                    if index + 1 < len(text) and text[index + 1] == "'":
                        index += 2
                        continue
                    index += 1
                    break
                if text[index] == "\n":
                    line += 1
                index += 1
            fragment = text[start:index]
            output.append(fragment if is_active else blank_fragment(fragment))
            continue

        # // line comment
        if text.startswith("//", index):
            end = text.find("\n", index)
            if end < 0:
                end = len(text)
            fragment = text[index:end]
            output.append(blank_fragment(fragment))
            removed_comments += 1
            index = end
            continue

        # {$directive}
        if text.startswith("{$", index):
            end = text.find("}", index + 2)
            if end < 0:
                raise PascalPreprocessorError(
                    "Nicht abgeschlossene Pascal-Direktive {$...}.", line
                )
            fragment = text[index:end + 1]
            process_directive(fragment[1:-1], line)
            output.append(blank_fragment(fragment))
            line += fragment.count("\n")
            index = end + 1
            continue

        # (*$directive*) - accepted as Delphi/FPC-compatible alternate spelling.
        if text.startswith("(*$", index):
            end = text.find("*)", index + 3)
            if end < 0:
                raise PascalPreprocessorError(
                    "Nicht abgeschlossene Pascal-Direktive (*$...*).", line
                )
            fragment = text[index:end + 2]
            process_directive(fragment[2:-2], line)
            output.append(blank_fragment(fragment))
            line += fragment.count("\n")
            index = end + 2
            continue

        # (* block comment *)
        if text.startswith("(*", index):
            end = text.find("*)", index + 2)
            if end < 0:
                raise PascalPreprocessorError(
                    "Nicht abgeschlossener Pascal-Kommentar (* ... *).", line
                )
            fragment = text[index:end + 2]
            output.append(blank_fragment(fragment))
            removed_comments += 1
            line += fragment.count("\n")
            index = end + 2
            continue

        # { block comment } -- only after {$...} was checked above.
        if ch == "{":
            end = text.find("}", index + 1)
            if end < 0:
                raise PascalPreprocessorError(
                    "Nicht abgeschlossener Pascal-Kommentar { ... }.", line
                )
            fragment = text[index:end + 1]
            output.append(blank_fragment(fragment))
            removed_comments += 1
            line += fragment.count("\n")
            index = end + 1
            continue

        if ch in "\r\n":
            output.append(ch)
            if ch == "\n":
                line += 1
            index += 1
            continue

        if not is_active:
            output.append(" " if ch != "\t" else "\t")
            index += 1
            continue

        # Expand object-like macros only on identifiers, never inside strings or
        # comments. Range types (0..255) and pointer syntax (^Char) are copied
        # byte-for-byte because they are valid Pascal grammar.
        if ch.isalpha() or ch == "_":
            end = index + 1
            while end < len(text) and (text[end].isalnum() or text[end] == "_"):
                end += 1
            identifier = text[index:end]
            output.append(
                _pascal_pp_expand_identifier(
                    identifier,
                    macros,
                    explicit_value_macros,
                    filename=filename,
                    line_number=line,
                )
            )
            index = end
            continue

        output.append(ch)
        index += 1

    if conditional_stack:
        frame = conditional_stack[-1]
        raise PascalPreprocessorError(
            "Nicht abgeschlossener Pascal-Bedingungsblock; {$endif} fehlt.",
            int(frame.get("line", 0) or 0),
        )

    result_source = "".join(output)
    original_lines = text.count("\n") + (1 if text or not text.endswith("\n") else 0)
    output_lines = result_source.count("\n") + (
        1 if result_source or not result_source.endswith("\n") else 0
    )
    return PascalPreprocessResult(
        source=result_source,
        macros=dict(macros),
        defined_symbols=tuple(sorted(defined)),
        directives=tuple(directives),
        warnings=tuple(warnings),
        removed_comment_count=removed_comments,
        original_line_count=original_lines,
        output_line_count=output_lines,
        link_files=tuple(link_files),
    )


from flags_rc    import *

# dBase: Start fuehrt ausschliesslich eine vorhandene EXE aus.
DBASE_START_HARD_NO_BUILD = True


# ---------------------------------------------------------------------------
# Stage 85: lokaler dBase-DBF-Strukturreader/-writer fuer den Tabellendesigner.
# ---------------------------------------------------------------------------
DBASE_DBF_FIELD_TYPES: Tuple[Tuple[str, str, int, int], ...] = (
    ("Zeichen", "C", 20, 0),
    ("Dezimal", "N", 10, 0),
    ("Fließkomma", "F", 12, 2),
    ("Datum", "D", 8, 0),
    ("Logisch", "L", 1, 0),
    ("Memo", "M", 10, 0),
)
DBASE_DBF_TYPE_LABELS: Dict[str, str] = {
    code: label for label, code, _length, _decimals in DBASE_DBF_FIELD_TYPES
}
DBASE_DBF_LABEL_TYPES: Dict[str, str] = {
    label: code for label, code, _length, _decimals in DBASE_DBF_FIELD_TYPES
}
DBASE_DBF_DEFAULTS: Dict[str, Tuple[int, int]] = {
    code: (length, decimals)
    for _label, code, length, decimals in DBASE_DBF_FIELD_TYPES
}


@dataclass
class DBaseDBFField:
    name: str
    field_type: str = "C"
    length: int = 20
    decimals: int = 0
    indexed: bool = False
    source_name: str = ""

    def normalized(self) -> "DBaseDBFField":
        name = str(self.name or "").strip()
        field_type = str(self.field_type or "C").strip().upper()[:1]
        if field_type not in DBASE_DBF_TYPE_LABELS:
            raise ValueError(f"Unbekannter DBF-Feldtyp: {self.field_type!r}")
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{0,9}", name):
            raise ValueError(
                f"Ungültiger DBF-Feldname {name!r}. Erlaubt sind 1 bis 10 "
                "Zeichen: Buchstaben, Ziffern und Unterstrich; das erste "
                "Zeichen muss ein Buchstabe oder Unterstrich sein."
            )

        length = int(self.length)
        decimals = int(self.decimals)
        if field_type == "C":
            length = max(1, min(length, 254))
            decimals = 0
        elif field_type in {"N", "F"}:
            length = max(1, min(length, 20))
            decimals = max(0, min(decimals, max(0, length - 2)))
        elif field_type == "D":
            length, decimals = 8, 0
        elif field_type == "L":
            length, decimals = 1, 0
        elif field_type == "M":
            length, decimals = 10, 0

        return DBaseDBFField(
            name=name,
            field_type=field_type,
            length=length,
            decimals=decimals,
            indexed=bool(self.indexed),
            source_name=str(self.source_name or name).strip(),
        )


@dataclass
class DBaseDBFTable:
    fields: List[DBaseDBFField]
    records: List[Tuple[bool, Dict[str, str]]] = field(default_factory=list)
    code_page_mark: int = 0x03
    source_path: Optional[Path] = None


def _dbase_dbf_field_bytes(value: str, field_type: str, length: int) -> bytes:
    text = "" if value is None else str(value)
    code = str(field_type).upper()[:1]
    if code == "C":
        raw = text.encode("cp1252", errors="replace")[:length]
        return raw.ljust(length, b" ")
    if code in {"N", "F", "M"}:
        raw = text.encode("ascii", errors="replace")[:length]
        return raw.rjust(length, b" ")
    if code == "D":
        raw = re.sub(r"[^0-9]", "", text).encode("ascii")[:8]
        return raw.ljust(length, b" ")
    if code == "L":
        first = text.strip().upper()[:1]
        if first in {"1", "Y", "J", "T"}:
            first = "T"
        elif first in {"0", "N", "F"}:
            first = "F"
        else:
            first = "?"
        return first.encode("ascii").ljust(length, b" ")
    return text.encode("cp1252", errors="replace")[:length].ljust(length, b" ")


def read_dbase_dbf(path: Path) -> DBaseDBFTable:
    """Liest DBF-Struktur und Datensaetze fuer den lokalen Tabellendesigner."""
    path = Path(path)
    blob = path.read_bytes()
    if len(blob) < 33:
        raise ValueError("Die DBF-Datei ist zu kurz oder beschädigt.")

    version = blob[0]
    record_count = struct.unpack_from("<I", blob, 4)[0]
    header_length = struct.unpack_from("<H", blob, 8)[0]
    record_length = struct.unpack_from("<H", blob, 10)[0]
    code_page_mark = blob[29] if len(blob) > 29 else 0x03
    if header_length < 33 or header_length > len(blob):
        raise ValueError("Ungültige DBF-Headerlänge.")
    if record_length < 1:
        raise ValueError("Ungültige DBF-Datensatzlänge.")

    fields: List[DBaseDBFField] = []
    offset = 32
    while offset + 32 <= header_length and blob[offset] != 0x0D:
        descriptor = blob[offset:offset + 32]
        raw_name = descriptor[0:11].split(b"\0", 1)[0].rstrip(b" ")
        name = raw_name.decode("ascii", errors="replace")
        field_type = chr(descriptor[11]).upper()
        length = int(descriptor[16])
        decimals = int(descriptor[17])
        if name and field_type:
            fields.append(
                DBaseDBFField(
                    name=name,
                    field_type=field_type,
                    length=length,
                    decimals=decimals,
                    source_name=name,
                )
            )
        offset += 32

    records: List[Tuple[bool, Dict[str, str]]] = []
    data_offset = header_length
    for record_index in range(record_count):
        start = data_offset + record_index * record_length
        end = start + record_length
        if end > len(blob):
            break
        record = blob[start:end]
        deleted = bool(record[:1] == b"*")
        values: Dict[str, str] = {}
        pos = 1
        for dbf_field in fields:
            raw = record[pos:pos + dbf_field.length]
            pos += dbf_field.length
            if dbf_field.field_type == "C":
                value = raw.decode("cp1252", errors="replace").rstrip(" \0")
            else:
                value = raw.decode("ascii", errors="replace").strip(" \0")
            values[dbf_field.name] = value
        records.append((deleted, values))

    table = DBaseDBFTable(
        fields=fields,
        records=records,
        code_page_mark=code_page_mark,
        source_path=path,
    )

    # Stage-85-Seitenmetadaten bewahren die im normalen DBF nicht enthaltene
    # Designer-Markierung "Index". Physische NDX/MDX-Dateien werden dadurch
    # nicht vorgetäuscht oder verändert.
    metadata_path = path.with_suffix(path.suffix + ".d64meta.json")
    try:
        metadata = json.loads(metadata_path.read_text(encoding="utf-8"))
        indexed_names = {
            str(name).casefold()
            for name in metadata.get("indexed_fields", [])
        }
        for dbf_field in table.fields:
            dbf_field.indexed = dbf_field.name.casefold() in indexed_names
    except (OSError, ValueError, TypeError, AttributeError):
        pass

    return table



# ---------------------------------------------------------------------------
# Stage ASM 43: kleiner SQL-Parser/-Executor fuer lokale dBase-DBF-Abfragen.
# Er versteht bewusst den vom integrierten SQL Builder erzeugten SELECT-Dialekt
# und kann dadurch *.d64sql-Dateien auch ohne aktive ODBC-Verbindung als
# Berichtsdatenquelle verwenden.
# ---------------------------------------------------------------------------
class D64DBFSQLParseError(ValueError):
    pass


def _d64sql_unquote_identifier(value: str) -> str:
    text = str(value or "").strip()
    if len(text) >= 2 and text[0] == '[' and text[-1] == ']':
        return text[1:-1].replace(']]', ']')
    if len(text) >= 2 and text[0] == '`' and text[-1] == '`':
        return text[1:-1].replace('``', '`')
    if len(text) >= 2 and text[0] == '"' and text[-1] == '"':
        return text[1:-1].replace('""', '"')
    return text


def _d64sql_split_top_level(text: str, delimiter: str = ',') -> List[str]:
    parts: List[str] = []
    current: List[str] = []
    depth = 0
    quote = ''
    bracket = False
    i = 0
    while i < len(text):
        ch = text[i]
        if bracket:
            current.append(ch)
            if ch == ']':
                if i + 1 < len(text) and text[i + 1] == ']':
                    current.append(text[i + 1]); i += 1
                else:
                    bracket = False
            i += 1; continue
        if quote:
            current.append(ch)
            if ch == quote:
                if i + 1 < len(text) and text[i + 1] == quote:
                    current.append(text[i + 1]); i += 1
                else:
                    quote = ''
            i += 1; continue
        if ch == '[':
            bracket = True; current.append(ch)
        elif ch in ('\'', '"', '`'):
            quote = ch; current.append(ch)
        elif ch == '(':
            depth += 1; current.append(ch)
        elif ch == ')':
            depth = max(0, depth - 1); current.append(ch)
        elif ch == delimiter and depth == 0:
            parts.append(''.join(current).strip()); current = []
        else:
            current.append(ch)
        i += 1
    if current or text.strip():
        parts.append(''.join(current).strip())
    return [part for part in parts if part]


def _d64sql_field_ref(expr: str) -> Tuple[str, str]:
    text = str(expr or '').strip()
    match = re.fullmatch(
        r'(?is)\s*(?:(\[[^\]]+(?:\]\][^\]]*)*\]|`[^`]+`|"[^"]+"|[A-Za-z_][A-Za-z0-9_$]*)\s*\.\s*)?'
        r'(\[[^\]]+(?:\]\][^\]]*)*\]|`[^`]+`|"[^"]+"|[A-Za-z_][A-Za-z0-9_$]*)\s*',
        text,
    )
    if not match:
        raise D64DBFSQLParseError(f'Ungueltige Feldreferenz: {text}')
    return (
        _d64sql_unquote_identifier(match.group(1) or ''),
        _d64sql_unquote_identifier(match.group(2) or ''),
    )


def _d64sql_parse_select(sql: str) -> Dict[str, object]:
    statement = str(sql or '').strip().rstrip(';').strip()
    if not statement:
        raise D64DBFSQLParseError('Der SQL-Ausdruck ist leer.')
    m = re.match(r'(?is)^\s*SELECT\s+(.*?)\s+FROM\s+(.+)$', statement)
    if not m:
        raise D64DBFSQLParseError('Der lokale DBF-SQL-Parser erwartet SELECT ... FROM ... .')
    select_text = m.group(1).strip()
    tail = m.group(2).strip()

    order_text = ''
    order_match = re.search(r'(?is)\s+ORDER\s+BY\s+', tail)
    if order_match:
        order_text = tail[order_match.end():].strip()
        tail = tail[:order_match.start()].strip()
    where_text = ''
    where_match = re.search(r'(?is)\s+WHERE\s+', tail)
    if where_match:
        where_text = tail[where_match.end():].strip()
        tail = tail[:where_match.start()].strip()

    join_re = re.compile(r'(?is)\s+(INNER\s+JOIN|CROSS\s+JOIN)\s+')
    pieces = join_re.split(tail)
    root_text = pieces[0].strip()

    def parse_table_decl(text: str) -> Tuple[str, str]:
        mm = re.match(
            r'(?is)^\s*(\[[^\]]+(?:\]\][^\]]*)*\]|`[^`]+`|"[^"]+"|[A-Za-z_][A-Za-z0-9_$]*)'
            r'(?:\s+(?:AS\s+)?(\[[^\]]+\]|`[^`]+`|"[^"]+"|[A-Za-z_][A-Za-z0-9_$]*))?\s*$',
            text,
        )
        if not mm:
            raise D64DBFSQLParseError(f'Ungueltige Tabellenangabe: {text}')
        name = _d64sql_unquote_identifier(mm.group(1))
        alias = _d64sql_unquote_identifier(mm.group(2) or name)
        return name, alias

    root_name, root_alias = parse_table_decl(root_text)
    joins = []
    for i in range(1, len(pieces), 2):
        kind = re.sub(r'\s+', ' ', pieces[i].strip().upper())
        body = pieces[i + 1].strip()
        if kind == 'INNER JOIN':
            on_m = re.search(r'(?is)\s+ON\s+', body)
            if not on_m:
                raise D64DBFSQLParseError('INNER JOIN ohne ON-Bedingung.')
            table_decl = body[:on_m.start()].strip()
            cond_text = body[on_m.end():].strip()
        else:
            table_decl = body
            cond_text = ''
        name, alias = parse_table_decl(table_decl)
        joins.append({'kind': kind, 'table': name, 'alias': alias, 'condition': cond_text})

    columns = []
    for raw in _d64sql_split_top_level(select_text):
        if raw == '*':
            columns.append({'expr': '*', 'alias': ''}); continue
        am = re.match(r'(?is)^(.*?)\s+AS\s+(\[[^\]]+\]|`[^`]+`|"[^"]+"|[A-Za-z_][A-Za-z0-9_$]*)\s*$', raw)
        if am:
            expr = am.group(1).strip(); alias = _d64sql_unquote_identifier(am.group(2))
        else:
            expr = raw.strip(); alias = ''
        _d64sql_field_ref(expr)  # validation
        columns.append({'expr': expr, 'alias': alias})

    orders = []
    if order_text:
        for raw in _d64sql_split_top_level(order_text):
            om = re.match(r'(?is)^(.*?)(?:\s+(ASC|DESC))?\s*$', raw)
            expr = om.group(1).strip(); direction = (om.group(2) or 'ASC').upper()
            transform = ''
            fm = re.fullmatch(r'(?is)(VAL|UPPER)\s*\((.*?)\)', expr)
            if fm:
                transform = fm.group(1).upper(); expr = fm.group(2).strip()
            _d64sql_field_ref(expr)
            orders.append({'expr': expr, 'direction': direction, 'transform': transform})

    return {
        'columns': columns,
        'root_table': root_name,
        'root_alias': root_alias,
        'joins': joins,
        'where': where_text,
        'order_by': orders,
    }


def _d64sql_split_boolean_and(text: str) -> List[str]:
    # Der SQL Builder erzeugt JOIN-Bedingungen mit AND. Klammern/Strings werden
    # beim Splitten beruecksichtigt; OR bleibt fuer eine spaetere Parserstufe.
    source = str(text or '').strip()
    if not source:
        return []
    parts = []
    start = 0; depth = 0; quote = ''; bracket = False; i = 0
    while i < len(source):
        ch = source[i]
        if bracket:
            if ch == ']': bracket = False
            i += 1; continue
        if quote:
            if ch == quote: quote = ''
            i += 1; continue
        if ch == '[': bracket = True; i += 1; continue
        if ch in ('\'', '"', '`'): quote = ch; i += 1; continue
        if ch == '(': depth += 1; i += 1; continue
        if ch == ')': depth = max(0, depth - 1); i += 1; continue
        if depth == 0 and source[i:i+3].upper() == 'AND':
            before = source[i-1] if i else ' '
            after = source[i+3] if i+3 < len(source) else ' '
            if not (before.isalnum() or before == '_') and not (after.isalnum() or after == '_'):
                parts.append(source[start:i].strip()); start = i + 3; i += 3; continue
        i += 1
    parts.append(source[start:].strip())
    return [p for p in parts if p]


def execute_d64sql_dbf_project(payload: Dict[str, object], *, sql: str = '') -> Tuple[List[str], List[List[object]]]:
    """Fuehrt den SELECT-Dialekt des SQL Builders direkt auf DBF-Dateien aus.

    Dadurch kann insbesondere der Bericht Builder *.d64sql als Datenquelle
    verwenden, ohne dass eine ODBC-Verbindung bereits live geoeffnet sein muss.
    """
    query_text = str(sql or payload.get('sql', '') or '').strip()
    parsed = _d64sql_parse_select(query_text)

    table_paths: Dict[str, Path] = {}
    for item in payload.get('tables', []) or []:
        if not isinstance(item, dict):
            continue
        raw = str(item.get('path', '') or '').strip()
        if not raw:
            continue
        path = Path(raw).expanduser()
        table_paths[path.stem.casefold()] = path
    directory = Path(str(payload.get('directory', '') or '')).expanduser()

    def find_table(name: str) -> Path:
        key = str(name).casefold()
        path = table_paths.get(key)
        if path is not None and path.is_file():
            return path
        if directory.is_dir():
            direct = directory / f'{name}.dbf'
            if direct.is_file(): return direct
            for candidate in directory.glob('*.dbf'):
                if candidate.stem.casefold() == key:
                    return candidate
        raise D64DBFSQLParseError(f'DBF-Tabelle fuer SQL nicht gefunden: {name}')

    loaded: Dict[str, Tuple[List[str], List[Dict[str, str]]]] = {}
    def load_table(name: str):
        key = name.casefold()
        if key not in loaded:
            table = read_dbase_dbf(find_table(name))
            fields = [str(f.name) for f in table.fields]
            rows = [dict(values) for deleted, values in table.records if not deleted]
            loaded[key] = (fields, rows)
        return loaded[key]

    aliases: Dict[str, str] = {str(parsed['root_alias']).casefold(): str(parsed['root_table'])}
    aliases[str(parsed['root_table']).casefold()] = str(parsed['root_table'])
    table_order = [(str(parsed['root_table']), str(parsed['root_alias']))]
    for join in parsed['joins']:
        aliases[str(join['alias']).casefold()] = str(join['table'])
        aliases[str(join['table']).casefold()] = str(join['table'])
        table_order.append((str(join['table']), str(join['alias'])))

    def ctx_value(ctx: Dict[str, Dict[str, str]], expr: str):
        table_ref, field = _d64sql_field_ref(expr)
        if table_ref:
            target = table_ref.casefold()
            for alias, row in ctx.items():
                if alias.casefold() == target:
                    for k, v in row.items():
                        if str(k).casefold() == field.casefold(): return v
            actual = aliases.get(target, '')
            if actual:
                for alias, row in ctx.items():
                    if aliases.get(alias.casefold(), alias).casefold() == actual.casefold():
                        for k, v in row.items():
                            if str(k).casefold() == field.casefold(): return v
            return ''
        matches = []
        for row in ctx.values():
            for k, v in row.items():
                if str(k).casefold() == field.casefold(): matches.append(v)
        return matches[0] if len(matches) == 1 else (matches[0] if matches else '')

    def scalar(expr: str, ctx):
        text = str(expr).strip()
        if len(text) >= 2 and text[0] == "'" and text[-1] == "'":
            return text[1:-1].replace("''", "'")
        if re.fullmatch(r'[+-]?\d+(?:\.\d+)?', text):
            try: return float(text) if '.' in text else int(text)
            except Exception: return text
        return ctx_value(ctx, text)

    def compare_values(left, op: str, right) -> bool:
        def number(v):
            try: return float(str(v).strip().replace(',', '.'))
            except Exception: return None
        ln, rn = number(left), number(right)
        a, b = (ln, rn) if ln is not None and rn is not None else (str(left), str(right))
        return {'=': a == b, '<>': a != b, '!=': a != b,
                '<': a < b, '<=': a <= b, '>': a > b, '>=': a >= b}.get(op, False)

    def condition_ok(text: str, ctx) -> bool:
        for part in _d64sql_split_boolean_and(text):
            cm = re.match(r'(?is)^\s*(.*?)\s*(<=|>=|<>|!=|=|<|>)\s*(.*?)\s*$', part)
            if not cm:
                raise D64DBFSQLParseError(f'Nicht unterstuetzte SQL-Bedingung: {part}')
            if not compare_values(scalar(cm.group(1), ctx), cm.group(2), scalar(cm.group(3), ctx)):
                return False
        return True

    _root_fields, root_rows = load_table(str(parsed['root_table']))
    contexts = [{str(parsed['root_alias']): row} for row in root_rows]
    for join in parsed['joins']:
        _fields, right_rows = load_table(str(join['table']))
        new_contexts = []
        for ctx in contexts:
            for row in right_rows:
                merged = dict(ctx); merged[str(join['alias'])] = row
                if str(join['kind']) == 'CROSS JOIN' or condition_ok(str(join['condition']), merged):
                    new_contexts.append(merged)
        contexts = new_contexts

    where_text = str(parsed.get('where', '') or '').strip()
    if where_text:
        contexts = [ctx for ctx in contexts if condition_ok(where_text, ctx)]

    # ORDER BY von hinten nach vorne stabil sortieren.
    for order in reversed(parsed['order_by']):
        def order_key(ctx, o=order):
            value = ctx_value(ctx, str(o['expr']))
            transform = str(o.get('transform', ''))
            if transform == 'VAL':
                try: return (0, float(str(value).strip().replace(',', '.')))
                except Exception: return (1, 0.0)
            if transform == 'UPPER': return str(value).upper()
            try: return (0, float(str(value).strip().replace(',', '.')))
            except Exception: return (1, str(value).casefold())
        contexts.sort(key=order_key, reverse=str(order['direction']).upper() == 'DESC')

    columns = list(parsed['columns'])
    if len(columns) == 1 and columns[0]['expr'] == '*':
        expanded = []
        seen = set()
        for table_name, alias in table_order:
            fields, _rows = load_table(table_name)
            for field in fields:
                header = field
                if header.casefold() in seen:
                    header = f'{alias}.{field}'
                seen.add(header.casefold())
                expanded.append({'expr': f'{alias}.{field}', 'alias': header})
        columns = expanded

    headers: List[str] = []
    for column in columns:
        expr = str(column['expr'])
        alias = str(column.get('alias', '') or '')
        if alias:
            header = alias
        else:
            _table, field = _d64sql_field_ref(expr)
            header = field
        if header in headers:
            table_ref, field = _d64sql_field_ref(expr)
            header = f'{table_ref}.{field}' if table_ref else field
        headers.append(header)

    rows: List[List[object]] = []
    for ctx in contexts:
        rows.append([ctx_value(ctx, str(column['expr'])) for column in columns])
    return headers, rows

def write_dbase_dbf(
    path: Path,
    fields: Sequence[DBaseDBFField],
    records: Optional[Sequence[Tuple[bool, Dict[str, str]]]] = None,
    *,
    code_page_mark: int = 0x03,
    source_path: Optional[Path] = None,
) -> Path:
    """Schreibt eine lokale dBase-III/IV-kompatible DBF-Datei."""
    path = Path(path)
    normalized = [field_spec.normalized() for field_spec in fields]
    if not normalized:
        raise ValueError("Eine DBF-Tabelle benötigt mindestens ein Feld.")

    seen = set()
    for field_spec in normalized:
        key = field_spec.name.casefold()
        if key in seen:
            raise ValueError(f"Der DBF-Feldname {field_spec.name!r} ist doppelt vorhanden.")
        seen.add(key)

    record_rows = list(records or [])
    header_length = 32 + len(normalized) * 32 + 1
    record_length = 1 + sum(field_spec.length for field_spec in normalized)
    if record_length > 0xFFFF:
        raise ValueError("Die DBF-Datensatzlänge überschreitet 65535 Bytes.")

    has_memo = any(field_spec.field_type == "M" for field_spec in normalized)
    header = bytearray(32)
    header[0] = 0x83 if has_memo else 0x03
    now = time.localtime()
    header[1] = max(0, min(255, now.tm_year - 1900))
    header[2] = now.tm_mon
    header[3] = now.tm_mday
    struct.pack_into("<I", header, 4, len(record_rows))
    struct.pack_into("<H", header, 8, header_length)
    struct.pack_into("<H", header, 10, record_length)
    header[29] = int(code_page_mark) & 0xFF

    output = bytearray(header)
    for field_spec in normalized:
        descriptor = bytearray(32)
        encoded_name = field_spec.name.encode("ascii", errors="strict")[:10]
        descriptor[0:len(encoded_name)] = encoded_name
        descriptor[11] = ord(field_spec.field_type)
        descriptor[16] = field_spec.length & 0xFF
        descriptor[17] = field_spec.decimals & 0xFF
        output.extend(descriptor)
    output.append(0x0D)

    for deleted, values in record_rows:
        output.extend(b"*" if deleted else b" ")
        for field_spec in normalized:
            lookup_name = field_spec.source_name or field_spec.name
            value = values.get(lookup_name, values.get(field_spec.name, ""))
            output.extend(
                _dbase_dbf_field_bytes(
                    value,
                    field_spec.field_type,
                    field_spec.length,
                )
            )
    output.append(0x1A)

    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_bytes(output)
    os.replace(str(temporary), str(path))

    # Die Index-Checkbox ist Strukturmetadaten des Designers. Klassische DBF-
    # Dateien speichern die Feld-zu-Index-Zuordnung nicht selbst; echte NDX/MDX-
    # Erzeugung ist ein separater Index-Writer. Deshalb bleibt die Markierung in
    # einer kleinen Sidecar-Datei erhalten, ohne fremde Indexdateien anzutasten.
    metadata_path = path.with_suffix(path.suffix + ".d64meta.json")
    metadata = {
        "format": "dBase2Many-table-designer-v1",
        "indexed_fields": [
            field_spec.name for field_spec in normalized if field_spec.indexed
        ],
    }
    metadata_path.write_text(
        json.dumps(metadata, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )

    if has_memo:
        destination_dbt = path.with_suffix(".dbt")
        source = Path(source_path) if source_path else None
        source_dbt = source.with_suffix(".dbt") if source else None
        if source_dbt is not None and source_dbt.is_file() and source_dbt != destination_dbt:
            shutil.copy2(source_dbt, destination_dbt)
        elif not destination_dbt.exists():
            dbt_header = bytearray(512)
            struct.pack_into(">I", dbt_header, 0, 1)
            destination_dbt.write_bytes(dbt_header)

    return path

# ---------------------------------------------------------------------------
# Stage 14 - PETSCII -> Unicode -> C64Pro.ttf Mapping fuer den Hex-Viewer.
#
# PETSCII-Bytewerte duerfen nicht mit Unicode-Codepoints gleichgesetzt werden.
# C64 Pro Mono besitzt neben den Direct-PETSCII-PUA-Seiten auch die passenden
# Unicode-Zeichen fuer ASCII, Pfeile, Box-Drawing, Blockgrafik, Kartenfarben
# und die historischen CUS/PUA-Zeichen. Die Tabelle unten bildet deshalb den
# PETSCII-Wert explizit auf den Unicode-Codepoint ab, der mit C64Pro.ttf
# gezeichnet werden soll.
#
# Nicht eindeutig definierte Steuerbytes fallen auf die Direct-PETSCII-Seite
# U+E000..U+E0FF zurueck. Dadurch bleibt jedes der 256 Bytes sichtbar.
#
# Wichtig: Die Tabelle ist absichtlich editierbar. Wenn eine lokal verwendete
# C64Pro.ttf-Version ein PETSCII-Zeichen an einem anderen Unicode-Codepoint
# ablegt, muss nur der betreffende Eintrag geaendert werden, z.B. hypothetisch:
#     C64_PETSCII_TO_C64PRO_CODEPOINT[203] = 0x1000
# ---------------------------------------------------------------------------

def _build_c64_petscii_to_c64pro_codepoint() -> Dict[int, int]:
    # Sicherer Fallback: Style Direct PETSCII (Upper/Graphics, reverse off).
    mapping: Dict[int, int] = {
        value: 0xE000 + value
        for value in range(0x100)
    }

    # PETSCII-Steuerzeichen, fuer die eine definierte Unicode/CUS-Zuordnung
    # existiert. Nicht definierte Controls behalten den Direct-PETSCII-Fallback.
    mapping.update({
        0x05: 0xF100,  # white
        0x08: 0xF118,  # disable charset switching
        0x09: 0xF119,  # enable charset switching
        0x0D: 0x000D,  # carriage return
        0x0E: 0x000E,  # shift out
        0x11: 0xF11C,  # cursor down
        0x12: 0xF11A,  # reverse on
        0x13: 0xF120,  # home
        0x14: 0x007F,  # delete
        0x1C: 0xF101,  # red
        0x1D: 0xF11D,  # cursor right
        0x1E: 0xF102,  # green
        0x1F: 0xF103,  # blue
        0x81: 0xF104,  # orange
        0x85: 0xF110,  # F1
        0x86: 0xF112,  # F3
        0x87: 0xF114,  # F5
        0x88: 0xF116,  # F7
        0x89: 0xF111,  # F2
        0x8A: 0xF113,  # F4
        0x8B: 0xF115,  # F6
        0x8C: 0xF117,  # F8
        0x8D: 0x000A,  # line feed
        0x8E: 0x000F,  # shift in
        0x90: 0xF105,  # black
        0x91: 0xF11E,  # cursor up
        0x92: 0xF11B,  # reverse off
        0x93: 0x000C,  # clear/form feed
        0x94: 0xF121,  # insert
        0x95: 0xF106,  # brown
        0x96: 0xF107,  # light red
        0x97: 0xF108,  # gray 1
        0x98: 0xF109,  # gray 2
        0x99: 0xF10A,  # light green
        0x9A: 0xF10B,  # light blue
        0x9B: 0xF10C,  # gray 3
        0x9C: 0xF10D,  # purple
        0x9D: 0xF11D,  # cursor left
        0x9E: 0xF10E,  # yellow
        0x9F: 0xF10F,  # cyan
    })

    # PETSCII $20..$5B entspricht den druckbaren Unicode/ASCII-Zeichen.
    for value in range(0x20, 0x5C):
        mapping[value] = value
    mapping.update({
        0x5C: 0x00A3,  # pound sign
        0x5D: 0x005D,
        0x5E: 0x2191,  # up arrow
        0x5F: 0x2190,  # left arrow
    })

    # Upper/Graphics PETSCII $60..$7F.
    upper_graphics = (
        0x2501, 0x2660, 0x2502, 0x2501,
        0xF122, 0xF123, 0xF124, 0xF126,
        0xF128, 0x256E, 0x2570, 0x256F,
        0xF12A, 0x2572, 0x2571, 0xF12B,
        0xF12C, 0x25CF, 0xF125, 0x2665,
        0xF127, 0x256D, 0x2573, 0x25CB,
        0x2663, 0xF129, 0x2666, 0x253C,
        0xF12E, 0x2502, 0x03C0, 0x25E5,
    )
    for offset, codepoint in enumerate(upper_graphics):
        mapping[0x60 + offset] = codepoint

    # Block-/Box-Grafik PETSCII $A0..$BF.
    block_graphics = (
        0x00A0, 0x258C, 0x2584, 0x2594,
        0x2581, 0x258F, 0x2592, 0x2595,
        0xF12F, 0x25E4, 0xF130, 0x251C,
        0xF134, 0x2514, 0x2510, 0x2582,
        0x250C, 0x2534, 0x252C, 0x2524,
        0x258E, 0x258D, 0xF131, 0xF132,
        0xF133, 0x2583, 0xF12D, 0xF135,
        0xF136, 0x2518, 0xF137, 0xF138,
    )
    for offset, codepoint in enumerate(block_graphics):
        mapping[0xA0 + offset] = codepoint

    # $C0..$DE wiederholen die sichtbaren Upper/Graphics-Zeichen von $60..$7E.
    for offset in range(0x1F):
        mapping[0xC0 + offset] = mapping[0x60 + offset]
    mapping[0xDF] = 0x25E5

    # $E0..$FE wiederholen die Blockgrafik von $A0..$BE; $FF ist PI.
    for offset in range(0x1F):
        mapping[0xE0 + offset] = mapping[0xA0 + offset]
    mapping[0xFF] = 0x03C0

    return mapping


C64_PETSCII_TO_C64PRO_CODEPOINT: Dict[int, int] = (
    _build_c64_petscii_to_c64pro_codepoint()
)

# Unicode-Zeichen-Map fuer die eigentliche QPainter-Ausgabe.
C64_PETSCII_TO_C64PRO_UNICODE: Dict[int, str] = {
    petscii_byte: chr(codepoint)
    for petscii_byte, codepoint in C64_PETSCII_TO_C64PRO_CODEPOINT.items()
}

# Kompatibilitaets-Tuple fuer bestehende Dialoge/Editoren.
C64_PRO_PETSCII_GLYPHS: Tuple[str, ...] = tuple(
    C64_PETSCII_TO_C64PRO_UNICODE[petscii_byte]
    for petscii_byte in range(0x100)
)

# ---------------------------------------------------------------------------
# C64-Character-Editor: Ein Zeichensatz umfasst 256 Zeichen zu je acht Bytes.
# Zeichen $00 bleibt als reserviertes Leerzeichen erhalten; editierbar sind
# die 255 Zeichen $01..$FF. Rohdateien duerfen entweder 2048 Bytes inklusive
# Zeichen $00 oder 2040 Bytes nur fuer die editierbaren Zeichen enthalten.
# ---------------------------------------------------------------------------
