def _parse_pe64_source(source: str):
    lines=[]; labels={}; externals=set(); imports={}; exports={}; dll_name=None; entry="_start"; offset=0
    for line_no,raw in enumerate(str(source).splitlines(),1):
        text=_x86_strip_comment(raw)
        if not text: continue
        while True:
            m=re.match(r"^([A-Za-z_.$?@][A-Za-z0-9_.$?@]*)\s*:\s*(.*)$",text)
            if not m: break
            key=m.group(1).casefold()
            if key in labels: raise PE64AssemblerError(f"Symbol mehrfach definiert: {m.group(1)}",line_no)
            labels[key]=offset; text=m.group(2).strip()
            if not text: break
        if not text: continue
        parts=text.split(None,1); directive=parts[0].casefold().lstrip("."); args=parts[1].strip() if len(parts)>1 else ""
        if directive in {"section","text","code","global","globl","public","bits","cpu","model"}:
            lines.append((line_no,text)); continue
        if directive in {"extern","extrn"}:
            for item in _x86_split_operands(args):
                if item: externals.add(item.strip().casefold())
            lines.append((line_no,text)); continue
        if directive=="import":
            ops=_x86_split_operands(args)
            if len(ops) not in {2,3}: raise PE64AssemblerError('IMPORT erwartet: import symbol, "dll", "member"',line_no)
            symbol=_pe32_unquote(ops[0]).strip(); dll=_pe32_unquote(ops[1]).strip(); member=_pe32_unquote(ops[2]).strip() if len(ops)==3 else symbol
            imports[symbol.casefold()]=(dll,member); externals.add(symbol.casefold()); lines.append((line_no,text)); continue
        if directive=="export":
            ops=_x86_split_operands(args)
            if len(ops) not in {1,2}: raise PE64AssemblerError("EXPORT erwartet public_name [, internal_symbol]",line_no)
            public=_pe32_unquote(ops[0]).strip(); internal=_pe32_unquote(ops[1]).strip() if len(ops)==2 else public
            exports[public]=internal.casefold(); lines.append((line_no,text)); continue
        if directive=="dllname": dll_name=_pe32_unquote(args); lines.append((line_no,text)); continue
        if directive=="entry": entry=args.split()[0]; lines.append((line_no,text)); continue
        if directive=="align":
            align=_x86_parse_int(args)
            if align is None or align<=0 or align&(align-1): raise PE64AssemblerError("ALIGN erwartet eine Zweierpotenz.",line_no)
            offset=_align_up(offset,align); lines.append((line_no,text)); continue
        if directive in {"db","byte"}: offset += len(_x86_data_values(args,line_no,1)); lines.append((line_no,text)); continue
        if directive in {"dw","word"}: offset += 2*len(_x86_split_operands(args)); lines.append((line_no,text)); continue
        if directive in {"dd","dword","long"}: offset += 4*len(_x86_split_operands(args)); lines.append((line_no,text)); continue
        if directive in {"dq","qword"}: offset += 8*len(_x86_split_operands(args)); lines.append((line_no,text)); continue
        encoded=_encode_pe64_instruction(text,line_no,offset,relocs=[]); offset += len(encoded); lines.append((line_no,text))
    return lines,labels,entry,tuple(sorted(externals)),imports,exports,dll_name


def assemble_pe64_object_source(source: str, *, filename: str="<PE64-Assembler>") -> PE64ObjectProgram:
    del filename
    lines,labels,entry,externals,imports,exports,dll_name=_parse_pe64_source(source)
    out=bytearray(); relocs=[]
    for line_no,text in lines:
        parts=text.split(None,1); directive=parts[0].casefold().lstrip("."); args=parts[1].strip() if len(parts)>1 else ""
        if directive in {"section","text","code","global","globl","public","bits","cpu","model","extern","extrn","import","export","dllname","entry"}: continue
        if directive=="align":
            align=int(_x86_parse_int(args)); out.extend(bytes(_align_up(len(out),align)-len(out))); continue
        unit={"db":1,"byte":1,"dw":2,"word":2,"dd":4,"dword":4,"long":4,"dq":8,"qword":8}.get(directive)
        if unit:
            for token in _x86_split_operands(args):
                token=token.strip()
                if unit==1 and len(token)>=2 and token[0] in {'\"',"'"} and token[-1]==token[0]:
                    decoded=ast.literal_eval(token); out.extend(str(decoded).encode("latin-1",errors="replace")); continue
                value=_x86_parse_int(token)
                if value is not None:
                    out.extend(int(value & ((1<<(unit*8))-1)).to_bytes(unit,"little")); continue
                if not _x64_is_symbol(token): raise PE64AssemblerError(f"Numerischer Datenwert oder Symbol erwartet: {token}",line_no)
                patch=len(out); out.extend(bytes(unit))
                rel_type=IMAGE_REL_AMD64_ADDR64 if unit==8 else IMAGE_REL_AMD64_ADDR32
                relocs.append(PE64Relocation(patch,token.casefold(),rel_type))
            continue
        encoded=_encode_pe64_instruction(text,line_no,len(out),relocs=relocs); out.extend(encoded)
    return PE64ObjectProgram(bytes(out),dict(labels),externals,tuple(relocs),entry,dict(imports),dict(exports),dll_name)


def _coff64_metadata_bytes(obj: PE64ObjectProgram) -> bytes:
    document={"format":"d64-coff64-link-v1","entry":obj.entry_symbol,"imports":{s:{"dll":v[0],"member":v[1]} for s,v in sorted(obj.imports.items())},"exports":dict(obj.exports),"dll_name":obj.dll_name}
    if not document["imports"] and not document["exports"] and not document["dll_name"]: return b""
    return (json.dumps(document,ensure_ascii=True,sort_keys=True)+"\n").encode("ascii")


def write_coff64_object(obj: PE64ObjectProgram) -> bytes:
    names=list(obj.symbols.keys())
    for name in obj.externals:
        if name not in names: names.append(name)
    index={name:i for i,name in enumerate(names)}; metadata=_coff64_metadata_bytes(obj); sections=2 if metadata else 1
    header_size=20+sections*40; text_ptr=header_size; meta_ptr=text_ptr+len(obj.code) if metadata else 0; reloc_ptr=text_ptr+len(obj.code)+len(metadata); sym_ptr=reloc_ptr+len(obj.relocations)*10
    header=struct.pack("<HHIIIHH",IMAGE_FILE_MACHINE_AMD64,sections,0,sym_ptr,len(names),0,0)
    sh=bytearray(40); sh[:8]=b".text\0\0\0"; struct.pack_into("<I",sh,0x10,len(obj.code)); struct.pack_into("<I",sh,0x14,text_ptr); struct.pack_into("<I",sh,0x18,reloc_ptr if obj.relocations else 0); struct.pack_into("<H",sh,0x20,len(obj.relocations)); struct.pack_into("<I",sh,0x24,0xE0500020)
    headers=bytearray(sh)
    if metadata:
        ds=bytearray(40); ds[:8]=b".drectve"; struct.pack_into("<I",ds,0x10,len(metadata)); struct.pack_into("<I",ds,0x14,meta_ptr); struct.pack_into("<I",ds,0x24,0x00100A00); headers.extend(ds)
    rb=bytearray()
    for r in obj.relocations:
        if r.symbol not in index: raise PE64AssemblerError(f"COFF64-Symbol fehlt: {r.symbol}")
        rb.extend(struct.pack("<IIH",r.offset,index[r.symbol],r.relocation_type))
    strings=bytearray(); syms=bytearray()
    for name in names:
        syms.extend(_coff_symbol_name_bytes(name,strings)); defined=name in obj.symbols; syms.extend(struct.pack("<IhHBB",int(obj.symbols.get(name,0)),1 if defined else 0,0,2,0))
    st=struct.pack("<I",4+len(strings))+bytes(strings)
    return header+bytes(headers)+obj.code+metadata+bytes(rb)+bytes(syms)+st


def assemble_pe64_coff_object(source: str, *, filename: str="<PE64-Assembler>") -> bytes:
    return write_coff64_object(assemble_pe64_object_source(source,filename=filename))


def parse_coff64_object(data: bytes) -> Coff64ParsedObject:
    payload=bytes(data)
    if len(payload)<60: raise PE64AssemblerError("COFF64-Objekt ist zu klein.")
    machine,sections,_ts,sym_ptr,sym_count,opt,_chars=struct.unpack_from("<HHIIIHH",payload,0)
    if machine!=IMAGE_FILE_MACHINE_AMD64 or sections<1 or opt!=0: raise PE64AssemblerError("Nur relocierbare AMD64-COFF-Objekte werden unterstützt.")
    text=None; meta=b""
    for i in range(sections):
        off=20+i*40; name=payload[off:off+8].rstrip(b"\0"); raw_size,raw_ptr,rel_ptr=struct.unpack_from("<III",payload,off+0x10); rel_count=struct.unpack_from("<H",payload,off+0x20)[0]
        if raw_ptr and raw_ptr+raw_size>len(payload): raise PE64AssemblerError("COFF64-Sektion außerhalb der Datei.")
        if name==b".text": text=(raw_size,raw_ptr,rel_ptr,rel_count)
        elif name==b".drectve" and raw_ptr: meta=payload[raw_ptr:raw_ptr+raw_size]
    if text is None: raise PE64AssemblerError("COFF64-Objekt enthält keine .text-Sektion.")
    raw_size,raw_ptr,rel_ptr,rel_count=text; code=payload[raw_ptr:raw_ptr+raw_size]
    st_off=sym_ptr+sym_count*18
    if st_off+4>len(payload): raise PE64AssemblerError("COFF64-Symboltabelle ist beschädigt.")
    st_size=struct.unpack_from("<I",payload,st_off)[0]; st=payload[st_off:st_off+max(4,st_size)]
    names=[]; symbols={}; i=0
    while i<sym_count:
        off=sym_ptr+i*18; raw_name=payload[off:off+8]; zeroes,so=struct.unpack("<II",raw_name)
        if zeroes==0 and so:
            end=st.find(b"\0",so); end=len(st) if end<0 else end; name=st[so:end].decode("utf-8",errors="replace")
        else: name=raw_name.rstrip(b"\0").decode("ascii",errors="replace")
        value,sec,_type,_storage,aux=struct.unpack_from("<IhHBB",payload,off+8); key=name.casefold(); names.append(key); symbols[key]=int(value) if sec==1 else None
        for _ in range(aux): i+=1; names.append("")
        i+=1
    rels=[]
    for j in range(rel_count):
        off=rel_ptr+j*10
        if off+10>len(payload): raise PE64AssemblerError("COFF64-Relocationstabelle ist beschädigt.")
        va,si,rt=struct.unpack_from("<IIH",payload,off)
        if si>=len(names): raise PE64AssemblerError("COFF64-Relocation verweist auf ungültiges Symbol.")
        rels.append(PE64Relocation(va,names[si],rt))
    imports={}; exports={}; dll_name=None
    if meta.strip():
        try: doc=json.loads(meta.decode("ascii"))
        except Exception as exc: raise PE64AssemblerError("COFF64-.drectve enthält ungültige Metadaten.") from exc
        if isinstance(doc,dict) and doc.get("format")=="d64-coff64-link-v1":
            for symbol,spec in (doc.get("imports") or {}).items():
                if isinstance(spec,dict) and spec.get("dll") and spec.get("member"): imports[str(symbol).casefold()]=(str(spec["dll"]),str(spec["member"]))
            for public,internal in (doc.get("exports") or {}).items(): exports[str(public)]=str(internal).casefold()
            if doc.get("dll_name"): dll_name=str(doc["dll_name"])
    return Coff64ParsedObject(code,symbols,tuple(rels),imports,exports,dll_name)


def create_coff64_archive(members: Sequence[Tuple[str, bytes]]) -> bytes:
    return create_coff32_archive(members)


def parse_coff64_archive(data: bytes) -> Tuple[Tuple[str, bytes], ...]:
    return parse_coff32_archive(data)


# Windows-x64-Signaturen fuer die Stack->Microsoft-x64-Adapterthunks des
# compilerinternen Runtime-ABIs. True = Aufrufer bereinigt (cdecl/variadic).
PE64_IMPORT_SIGNATURES: Dict[str, Tuple[int, bool]] = {
    "exitprocess":(1,False), "allocconsole":(0,False), "getstdhandle":(1,False),
    "setconsolescreenbuffersize":(2,False), "setconsolewindowinfo":(3,False),
    "getconsolemode":(2,False), "setconsolemode":(2,False), "writefile":(5,False),
    "readfile":(5,False), "createfilea":(7,False), "lstrlena":(1,False),
    "getmodulehandlea":(1,False), "getprocaddress":(2,False), "loadlibrarya":(1,False),
    "getcommandlinea":(0,False), "getprocessheap":(0,False), "heapalloc":(3,False),
    "heapfree":(3,False), "virtualalloc":(4,False), "virtualfree":(3,False),
    "sleep":(1,False), "wsprintfa":(3,True),
    "registerclassexa":(1,False), "createwindowexa":(12,False), "defwindowproca":(4,False),
    "destroywindow":(1,False), "showwindow":(2,False), "updatewindow":(1,False),
    "peekmessagea":(5,False), "translatemessage":(1,False), "dispatchmessagea":(1,False),
    "loadcursora":(2,False), "postquitmessage":(1,False), "getclientrect":(2,False),
    "messageboxa":(4,False), "d2d1createfactory":(3,False), "direct3dcreate9":(1,False),
    "printf":(1,True),
}


def _build_pe64_import_section(import_specs: Dict[str, Tuple[str,str]], idata_rva: int):
    grouped={}
    for _symbol,(dll,func) in import_specs.items():
        funcs=grouped.setdefault(dll,[])
        if func not in funcs: funcs.append(func)
    if not grouped: return b"",{},0,0
    items=list(grouped.items()); data=bytearray(20*(len(items)+1)); ilt={}; iat={}; hints={}; names={}
    for dll,funcs in items: ilt[dll]=len(data); data.extend(bytes(8*(len(funcs)+1)))
    for dll,funcs in items: iat[dll]=len(data); data.extend(bytes(8*(len(funcs)+1)))
    for dll,funcs in items:
        for func in funcs:
            if len(data)&1: data.append(0)
            hints[(dll,func)]=len(data); data.extend(struct.pack("<H",0)); data.extend(func.encode("ascii")+b"\0")
    for dll,_ in items: names[dll]=len(data); data.extend(dll.encode("ascii")+b"\0")
    spec_iat={}; first=0; total=0
    for di,(dll,funcs) in enumerate(items):
        ilt_rva=idata_rva+ilt[dll]; iat_rva=idata_rva+iat[dll]; first=first or iat_rva; total += 8*(len(funcs)+1)
        struct.pack_into("<IIIII",data,di*20,ilt_rva,0,0,idata_rva+names[dll],iat_rva)
        for fi,func in enumerate(funcs):
            hint=idata_rva+hints[(dll,func)]; struct.pack_into("<Q",data,ilt[dll]+fi*8,hint); struct.pack_into("<Q",data,iat[dll]+fi*8,hint); spec_iat[(dll,func)]=iat_rva+fi*8
    return bytes(data),{symbol:spec_iat[spec] for symbol,spec in import_specs.items()},first,total


def _build_pe64_reloc_section(rvas: Sequence[int]) -> bytes:
    pages={}
    for rva in sorted({int(x) for x in rvas if int(x)>=0}): pages.setdefault(rva&~0xFFF,[]).append(rva&0xFFF)
    out=bytearray()
    for page,offs in sorted(pages.items()):
        entries=[(10<<12)|off for off in offs]  # IMAGE_REL_BASED_DIR64
        size=8+2*len(entries)
        if size&3: entries.append(0); size+=2
        out.extend(struct.pack("<II",page,size)); [out.extend(struct.pack("<H",e)) for e in entries]
    return bytes(out)


def build_pe64_image_with_imports_exports(code: bytes, entry_offset: Optional[int], import_specs: Dict[str,Tuple[str,str]], iat_call_patches: Dict[str,List[int]], *, exports=None, dll_name="library.dll", gui=False, dll=False, image_base=PE64_IMAGE_BASE, base_relocations=()):
    text=bytearray(code); text_rva=PE64_SECTION_RVA; next_rva=_align_up(text_rva+max(1,len(text)),PE64_SECTION_ALIGNMENT)
    idata=b""; iat_rvas={}; first_iat=0; iat_size=0; idata_rva=0
    if import_specs:
        idata_rva=next_rva; idata,iat_rvas,first_iat,iat_size=_build_pe64_import_section(import_specs,idata_rva); next_rva=_align_up(idata_rva+max(1,len(idata)),PE64_SECTION_ALIGNMENT)
    for symbol,patches in iat_call_patches.items():
        if symbol not in iat_rvas: raise PE64AssemblerError(f"PE64-IAT-Eintrag fehlt: {symbol}")
        for patch in patches:
            # patch zeigt auf disp32 eines RIP-relativen CALL/JMP [RIP+disp32]
            instruction_end=text_rva+patch+4; disp=iat_rvas[symbol]-instruction_end; struct.pack_into("<i",text,patch,disp)
    export_offsets=dict(exports or {}); edata=b""; edata_rva=0
    if export_offsets:
        edata_rva=next_rva; edata=_build_pe32_export_section(export_offsets,dll_name,edata_rva,text_rva); next_rva=_align_up(edata_rva+max(1,len(edata)),PE64_SECTION_ALIGNMENT)
    reloc=b""; reloc_rva=0
    if base_relocations:
        reloc_rva=next_rva; reloc=_build_pe64_reloc_section(base_relocations); next_rva=_align_up(reloc_rva+max(1,len(reloc)),PE64_SECTION_ALIGNMENT)
    sections=[(b".text\0\0\0",bytes(text),text_rva,0xE0000020)]
    if idata: sections.append((b".idata\0\0",idata,idata_rva,0xC0000040))
    if edata: sections.append((b".edata\0\0",edata,edata_rva,0x40000040))
    if reloc: sections.append((b".reloc\0\0",reloc,reloc_rva,0x42000040))
    headers_unaligned=0x80+4+20+0xF0+40*len(sections); headers_size=_align_up(headers_unaligned,PE64_FILE_ALIGNMENT); raw_ptr=headers_size; layout=[]; code_size=0; data_size=0
    for name,data,rva,chars in sections:
        raw_size=_align_up(len(data),PE64_FILE_ALIGNMENT); layout.append((name,data,rva,chars,raw_ptr,raw_size)); raw_ptr+=raw_size; code_size += raw_size if name.startswith(b".text") else 0; data_size += 0 if name.startswith(b".text") else raw_size
    image_size=_align_up(next_rva,PE64_SECTION_ALIGNMENT)
    dos=bytearray(0x80); dos[:2]=b"MZ"; struct.pack_into("<I",dos,0x3C,0x80)
    pe=bytearray(b"PE\0\0"); chars=0x0022|(0x2000 if dll else 0); pe.extend(struct.pack("<HHIIIHH",IMAGE_FILE_MACHINE_AMD64,len(sections),0,0,0,0xF0,chars))
    opt=bytearray(0xF0); struct.pack_into("<H",opt,0,0x020B); opt[2]=1; struct.pack_into("<I",opt,4,code_size); struct.pack_into("<I",opt,8,data_size); struct.pack_into("<I",opt,0x10,0 if entry_offset is None else text_rva+int(entry_offset)); struct.pack_into("<I",opt,0x14,text_rva); struct.pack_into("<Q",opt,0x18,int(image_base)); struct.pack_into("<I",opt,0x20,PE64_SECTION_ALIGNMENT); struct.pack_into("<I",opt,0x24,PE64_FILE_ALIGNMENT); struct.pack_into("<HHHH",opt,0x28,6,0,0,0); struct.pack_into("<HH",opt,0x30,6,0); struct.pack_into("<I",opt,0x38,image_size); struct.pack_into("<I",opt,0x3C,headers_size); struct.pack_into("<H",opt,0x44,2 if gui else 3); struct.pack_into("<H",opt,0x46,0x0160); struct.pack_into("<QQQQ",opt,0x48,0x400000,0x4000,0x100000,0x2000); struct.pack_into("<II",opt,0x68,0,16)
    if edata: struct.pack_into("<II",opt,0x70,edata_rva,len(edata))
    if idata: struct.pack_into("<II",opt,0x78,idata_rva,len(idata)); struct.pack_into("<II",opt,0xD0,first_iat,iat_size)
    if reloc: struct.pack_into("<II",opt,0x98,reloc_rva,len(reloc))
    pe.extend(opt)
    for name,data,rva,schars,rptr,rsize in layout:
        sh=bytearray(40); sh[:8]=name[:8].ljust(8,b"\0"); struct.pack_into("<I",sh,8,len(data)); struct.pack_into("<I",sh,0x0C,rva); struct.pack_into("<I",sh,0x10,rsize); struct.pack_into("<I",sh,0x14,rptr); struct.pack_into("<I",sh,0x24,schars); pe.extend(sh)
    headers=bytes(dos)+bytes(pe); headers += bytes(headers_size-len(headers)); image=bytearray(headers)
    for _n,data,_r,_c,_p,rsize in layout: image.extend(data); image.extend(bytes(rsize-len(data)))
    return bytes(image),bytes(text)


def _pe64_import_adapter_bytes(arg_count: int, caller_cleanup: bool):
    """Stack-ABI des Compilers -> Microsoft x64 ABI. Return (code, iat_disp_offset)."""
    n=max(0,int(arg_count)); out=bytearray(b"\x55\x48\x89\xE5\x48\x83\xE4\xF0")  # push rbp; mov rbp,rsp; and rsp,-16
    stack_args=max(0,n-4); reserve=_align_up(32+stack_args*8,16)
    if reserve<=127: out.extend(b"\x48\x83\xEC"+bytes((reserve,)))
    else: out.extend(b"\x48\x81\xEC"+struct.pack("<I",reserve))
    loads=[b"\x48\x8B\x4D",b"\x48\x8B\x55",b"\x4C\x8B\x45",b"\x4C\x8B\x4D"]
    for i in range(min(n,4)):
        disp=16+i*8
        if disp<=127: out.extend(loads[i]+bytes((disp,)))
        else: raise PE64AssemblerError("Zu viele Stackparameter im PE64-Adapter.")
    for i in range(4,n):
        src=16+i*8; dst=32+(i-4)*8
        # mov rax,[rbp+src]
        if src<=127: out.extend(b"\x48\x8B\x45"+bytes((src,)))
        else: out.extend(b"\x48\x8B\x85"+struct.pack("<i",src))
        # mov [rsp+dst],rax
        if dst<=127: out.extend(b"\x48\x89\x44\x24"+bytes((dst,)))
        else: out.extend(b"\x48\x89\x84\x24"+struct.pack("<i",dst))
    out.extend(b"\xFF\x15"); patch=len(out); out.extend(b"\0\0\0\0")
    out.extend(b"\x48\x89\xEC\x5D")
    if caller_cleanup: out.append(0xC3)
    elif n: out.extend(b"\xC2"+struct.pack("<H",n*8))
    else: out.append(0xC3)
    return bytes(out),patch


def link_coff64_objects(objects: Sequence[bytes], *, entry_symbol="_start", gui=False, dll=False, imports=None, exports=None, dll_name=None) -> PE64Program:
    parsed=[parse_coff64_object(x) for x in objects]; code=bytearray(); bases=[]; globals_map={}; declared_imports={}; declared_exports={}; declared_dll=None
    for obj in parsed:
        declared_imports.update(obj.imports); declared_exports.update(obj.exports); declared_dll=obj.dll_name or declared_dll
    for s,v in (imports or {}).items(): declared_imports[str(s).casefold()]=(str(v[0]),str(v[1]))
    for p,i in (exports or {}).items(): declared_exports[str(p)]=str(i).casefold()
    if dll_name: declared_dll=str(dll_name)
    effective_dll=bool(dll or declared_exports); image_base=PE64_DLL_IMAGE_BASE if effective_dll else PE64_IMAGE_BASE; base_relocs=[]
    for obj in parsed:
        base=_align_up(len(code),16); code.extend(bytes(base-len(code))); bases.append(base); code.extend(obj.code)
        for name,value in obj.symbols.items():
            if value is None: continue
            if name in globals_map: raise PE64AssemblerError(f"COFF64-Symbol mehrfach definiert: {name}")
            globals_map[name]=base+value
    import_specs={}; iat_patches={}; unresolved=[]
    # Alle noch externen Symbole erhalten entweder einen Stackadapter fuer die
    # Compiler-Runtime oder einen direkten JMP-[RIP+IAT]-Thunk.
    external_names=[]
    for obj in parsed:
        for r in obj.relocations:
            s=r.symbol.casefold()
            if s not in globals_map and s not in external_names: external_names.append(s)
    for symbol in external_names:
        alias_match = re.fullmatch(r"__d64_argc(\d+)__(.+)", symbol, re.IGNORECASE)
        original_symbol = alias_match.group(2).casefold() if alias_match else symbol
        spec=(
            declared_imports.get(symbol)
            or declared_imports.get(original_symbol)
            or _resolve_pe32_default_import(original_symbol)
        )
        if spec is None: unresolved.append(symbol); continue
        start=_align_up(len(code),16); code.extend(bytes(start-len(code)))
        if alias_match:
            sig=(int(alias_match.group(1)), False)
        else:
            sig=PE64_IMPORT_SIGNATURES.get(original_symbol)
        if sig is not None:
            thunk,local_patch=_pe64_import_adapter_bytes(*sig); code.extend(thunk); iat_patches.setdefault(symbol,[]).append(start+local_patch)
        else:
            # Direkter Win64-ABI-Thunk fuer handgeschriebenen PE64-Assembler.
            code.extend(b"\xFF\x25\0\0\0\0"); iat_patches.setdefault(symbol,[]).append(start+2)
        globals_map[symbol]=start; import_specs[symbol]=spec
    if unresolved: raise PE64AssemblerError("COFF64-Linker: externe Symbole nicht aufgeloest: "+", ".join(unresolved))
    for obj,base in zip(parsed,bases):
        for r in obj.relocations:
            target=globals_map.get(r.symbol.casefold())
            if target is None: raise PE64AssemblerError(f"COFF64-Symbol nicht aufgeloest: {r.symbol}")
            patch=base+r.offset
            if IMAGE_REL_AMD64_REL32 <= r.relocation_type <= IMAGE_REL_AMD64_REL32_5:
                tail = r.relocation_type - IMAGE_REL_AMD64_REL32
                struct.pack_into("<i", code, patch, target - (patch + 4 + tail))
            elif r.relocation_type==IMAGE_REL_AMD64_ADDR64:
                struct.pack_into("<Q",code,patch,image_base+PE64_SECTION_RVA+target); base_relocs.append(PE64_SECTION_RVA+patch)
            elif r.relocation_type==IMAGE_REL_AMD64_ADDR32: struct.pack_into("<I",code,patch,(image_base+PE64_SECTION_RVA+target)&0xFFFFFFFF)
            else: raise PE64AssemblerError(f"COFF64-Relocation 0x{r.relocation_type:04X} nicht unterstützt.")
    wanted=str(entry_symbol or "").casefold(); entry=globals_map.get(wanted)
    if entry is None and not effective_dll:
        for fallback in ("_start","start","main","_main"):
            if fallback in globals_map: entry=globals_map[fallback]; break
    if entry is None and not effective_dll: entry=0
    export_offsets={}
    for public,internal in declared_exports.items():
        if internal.casefold() not in globals_map: raise PE64AssemblerError(f"DLL-Export {public} verweist auf unbekanntes Symbol {internal}.")
        export_offsets[public]=globals_map[internal.casefold()]
    effective_dll=bool(effective_dll or export_offsets); final_name=declared_dll or "library.dll"
    image,patched=build_pe64_image_with_imports_exports(bytes(code),entry,import_specs,iat_patches,exports=export_offsets,dll_name=final_name,gui=gui,dll=effective_dll,image_base=image_base,base_relocations=base_relocs)
    return PE64Program(image,patched,int(entry or 0),0,globals_map)


def link_coff64_inputs(paths: Sequence[Path], *, entry_symbol="_start", gui=False, dll=False, imports=None, exports=None, dll_name=None) -> PE64Program:
    objects = _coff_link_input_objects(paths, target="pe64", required_symbols=(entry_symbol,))
    if not objects: raise PE64AssemblerError("Der COFF64-Linker benötigt mindestens ein Objekt.")
    return link_coff64_objects(objects,entry_symbol=entry_symbol,gui=gui,dll=dll,imports=imports,exports=exports,dll_name=dll_name)


def assemble_pe64_source(source: str, *, filename="<PE64-Assembler>", gui=False) -> PE64Program:
    obj=assemble_pe64_object_source(source,filename=filename)
    return link_coff64_objects((write_coff64_object(obj),),entry_symbol=obj.entry_symbol or "_start",gui=gui)


# ---------------------------------------------------------------------------
# PE64 section model v2
# ---------------------------------------------------------------------------
# PE64 uses real, separate COFF/PE sections now:
#   .text = code, READ|EXECUTE
#   .data = initialized runtime/program data, READ|WRITE
# This deliberately replaces the earlier temporary RWX single-section model.

@dataclass(frozen=True)
class PE64Relocation:
    offset: int
    symbol: str
    relocation_type: int
    section: str = ".text"


@dataclass(frozen=True)
class PE64ObjectProgram:
    code: bytes
    symbols: Dict[str, int]
    externals: Tuple[str, ...]
    relocations: Tuple[PE64Relocation, ...]
    entry_symbol: str = "_start"
    imports: Dict[str, Tuple[str, str]] = field(default_factory=dict)
    exports: Dict[str, str] = field(default_factory=dict)
    dll_name: Optional[str] = None
    data: bytes = b""
    bss_size: int = 0
    symbol_sections: Dict[str, str] = field(default_factory=dict)


@dataclass(frozen=True)
class Coff64ParsedObject:
    code: bytes
    symbols: Dict[str, Optional[int]]
    relocations: Tuple[PE64Relocation, ...]
    imports: Dict[str, Tuple[str, str]] = field(default_factory=dict)
    exports: Dict[str, str] = field(default_factory=dict)
    dll_name: Optional[str] = None
    data: bytes = b""
    bss_size: int = 0
    symbol_sections: Dict[str, str] = field(default_factory=dict)


def _pe64_section_from_directive(directive: str, args: str, current: str, line: int) -> Optional[str]:
    key = str(directive).strip().casefold().lstrip(".")
    if key in {"text", "code"}:
        return ".text"
    if key == "data":
        return ".data"
    if key in {"bss", "uninitialized"}:
        return ".bss"
    if key != "section":
        return None
    token = str(args or "").strip().split(",", 1)[0].split(None, 1)[0].casefold()
    token = token.lstrip(".")
    if token in {"text", "code"}:
        return ".text"
    if token in {"data", "rdata"}:
        # rdata is kept in writable .data for now because some generated
        # runtime structures are initialized there.
        return ".data"
    if token in {"bss", "uninitialized"}:
        return ".bss"
    raise PE64AssemblerError(f"PE64-Sektion nicht unterstützt: {args}", line)


def _parse_pe64_source(source: str):
    lines = []
    labels: Dict[str, int] = {}
    symbol_sections: Dict[str, str] = {}
    externals = set()
    imports = {}
    exports = {}
    dll_name = None
    entry = "_start"
    current = ".text"
    offsets = {".text": 0, ".data": 0, ".bss": 0}

    for line_no, raw in enumerate(str(source).splitlines(), 1):
        text = _x86_strip_comment(raw)
        if not text:
            continue
        while True:
            m = re.match(r"^([A-Za-z_.$?@][A-Za-z0-9_.$?@]*)\s*:\s*(.*)$", text)
            if not m:
                break
            key = m.group(1).casefold()
            if key in labels:
                raise PE64AssemblerError(f"Symbol mehrfach definiert: {m.group(1)}", line_no)
            labels[key] = offsets[current]
            symbol_sections[key] = current
            text = m.group(2).strip()
            if not text:
                break
        if not text:
            continue

        parts = text.split(None, 1)
        directive = parts[0].casefold().lstrip(".")
        args = parts[1].strip() if len(parts) > 1 else ""
        new_section = _pe64_section_from_directive(directive, args, current, line_no)
        if new_section is not None:
            current = new_section
            lines.append((line_no, text, current))
            continue
        if directive in {"global", "globl", "public", "bits", "cpu", "model"}:
            lines.append((line_no, text, current))
            continue
        if directive in {"extern", "extrn"}:
            for item in _x86_split_operands(args):
                if item:
                    externals.add(item.strip().casefold())
            lines.append((line_no, text, current))
            continue
        if directive == "import":
            ops = _x86_split_operands(args)
            if len(ops) not in {2, 3}:
                raise PE64AssemblerError('IMPORT erwartet: import symbol, "dll", "member"', line_no)
            symbol = _pe32_unquote(ops[0]).strip()
            dll = _pe32_unquote(ops[1]).strip()
            member = _pe32_unquote(ops[2]).strip() if len(ops) == 3 else symbol
            imports[symbol.casefold()] = (dll, member)
            externals.add(symbol.casefold())
            lines.append((line_no, text, current))
            continue
        if directive == "export":
            ops = _x86_split_operands(args)
            if len(ops) not in {1, 2}:
                raise PE64AssemblerError("EXPORT erwartet public_name [, internal_symbol]", line_no)
            public = _pe32_unquote(ops[0]).strip()
            internal = _pe32_unquote(ops[1]).strip() if len(ops) == 2 else public
            exports[public] = internal.casefold()
            lines.append((line_no, text, current))
            continue
        if directive == "dllname":
            dll_name = _pe32_unquote(args)
            lines.append((line_no, text, current))
            continue
        if directive == "entry":
            entry = args.split()[0]
            lines.append((line_no, text, current))
            continue
        if directive == "align":
            align = _x86_parse_int(args)
            if align is None or align <= 0 or align & (align - 1):
                raise PE64AssemblerError("ALIGN erwartet eine Zweierpotenz.", line_no)
            offsets[current] = _align_up(offsets[current], align)
            lines.append((line_no, text, current))
            continue
        reserve_unit = {"resb": 1, "rb": 1, "resw": 2, "rw": 2,
                        "resd": 4, "rd": 4, "resq": 8, "rq": 8}.get(directive)
        if reserve_unit is not None:
            if current != ".bss":
                raise PE64AssemblerError(f"{directive.upper()} ist nur in .bss erlaubt.", line_no)
            count = _x86_parse_int(args)
            if count is None or count < 0:
                raise PE64AssemblerError(f"{directive.upper()} erwartet eine nichtnegative Anzahl.", line_no)
            offsets[current] += int(count) * reserve_unit
            lines.append((line_no, text, current))
            continue
        if directive in {"db", "byte"}:
            if current == ".bss":
                raise PE64AssemblerError("Initialisierte Daten sind in .bss nicht erlaubt; RESB/RESW/RESD/RESQ verwenden.", line_no)
            offsets[current] += len(_x86_data_values(args, line_no, 1))
            lines.append((line_no, text, current))
            continue
        if directive in {"dw", "word"}:
            if current == ".bss":
                raise PE64AssemblerError("Initialisierte Daten sind in .bss nicht erlaubt.", line_no)
            offsets[current] += 2 * len(_x86_split_operands(args))
            lines.append((line_no, text, current))
            continue
        if directive in {"dd", "dword", "long"}:
            if current == ".bss":
                raise PE64AssemblerError("Initialisierte Daten sind in .bss nicht erlaubt.", line_no)
            offsets[current] += 4 * len(_x86_split_operands(args))
            lines.append((line_no, text, current))
            continue
        if directive in {"dq", "qword"}:
            if current == ".bss":
                raise PE64AssemblerError("Initialisierte Daten sind in .bss nicht erlaubt.", line_no)
            offsets[current] += 8 * len(_x86_split_operands(args))
            lines.append((line_no, text, current))
            continue
        if current != ".text":
            raise PE64AssemblerError(
                f"Ausführbarer AMD64-Befehl ist in {current} nicht erlaubt: {text}", line_no
            )
        encoded = _encode_pe64_instruction(text, line_no, offsets[current], relocs=[])
        offsets[current] += len(encoded)
        lines.append((line_no, text, current))

    return (
        lines, labels, symbol_sections, entry, tuple(sorted(externals)),
        imports, exports, dll_name, int(offsets[".bss"]),
    )


def assemble_pe64_object_source(source: str, *, filename: str = "<PE64-Assembler>") -> PE64ObjectProgram:
    del filename
    lines, labels, symbol_sections, entry, externals, imports, exports, dll_name, bss_size = _parse_pe64_source(source)
    buffers = {".text": bytearray(), ".data": bytearray(), ".bss": bytearray()}
    relocs: List[PE64Relocation] = []

    for line_no, text, section in lines:
        parts = text.split(None, 1)
        directive = parts[0].casefold().lstrip(".")
        args = parts[1].strip() if len(parts) > 1 else ""
        if _pe64_section_from_directive(directive, args, section, line_no) is not None:
            continue
        if directive in {
            "global", "globl", "public", "bits", "cpu", "model", "extern", "extrn",
            "import", "export", "dllname", "entry",
        }:
            continue
        if directive in {"resb", "rb", "resw", "rw", "resd", "rd", "resq", "rq"}:
            continue
        out = buffers[section]
        if directive == "align":
            align = int(_x86_parse_int(args))
            out.extend(bytes(_align_up(len(out), align) - len(out)))
            continue
        unit = {
            "db": 1, "byte": 1, "dw": 2, "word": 2,
            "dd": 4, "dword": 4, "long": 4, "dq": 8, "qword": 8,
        }.get(directive)
        if unit:
            for token in _x86_split_operands(args):
                token = token.strip()
                if unit == 1 and len(token) >= 2 and token[0] in {'"', "'"} and token[-1] == token[0]:
                    decoded = ast.literal_eval(token)
                    out.extend(str(decoded).encode("latin-1", errors="replace"))
                    continue
                value = _x86_parse_int(token)
                if value is not None:
                    out.extend(int(value & ((1 << (unit * 8)) - 1)).to_bytes(unit, "little"))
                    continue
                if not _x64_is_symbol(token):
                    raise PE64AssemblerError(f"Numerischer Datenwert oder Symbol erwartet: {token}", line_no)
                patch = len(out)
                out.extend(bytes(unit))
                rel_type = IMAGE_REL_AMD64_ADDR64 if unit == 8 else IMAGE_REL_AMD64_ADDR32
                relocs.append(PE64Relocation(patch, token.casefold(), rel_type, section))
            continue
        if section != ".text":
            raise PE64AssemblerError(f"AMD64-Code darf nicht in {section} assembliert werden.", line_no)
        tmp: List[PE64Relocation] = []
        encoded = _encode_pe64_instruction(text, line_no, len(out), relocs=tmp)
        out.extend(encoded)
        relocs.extend(PE64Relocation(r.offset, r.symbol, r.relocation_type, section) for r in tmp)

    return PE64ObjectProgram(
        bytes(buffers[".text"]), dict(labels), externals, tuple(relocs), entry,
        dict(imports), dict(exports), dll_name,
        data=bytes(buffers[".data"]), bss_size=int(bss_size),
        symbol_sections=dict(symbol_sections),
    )


def write_coff64_object(obj: PE64ObjectProgram) -> bytes:
    names = list(obj.symbols.keys())
    for name in obj.externals:
        if name not in names:
            names.append(name)
    index = {name: i for i, name in enumerate(names)}
    metadata = _coff64_metadata_bytes(obj)
    text_relocs = [r for r in obj.relocations if r.section == ".text"]
    data_relocs = [r for r in obj.relocations if r.section == ".data"]

    section_defs = [
        {"name": b".text\0\0\0", "data": bytes(obj.code), "virtual_size": len(obj.code),
         "chars": 0x60500020, "relocs": text_relocs, "key": ".text"},
    ]
    if obj.data or any(v == ".data" for v in obj.symbol_sections.values()):
        section_defs.append(
            {"name": b".data\0\0\0", "data": bytes(obj.data), "virtual_size": len(obj.data),
             "chars": 0xC0500040, "relocs": data_relocs, "key": ".data"}
        )
    if int(getattr(obj, "bss_size", 0)) or any(v == ".bss" for v in obj.symbol_sections.values()):
        section_defs.append(
            {"name": b".bss\0\0\0\0", "data": b"", "virtual_size": int(getattr(obj, "bss_size", 0)),
             "chars": 0xC0500080, "relocs": [], "key": ".bss"}
        )
    if metadata:
        section_defs.append(
            {"name": b".drectve", "data": metadata, "virtual_size": len(metadata),
             "chars": 0x00100A00, "relocs": [], "key": ".drectve"}
        )

    section_numbers = {item["key"]: i + 1 for i, item in enumerate(section_defs)}
    header_size = 20 + len(section_defs) * 40
    cursor = header_size
    for item in section_defs:
        item["raw_ptr"] = cursor if item["data"] else 0
        cursor += len(item["data"])
    for item in section_defs:
        item["reloc_ptr"] = cursor if item["relocs"] else 0
        cursor += len(item["relocs"]) * 10
    sym_ptr = cursor

    header = struct.pack(
        "<HHIIIHH", IMAGE_FILE_MACHINE_AMD64, len(section_defs), 0,
        sym_ptr, len(names), 0, 0,
    )
    headers = bytearray()
    for item in section_defs:
        sh = bytearray(40)
        sh[:8] = item["name"][:8].ljust(8, b"\0")
        struct.pack_into("<I", sh, 0x08, int(item.get("virtual_size", len(item["data"]))))
        struct.pack_into("<I", sh, 0x10, len(item["data"]))
        struct.pack_into("<I", sh, 0x14, item["raw_ptr"])
        struct.pack_into("<I", sh, 0x18, item["reloc_ptr"])
        struct.pack_into("<H", sh, 0x20, len(item["relocs"]))
        struct.pack_into("<I", sh, 0x24, item["chars"])
        headers.extend(sh)

    raw = bytearray()
    for item in section_defs:
        raw.extend(item["data"])
    reloc_bytes = bytearray()
    for item in section_defs:
        for r in item["relocs"]:
            if r.symbol not in index:
                raise PE64AssemblerError(f"COFF64-Symbol fehlt: {r.symbol}")
            reloc_bytes.extend(struct.pack("<IIH", r.offset, index[r.symbol], r.relocation_type))

    strings = bytearray()
    syms = bytearray()
    for name in names:
        syms.extend(_coff_symbol_name_bytes(name, strings))
        defined = name in obj.symbols
        section_name = obj.symbol_sections.get(name, ".text") if defined else None
        sec_no = section_numbers.get(section_name, 0) if defined else 0
        syms.extend(struct.pack("<IhHBB", int(obj.symbols.get(name, 0)), sec_no, 0, 2, 0))
    st = struct.pack("<I", 4 + len(strings)) + bytes(strings)
    return header + bytes(headers) + bytes(raw) + bytes(reloc_bytes) + bytes(syms) + st


def parse_coff64_object(data: bytes) -> Coff64ParsedObject:
    payload = bytes(data)
    if len(payload) < 60:
        raise PE64AssemblerError("COFF64-Objekt ist zu klein.")
    machine, sections, _ts, sym_ptr, sym_count, opt, _chars = struct.unpack_from("<HHIIIHH", payload, 0)
    if machine != IMAGE_FILE_MACHINE_AMD64 or sections < 1 or opt != 0:
        raise PE64AssemblerError("Nur relocierbare AMD64-COFF-Objekte werden unterstützt.")

    section_info = []
    meta = b""
    text_data = b""
    init_data = b""
    bss_size = 0
    for i in range(sections):
        off = 20 + i * 40
        name = payload[off:off + 8].rstrip(b"\0")
        virtual_size = struct.unpack_from("<I", payload, off + 0x08)[0]
        raw_size, raw_ptr, rel_ptr = struct.unpack_from("<III", payload, off + 0x10)
        rel_count = struct.unpack_from("<H", payload, off + 0x20)[0]
        if raw_ptr and raw_ptr + raw_size > len(payload):
            raise PE64AssemblerError("COFF64-Sektion außerhalb der Datei.")
        key = name.decode("ascii", errors="replace")
        section_info.append((key, raw_size, raw_ptr, rel_ptr, rel_count))
        content = payload[raw_ptr:raw_ptr + raw_size] if raw_ptr else b""
        if name == b".text":
            text_data = content
        elif name == b".data":
            init_data = content
        elif name == b".bss":
            bss_size = int(virtual_size)
        elif name == b".drectve":
            meta = content
    if not any(item[0] == ".text" for item in section_info):
        raise PE64AssemblerError("COFF64-Objekt enthält keine .text-Sektion.")

    st_off = sym_ptr + sym_count * 18
    if st_off + 4 > len(payload):
        raise PE64AssemblerError("COFF64-Symboltabelle ist beschädigt.")
    st_size = struct.unpack_from("<I", payload, st_off)[0]
    st = payload[st_off:st_off + max(4, st_size)]

    names = []
    symbols: Dict[str, Optional[int]] = {}
    symbol_sections: Dict[str, str] = {}
    i = 0
    while i < sym_count:
        off = sym_ptr + i * 18
        raw_name = payload[off:off + 8]
        zeroes, so = struct.unpack("<II", raw_name)
        if zeroes == 0 and so:
            end = st.find(b"\0", so)
            end = len(st) if end < 0 else end
            name = st[so:end].decode("utf-8", errors="replace")
        else:
            name = raw_name.rstrip(b"\0").decode("ascii", errors="replace")
        value, sec, _type, _storage, aux = struct.unpack_from("<IhHBB", payload, off + 8)
        key = name.casefold()
        names.append(key)
        if sec > 0 and sec <= len(section_info):
            sec_name = section_info[sec - 1][0]
            if sec_name in {".text", ".data", ".bss"}:
                symbols[key] = int(value)
                symbol_sections[key] = sec_name
            else:
                symbols[key] = None
        else:
            symbols[key] = None
        for _ in range(aux):
            i += 1
            names.append("")
        i += 1

    rels: List[PE64Relocation] = []
    for sec_name, _raw_size, _raw_ptr, rel_ptr, rel_count in section_info:
        if sec_name not in {".text", ".data"}:
            continue
        for j in range(rel_count):
            off = rel_ptr + j * 10
            if off + 10 > len(payload):
                raise PE64AssemblerError("COFF64-Relocationstabelle ist beschädigt.")
            va, si, rt = struct.unpack_from("<IIH", payload, off)
            if si >= len(names):
                raise PE64AssemblerError("COFF64-Relocation verweist auf ungültiges Symbol.")
            rels.append(PE64Relocation(va, names[si], rt, sec_name))

    imports = {}
    exports = {}
    dll_name = None
    if meta.strip():
        try:
            doc = json.loads(meta.decode("ascii"))
        except Exception as exc:
            raise PE64AssemblerError("COFF64-.drectve enthält ungültige Metadaten.") from exc
        if isinstance(doc, dict) and doc.get("format") == "d64-coff64-link-v1":
            for symbol, spec in (doc.get("imports") or {}).items():
                if isinstance(spec, dict) and spec.get("dll") and spec.get("member"):
                    imports[str(symbol).casefold()] = (str(spec["dll"]), str(spec["member"]))
            for public, internal in (doc.get("exports") or {}).items():
                exports[str(public)] = str(internal).casefold()
            if doc.get("dll_name"):
                dll_name = str(doc["dll_name"])

    return Coff64ParsedObject(
        text_data, symbols, tuple(rels), imports, exports, dll_name,
        data=init_data, bss_size=int(bss_size), symbol_sections=symbol_sections,
    )


def build_pe64_image_with_imports_exports(
    code: bytes,
    entry_offset: Optional[int],
    import_specs: Dict[str, Tuple[str, str]],
    iat_call_patches: Dict[str, List[int]],
    *, exports=None, dll_name="library.dll", gui=False, dll=False,
    image_base=PE64_IMAGE_BASE, base_relocations=(), data: bytes = b"",
    bss_size: int = 0,
):
    """Build a compact, standard PE32+ image with RX/RW/BSS separation.

    We keep the standard 0xF0-byte PE32+ optional header and all 16 data
    directories for loader compatibility.  Space is saved by using only the
    mandatory 64-byte DOS header (e_lfanew=0x40) and by storing imports,
    exports and base-relocation blocks in one linker-data section.  Therefore
    the normal image has at most four section headers and the complete header
    fits into one 0x200-byte FileAlignment block.
    """
    text = bytearray(code)
    init_data = bytes(data or b"")
    bss_size = max(0, int(bss_size or 0))

    text_rva = PE64_SECTION_RVA
    next_rva = _align_up(text_rva + max(1, len(text)), PE64_SECTION_ALIGNMENT)
    data_rva = 0
    if init_data:
        data_rva = next_rva
        next_rva = _align_up(data_rva + max(1, len(init_data)), PE64_SECTION_ALIGNMENT)
    bss_rva = 0
    if bss_size:
        bss_rva = next_rva
        next_rva = _align_up(bss_rva + max(1, bss_size), PE64_SECTION_ALIGNMENT)

    export_offsets = dict(exports or {})
    link_data = bytearray()
    link_rva = 0
    idata_rva = 0
    idata_size = 0
    edata_rva = 0
    edata_size = 0
    reloc_rva = 0
    reloc_size = 0
    iat_rvas = {}
    first_iat = 0
    iat_size = 0

    if import_specs or export_offsets or base_relocations:
        link_rva = next_rva
        if import_specs:
            idata_rva = link_rva + len(link_data)
            idata, iat_rvas, first_iat, iat_size = _build_pe64_import_section(import_specs, idata_rva)
            idata_size = len(idata)
            link_data.extend(idata)
        if export_offsets:
            pad = _align_up(len(link_data), 8) - len(link_data)
            link_data.extend(bytes(pad))
            edata_rva = link_rva + len(link_data)
            edata = _build_pe32_export_section(export_offsets, dll_name, edata_rva, text_rva)
            edata_size = len(edata)
            link_data.extend(edata)
        if base_relocations:
            pad = _align_up(len(link_data), 4) - len(link_data)
            link_data.extend(bytes(pad))
            reloc_rva = link_rva + len(link_data)
            reloc = _build_pe64_reloc_section(base_relocations)
            reloc_size = len(reloc)
            link_data.extend(reloc)
        next_rva = _align_up(link_rva + max(1, len(link_data)), PE64_SECTION_ALIGNMENT)

    for symbol, patches in iat_call_patches.items():
        if symbol not in iat_rvas:
            raise PE64AssemblerError(f"PE64-IAT-Eintrag fehlt: {symbol}")
        for patch in patches:
            instruction_end = text_rva + patch + 4
            disp = iat_rvas[symbol] - instruction_end
            struct.pack_into("<i", text, patch, disp)

    sections = [
        {"name": b".text\0\0\0", "data": bytes(text), "virtual_size": len(text),
         "rva": text_rva, "chars": 0x60000020, "raw": True},
    ]
    if init_data:
        sections.append({"name": b".data\0\0\0", "data": init_data, "virtual_size": len(init_data),
                         "rva": data_rva, "chars": 0xC0000040, "raw": True})
    if bss_size:
        sections.append({"name": b".bss\0\0\0\0", "data": b"", "virtual_size": bss_size,
                         "rva": bss_rva, "chars": 0xC0000080, "raw": False})
    if link_data:
        if import_specs:
            link_name = b".idata\0\0"
            link_chars = 0xC0000040
        elif export_offsets:
            link_name = b".edata\0\0"
            link_chars = 0x40000040
        else:
            link_name = b".reloc\0\0"
            link_chars = 0x42000040
        sections.append({"name": link_name, "data": bytes(link_data), "virtual_size": len(link_data),
                         "rva": link_rva, "chars": link_chars, "raw": True})

    dos_size = 0x40
    optional_size = 0xF0
    directory_count = 16
    headers_unaligned = dos_size + 4 + 20 + optional_size + 40 * len(sections)
    headers_size = _align_up(headers_unaligned, PE64_FILE_ALIGNMENT)

    raw_ptr = headers_size
    layout = []
    code_size = 0
    initialized_size = 0
    for sec in sections:
        if sec["raw"] and sec["data"]:
            raw_size = _align_up(len(sec["data"]), PE64_FILE_ALIGNMENT)
            rptr = raw_ptr
            raw_ptr += raw_size
        else:
            raw_size = 0
            rptr = 0
        item = dict(sec)
        item.update(raw_ptr=rptr, raw_size=raw_size)
        layout.append(item)
        if sec["name"].startswith(b".text"):
            code_size += raw_size
        elif sec["raw"]:
            initialized_size += raw_size

    image_size = _align_up(next_rva, PE64_SECTION_ALIGNMENT)

    dos = bytearray(dos_size)
    dos[:2] = b"MZ"
    struct.pack_into("<I", dos, 0x3C, dos_size)
    pe = bytearray(b"PE\0\0")
    chars = 0x0022 | (0x2000 if dll else 0)
    pe.extend(struct.pack("<HHIIIHH", IMAGE_FILE_MACHINE_AMD64, len(sections), 0, 0, 0, optional_size, chars))

    opt = bytearray(optional_size)
    struct.pack_into("<H", opt, 0, 0x020B)
    opt[2] = 1
    struct.pack_into("<I", opt, 4, code_size)
    struct.pack_into("<I", opt, 8, initialized_size)
    struct.pack_into("<I", opt, 0x0C, bss_size)
    struct.pack_into("<I", opt, 0x10, 0 if entry_offset is None else text_rva + int(entry_offset))
    struct.pack_into("<I", opt, 0x14, text_rva)
    struct.pack_into("<Q", opt, 0x18, int(image_base))
    struct.pack_into("<I", opt, 0x20, PE64_SECTION_ALIGNMENT)
    struct.pack_into("<I", opt, 0x24, PE64_FILE_ALIGNMENT)
    struct.pack_into("<HHHH", opt, 0x28, 6, 0, 0, 0)
    struct.pack_into("<HH", opt, 0x30, 6, 0)
    struct.pack_into("<I", opt, 0x38, image_size)
    struct.pack_into("<I", opt, 0x3C, headers_size)
    struct.pack_into("<H", opt, 0x44, 2 if gui else 3)
    struct.pack_into("<H", opt, 0x46, 0x0160)
    struct.pack_into("<QQQQ", opt, 0x48, 0x400000, 0x4000, 0x100000, 0x2000)
    struct.pack_into("<I", opt, 0x68, 0)
    struct.pack_into("<I", opt, 0x6C, directory_count)
    if edata_rva:
        struct.pack_into("<II", opt, 0x70, edata_rva, edata_size)
    if idata_rva:
        struct.pack_into("<II", opt, 0x78, idata_rva, idata_size)
        struct.pack_into("<II", opt, 0xD0, first_iat, iat_size)
    if reloc_rva:
        struct.pack_into("<II", opt, 0x98, reloc_rva, reloc_size)
    pe.extend(opt)

    for sec in layout:
        sh = bytearray(40)
        sh[:8] = sec["name"][:8].ljust(8, b"\0")
        struct.pack_into("<I", sh, 0x08, int(sec["virtual_size"]))
        struct.pack_into("<I", sh, 0x0C, int(sec["rva"]))
        struct.pack_into("<I", sh, 0x10, int(sec["raw_size"]))
        struct.pack_into("<I", sh, 0x14, int(sec["raw_ptr"]))
        struct.pack_into("<I", sh, 0x24, int(sec["chars"]))
        pe.extend(sh)

    headers = bytes(dos) + bytes(pe)
    if len(headers) > headers_size:
        raise PE64AssemblerError("PE64-Header überschreitet SizeOfHeaders.")
    image = bytearray(headers_size)
    image[:len(headers)] = headers
    for sec in layout:
        if not sec["raw_size"]:
            continue
        start = int(sec["raw_ptr"])
        end = start + len(sec["data"])
        if len(image) < start + int(sec["raw_size"]):
            image.extend(bytes(start + int(sec["raw_size"]) - len(image)))
        image[start:end] = sec["data"]
    return bytes(image), bytes(text)


# ---------------------------------------------------------------------------
# Stage 169: PE32+ / AMD64 MSZIP-Packer.
#
# Auch hier bleibt der vollständige Stage-167-PE32+-Writer oberhalb erhalten.
# Der Wrapper packt ausschließlich den bereits fertig gelinkten .text-Block.
# ---------------------------------------------------------------------------
PE64_TEXT_COMPRESSION_MSZIP_DEFAULT = (os.name == "nt")
PE64_MSZIP_LOADER_IMPORTS: Dict[str, Tuple[str, str]] = dict(
    PE32_MSZIP_LOADER_IMPORTS
)


class _PE64LoaderBuilder:
    def __init__(self, loader_rva: int) -> None:
        self.loader_rva = int(loader_rva)
        self.code = bytearray()
        self.labels: Dict[str, int] = {}
        self.local_fixups: List[Tuple[int, str]] = []
        self.rva_fixups: List[Tuple[int, int]] = []

    def emit(self, data: bytes) -> None:
        self.code.extend(data)

    def u32(self, value: int) -> None:
        self.code.extend(struct.pack("<I", int(value) & 0xFFFFFFFF))

    def u64(self, value: int) -> None:
        self.code.extend(struct.pack("<Q", int(value) & 0xFFFFFFFFFFFFFFFF))

    def label(self, name: str) -> None:
        key = str(name)
        if key in self.labels:
            raise PE64AssemblerError(f"PE64-Loaderlabel mehrfach definiert: {key}")
        self.labels[key] = len(self.code)

    def jcc(self, opcode2: int, label: str) -> None:
        self.code.extend(bytes((0x0F, int(opcode2) & 0xFF)))
        pos = len(self.code)
        self.code.extend(b"\x00\x00\x00\x00")
        self.local_fixups.append((pos, str(label)))

    def rip32(self, prefix: bytes, target_rva: int) -> None:
        self.code.extend(prefix)
        pos = len(self.code)
        self.code.extend(b"\x00\x00\x00\x00")
        self.rva_fixups.append((pos, int(target_rva)))

    def call_iat(self, iat_rva: int) -> None:
        self.rip32(b"\xFF\x15", iat_rva)

    def jmp_rva(self, target_rva: int) -> None:
        self.rip32(b"\xE9", target_rva)

    def finish(self) -> bytes:
        for pos, label in self.local_fixups:
            if label not in self.labels:
                raise PE64AssemblerError(f"PE64-Loaderlabel fehlt: {label}")
            disp = self.labels[label] - (pos + 4)
            if not -(1 << 31) <= disp < (1 << 31):
                raise PE64AssemblerError("PE64-Loader: lokaler Sprung außerhalb REL32.")
            struct.pack_into("<i", self.code, pos, disp)

        for pos, target_rva in self.rva_fixups:
            instruction_end_rva = self.loader_rva + pos + 4
            disp = int(target_rva) - instruction_end_rva
            if not -(1 << 31) <= disp < (1 << 31):
                raise PE64AssemblerError(
                    "PE64-Loader: RIP-relatives Ziel außerhalb des 32-Bit-Bereichs."
                )
            struct.pack_into("<i", self.code, pos, disp)
        return bytes(self.code)


def _build_pe64_mszip_loader(
    *,
    loader_rva: int,
    text_rva: int,
    text_size: int,
    ztext_rva: int,
    packed_size: int,
    original_entry_rva: int,
    iat_rvas: Dict[str, int],
) -> bytes:
    missing = [name for name in PE64_MSZIP_LOADER_IMPORTS if name not in iat_rvas]
    if missing:
        raise PE64AssemblerError(
            "PE32+-MSZIP-Loader: IAT-Einträge fehlen: " + ", ".join(missing)
        )

    text_size = int(text_size)
    packed_size = int(packed_size)
    if text_size <= 0 or packed_size <= 0:
        raise PE64AssemblerError("PE32+-MSZIP-Loader: ungültige Datenlänge.")
    if text_size > 0xFFFFFFFF or packed_size > 0xFFFFFFFF:
        raise PE64AssemblerError("PE32+-MSZIP-Loader: .text/.ztext ist größer als 4 GiB.")

    packed_rva = int(ztext_rva) + PE32_D64Z_HEADER_SIZE
    b = _PE64LoaderBuilder(loader_rva)

    # Win64 ABI: 32 Byte Shadow Space, Argumente 1..4 in RCX/RDX/R8/R9.
    # Lokale Variablen: handle, oldProtect, written, tempProtect.
    b.emit(b"\x55\x48\x89\xE5\x48\x83\xEC\x60")

    # CreateDecompressor(MSZIP, NULL, &handle)
    b.emit(b"\xB9")
    b.u32(PE32_COMPRESS_ALGORITHM_MSZIP)
    b.emit(b"\x31\xD2")
    b.emit(b"\x4C\x8D\x45\xF8")
    b.call_iat(iat_rvas["__d64_loader_CreateDecompressor"])
    b.emit(b"\x85\xC0")
    b.jcc(0x84, "fail")

    # VirtualProtect(.text, text_size, PAGE_EXECUTE_READWRITE, &oldProtect)
    b.rip32(b"\x48\x8D\x0D", text_rva)
    b.emit(b"\xBA")
    b.u32(text_size)
    b.emit(b"\x41\xB8")
    b.u32(0x40)
    b.emit(b"\x4C\x8D\x4D\xF0")
    b.call_iat(iat_rvas["__d64_loader_VirtualProtect"])
    b.emit(b"\x85\xC0")
    b.jcc(0x84, "fail")

    # Decompress(handle, packed, packed_size, text, text_size, &written)
    b.emit(b"\x48\x8B\x4D\xF8")
    b.rip32(b"\x48\x8D\x15", packed_rva)
    b.emit(b"\x41\xB8")
    b.u32(packed_size)
    b.rip32(b"\x4C\x8D\x0D", text_rva)
    b.emit(b"\x48\xB8")
    b.u64(text_size)
    b.emit(b"\x48\x89\x44\x24\x20")
    b.emit(b"\x48\x8D\x45\xE8")
    b.emit(b"\x48\x89\x44\x24\x28")
    b.call_iat(iat_rvas["__d64_loader_Decompress"])
    b.emit(b"\x85\xC0")
    b.jcc(0x84, "fail")

    b.emit(b"\x48\x8B\x45\xE8")
    b.emit(b"\x49\xBA")
    b.u64(text_size)
    b.emit(b"\x4C\x39\xD0")
    b.jcc(0x85, "fail")

    # CloseDecompressor(handle)
    b.emit(b"\x48\x8B\x4D\xF8")
    b.call_iat(iat_rvas["__d64_loader_CloseDecompressor"])

    # FlushInstructionCache((HANDLE)-1, .text, text_size)
    b.emit(b"\x48\xC7\xC1\xFF\xFF\xFF\xFF")
    b.rip32(b"\x48\x8D\x15", text_rva)
    b.emit(b"\x49\xB8")
    b.u64(text_size)
    b.call_iat(iat_rvas["__d64_loader_FlushInstructionCache"])

    # Seitenschutz wiederherstellen.
    b.rip32(b"\x48\x8D\x0D", text_rva)
    b.emit(b"\x48\xBA")
    b.u64(text_size)
    b.emit(b"\x44\x8B\x45\xF0")
    b.emit(b"\x4C\x8D\x4D\xE0")
    b.call_iat(iat_rvas["__d64_loader_VirtualProtect"])

    # Originalen Stack restaurieren und OEP per REL32 anspringen.
    b.emit(b"\x48\x89\xEC\x5D")
    b.jmp_rva(original_entry_rva)

    b.label("fail")
    b.emit(b"\xB9")
    b.u32(0xD6400002)
    b.call_iat(iat_rvas["__d64_loader_ExitProcess"])
    b.emit(b"\xCC")
    return b.finish()


def _pe64_rebuild_with_mszip_loader(
    stage167_image: bytes,
    patched_text: bytes,
    effective_import_specs: Dict[str, Tuple[str, str]],
    *,
    original_entry_rva: int,
) -> Tuple[bytes, bytes]:
    image = bytes(stage167_image)
    text = bytes(patched_text)
    if len(image) < 0x100 or image[:2] != b"MZ":
        raise PE64AssemblerError("PE32+-MSZIP: ungültiges MZ/PE-Image.")

    pe_offset = struct.unpack_from("<I", image, 0x3C)[0]
    if pe_offset + 24 > len(image) or image[pe_offset:pe_offset + 4] != b"PE\0\0":
        raise PE64AssemblerError("PE32+-MSZIP: PE-Signatur fehlt.")
    file_header = pe_offset + 4
    machine, section_count = struct.unpack_from("<HH", image, file_header)
    if machine != IMAGE_FILE_MACHINE_AMD64:
        raise PE64AssemblerError("PE32+-MSZIP: kein AMD64-PE-Image.")

    optional_size = struct.unpack_from("<H", image, file_header + 16)[0]
    optional_offset = file_header + 20
    if optional_offset + optional_size > len(image):
        raise PE64AssemblerError("PE32+-MSZIP: Optional Header abgeschnitten.")
    if struct.unpack_from("<H", image, optional_offset)[0] != 0x020B:
        raise PE64AssemblerError("PE32+-MSZIP: PE32+-Magic 0x20B fehlt.")

    section_alignment = struct.unpack_from("<I", image, optional_offset + 0x20)[0]
    file_alignment = struct.unpack_from("<I", image, optional_offset + 0x24)[0]
    section_table = optional_offset + optional_size
    if section_table + section_count * 40 > len(image):
        raise PE64AssemblerError("PE32+-MSZIP: Section-Tabelle abgeschnitten.")

    sections = []
    text_index = None
    for index in range(section_count):
        off = section_table + index * 40
        header = bytearray(image[off:off + 40])
        name = bytes(header[:8]).split(b"\0", 1)[0]
        virtual_size, rva, raw_size, raw_ptr = struct.unpack_from("<IIII", header, 0x08)
        chars = struct.unpack_from("<I", header, 0x24)[0]
        if raw_size:
            if raw_ptr <= 0 or raw_ptr + raw_size > len(image):
                raise PE64AssemblerError(
                    f"PE32+-MSZIP: Raw-Daten von {name!r} liegen außerhalb der Datei."
                )
            raw_block = bytes(image[raw_ptr:raw_ptr + raw_size])
        else:
            raw_block = b""
        if name == b".text":
            text_index = index
        sections.append({
            "header": header,
            "name": name,
            "virtual_size": int(virtual_size),
            "rva": int(rva),
            "chars": int(chars),
            "raw_block": raw_block,
            "raw_size": int(raw_size),
        })

    if text_index is None or not text:
        raise PE64AssemblerError("PE32+-MSZIP: .text fehlt oder ist leer.")
    text_section = sections[text_index]
    text_rva = int(text_section["rva"])

    import_rva, import_size = struct.unpack_from(
        "<II", image, optional_offset + 0x78
    )
    if import_rva <= 0 or import_size <= 0:
        raise PE64AssemblerError("PE32+-MSZIP: Importtabelle für Loader fehlt.")
    _idata, iat_rvas, _first_iat, _iat_size = _build_pe64_import_section(
        effective_import_specs,
        int(import_rva),
    )

    ztext, packed_size = _pe32_build_d64z_payload(
        text,
        text_rva=text_rva,
        original_entry_rva=int(original_entry_rva),
    )

    old_image_size = struct.unpack_from("<I", image, optional_offset + 0x38)[0]
    loader_rva = _align_up(max(int(old_image_size), 1), section_alignment)
    probe = _build_pe64_mszip_loader(
        loader_rva=loader_rva,
        text_rva=text_rva,
        text_size=len(text),
        ztext_rva=0,
        packed_size=packed_size,
        original_entry_rva=int(original_entry_rva),
        iat_rvas=iat_rvas,
    )
    ztext_rva = _align_up(loader_rva + max(1, len(probe)), section_alignment)
    loader = _build_pe64_mszip_loader(
        loader_rva=loader_rva,
        text_rva=text_rva,
        text_size=len(text),
        ztext_rva=ztext_rva,
        packed_size=packed_size,
        original_entry_rva=int(original_entry_rva),
        iat_rvas=iat_rvas,
    )

    text_section["raw_block"] = b""
    text_section["raw_size"] = 0
    text_section["virtual_size"] = max(1, len(text))

    sections.append({
        "header": None,
        "name": b".loader",
        "virtual_size": len(loader),
        "rva": loader_rva,
        "chars": 0x60000020,
        "raw_block": loader,
        "raw_size": _align_up(len(loader), file_alignment),
    })
    sections.append({
        "header": None,
        "name": b".ztext",
        "virtual_size": len(ztext),
        "rva": ztext_rva,
        "chars": 0x40000040,
        "raw_block": ztext,
        "raw_size": _align_up(len(ztext), file_alignment),
    })

    new_section_count = len(sections)
    new_headers_size = _align_up(
        section_table + new_section_count * 40,
        file_alignment,
    )
    raw_cursor = new_headers_size
    for sec in sections:
        raw_size = int(sec["raw_size"])
        if raw_size > 0:
            sec["raw_ptr"] = raw_cursor
            raw_cursor += raw_size
        else:
            sec["raw_ptr"] = 0

    rebuilt = bytearray(new_headers_size)
    rebuilt[:section_table] = image[:section_table]
    struct.pack_into("<H", rebuilt, file_header + 2, new_section_count)
    struct.pack_into("<I", rebuilt, optional_offset + 0x10, loader_rva)
    struct.pack_into(
        "<I",
        rebuilt,
        optional_offset + 0x38,
        _align_up(ztext_rva + max(1, len(ztext)), section_alignment),
    )
    struct.pack_into("<I", rebuilt, optional_offset + 0x3C, new_headers_size)

    size_of_code = 0
    size_of_initialized_data = 0
    for sec in sections:
        raw_size = int(sec["raw_size"])
        chars = int(sec["chars"])
        if chars & 0x00000020:
            size_of_code += raw_size
        elif chars & 0x00000040:
            size_of_initialized_data += raw_size
    struct.pack_into("<I", rebuilt, optional_offset + 0x04, size_of_code)
    struct.pack_into("<I", rebuilt, optional_offset + 0x08, size_of_initialized_data)

    for index, sec in enumerate(sections):
        off = section_table + index * 40
        if sec["header"] is not None:
            header = bytearray(sec["header"])
        else:
            header = bytearray(40)
            header[:8] = bytes(sec["name"])[:8].ljust(8, b"\0")
            struct.pack_into("<I", header, 0x24, int(sec["chars"]))
        struct.pack_into("<I", header, 0x08, int(sec["virtual_size"]))
        struct.pack_into("<I", header, 0x0C, int(sec["rva"]))
        struct.pack_into("<I", header, 0x10, int(sec["raw_size"]))
        struct.pack_into("<I", header, 0x14, int(sec["raw_ptr"]))
        rebuilt[off:off + 40] = header

    for sec in sections:
        raw_size = int(sec["raw_size"])
        if raw_size <= 0:
            continue
        raw_ptr = int(sec["raw_ptr"])
        raw_block = bytes(sec["raw_block"])
        if len(raw_block) > raw_size:
            raise PE64AssemblerError("PE32+-MSZIP: Raw-Sektion größer als SizeOfRawData.")
        if len(rebuilt) < raw_ptr + raw_size:
            rebuilt.extend(bytes(raw_ptr + raw_size - len(rebuilt)))
        rebuilt[raw_ptr:raw_ptr + len(raw_block)] = raw_block

    return bytes(rebuilt), text


_build_pe64_image_with_imports_exports_stage167 = build_pe64_image_with_imports_exports


def build_pe64_image_with_imports_exports(
    code: bytes,
    entry_offset: Optional[int],
    import_specs: Dict[str, Tuple[str, str]],
    iat_call_patches: Dict[str, List[int]],
    *,
    exports=None,
    dll_name="library.dll",
    gui=False,
    dll=False,
    image_base=PE64_IMAGE_BASE,
    base_relocations=(),
    data: bytes = b"",
    bss_size: int = 0,
    compress_text_mszip: Optional[bool] = None,
):
    """Stage-169-Wrapper: vollständigen Stage-167-PE32+-Writer optional packen."""
    if compress_text_mszip is None:
        compress_text_mszip = PE64_TEXT_COMPRESSION_MSZIP_DEFAULT

    pack_text = (
        bool(compress_text_mszip)
        and not bool(dll)
        and bool(code)
        and entry_offset is not None
    )

    if not pack_text:
        return _build_pe64_image_with_imports_exports_stage167(
            code,
            entry_offset,
            import_specs,
            iat_call_patches,
            exports=exports,
            dll_name=dll_name,
            gui=gui,
            dll=dll,
            image_base=image_base,
            base_relocations=base_relocations,
            data=data,
            bss_size=bss_size,
        )

    effective_import_specs = dict(import_specs)
    for symbol, spec in PE64_MSZIP_LOADER_IMPORTS.items():
        effective_import_specs.setdefault(symbol, spec)

    base_image, patched_text = _build_pe64_image_with_imports_exports_stage167(
        code,
        entry_offset,
        effective_import_specs,
        iat_call_patches,
        exports=exports,
        dll_name=dll_name,
        gui=gui,
        dll=dll,
        image_base=image_base,
        base_relocations=base_relocations,
        data=data,
        bss_size=bss_size,
    )

    original_entry_rva = PE64_SECTION_RVA + int(entry_offset)
    return _pe64_rebuild_with_mszip_loader(
        base_image,
        patched_text,
        effective_import_specs,
        original_entry_rva=original_entry_rva,
    )


def link_coff64_objects(
    objects: Sequence[bytes], *, entry_symbol="_start", gui=False, dll=False,
    imports=None, exports=None, dll_name=None,
) -> PE64Program:
    parsed = [parse_coff64_object(x) for x in objects]
    text = bytearray(); init_data = bytearray()
    text_bases = []; data_bases = []; bss_bases = []
    total_bss_size = 0
    global_refs: Dict[str, Tuple[str, int]] = {}
    declared_imports = {}; declared_exports = {}; declared_dll = None
    for obj in parsed:
        declared_imports.update(obj.imports)
        declared_exports.update(obj.exports)
        declared_dll = obj.dll_name or declared_dll
    for s, v in (imports or {}).items():
        declared_imports[str(s).casefold()] = (str(v[0]), str(v[1]))
    for p, i in (exports or {}).items():
        declared_exports[str(p)] = str(i).casefold()
    if dll_name:
        declared_dll = str(dll_name)
    effective_dll = bool(dll or declared_exports)
    image_base = PE64_DLL_IMAGE_BASE if effective_dll else PE64_IMAGE_BASE

    for obj in parsed:
        tbase = _align_up(len(text), 16)
        text.extend(bytes(tbase - len(text)))
        text_bases.append(tbase)
        text.extend(obj.code)
        dbase = _align_up(len(init_data), 8)
        init_data.extend(bytes(dbase - len(init_data)))
        data_bases.append(dbase)
        init_data.extend(obj.data)
        bbase = _align_up(total_bss_size, 8)
        bss_bases.append(bbase)
        total_bss_size = bbase + int(getattr(obj, "bss_size", 0))
        for name, value in obj.symbols.items():
            if value is None:
                continue
            if name in global_refs:
                raise PE64AssemblerError(f"COFF64-Symbol mehrfach definiert: {name}")
            sec = obj.symbol_sections.get(name, ".text")
            if sec == ".text":
                base = tbase
            elif sec == ".data":
                base = dbase
            elif sec == ".bss":
                base = bbase
            else:
                raise PE64AssemblerError(f"Unbekannte COFF64-Symbolsektion: {sec}")
            global_refs[name] = (sec, base + value)

    import_specs = {}; iat_patches = {}; unresolved = []
    external_names = []
    for obj in parsed:
        for r in obj.relocations:
            s = r.symbol.casefold()
            if s not in global_refs and s not in external_names:
                external_names.append(s)
    for symbol in external_names:
        alias_match = re.fullmatch(r"__d64_argc(\d+)__(.+)", symbol, re.IGNORECASE)
        original_symbol = alias_match.group(2).casefold() if alias_match else symbol
        spec = (
            declared_imports.get(symbol)
            or declared_imports.get(original_symbol)
            or _resolve_pe32_default_import(original_symbol)
        )
        if spec is None:
            unresolved.append(symbol)
            continue
        start = _align_up(len(text), 16)
        text.extend(bytes(start - len(text)))
        if alias_match:
            sig = (int(alias_match.group(1)), False)
        else:
            sig = PE64_IMPORT_SIGNATURES.get(original_symbol)
        if sig is not None:
            thunk, local_patch = _pe64_import_adapter_bytes(*sig)
            text.extend(thunk)
            iat_patches.setdefault(symbol, []).append(start + local_patch)
        else:
            text.extend(b"\xFF\x25\0\0\0\0")
            iat_patches.setdefault(symbol, []).append(start + 2)
        global_refs[symbol] = (".text", start)
        import_specs[symbol] = spec
    if unresolved:
        raise PE64AssemblerError(
            "COFF64-Linker: externe Symbole nicht aufgeloest: " + ", ".join(unresolved)
        )

    text_rva = PE64_SECTION_RVA
    next_rva = _align_up(text_rva + max(1, len(text)), PE64_SECTION_ALIGNMENT)
    data_rva = 0
    if init_data:
        data_rva = next_rva
        next_rva = _align_up(data_rva + max(1, len(init_data)), PE64_SECTION_ALIGNMENT)
    bss_rva = 0
    if total_bss_size:
        bss_rva = next_rva
        next_rva = _align_up(bss_rva + max(1, total_bss_size), PE64_SECTION_ALIGNMENT)
    base_relocs = []

    def symbol_rva(name: str) -> int:
        sec, off = global_refs[name]
        base = {".text": text_rva, ".data": data_rva, ".bss": bss_rva}.get(sec)
        if base is None:
            raise PE64AssemblerError(f"Unbekannte COFF64-Zielsektion: {sec}")
        return base + off

    for obj, tbase, dbase in zip(parsed, text_bases, data_bases):
        for r in obj.relocations:
            target = global_refs.get(r.symbol.casefold())
            if target is None:
                raise PE64AssemblerError(f"COFF64-Symbol nicht aufgeloest: {r.symbol}")
            if r.section == ".text":
                buf = text; patch = tbase + r.offset; patch_rva = text_rva + patch
            elif r.section == ".data":
                buf = init_data; patch = dbase + r.offset; patch_rva = data_rva + patch
            else:
                raise PE64AssemblerError(f"Unbekannte COFF64-Relocation-Sektion: {r.section}")
            target_rva = symbol_rva(r.symbol.casefold())
            if IMAGE_REL_AMD64_REL32 <= r.relocation_type <= IMAGE_REL_AMD64_REL32_5:
                tail = r.relocation_type - IMAGE_REL_AMD64_REL32
                struct.pack_into(
                    "<i", buf, patch,
                    target_rva - (patch_rva + 4 + tail),
                )
            elif r.relocation_type == IMAGE_REL_AMD64_ADDR64:
                struct.pack_into("<Q", buf, patch, image_base + target_rva)
                base_relocs.append(patch_rva)
            elif r.relocation_type == IMAGE_REL_AMD64_ADDR32:
                struct.pack_into("<I", buf, patch, (image_base + target_rva) & 0xFFFFFFFF)
            else:
                raise PE64AssemblerError(
                    f"COFF64-Relocation 0x{r.relocation_type:04X} nicht unterstützt."
                )

    wanted = str(entry_symbol or "").casefold()
    entry_ref = global_refs.get(wanted)
    if entry_ref is None and not effective_dll:
        for fallback in ("_start", "start", "main", "_main"):
            if fallback in global_refs:
                entry_ref = global_refs[fallback]
                break
    if entry_ref is None and not effective_dll:
        entry_ref = (".text", 0)
    if entry_ref is not None and entry_ref[0] != ".text":
        raise PE64AssemblerError("PE64-Einstiegspunkt muss in der .text-Sektion liegen.")
    entry = None if entry_ref is None else entry_ref[1]

    export_offsets = {}
    for public, internal in declared_exports.items():
        ref = global_refs.get(internal.casefold())
        if ref is None:
            raise PE64AssemblerError(
                f"DLL-Export {public} verweist auf unbekanntes Symbol {internal}."
            )
        if ref[0] != ".text":
            raise PE64AssemblerError(f"DLL-Export {public} muss ausführbaren Code in .text referenzieren.")
        export_offsets[public] = ref[1]

    effective_dll = bool(effective_dll or export_offsets)
    final_name = declared_dll or "library.dll"
    image, patched = build_pe64_image_with_imports_exports(
        bytes(text), entry, import_specs, iat_patches,
        exports=export_offsets, dll_name=final_name, gui=gui, dll=effective_dll,
        image_base=image_base, base_relocations=base_relocs, data=bytes(init_data),
        bss_size=total_bss_size,
    )
    public_symbols = {}
    for name, (sec, off) in global_refs.items():
        base = {".text": text_rva, ".data": data_rva, ".bss": bss_rva}.get(sec, text_rva)
        public_symbols[name] = base - text_rva + off

    return PE64Program(image, patched, int(entry or 0), 0, public_symbols)


# ---------------------------------------------------------------------------
# Stage 170: bevorzugtes Packerlayout und Import-by-Ordinal.
#
# Bestehende Stage-169-Funktionen bleiben vollständig oberhalb erhalten. Die
# folgenden Definitionen sind additive Wrapper/Erweiterungen. Im gepackten
# EXE-Pfad wird die Section-Reihenfolge bewusst auf
#
#     .text -> .loader -> .ztext -> .idata
#
# festgelegt. PE32+ hängt vorhandene .data/.bss-Sektionen erst danach an.
# ---------------------------------------------------------------------------
# Projektoption statt impliziter Host-Entscheidung: Ohne gesetzte Checkbox
# bleiben Namensimporte auch unter Windows echte Namensimporte.
PE_PACK_IMPORTS_BY_LOCAL_ORDINAL_DEFAULT = False
PE_PACK_LAST_ORDINAL_IMPORTS: List[Dict[str, object]] = []
PE_STAGE170_DOS_HEADER_SIZE = 0x40

_build_pe32_import_section_stage169 = _build_pe32_import_section
_build_pe64_import_section_stage169 = _build_pe64_import_section
_build_pe32_image_with_imports_exports_stage169_layout = (
    build_pe32_image_with_imports_exports
)
_link_coff64_objects_stage169_layout = link_coff64_objects


def _pe_import_spec_parts(spec) -> Tuple[str, object]:
    """Normalisiert (dll, name|ordinal) sowie dict-Importbeschreibungen."""
    dll = ""
    member = None

    if isinstance(spec, dict):
        dll = str(spec.get("dll", "")).strip()
        if spec.get("ordinal") is not None:
            member = spec.get("ordinal")
        else:
            member = spec.get("member", spec.get("name"))
    elif isinstance(spec, (tuple, list)) and len(spec) >= 2:
        dll = str(spec[0]).strip()
        member = spec[1]
    else:
        raise PE32AssemblerError(
            "Ungültige PE-Importbeschreibung: " + repr(spec)
        )

    if not dll:
        raise PE32AssemblerError("PE-Import besitzt keinen DLL-Namen.")

    if isinstance(member, bool):
        member = int(member)

    if isinstance(member, int):
        ordinal = int(member)
        if not 1 <= ordinal <= 0xFFFF:
            raise PE32AssemblerError(
                f"PE-Importordinal außerhalb 1..65535: {ordinal}"
            )
        return dll, ordinal

    text = str(member if member is not None else "").strip()
    if not text:
        raise PE32AssemblerError("PE-Import besitzt weder Namen noch Ordinal.")

    ordinal_text = text[1:] if text.startswith("#") else text
    if ordinal_text.isdigit():
        ordinal = int(ordinal_text, 10)
        if not 1 <= ordinal <= 0xFFFF:
            raise PE32AssemblerError(
                f"PE-Importordinal außerhalb 1..65535: {ordinal}"
            )
        return dll, ordinal

    return dll, text


def _build_pe_import_section_stage170(
    import_specs,
    idata_rva: int,
    *,
    pointer_size: int,
) -> Tuple[bytes, Dict[str, int], int, int]:
    """Gemeinsamer PE32/PE32+-Importbuilder mit Name- und Ordinalimporten."""
    if pointer_size not in {4, 8}:
        raise PE32AssemblerError("PE-Importpointer muss 4 oder 8 Byte groß sein.")

    normalized: Dict[str, Tuple[str, object]] = {}
    grouped: Dict[str, List[object]] = {}

    for symbol, raw_spec in import_specs.items():
        dll, member = _pe_import_spec_parts(raw_spec)
        normalized[str(symbol)] = (dll, member)
        members = grouped.setdefault(dll, [])
        if member not in members:
            members.append(member)

    if not grouped:
        return b"", {}, 0, 0

    dll_items = list(grouped.items())
    data = bytearray(20 * (len(dll_items) + 1))
    ilt_offsets: Dict[str, int] = {}
    iat_offsets: Dict[str, int] = {}
    hint_offsets: Dict[Tuple[str, str], int] = {}
    dll_name_offsets: Dict[str, int] = {}

    for dll, members in dll_items:
        ilt_offsets[dll] = len(data)
        data.extend(bytes(pointer_size * (len(members) + 1)))

    for dll, members in dll_items:
        iat_offsets[dll] = len(data)
        data.extend(bytes(pointer_size * (len(members) + 1)))

    # IMAGE_IMPORT_BY_NAME wird nur für echte Namensimporte angelegt.
    for dll, members in dll_items:
        for member in members:
            if isinstance(member, int):
                continue
            if len(data) & 1:
                data.append(0)
            name = str(member)
            hint_offsets[(dll, name)] = len(data)
            data.extend(struct.pack("<H", 0))
            data.extend(name.encode("ascii") + b"\0")

    for dll, _members in dll_items:
        dll_name_offsets[dll] = len(data)
        data.extend(dll.encode("ascii") + b"\0")

    iat_by_spec: Dict[Tuple[str, object], int] = {}
    first_iat_rva = 0
    total_iat_size = 0
    ordinal_flag = (
        0x80000000
        if pointer_size == 4
        else 0x8000000000000000
    )
    pack_fmt = "<I" if pointer_size == 4 else "<Q"

    for descriptor_index, (dll, members) in enumerate(dll_items):
        ilt_rva = int(idata_rva) + ilt_offsets[dll]
        iat_rva = int(idata_rva) + iat_offsets[dll]
        if first_iat_rva == 0:
            first_iat_rva = iat_rva
        total_iat_size += pointer_size * (len(members) + 1)

        struct.pack_into(
            "<IIIII",
            data,
            descriptor_index * 20,
            ilt_rva,
            0,
            0,
            int(idata_rva) + dll_name_offsets[dll],
            iat_rva,
        )

        for member_index, member in enumerate(members):
            if isinstance(member, int):
                lookup = ordinal_flag | (int(member) & 0xFFFF)
            else:
                lookup = int(idata_rva) + hint_offsets[(dll, str(member))]

            struct.pack_into(
                pack_fmt,
                data,
                ilt_offsets[dll] + member_index * pointer_size,
                lookup,
            )
            struct.pack_into(
                pack_fmt,
                data,
                iat_offsets[dll] + member_index * pointer_size,
                lookup,
            )
            iat_by_spec[(dll, member)] = iat_rva + member_index * pointer_size

    symbol_iat_rvas = {
        symbol: iat_by_spec[spec]
        for symbol, spec in normalized.items()
    }
    return bytes(data), symbol_iat_rvas, first_iat_rva, total_iat_size


def _build_pe32_import_section(import_specs, idata_rva: int):
    return _build_pe_import_section_stage170(
        import_specs,
        idata_rva,
        pointer_size=4,
    )


def _build_pe64_import_section(import_specs, idata_rva: int):
    return _build_pe_import_section_stage170(
        import_specs,
        idata_rva,
        pointer_size=8,
    )


def _pe_file_machine(path: Path) -> Optional[int]:
    try:
        with Path(path).open("rb") as stream:
            head = stream.read(0x1000)
    except OSError:
        return None

    if len(head) < 0x40 or head[:2] != b"MZ":
        return None
    pe_offset = struct.unpack_from("<I", head, 0x3C)[0]

    try:
        if pe_offset + 6 <= len(head):
            data = head
        else:
            with Path(path).open("rb") as stream:
                stream.seek(pe_offset)
                part = stream.read(24)
            if len(part) < 6 or part[:4] != b"PE\0\0":
                return None
            return struct.unpack_from("<H", part, 4)[0]
    except OSError:
        return None

    if data[pe_offset:pe_offset + 4] != b"PE\0\0":
        return None
    return struct.unpack_from("<H", data, pe_offset + 4)[0]


_PE_EXPORT_ORDINAL_CACHE: Dict[Tuple[str, int, int], Dict[str, int]] = {}


def _pe_export_name_ordinals(path: Path, expected_machine: int) -> Dict[str, int]:
    """Liest Name->Ordinal direkt aus der PE-Exporttabelle einer DLL."""
    file_path = Path(path)
    try:
        stat = file_path.stat()
        cache_key = (
            str(file_path.resolve()).casefold(),
            int(stat.st_mtime_ns),
            int(expected_machine),
        )
    except OSError:
        return {}

    cached = _PE_EXPORT_ORDINAL_CACHE.get(cache_key)
    if cached is not None:
        return dict(cached)

    try:
        data = file_path.read_bytes()
    except OSError:
        return {}

    result: Dict[str, int] = {}
    try:
        if len(data) < 0x40 or data[:2] != b"MZ":
            return {}
        pe_offset = struct.unpack_from("<I", data, 0x3C)[0]
        if pe_offset + 24 > len(data) or data[pe_offset:pe_offset + 4] != b"PE\0\0":
            return {}

        file_header = pe_offset + 4
        machine, section_count = struct.unpack_from("<HH", data, file_header)
        if int(machine) != int(expected_machine):
            return {}

        optional_size = struct.unpack_from("<H", data, file_header + 16)[0]
        optional_offset = file_header + 20
        if optional_offset + optional_size > len(data):
            return {}
        magic = struct.unpack_from("<H", data, optional_offset)[0]
        if magic == 0x010B:
            directory_offset = optional_offset + 0x60
            size_headers_offset = optional_offset + 0x3C
        elif magic == 0x020B:
            directory_offset = optional_offset + 0x70
            size_headers_offset = optional_offset + 0x3C
        else:
            return {}

        export_rva, export_size = struct.unpack_from(
            "<II", data, directory_offset
        )
        if export_rva == 0 or export_size == 0:
            return {}

        section_table = optional_offset + optional_size
        sections = []
        for index in range(section_count):
            off = section_table + index * 40
            if off + 40 > len(data):
                return {}
            virtual_size, rva, raw_size, raw_ptr = struct.unpack_from(
                "<IIII", data, off + 0x08
            )
            sections.append((rva, virtual_size, raw_size, raw_ptr))

        size_of_headers = struct.unpack_from("<I", data, size_headers_offset)[0]

        def rva_to_offset(rva_value: int, size: int = 1) -> int:
            rva_value = int(rva_value)
            if 0 <= rva_value < int(size_of_headers):
                if rva_value + size <= len(data):
                    return rva_value
                raise ValueError("RVA außerhalb Header")
            for sec_rva, virtual_size, raw_size, raw_ptr in sections:
                span = max(int(virtual_size), int(raw_size))
                if int(sec_rva) <= rva_value < int(sec_rva) + span:
                    relative = rva_value - int(sec_rva)
                    if relative + size > int(raw_size):
                        raise ValueError("RVA liegt nur im virtuellen Nullbereich")
                    file_off = int(raw_ptr) + relative
                    if file_off + size > len(data):
                        raise ValueError("RVA außerhalb Datei")
                    return file_off
            raise ValueError("RVA keiner Section zugeordnet")

        export_off = rva_to_offset(export_rva, 40)
        (
            _characteristics,
            _timestamp,
            _major,
            _minor,
            _name_rva,
            ordinal_base,
            _function_count,
            name_count,
            _address_functions,
            address_names,
            address_name_ordinals,
        ) = struct.unpack_from("<IIHHIIIIIII", data, export_off)

        names_off = rva_to_offset(address_names, int(name_count) * 4)
        ordinals_off = rva_to_offset(
            address_name_ordinals,
            int(name_count) * 2,
        )

        for index in range(int(name_count)):
            name_rva = struct.unpack_from("<I", data, names_off + index * 4)[0]
            ordinal_index = struct.unpack_from(
                "<H", data, ordinals_off + index * 2
            )[0]
            name_off = rva_to_offset(name_rva, 1)
            end = data.find(b"\0", name_off)
            if end < 0:
                continue
            try:
                export_name = data[name_off:end].decode("ascii")
            except UnicodeDecodeError:
                continue
            ordinal = int(ordinal_base) + int(ordinal_index)
            if 1 <= ordinal <= 0xFFFF:
                result[export_name] = ordinal
    except (ValueError, struct.error, OverflowError):
        result = {}

    _PE_EXPORT_ORDINAL_CACHE[cache_key] = dict(result)
    return result


def _pe_target_dll_candidates(
    dll_name: str,
    machine: int,
    search_paths: Iterable[Path | str] = (),
) -> List[Path]:
    raw = str(dll_name).strip().strip('"')
    if not raw:
        return []

    candidates: List[Path] = []
    raw_path = Path(raw)
    if raw_path.is_absolute() or raw_path.parent != Path("."):
        candidates.append(raw_path)
    else:
        for search_path in search_paths or ():
            candidates.append(Path(search_path).expanduser() / raw_path.name)
        candidates.append(Path.cwd() / raw_path.name)

    if os.name == "nt":
        windir = Path(os.environ.get("WINDIR", r"C:\Windows"))
        if int(machine) == IMAGE_FILE_MACHINE_I386:
            candidates.append(windir / "SysWOW64" / raw_path.name)
            candidates.append(windir / "System32" / raw_path.name)
        elif int(machine) == IMAGE_FILE_MACHINE_AMD64:
            # Sysnative ist für einen 32-Bit-Buildprozess der Zugriff auf die
            # native 64-Bit-System32-Ansicht; bei 64-Bit-Python existiert der
            # normale System32-Pfad direkt.
            candidates.append(windir / "System32" / raw_path.name)
            candidates.append(windir / "Sysnative" / raw_path.name)

        for entry in os.environ.get("PATH", "").split(os.pathsep):
            entry = entry.strip().strip('"')
            if entry:
                candidates.append(Path(entry) / raw_path.name)

    unique: List[Path] = []
    seen = set()
    for candidate in candidates:
        key = str(candidate).casefold()
        if key in seen:
            continue
        seen.add(key)
        unique.append(candidate)
    return unique


def _pe_find_target_dll(
    dll_name: str,
    machine: int,
    search_paths: Iterable[Path | str] = (),
) -> Optional[Path]:
    for candidate in _pe_target_dll_candidates(
        dll_name, machine, search_paths
    ):
        try:
            if not candidate.is_file():
                continue
        except OSError:
            continue
        if _pe_file_machine(candidate) == int(machine):
            return candidate
    return None


def _pe_import_specs_with_local_ordinals(
    import_specs,
    *,
    machine: int,
    enabled: Optional[bool] = None,
    search_paths: Iterable[Path | str] = (),
    require_all: bool = False,
) -> Dict[str, Tuple[str, object]]:
    """Ersetzt Namensimporte durch Ordinale aus der lokalen Ziel-DLL.

    Das spart IMAGE_IMPORT_BY_NAME-Zeichenketten. Die Bindung an lokale
    System-DLL-Ordinale ist absichtlich abschaltbar, weil Microsoft die
    Ordinalnummern vieler System-DLLs nicht als stabile API garantiert.
    """
    if enabled is None:
        enabled = PE_PACK_IMPORTS_BY_LOCAL_ORDINAL_DEFAULT

    result: Dict[str, Tuple[str, object]] = {}
    dll_cache: Dict[str, Tuple[Optional[Path], Dict[str, int]]] = {}

    if enabled:
        PE_PACK_LAST_ORDINAL_IMPORTS.clear()

    for symbol, raw_spec in import_specs.items():
        dll, member = _pe_import_spec_parts(raw_spec)
        if isinstance(member, int) or not enabled:
            result[str(symbol)] = (dll, member)
            continue

        dll_key = dll.casefold()
        cached = dll_cache.get(dll_key)
        if cached is None:
            path = _pe_find_target_dll(dll, machine, search_paths)
            ordinals = (
                _pe_export_name_ordinals(path, machine)
                if path is not None
                else {}
            )
            cached = (path, ordinals)
            dll_cache[dll_key] = cached

        path, ordinals = cached
        ordinal = ordinals.get(str(member))
        if ordinal is None:
            folded = str(member).casefold()
            matches = [
                value
                for name, value in ordinals.items()
                if name.casefold() == folded
            ]
            if len(matches) == 1:
                ordinal = matches[0]

        if ordinal is None:
            if require_all:
                target_name = (
                    "PE32+ (AMD64)"
                    if int(machine) == IMAGE_FILE_MACHINE_AMD64
                    else "PE32 (IA-32)"
                )
                if path is None:
                    raise PE32AssemblerError(
                        f"Ordinalimport für '{member}' aus '{dll}' ist nicht "
                        f"möglich: passende {target_name}-DLL wurde in den "
                        "Projekt-Suchpfaden nicht gefunden."
                    )
                raise PE32AssemblerError(
                    f"Ordinalimport für '{member}' aus '{dll}' ist nicht "
                    f"möglich: die Exporttabelle von '{path}' enthält diesen "
                    "Funktionsnamen nicht."
                )
            result[str(symbol)] = (dll, member)
            continue

        result[str(symbol)] = (dll, int(ordinal))
        PE_PACK_LAST_ORDINAL_IMPORTS.append({
            "machine": int(machine),
            "dll": dll,
            "name": str(member),
            "ordinal": int(ordinal),
            "path": str(path) if path is not None else "",
        })

    return result


def rewrite_pe_assembly_imports_to_ordinals(
    source: str,
    *,
    target: str,
    search_paths: Iterable[Path | str] = (),
    require_all: bool = True,
) -> str:
    """Ersetzt sichtbare DLL-Funktionsnamen durch ``"#<Ordinal>"``.

    Die Zeilenzahl bleibt unverändert, damit Source-Maps und ASM-Diagnosen
    weiterhin auf dieselben Zeilen zeigen.
    """
    target_key = str(target or "").strip().casefold()
    if target_key not in {"pe32", "pe64"}:
        return str(source)
    machine = (
        IMAGE_FILE_MACHINE_AMD64
        if target_key == "pe64"
        else IMAGE_FILE_MACHINE_I386
    )
    lines = str(source).splitlines(keepends=True)
    imports: Dict[str, Tuple[str, object]] = {}
    line_imports: Dict[int, Tuple[str, str, object]] = {}

    for index, raw_line in enumerate(lines):
        code = _x86_strip_comment(raw_line).strip()
        if not code:
            continue
        parts = code.split(None, 1)
        if parts[0].casefold().lstrip(".") != "import" or len(parts) != 2:
            continue
        operands = _x86_split_operands(parts[1])
        if len(operands) not in {2, 3}:
            continue
        symbol = _pe32_unquote(operands[0]).strip()
        dll = _pe32_unquote(operands[1]).strip()
        member = (
            _pe32_unquote(operands[2]).strip()
            if len(operands) == 3
            else symbol
        )
        if not symbol or not dll or not member:
            continue
        ordinal_text = member[1:] if member.startswith("#") else member
        member_value: object = (
            int(ordinal_text, 10) if ordinal_text.isdigit() else member
        )
        key = f"__d64_import_line_{index}"
        imports[key] = (dll, member_value)
        line_imports[index] = (key, symbol, member_value)

    if not imports:
        return str(source)

    converted = _pe_import_specs_with_local_ordinals(
        imports,
        machine=machine,
        enabled=True,
        search_paths=search_paths,
        require_all=require_all,
    )
    for index, (key, symbol, original_member) in line_imports.items():
        dll, member = converted[key]
        if not isinstance(member, int) or isinstance(original_member, int):
            continue
        raw_line = lines[index]
        newline = (
            "\r\n" if raw_line.endswith("\r\n")
            else "\n" if raw_line.endswith("\n")
            else ""
        )
        body = raw_line[:-len(newline)] if newline else raw_line
        indentation = body[:len(body) - len(body.lstrip())]
        comment = ""
        semicolon = body.find(";")
        if semicolon >= 0:
            comment = " " + body[semicolon:].lstrip()
        lines[index] = (
            f'{indentation}import {symbol}, "{dll}", "#{int(member)}"'
            f"{comment}{newline}"
        )
    return "".join(lines)


def _pe_stage170_ztext_virtual_span(text_size: int, alignment: int) -> int:
    """Reserviert genug VA-Raum für einen selten leicht größeren MSZIP-Block."""
    size = max(1, int(text_size))
    # MSZIP/DEFLATE kann bei bereits unkomprimierbaren Daten geringfügig
    # wachsen. 4 KiB + 6,25 Prozent Reserve halten die nachfolgende .idata
    # nah an .ztext, ohne eine zirkuläre IAT->Kompression->RVA-Abhängigkeit.
    extra = 0x1000 + (size // 16)
    wanted = PE32_D64Z_HEADER_SIZE + size + extra
    return _align_up(max(wanted, alignment), alignment)


def _pe_emit_stage170_image(
    *,
    machine: int,
    image_base: int,
    text_rva: int,
    text_virtual_size: int,
    loader_rva: int,
    loader: bytes,
    ztext_rva: int,
    ztext: bytes,
    ztext_virtual_size: int,
    idata_rva: int,
    idata: bytes,
    first_iat_rva: int,
    iat_size: int,
    entry_rva: int,
    gui: bool,
    data_rva: int = 0,
    data: bytes = b"",
    bss_rva: int = 0,
    bss_size: int = 0,
) -> bytes:
    """Schreibt das Stage-170-Packerlayout für PE32 oder PE32+."""
    is64 = int(machine) == IMAGE_FILE_MACHINE_AMD64
    if not is64 and int(machine) != IMAGE_FILE_MACHINE_I386:
        raise PE32AssemblerError("Stage170: unbekannte PE-Maschine.")

    file_alignment = PE64_FILE_ALIGNMENT if is64 else PE32_FILE_ALIGNMENT
    section_alignment = PE64_SECTION_ALIGNMENT if is64 else PE32_SECTION_ALIGNMENT
    optional_size = 0xF0 if is64 else 0xE0

    sections = [
        {
            "name": b".text",
            "data": b"",
            "virtual_size": max(1, int(text_virtual_size)),
            "rva": int(text_rva),
            "chars": 0x60000020 if is64 else 0xE0000020,
            "raw": False,
        },
        {
            "name": b".loader",
            "data": bytes(loader),
            "virtual_size": len(loader),
            "rva": int(loader_rva),
            "chars": 0x60000020,
            "raw": True,
        },
        {
            "name": b".ztext",
            "data": bytes(ztext),
            "virtual_size": max(len(ztext), int(ztext_virtual_size)),
            "rva": int(ztext_rva),
            "chars": 0x40000040,
            "raw": True,
        },
        {
            "name": b".idata",
            "data": bytes(idata),
            "virtual_size": len(idata),
            "rva": int(idata_rva),
            "chars": 0xC0000040,
            "raw": True,
        },
    ]

    if data:
        sections.append({
            "name": b".data",
            "data": bytes(data),
            "virtual_size": len(data),
            "rva": int(data_rva),
            "chars": 0xC0000040,
            "raw": True,
        })
    if int(bss_size) > 0:
        sections.append({
            "name": b".bss",
            "data": b"",
            "virtual_size": int(bss_size),
            "rva": int(bss_rva),
            "chars": 0xC0000080,
            "raw": False,
        })

    # Section-RVAs müssen monoton steigen. Das ist für Windows-Images die
    # robuste Variante und entspricht zugleich der gewünschten sichtbaren
    # Reihenfolge in PE-Viewern.
    previous_rva = -1
    for sec in sections:
        if int(sec["rva"]) <= previous_rva:
            raise PE32AssemblerError(
                "Stage170: Section-RVAs sind nicht streng aufsteigend."
            )
        previous_rva = int(sec["rva"])

    section_table = (
        PE_STAGE170_DOS_HEADER_SIZE
        + 4
        + 20
        + optional_size
    )
    headers_size = _align_up(
        section_table + len(sections) * 40,
        file_alignment,
    )

    raw_cursor = headers_size
    layout = []
    size_of_code = 0
    size_of_initialized_data = 0
    for sec in sections:
        if sec["raw"] and sec["data"]:
            raw_size = _align_up(len(sec["data"]), file_alignment)
            raw_ptr = raw_cursor
            raw_cursor += raw_size
        else:
            raw_size = 0
            raw_ptr = 0
        item = dict(sec)
        item["raw_size"] = raw_size
        item["raw_ptr"] = raw_ptr
        layout.append(item)
        if int(sec["chars"]) & 0x00000020:
            size_of_code += raw_size
        elif raw_size:
            size_of_initialized_data += raw_size

    last = sections[-1]
    size_of_image = _align_up(
        int(last["rva"]) + max(1, int(last["virtual_size"])),
        section_alignment,
    )

    dos = bytearray(PE_STAGE170_DOS_HEADER_SIZE)
    dos[:2] = b"MZ"
    struct.pack_into("<I", dos, 0x3C, PE_STAGE170_DOS_HEADER_SIZE)

    pe = bytearray(b"PE\0\0")
    if is64:
        # Gepackter .text wird erst nach dem Windows-Loader dekomprimiert.
        # Darum wird ASLR für diesen Modus bewusst abgeschaltet: Windows kann
        # Relocations in einem noch nicht vorhandenen .text nicht vorab patchen.
        file_chars = 0x0023  # EXECUTABLE | LARGE_ADDRESS_AWARE | RELOCS_STRIPPED
    else:
        file_chars = 0x0103  # i386 | EXECUTABLE | RELOCS_STRIPPED
    pe.extend(struct.pack(
        "<HHIIIHH",
        int(machine),
        len(layout),
        0,
        0,
        0,
        optional_size,
        file_chars,
    ))

    optional = bytearray(optional_size)
    if is64:
        struct.pack_into("<H", optional, 0x00, 0x020B)
        optional[0x02] = 1
        struct.pack_into("<I", optional, 0x04, size_of_code)
        struct.pack_into("<I", optional, 0x08, size_of_initialized_data)
        struct.pack_into("<I", optional, 0x0C, int(bss_size))
        struct.pack_into("<I", optional, 0x10, int(entry_rva))
        struct.pack_into("<I", optional, 0x14, int(text_rva))
        struct.pack_into("<Q", optional, 0x18, int(image_base))
        struct.pack_into("<I", optional, 0x20, section_alignment)
        struct.pack_into("<I", optional, 0x24, file_alignment)
        struct.pack_into("<HHHH", optional, 0x28, 6, 0, 0, 0)
        struct.pack_into("<HH", optional, 0x30, 6, 0)
        struct.pack_into("<I", optional, 0x38, size_of_image)
        struct.pack_into("<I", optional, 0x3C, headers_size)
        struct.pack_into("<H", optional, 0x44, 2 if gui else 3)
        struct.pack_into("<H", optional, 0x46, 0x0100)  # NX_COMPAT, kein ASLR
        struct.pack_into(
            "<QQQQ",
            optional,
            0x48,
            0x400000,
            0x4000,
            0x100000,
            0x2000,
        )
        struct.pack_into("<I", optional, 0x68, 0)
        struct.pack_into("<I", optional, 0x6C, 16)
        struct.pack_into("<II", optional, 0x78, int(idata_rva), len(idata))
        struct.pack_into("<II", optional, 0xD0, int(first_iat_rva), int(iat_size))
    else:
        struct.pack_into("<H", optional, 0x00, 0x010B)
        optional[0x02] = 1
        struct.pack_into("<I", optional, 0x04, size_of_code)
        struct.pack_into("<I", optional, 0x08, size_of_initialized_data)
        struct.pack_into("<I", optional, 0x0C, int(bss_size))
        struct.pack_into("<I", optional, 0x10, int(entry_rva))
        struct.pack_into("<I", optional, 0x14, int(text_rva))
        struct.pack_into("<I", optional, 0x18, int(ztext_rva))
        struct.pack_into("<I", optional, 0x1C, int(image_base))
        struct.pack_into("<I", optional, 0x20, section_alignment)
        struct.pack_into("<I", optional, 0x24, file_alignment)
        struct.pack_into("<HHHH", optional, 0x28, 4, 0, 0, 0)
        struct.pack_into("<HH", optional, 0x30, 4, 0)
        struct.pack_into("<I", optional, 0x38, size_of_image)
        struct.pack_into("<I", optional, 0x3C, headers_size)
        struct.pack_into("<H", optional, 0x44, 2 if gui else 3)
        struct.pack_into("<H", optional, 0x46, 0)
        struct.pack_into(
            "<IIII",
            optional,
            0x48,
            0x00100000,
            0x1000,
            0x00100000,
            0x1000,
        )
        struct.pack_into("<II", optional, 0x58, 0, 16)
        struct.pack_into("<II", optional, 0x68, int(idata_rva), len(idata))
        struct.pack_into("<II", optional, 0xC0, int(first_iat_rva), int(iat_size))

    pe.extend(optional)

    for sec in layout:
        header = bytearray(40)
        header[:8] = bytes(sec["name"])[:8].ljust(8, b"\0")
        struct.pack_into("<I", header, 0x08, int(sec["virtual_size"]))
        struct.pack_into("<I", header, 0x0C, int(sec["rva"]))
        struct.pack_into("<I", header, 0x10, int(sec["raw_size"]))
        struct.pack_into("<I", header, 0x14, int(sec["raw_ptr"]))
        struct.pack_into("<I", header, 0x24, int(sec["chars"]))
        pe.extend(header)

    headers = bytes(dos) + bytes(pe)
    if len(headers) > headers_size:
        raise PE32AssemblerError("Stage170: PE-Header überschreitet SizeOfHeaders.")
    image = bytearray(headers_size)
    image[:len(headers)] = headers

    for sec in layout:
        raw_size = int(sec["raw_size"])
        if raw_size <= 0:
            continue
        raw_ptr = int(sec["raw_ptr"])
        raw_data = bytes(sec["data"])
        if len(image) < raw_ptr + raw_size:
            image.extend(bytes(raw_ptr + raw_size - len(image)))
        image[raw_ptr:raw_ptr + len(raw_data)] = raw_data

    return bytes(image)


def build_pe32_image_with_imports_exports(
    code: bytes,
    entry_offset: Optional[int],
    import_specs,
    thunk_patches: Dict[str, int],
    *,
    exports: Optional[Dict[str, int]] = None,
    dll_name: str = "library.dll",
    gui: bool = False,
    dll: bool = False,
    image_base: int = PE32_IMAGE_BASE,
    base_relocations: Optional[Sequence[int]] = None,
    compress_text_mszip: Optional[bool] = None,
    imports_by_local_ordinal: Optional[bool] = None,
    bss_size: int = 0,
) -> Tuple[bytes, bytes]:
    """Stage170-PE32: .text/.loader/.ztext/.idata in RVA-Reihenfolge."""
    if compress_text_mszip is None:
        compress_text_mszip = PE32_TEXT_COMPRESSION_MSZIP_DEFAULT

    pack_text = (
        bool(compress_text_mszip)
        and not bool(dll)
        and not bool(exports)
        and bool(code)
        and entry_offset is not None
    )
    if not pack_text:
        return _build_pe32_image_with_imports_exports_stage169_layout(
            code,
            entry_offset,
            import_specs,
            thunk_patches,
            exports=exports,
            dll_name=dll_name,
            gui=gui,
            dll=dll,
            image_base=image_base,
            base_relocations=base_relocations,
            compress_text_mszip=False,
            bss_size=bss_size,
        )

    text = bytearray(code)
    text_rva = PE32_SECTION_RVA
    original_entry_rva = text_rva + int(entry_offset)

    effective_import_specs = dict(import_specs)
    for symbol, spec in PE32_MSZIP_LOADER_IMPORTS.items():
        effective_import_specs.setdefault(symbol, spec)
    effective_import_specs = _pe_import_specs_with_local_ordinals(
        effective_import_specs,
        machine=IMAGE_FILE_MACHINE_I386,
        enabled=imports_by_local_ordinal,
    )

    loader_rva = _align_up(
        text_rva + max(1, len(text)),
        PE32_SECTION_ALIGNMENT,
    )
    dummy_iat = {name: 0 for name in PE32_MSZIP_LOADER_IMPORTS}
    probe = _build_pe32_mszip_loader(
        image_base=image_base,
        text_rva=text_rva,
        text_size=len(text),
        ztext_rva=0,
        packed_size=max(1, len(text)),
        original_entry_rva=original_entry_rva,
        iat_rvas=dummy_iat,
    )
    ztext_rva = _align_up(
        loader_rva + max(1, len(probe)),
        PE32_SECTION_ALIGNMENT,
    )
    ztext_virtual_size = _pe_stage170_ztext_virtual_span(
        len(text),
        PE32_SECTION_ALIGNMENT,
    )
    idata_rva = ztext_rva + ztext_virtual_size

    idata, iat_rvas, first_iat_rva, iat_size = _build_pe32_import_section(
        effective_import_specs,
        idata_rva,
    )
    bss_rva = 0
    if int(bss_size) > 0:
        bss_rva = _align_up(
            idata_rva + max(1, len(idata)), PE32_SECTION_ALIGNMENT
        )

    for symbol, patch_offset in thunk_patches.items():
        if symbol not in iat_rvas:
            raise PE32AssemblerError(
                f"Stage170-PE32: IAT-Eintrag fehlt für {symbol}."
            )
        struct.pack_into(
            "<I",
            text,
            int(patch_offset),
            (int(image_base) + int(iat_rvas[symbol])) & 0xFFFFFFFF,
        )

    ztext, packed_size = _pe32_build_d64z_payload(
        bytes(text),
        text_rva=text_rva,
        original_entry_rva=original_entry_rva,
    )
    if len(ztext) > ztext_virtual_size:
        raise PE32AssemblerError(
            "Stage170-PE32: MSZIP-Block überschreitet reservierten .ztext-VA-Raum."
        )

    loader = _build_pe32_mszip_loader(
        image_base=image_base,
        text_rva=text_rva,
        text_size=len(text),
        ztext_rva=ztext_rva,
        packed_size=packed_size,
        original_entry_rva=original_entry_rva,
        iat_rvas=iat_rvas,
    )

    image = _pe_emit_stage170_image(
        machine=IMAGE_FILE_MACHINE_I386,
        image_base=image_base,
        text_rva=text_rva,
        text_virtual_size=len(text),
        loader_rva=loader_rva,
        loader=loader,
        ztext_rva=ztext_rva,
        ztext=ztext,
        ztext_virtual_size=ztext_virtual_size,
        idata_rva=idata_rva,
        idata=idata,
        first_iat_rva=first_iat_rva,
        iat_size=iat_size,
        entry_rva=loader_rva,
        gui=gui,
        bss_rva=bss_rva,
        bss_size=int(bss_size),
    )
    return image, bytes(text)


def link_coff64_objects(
    objects: Sequence[bytes],
    *,
    entry_symbol="_start",
    gui=False,
    dll=False,
    imports=None,
    exports=None,
    dll_name=None,
) -> PE64Program:
    """Stage170-PE32+: gepacktes EXE mit .text/.loader/.ztext/.idata."""
    parsed = [parse_coff64_object(x) for x in objects]

    declared_exports = {}
    for obj in parsed:
        declared_exports.update(obj.exports)
    for public, internal in (exports or {}).items():
        declared_exports[str(public)] = str(internal).casefold()

    effective_dll = bool(dll or declared_exports)
    pack_text = bool(PE64_TEXT_COMPRESSION_MSZIP_DEFAULT) and not effective_dll
    if not pack_text:
        return _link_coff64_objects_stage169_layout(
            objects,
            entry_symbol=entry_symbol,
            gui=gui,
            dll=dll,
            imports=imports,
            exports=exports,
            dll_name=dll_name,
        )

    text = bytearray()
    init_data = bytearray()
    text_bases = []
    data_bases = []
    bss_bases = []
    total_bss_size = 0
    global_refs: Dict[str, Tuple[str, int]] = {}
    declared_imports = {}
    declared_dll = None

    for obj in parsed:
        declared_imports.update(obj.imports)
        declared_dll = obj.dll_name or declared_dll

    for symbol, raw_spec in (imports or {}).items():
        declared_imports[str(symbol).casefold()] = _pe_import_spec_parts(raw_spec)
    if dll_name:
        declared_dll = str(dll_name)

    image_base = PE64_IMAGE_BASE

    for obj in parsed:
        tbase = _align_up(len(text), 16)
        text.extend(bytes(tbase - len(text)))
        text_bases.append(tbase)
        text.extend(obj.code)

        dbase = _align_up(len(init_data), 8)
        init_data.extend(bytes(dbase - len(init_data)))
        data_bases.append(dbase)
        init_data.extend(obj.data)

        bbase = _align_up(total_bss_size, 8)
        bss_bases.append(bbase)
        total_bss_size = bbase + int(getattr(obj, "bss_size", 0))

        for name, value in obj.symbols.items():
            if value is None:
                continue
            if name in global_refs:
                raise PE64AssemblerError(
                    f"COFF64-Symbol mehrfach definiert: {name}"
                )
            sec = obj.symbol_sections.get(name, ".text")
            if sec == ".text":
                base = tbase
            elif sec == ".data":
                base = dbase
            elif sec == ".bss":
                base = bbase
            else:
                raise PE64AssemblerError(
                    f"Unbekannte COFF64-Symbolsektion: {sec}"
                )
            global_refs[name] = (sec, base + value)

    import_specs = {}
    iat_patches = {}
    unresolved = []
    external_names = []
    for obj in parsed:
        for relocation in obj.relocations:
            symbol = relocation.symbol.casefold()
            if symbol not in global_refs and symbol not in external_names:
                external_names.append(symbol)

    for symbol in external_names:
        alias_match = re.fullmatch(
            r"__d64_argc(\d+)__(.+)",
            symbol,
            re.IGNORECASE,
        )
        original_symbol = (
            alias_match.group(2).casefold()
            if alias_match
            else symbol
        )
        spec = (
            declared_imports.get(symbol)
            or declared_imports.get(original_symbol)
            or _resolve_pe32_default_import(original_symbol)
        )
        if spec is None:
            unresolved.append(symbol)
            continue

        start = _align_up(len(text), 16)
        text.extend(bytes(start - len(text)))
        if alias_match:
            signature = (int(alias_match.group(1)), False)
        else:
            signature = PE64_IMPORT_SIGNATURES.get(original_symbol)

        if signature is not None:
            thunk, local_patch = _pe64_import_adapter_bytes(*signature)
            text.extend(thunk)
            iat_patches.setdefault(symbol, []).append(start + local_patch)
        else:
            text.extend(b"\xFF\x25\0\0\0\0")
            iat_patches.setdefault(symbol, []).append(start + 2)

        global_refs[symbol] = (".text", start)
        import_specs[symbol] = spec

    if unresolved:
        raise PE64AssemblerError(
            "COFF64-Linker: externe Symbole nicht aufgeloest: "
            + ", ".join(unresolved)
        )

    effective_import_specs = dict(import_specs)
    for symbol, spec in PE64_MSZIP_LOADER_IMPORTS.items():
        effective_import_specs.setdefault(symbol, spec)
    effective_import_specs = _pe_import_specs_with_local_ordinals(
        effective_import_specs,
        machine=IMAGE_FILE_MACHINE_AMD64,
    )

    # Virtuelles Layout zuerst festlegen, damit COFF64-Relocations bereits die
    # endgültigen .data/.bss-RVAs sehen.
    text_rva = PE64_SECTION_RVA
    loader_rva = _align_up(
        text_rva + max(1, len(text)),
        PE64_SECTION_ALIGNMENT,
    )
    dummy_iat = {name: 0 for name in PE64_MSZIP_LOADER_IMPORTS}
    probe = _build_pe64_mszip_loader(
        loader_rva=loader_rva,
        text_rva=text_rva,
        text_size=len(text),
        ztext_rva=0,
        packed_size=max(1, len(text)),
        original_entry_rva=text_rva,
        iat_rvas=dummy_iat,
    )
    ztext_rva = _align_up(
        loader_rva + max(1, len(probe)),
        PE64_SECTION_ALIGNMENT,
    )
    ztext_virtual_size = _pe_stage170_ztext_virtual_span(
        len(text),
        PE64_SECTION_ALIGNMENT,
    )
    idata_rva = ztext_rva + ztext_virtual_size
    idata, iat_rvas, first_iat, iat_size = _build_pe64_import_section(
        effective_import_specs,
        idata_rva,
    )

    next_rva = _align_up(
        idata_rva + max(1, len(idata)),
        PE64_SECTION_ALIGNMENT,
    )
    data_rva = 0
    if init_data:
        data_rva = next_rva
        next_rva = _align_up(
            data_rva + max(1, len(init_data)),
            PE64_SECTION_ALIGNMENT,
        )
    bss_rva = 0
    if total_bss_size:
        bss_rva = next_rva
        next_rva = _align_up(
            bss_rva + max(1, total_bss_size),
            PE64_SECTION_ALIGNMENT,
        )

    def symbol_rva(name: str) -> int:
        sec, off = global_refs[name]
        base = {
            ".text": text_rva,
            ".data": data_rva,
            ".bss": bss_rva,
        }.get(sec)
        if base is None:
            raise PE64AssemblerError(
                f"Unbekannte COFF64-Zielsektion: {sec}"
            )
        return int(base) + int(off)

    # Im gepackten PE32+-Modus wird absichtlich fixed-base gelinkt. Absolute
    # Werte werden daher auf die bevorzugte ImageBase geschrieben und es wird
    # keine vor dem Entpacken unbrauchbare .reloc-Sektion benötigt.
    for obj, tbase, dbase in zip(parsed, text_bases, data_bases):
        for relocation in obj.relocations:
            target = global_refs.get(relocation.symbol.casefold())
            if target is None:
                raise PE64AssemblerError(
                    f"COFF64-Symbol nicht aufgeloest: {relocation.symbol}"
                )

            if relocation.section == ".text":
                buffer = text
                patch = tbase + relocation.offset
                patch_rva = text_rva + patch
            elif relocation.section == ".data":
                buffer = init_data
                patch = dbase + relocation.offset
                patch_rva = data_rva + patch
            else:
                raise PE64AssemblerError(
                    "Unbekannte COFF64-Relocation-Sektion: "
                    + str(relocation.section)
                )

            target_rva = symbol_rva(relocation.symbol.casefold())
            if IMAGE_REL_AMD64_REL32 <= relocation.relocation_type <= IMAGE_REL_AMD64_REL32_5:
                tail = relocation.relocation_type - IMAGE_REL_AMD64_REL32
                struct.pack_into(
                    "<i",
                    buffer,
                    patch,
                    target_rva - (patch_rva + 4 + tail),
                )
            elif relocation.relocation_type == IMAGE_REL_AMD64_ADDR64:
                struct.pack_into(
                    "<Q",
                    buffer,
                    patch,
                    int(image_base) + int(target_rva),
                )
            elif relocation.relocation_type == IMAGE_REL_AMD64_ADDR32:
                struct.pack_into(
                    "<I",
                    buffer,
                    patch,
                    (int(image_base) + int(target_rva)) & 0xFFFFFFFF,
                )
            else:
                raise PE64AssemblerError(
                    "COFF64-Relocation "
                    f"0x{relocation.relocation_type:04X} nicht unterstützt."
                )

    for symbol, patches in iat_patches.items():
        if symbol not in iat_rvas:
            raise PE64AssemblerError(
                f"Stage170-PE64: IAT-Eintrag fehlt: {symbol}"
            )
        for patch in patches:
            instruction_end = text_rva + int(patch) + 4
            displacement = int(iat_rvas[symbol]) - instruction_end
            struct.pack_into("<i", text, int(patch), displacement)

    wanted = str(entry_symbol or "").casefold()
    entry_ref = global_refs.get(wanted)
    if entry_ref is None:
        for fallback in ("_start", "start", "main", "_main"):
            if fallback in global_refs:
                entry_ref = global_refs[fallback]
                break
    if entry_ref is None:
        entry_ref = (".text", 0)
    if entry_ref[0] != ".text":
        raise PE64AssemblerError(
            "PE64-Einstiegspunkt muss in der .text-Sektion liegen."
        )
    entry = int(entry_ref[1])
    original_entry_rva = text_rva + entry

    ztext, packed_size = _pe32_build_d64z_payload(
        bytes(text),
        text_rva=text_rva,
        original_entry_rva=original_entry_rva,
    )
    if len(ztext) > ztext_virtual_size:
        raise PE64AssemblerError(
            "Stage170-PE64: MSZIP-Block überschreitet reservierten .ztext-VA-Raum."
        )

    loader = _build_pe64_mszip_loader(
        loader_rva=loader_rva,
        text_rva=text_rva,
        text_size=len(text),
        ztext_rva=ztext_rva,
        packed_size=packed_size,
        original_entry_rva=original_entry_rva,
        iat_rvas=iat_rvas,
    )

    image = _pe_emit_stage170_image(
        machine=IMAGE_FILE_MACHINE_AMD64,
        image_base=image_base,
        text_rva=text_rva,
        text_virtual_size=len(text),
        loader_rva=loader_rva,
        loader=loader,
        ztext_rva=ztext_rva,
        ztext=ztext,
        ztext_virtual_size=ztext_virtual_size,
        idata_rva=idata_rva,
        idata=idata,
        first_iat_rva=first_iat,
        iat_size=iat_size,
        entry_rva=loader_rva,
        gui=gui,
        data_rva=data_rva,
        data=bytes(init_data),
        bss_rva=bss_rva,
        bss_size=total_bss_size,
    )

    public_symbols = {}
    for name, (sec, off) in global_refs.items():
        base_rva = {
            ".text": text_rva,
            ".data": data_rva,
            ".bss": bss_rva,
        }.get(sec, text_rva)
        public_symbols[name] = int(base_rva) - text_rva + int(off)

    return PE64Program(
        image,
        bytes(text),
        entry,
        0,
        public_symbols,
    )


# ---------------------------------------------------------------------------
# Stage 172: PE32 packed-image compactor.
#
# Stage 170/171 deliberately emitted separate .loader and .ztext sections.
# With FileAlignment=0x200 both consume a full 512-byte file block even when
# their logical contents are much smaller.  The compactor below embeds the
# logical D64Z/MSZIP payload immediately after the x86 loader code and removes
# only the now redundant .ztext section.  RVAs of all later sections (notably
# .idata) stay unchanged, so existing IAT addresses and the compressed .text
# do not need to be rewritten/recompressed.
#
# Result for the uploaded Stage-171 sample:
#
#     before: .text | .loader(0x200) | .ztext(0x200) | .idata(0x200)
#             file size 0x800 = 2048
#
#     after : .text | .loader+D64Z(0x200) | .idata(0x200)
#             file size 0x600 = 1536
# ---------------------------------------------------------------------------
PE32_PACK_COMPACTOR_DEFAULT = True
PE32_PACK_COMPACTOR_LAST_RESULT: Dict[str, object] = {}


def _pe32_compactor_fail(
    original: bytes,
    message: str,
    *,
    strict: bool,
) -> bytes:
    PE32_PACK_COMPACTOR_LAST_RESULT.clear()
    PE32_PACK_COMPACTOR_LAST_RESULT.update({
        "changed": False,
        "reason": str(message),
        "before_size": len(original),
        "after_size": len(original),
        "saved_bytes": 0,
    })
    if strict:
        raise PE32AssemblerError(str(message))
    return original


def compact_packed_pe32_image(
    image: bytes,
    *,
    strict: bool = False,
) -> bytes:
    """Compact a Stage-170/171 packed PE32 image without external tools.

    Only the known D64Z x86 loader layout is touched.  Unsupported, signed or
    already compact images are returned byte-identically unless ``strict`` is
    requested.  No PE32+ image is modified by this routine.
    """
    original = bytes(image)

    if len(original) < 0x100 or original[:2] != b"MZ":
        return _pe32_compactor_fail(
            original,
            "PE32-Compactor: MZ-Header fehlt.",
            strict=strict,
        )

    try:
        pe_offset = struct.unpack_from("<I", original, 0x3C)[0]
        if (
            pe_offset + 24 > len(original)
            or original[pe_offset:pe_offset + 4] != b"PE\0\0"
        ):
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: PE-Signatur fehlt.",
                strict=strict,
            )

        file_header = pe_offset + 4
        machine, section_count = struct.unpack_from(
            "<HH", original, file_header
        )
        optional_size = struct.unpack_from(
            "<H", original, file_header + 16
        )[0]
        optional_offset = file_header + 20

        if machine != IMAGE_FILE_MACHINE_I386:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: nur IMAGE_FILE_MACHINE_I386 wird unterstützt.",
                strict=strict,
            )
        if optional_offset + optional_size > len(original):
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: Optional Header ist abgeschnitten.",
                strict=strict,
            )
        if struct.unpack_from("<H", original, optional_offset)[0] != 0x010B:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: PE32-Magic 0x10B fehlt.",
                strict=strict,
            )

        file_alignment = struct.unpack_from(
            "<I", original, optional_offset + 0x24
        )[0]
        section_alignment = struct.unpack_from(
            "<I", original, optional_offset + 0x20
        )[0]
        size_of_headers = struct.unpack_from(
            "<I", original, optional_offset + 0x3C
        )[0]
        image_base = struct.unpack_from(
            "<I", original, optional_offset + 0x1C
        )[0]

        if (
            file_alignment <= 0
            or file_alignment & (file_alignment - 1)
            or section_alignment <= 0
            or section_alignment & (section_alignment - 1)
        ):
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: ungültiges PE-Alignment.",
                strict=strict,
            )

        section_table = optional_offset + optional_size
        section_table_end = section_table + int(section_count) * 40
        if section_table_end > len(original):
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: Section-Tabelle ist abgeschnitten.",
                strict=strict,
            )
        if size_of_headers < section_table_end or size_of_headers > len(original):
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: SizeOfHeaders ist inkonsistent.",
                strict=strict,
            )

        # A PE certificate uses a FILE offset rather than an RVA. Repacking
        # would invalidate both signature and security-directory location.
        security_directory = optional_offset + 0x60 + 4 * 8
        certificate_offset, certificate_size = struct.unpack_from(
            "<II", original, security_directory
        )
        if certificate_offset or certificate_size:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: signierte PE-Dateien werden nicht verändert.",
                strict=strict,
            )

        # IMAGE_DEBUG_DIRECTORY contains PointerToRawData file offsets.  The
        # generated d64 images do not use it; reject foreign debug images rather
        # than silently leaving stale file offsets behind.
        debug_directory = optional_offset + 0x60 + 6 * 8
        debug_rva, debug_size = struct.unpack_from(
            "<II", original, debug_directory
        )
        if debug_rva or debug_size:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: PE-Images mit Debug-Directory werden nicht verändert.",
                strict=strict,
            )

        sections = []
        loader_index = None
        ztext_index = None
        highest_raw_end = int(size_of_headers)

        for index in range(int(section_count)):
            header_offset = section_table + index * 40
            header = bytearray(original[header_offset:header_offset + 40])
            name_bytes = bytes(header[:8]).split(b"\0", 1)[0]
            name = name_bytes.decode("ascii", errors="replace")
            virtual_size, rva, raw_size, raw_ptr = struct.unpack_from(
                "<IIII", header, 0x08
            )
            characteristics = struct.unpack_from("<I", header, 0x24)[0]

            if raw_size:
                if raw_ptr <= 0 or raw_ptr + raw_size > len(original):
                    return _pe32_compactor_fail(
                        original,
                        f"PE32-Compactor: Raw-Daten von {name!r} liegen außerhalb der Datei.",
                        strict=strict,
                    )
                raw_data = bytes(original[raw_ptr:raw_ptr + raw_size])
                highest_raw_end = max(
                    highest_raw_end,
                    int(raw_ptr) + int(raw_size),
                )
            else:
                raw_data = b""

            if name_bytes == b".loader":
                loader_index = index
            elif name_bytes == b".ztext":
                ztext_index = index

            sections.append({
                "header": header,
                "name": name_bytes,
                "name_text": name,
                "virtual_size": int(virtual_size),
                "rva": int(rva),
                "raw_size": int(raw_size),
                "raw_ptr": int(raw_ptr),
                "raw_data": raw_data,
                "chars": int(characteristics),
            })

        if loader_index is None:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: .loader-Sektion fehlt.",
                strict=strict,
            )
        if ztext_index is None:
            # Already compact or not a D64Z packed image: no error in the
            # automatic build path.
            PE32_PACK_COMPACTOR_LAST_RESULT.clear()
            PE32_PACK_COMPACTOR_LAST_RESULT.update({
                "changed": False,
                "reason": "PE32-Compactor: keine separate .ztext-Sektion vorhanden.",
                "before_size": len(original),
                "after_size": len(original),
                "saved_bytes": 0,
            })
            return original
        if int(ztext_index) != int(loader_index) + 1:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: .ztext folgt nicht unmittelbar auf .loader.",
                strict=strict,
            )

        loader = sections[loader_index]
        ztext = sections[ztext_index]
        if loader["raw_size"] <= 0 or ztext["raw_size"] <= 0:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: .loader/.ztext besitzen keine Raw-Daten.",
                strict=strict,
            )
        if loader["virtual_size"] <= 0:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: .loader VirtualSize ist 0.",
                strict=strict,
            )
        if loader["virtual_size"] > loader["raw_size"]:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: Loadercode überschreitet seinen Raw-Block.",
                strict=strict,
            )

        zraw = ztext["raw_data"]
        if len(zraw) < PE32_D64Z_HEADER_SIZE:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: .ztext ist kleiner als der D64Z-Header.",
                strict=strict,
            )

        (
            magic,
            version,
            algorithm,
            flags,
            text_rva,
            text_size,
            packed_size,
            original_entry_rva,
            crc32,
        ) = PE32_D64Z_HEADER.unpack_from(zraw, 0)

        if magic != PE32_D64Z_MAGIC or int(version) != PE32_D64Z_VERSION:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: unbekannter D64Z-Header.",
                strict=strict,
            )
        if int(algorithm) != PE32_COMPRESS_ALGORITHM_MSZIP:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: D64Z benutzt nicht MSZIP.",
                strict=strict,
            )

        logical_ztext_size = PE32_D64Z_HEADER_SIZE + int(packed_size)
        if logical_ztext_size > len(zraw):
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: D64Z PackedSize überschreitet .ztext.",
                strict=strict,
            )

        # Keep the embedded header DWORD-aligned so the layout remains easy to
        # inspect in a PE/hex viewer.  The loader reads only byte addresses.
        embedded_ztext_offset = _align_up(
            int(loader["virtual_size"]),
            4,
        )
        combined_virtual_size = (
            embedded_ztext_offset + logical_ztext_size
        )
        combined_raw_size = _align_up(
            combined_virtual_size,
            int(file_alignment),
        )
        old_pair_raw_size = (
            int(loader["raw_size"])
            + int(ztext["raw_size"])
        )

        if combined_raw_size >= old_pair_raw_size:
            PE32_PACK_COMPACTOR_LAST_RESULT.clear()
            PE32_PACK_COMPACTOR_LAST_RESULT.update({
                "changed": False,
                "reason": (
                    "PE32-Compactor: .loader + D64Z sparen bei diesem "
                    "FileAlignment keinen Raw-Block."
                ),
                "before_size": len(original),
                "after_size": len(original),
                "saved_bytes": 0,
                "loader_size": int(loader["virtual_size"]),
                "ztext_logical_size": logical_ztext_size,
                "combined_raw_size": combined_raw_size,
                "old_pair_raw_size": old_pair_raw_size,
            })
            return original

        loader_code = bytearray(
            loader["raw_data"][:int(loader["virtual_size"])]
        )

        old_packed_va = (
            int(image_base)
            + int(ztext["rva"])
            + PE32_D64Z_HEADER_SIZE
        ) & 0xFFFFFFFF
        new_ztext_rva = (
            int(loader["rva"])
            + embedded_ztext_offset
        )
        new_packed_va = (
            int(image_base)
            + new_ztext_rva
            + PE32_D64Z_HEADER_SIZE
        ) & 0xFFFFFFFF

        # Stage-169/170 x86 loader emits exactly:
        #     push old_packed_va
        # before Decompress().  Require the opcode as part of the signature so
        # a coincidental DWORD elsewhere in code is not modified.
        old_push = b"\x68" + struct.pack("<I", old_packed_va)
        new_push = b"\x68" + struct.pack("<I", new_packed_va)
        matches = []
        cursor = 0
        while True:
            position = loader_code.find(old_push, cursor)
            if position < 0:
                break
            matches.append(position)
            cursor = position + 1

        if len(matches) != 1:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: eindeutige Loader-PackedVA-Signatur fehlt.",
                strict=strict,
            )
        position = matches[0]
        loader_code[position:position + len(old_push)] = new_push

        compact_loader_data = bytearray(combined_raw_size)
        compact_loader_data[:len(loader_code)] = loader_code
        compact_loader_data[
            embedded_ztext_offset:
            embedded_ztext_offset + logical_ztext_size
        ] = zraw[:logical_ztext_size]

        # Remove only .ztext.  All later RVAs stay byte-identical; only their
        # physical PointerToRawData values are packed left.
        compact_sections = [
            dict(section)
            for index, section in enumerate(sections)
            if index != ztext_index
        ]
        compact_loader = compact_sections[loader_index]
        compact_loader["virtual_size"] = combined_virtual_size
        compact_loader["raw_size"] = combined_raw_size
        compact_loader["raw_data"] = bytes(compact_loader_data)

        raw_cursor = int(size_of_headers)
        for section in compact_sections:
            raw_size = int(section["raw_size"])
            if raw_size > 0:
                section["raw_ptr"] = raw_cursor
                raw_cursor += raw_size
            else:
                section["raw_ptr"] = 0

        overlay = (
            original[highest_raw_end:]
            if highest_raw_end < len(original)
            else b""
        )

        rebuilt = bytearray(size_of_headers)
        rebuilt[:section_table] = original[:section_table]

        new_section_count = len(compact_sections)
        struct.pack_into(
            "<H",
            rebuilt,
            file_header + 2,
            new_section_count,
        )

        size_of_code = 0
        size_of_initialized_data = 0
        for section in compact_sections:
            raw_size = int(section["raw_size"])
            chars = int(section["chars"])
            if chars & 0x00000020:
                size_of_code += raw_size
            elif raw_size and chars & 0x00000040:
                size_of_initialized_data += raw_size

        struct.pack_into(
            "<I", rebuilt, optional_offset + 0x04, size_of_code
        )
        struct.pack_into(
            "<I", rebuilt, optional_offset + 0x08, size_of_initialized_data
        )

        # BaseOfData should refer to the first remaining data section.  The
        # original Stage170 image pointed it at .ztext.
        first_data_rva = 0
        for section in compact_sections:
            chars = int(section["chars"])
            if chars & 0x00000040 and not (chars & 0x00000020):
                first_data_rva = int(section["rva"])
                break
        if first_data_rva:
            struct.pack_into(
                "<I", rebuilt, optional_offset + 0x18, first_data_rva
            )

        # SizeOfImage can safely shrink only if the removed section was the
        # final one.  In normal packed images .idata follows it, so the value
        # remains unchanged.  Recompute generically from remaining RVAs.
        if compact_sections:
            last_virtual_end = max(
                int(section["rva"])
                + max(1, int(section["virtual_size"]))
                for section in compact_sections
            )
            struct.pack_into(
                "<I",
                rebuilt,
                optional_offset + 0x38,
                _align_up(last_virtual_end, int(section_alignment)),
            )

        # Rewrite compacted section headers and clear the no-longer-used slot.
        for index, section in enumerate(compact_sections):
            header = bytearray(section["header"])
            struct.pack_into(
                "<I", header, 0x08, int(section["virtual_size"])
            )
            struct.pack_into(
                "<I", header, 0x0C, int(section["rva"])
            )
            struct.pack_into(
                "<I", header, 0x10, int(section["raw_size"])
            )
            struct.pack_into(
                "<I", header, 0x14, int(section["raw_ptr"])
            )
            destination = section_table + index * 40
            rebuilt[destination:destination + 40] = header

        old_last_slot = section_table + (new_section_count * 40)
        if old_last_slot + 40 <= size_of_headers:
            rebuilt[old_last_slot:old_last_slot + 40] = bytes(40)

        # Raw sections are now tightly packed at FileAlignment boundaries.
        for section in compact_sections:
            raw_size = int(section["raw_size"])
            if raw_size <= 0:
                continue
            raw_ptr = int(section["raw_ptr"])
            raw_data = bytes(section["raw_data"])
            if len(raw_data) > raw_size:
                return _pe32_compactor_fail(
                    original,
                    f"PE32-Compactor: {section['name_text']} überschreitet SizeOfRawData.",
                    strict=strict,
                )
            if len(rebuilt) < raw_ptr + raw_size:
                rebuilt.extend(
                    bytes(raw_ptr + raw_size - len(rebuilt))
                )
            rebuilt[raw_ptr:raw_ptr + len(raw_data)] = raw_data

        if overlay:
            rebuilt.extend(overlay)

        result = bytes(rebuilt)
        PE32_PACK_COMPACTOR_LAST_RESULT.clear()
        PE32_PACK_COMPACTOR_LAST_RESULT.update({
            "changed": True,
            "reason": "PE32-Compactor: .ztext erfolgreich in .loader eingebettet.",
            "before_size": len(original),
            "after_size": len(result),
            "saved_bytes": len(original) - len(result),
            "loader_rva": int(loader["rva"]),
            "embedded_ztext_rva": new_ztext_rva,
            "embedded_ztext_offset": embedded_ztext_offset,
            "loader_code_size": int(loader["virtual_size"]),
            "ztext_logical_size": logical_ztext_size,
            "combined_virtual_size": combined_virtual_size,
            "combined_raw_size": combined_raw_size,
            "old_pair_raw_size": old_pair_raw_size,
            "old_packed_va": old_packed_va,
            "new_packed_va": new_packed_va,
        })
        return result

    except (struct.error, OverflowError, ValueError) as exc:
        return _pe32_compactor_fail(
            original,
            f"PE32-Compactor: ungültiges PE-Layout: {exc}",
            strict=strict,
        )


# Keep a reference to the complete Stage-171 PE32 writer.  The new wrapper is
# additive and only post-processes a successfully built packed PE32 image.
_build_pe32_image_with_imports_exports_stage171 = (
    build_pe32_image_with_imports_exports
)


def build_pe32_image_with_imports_exports(
    code: bytes,
    entry_offset: Optional[int],
    import_specs,
    thunk_patches: Dict[str, int],
    *,
    exports: Optional[Dict[str, int]] = None,
    dll_name: str = "library.dll",
    gui: bool = False,
    dll: bool = False,
    image_base: int = PE32_IMAGE_BASE,
    base_relocations: Optional[Sequence[int]] = None,
    compress_text_mszip: Optional[bool] = None,
    imports_by_local_ordinal: Optional[bool] = None,
    compact_packed_image: Optional[bool] = None,
    bss_size: int = 0,
) -> Tuple[bytes, bytes]:
    """Stage172 wrapper: Stage171 build + optional safe packed-PE32 compact."""
    image, patched_text = _build_pe32_image_with_imports_exports_stage171(
        code,
        entry_offset,
        import_specs,
        thunk_patches,
        exports=exports,
        dll_name=dll_name,
        gui=gui,
        dll=dll,
        image_base=image_base,
        base_relocations=base_relocations,
        compress_text_mszip=compress_text_mszip,
        imports_by_local_ordinal=imports_by_local_ordinal,
        bss_size=bss_size,
    )

    if compact_packed_image is None:
        compact_packed_image = PE32_PACK_COMPACTOR_DEFAULT

    if bool(compact_packed_image) and not bool(dll):
        image = compact_packed_pe32_image(
            image,
            strict=False,
        )

    return image, patched_text


# ---------------------------------------------------------------------------
# Stage 173: conservative PE32 compactor correction.
#
# Windows rejected the aggressive Stage-172 variant on the user's real system.
# Keep the complete virtual section table now.  Only the redundant physical
# .ztext raw block disappears.  This leaves NumberOfSections, section RVAs,
# BaseOfData, SizeOfImage and all PE data-directory RVAs exactly as generated
# by the known-working Stage-171/172 writer.
# ---------------------------------------------------------------------------
_compact_packed_pe32_image_stage172 = compact_packed_pe32_image


def compact_packed_pe32_image(
    image: bytes,
    *,
    strict: bool = False,
) -> bytes:
    """Conservatively compact D64Z PE32 while retaining the .ztext section.

    Physical layout after compaction:

        headers | .loader + embedded D64Z | .idata | ...

    Virtual PE layout remains:

        .text | .loader | .ztext | .idata | ...

    .ztext simply becomes a zero-raw virtual placeholder.  This deliberately
    preserves the Windows-loader-visible section topology of the original PE.
    """
    original = bytes(image)

    if len(original) < 0x100 or original[:2] != b"MZ":
        return _pe32_compactor_fail(
            original,
            "PE32-Compactor: MZ-Header fehlt.",
            strict=strict,
        )

    try:
        pe_offset = struct.unpack_from("<I", original, 0x3C)[0]
        if (
            pe_offset + 24 > len(original)
            or original[pe_offset:pe_offset + 4] != b"PE\0\0"
        ):
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: PE-Signatur fehlt.",
                strict=strict,
            )

        file_header = pe_offset + 4
        machine, section_count = struct.unpack_from(
            "<HH", original, file_header
        )
        optional_size = struct.unpack_from(
            "<H", original, file_header + 16
        )[0]
        optional_offset = file_header + 20

        if machine != IMAGE_FILE_MACHINE_I386:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: nur i386/PE32 wird unterstützt.",
                strict=strict,
            )
        if optional_offset + optional_size > len(original):
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: Optional Header ist abgeschnitten.",
                strict=strict,
            )
        if struct.unpack_from("<H", original, optional_offset)[0] != 0x010B:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: PE32-Magic 0x10B fehlt.",
                strict=strict,
            )

        file_alignment = struct.unpack_from(
            "<I", original, optional_offset + 0x24
        )[0]
        size_of_headers = struct.unpack_from(
            "<I", original, optional_offset + 0x3C
        )[0]
        image_base = struct.unpack_from(
            "<I", original, optional_offset + 0x1C
        )[0]

        if file_alignment <= 0 or file_alignment & (file_alignment - 1):
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: ungültiges FileAlignment.",
                strict=strict,
            )

        section_table = optional_offset + optional_size
        if section_table + int(section_count) * 40 > int(size_of_headers):
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: Section-Tabelle überschreitet SizeOfHeaders.",
                strict=strict,
            )

        # Do not rewrite images containing file-offset based PE directories.
        security_offset, security_size = struct.unpack_from(
            "<II", original, optional_offset + 0x60 + 4 * 8
        )
        if security_offset or security_size:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: signierte PE-Dateien werden nicht verändert.",
                strict=strict,
            )
        debug_rva, debug_size = struct.unpack_from(
            "<II", original, optional_offset + 0x60 + 6 * 8
        )
        if debug_rva or debug_size:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: Debug-Directory verhindert Raw-Repacking.",
                strict=strict,
            )

        sections = []
        loader_index = None
        ztext_index = None
        highest_raw_end = int(size_of_headers)

        for index in range(int(section_count)):
            off = section_table + index * 40
            header = bytearray(original[off:off + 40])
            name = bytes(header[:8]).split(b"\0", 1)[0]
            virtual_size, rva, raw_size, raw_ptr = struct.unpack_from(
                "<IIII", header, 0x08
            )
            chars = struct.unpack_from("<I", header, 0x24)[0]
            if raw_size:
                if raw_ptr <= 0 or raw_ptr + raw_size > len(original):
                    return _pe32_compactor_fail(
                        original,
                        f"PE32-Compactor: Raw-Bereich von {name!r} ist ungültig.",
                        strict=strict,
                    )
                raw_data = bytes(
                    original[raw_ptr:raw_ptr + raw_size]
                )
                highest_raw_end = max(
                    highest_raw_end,
                    int(raw_ptr) + int(raw_size),
                )
            else:
                raw_data = b""

            if name == b".loader":
                loader_index = index
            elif name == b".ztext":
                ztext_index = index

            sections.append({
                "header": header,
                "name": name,
                "virtual_size": int(virtual_size),
                "rva": int(rva),
                "raw_size": int(raw_size),
                "raw_ptr": int(raw_ptr),
                "raw_data": raw_data,
                "chars": int(chars),
            })

        if loader_index is None:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: .loader fehlt.",
                strict=strict,
            )
        if ztext_index is None:
            PE32_PACK_COMPACTOR_LAST_RESULT.clear()
            PE32_PACK_COMPACTOR_LAST_RESULT.update({
                "changed": False,
                "reason": "PE32-Compactor: keine separate .ztext-Sektion vorhanden.",
                "before_size": len(original),
                "after_size": len(original),
                "saved_bytes": 0,
            })
            return original
        if int(ztext_index) != int(loader_index) + 1:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: .ztext folgt nicht direkt auf .loader.",
                strict=strict,
            )

        loader = sections[loader_index]
        ztext = sections[ztext_index]

        # Already Stage-173 compact: .ztext remains visible but owns no file
        # block. Return byte-identically on a second pass.
        if int(ztext["raw_size"]) == 0 and int(ztext["raw_ptr"]) == 0:
            PE32_PACK_COMPACTOR_LAST_RESULT.clear()
            PE32_PACK_COMPACTOR_LAST_RESULT.update({
                "changed": False,
                "reason": "PE32-Compactor: .ztext ist bereits raw-frei.",
                "before_size": len(original),
                "after_size": len(original),
                "saved_bytes": 0,
            })
            return original

        if loader["raw_size"] <= 0 or ztext["raw_size"] <= 0:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: .loader/.ztext besitzen keine Raw-Daten.",
                strict=strict,
            )
        if loader["virtual_size"] <= 0 or loader["virtual_size"] > loader["raw_size"]:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: ungültige .loader-Größe.",
                strict=strict,
            )

        zraw = bytes(ztext["raw_data"])
        if len(zraw) < PE32_D64Z_HEADER_SIZE:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: D64Z-Header fehlt.",
                strict=strict,
            )

        (
            magic,
            version,
            algorithm,
            flags,
            text_rva,
            text_size,
            packed_size,
            original_entry_rva,
            crc32,
        ) = PE32_D64Z_HEADER.unpack_from(zraw, 0)

        if (
            magic != PE32_D64Z_MAGIC
            or int(version) != PE32_D64Z_VERSION
            or int(algorithm) != PE32_COMPRESS_ALGORITHM_MSZIP
        ):
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: unbekanntes D64Z/MSZIP-Format.",
                strict=strict,
            )

        logical_ztext_size = PE32_D64Z_HEADER_SIZE + int(packed_size)
        if logical_ztext_size > len(zraw):
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: PackedSize überschreitet .ztext RawSize.",
                strict=strict,
            )

        embedded_offset = _align_up(
            int(loader["virtual_size"]),
            4,
        )
        combined_virtual_size = embedded_offset + logical_ztext_size
        combined_raw_size = _align_up(
            combined_virtual_size,
            int(file_alignment),
        )
        old_pair_raw_size = int(loader["raw_size"]) + int(ztext["raw_size"])

        if combined_raw_size >= old_pair_raw_size:
            PE32_PACK_COMPACTOR_LAST_RESULT.clear()
            PE32_PACK_COMPACTOR_LAST_RESULT.update({
                "changed": False,
                "reason": "PE32-Compactor: kein FileAlignment-Block einsparbar.",
                "before_size": len(original),
                "after_size": len(original),
                "saved_bytes": 0,
            })
            return original

        loader_code = bytearray(
            loader["raw_data"][:int(loader["virtual_size"])]
        )
        old_packed_va = (
            int(image_base)
            + int(ztext["rva"])
            + PE32_D64Z_HEADER_SIZE
        ) & 0xFFFFFFFF
        embedded_ztext_rva = int(loader["rva"]) + embedded_offset
        new_packed_va = (
            int(image_base)
            + embedded_ztext_rva
            + PE32_D64Z_HEADER_SIZE
        ) & 0xFFFFFFFF

        old_push = b"\x68" + struct.pack("<I", old_packed_va)
        new_push = b"\x68" + struct.pack("<I", new_packed_va)
        matches = []
        pos = 0
        while True:
            hit = loader_code.find(old_push, pos)
            if hit < 0:
                break
            matches.append(hit)
            pos = hit + 1
        if len(matches) != 1:
            return _pe32_compactor_fail(
                original,
                "PE32-Compactor: Loader-PackedVA-Signatur ist nicht eindeutig.",
                strict=strict,
            )
        hit = matches[0]
        loader_code[hit:hit + len(old_push)] = new_push

        combined = bytearray(combined_raw_size)
        combined[:len(loader_code)] = loader_code
        combined[
            embedded_offset:embedded_offset + logical_ztext_size
        ] = zraw[:logical_ztext_size]

        # Preserve every section entry and every RVA. Only physical ownership
        # changes: .loader grows inside the same 0x200 raw block, .ztext loses
        # its raw block, following raw sections slide left.
        loader["virtual_size"] = combined_virtual_size
        loader["raw_size"] = combined_raw_size
        loader["raw_data"] = bytes(combined)
        ztext["raw_size"] = 0
        ztext["raw_ptr"] = 0
        ztext["raw_data"] = b""

        raw_cursor = int(size_of_headers)
        for section in sections:
            raw_size = int(section["raw_size"])
            if raw_size > 0:
                section["raw_ptr"] = raw_cursor
                raw_cursor += raw_size
            else:
                section["raw_ptr"] = 0

        overlay = (
            original[highest_raw_end:]
            if highest_raw_end < len(original)
            else b""
        )

        # Copy the complete original header first. Do NOT change section count,
        # BaseOfData, SizeOfImage, SizeOfInitializedData or any data directory.
        rebuilt = bytearray(original[:int(size_of_headers)])

        for index, section in enumerate(sections):
            header = bytearray(section["header"])
            struct.pack_into(
                "<I", header, 0x08, int(section["virtual_size"])
            )
            struct.pack_into(
                "<I", header, 0x10, int(section["raw_size"])
            )
            struct.pack_into(
                "<I", header, 0x14, int(section["raw_ptr"])
            )
            destination = section_table + index * 40
            rebuilt[destination:destination + 40] = header

        for section in sections:
            raw_size = int(section["raw_size"])
            if raw_size <= 0:
                continue
            raw_ptr = int(section["raw_ptr"])
            raw_data = bytes(section["raw_data"])
            if len(raw_data) > raw_size:
                return _pe32_compactor_fail(
                    original,
                    "PE32-Compactor: Raw-Daten überschreiten SizeOfRawData.",
                    strict=strict,
                )
            if len(rebuilt) < raw_ptr + raw_size:
                rebuilt.extend(bytes(raw_ptr + raw_size - len(rebuilt)))
            rebuilt[raw_ptr:raw_ptr + len(raw_data)] = raw_data

        if overlay:
            rebuilt.extend(overlay)

        result = bytes(rebuilt)
        PE32_PACK_COMPACTOR_LAST_RESULT.clear()
        PE32_PACK_COMPACTOR_LAST_RESULT.update({
            "changed": True,
            "reason": (
                "PE32-Compactor Stage173: .ztext-RVA/Section beibehalten; "
                "nur Raw-Daten in .loader eingebettet."
            ),
            "before_size": len(original),
            "after_size": len(result),
            "saved_bytes": len(original) - len(result),
            "section_count_preserved": int(section_count),
            "ztext_rva_preserved": int(ztext["rva"]),
            "ztext_virtual_size_preserved": int(ztext["virtual_size"]),
            "ztext_raw_size": 0,
            "embedded_ztext_rva": embedded_ztext_rva,
            "embedded_ztext_offset": embedded_offset,
            "old_packed_va": old_packed_va,
            "new_packed_va": new_packed_va,
        })
        return result

    except (struct.error, ValueError, OverflowError) as exc:
        return _pe32_compactor_fail(
            original,
            f"PE32-Compactor: ungültiges PE-Layout: {exc}",
            strict=strict,
        )


# ---------------------------------------------------------------------------
# Windows-Grafik-ABI. Die Compiler können über target='pe32'/'pe64' und die
# Präprozessor-Symbole die passende Runtime auswählen. Die eigentliche
# Direct2D/Direct3D-Runtime kann dadurch plattformgetrennt bleiben, während
# die öffentliche Grafik-API identisch bleibt.
# ---------------------------------------------------------------------------
def windows_graphics_predefined_macros(backend: str, target: str = "pe32") -> Dict[str, str]:
    selected = normalize_windows_graphics_backend(backend)
    target_key = str(target or "pe32").strip().casefold()
    macros = {
        "__D64_TARGET_PE64__" if target_key in {"pe64", "win64", "windows64", "windows-pe64"}
        else "__D64_TARGET_PE32__": "1",
        "__D64_GRAPHICS_WINDOWS__": "1",
    }
    if selected == "Direct3D":
        macros["__D64_GRAPHICS_DIRECT3D__"] = "1"
    else:
        macros["__D64_GRAPHICS_DIRECT2D__"] = "1"
    return macros


WINDOWS_GRAPHICS_RUNTIME_HEADER = r'''#ifndef D64_WINDOWS_GRAPHICS_H
#define D64_WINDOWS_GRAPHICS_H

#include <stdint.h>

#if defined(_WIN32)
# if defined(D64_GRAPHICS_RUNTIME_EXPORTS)
#  define D64_GRAPHICS_API __declspec(dllexport)
# else
#  define D64_GRAPHICS_API __declspec(dllimport)
# endif
#else
# define D64_GRAPHICS_API
#endif

#ifdef __cplusplus
extern "C" {
#endif

#define GRAPHICS_WIDTH  320
#define GRAPHICS_HEIGHT 200

typedef uint8_t GraphicsColor;
typedef uint8_t TextMode;

D64_GRAPHICS_API void SetTextColor(unsigned int foreground, unsigned int background);
D64_GRAPHICS_API void ClearScreen(void);
D64_GRAPHICS_API void InitGraphics(void);
D64_GRAPHICS_API void InitGraphics320x200(void);
D64_GRAPHICS_API int GraphicsWindowOpen(void);
D64_GRAPHICS_API void DoneGraphics(TextMode mode);
D64_GRAPHICS_API void SetPixel(int x, int y, GraphicsColor color);
D64_GRAPHICS_API GraphicsColor GetPixel(int x, int y);
D64_GRAPHICS_API void DrawLine(int x1, int y1, int x2, int y2, GraphicsColor color);
D64_GRAPHICS_API void DrawRect(int x1, int y1, int x2, int y2, GraphicsColor color);
D64_GRAPHICS_API void FillRect(
    int x1, int y1, int x2, int y2,
    GraphicsColor fillColor,
    GraphicsColor borderColor,
    unsigned int borderWidth);
D64_GRAPHICS_API void DrawCircle(int centerX, int centerY, int radius, GraphicsColor color);
D64_GRAPHICS_API void FillCircle(
    int centerX, int centerY, int radius,
    GraphicsColor fillColor,
    GraphicsColor borderColor,
    unsigned int borderWidth);
D64_GRAPHICS_API void FloodFill(int x, int y, GraphicsColor fillColor);
D64_GRAPHICS_API void DrawTriangle(
    int x1, int y1, int x2, int y2,
    int x3, int y3, GraphicsColor color);
D64_GRAPHICS_API void FillTriangle(
    int x1, int y1, int x2, int y2,
    int x3, int y3,
    GraphicsColor fillColor,
    GraphicsColor borderColor,
    unsigned int borderWidth);
D64_GRAPHICS_API void DrawTriangleAngles(
    int centerX, int centerY,
    int radius1, int radius2, int radius3,
    int angle1, int angle2, int angle3,
    GraphicsColor color);

#ifdef __cplusplus
}
#endif

#endif
'''


def write_windows_graphics_runtime_header(path: Path) -> Path:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(WINDOWS_GRAPHICS_RUNTIME_HEADER, encoding="utf-8", newline="\n")
    return target

WINDOWS_GRAPHICS_RUNTIME_CPP = r'''#define WIN32_LEAN_AND_MEAN
#define D64_GRAPHICS_RUNTIME_EXPORTS 1
#include <windows.h>
#include <stdint.h>
#include <string.h>
#include "graphics_windows.h"

#if defined(__D64_GRAPHICS_DIRECT3D__)
# include <d3d9.h>
#else
# include <d2d1.h>
# include <dxgiformat.h>
#endif

static HWND g_hwnd = 0;
static uint32_t g_pixels[320 * 200];
static uint32_t g_logical_pixels[320 * 200];
static unsigned int g_present_divider = 0;
static unsigned int g_text_foreground = 1;
static unsigned int g_text_background = 0;
static unsigned int g_output_width = 640;
static unsigned int g_output_height = 400;

static const uint32_t g_c64_palette[16] = {
    0x000000,0xFFFFFF,0x883932,0x67B6BD,
    0x8B3F96,0x55A049,0x40318D,0xBFCE72,
    0x8B5429,0x574200,0xB86962,0x505050,
    0x787878,0x94E089,0x7869C4,0x9F9F9F
};

static uint32_t d64_color(unsigned int value)
{
    if (value < 16) value = g_c64_palette[value];
    return 0xFF000000u | (value & 0x00FFFFFFu);
}

static LRESULT CALLBACK d64_wndproc(HWND hwnd, UINT msg, WPARAM wp, LPARAM lp)
{
    if (msg == WM_CLOSE) { DestroyWindow(hwnd); return 0; }
    if (msg == WM_DESTROY) { g_hwnd = 0; return 0; }
    return DefWindowProcA(hwnd, msg, wp, lp);
}

static void d64_pump_messages(void)
{
    MSG msg;
    while (PeekMessageA(&msg, 0, 0, 0, PM_REMOVE)) {
        TranslateMessage(&msg);
        DispatchMessageA(&msg);
    }
}

#if defined(__D64_GRAPHICS_DIRECT3D__)
static IDirect3D9 *g_d3d = 0;
static IDirect3DDevice9 *g_device = 0;

static int d64_create_renderer(void)
{
    D3DPRESENT_PARAMETERS pp;
    ZeroMemory(&pp, sizeof(pp));
    pp.Windowed = TRUE;
    pp.SwapEffect = D3DSWAPEFFECT_DISCARD;
    pp.hDeviceWindow = g_hwnd;
    pp.BackBufferWidth = g_output_width;
    pp.BackBufferHeight = g_output_height;
    pp.BackBufferFormat = D3DFMT_X8R8G8B8;
    pp.PresentationInterval = D3DPRESENT_INTERVAL_ONE;
    pp.Flags = D3DPRESENTFLAG_LOCKABLE_BACKBUFFER;

    g_d3d = Direct3DCreate9(D3D_SDK_VERSION);
    if (!g_d3d) return 0;
    if (FAILED(g_d3d->CreateDevice(
        D3DADAPTER_DEFAULT, D3DDEVTYPE_HAL, g_hwnd,
        D3DCREATE_SOFTWARE_VERTEXPROCESSING, &pp, &g_device))) {
        return 0;
    }
    return 1;
}

static void d64_present(void)
{
    if (!g_device || !g_hwnd) return;
    IDirect3DSurface9 *back = 0;
    if (FAILED(g_device->GetBackBuffer(0, 0, D3DBACKBUFFER_TYPE_MONO, &back))) return;
    D3DLOCKED_RECT lock;
    if (SUCCEEDED(back->LockRect(&lock, 0, 0))) {
        for (unsigned int y = 0; y < g_output_height; ++y) {
            uint32_t *dst = (uint32_t *)((unsigned char *)lock.pBits + y * lock.Pitch);
            unsigned int src_y = (y * 200u) / g_output_height;
            for (unsigned int x = 0; x < g_output_width; ++x) {
                unsigned int src_x = (x * 320u) / g_output_width;
                dst[x] = g_pixels[src_y * 320u + src_x];
            }
        }
        back->UnlockRect();
    }
    back->Release();
    g_device->Present(0, 0, 0, 0);
    d64_pump_messages();
}

static void d64_destroy_renderer(void)
{
    if (g_device) { g_device->Release(); g_device = 0; }
    if (g_d3d) { g_d3d->Release(); g_d3d = 0; }
}
#else
static ID2D1Factory *g_factory = 0;
static ID2D1HwndRenderTarget *g_target = 0;
static ID2D1Bitmap *g_bitmap = 0;

static int d64_create_renderer(void)
{
    HRESULT hr = D2D1CreateFactory(D2D1_FACTORY_TYPE_SINGLE_THREADED, &g_factory);
    if (FAILED(hr)) return 0;
    D2D1_RENDER_TARGET_PROPERTIES props = D2D1::RenderTargetProperties();
    D2D1_HWND_RENDER_TARGET_PROPERTIES hwndProps =
        D2D1::HwndRenderTargetProperties(g_hwnd, D2D1::SizeU(g_output_width, g_output_height));
    hr = g_factory->CreateHwndRenderTarget(props, hwndProps, &g_target);
    if (FAILED(hr)) return 0;
    D2D1_BITMAP_PROPERTIES bp = D2D1::BitmapProperties(
        D2D1::PixelFormat(DXGI_FORMAT_B8G8R8A8_UNORM, D2D1_ALPHA_MODE_IGNORE));
    hr = g_target->CreateBitmap(D2D1::SizeU(320, 200), 0, 0, &bp, &g_bitmap);
    return SUCCEEDED(hr);
}

static void d64_present(void)
{
    if (!g_target || !g_bitmap || !g_hwnd) return;
    g_bitmap->CopyFromMemory(0, g_pixels, 320 * 4);
    g_target->BeginDraw();
    g_target->Clear(D2D1::ColorF(D2D1::ColorF::Black));
    g_target->DrawBitmap(
        g_bitmap,
        D2D1::RectF(0.0f, 0.0f, (FLOAT)g_output_width, (FLOAT)g_output_height),
        1.0f,
        D2D1_BITMAP_INTERPOLATION_MODE_NEAREST_NEIGHBOR);
    g_target->EndDraw();
    d64_pump_messages();
}

static void d64_destroy_renderer(void)
{
    if (g_bitmap) { g_bitmap->Release(); g_bitmap = 0; }
    if (g_target) { g_target->Release(); g_target = 0; }
    if (g_factory) { g_factory->Release(); g_factory = 0; }
}
#endif

D64_GRAPHICS_API void SetTextColor(unsigned int foreground, unsigned int background)
{
    g_text_foreground = foreground;
    g_text_background = background;
}

static void d64_init_graphics_window(unsigned int client_width, unsigned int client_height)
{
    if (g_hwnd) DoneGraphics(0);
    g_output_width = client_width ? client_width : 320u;
    g_output_height = client_height ? client_height : 200u;

    WNDCLASSEXA wc;
    ZeroMemory(&wc, sizeof(wc));
    wc.cbSize = sizeof(wc);
    wc.lpfnWndProc = d64_wndproc;
    wc.hInstance = GetModuleHandleA(0);
    wc.hCursor = LoadCursorA(0, IDC_ARROW);
    wc.lpszClassName = "dBase2ManyGraphicsWindow";
    RegisterClassExA(&wc);

    const DWORD style = WS_OVERLAPPEDWINDOW | WS_VISIBLE;
    RECT window_rect = {0, 0, (LONG)g_output_width, (LONG)g_output_height};
    AdjustWindowRect(&window_rect, style, FALSE);
    g_hwnd = CreateWindowExA(
        0, wc.lpszClassName, "dBase2Many - 320x200 Graphics",
        style,
        CW_USEDEFAULT, CW_USEDEFAULT,
        window_rect.right - window_rect.left,
        window_rect.bottom - window_rect.top,
        0, 0, wc.hInstance, 0);
    memset(g_pixels, 0, sizeof(g_pixels));
    memset(g_logical_pixels, 0, sizeof(g_logical_pixels));
    d64_create_renderer();
    d64_present();
}

D64_GRAPHICS_API void InitGraphics(void)
{
    /* Bestehendes Verhalten: 320x200 logisch, 2x vergrößert dargestellt. */
    d64_init_graphics_window(640u, 400u);
}

D64_GRAPHICS_API void InitGraphics320x200(void)
{
    /* LOGO: tatsächliche Client-Zeichenfläche exakt 320x200 Pixel. */
    d64_init_graphics_window(320u, 200u);
}

D64_GRAPHICS_API int GraphicsWindowOpen(void)
{
    d64_pump_messages();
    return g_hwnd ? 1 : 0;
}

D64_GRAPHICS_API void DoneGraphics(TextMode mode)
{
    (void)mode;
    d64_present();
    d64_destroy_renderer();
    if (g_hwnd) { DestroyWindow(g_hwnd); g_hwnd = 0; }
}

D64_GRAPHICS_API void ClearScreen(void)
{
    const unsigned int color = 0;
    uint32_t value = d64_color(color);
    for (int i = 0; i < 320 * 200; ++i) {
        g_pixels[i] = value;
        g_logical_pixels[i] = color;
    }
    d64_present();
}

D64_GRAPHICS_API void SetPixel(int x, int y, GraphicsColor color)
{
    if ((unsigned)x >= 320u || (unsigned)y >= 200u) return;
    g_pixels[y * 320 + x] = d64_color(color);
    g_logical_pixels[y * 320 + x] = color;
    if ((++g_present_divider & 255u) == 0u) d64_present();
}

D64_GRAPHICS_API GraphicsColor GetPixel(int x, int y)
{
    if ((unsigned)x >= 320u || (unsigned)y >= 200u) return 0;
    return (GraphicsColor)(g_logical_pixels[y * 320 + x] & 0xFFu);
}

D64_GRAPHICS_API void DrawLine(int x1,int y1,int x2,int y2,GraphicsColor c)
{
    int dx = x2 > x1 ? x2-x1 : x1-x2;
    int sx = x1 < x2 ? 1 : -1;
    int dy = -(y2 > y1 ? y2-y1 : y1-y2);
    int sy = y1 < y2 ? 1 : -1;
    int err = dx + dy;
    for (;;) {
        SetPixel(x1,y1,c);
        if (x1 == x2 && y1 == y2) break;
        int e2 = err << 1;
        if (e2 >= dy) { err += dy; x1 += sx; }
        if (e2 <= dx) { err += dx; y1 += sy; }
    }
    d64_present();
}

D64_GRAPHICS_API void DrawRect(int x1,int y1,int x2,int y2,GraphicsColor c)
{
    DrawLine(x1,y1,x2,y1,c); DrawLine(x2,y1,x2,y2,c);
    DrawLine(x2,y2,x1,y2,c); DrawLine(x1,y2,x1,y1,c);
}

D64_GRAPHICS_API void FillRect(
    int x1,int y1,int x2,int y2,GraphicsColor fill,
    GraphicsColor border,unsigned int bw)
{
    if (x1 > x2) { int t=x1; x1=x2; x2=t; }
    if (y1 > y2) { int t=y1; y1=y2; y2=t; }
    for (int y=y1;y<=y2;++y) for (int x=x1;x<=x2;++x) SetPixel(x,y,fill);
    for (int i=0;i<bw;++i) DrawRect(x1+i,y1+i,x2-i,y2-i,border);
    d64_present();
}

D64_GRAPHICS_API void DrawCircle(int cx,int cy,int r,GraphicsColor c)
{
    int x=r,y=0,d=1-r;
    while (x>=y) {
        SetPixel(cx+x,cy+y,c);SetPixel(cx-x,cy+y,c);
        SetPixel(cx+x,cy-y,c);SetPixel(cx-x,cy-y,c);
        SetPixel(cx+y,cy+x,c);SetPixel(cx-y,cy+x,c);
        SetPixel(cx+y,cy-x,c);SetPixel(cx-y,cy-x,c);
        ++y; if (d<0) d+=2*y+1; else { --x; d+=2*(y-x)+1; }
    }
    d64_present();
}

D64_GRAPHICS_API void FillCircle(int cx,int cy,int r,GraphicsColor fill,
                GraphicsColor border,unsigned int bw)
{
    for (int y=-r;y<=r;++y) {
        int xx=0; while ((xx+1)*(xx+1)+y*y<=r*r) ++xx;
        DrawLine(cx-xx,cy+y,cx+xx,cy+y,fill);
    }
    for (int i=0;i<bw;++i) DrawCircle(cx,cy,r-i,border);
    d64_present();
}

static void d64_hline(int x1, int y, int x2, GraphicsColor color)
{
    if (y < 0 || y >= GRAPHICS_HEIGHT) return;
    if (x1 > x2) { int t=x1; x1=x2; x2=t; }
    if (x1 < 0) x1 = 0;
    if (x2 >= GRAPHICS_WIDTH) x2 = GRAPHICS_WIDTH - 1;
    for (int x=x1; x<=x2; ++x) SetPixel(x,y,color);
}

D64_GRAPHICS_API void FloodFill(int x, int y, GraphicsColor fillColor)
{
    if ((unsigned)x >= GRAPHICS_WIDTH || (unsigned)y >= GRAPHICS_HEIGHT) return;
    GraphicsColor source = GetPixel(x,y);
    if (source == fillColor) return;

    enum { STACK_SIZE = GRAPHICS_WIDTH * GRAPHICS_HEIGHT };
    static int xs[STACK_SIZE];
    static int ys[STACK_SIZE];
    int top = 0;
    xs[top] = x; ys[top] = y; ++top;
    while (top > 0) {
        --top;
        int cx = xs[top], cy = ys[top];
        if ((unsigned)cx >= GRAPHICS_WIDTH || (unsigned)cy >= GRAPHICS_HEIGHT) continue;
        if (GetPixel(cx,cy) != source) continue;
        SetPixel(cx,cy,fillColor);
        if (top + 4 < STACK_SIZE) {
            xs[top]=cx-1; ys[top]=cy; ++top;
            xs[top]=cx+1; ys[top]=cy; ++top;
            xs[top]=cx; ys[top]=cy-1; ++top;
            xs[top]=cx; ys[top]=cy+1; ++top;
        }
    }
    d64_present();
}

D64_GRAPHICS_API void DrawTriangle(int x1,int y1,int x2,int y2,int x3,int y3,GraphicsColor color)
{
    DrawLine(x1,y1,x2,y2,color);
    DrawLine(x2,y2,x3,y3,color);
    DrawLine(x3,y3,x1,y1,color);
    d64_present();
}

static void d64_thick_line(int x1,int y1,int x2,int y2,GraphicsColor color,unsigned int width)
{
    if (width <= 1u) { DrawLine(x1,y1,x2,y2,color); return; }
    int dx = x2>x1 ? x2-x1 : x1-x2;
    int dy = y2>y1 ? y2-y1 : y1-y2;
    int half = (int)(width/2u);
    if (dx >= dy) {
        for (int o=-half;o<=half;++o) DrawLine(x1,y1+o,x2,y2+o,color);
    } else {
        for (int o=-half;o<=half;++o) DrawLine(x1+o,y1,x2+o,y2,color);
    }
}

D64_GRAPHICS_API void FillTriangle(
    int x1,int y1,int x2,int y2,int x3,int y3,
    GraphicsColor fillColor,GraphicsColor borderColor,
    unsigned int borderWidth)
{
    int t;
    if (y1>y2) { t=y1;y1=y2;y2=t; t=x1;x1=x2;x2=t; }
    if (y2>y3) { t=y2;y2=y3;y3=t; t=x2;x2=x3;x3=t; }
    if (y1>y2) { t=y1;y1=y2;y2=t; t=x1;x1=x2;x2=t; }
    if (y1==y3) {
        int lo=x1, hi=x1;
        if (x2<lo) lo=x2; if (x3<lo) lo=x3;
        if (x2>hi) hi=x2; if (x3>hi) hi=x3;
        d64_hline(lo,y1,hi,fillColor);
    } else {
        for (int y=y1;y<=y3;++y) {
            int a, b;
            if (y<y2 && y2!=y1) a=x1+((x2-x1)*(y-y1))/(y2-y1);
            else if (y3!=y2) a=x2+((x3-x2)*(y-y2))/(y3-y2);
            else a=x2;
            b=x1+((x3-x1)*(y-y1))/(y3-y1);
            /* Draw span regardless of edge ordering. */
            if (a<=b) d64_hline(a,y,b,fillColor); else d64_hline(b,y,a,fillColor);
        }
    }
    if (borderWidth) {
        d64_thick_line(x1,y1,x2,y2,borderColor,borderWidth);
        d64_thick_line(x2,y2,x3,y3,borderColor,borderWidth);
        d64_thick_line(x3,y3,x1,y1,borderColor,borderWidth);
    }
    d64_present();
}

static int d64_sine_quarter(unsigned int index)
{
    static const int table[19] = {0,22,44,66,88,108,128,147,165,181,196,210,222,232,241,247,252,255,256};
    return table[index <= 18u ? index : 18u];
}

static int d64_sin_deg(int angle)
{
    while (angle < 0) angle += 360;
    while (angle >= 360) angle -= 360;
    unsigned int quadrant=(unsigned int)angle/90u;
    unsigned int remainder=(unsigned int)angle%90u;
    if (quadrant==1u || quadrant==3u) remainder=90u-remainder;
    unsigned int index=(remainder+2u)/5u;
    int value=d64_sine_quarter(index);
    if (quadrant>=2u) value=-value;
    return value;
}
static int d64_cos_deg(int angle) { return d64_sin_deg(angle+90); }

D64_GRAPHICS_API void DrawTriangleAngles(
    int centerX,int centerY,
    int radius1,int radius2,int radius3,
    int angle1,int angle2,int angle3,
    GraphicsColor color)
{
    int x1=centerX+(d64_cos_deg(angle1)*radius1)/256;
    int y1=centerY+(d64_sin_deg(angle1)*radius1)/256;
    int x2=centerX+(d64_cos_deg(angle2)*radius2)/256;
    int y2=centerY+(d64_sin_deg(angle2)*radius2)/256;
    int x3=centerX+(d64_cos_deg(angle3)*radius3)/256;
    int y3=centerY+(d64_sin_deg(angle3)*radius3)/256;
    DrawTriangle(x1,y1,x2,y2,x3,y3,color);
}
'''

def write_windows_graphics_runtime_source(path: Path) -> Path:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(WINDOWS_GRAPHICS_RUNTIME_CPP, encoding="utf-8", newline="\n")
    return target



def build_windows_graphics_runtime_dll(
    output_path: Path,
    backend: str = "Direct2D",
) -> Path:
    """Baut die 32-Bit-Windows-Grafik-Runtime als ``d64graphics.dll``.

    Der Build benutzt bewusst einen vorhandenen MinGW-g++-Compiler, während
    der eigentliche PE32-Programm-Linker weiterhin vollständig in d64_dism
    bleibt. Das Runtime-DLL kapselt die C++-/COM-Anteile von Direct2D/Direct3D,
    die nicht in den einfachen internen COFF32-Objektleser gehören.
    """
    if os.name != "nt":
        raise PE32AssemblerError(
            "Die Direct2D/Direct3D-Runtime kann nur unter Windows gebaut werden."
        )

    selected = normalize_windows_graphics_backend(backend)
    compiler = (
        shutil.which("i686-w64-mingw32-g++")
        or shutil.which("g++")
        or shutil.which("c++")
    )
    if not compiler:
        raise PE32AssemblerError(
            "Kein MinGW-C++-Compiler gefunden. Erwartet wird "
            "i686-w64-mingw32-g++ oder g++ im PATH."
        )

    target = Path(output_path).expanduser().resolve()
    if target.suffix.casefold() != ".dll":
        target = target.with_suffix(".dll")
    target.parent.mkdir(parents=True, exist_ok=True)

    with tempfile.TemporaryDirectory(prefix="d64graphics_") as temp_name:
        temp_dir = Path(temp_name)
        header = write_windows_graphics_runtime_header(
            temp_dir / "graphics_windows.h"
        )
        source = write_windows_graphics_runtime_source(
            temp_dir / "graphics_windows_runtime.cpp"
        )
        del header

        command = [
            compiler,
            "-m32",
            "-shared",
            "-O2",
            "-std=gnu++17",
            "-Wl,--enable-auto-import",
            "-D__D64_GRAPHICS_DIRECT3D__"
            if selected == "Direct3D"
            else "-D__D64_GRAPHICS_DIRECT2D__",
            str(source),
            "-o",
            str(target),
            "-luser32",
            "-lkernel32",
        ]
        if selected == "Direct3D":
            command.append("-ld3d9")
        else:
            command.extend(("-ld2d1", "-ldxgi", "-lole32"))

        result = subprocess.run(
            command,
            cwd=str(temp_dir),
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
        if result.returncode != 0:
            details = (result.stderr or result.stdout or "").strip()
            raise PE32AssemblerError(
                "Windows-Grafik-Runtime konnte nicht gebaut werden"
                + (f": {details}" if details else ".")
            )

    try:
        data = target.read_bytes()
        if len(data) < 0x40 or data[:2] != b"MZ":
            raise ValueError("kein MZ-Header")
        pe_offset = struct.unpack_from("<I", data, 0x3C)[0]
        if data[pe_offset:pe_offset + 4] != b"PE\x00\x00":
            raise ValueError("keine PE-Signatur")
        machine = struct.unpack_from("<H", data, pe_offset + 4)[0]
        if machine != 0x014C:
            raise ValueError(
                f"falsche PE-Machine 0x{machine:04X}; IA-32/0x014C erwartet"
            )

        # Sicherstellen, dass MinGW die erwarteten undecorated C-Namen in die
        # Exporttabelle geschrieben hat. Damit stimmt die DLL exakt mit den
        # vom internen PE32-Linker erzeugten Imports ueberein.
        section_count = struct.unpack_from("<H", data, pe_offset + 6)[0]
        optional_size = struct.unpack_from("<H", data, pe_offset + 20)[0]
        optional_offset = pe_offset + 24
        if struct.unpack_from("<H", data, optional_offset)[0] != 0x010B:
            raise ValueError("kein PE32-Optional-Header")
        export_rva = struct.unpack_from("<I", data, optional_offset + 96)[0]
        if not export_rva:
            raise ValueError("Runtime-DLL besitzt keine Exporttabelle")
        section_offset = optional_offset + optional_size

        def rva_to_offset(rva: int) -> int:
            for index in range(section_count):
                base = section_offset + index * 40
                virtual_size, virtual_address, raw_size, raw_pointer = struct.unpack_from(
                    "<IIII", data, base + 8
                )
                span = max(virtual_size, raw_size)
                if virtual_address <= rva < virtual_address + span:
                    return raw_pointer + (rva - virtual_address)
            raise ValueError(f"RVA 0x{rva:08X} liegt in keiner Sektion")

        export_offset = rva_to_offset(export_rva)
        name_count = struct.unpack_from("<I", data, export_offset + 24)[0]
        names_rva = struct.unpack_from("<I", data, export_offset + 32)[0]
        names_offset = rva_to_offset(names_rva)
        exports = set()
        for index in range(name_count):
            name_rva = struct.unpack_from("<I", data, names_offset + index * 4)[0]
            name_offset = rva_to_offset(name_rva)
            end = data.find(b"\0", name_offset)
            if end < 0:
                raise ValueError("ungueltiger Name in der Exporttabelle")
            exports.add(data[name_offset:end].decode("ascii", errors="replace"))
        required_exports = {
            "SetTextColor", "ClearScreen", "InitGraphics", "DoneGraphics",
            "SetPixel", "GetPixel", "DrawLine", "DrawRect", "FillRect",
            "DrawCircle", "FillCircle", "FloodFill", "DrawTriangle",
            "FillTriangle", "DrawTriangleAngles",
        }
        missing_exports = sorted(required_exports - exports)
        if missing_exports:
            raise ValueError(
                "fehlende DLL-Exports: " + ", ".join(missing_exports)
            )
    except (OSError, struct.error, ValueError) as exc:
        try:
            target.unlink(missing_ok=True)
        except OSError:
            pass
        raise PE32AssemblerError(
            f"Das erzeugte Runtime-DLL ist kein gültiges PE32-i386-DLL: {exc}"
        ) from exc

    return target



class AmigaAssemblerError(Exception):
    """Assemblerfehler mit optionaler Quellzeile."""

    def __init__(self, message: str, line: int = 0) -> None:
        self.message = str(message)
        self.line = int(line or 0)
        super().__init__(self.message)

    def __str__(self) -> str:
        if self.line:
            return f"Zeile {self.line}: {self.message}"
        return self.message


@dataclass(frozen=True)
class AmigaProgram:
    executable: bytes
    code: bytes
    entry_offset: int
    end_offset: int
    instruction_count: int
    hunk_count: int = 1


@dataclass(frozen=True)
class AmigaBootProgram:
    """Bootfähiges ADF mit Trackloader und direkt ausführbarem 68000-Code."""

    adf: bytes
    boot_block: bytes
    code: bytes
    entry_offset: int
    end_offset: int
    instruction_count: int
    hunk_count: int = 0
    load_address: int = BOOT_PAYLOAD_ADDRESS
    payload_offset: int = BOOT_PAYLOAD_OFFSET


@dataclass(frozen=True)
class _SourceItem:
    line: int
    offset: int
    text: str


@dataclass(frozen=True)
class _EffectiveAddress:
    mode: int
    register: int
    extension_kind: str = ""
    expression: str = ""

    @property
    def bits(self) -> int:
        return (self.mode << 3) | self.register

    def extension_words(
        self,
        labels: Dict[str, int],
        extension_offset: int,
        size: str,
        line: int,
        resolve: bool,
    ) -> List[int]:
        kind = self.extension_kind
        if not kind:
            return []
        if kind == "immediate":
            value = _parse_expression(self.expression, labels, line, resolve)
            if size == "l":
                value &= 0xFFFFFFFF
                return [(value >> 16) & 0xFFFF, value & 0xFFFF]
            return [value & 0xFFFF]
        if kind == "pc":
            target = _parse_expression(self.expression, labels, line, resolve)
            displacement = target - extension_offset if resolve else 0
            _require_signed_word(displacement, line, "PC-relativer Abstand")
            return [displacement & 0xFFFF]
        if kind == "displacement":
            value = _parse_expression(self.expression, labels, line, resolve)
            _require_signed_word(value, line, "Adressabstand")
            return [value & 0xFFFF]
        if kind == "absolute_word":
            value = _parse_expression(self.expression, labels, line, resolve)
            if resolve and not -32768 <= value <= 0xFFFF:
                raise AmigaAssemblerError(
                    f"Absolute Word-Adresse außerhalb des Bereichs: {value}.",
                    line,
                )
            return [value & 0xFFFF]
        raise AmigaAssemblerError(f"Interner EA-Fehler: {kind}.", line)

_LABEL_RE       = re.compile(r"^[A-Za-z_.$][A-Za-z0-9_.$]*$")
_REGISTER_RE    = re.compile(r"^(?P<kind>[dDaA])(?P<number>[0-7])$")
_INDIRECT_RE    = re.compile(r"^\((?P<register>a[0-7]|sp)\)$", re.IGNORECASE)
_POSTINC_RE     = re.compile(r"^\((?P<register>a[0-7]|sp)\)\+$", re.IGNORECASE)
_PREDEC_RE      = re.compile(r"^-\((?P<register>a[0-7]|sp)\)$", re.IGNORECASE)
_INDEXED_RE     = re.compile(r"^(?P<expression>.+?)\((?P<register>a[0-7]|sp|pc)\)$", re.IGNORECASE,)


def _register_number(text: str, line: int) -> Tuple[str, int]:
    lowered = text.strip().lower()
    if lowered == "sp":
        return "a", 7
    match = _REGISTER_RE.fullmatch(lowered)
    if match is None:
        raise AmigaAssemblerError(f"Register erwartet: {text}.", line)
    return match.group("kind").lower(), int(match.group("number"))


def _parse_number(text: str) -> Optional[int]:
    value = text.strip()
    sign = 1
    if value.startswith(("+", "-")):
        if value[0] == "-":
            sign = -1
        value = value[1:].strip()
    try:
        if value.startswith("$"):
            return sign * int(value[1:], 16)
        if value.startswith("%"):
            return sign * int(value[1:], 2)
        if value.lower().startswith("0x"):
            return sign * int(value[2:], 16)
        if value.lower().startswith("0b"):
            return sign * int(value[2:], 2)
        if value.isdigit():
            return sign * int(value, 10)
    except ValueError:
        return None
    return None

def _parse_expression(
    text: str,
    labels: Dict[str, int],
    line: int,
    resolve: bool,
) -> int:
    expression = text.strip()
    numeric = _parse_number(expression)
    if numeric is not None:
        return numeric

    match = re.fullmatch(
        r"(?P<label>[A-Za-z_.$][A-Za-z0-9_.$]*)"
        r"(?:\s*(?P<operator>[+-])\s*(?P<offset>.+))?",
        expression,
    )
    if match is None:
        raise AmigaAssemblerError(f"Ungültiger Ausdruck: {text}.", line)
    label = match.group("label").casefold()
    if label not in labels:
        if not resolve:
            base = 0
        else:
            raise AmigaAssemblerError(
                f"Symbol nicht definiert: {match.group('label')}.",
                line,
            )
    else:
        base = labels[label]
    offset_text = match.group("offset")
    if offset_text:
        offset = _parse_number(offset_text)
        if offset is None:
            raise AmigaAssemblerError(
                f"Numerischer Symbolabstand erwartet: {offset_text}.",
                line,
            )
        base = base + offset if match.group("operator") == "+" else base - offset
    return base

def _require_signed_word(value: int, line: int, description: str) -> None:
    if not -32768 <= int(value) <= 32767:
        raise AmigaAssemblerError(
            f"{description} liegt außerhalb -32768..32767: {value}.",
            line,
        )

def _parse_ea(text: str, line: int) -> _EffectiveAddress:
    operand = text.strip()
    if operand.startswith("#"):
        return _EffectiveAddress(7, 4, "immediate", operand[1:].strip())

    register_match = _REGISTER_RE.fullmatch(operand)
    if register_match is not None:
        kind = register_match.group("kind").lower()
        return _EffectiveAddress(
            0 if kind == "d" else 1,
            int(register_match.group("number")),
        )
    if operand.lower() == "sp":
        return _EffectiveAddress(1, 7)

    match = _INDIRECT_RE.fullmatch(operand)
    if match is not None:
        unused_kind, register = _register_number(match.group("register"), line)
        return _EffectiveAddress(2, register)
    match = _POSTINC_RE.fullmatch(operand)
    if match is not None:
        unused_kind, register = _register_number(match.group("register"), line)
        return _EffectiveAddress(3, register)
    match = _PREDEC_RE.fullmatch(operand)
    if match is not None:
        unused_kind, register = _register_number(match.group("register"), line)
        return _EffectiveAddress(4, register)
    match = _INDEXED_RE.fullmatch(operand)
    if match is not None:
        register_text = match.group("register").lower()
        if register_text == "pc":
            return _EffectiveAddress(7, 2, "pc", match.group("expression"))
        unused_kind, register = _register_number(register_text, line)
        return _EffectiveAddress(
            5,
            register,
            "displacement",
            match.group("expression"),
        )
    if operand.lower().endswith(".w"):
        return _EffectiveAddress(7, 0, "absolute_word", operand[:-2])
    raise AmigaAssemblerError(f"Adressierungsart nicht unterstützt: {text}.", line)

def _split_operands(text: str) -> List[str]:
    result: List[str] = []
    start = 0
    depth = 0
    for index, character in enumerate(text):
        if character == "(":
            depth += 1
        elif character == ")":
            depth = max(0, depth - 1)
        elif character == "," and depth == 0:
            result.append(text[start:index].strip())
            start = index + 1
    tail = text[start:].strip()
    if tail:
        result.append(tail)
    return result


def _word_bytes(words: Sequence[int]) -> bytes:
    return b"".join(struct.pack(">H", word & 0xFFFF) for word in words)


def _ea_words(
    ea: _EffectiveAddress,
    labels: Dict[str, int],
    extension_offset: int,
    size: str,
    line: int,
    resolve: bool,
) -> List[int]:
    return ea.extension_words(
        labels,
        extension_offset,
        size,
        line,
        resolve,
    )

_SIZE_BITS = {"b": 0x0000, "w": 0x0040, "l": 0x0080}
_MOVE_BASE = {"b": 0x1000, "w": 0x3000, "l": 0x2000}
_AMIGA_MOVEC_REGISTERS: Dict[str, Tuple[int, str, Optional[str]]] = {
    "sfc":   (0x000, "mk68010", None),
    "dfc":   (0x001, "mk68010", None),
    "cacr":  (0x002, "mk68020", None),
    "tc":    (0x003, "mk68040", None),
    "itt0":  (0x004, "mk68040", None),
    "itt1":  (0x005, "mk68040", None),
    "dtt0":  (0x006, "mk68040", None),
    "dtt1":  (0x007, "mk68040", None),
    "usp":   (0x800, "mk68010", None),
    "vbr":   (0x801, "mk68010", None),
    "caar":  (0x802, "mk68020", "mk68030"),
    "msp":   (0x803, "mk68020", None),
    "isp":   (0x804, "mk68020", None),
    "mmusr": (0x805, "mk68040", None),
    "urp":   (0x806, "mk68040", None),
    "srp":   (0x807, "mk68040", None),
    "pcr":   (0x808, "mk68060", None),
}


def _amiga_movec_register_code(name: str, cpu_model: str, line: int) -> int:
    key = str(name).strip().casefold()
    spec = _AMIGA_MOVEC_REGISTERS.get(key)
    if spec is None:
        raise AmigaAssemblerError(f"Unbekanntes MOVEC-Control-Register: {name}.", line)
    code, minimum, maximum = spec
    if not amiga_cpu_at_least(cpu_model, minimum):
        raise AmigaAssemblerError(
            f"MOVEC {name.upper()} benötigt mindestens {minimum}.", line
        )
    if maximum is not None and AMIGA_CPU_LEVEL[normalize_amiga_cpu_model(cpu_model)] > AMIGA_CPU_LEVEL[maximum]:
        raise AmigaAssemblerError(
            f"MOVEC {name.upper()} ist nur bis {maximum} verfügbar.", line
        )
    return code


_BRANCH_CONDITION = {
    "bra": 0x0,
    "bsr": 0x1,
    "bhi": 0x2,
    "bls": 0x3,
    "bcc": 0x4,
    "bhs": 0x4,
    "bcs": 0x5,
    "blo": 0x5,
    "bne": 0x6,
    "beq": 0x7,
    "bvc": 0x8,
    "bvs": 0x9,
    "bpl": 0xA,
    "bmi": 0xB,
    "bge": 0xC,
    "blt": 0xD,
    "bgt": 0xE,
    "ble": 0xF,
}


def _encode_instruction(
    text: str,
    offset: int,
    labels: Dict[str, int],
    line: int,
    resolve: bool,
    cpu_model: str = "mk68000",
    fpu_model: str = "FPU: None",
) -> bytes:
    cpu_model = normalize_amiga_cpu_model(cpu_model)
    fpu_model = normalize_amiga_fpu_model(fpu_model)
    parts = text.strip().split(None, 1)
    mnemonic_text = parts[0].lower()
    operands = _split_operands(parts[1] if len(parts) > 1 else "")
    if "." in mnemonic_text:
        mnemonic, size = mnemonic_text.split(".", 1)
    else:
        mnemonic, size = mnemonic_text, ""

    if mnemonic == "nop" and not operands:
        return _word_bytes([0x4E71])
    if mnemonic == "rts" and not operands:
        return _word_bytes([0x4E75])

    if mnemonic == "reset" and not operands:
        return _word_bytes([0x4E70])
    if mnemonic == "rte" and not operands:
        return _word_bytes([0x4E73])
    if mnemonic == "rtr" and not operands:
        return _word_bytes([0x4E77])
    if mnemonic == "trapv" and not operands:
        return _word_bytes([0x4E76])
    if mnemonic == "stop":
        if len(operands) != 1 or not operands[0].startswith("#"):
            raise AmigaAssemblerError("STOP erwartet #Statuswort.", line)
        value = _parse_expression(operands[0][1:], labels, line, resolve)
        return _word_bytes([0x4E72, value])
    if mnemonic == "trap":
        if len(operands) != 1 or not operands[0].startswith("#"):
            raise AmigaAssemblerError("TRAP erwartet #0..15.", line)
        vector = _parse_expression(operands[0][1:], labels, line, resolve)
        if resolve and not 0 <= vector <= 15:
            raise AmigaAssemblerError("TRAP-Vektor muss 0..15 sein.", line)
        return _word_bytes([0x4E40 | (vector & 15)])
    if mnemonic == "unlk":
        if len(operands) != 1:
            raise AmigaAssemblerError("UNLK erwartet An.", line)
        kind, register = _register_number(operands[0], line)
        if kind != "a":
            raise AmigaAssemblerError("UNLK erwartet ein Adressregister.", line)
        return _word_bytes([0x4E58 | register])
    if mnemonic == "link":
        if len(operands) != 2 or not operands[1].startswith("#"):
            raise AmigaAssemblerError("LINK erwartet An,#Abstand.", line)
        kind, register = _register_number(operands[0], line)
        if kind != "a":
            raise AmigaAssemblerError("LINK erwartet ein Adressregister.", line)
        displacement = _parse_expression(operands[1][1:], labels, line, resolve)
        if size in {"", "w"}:
            _require_signed_word(displacement, line, "LINK.W-Abstand")
            return _word_bytes([0x4E50 | register, displacement])
        if size == "l":
            if not amiga_cpu_at_least(cpu_model, "mk68020"):
                raise AmigaAssemblerError("LINK.L benötigt mindestens mk68020.", line)
            value = displacement & 0xFFFFFFFF
            return _word_bytes([0x4808 | register, (value >> 16) & 0xFFFF, value & 0xFFFF])
        raise AmigaAssemblerError("LINK unterstützt .W oder ab mk68020 .L.", line)
    if mnemonic == "movec":
        if not amiga_cpu_at_least(cpu_model, "mk68010"):
            raise AmigaAssemblerError("MOVEC benötigt mindestens mk68010.", line)
        if len(operands) != 2:
            raise AmigaAssemblerError("MOVEC erwartet Rc,Rn oder Rn,Rc.", line)
        left = operands[0].strip()
        right = operands[1].strip()
        left_control = left.casefold() in _AMIGA_MOVEC_REGISTERS
        right_control = right.casefold() in _AMIGA_MOVEC_REGISTERS
        if left_control == right_control:
            raise AmigaAssemblerError("MOVEC benötigt genau ein Control-Register.", line)
        if left_control:
            control = _amiga_movec_register_code(left, cpu_model, line)
            kind, register = _register_number(right, line)
            first_word = 0x4E7A
        else:
            kind, register = _register_number(left, line)
            control = _amiga_movec_register_code(right, cpu_model, line)
            first_word = 0x4E7B
        extension = ((1 if kind == "a" else 0) << 15) | ((register & 7) << 12) | control
        return _word_bytes([first_word, extension])

    if mnemonic in _BRANCH_CONDITION:
        if len(operands) != 1:
            raise AmigaAssemblerError(f"{mnemonic.upper()} erwartet ein Ziel.", line)
        target = _parse_expression(operands[0], labels, line, resolve)
        opcode = 0x6000 | (_BRANCH_CONDITION[mnemonic] << 8)
        if size == "l":
            if not amiga_cpu_at_least(cpu_model, "mk68020"):
                raise AmigaAssemblerError(
                    f"{mnemonic.upper()}.L benötigt mindestens mk68020.", line
                )
            displacement = target - (offset + 2) if resolve else 0
            value = displacement & 0xFFFFFFFF
            return _word_bytes([
                opcode | 0x00FF,
                (value >> 16) & 0xFFFF,
                value & 0xFFFF,
            ])
        if size not in {"", "w"}:
            raise AmigaAssemblerError(
                f"{mnemonic.upper()} unterstützt hier nur .W oder ab mk68020 .L.", line
            )
        displacement = target - (offset + 2) if resolve else 0
        _require_signed_word(displacement, line, "Sprungabstand")
        return _word_bytes([opcode, displacement])

    if mnemonic in {"jmp", "jsr"} and len(operands) == 1:
        if _LABEL_RE.fullmatch(operands[0]):
            pseudo = "bra" if mnemonic == "jmp" else "bsr"
            return _encode_instruction(
                f"{pseudo} {operands[0]}",
                offset,
                labels,
                line,
                resolve,
                cpu_model,
                fpu_model,
            )
        ea = _parse_ea(operands[0], line)
        extension = _ea_words(ea, labels, offset + 2, "l", line, resolve)
        return _word_bytes([(0x4EC0 if mnemonic == "jmp" else 0x4E80) | ea.bits] + extension)

    if mnemonic == "moveq":
        if len(operands) != 2 or not operands[0].startswith("#"):
            raise AmigaAssemblerError("MOVEQ erwartet #Wert,Dn.", line)
        kind, register = _register_number(operands[1], line)
        if kind != "d":
            raise AmigaAssemblerError("MOVEQ benötigt ein Datenregister.", line)
        value = _parse_expression(operands[0][1:], labels, line, resolve)
        if resolve and not -128 <= value <= 255:
            raise AmigaAssemblerError("MOVEQ-Wert liegt außerhalb -128..255.", line)
        return _word_bytes([0x7000 | (register << 9) | (value & 0xFF)])

    if mnemonic == "move":
        if size not in _MOVE_BASE or len(operands) != 2:
            raise AmigaAssemblerError("MOVE benötigt .B, .W oder .L und zwei Operanden.", line)
        source = _parse_ea(operands[0], line)
        destination = _parse_ea(operands[1], line)
        if destination.mode == 7:
            raise AmigaAssemblerError("MOVE-Zieladressierung wird nicht unterstützt.", line)
        source_extension = _ea_words(source, labels, offset + 2, size, line, resolve)
        destination_extension_offset = offset + 2 + 2 * len(source_extension)
        destination_extension = _ea_words(
            destination,
            labels,
            destination_extension_offset,
            size,
            line,
            resolve,
        )
        opcode = (
            _MOVE_BASE[size]
            | (destination.register << 9)
            | (destination.mode << 6)
            | source.bits
        )
        return _word_bytes([opcode] + source_extension + destination_extension)

    if mnemonic == "lea":
        if len(operands) != 2:
            raise AmigaAssemblerError("LEA erwartet Quelle,An.", line)
        source = _parse_ea(operands[0], line)
        kind, register = _register_number(operands[1], line)
        if kind != "a":
            raise AmigaAssemblerError("LEA benötigt ein Adressregister als Ziel.", line)
        extension = _ea_words(source, labels, offset + 2, "l", line, resolve)
        return _word_bytes([0x41C0 | (register << 9) | source.bits] + extension)

    if mnemonic in {"tst", "clr", "neg"}:
        if size not in _SIZE_BITS or len(operands) != 1:
            raise AmigaAssemblerError(f"{mnemonic.upper()} benötigt eine Größe und einen Operanden.", line)
        ea = _parse_ea(operands[0], line)
        base = {"tst": 0x4A00, "clr": 0x4200, "neg": 0x4400}[mnemonic]
        extension = _ea_words(ea, labels, offset + 2, size, line, resolve)
        return _word_bytes([base | _SIZE_BITS[size] | ea.bits] + extension)

    if mnemonic == "swap":
        if len(operands) != 1:
            raise AmigaAssemblerError("SWAP erwartet Dn.", line)
        kind, register = _register_number(operands[0], line)
        if kind != "d":
            raise AmigaAssemblerError("SWAP erwartet ein Datenregister.", line)
        return _word_bytes([0x4840 | register])

    if mnemonic == "ext":
        if size not in {"w", "l"} or len(operands) != 1:
            raise AmigaAssemblerError("EXT erwartet .W oder .L und Dn.", line)
        kind, register = _register_number(operands[0], line)
        if kind != "d":
            raise AmigaAssemblerError("EXT erwartet ein Datenregister.", line)
        return _word_bytes([(0x4880 if size == "w" else 0x48C0) | register])

    if mnemonic in {"add", "sub", "and", "or", "cmp"}:
        if size not in _SIZE_BITS or len(operands) != 2:
            raise AmigaAssemblerError(f"{mnemonic.upper()} benötigt Größe und zwei Operanden.", line)
        source = _parse_ea(operands[0], line)
        kind, register = _register_number(operands[1], line)
        if kind != "d":
            raise AmigaAssemblerError(f"{mnemonic.upper()} benötigt Dn als Ziel.", line)
        base = {"add": 0xD000, "sub": 0x9000, "and": 0xC000, "or": 0x8000, "cmp": 0xB000}[mnemonic]
        extension = _ea_words(source, labels, offset + 2, size, line, resolve)
        return _word_bytes([base | (register << 9) | _SIZE_BITS[size] | source.bits] + extension)

    if mnemonic == "eor":
        if size not in _SIZE_BITS or len(operands) != 2:
            raise AmigaAssemblerError("EOR benötigt Größe und zwei Operanden.", line)
        kind, register = _register_number(operands[0], line)
        if kind != "d":
            raise AmigaAssemblerError("EOR benötigt Dn als Quelle.", line)
        destination = _parse_ea(operands[1], line)
        extension = _ea_words(destination, labels, offset + 2, size, line, resolve)
        return _word_bytes([0xB100 | (register << 9) | _SIZE_BITS[size] | destination.bits] + extension)

    immediate_bases = {
        "addi": 0x0600,
        "subi": 0x0400,
        "andi": 0x0200,
        "ori": 0x0000,
        "eori": 0x0A00,
        "cmpi": 0x0C00,
    }
    if mnemonic in immediate_bases:
        if size not in _SIZE_BITS or len(operands) != 2 or not operands[0].startswith("#"):
            raise AmigaAssemblerError(f"{mnemonic.upper()} erwartet #Wert,Ziel.", line)
        destination = _parse_ea(operands[1], line)
        immediate = _EffectiveAddress(7, 4, "immediate", operands[0][1:])
        immediate_words = _ea_words(immediate, labels, offset + 2, size, line, resolve)
        destination_offset = offset + 2 + 2 * len(immediate_words)
        extension = _ea_words(destination, labels, destination_offset, size, line, resolve)
        opcode = immediate_bases[mnemonic] | _SIZE_BITS[size] | destination.bits
        return _word_bytes([opcode] + immediate_words + extension)

    if mnemonic in {"addq", "subq"}:
        if size not in _SIZE_BITS or len(operands) != 2 or not operands[0].startswith("#"):
            raise AmigaAssemblerError(f"{mnemonic.upper()} erwartet #1..8,Ziel.", line)
        count = _parse_expression(operands[0][1:], labels, line, resolve)
        if resolve and not 1 <= count <= 8:
            raise AmigaAssemblerError("Quick-Konstante muss 1..8 betragen.", line)
        destination = _parse_ea(operands[1], line)
        extension = _ea_words(destination, labels, offset + 2, size, line, resolve)
        encoded_count = 0 if count == 8 else count
        opcode = (0x5100 if mnemonic == "subq" else 0x5000)
        opcode |= (encoded_count << 9) | _SIZE_BITS[size] | destination.bits
        return _word_bytes([opcode] + extension)

    if mnemonic in {"adda", "suba"}:
        if size not in {"w", "l"} or len(operands) != 2:
            raise AmigaAssemblerError(f"{mnemonic.upper()} erwartet .W/.L Quelle,An.", line)
        source = _parse_ea(operands[0], line)
        kind, register = _register_number(operands[1], line)
        if kind != "a":
            raise AmigaAssemblerError(f"{mnemonic.upper()} benötigt An als Ziel.", line)
        base = 0xD0C0 if mnemonic == "adda" else 0x90C0
        if size == "l":
            base |= 0x0100
        extension = _ea_words(source, labels, offset + 2, size, line, resolve)
        return _word_bytes([base | (register << 9) | source.bits] + extension)

    if mnemonic in {"mulu", "muls", "divu", "divs"}:
        if size not in {"", "w"} or len(operands) != 2:
            raise AmigaAssemblerError(f"{mnemonic.upper()} erwartet Quelle,Dn.", line)
        source = _parse_ea(operands[0], line)
        kind, register = _register_number(operands[1], line)
        if kind != "d":
            raise AmigaAssemblerError(f"{mnemonic.upper()} benötigt Dn als Ziel.", line)
        base = {"mulu": 0xC0C0, "muls": 0xC1C0, "divu": 0x80C0, "divs": 0x81C0}[mnemonic]
        extension = _ea_words(source, labels, offset + 2, "w", line, resolve)
        return _word_bytes([base | (register << 9) | source.bits] + extension)

    if mnemonic == "rtd":
        if not amiga_cpu_at_least(cpu_model, "mk68010"):
            raise AmigaAssemblerError("RTD benötigt mindestens mk68010.", line)
        if len(operands) != 1 or not operands[0].startswith("#"):
            raise AmigaAssemblerError("RTD erwartet #Abstand.", line)
        value = _parse_expression(operands[0][1:], labels, line, resolve)
        _require_signed_word(value, line, "RTD-Stackabstand")
        return _word_bytes([0x4E74, value])

    if mnemonic == "bkpt":
        if not amiga_cpu_at_least(cpu_model, "mk68010"):
            raise AmigaAssemblerError("BKPT benötigt mindestens mk68010.", line)
        if len(operands) != 1 or not operands[0].startswith("#"):
            raise AmigaAssemblerError("BKPT erwartet #0..7.", line)
        value = _parse_expression(operands[0][1:], labels, line, resolve)
        if resolve and not 0 <= value <= 7:
            raise AmigaAssemblerError("BKPT-Vektor muss 0..7 sein.", line)
        return _word_bytes([0x4848 | (value & 7)])

    if mnemonic == "extb":
        if not amiga_cpu_at_least(cpu_model, "mk68020"):
            raise AmigaAssemblerError("EXTB.L benötigt mindestens mk68020.", line)
        if size not in {"", "l"} or len(operands) != 1:
            raise AmigaAssemblerError("EXTB erwartet .L Dn.", line)
        kind, register = _register_number(operands[0], line)
        if kind != "d":
            raise AmigaAssemblerError("EXTB.L erwartet ein Datenregister.", line)
        return _word_bytes([0x49C0 | register])

    fpu_register_opmodes = {
        "fmove": 0x00, "fint": 0x01, "fintrz": 0x03,
        "fsqrt": 0x04, "fabs": 0x18, "fneg": 0x1A,
        "fdiv": 0x20, "fadd": 0x22, "fmul": 0x23,
        "fsub": 0x28, "fcmp": 0x38, "ftst": 0x3A,
    }
    if mnemonic in fpu_register_opmodes:
        if fpu_model == "FPU: None":
            raise AmigaAssemblerError(
                f"{mnemonic.upper()} benötigt FPU: 68881 oder FPU: 68882.", line
            )
        if size not in {"", "x"}:
            raise AmigaAssemblerError(
                f"{mnemonic.upper()} unterstützt im integrierten Assembler derzeit FP-Register/X-Format.", line
            )
        def fp_register(value: str) -> int:
            match = re.fullmatch(r"fp([0-7])", value.strip(), re.IGNORECASE)
            if match is None:
                raise AmigaAssemblerError(
                    f"{mnemonic.upper()} erwartet FP0..FP7.", line
                )
            return int(match.group(1))
        if mnemonic == "ftst":
            if len(operands) != 1:
                raise AmigaAssemblerError("FTST erwartet FPn.", line)
            source_register = fp_register(operands[0])
            destination_register = source_register
        elif len(operands) == 1 and mnemonic in {"fint", "fintrz", "fsqrt", "fabs", "fneg"}:
            source_register = fp_register(operands[0])
            destination_register = source_register
        elif len(operands) == 2:
            source_register = fp_register(operands[0])
            destination_register = fp_register(operands[1])
        else:
            raise AmigaAssemblerError(
                f"{mnemonic.upper()} erwartet FPm,FPn.", line
            )
        extension = (source_register << 10) | (destination_register << 7) | fpu_register_opmodes[mnemonic]
        return _word_bytes([0xF200, extension])

    if mnemonic == "fnop":
        if fpu_model == "FPU: None":
            raise AmigaAssemblerError(
                "FNOP benötigt FPU: 68881 oder FPU: 68882.", line
            )
        if operands:
            raise AmigaAssemblerError("FNOP besitzt keine Operanden.", line)
        return _word_bytes([0xF280, 0x0000])

    if mnemonic in {"lsl", "lsr"}:
        if size not in {"b", "w", "l"} or len(operands) != 2 or not operands[0].startswith("#"):
            raise AmigaAssemblerError(f"{mnemonic.upper()} erwartet #1..8,Dn.", line)
        count = _parse_expression(operands[0][1:], labels, line, resolve)
        if resolve and not 1 <= count <= 8:
            raise AmigaAssemblerError("Schiebeweite muss 1..8 betragen.", line)
        kind, register = _register_number(operands[1], line)
        if kind != "d":
            raise AmigaAssemblerError("Register-Schiebebefehl benötigt Dn.", line)
        size_bits = {"b": 0x0000, "w": 0x0040, "l": 0x0080}[size]
        encoded_count = 0 if count == 8 else count
        opcode = 0xE008 | (encoded_count << 9) | size_bits | register
        if mnemonic == "lsl":
            opcode |= 0x0100
        return _word_bytes([opcode])

    raise AmigaAssemblerError(f"68000-Befehl nicht unterstützt: {text}.", line)

def _strip_comment(line: str) -> str:
    return line.split(";", 1)[0].strip()

def _split_label(text: str) -> Tuple[Optional[str], str]:
    match = re.match(
        r"^(?P<label>[A-Za-z_.$][A-Za-z0-9_.$]*)\s*:\s*(?P<tail>.*)$",
        text,
    )
    if match is None:
        return None, text
    return match.group("label"), match.group("tail").strip()

def _directive_parts(text: str) -> Tuple[str, str]:
    parts = text.strip().split(None, 1)
    name = parts[0].lower().lstrip(".") if parts else ""
    arguments = parts[1].strip() if len(parts) > 1 else ""
    return name, arguments

def _data_values(arguments: str) -> List[str]:
    return [item.strip() for item in _split_operands(arguments) if item.strip()]

def _item_size(
    text: str,
    offset: int,
    labels: Dict[str, int],
    line: int,
    cpu_model: str = "mk68000",
    fpu_model: str = "FPU: None",
) -> int:
    name, arguments = _directive_parts(text)
    if name in {"section", "xdef", "end", "bootable"}:
        return 0
    if name == "even":
        return offset & 1
    if name in {"dc.b", "dc.w", "dc.l"}:
        unit = {"dc.b": 1, "dc.w": 2, "dc.l": 4}[name]
        return unit * len(_data_values(arguments))
    if name in {"ds.b", "ds.w", "ds.l"}:
        unit = {"ds.b": 1, "ds.w": 2, "ds.l": 4}[name]
        count = _parse_expression(arguments, labels, line, False)
        if count < 0:
            raise AmigaAssemblerError("DS-Anzahl darf nicht negativ sein.", line)
        return unit * count
    return len(_encode_instruction(
        text, offset, labels, line, False, cpu_model, fpu_model
    ))

def _encode_item(
    item: _SourceItem,
    labels: Dict[str, int],
    cpu_model: str = "mk68000",
    fpu_model: str = "FPU: None",
) -> Tuple[bytes, int]:
    name, arguments = _directive_parts(item.text)
    if name in {"section", "xdef", "end", "bootable"}:
        return b"", 0
    if name == "even":
        return (b"\x00" if item.offset & 1 else b""), 0
    if name in {"dc.b", "dc.w", "dc.l"}:
        unit = {"dc.b": 1, "dc.w": 2, "dc.l": 4}[name]
        output = bytearray()
        for expression in _data_values(arguments):
            value = _parse_expression(expression, labels, item.line, True)
            if unit == 1:
                output.append(value & 0xFF)
            elif unit == 2:
                output.extend(struct.pack(">H", value & 0xFFFF))
            else:
                output.extend(struct.pack(">I", value & 0xFFFFFFFF))
        return bytes(output), 0
    if name in {"ds.b", "ds.w", "ds.l"}:
        unit = {"ds.b": 1, "ds.w": 2, "ds.l": 4}[name]
        count = _parse_expression(arguments, labels, item.line, True)
        return bytes(unit * count), 0
    return (
        _encode_instruction(
            item.text,
            item.offset,
            labels,
            item.line,
            True,
            cpu_model,
            fpu_model,
        ),
        1,
    )


def _hunk_executable(code: bytes) -> bytes:
    padded_size = (len(code) + 3) & ~3
    padded_code = code + bytes(padded_size - len(code))
    long_count = padded_size // 4
    header = struct.pack(
        ">6I",
        HUNK_HEADER,
        0,
        1,
        0,
        0,
        long_count,
    )
    return (
        header
        + struct.pack(">2I", HUNK_CODE, long_count)
        + padded_code
        + struct.pack(">I", HUNK_END)
    )

def is_amiga_boot_source(source: str) -> bool:
    """Erkennt die explizite ``.bootable``-Direktive."""
    for raw_line in str(source).splitlines():
        text = _strip_comment(raw_line)
        if not text:
            continue
        unused_label, tail = _split_label(text)
        if tail and _directive_parts(tail)[0] == "bootable":
            return True
    return False


def _boot_block_checksum(block: bytes) -> int:
    """Berechnet die Amiga-Bootblock-Prüfsumme mit End-Around-Carry."""
    if len(block) != BOOT_BLOCK_SIZE:
        raise ValueError("Ein Amiga-Bootblock muss genau 1024 Bytes groß sein.")
    total = 0
    for (value,) in struct.iter_unpack(">I", block):
        previous = total
        total = (total + value) & 0xFFFFFFFF
        if total < previous:
            total = (total + 1) & 0xFFFFFFFF
    return (~total) & 0xFFFFFFFF


def _boot_loader_source(payload_size: int) -> str:
    """Erzeugt den kleinen Bootblock-Trackloader für den Nutzcode."""
    return (
        "section code,code\n"
        "xdef _start\n"
        "_start:\n"
        f"    move.l #${BOOT_PAYLOAD_ADDRESS:08X},$28(a1)\n"
        f"    move.l #${payload_size:08X},$24(a1)\n"
        f"    move.l #${BOOT_PAYLOAD_OFFSET:08X},$2C(a1)\n"
        "    move.w #$0002,$1C(a1)\n"
        "    jsr -456(a6)\n"
        "    tst.b $1F(a1)\n"
        "    bne .load_error\n"
        f"    move.l #${BOOT_PAYLOAD_ADDRESS:08X},a0\n"
        "    jmp (a0)\n"
        ".load_error:\n"
        "    moveq #-1,d0\n"
        "    rts\n"
    )

def _bootable_adf(code: bytes) -> Tuple[bytes, bytes]:
    if len(code) > MAX_BOOT_PAYLOAD_SIZE:
        raise AmigaAssemblerError(
            "Der Standalone-Nutzcode ist zu groß: "
            f"{len(code)} Bytes; erlaubt sind höchstens "
            f"{MAX_BOOT_PAYLOAD_SIZE} Bytes."
        )

    padded_size = (len(code) + 511) & ~511
    if BOOT_PAYLOAD_OFFSET + padded_size > ADF_SIZE:
        raise AmigaAssemblerError(
            "Der Standalone-Nutzcode passt nicht auf eine Amiga-DD-Diskette."
        )

    loader = assemble_amiga_source(_boot_loader_source(padded_size))
    maximum_loader_size = BOOT_BLOCK_SIZE - BOOT_CODE_OFFSET
    if len(loader.code) > maximum_loader_size:
        raise AmigaAssemblerError(
            "Interner Fehler: Der Amiga-Trackloader überschreitet den Bootblock."
        )

    boot_block = bytearray(BOOT_BLOCK_SIZE)
    boot_block[0:4] = b"DOS\0"
    struct.pack_into(">I", boot_block, 8, AMIGA_DD_ROOT_BLOCK)
    boot_block[
        BOOT_CODE_OFFSET:BOOT_CODE_OFFSET + len(loader.code)
    ] = loader.code
    struct.pack_into(">I", boot_block, 4, _boot_block_checksum(boot_block))

    adf = bytearray(ADF_SIZE)
    adf[:BOOT_BLOCK_SIZE] = boot_block
    adf[
        BOOT_PAYLOAD_OFFSET:BOOT_PAYLOAD_OFFSET + len(code)
    ] = code
    return bytes(adf), bytes(boot_block)


def assemble_amiga_source(
    source: str,
    *,
    filename: str = "<Amiga-Assembler>",
    cpu_model: str = "mk68000",
    fpu_model: str = "FPU: None",
) -> AmigaProgram:
    """Assembliert 68k-Quelltext passend zum gewählten CPU/FPU-Profil."""
    del filename
    cpu_model = normalize_amiga_cpu_model(cpu_model)
    fpu_model = normalize_amiga_fpu_model(fpu_model)
    labels: Dict[str, int] = {}
    items: List[_SourceItem] = []
    offset = 0

    for line_number, raw_line in enumerate(source.splitlines(), 1):
        text = _strip_comment(raw_line)
        if not text:
            continue
        label, text = _split_label(text)
        if label is not None:
            key = label.casefold()
            if key in labels:
                raise AmigaAssemblerError(f"Symbol mehrfach definiert: {label}.", line_number)
            labels[key] = offset
        if not text:
            continue
        size = _item_size(
            text, offset, labels, line_number, cpu_model, fpu_model
        )
        items.append(_SourceItem(line_number, offset, text))
        offset += size

    if "_start" not in labels:
        raise AmigaAssemblerError("Einsprungmarke _start fehlt.")
    if labels["_start"] != 0:
        raise AmigaAssemblerError("_start muss am Beginn des CODE-Hunks stehen.")

    output = bytearray()
    instruction_count = 0
    for item in items:
        if len(output) != item.offset:
            raise AmigaAssemblerError("Interner Layoutfehler.", item.line)
        encoded, instructions = _encode_item(
            item, labels, cpu_model, fpu_model
        )
        output.extend(encoded)
        instruction_count += instructions

    code = bytes(output)
    return AmigaProgram(
        executable=_hunk_executable(code),
        code=code,
        entry_offset=labels["_start"],
        end_offset=len(code),
        instruction_count=instruction_count,
    )

def assemble_amiga_boot_source(
    source: str,
    *,
    filename: str = "<Amiga-Standalone-Assembler>",
    cpu_model: str = "mk68000",
    fpu_model: str = "FPU: None",
) -> AmigaBootProgram:
    """Erzeugt aus ``.bootable``-Quelltext ein direkt bootfähiges ADF."""
    if not is_amiga_boot_source(source):
        raise AmigaAssemblerError(
            "Für ein Standalone-ADF fehlt die Direktive .bootable."
        )
    program = assemble_amiga_source(
        source,
        filename=filename,
        cpu_model=cpu_model,
        fpu_model=fpu_model,
    )
    adf, boot_block = _bootable_adf(program.code)
    return AmigaBootProgram(
        adf=adf,
        boot_block=boot_block,
        code=program.code,
        entry_offset=BOOT_PAYLOAD_ADDRESS + program.entry_offset,
        end_offset=BOOT_PAYLOAD_ADDRESS + program.end_offset,
        instruction_count=program.instruction_count,
    )



def normalize_c64_charset_data(data: bytes) -> bytearray:
    """Normalisiert eine 2048- oder 2040-Byte-Zeichensatzdatei."""
    payload = bytes(data)
    if len(payload) == C64_CHARACTER_FILE_SIZE:
        return bytearray(payload)
    if len(payload) == C64_CHARACTER_EDITABLE_FILE_SIZE:
        return bytearray(C64_CHARACTER_BYTES) + bytearray(payload)
    raise ValueError(
        "Ein C64-Zeichensatz muss 2048 Bytes (256 Zeichen) oder "
        "2040 Bytes (Zeichen $01-$FF) enthalten."
    )


def c64_charset_character_rows(
    charset: Sequence[int],
    character_code: int,
) -> Tuple[int, ...]:
    code = int(character_code)
    if not 0 <= code < C64_CHARACTER_TOTAL_COUNT:
        raise ValueError("Der Zeichencode muss zwischen $00 und $FF liegen.")
    if len(charset) < C64_CHARACTER_FILE_SIZE:
        raise ValueError("Der Zeichensatz enthält weniger als 2048 Bytes.")
    start = code * C64_CHARACTER_BYTES
    return tuple(int(value) & 0xFF for value in charset[start:start + 8])


def c64_charset_set_character_rows(
    charset: bytearray,
    character_code: int,
    rows: Sequence[int],
) -> None:
    code = int(character_code)
    if not 1 <= code < C64_CHARACTER_TOTAL_COUNT:
        raise ValueError("Editierbar sind nur die Zeichen $01 bis $FF.")
    normalized = tuple(int(value) & 0xFF for value in rows)
    if len(normalized) != C64_CHARACTER_BYTES:
        raise ValueError("Ein C64-Zeichen muss genau acht Zeilen besitzen.")
    if len(charset) != C64_CHARACTER_FILE_SIZE:
        raise ValueError("Der Zeichensatz muss genau 2048 Bytes enthalten.")
    start = code * C64_CHARACTER_BYTES
    charset[start:start + 8] = bytes(normalized)


def c64_character_invert(rows: Sequence[int]) -> Tuple[int, ...]:
    return tuple((~int(value)) & 0xFF for value in rows)


def c64_character_mirror_horizontal(rows: Sequence[int]) -> Tuple[int, ...]:
    def reverse_bits(value: int) -> int:
        result = 0
        current = int(value) & 0xFF
        for _index in range(8):
            result = (result << 1) | (current & 1)
            current >>= 1
        return result

    return tuple(reverse_bits(value) for value in rows)


def c64_character_mirror_vertical(rows: Sequence[int]) -> Tuple[int, ...]:
    normalized = tuple(int(value) & 0xFF for value in rows)
    if len(normalized) != 8:
        raise ValueError("Ein C64-Zeichen muss genau acht Zeilen besitzen.")
    return tuple(reversed(normalized))


def c64_character_shift(
    rows: Sequence[int],
    delta_x: int,
    delta_y: int,
) -> Tuple[int, ...]:
    """Verschiebt ohne Wrap-Around; herausgeschobene Pixel gehen verloren."""
    source = tuple(int(value) & 0xFF for value in rows)
    if len(source) != 8:
        raise ValueError("Ein C64-Zeichen muss genau acht Zeilen besitzen.")

    shifted = [0] * 8
    dx = max(-7, min(7, int(delta_x)))
    dy = max(-7, min(7, int(delta_y)))
    for source_y, row in enumerate(source):
        target_y = source_y + dy
        if not 0 <= target_y < 8:
            continue
        if dx > 0:
            shifted[target_y] = (row >> dx) & 0xFF
        elif dx < 0:
            shifted[target_y] = (row << (-dx)) & 0xFF
        else:
            shifted[target_y] = row
    return tuple(shifted)


def format_c64_charset_asm(
    charset: Sequence[int],
    label: str = "C64CustomCharset",
) -> str:
    data = normalize_c64_charset_data(bytes(charset))
    lines = [
        "; 256 C64-Zeichen mit jeweils 8 Bitmapzeilen",
        "; Zeichen $00 ist reserviert, editierbar sind $01-$FF.",
        f"{label}:",
    ]
    for code in range(256):
        rows = c64_charset_character_rows(data, code)
        values = ", ".join(f"${value:02X}" for value in rows)
        lines.append(f"    .byte {values}    ; ${code:02X}")
    return "\n".join(lines) + "\n"


def format_c64_charset_c(
    charset: Sequence[int],
    identifier: str = "C64CustomCharset",
) -> str:
    data = normalize_c64_charset_data(bytes(charset))
    lines = [
        "/* 256 C64-Zeichen mit jeweils 8 Bitmapzeilen. */",
        f"const unsigned char {identifier}[256][8] = {{",
    ]
    for code in range(256):
        rows = c64_charset_character_rows(data, code)
        values = ", ".join(f"0x{value:02X}" for value in rows)
        comma = "," if code < 255 else ""
        lines.append(f"    {{ {values} }}{comma} /* 0x{code:02X} */")
    lines.append("};")
    return "\n".join(lines) + "\n"


def format_c64_charset_pascal(
    charset: Sequence[int],
    identifier: str = "C64CustomCharset",
) -> str:
    data = normalize_c64_charset_data(bytes(charset))
    lines = [
        "{ 256 C64-Zeichen mit jeweils 8 Bitmapzeilen. }",
        "const",
        f"    {identifier}: array[0..255, 0..7] of Byte = (",
    ]
    for code in range(256):
        rows = c64_charset_character_rows(data, code)
        values = ", ".join(f"${value:02X}" for value in rows)
        comma = "," if code < 255 else ""
        lines.append(f"        ({values}){comma} {{ ${code:02X} }}")
    lines.append("    );")
    return "\n".join(lines) + "\n"


C64_PALETTE_COLOR_COUNT = 16
C64_PALETTE_FILE_SIZE = C64_PALETTE_COLOR_COUNT * 3
C64_OUTPUT_FORMATS: Tuple[str, ...] = (
    "Assembler",
    "Pascal",
    "C",
    "BASIC",
)


def normalize_c64_color_hex(value: str) -> str:
    """Normalisiert eine RGB-Farbe auf #RRGGBB."""
    text = str(value).strip()
    if text.startswith("$"):
        text = text[1:]
    elif text.lower().startswith("0x"):
        text = text[2:]
    elif text.startswith("#"):
        text = text[1:]
    if not re.fullmatch(r"[0-9A-Fa-f]{6}", text):
        raise ValueError("Eine Farbe muss als #RRGGBB angegeben werden.")
    return "#" + text.upper()


def normalize_c64_palette_entries(
    entries: Sequence[Sequence[str]],
) -> Tuple[Tuple[str, str], ...]:
    if len(entries) != C64_PALETTE_COLOR_COUNT:
        raise ValueError("Eine C64-Palette muss genau 16 Farben enthalten.")
    normalized = []
    for index, entry in enumerate(entries):
        if len(entry) != 2:
            raise ValueError("Jeder Paletteneintrag benötigt Name und RGB-Wert.")
        name = str(entry[0]).strip() or f"Farbe {index}"
        normalized.append((name, normalize_c64_color_hex(entry[1])))
    return tuple(normalized)


def encode_c64_palette_data(entries: Sequence[Sequence[str]]) -> bytes:
    palette = normalize_c64_palette_entries(entries)
    result = bytearray()
    for _name, color_hex in palette:
        result.extend(bytes.fromhex(color_hex[1:]))
    return bytes(result)


def decode_c64_palette_data(
    data: bytes,
    names: Optional[Sequence[str]] = None,
) -> Tuple[Tuple[str, str], ...]:
    payload = bytes(data)
    if len(payload) != C64_PALETTE_FILE_SIZE:
        raise ValueError("Eine rohe C64-Palette muss genau 48 Bytes enthalten.")
    if names is None:
        names = tuple(name for name, _color in C64_CHARACTER_PALETTE)
    if len(names) != C64_PALETTE_COLOR_COUNT:
        raise ValueError("Für eine Palette werden genau 16 Farbnamen benötigt.")
    entries = []
    for index in range(C64_PALETTE_COLOR_COUNT):
        red, green, blue = payload[index * 3:index * 3 + 3]
        entries.append((str(names[index]), f"#{red:02X}{green:02X}{blue:02X}"))
    return tuple(entries)


def format_c64_charset_basic(
    charset: Sequence[int],
    variable_name: str = "CS",
) -> str:
    data = normalize_c64_charset_data(bytes(charset))
    lines = [
        "10 REM 256 C64-ZEICHEN, JEWEILS 8 BITMAPZEILEN",
        "20 REM ZEICHEN 0 IST RESERVIERT, EDITIERBAR SIND 1 BIS 255",
        f"30 DIM {variable_name}(255,7)",
        "40 FOR C=0 TO 255:FOR R=0 TO 7:READ "
        f"{variable_name}(C,R):NEXT R:NEXT C",
    ]
    line_number = 100
    for code in range(256):
        rows = c64_charset_character_rows(data, code)
        values = ",".join(str(value) for value in rows)
        lines.append(f"{line_number} DATA {values}:REM ${code:02X}")
        line_number += 10
    return "\n".join(lines) + "\n"


def format_c64_palette_asm(
    entries: Sequence[Sequence[str]],
    label: str = "C64CustomPalette",
) -> str:
    palette = normalize_c64_palette_entries(entries)
    lines = [
        "; 16 C64-Farben als RGB-Tripel",
        f"{label}:",
    ]
    for index, (name, color_hex) in enumerate(palette):
        red, green, blue = bytes.fromhex(color_hex[1:])
        lines.append(
            f"    .byte ${red:02X}, ${green:02X}, ${blue:02X}"
            f"    ; {index:02d}: {name}"
        )
    return "\n".join(lines) + "\n"


def format_c64_palette_c(
    entries: Sequence[Sequence[str]],
    identifier: str = "C64CustomPalette",
) -> str:
    palette = normalize_c64_palette_entries(entries)
    lines = [
        "/* 16 C64-Farben als RGB-Tripel. */",
        f"const unsigned char {identifier}[16][3] = {{",
    ]
    for index, (name, color_hex) in enumerate(palette):
        red, green, blue = bytes.fromhex(color_hex[1:])
        comma = "," if index < 15 else ""
        lines.append(
            f"    {{ 0x{red:02X}, 0x{green:02X}, 0x{blue:02X} }}{comma}"
            f" /* {index:02d}: {name} */"
        )
    lines.append("};")
    return "\n".join(lines) + "\n"


def format_c64_palette_pascal(
    entries: Sequence[Sequence[str]],
    identifier: str = "C64CustomPalette",
) -> str:
    palette = normalize_c64_palette_entries(entries)
    lines = [
        "{ 16 C64-Farben als RGB-Tripel. }",
        "const",
        f"    {identifier}: array[0..15, 0..2] of Byte = (",
    ]
    for index, (name, color_hex) in enumerate(palette):
        red, green, blue = bytes.fromhex(color_hex[1:])
        comma = "," if index < 15 else ""
        lines.append(
            f"        (${red:02X}, ${green:02X}, ${blue:02X}){comma}"
            f" {{ {index:02d}: {name} }}"
        )
    lines.append("    );")
    return "\n".join(lines) + "\n"


def format_c64_palette_basic(
    entries: Sequence[Sequence[str]],
    variable_name: str = "CP",
) -> str:
    palette = normalize_c64_palette_entries(entries)
    lines = [
        "10 REM 16 C64-FARBEN ALS RGB-TRIPEL",
        f"20 DIM {variable_name}(15,2)",
        "30 FOR C=0 TO 15:FOR K=0 TO 2:READ "
        f"{variable_name}(C,K):NEXT K:NEXT C",
    ]
    line_number = 100
    for index, (name, color_hex) in enumerate(palette):
        red, green, blue = bytes.fromhex(color_hex[1:])
        basic_name = re.sub(r"[^A-Za-z0-9 ]+", "", name).upper()
        lines.append(
            f"{line_number} DATA {red},{green},{blue}:REM {index:02d} {basic_name}"
        )
        line_number += 10
    return "\n".join(lines) + "\n"


def normalize_c64_output_format(format_name: str) -> str:
    value = str(format_name).strip().lower()
    mapping = {
        "assembler": "Assembler",
        "asm": "Assembler",
        "pascal": "Pascal",
        "pas": "Pascal",
        "c": "C",
        "basic": "BASIC",
        "bas": "BASIC",
    }
    try:
        return mapping[value]
    except KeyError as exc:
        raise ValueError(f"Unbekanntes Ausgabeformat: {format_name}") from exc


def c64_output_format_extension(format_name: str) -> str:
    output_format = normalize_c64_output_format(format_name)
    return {
        "Assembler": ".asm",
        "Pascal": ".pas",
        "C": ".h",
        "BASIC": ".bas",
    }[output_format]


def c64_output_format_filter(format_name: str) -> str:
    output_format = normalize_c64_output_format(format_name)
    return {
        "Assembler": "MOS-6510-Assembler (*.asm *.inc)",
        "Pascal": "Pascal-Quellcode (*.pas *.inc)",
        "C": "C-Quellcode (*.c *.h)",
        "BASIC": "BASIC-Quellcode (*.bas)",
    }[output_format]


def format_c64_charset_output(
    charset: Sequence[int],
    format_name: str,
) -> str:
    output_format = normalize_c64_output_format(format_name)
    if output_format == "Assembler":
        return format_c64_charset_asm(charset)
    if output_format == "Pascal":
        return format_c64_charset_pascal(charset)
    if output_format == "C":
        return format_c64_charset_c(charset)
    return format_c64_charset_basic(charset)


def format_c64_palette_output(
    entries: Sequence[Sequence[str]],
    format_name: str,
) -> str:
    output_format = normalize_c64_output_format(format_name)
    if output_format == "Assembler":
        return format_c64_palette_asm(entries)
    if output_format == "Pascal":
        return format_c64_palette_pascal(entries)
    if output_format == "C":
        return format_c64_palette_c(entries)
    return format_c64_palette_basic(entries)


# ---------------------------------------------------------------------------
# C64-Textbildschirm- und Pixelbildschirm-Editoren.
# Der Textbildschirm speichert 40x25 Zeichenbytes und 40x25 Farbbytes.
# Der Pixelbildschirm verwendet eine plattformneutrale 320x200-Farbindex-
# Flaeche mit 16 Farben; im Rohformat werden je zwei Pixel in einem Byte
# zusammengefasst.
# ---------------------------------------------------------------------------
C64_TEXT_SCREEN_COLUMNS = 40
C64_TEXT_SCREEN_ROWS = 25
C64_TEXT_SCREEN_CELL_COUNT = C64_TEXT_SCREEN_COLUMNS * C64_TEXT_SCREEN_ROWS
C64_TEXT_SCREEN_FILE_SIZE = C64_TEXT_SCREEN_CELL_COUNT * 2

C64_PIXEL_SCREEN_WIDTH = 320
C64_PIXEL_SCREEN_HEIGHT = 200
C64_PIXEL_SCREEN_PIXEL_COUNT = C64_PIXEL_SCREEN_WIDTH * C64_PIXEL_SCREEN_HEIGHT
C64_PIXEL_SCREEN_PACKED_SIZE = C64_PIXEL_SCREEN_PIXEL_COUNT // 2


def normalize_c64_text_screen_data(
    characters: Sequence[int],
    colors: Optional[Sequence[int]] = None,
) -> Tuple[bytearray, bytearray]:
    chars = bytearray(int(value) & 0xFF for value in characters)
    if len(chars) != C64_TEXT_SCREEN_CELL_COUNT:
        raise ValueError("Ein C64-Textbildschirm benötigt genau 1000 Zeichenbytes.")
    if colors is None:
        cols = bytearray([1] * C64_TEXT_SCREEN_CELL_COUNT)
    else:
        cols = bytearray(int(value) & 0x0F for value in colors)
    if len(cols) != C64_TEXT_SCREEN_CELL_COUNT:
        raise ValueError("Ein C64-Textbildschirm benötigt genau 1000 Farbbytes.")
    return chars, cols


def encode_c64_text_screen_data(
    characters: Sequence[int],
    colors: Sequence[int],
) -> bytes:
    chars, cols = normalize_c64_text_screen_data(characters, colors)
    return bytes(chars + cols)


def decode_c64_text_screen_data(data: bytes) -> Tuple[bytearray, bytearray]:
    payload = bytes(data)
    if len(payload) == C64_TEXT_SCREEN_CELL_COUNT:
        return normalize_c64_text_screen_data(payload, None)
    if len(payload) == C64_TEXT_SCREEN_FILE_SIZE:
        return normalize_c64_text_screen_data(
            payload[:C64_TEXT_SCREEN_CELL_COUNT],
            payload[C64_TEXT_SCREEN_CELL_COUNT:],
        )
    raise ValueError(
        "Eine Bildschirmseite muss 1000 Bytes (nur Zeichen) oder "
        "2000 Bytes (Zeichen und Farben) enthalten."
    )


def _format_asm_byte_rows(data: Sequence[int], width: int, comment: str) -> List[str]:
    values = [int(value) & 0xFF for value in data]
    lines = []
    for row_start in range(0, len(values), width):
        row = values[row_start:row_start + width]
        lines.append(
            "    .byte " + ", ".join(f"${value:02X}" for value in row)
            + f"    ; {comment} {row_start // width:02d}"
        )
    return lines


def format_c64_text_screen_asm(
    characters: Sequence[int],
    colors: Sequence[int],
) -> str:
    chars, cols = normalize_c64_text_screen_data(characters, colors)
    lines = [
        "; C64-Textbildschirm: 40 Spalten x 25 Zeilen",
        "C64TextScreenCharacters:",
    ]
    lines.extend(_format_asm_byte_rows(chars, 40, "Zeile"))
    lines.append("")
    lines.append("C64TextScreenColors:")
    lines.extend(_format_asm_byte_rows(cols, 40, "Farbzeile"))
    return "\n".join(lines) + "\n"


def format_c64_text_screen_c(
    characters: Sequence[int],
    colors: Sequence[int],
) -> str:
    chars, cols = normalize_c64_text_screen_data(characters, colors)
    lines = [
        "/* C64-Textbildschirm: 40 Spalten x 25 Zeilen. */",
        "const unsigned char C64TextScreenCharacters[25][40] = {",
    ]
    for row in range(25):
        start = row * 40
        values = ", ".join(f"0x{value:02X}" for value in chars[start:start + 40])
        lines.append(f"    {{ {values} }}{',' if row < 24 else ''}")
    lines.extend(["};", "", "const unsigned char C64TextScreenColors[25][40] = {"])
    for row in range(25):
        start = row * 40
        values = ", ".join(f"0x{value:02X}" for value in cols[start:start + 40])
        lines.append(f"    {{ {values} }}{',' if row < 24 else ''}")
    lines.append("};")
    return "\n".join(lines) + "\n"


def format_c64_text_screen_pascal(
    characters: Sequence[int],
    colors: Sequence[int],
) -> str:
    chars, cols = normalize_c64_text_screen_data(characters, colors)
    lines = [
        "{ C64-Textbildschirm: 40 Spalten x 25 Zeilen. }",
        "const",
        "    C64TextScreenCharacters: array[0..24, 0..39] of Byte = (",
    ]
    for row in range(25):
        start = row * 40
        values = ", ".join(f"${value:02X}" for value in chars[start:start + 40])
        lines.append(f"        ({values}){',' if row < 24 else ''}")
    lines.extend([
        "    );",
        "",
        "    C64TextScreenColors: array[0..24, 0..39] of Byte = (",
    ])
    for row in range(25):
        start = row * 40
        values = ", ".join(f"${value:02X}" for value in cols[start:start + 40])
        lines.append(f"        ({values}){',' if row < 24 else ''}")
    lines.append("    );")
    return "\n".join(lines) + "\n"


def format_c64_text_screen_basic(
    characters: Sequence[int],
    colors: Sequence[int],
) -> str:
    chars, cols = normalize_c64_text_screen_data(characters, colors)
    lines = [
        "10 REM C64-TEXTBILDSCHIRM 40 X 25",
        "20 DIM SC(999):DIM CO(999)",
        "30 FOR I=0 TO 999:READ SC(I):NEXT I",
        "40 FOR I=0 TO 999:READ CO(I):NEXT I",
    ]
    number = 100
    for data, label in ((chars, "ZEICHEN"), (cols, "FARBEN")):
        lines.append(f"{number} REM {label}")
        number += 10
        for start in range(0, 1000, 20):
            values = ",".join(str(value) for value in data[start:start + 20])
            lines.append(f"{number} DATA {values}")
            number += 10
    return "\n".join(lines) + "\n"


def format_c64_text_screen_output(
    characters: Sequence[int],
    colors: Sequence[int],
    format_name: str,
) -> str:
    output_format = normalize_c64_output_format(format_name)
    if output_format == "Assembler":
        return format_c64_text_screen_asm(characters, colors)
    if output_format == "Pascal":
        return format_c64_text_screen_pascal(characters, colors)
    if output_format == "C":
        return format_c64_text_screen_c(characters, colors)
    return format_c64_text_screen_basic(characters, colors)


def normalize_c64_pixel_screen(pixels: Sequence[int]) -> bytearray:
    result = bytearray(int(value) & 0x0F for value in pixels)
    if len(result) != C64_PIXEL_SCREEN_PIXEL_COUNT:
        raise ValueError("Ein Pixelbildschirm benötigt genau 320 x 200 Farbpixel.")
    return result


def encode_c64_pixel_screen_data(pixels: Sequence[int]) -> bytes:
    source = normalize_c64_pixel_screen(pixels)
    result = bytearray(C64_PIXEL_SCREEN_PACKED_SIZE)
    target = 0
    for index in range(0, len(source), 2):
        result[target] = ((source[index] & 0x0F) << 4) | (source[index + 1] & 0x0F)
        target += 1
    return bytes(result)


def decode_c64_pixel_screen_data(data: bytes) -> bytearray:
    payload = bytes(data)
    if len(payload) != C64_PIXEL_SCREEN_PACKED_SIZE:
        raise ValueError(
            "Ein 320x200-Pixelbildschirm mit 16 Farben muss genau 32000 Bytes enthalten."
        )
    result = bytearray(C64_PIXEL_SCREEN_PIXEL_COUNT)
    target = 0
    for value in payload:
        result[target] = (value >> 4) & 0x0F
        result[target + 1] = value & 0x0F
        target += 2
    return result


def _pixel_offset(x: int, y: int) -> Optional[int]:
    x_value = int(x)
    y_value = int(y)
    if 0 <= x_value < C64_PIXEL_SCREEN_WIDTH and 0 <= y_value < C64_PIXEL_SCREEN_HEIGHT:
        return y_value * C64_PIXEL_SCREEN_WIDTH + x_value
    return None


def c64_pixel_screen_set(pixels: bytearray, x: int, y: int, color: int) -> None:
    offset = _pixel_offset(x, y)
    if offset is not None:
        pixels[offset] = int(color) & 0x0F


def c64_pixel_screen_draw_line(
    pixels: bytearray,
    x1: int,
    y1: int,
    x2: int,
    y2: int,
    color: int,
) -> None:
    x = int(x1)
    y = int(y1)
    target_x = int(x2)
    target_y = int(y2)
    dx = abs(target_x - x)
    step_x = 1 if x < target_x else -1
    dy = -abs(target_y - y)
    step_y = 1 if y < target_y else -1
    error = dx + dy
    while True:
        c64_pixel_screen_set(pixels, x, y, color)
        if x == target_x and y == target_y:
            break
        doubled = error * 2
        if doubled >= dy:
            error += dy
            x += step_x
        if doubled <= dx:
            error += dx
            y += step_y


def _ordered_clipped_rect(x1: int, y1: int, x2: int, y2: int) -> Tuple[int, int, int, int]:
    left, right = sorted((int(x1), int(x2)))
    top, bottom = sorted((int(y1), int(y2)))
    return (
        max(0, left),
        max(0, top),
        min(C64_PIXEL_SCREEN_WIDTH - 1, right),
        min(C64_PIXEL_SCREEN_HEIGHT - 1, bottom),
    )


def c64_pixel_screen_draw_rect(
    pixels: bytearray, x1: int, y1: int, x2: int, y2: int, color: int
) -> None:
    left, top, right, bottom = _ordered_clipped_rect(x1, y1, x2, y2)
    c64_pixel_screen_draw_line(pixels, left, top, right, top, color)
    c64_pixel_screen_draw_line(pixels, left, bottom, right, bottom, color)
    c64_pixel_screen_draw_line(pixels, left, top, left, bottom, color)
    c64_pixel_screen_draw_line(pixels, right, top, right, bottom, color)


def c64_pixel_screen_fill_rect(
    pixels: bytearray, x1: int, y1: int, x2: int, y2: int, color: int
) -> None:
    left, top, right, bottom = _ordered_clipped_rect(x1, y1, x2, y2)
    if right < left or bottom < top:
        return
    value = int(color) & 0x0F
    width = right - left + 1
    row_data = bytes([value]) * width
    for y in range(top, bottom + 1):
        start = y * C64_PIXEL_SCREEN_WIDTH + left
        pixels[start:start + width] = row_data


def _circle_octants(center_x: int, center_y: int, x: int, y: int) -> Tuple[Tuple[int, int], ...]:
    return (
        (center_x + x, center_y + y),
        (center_x - x, center_y + y),
        (center_x + x, center_y - y),
        (center_x - x, center_y - y),
        (center_x + y, center_y + x),
        (center_x - y, center_y + x),
        (center_x + y, center_y - x),
        (center_x - y, center_y - x),
    )


def c64_pixel_screen_draw_circle(
    pixels: bytearray, center_x: int, center_y: int, radius: int, color: int
) -> None:
    r = max(0, int(radius))
    x = r
    y = 0
    decision = 1 - r
    while x >= y:
        for point_x, point_y in _circle_octants(int(center_x), int(center_y), x, y):
            c64_pixel_screen_set(pixels, point_x, point_y, color)
        y += 1
        if decision < 0:
            decision += 2 * y + 1
        else:
            x -= 1
            decision += 2 * (y - x) + 1


def c64_pixel_screen_fill_circle(
    pixels: bytearray, center_x: int, center_y: int, radius: int, color: int
) -> None:
    r = max(0, int(radius))
    cx = int(center_x)
    cy = int(center_y)
    x = r
    y = 0
    decision = 1 - r
    while x >= y:
        for row_y, left, right in (
            (cy + y, cx - x, cx + x),
            (cy - y, cx - x, cx + x),
            (cy + x, cx - y, cx + y),
            (cy - x, cx - y, cx + y),
        ):
            c64_pixel_screen_fill_rect(pixels, left, row_y, right, row_y, color)
        y += 1
        if decision < 0:
            decision += 2 * y + 1
        else:
            x -= 1
            decision += 2 * (y - x) + 1


def c64_pixel_screen_flood_fill(
    pixels: bytearray, x: int, y: int, color: int
) -> None:
    offset = _pixel_offset(x, y)
    if offset is None:
        return
    replacement = int(color) & 0x0F
    target = pixels[offset]
    if target == replacement:
        return
    stack = [(int(x), int(y))]
    while stack:
        current_x, current_y = stack.pop()
        current_offset = _pixel_offset(current_x, current_y)
        if current_offset is None or pixels[current_offset] != target:
            continue
        pixels[current_offset] = replacement
        stack.append((current_x - 1, current_y))
        stack.append((current_x + 1, current_y))
        stack.append((current_x, current_y - 1))
        stack.append((current_x, current_y + 1))


def format_c64_pixel_screen_asm(pixels: Sequence[int]) -> str:
    packed = encode_c64_pixel_screen_data(pixels)
    lines = [
        "; 320x200-Pixelbildschirm, 16 Farben, zwei Pixel pro Byte",
        "C64PixelScreenWidth = 320",
        "C64PixelScreenHeight = 200",
        "C64PixelScreenData:",
    ]
    lines.extend(_format_asm_byte_rows(packed, 16, "Block"))
    return "\n".join(lines) + "\n"


def format_c64_pixel_screen_c(pixels: Sequence[int]) -> str:
    packed = encode_c64_pixel_screen_data(pixels)
    lines = [
        "/* 320x200-Pixelbildschirm, 16 Farben, zwei Pixel pro Byte. */",
        "#define C64_PIXEL_SCREEN_WIDTH 320",
        "#define C64_PIXEL_SCREEN_HEIGHT 200",
        f"const unsigned char C64PixelScreenData[{len(packed)}] = {{",
    ]
    for start in range(0, len(packed), 16):
        values = ", ".join(f"0x{value:02X}" for value in packed[start:start + 16])
        lines.append(f"    {values}{',' if start + 16 < len(packed) else ''}")
    lines.append("};")
    return "\n".join(lines) + "\n"


def format_c64_pixel_screen_pascal(pixels: Sequence[int]) -> str:
    packed = encode_c64_pixel_screen_data(pixels)
    lines = [
        "{ 320x200-Pixelbildschirm, 16 Farben, zwei Pixel pro Byte. }",
        "const",
        "    C64PixelScreenWidth = 320;",
        "    C64PixelScreenHeight = 200;",
        f"    C64PixelScreenData: array[0..{len(packed) - 1}] of Byte = (",
    ]
    for start in range(0, len(packed), 16):
        values = ", ".join(f"${value:02X}" for value in packed[start:start + 16])
        lines.append(f"        {values}{',' if start + 16 < len(packed) else ''}")
    lines.append("    );")
    return "\n".join(lines) + "\n"


def format_c64_pixel_screen_basic(pixels: Sequence[int]) -> str:
    packed = encode_c64_pixel_screen_data(pixels)
    lines = [
        "10 REM 320X200-PIXELBILDSCHIRM, 16 FARBEN",
        f"20 DIM PX({len(packed) - 1})",
        f"30 FOR I=0 TO {len(packed) - 1}:READ PX(I):NEXT I",
    ]
    number = 100
    for start in range(0, len(packed), 16):
        values = ",".join(str(value) for value in packed[start:start + 16])
        lines.append(f"{number} DATA {values}")
        number += 10
    return "\n".join(lines) + "\n"


def format_c64_pixel_screen_output(pixels: Sequence[int], format_name: str) -> str:
    output_format = normalize_c64_output_format(format_name)
    if output_format == "Assembler":
        return format_c64_pixel_screen_asm(pixels)
    if output_format == "Pascal":
        return format_c64_pixel_screen_pascal(pixels)
    if output_format == "C":
        return format_c64_pixel_screen_c(pixels)
    return format_c64_pixel_screen_basic(pixels)


# ---------------------------------------------------------------------------
# CHM-Hilfe: Projekt-, Inhalts- und Indexdaten
# ---------------------------------------------------------------------------
@dataclass
class ChmSitemapEntry:
    title: str
    local: str = ""
    children: List["ChmSitemapEntry"] = field(default_factory=list)

# ---------------------------------------------------------------------------
# Toleranter Parser für die OBJECT/PARAM-Struktur von HHC und HHK.
# ---------------------------------------------------------------------------
class ChmSitemapParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.roots: List[ChmSitemapEntry] = []
        self.parents: List[Optional[ChmSitemapEntry]] = []
        self.last_at_depth: Dict[int, ChmSitemapEntry] = {}
        self.params: Optional[Dict[str, str]] = None

    def handle_starttag(self, tag, attrs) -> None:
        tag = tag.lower()
        if tag == "ul":
            depth = len(self.parents)
            parent = self.last_at_depth.get(depth)
            if parent is None and self.parents:
                parent = self.parents[-1]
            self.parents.append(parent)
            return

        if tag == "object":
            self.params = {}
            return

        if tag == "param" and self.params is not None:
            values = {key.lower(): value or "" for key, value in attrs}
            name = values.get("name", "").strip().lower()
            if name:
                self.params[name] = values.get("value", "").strip()

    def handle_endtag(self, tag) -> None:
        tag = tag.lower()
        if tag == "object" and self.params is not None:
            title = self.params.get("name", "").strip()
            local = self.params.get("local", "").strip()
            if title or local:
                entry = ChmSitemapEntry(
                    title or Path(local).name or "(ohne Titel)",
                    local,
                )
                parent = self.parents[-1] if self.parents else None
                if parent is None:
                    self.roots.append(entry)
                else:
                    parent.children.append(entry)
                self.last_at_depth[len(self.parents)] = entry
            self.params = None
            return

        if tag == "ul" and self.parents:
            self.parents.pop()
            maximum_depth = len(self.parents)
            for depth in list(self.last_at_depth):
                if depth > maximum_depth:
                    del self.last_at_depth[depth]

def decode_chm_text(path: Path) -> str:
    data = path.read_bytes()
    if data.startswith(b"\xef\xbb\xbf"):
        return data.decode("utf-8-sig", errors="replace")
    if data.startswith((b"\xff\xfe", b"\xfe\xff")):
        return data.decode("utf-16", errors="replace")

    header = data[:8192].decode("ascii", errors="ignore")
    match = re.search(
        r"charset\s*=\s*[\"']?\s*([A-Za-z0-9._-]+)",
        header,
        re.IGNORECASE,
    )
    encodings = [match.group(1)] if match else []
    encodings.extend(["utf-8", "cp1252", "latin-1"])
    for encoding in encodings:
        try:
            return data.decode(encoding)
        except (LookupError, UnicodeDecodeError):
            continue
    return data.decode("latin-1", errors="replace")

def parse_chm_sitemap(path: Optional[Path]) -> List[ChmSitemapEntry]:
    if path is None or not path.is_file():
        return []
    parser = ChmSitemapParser()
    parser.feed(decode_chm_text(path))
    parser.close()
    return parser.roots

def iter_chm_files(root: Path) -> Iterable[Path]:
    for path in root.rglob("*"):
        if path.is_file():
            yield path

def find_chm_file_by_suffix(root: Path, suffix: str) -> Optional[Path]:
    suffix = suffix.lower()
    candidates = [
        path for path in iter_chm_files(root)
        if path.suffix.lower() == suffix
    ]
    return min(
        candidates,
        key=lambda path: (len(path.parts), str(path).lower()),
        default=None,
    )

# ---------------------------------------------------------------------------
# Zerlegt ein HHC/HHK-Local-Feld in relativen Pfad und Sprungmarke.
# ---------------------------------------------------------------------------
def clean_chm_local(value: str) -> Tuple[str, str]:
    value = html.unescape(value.strip()).strip("\"'").replace("\\", "/")
    lowered = value.lower()
    if "::/" in lowered:
        value = value[lowered.index("::/") + 3:]
    value = value.split("?", 1)[0]
    path_part, separator, fragment = value.partition("#")
    from urllib.parse import unquote
    path_part = unquote(path_part).lstrip("/")
    parts = [
        part for part in path_part.split("/")
        if part not in ("", ".")
    ]
    if any(part == ".." for part in parts):
        return "", ""
    return "/".join(parts), unquote(fragment) if separator else ""

# ---------------------------------------------------------------------------
# Loest Windows-typische, nicht case-sensitive CHM-Pfade sicher auf.
# ---------------------------------------------------------------------------
def resolve_chm_path(root: Path, relative: str) -> Optional[Path]:
    current = root
    for part in Path(relative).parts:
        exact = current / part
        if exact.exists():
            current = exact
            continue
        try:
            current = next(
                child for child in current.iterdir()
                if child.name.casefold() == part.casefold()
            )
        except (StopIteration, OSError):
            return None

    try:
        current.resolve().relative_to(root.resolve())
    except (OSError, ValueError):
        return None
    return current if current.is_file() else None

# ---------------------------------------------------------------------------
# Stage ASM 1: stabile C64-Hilfekontexte fuer klickbare Disassembler-Overlays.
#
# WICHTIG: Ein Python-Dictionary wird mit Doppelpunkt geschrieben.
#     help_py = {"test": 21}
# Die Zahl ist die stabile Context-ID; der Text bleibt der Such-Fallback.
# ---------------------------------------------------------------------------
help_py = {
    "test": 21,
    # Stage ASM 7: Hilfe-Kontext fuer das semantische Relocation-/Bootstrap-Overlay.
    # Wenn c64.chm eine passende MAP/ALIAS-Zuordnung besitzt, wird ID 22 direkt
    # aufgeloest; andernfalls sucht der integrierte Viewer nach dem Topic-Text.
    "relocation_bootstrap": 22,
}


def read_chm_context_map(root: Path) -> Dict[int, str]:
    """Liest numerische CHM-Context-IDs aus [MAP]/[ALIAS], soweit vorhanden.

    Unterstuetzt die ueblichen HHP-Formen::

        [MAP]
        #define IDH_TEST 21

        [ALIAS]
        IDH_TEST=test.html

    sowie MAP-Includes/Header mit ``#define``. Fehlen diese Metadaten in einer
    bereits kompilierten CHM, bleibt die Text-/Keyword-Suche des Viewers der
    sichere Fallback.
    """
    root = Path(root)
    project = find_chm_file_by_suffix(root, ".hhp")
    if project is None:
        return {}

    map_symbols: Dict[str, int] = {}
    aliases: Dict[str, str] = {}
    include_names: List[str] = []
    section = ""

    def parse_define(line: str) -> None:
        match = re.match(
            r"^\s*#define\s+([A-Za-z_][A-Za-z0-9_]*)\s+"
            r"(0[xX][0-9A-Fa-f]+|\d+)\b",
            line,
        )
        if not match:
            return
        try:
            map_symbols[match.group(1)] = int(match.group(2), 0)
        except ValueError:
            pass

    for raw_line in decode_chm_text(project).splitlines():
        line = raw_line.strip()
        if not line or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            section = line.casefold()
            continue

        if section == "[map]":
            parse_define(line)
            include = re.match(r'^\s*#include\s+[<"]([^>"]+)[>"]', line)
            if include:
                include_names.append(include.group(1).strip())
                continue
            if "=" in line:
                key, value = line.split("=", 1)
                try:
                    map_symbols[key.strip()] = int(value.strip(), 0)
                except ValueError:
                    pass

        elif section == "[alias]" and "=" in line:
            key, value = line.split("=", 1)
            key = key.strip()
            value = value.strip()
            if key and value:
                aliases[key] = value

    # MAP-Konstanten liegen bei vielen Projekten in einer Headerdatei.
    # Zuerst explizite Includes, danach als robuste Reserve alle kleinen .h/.hh.
    header_candidates: List[Path] = []
    for name in include_names:
        candidate = resolve_chm_path(root, name.replace("\\", "/"))
        if candidate is not None:
            header_candidates.append(candidate)
    try:
        for candidate in root.rglob("*"):
            if candidate.is_file() and candidate.suffix.casefold() in {".h", ".hh", ".hpp"}:
                if candidate not in header_candidates:
                    header_candidates.append(candidate)
    except OSError:
        pass

    for header in header_candidates:
        try:
            for raw_line in decode_chm_text(header).splitlines():
                parse_define(raw_line)
        except OSError:
            continue

    result: Dict[int, str] = {}
    for symbol, local in aliases.items():
        context_id = map_symbols.get(symbol)
        if context_id is None:
            # Einige HHP-Dateien verwenden die numerische ID direkt links.
            try:
                context_id = int(symbol, 0)
            except ValueError:
                continue
        relative, fragment = clean_chm_local(local)
        if not relative:
            continue
        result[int(context_id)] = relative + (("#" + fragment) if fragment else "")
    return result


def read_chm_project_options(project_file: Optional[Path]) -> Dict[str, str]:
    if project_file is None:
        return {}
    result: Dict[str, str] = {}
    in_options = False
    for raw_line in decode_chm_text(project_file).splitlines():
        line = raw_line.strip()
        if line.startswith("[") and line.endswith("]"):
            in_options = line.casefold() == "[options]"
            continue
        if in_options and "=" in line:
            key, value = line.split("=", 1)
            result[key.strip().casefold()] = value.strip()
    return result

# ---------------------------------------------------------------------------
# Entpackt CHM per 7-Zip oder unter Windows per hh.exe.
# ---------------------------------------------------------------------------
class ChmExtractor:
    @staticmethod
    def seven_zip_command() -> Optional[str]:
        for command in ("7zz", "7z", "7za"):
            found = shutil.which(command)
            if found:
                return found
        if os.name == "nt":
            for variable in ("ProgramFiles", "ProgramFiles(x86)"):
                base = os.environ.get(variable)
                if base:
                    candidate = Path(base) / "7-Zip" / "7z.exe"
                    if candidate.is_file():
                        return str(candidate)
        return None

    @staticmethod
    def extract_with_7zip(command: str, source: Path, target: Path) -> None:
        completed = subprocess.run(
            [command, "x", "-y", f"-o{target}", str(source)],
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=120,
            check=False,
        )
        if completed.returncode not in (0, 1):
            raise RuntimeError(
                "7-Zip konnte die CHM-Datei nicht entpacken.\n\n"
                + completed.stdout[-1500:].strip()
            )

    @staticmethod
    def extract_with_windows_help(source: Path, target: Path) -> None:
        helper = Path(os.environ.get("WINDIR", r"C:\Windows")) / "hh.exe"
        if not helper.is_file():
            raise RuntimeError("hh.exe wurde nicht gefunden.")

        process = subprocess.Popen(
            [str(helper), "-decompile", str(target), str(source)],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
        try:
            process.wait(timeout=10)
        except subprocess.TimeoutExpired:
            process.terminate()

        deadline = time.monotonic() + 30.0
        previous_count = -1
        stable_rounds = 0
        while time.monotonic() < deadline:
            count = sum(1 for _ in iter_chm_files(target))
            if count > 0 and count == previous_count:
                stable_rounds += 1
                if stable_rounds >= 4:
                    return
            else:
                stable_rounds = 0
            previous_count = count
            time.sleep(0.25)
        if previous_count <= 0:
            raise RuntimeError("Windows HTML Help hat keine Dateien extrahiert.")

    @classmethod
    def extract(cls, source: Path, target: Path) -> None:
        errors: List[str] = []
        command = cls.seven_zip_command()
        if command:
            try:
                cls.extract_with_7zip(command, source, target)
                if any(iter_chm_files(target)):
                    return
            except Exception as exc:
                errors.append(str(exc))

        if os.name == "nt":
            try:
                cls.extract_with_windows_help(source, target)
                if any(iter_chm_files(target)):
                    return
            except Exception as exc:
                errors.append(str(exc))

        hint = (
            "Installiere 7-Zip und stelle 7z/7zz ueber PATH bereit."
            if os.name == "nt"
            else "Installiere 7-Zip, z. B. mit 'sudo apt install p7zip-full'."
        )
        details = "\n\n".join(errors)
        raise RuntimeError(
            "Kein verwendbares CHM-Entpackprogramm gefunden.\n"
            f"{hint}\n\n{details}"
        )


# ---------------------------------------------------------------------------
# D64-Dateisystem
# Eine D64-Datei besitzt kein unterstütztes oder gültiges Layout.
# ---------------------------------------------------------------------------
class D64Error(Exception):
    pass

# ---------------------------------------------------------------------------
# Liefert die Sektoranzahl einer 1541-Spur.
# ---------------------------------------------------------------------------
def sectors_on_track(track: int) -> int:
    if 1  <= track <= 17:   return 21
    if 18 <= track <= 24:   return 19
    if 25 <= track <= 30:   return 18
    if 31 <= track <= 42:   return 17
    
    raise D64Error(f"Ungültige D64-Spur: {track}")

def sector_count_for_tracks(track_count: int) -> int:
    return sum(sectors_on_track(track) for track in range(1, track_count + 1))

# ---------------------------------------------------------------------------
# Erkennt 35- bis 42-Spur-Images, optional mit Fehlerbyte-Tabelle.
# ---------------------------------------------------------------------------
def detect_d64_layout(file_size: int) -> Tuple[int, int, bool]:
    for track_count in range(35, 43):
        sector_count = sector_count_for_tracks(track_count)
        data_size = sector_count * 256
        if file_size == data_size:
            return track_count, data_size, False
        if file_size == data_size + sector_count:
            return track_count, data_size, True

    raise D64Error(
        f"Nicht unterstützte D64-Größe: {file_size:,} Bytes. "
        "Erwartet wird ein 35- bis 42-Spur-Image, optional mit Fehlerbytes."
    )

# ---------------------------------------------------------------------------
# Konvertiert die für D64-Namen übliche PETSCII-Teilmenge.
# ---------------------------------------------------------------------------
def petscii_to_text(data: bytes) -> str:
    result = []
    for value in data:
        if value in (0x00, 0xA0):
            result.append(" ")
        elif 0x20 <= value <= 0x5F:
            result.append(chr(value))
        elif 0x61 <= value <= 0x7A:
            result.append(chr(value).upper())
        elif 0xC1 <= value <= 0xDA:
            result.append(chr(value - 0x80))
        else:
            result.append("·")
    return "".join(result).rstrip()


@dataclass(frozen=True)
class D64DirectoryEntry:
    name: str
    file_type: str
    blocks: int
    start_track: int
    start_sector: int
    closed: bool
    locked: bool

    @property
    def type_display(self) -> str:
        prefix = "" if self.closed else "*"
        suffix = "<" if self.locked else ""
        return f"{prefix}{self.file_type}{suffix}"

    def listing_line(self) -> str:
        quoted_name = f'"{self.name[:16]}"'
        return (
            f"{self.blocks:>5}  {quoted_name:<18} "
            f"{self.type_display:<5}  {self.start_track:02d}/{self.start_sector:02d}"
        )


@dataclass(frozen=True)
class D64Directory:
    disk_name: str
    disk_id: str
    dos_type: str
    track_count: int
    has_error_table: bool
    free_blocks: Optional[int]
    entries: Tuple[D64DirectoryEntry, ...]


class D64Image:
    FILE_TYPES = {
        0: "DEL",
        1: "SEQ",
        2: "PRG",
        3: "USR",
        4: "REL",
    }

    def __init__(self, path: Path):
        self.path = Path(path)
        try:
            raw_data = self.path.read_bytes()
        except OSError as exc:
            raise D64Error(f"D64-Datei kann nicht gelesen werden: {exc}") from exc

        self.track_count, data_size, self.has_error_table = detect_d64_layout(
            len(raw_data)
        )
        self.data = raw_data[:data_size]

    def sector_offset(self, track: int, sector: int) -> int:
        if not 1 <= track <= self.track_count:
            raise D64Error(f"Spur {track} liegt außerhalb des Images.")

        sector_count = sectors_on_track(track)
        if not 0 <= sector < sector_count:
            raise D64Error(
                f"Sektor {track}/{sector} ist ungültig; Spur {track} "
                f"besitzt die Sektoren 0 bis {sector_count - 1}."
            )

        previous_sectors = sum(
            sectors_on_track(value) for value in range(1, track)
        )
        return (previous_sectors + sector) * 256

    def read_sector(self, track: int, sector: int) -> bytes:
        offset = self.sector_offset(track, sector)
        return self.data[offset : offset + 256]

    def _free_blocks(self, bam: bytes) -> Optional[int]:
        # Das Standard-BAM enthält Einträge für die Spuren 1 bis 35.
        if len(bam) < 144:
            return None
        return sum(bam[4 + (track - 1) * 4] for track in range(1, 36))

    def directory(self) -> D64Directory:
        bam = self.read_sector(18, 0)
        disk_name = petscii_to_text(bam[0x90:0xA0]) or "UNBENANNT"
        disk_id   = petscii_to_text(bam[0xA2:0xA4])
        dos_type  = petscii_to_text(bam[0xA5:0xA7])

        track     = bam[0] or 18
        sector    = bam[1] if bam[0] else 1
        visited   = set()
        entries   = []

        while track:
            location = (track, sector)
            if location in visited:
                raise D64Error(
                    f"Zyklische Verzeichniskette bei Spur/Sektor {track}/{sector}."
                )
            visited.add(location)

            directory_sector = self.read_sector(track, sector)
            for index in range(8):
                offset = 2 + index * 32
                raw_type = directory_sector[offset]
                # Typ 0 bezeichnet gelöschte/DEL-Einträge. Die Dateiliste soll
                # nur die aktuell im C64-Verzeichnis vorhandenen Dateien zeigen.
                if raw_type == 0 or (raw_type & 0x07) == 0:
                    continue

                type_number = raw_type & 0x07
                file_type = self.FILE_TYPES.get(type_number, f"T{type_number}")
                start_track = directory_sector[offset + 1]
                start_sector = directory_sector[offset + 2]
                name = petscii_to_text(directory_sector[offset + 3 : offset + 19])
                blocks = int.from_bytes(
                    directory_sector[offset + 28 : offset + 30], "little"
                )

                entries.append(
                    D64DirectoryEntry(
                        name=name or "(OHNE NAME)",
                        file_type=file_type,
                        blocks=blocks,
                        start_track=start_track,
                        start_sector=start_sector,
                        closed=bool(raw_type & 0x80),
                        locked=bool(raw_type & 0x40),
                    )
                )

            track = directory_sector[0]
            sector = directory_sector[1]

        return D64Directory(
            disk_name=disk_name,
            disk_id=disk_id,
            dos_type=dos_type,
            track_count=self.track_count,
            has_error_table=self.has_error_table,
            free_blocks=self._free_blocks(bam),
            entries=tuple(entries),
        )


