# Stage 190: Sichtbare Pascal-Unit-Hierarchie. Die Projektdatei behaelt den
# vollstaendigen echten Pfad; lediglich die Darstellung wird nach dem ersten
# Unit-Namespace aufgeteilt. Dadurch wird z. B.
#
#     Crypto.blake2.pas  ->  Units / Crypto / blake2.pas
#     System.Objects.pas ->  Units / System / Objects.pas
#     System.pas         ->  Units / System / System.pas
#
# Auch Dateien, die physisch nur Objects.pas heissen, werden anhand der
# ``unit System.Objects;``-Deklaration korrekt dem System-Knoten zugeordnet.
def project_pascal_unit_tree_parts(
    path: Path,
    title: str = "",
) -> Tuple[str, str]:
    candidate = Path(path).expanduser()
    filename = candidate.name or str(title or "").strip() or "Unit.pas"
    suffix = Path(filename).suffix
    unit_name = ""

    if candidate.suffix.casefold() in {".pas", ".pp"} and candidate.is_file():
        source = ""
        try:
            source = candidate.read_text(encoding="utf-8-sig")
        except UnicodeError:
            try:
                source = candidate.read_text(encoding="cp1252")
            except OSError:
                source = ""
        except OSError:
            source = ""
        if source:
            # Fuer die Unit-Kopfzeile reicht eine kommentarbereinigte Suche.
            cleaned = re.sub(r"\(\*.*?\*\)", " ", source, flags=re.DOTALL)
            cleaned = re.sub(r"\{.*?\}", " ", cleaned, flags=re.DOTALL)
            cleaned = re.sub(r"//[^\r\n]*", " ", cleaned)
            match = re.search(
                r"\bunit\s+([A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*)\s*;",
                cleaned,
                re.IGNORECASE,
            )
            if match:
                unit_name = match.group(1)

    if not unit_name:
        stem = Path(filename).stem.strip()
        if "." in stem:
            unit_name = stem
        else:
            # Fallback fuer Layouts wie units/System/Objects.pas, falls die
            # Quelldatei gerade nicht lesbar ist. Generische Ordnernamen
            # werden nicht als Namespace missverstanden.
            parent_name = candidate.parent.name.strip()
            generic_parents = {
                "", "unit", "units", "pascal", "src", "source", "sources",
                "runtime", "compiler", "frontend", "c64pascal", "pe32", "pe64",
                "build", "bin", "obj", "objects",
            }
            if (
                parent_name
                and parent_name.casefold() not in generic_parents
                and parent_name.casefold() != stem.casefold()
            ):
                unit_name = parent_name + "." + stem
            else:
                unit_name = stem

    name_parts = [part for part in unit_name.split(".") if part]
    namespace = name_parts[0] if name_parts else (Path(filename).stem or "Units")
    if len(name_parts) > 1:
        leaf_stem = ".".join(name_parts[1:])
        leaf_name = leaf_stem + (suffix or candidate.suffix or ".pas")
    else:
        leaf_name = filename
    return namespace, leaf_name


PROJECT_CATEGORY_TITLES: Dict[str, str] = {
    key: title for key, title, _extensions in PROJECT_CATEGORIES
}
PROJECT_CATEGORY_EXTENSIONS: Dict[str, Tuple[str, ...]] = {
    key: extensions for key, _title, extensions in PROJECT_CATEGORIES
}
PROJECT_CATEGORY_DEFAULT_EXTENSIONS: Dict[str, str] = {
    key: (extensions[0] if extensions else ".dat")
    for key, _title, extensions in PROJECT_CATEGORIES
}

# ---------------------------------------------------------------------------
# Liefert einen freien Namen ``Unbenannt_<n>.<ext>``.
#
# Geprueft werden sowohl die bereits sichtbaren Projekteintraege als auch
# vorhandene Dateien im Zielverzeichnis. Dadurch wird kein Eintrag und keine
# Datei versehentlich ueberschrieben.
# ---------------------------------------------------------------------------
def project_untitled_filename(
    category_key: str,
    existing_names: Iterable[str] = (),
    *,
    directory: Optional[Path] = None,
) -> str:
    extension = PROJECT_CATEGORY_DEFAULT_EXTENSIONS.get(category_key, ".dat")
    if extension and not extension.startswith("."):
        extension = "." + extension
    used_names = {str(value).casefold() for value in existing_names}
    used_stems = {Path(str(value)).stem.casefold() for value in existing_names}
    target_directory = Path(directory) if directory is not None else None
    number = 1
    while True:
        filename = f"Unbenannt_{number}{extension}"
        stem = Path(filename).stem.casefold()
        name_used = filename.casefold() in used_names or stem in used_stems
        file_used = bool(
            target_directory is not None
            and (target_directory / filename).exists()
        )
        if not name_used and not file_used:
            return filename
        number += 1


def empty_project_entries() -> Dict[str, List[Dict[str, str]]]:
    entries = {key: [] for key, _title, _extensions in PROJECT_CATEGORIES}
    # Verschachtelte COFF-Archive liegen bewusst nicht als neue Root-Kategorie
    # vor, sondern unter C-Programme -> Archive. Der reservierte Schlüssel
    # hält diese Hierarchie in der *.pro-Datei getrennt von normalen C-Dateien.
    entries[PROJECT_C_ARCHIVES_KEY] = []
    entries[PROJECT_PROLOG_KNOWLEDGE_KEY] = []
    entries[PROJECT_BREAKPOINTS_KEY] = []
    entries[PROJECT_BOOKMARKS_KEY] = []
    # Stage ASM 63: Arbeitsverzeichnis (Pfadfeld/current_directory) und
    # TreeList-Wurzel getrennt halten. Alte Projekte dürfen beide leer lassen.
    entries[PROJECT_WORKING_DIRECTORY_KEY] = []
    entries[PROJECT_WORKSPACE_ROOT_KEY] = []
    entries[PROJECT_VIEW_STATE_KEY] = []
    entries[PROJECT_PRIMARY_DOCK_LAYOUT_KEY] = []
    entries[PROJECT_C64_OPEN_EDITORS_KEY] = []
    entries[PROJECT_SESSION_GEOMETRY_KEY] = []
    entries[PROJECT_C64_LAST_BASIC_FILE_KEY] = []
    for _dbase_key in PROJECT_DBASE_ENTRY_KEYS:
        entries[_dbase_key] = []
    # Stage 174: separate Ziel-/Rollenlisten für Pascal.
    for _special_key in PROJECT_PASCAL_TARGET_ENTRY_KEYS.values():
        entries[_special_key] = []
    for _special_key in PROJECT_PASCAL_TABLE_ENTRY_KEYS.values():
        entries[_special_key] = []
    for _settings in PROJECT_WINDOWS_TARGET_SETTINGS.values():
        entries[_settings["input_key"]] = []
        entries[_settings["output_key"]] = []
        # Stage 197: relative Darstellung/Speicherung ist standardmäßig aktiv.
        entries[_settings["input_relative_key"]] = [{"value": "true"}]
        entries[_settings["output_relative_key"]] = [{"value": "true"}]
        entries[_settings["link_with_ordinals_key"]] = [{"value": "false"}]
        entries[_settings["workstation_mode_key"]] = [{"value": "false"}]
    entries[PROJECT_C64_OPTIMIZER_ACTIVE_PROFILE_KEY] = [{"value": "68000"}]
    for _profile_settings in PROJECT_C64_OPTIMIZER_PROFILES.values():
        entries[_profile_settings["enabled_key"]] = [{"value": "true"}]
        entries[_profile_settings["strategy_key"]] = [{"value": "direct"}]
    for _profile_settings in PROJECT_C64_PACKER_PROFILES.values():
        entries[_profile_settings["enabled_key"]] = [{"value": "false"}]
        entries[_profile_settings["mode_key"]] = [{"value": "none"}]
        entries[_profile_settings["search_key"]] = [{"value": "balanced"}]
        # Stage ASM 55: symbolic De-Cruncher source is shown in the packed ASM
        # editor by default, preserving Stage 51-54 behaviour.
        entries[_profile_settings["include_decruncher_source_key"]] = [{"value": "true"}]
    for _profile_settings in PROJECT_C64_ENVIRONMENT_PROFILES.values():
        entries[_profile_settings["screen_keyboard_key"]] = [{"value": "false"}]
        entries[_profile_settings["keyboard_layout_key"]] = [{"value": "qwertz"}]
    return entries


def project_category_for_path(path: Path) -> str:
    suffix = Path(path).suffix.casefold()
    for key, _title, extensions in PROJECT_CATEGORIES:
        if suffix in extensions:
            return key
    return "other"


def _project_storage_path(path_value: str, project_path: Path) -> str:
    candidate = Path(path_value).expanduser()
    try:
        resolved = candidate.resolve()
    except OSError:
        resolved = candidate
    try:
        relative = os.path.relpath(
            str(resolved),
            str(project_path.parent.resolve()),
        )
        return Path(relative).as_posix()
    except (OSError, ValueError):
        return str(resolved)


def _project_storage_path_mode(
    path_value: str,
    project_path: Path,
    *,
    relative: bool,
) -> str:
    """Stage 197: Projektpfad abhängig vom UI-Modus serialisieren."""
    if relative:
        return _project_storage_path(path_value, project_path)
    candidate = Path(path_value).expanduser()
    try:
        return str(candidate.resolve())
    except (OSError, RuntimeError, ValueError):
        return str(candidate.absolute())


def _project_bool_entry(
    entries: Dict[str, List[Dict[str, str]]],
    key: str,
    default: bool = True,
) -> bool:
    values = entries.get(key, ())
    if not values:
        return bool(default)
    raw = str(values[0].get("value", "true" if default else "false")).strip().casefold()
    return raw not in {"0", "false", "no", "off", "absolute", "absolute paths", "absolute pfade"}


def _parse_project_bool(value: str, default: bool = True) -> bool:
    raw = str(value or "").strip().casefold()
    if not raw:
        return bool(default)
    return raw not in {"0", "false", "no", "off", "absolute", "absolute paths", "absolute pfade"}


def _project_loaded_path(path_value: str, project_path: Path) -> str:
    candidate = Path(path_value).expanduser()
    if not candidate.is_absolute():
        candidate = project_path.parent / candidate
    try:
        return str(candidate.resolve())
    except OSError:
        return str(candidate)


def format_project_ini(
    entries: Dict[str, List[Dict[str, str]]],
    project_path: Path,
) -> str:
    project_path = Path(project_path)
    parser = configparser.ConfigParser(interpolation=None)
    parser.optionxform = str
    parser["Project"] = {
        "Format": "dBase2Many Project",
        "Version": "2",
    }
    # Stage ASM 63: WorkingDirectory ist exakt der im Dateisystem-Dock
    # angezeigte Pfad (current_directory). WorkspaceRoot hält zusätzlich die
    # Wurzel der linken TreeList fest. Beide Pfade werden möglichst relativ zur
    # *.pro-Datei gespeichert.
    _working_entries = entries.get(PROJECT_WORKING_DIRECTORY_KEY, ())
    _working_value = (
        str(_working_entries[0].get("path", "") or "").strip()
        if _working_entries else ""
    )
    _workspace_entries = entries.get(PROJECT_WORKSPACE_ROOT_KEY, ())
    _workspace_value = (
        str(_workspace_entries[0].get("path", "") or "").strip()
        if _workspace_entries else ""
    )
    if _working_value:
        parser["Project"]["WorkingDirectory"] = _project_storage_path(
            _working_value, project_path
        )
    if _workspace_value:
        parser["Project"]["WorkspaceRoot"] = _project_storage_path(
            _workspace_value, project_path
        )

    # Stage ASM 65: Der komplette Dock-/Ansichtszustand wird projektbezogen
    # gespeichert. Base64 vermeidet Binärdaten in der INI-Datei und bleibt
    # vollständig text-/git-freundlich.
    _view_entries = entries.get("__project_view_state__", ())
    _view_state = (
        str(_view_entries[0].get("value", "") or "").strip()
        if _view_entries else ""
    )
    if _view_state:
        parser["Project"]["ViewState"] = _view_state

    # Stage ASM 69: explizite Split-/Stack-Beziehung der beiden seitlichen
    # Primaer-Docks. JSON bleibt menschenlesbar und unabhaengig vom Qt-Blob.
    _primary_layout_entries = entries.get("__project_primary_dock_layout__", ())
    _primary_layout = (
        _primary_layout_entries[0].get("value", {})
        if _primary_layout_entries else {}
    )
    if isinstance(_primary_layout, str):
        try:
            _primary_layout = json.loads(_primary_layout)
        except json.JSONDecodeError:
            _primary_layout = {}
    if isinstance(_primary_layout, dict) and _primary_layout.get("paired"):
        parser["Project"]["PrimaryDockLayout"] = json.dumps(
            _primary_layout, ensure_ascii=False, separators=(",", ":")
        )

    # Stage ASM 70: explizite Geometrien zusätzlich zum Qt-ViewState.
    # Dadurch können Hauptfenster, einzelne Docks und ihre Sichtbarkeit
    # deterministisch und unabhängig von Qt-Heuristiken wiederhergestellt werden.
    _geometry_entries = entries.get("__project_session_geometry__", ())
    _geometry = (
        _geometry_entries[0].get("value", {})
        if _geometry_entries else {}
    )
    if isinstance(_geometry, str):
        try:
            _geometry = json.loads(_geometry)
        except json.JSONDecodeError:
            _geometry = {}
    if isinstance(_geometry, dict) and _geometry:
        parser["Session.Geometry"] = {"Version": "2"}
        for _key in (
            "MainWindow", "CentralArea", "PrimaryDockArea",
            "FileSystemDock", "ProjectDock", "ProtocolDock",
        ):
            _payload = _geometry.get(_key)
            if isinstance(_payload, dict) and _payload:
                parser["Session.Geometry"][_key] = json.dumps(
                    _payload, ensure_ascii=False, separators=(",", ":")
                )

    # Stage ASM 70: zuletzt geöffnete BASIC-Datei separat merken. Die offene
    # Editorliste enthält weiterhin alle Tabs; dieser Wert ist die MRU-Referenz.
    _last_basic_entries = entries.get("__project_c64_last_basic_file__", ())
    _last_basic_path = (
        str(_last_basic_entries[0].get("path", "") or "").strip()
        if _last_basic_entries else ""
    )
    if _last_basic_path:
        parser["Session.C64"] = {
            "LastBasicFile": _project_storage_path(_last_basic_path, project_path)
        }

    # Stage ASM 67: offene C64-BASIC-Dateireferenzen als Editor-Session.
    # Die Pfade werden wie alle Projektressourcen moeglichst relativ zur
    # Projektdatei gespeichert.
    _c64_editor_section = "Session.C64.Editors"
    parser[_c64_editor_section] = {"Title": "Offene C64 BASIC Editoren"}
    for _index, _entry in enumerate(
        entries.get("__project_c64_open_editors__", ()), 1
    ):
        _path_value = str(_entry.get("path", "") or "").strip()
        if not _path_value:
            continue
        _payload = {
            "path": _project_storage_path(_path_value, project_path),
            "active": bool(_entry.get("active", False)),
        }
        # Stage ASM 70: Editor-/Bildschirmtastatur-Geometrie je BASIC-Datei.
        for _name in (
            "keyboard_visible", "splitter_sizes", "keyboard_last_sizes",
            "splitter_state", "splitter_handle_width",
            "keyboard_width", "keyboard_height",
            "keyboard_host_width", "keyboard_host_height",
            "keyboard_scroll_x", "keyboard_scroll_y",
        ):
            if _name in _entry:
                _payload[_name] = _entry[_name]
        parser[_c64_editor_section][f"Item{_index:04d}"] = json.dumps(
            _payload, ensure_ascii=False, separators=(",", ":")
        )

    for key, title, _extensions in PROJECT_CATEGORIES:
        section = f"Category.{key}"
        parser[section] = {"Title": title}
        for index, entry in enumerate(entries.get(key, ()), 1):
            path_value = str(entry.get("path", "")).strip()
            if not path_value:
                continue
            payload = {
                "title": str(entry.get("title", "") or Path(path_value).name),
                "path": _project_storage_path(path_value, project_path),
            }
            parser[section][f"Item{index:04d}"] = json.dumps(
                payload,
                ensure_ascii=False,
                separators=(",", ":"),
            )
    # Stage ASM 29: dBase-Unterknoten außer Programme separat speichern.
    for _role, _title, _extensions, _entry_key in PROJECT_DBASE_GROUPS:
        if _entry_key == "dbase":
            continue
        _section = PROJECT_DBASE_SECTIONS[_entry_key]
        parser[_section] = {"Title": _title}
        for _index, _entry in enumerate(entries.get(_entry_key, ()), 1):
            _path_value = str(_entry.get("path", "")).strip()
            if not _path_value:
                continue
            _payload = {
                "title": str(_entry.get("title", "") or Path(_path_value).name),
                "path": _project_storage_path(_path_value, project_path),
            }
            parser[_section][f"Item{_index:04d}"] = json.dumps(
                _payload, ensure_ascii=False, separators=(",", ":")
            )

    # C-Programme -> Archive -> <archive.a> -> <object.o>
    # wird als eigener INI-Abschnitt gespeichert, damit alte Projektdateien
    # weiterhin ohne Migration geladen werden können.
    archive_section = "Category.c.archives"
    parser[archive_section] = {"Title": "Archive"}
    for index, archive in enumerate(entries.get(PROJECT_C_ARCHIVES_KEY, ()), 1):
        archive_path = str(archive.get("path", "")).strip()
        archive_title = str(archive.get("title", "")).strip()
        objects = []
        for obj in archive.get("objects", ()):
            object_path = str(obj.get("path", "")).strip()
            if not object_path:
                continue
            objects.append({
                "title": str(obj.get("title", "") or Path(object_path).name),
                "path": _project_storage_path(object_path, project_path),
            })
        payload = {
            "title": archive_title or (Path(archive_path).name if archive_path else f"library_{index}.a"),
            "path": _project_storage_path(archive_path, project_path) if archive_path else "",
            "objects": objects,
        }
        parser[archive_section][f"Item{index:04d}"] = json.dumps(
            payload, ensure_ascii=False, separators=(",", ":")
        )

    # PROLOG-Programme -> Wissen-Datenbanken -> *.pl/*.prolog
    knowledge_section = "Category.prolog.knowledge"
    parser[knowledge_section] = {"Title": "Wissen-Datenbanken"}
    for index, entry in enumerate(entries.get(PROJECT_PROLOG_KNOWLEDGE_KEY, ()), 1):
        path_value = str(entry.get("path", "")).strip()
        if not path_value:
            continue
        payload = {
            "title": str(entry.get("title", "") or Path(path_value).name),
            "path": _project_storage_path(path_value, project_path),
        }
        parser[knowledge_section][f"Item{index:04d}"] = json.dumps(
            payload, ensure_ascii=False, separators=(",", ":")
        )

    # Stage 174: Pascal-Programme -> Windows PE32/PE32+ -> Module/Units.
    for (_target, _role), _entry_key in PROJECT_PASCAL_TARGET_ENTRY_KEYS.items():
        _section = PROJECT_PASCAL_TARGET_SECTIONS[(_target, _role)]
        parser[_section] = {
            "Title": (
                "Windows PE32" if _target == "pe32" else "Windows PE32+"
            ) + (" Module" if _role == "modules" else " Units")
        }
        for _index, _entry in enumerate(entries.get(_entry_key, ()), 1):
            _path_value = str(_entry.get("path", "")).strip()
            if not _path_value:
                continue
            _payload = {
                "title": str(_entry.get("title", "") or Path(_path_value).name),
                "path": _project_storage_path(_path_value, project_path),
            }
            parser[_section][f"Item{_index:04d}"] = json.dumps(
                _payload, ensure_ascii=False, separators=(",", ":")
            )

    # Stage 236: Pascal-Tabellen werden pro Windows-Ziel separat gespeichert.
    for _target, _entry_key in PROJECT_PASCAL_TABLE_ENTRY_KEYS.items():
        _section = PROJECT_PASCAL_TABLE_SECTIONS[_target]
        parser[_section] = {
            "Title": (
                "Windows PE32" if _target == "pe32" else "Windows PE32+"
            ) + " Tabellen"
        }
        for _index, _entry in enumerate(entries.get(_entry_key, ()), 1):
            _path_value = str(_entry.get("path", "")).strip()
            if not _path_value:
                continue
            _payload = {
                "title": str(_entry.get("title", "") or Path(_path_value).name),
                "path": _project_storage_path(_path_value, project_path),
            }
            parser[_section][f"Item{_index:04d}"] = json.dumps(
                _payload, ensure_ascii=False, separators=(",", ":")
            )

    # Stage 246: Breakpoints/Bookmarks werden pro Quelldatei gespeichert.
    # Die Blätter selbst sind reine 1-basierte Zeilennummern.
    for _marker_kind, (_entry_key, _section) in PROJECT_MARKER_SECTIONS.items():
        parser[_section] = {
            "Title": "Break points" if _marker_kind == "breakpoint" else "Bookmarks"
        }
        for _index, _entry in enumerate(entries.get(_entry_key, ()), 1):
            _path_value = str(_entry.get("path", "")).strip()
            if not _path_value:
                continue
            _lines = sorted({
                int(_line)
                for _line in _entry.get("lines", ())
                if str(_line).strip() and int(_line) > 0
            })
            if not _lines:
                continue
            _payload = {
                "title": str(_entry.get("title", "") or Path(_path_value).name),
                "path": _project_storage_path(_path_value, project_path),
                "lines": _lines,
            }
            parser[_section][f"Item{_index:04d}"] = json.dumps(
                _payload, ensure_ascii=False, separators=(",", ":")
            )

    # Stage 197: PE32 und PE32+ speichern getrennte Eingabe-/Ausgabe-
    # Verzeichnisse und zusätzlich den Darstellungsmodus. RelativePaths=true
    # serialisiert die Pfade relativ zur *.pro-Datei, false schreibt absolute
    # Pfade. Die PathXXXX-Reihenfolge bleibt die echte Suchpriorität.
    for _target, _settings in PROJECT_WINDOWS_TARGET_SETTINGS.items():
        _input_relative = _project_bool_entry(
            entries, _settings["input_relative_key"], True
        )
        _output_relative = _project_bool_entry(
            entries, _settings["output_relative_key"], True
        )
        _input_section = _settings["input_section"]
        parser[_input_section] = {
            "Title": f"Windows {_settings['title']} Compiler Eingabe-Verzeichnis",
            "RelativePaths": "true" if _input_relative else "false",
        }
        for _index, _entry in enumerate(
            entries.get(_settings["input_key"], ()), 1
        ):
            _path_value = str(_entry.get("path", "")).strip()
            if not _path_value:
                continue
            parser[_input_section][f"Path{_index:04d}"] = _project_storage_path_mode(
                _path_value,
                project_path,
                relative=_input_relative,
            )

        _output_section = _settings["output_section"]
        parser[_output_section] = {
            "Title": f"Windows {_settings['title']} Compiler Ausgabe-Verzeichnis",
            "RelativePaths": "true" if _output_relative else "false",
        }
        _output_entries = entries.get(_settings["output_key"], ())
        if _output_entries:
            _output_value = str(_output_entries[0].get("path", "")).strip()
            if _output_value:
                parser[_output_section]["Path"] = _project_storage_path_mode(
                    _output_value,
                    project_path,
                    relative=_output_relative,
                )

        _workstation_mode = _project_bool_entry(
            entries, _settings["workstation_mode_key"], False
        )
        parser[_settings["environment_section"]] = {
            "Title": f"Windows {_settings['title']} Umgebung",
            "WorkstationMode": "true" if _workstation_mode else "false",
        }

        _link_with_ordinals = _project_bool_entry(
            entries, _settings["link_with_ordinals_key"], False
        )
        parser[_settings["linker_section"]] = {
            "Title": f"Windows {_settings['title']} Linker",
            "LinkWithOrdinals": "true" if _link_with_ordinals else "false",
        }

    # Stage ASM 48: C=64 Optimizerprofile speichern.
    _active_entries = entries.get(PROJECT_C64_OPTIMIZER_ACTIVE_PROFILE_KEY, ())
    _active_profile = (
        str(_active_entries[0].get("value", "68000") or "68000").strip()
        if _active_entries else "68000"
    )
    if _active_profile not in PROJECT_C64_OPTIMIZER_PROFILES:
        _active_profile = "68000"
    parser["Settings.C64"] = {
        "Title": "C=64 Projekteinstellungen",
        "ActiveProfile": _active_profile,
    }
    for _profile, _profile_settings in PROJECT_C64_OPTIMIZER_PROFILES.items():
        _enabled = _project_bool_entry(entries, _profile_settings["enabled_key"], True)
        _strategy_entries = entries.get(_profile_settings["strategy_key"], ())
        _strategy = (
            str(_strategy_entries[0].get("value", "direct") or "direct")
            if _strategy_entries else "direct"
        )
        _strategy = _normalize_project_c64_optimizer_strategy(_strategy)
        parser[_profile_settings["section"]] = {
            "Title": f"C=64 {_profile} Compiler Optimizer",
            "Enabled": "true" if _enabled else "false",
            "Strategy": _strategy,
        }

    # Stage ASM 60: C64-Umgebung / optionale Bildschirmtastatur und Layout.
    for _profile, _profile_settings in PROJECT_C64_ENVIRONMENT_PROFILES.items():
        _screen_keyboard = _project_bool_entry(
            entries, _profile_settings["screen_keyboard_key"], False
        )
        _layout_entries = entries.get(_profile_settings["keyboard_layout_key"], ())
        _keyboard_layout = _normalize_project_c64_keyboard_layout(
            _layout_entries[0].get("value", "qwertz") if _layout_entries else "qwertz"
        )
        parser[_profile_settings["section"]] = {
            "Title": f"C=64 {_profile} Umgebung",
            "ScreenKeyboard": "true" if _screen_keyboard else "false",
            "KeyboardLayout": _keyboard_layout,
        }

    # Stage ASM 50: Image-Packer je C64-Profil speichern.
    for _profile, _profile_settings in PROJECT_C64_PACKER_PROFILES.items():
        _enabled = _project_bool_entry(entries, _profile_settings["enabled_key"], False)
        _mode_entries = entries.get(_profile_settings["mode_key"], ())
        _mode = _normalize_project_c64_packer_mode(
            _mode_entries[0].get("value", "none") if _mode_entries else "none"
        )
        _search_entries = entries.get(_profile_settings["search_key"], ())
        _search = _normalize_project_c64_packer_search(
            _search_entries[0].get("value", "balanced") if _search_entries else "balanced"
        )
        _include_decruncher_source = _project_bool_entry(
            entries, _profile_settings["include_decruncher_source_key"], True
        )
        parser[_profile_settings["section"]] = {
            "Title": f"C=64 {_profile} Compiler Image Packer",
            "Enabled": "true" if _enabled else "false",
            "Mode": _mode,
            "Search": _search,
            "IncludeDecruncherSource": "true" if _include_decruncher_source else "false",
        }

    from io import StringIO
    stream = StringIO()
    parser.write(stream)
    return stream.getvalue()


def parse_project_ini(text: str, project_path: Path) -> Dict[str, List[Dict[str, str]]]:
    parser = configparser.ConfigParser(interpolation=None)
    parser.optionxform = str
    parser.read_string(text)
    entries = empty_project_entries()

    # Stage ASM 63: das sichtbare Arbeitsverzeichnis und die TreeList-Wurzel
    # getrennt wiederherstellen. Bei Stage-57-Projekten ohne WorkspaceRoot
    # dient WorkingDirectory zugleich als Root (voll rückwärtskompatibel).
    if parser.has_section("Project"):
        _working_value = str(
            parser.get("Project", "WorkingDirectory", fallback="") or ""
        ).strip()
        _workspace_value = str(
            parser.get("Project", "WorkspaceRoot", fallback="") or ""
        ).strip()
        if _working_value:
            _loaded_working = _project_loaded_path(
                _working_value, Path(project_path)
            )
            entries[PROJECT_WORKING_DIRECTORY_KEY] = [{"path": _loaded_working}]
        if _workspace_value:
            entries[PROJECT_WORKSPACE_ROOT_KEY] = [{
                "path": _project_loaded_path(_workspace_value, Path(project_path))
            }]
        elif _working_value:
            entries[PROJECT_WORKSPACE_ROOT_KEY] = [{"path": _loaded_working}]

        # Stage ASM 65: Projektlayout aus der INI übernehmen. Ungültige oder
        # ältere Projekte dürfen den Wert einfach weglassen.
        _view_state = str(
            parser.get("Project", "ViewState", fallback="") or ""
        ).strip()
        if _view_state:
            entries[PROJECT_VIEW_STATE_KEY] = [{"value": _view_state}]

        _primary_layout_text = str(
            parser.get("Project", "PrimaryDockLayout", fallback="") or ""
        ).strip()
        if _primary_layout_text:
            try:
                _primary_layout = json.loads(_primary_layout_text)
            except json.JSONDecodeError:
                _primary_layout = {}
            if isinstance(_primary_layout, dict) and _primary_layout.get("paired"):
                entries["__project_primary_dock_layout__"] = [{"value": _primary_layout}]

    # Stage ASM 70: explizite Fenster-/Dockgeometrien laden.
    if parser.has_section("Session.Geometry"):
        _geometry = {}
        for _key in (
            "MainWindow", "CentralArea", "PrimaryDockArea",
            "FileSystemDock", "ProjectDock", "ProtocolDock",
        ):
            _text = str(parser.get("Session.Geometry", _key, fallback="") or "").strip()
            if not _text:
                continue
            try:
                _payload = json.loads(_text)
            except json.JSONDecodeError:
                _payload = {}
            if isinstance(_payload, dict):
                _geometry[_key] = _payload
        if _geometry:
            entries["__project_session_geometry__"] = [{"value": _geometry}]

    if parser.has_section("Session.C64"):
        _last_basic = str(
            parser.get("Session.C64", "LastBasicFile", fallback="") or ""
        ).strip()
        if _last_basic:
            entries["__project_c64_last_basic_file__"] = [{
                "path": _project_loaded_path(_last_basic, Path(project_path))
            }]

    # Stage ASM 67: gespeicherte C64-BASIC-Editor-Dateireferenzen laden.
    _c64_editor_section = "Session.C64.Editors"
    if parser.has_section(_c64_editor_section):
        _values = sorted(
            (
                (name, value)
                for name, value in parser.items(_c64_editor_section)
                if name.casefold().startswith("item")
            ),
            key=lambda pair: pair[0].casefold(),
        )
        for _name, _value in _values:
            try:
                _payload = json.loads(_value)
            except json.JSONDecodeError:
                _payload = {"path": _value, "active": False}
            _path_value = str(_payload.get("path", "") or "").strip()
            if not _path_value:
                continue
            _editor_entry = {
                "path": _project_loaded_path(_path_value, Path(project_path)),
                "active": bool(_payload.get("active", False)),
            }
            for _field in (
                "keyboard_visible", "splitter_sizes", "keyboard_last_sizes",
                "splitter_state", "splitter_handle_width",
                "keyboard_width", "keyboard_height",
                "keyboard_host_width", "keyboard_host_height",
                "keyboard_scroll_x", "keyboard_scroll_y",
            ):
                if _field in _payload:
                    _editor_entry[_field] = _payload[_field]
            entries.setdefault("__project_c64_open_editors__", []).append(_editor_entry)

    for key, _title, _extensions in PROJECT_CATEGORIES:
        section = f"Category.{key}"
        if not parser.has_section(section):
            continue
        values = sorted(
            (
                (name, value)
                for name, value in parser.items(section)
                if name.casefold().startswith("item")
            ),
            key=lambda pair: pair[0].casefold(),
        )
        for _name, value in values:
            try:
                payload = json.loads(value)
            except json.JSONDecodeError:
                payload = {"path": value, "title": Path(value).name}
            path_value = str(payload.get("path", "")).strip()
            if not path_value:
                continue
            loaded_path = _project_loaded_path(path_value, Path(project_path))
            entries[key].append(
                {
                    "title": str(payload.get("title", "") or Path(loaded_path).name),
                    "path": loaded_path,
                }
            )

    # Stage ASM 29: dBase-Ressourcen aus den festen Unterknoten laden.
    for _role, _title, _extensions, _entry_key in PROJECT_DBASE_GROUPS:
        if _entry_key == "dbase":
            continue
        _section = PROJECT_DBASE_SECTIONS[_entry_key]
        if not parser.has_section(_section):
            continue
        _values = sorted(
            ((name, value) for name, value in parser.items(_section)
             if name.casefold().startswith("item")),
            key=lambda pair: pair[0].casefold(),
        )
        for _name, _value in _values:
            try:
                _payload = json.loads(_value)
            except json.JSONDecodeError:
                _payload = {"path": _value, "title": Path(_value).name}
            _path_value = str(_payload.get("path", "")).strip()
            if not _path_value:
                continue
            _loaded_path = _project_loaded_path(_path_value, Path(project_path))
            entries[_entry_key].append({
                "title": str(_payload.get("title", "") or Path(_loaded_path).name),
                "path": _loaded_path,
            })

    archive_section = "Category.c.archives"
    if parser.has_section(archive_section):
        values = sorted(
            (
                (name, value)
                for name, value in parser.items(archive_section)
                if name.casefold().startswith("item")
            ),
            key=lambda pair: pair[0].casefold(),
        )
        for _name, value in values:
            try:
                payload = json.loads(value)
            except json.JSONDecodeError:
                continue
            if not isinstance(payload, dict):
                continue
            archive_path = str(payload.get("path", "")).strip()
            loaded_archive_path = (
                _project_loaded_path(archive_path, Path(project_path))
                if archive_path else ""
            )
            object_entries = []
            for obj in payload.get("objects", ()):
                if not isinstance(obj, dict):
                    continue
                object_path = str(obj.get("path", "")).strip()
                if not object_path:
                    continue
                loaded_object_path = _project_loaded_path(
                    object_path, Path(project_path)
                )
                object_entries.append({
                    "title": str(obj.get("title", "") or Path(loaded_object_path).name),
                    "path": loaded_object_path,
                })
            entries[PROJECT_C_ARCHIVES_KEY].append({
                "title": str(
                    payload.get("title", "")
                    or (Path(loaded_archive_path).name if loaded_archive_path else "library.a")
                ),
                "path": loaded_archive_path,
                "objects": object_entries,
            })

    knowledge_section = "Category.prolog.knowledge"
    if parser.has_section(knowledge_section):
        values = sorted(
            (
                (name, value)
                for name, value in parser.items(knowledge_section)
                if name.casefold().startswith("item")
            ),
            key=lambda pair: pair[0].casefold(),
        )
        for _name, value in values:
            try:
                payload = json.loads(value)
            except json.JSONDecodeError:
                payload = {"path": value, "title": Path(value).name}
            path_value = str(payload.get("path", "")).strip()
            if not path_value:
                continue
            loaded_path = _project_loaded_path(path_value, Path(project_path))
            entries[PROJECT_PROLOG_KNOWLEDGE_KEY].append({
                "title": str(payload.get("title", "") or Path(loaded_path).name),
                "path": loaded_path,
            })
    # Stage 174: optionale Pascal-Zielzweige laden.
    for (_target, _role), _entry_key in PROJECT_PASCAL_TARGET_ENTRY_KEYS.items():
        _section = PROJECT_PASCAL_TARGET_SECTIONS[(_target, _role)]
        if not parser.has_section(_section):
            continue
        _values = sorted(
            (
                (name, value)
                for name, value in parser.items(_section)
                if name.casefold().startswith("item")
            ),
            key=lambda pair: pair[0].casefold(),
        )
        for _name, _value in _values:
            try:
                _payload = json.loads(_value)
            except json.JSONDecodeError:
                _payload = {"path": _value, "title": Path(_value).name}
            _path_value = str(_payload.get("path", "")).strip()
            if not _path_value:
                continue
            _loaded_path = _project_loaded_path(_path_value, Path(project_path))
            entries[_entry_key].append({
                "title": str(_payload.get("title", "") or Path(_loaded_path).name),
                "path": _loaded_path,
            })

    # Stage 236: optionale Pascal-Tabellenzweige laden.
    for _target, _entry_key in PROJECT_PASCAL_TABLE_ENTRY_KEYS.items():
        _section = PROJECT_PASCAL_TABLE_SECTIONS[_target]
        if not parser.has_section(_section):
            continue
        _values = sorted(
            (
                (name, value)
                for name, value in parser.items(_section)
                if name.casefold().startswith("item")
            ),
            key=lambda pair: pair[0].casefold(),
        )
        for _name, _value in _values:
            try:
                _payload = json.loads(_value)
            except json.JSONDecodeError:
                _payload = {"path": _value, "title": Path(_value).name}
            _path_value = str(_payload.get("path", "")).strip()
            if not _path_value:
                continue
            _loaded_path = _project_loaded_path(_path_value, Path(project_path))
            entries[_entry_key].append({
                "title": str(_payload.get("title", "") or Path(_loaded_path).name),
                "path": _loaded_path,
            })

    # Stage 246: persistente Breakpoints/Bookmarks laden.
    for _marker_kind, (_entry_key, _section) in PROJECT_MARKER_SECTIONS.items():
        if not parser.has_section(_section):
            continue
        _values = sorted(
            (
                (name, value)
                for name, value in parser.items(_section)
                if name.casefold().startswith("item")
            ),
            key=lambda pair: pair[0].casefold(),
        )
        for _name, _value in _values:
            try:
                _payload = json.loads(_value)
            except json.JSONDecodeError:
                continue
            if not isinstance(_payload, dict):
                continue
            _path_value = str(_payload.get("path", "")).strip()
            if not _path_value:
                continue
            _loaded_path = _project_loaded_path(_path_value, Path(project_path))
            _lines = []
            for _line in _payload.get("lines", ()):
                try:
                    _line_number = int(_line)
                except (TypeError, ValueError):
                    continue
                if _line_number > 0 and _line_number not in _lines:
                    _lines.append(_line_number)
            if _lines:
                entries[_entry_key].append({
                    "title": str(
                        _payload.get("title", "") or Path(_loaded_path).name
                    ),
                    "path": _loaded_path,
                    "lines": sorted(_lines),
                })

    # Stage 196: zuerst die getrennten 32-/64-Bit-Abschnitte laden.
    _have_arch_settings = False
    for _target, _settings in PROJECT_WINDOWS_TARGET_SETTINGS.items():
        _input_section = _settings["input_section"]
        _output_section = _settings["output_section"]
        _environment_section = _settings["environment_section"]
        _linker_section = _settings["linker_section"]
        if parser.has_section(_input_section):
            _have_arch_settings = True
            _input_relative = _parse_project_bool(
                parser.get(_input_section, "RelativePaths", fallback="true"),
                True,
            )
            entries[_settings["input_relative_key"]] = [
                {"value": "true" if _input_relative else "false"}
            ]
            _values = sorted(
                (
                    (name, value)
                    for name, value in parser.items(_input_section)
                    if name.casefold().startswith("path")
                ),
                key=lambda pair: pair[0].casefold(),
            )
            for _name, _value in _values:
                _path_value = str(_value).strip()
                if not _path_value:
                    continue
                entries[_settings["input_key"]].append({
                    "path": _project_loaded_path(
                        _path_value, Path(project_path)
                    ),
                })
        if parser.has_section(_output_section):
            _have_arch_settings = True
            _output_relative = _parse_project_bool(
                parser.get(_output_section, "RelativePaths", fallback="true"),
                True,
            )
            entries[_settings["output_relative_key"]] = [
                {"value": "true" if _output_relative else "false"}
            ]
            _output_value = str(
                parser.get(_output_section, "Path", fallback="")
            ).strip()
            if _output_value:
                entries[_settings["output_key"]].append({
                    "path": _project_loaded_path(
                        _output_value, Path(project_path)
                    ),
                })
        if parser.has_section(_environment_section):
            _have_arch_settings = True
            _workstation_mode = _parse_project_bool(
                parser.get(
                    _environment_section,
                    "WorkstationMode",
                    fallback="false",
                ),
                False,
            )
            entries[_settings["workstation_mode_key"]] = [{
                "value": "true" if _workstation_mode else "false"
            }]
        if parser.has_section(_linker_section):
            _link_with_ordinals = _parse_project_bool(
                parser.get(
                    _linker_section,
                    "LinkWithOrdinals",
                    fallback="false",
                ),
                False,
            )
            entries[_settings["link_with_ordinals_key"]] = [{
                "value": "true" if _link_with_ordinals else "false"
            }]

    # Stage ASM 48: C=64 Optimizerprofile laden.
    if parser.has_section("Settings.C64"):
        _active_profile = str(
            parser.get("Settings.C64", "ActiveProfile", fallback="68000")
        ).strip()
        if _active_profile not in PROJECT_C64_OPTIMIZER_PROFILES:
            _active_profile = "68000"
        entries[PROJECT_C64_OPTIMIZER_ACTIVE_PROFILE_KEY] = [{"value": _active_profile}]
    for _profile, _profile_settings in PROJECT_C64_OPTIMIZER_PROFILES.items():
        _section = _profile_settings["section"]
        if not parser.has_section(_section):
            continue
        _enabled = _parse_project_bool(
            parser.get(_section, "Enabled", fallback="true"), True
        )
        _strategy = _normalize_project_c64_optimizer_strategy(
            parser.get(_section, "Strategy", fallback="direct")
        )
        entries[_profile_settings["enabled_key"]] = [
            {"value": "true" if _enabled else "false"}
        ]
        entries[_profile_settings["strategy_key"]] = [{"value": _strategy}]

    # Stage ASM 60: C64-Umgebung / Bildschirmtastatur und Layout laden.
    for _profile, _profile_settings in PROJECT_C64_ENVIRONMENT_PROFILES.items():
        _section = _profile_settings["section"]
        if not parser.has_section(_section):
            continue
        _screen_keyboard = _parse_project_bool(
            parser.get(_section, "ScreenKeyboard", fallback="false"), False
        )
        _keyboard_layout = _normalize_project_c64_keyboard_layout(
            parser.get(_section, "KeyboardLayout", fallback="qwertz")
        )
        entries[_profile_settings["screen_keyboard_key"]] = [{
            "value": "true" if _screen_keyboard else "false"
        }]
        entries[_profile_settings["keyboard_layout_key"]] = [{
            "value": _keyboard_layout
        }]

    # Stage ASM 50: C64 Image-Packer laden.
    for _profile, _profile_settings in PROJECT_C64_PACKER_PROFILES.items():
        _section = _profile_settings["section"]
        if not parser.has_section(_section):
            continue
        _enabled = _parse_project_bool(
            parser.get(_section, "Enabled", fallback="false"), False
        )
        _mode = _normalize_project_c64_packer_mode(
            parser.get(_section, "Mode", fallback="none")
        )
        _search = _normalize_project_c64_packer_search(
            parser.get(_section, "Search", fallback="balanced")
        )
        _include_decruncher_source = _parse_project_bool(
            parser.get(_section, "IncludeDecruncherSource", fallback="true"), True
        )
        entries[_profile_settings["enabled_key"]] = [{
            "value": "true" if _enabled else "false"
        }]
        entries[_profile_settings["mode_key"]] = [{"value": _mode}]
        entries[_profile_settings["search_key"]] = [{"value": _search}]
        entries[_profile_settings["include_decruncher_source_key"]] = [{
            "value": "true" if _include_decruncher_source else "false"
        }]

    # Migration Stage185/187 -> Stage196. Ein bisher gemeinsam genutztes
    # Ausgabe-Verzeichnis wird absichtlich in zwei Unterordner geteilt. So
    # kann eine alte coff64-PUI beim ersten PE32-Build nicht erneut die neue
    # coff32-PUI ueberschreiben (und umgekehrt).
    if not _have_arch_settings:
        _legacy_input_section = ""
        for _candidate_section in (
            PROJECT_WINDOWS_LINK_SEARCH_PATHS_LEGACY_SECTION,
            PROJECT_WINDOWS_LINK_SEARCH_PATHS_OLDER_LEGACY_SECTION,
        ):
            if parser.has_section(_candidate_section):
                _legacy_input_section = _candidate_section
                break

        _legacy_inputs: List[str] = []
        if _legacy_input_section:
            _values = sorted(
                (
                    (name, value)
                    for name, value in parser.items(_legacy_input_section)
                    if name.casefold().startswith("path")
                ),
                key=lambda pair: pair[0].casefold(),
            )
            for _name, _value in _values:
                _path_value = str(_value).strip()
                if _path_value:
                    _legacy_inputs.append(
                        _project_loaded_path(_path_value, Path(project_path))
                    )

        _legacy_output = ""
        if parser.has_section(PROJECT_WINDOWS_OUTPUT_DIRECTORY_LEGACY_SECTION):
            _raw_output = str(
                parser.get(
                    PROJECT_WINDOWS_OUTPUT_DIRECTORY_LEGACY_SECTION,
                    "Path",
                    fallback="",
                )
            ).strip()
            if _raw_output:
                _legacy_output = _project_loaded_path(
                    _raw_output, Path(project_path)
                )

        for _target, _settings in PROJECT_WINDOWS_TARGET_SETTINGS.items():
            entries[_settings["input_relative_key"]] = [{"value": "true"}]
            entries[_settings["output_relative_key"]] = [{"value": "true"}]
            _arch_output = ""
            if _legacy_output:
                _arch_output = str(
                    (
                        Path(_legacy_output)
                        / ("pe32" if _target == "pe32" else "pe64")
                    ).resolve()
                )
                entries[_settings["output_key"]].append({"path": _arch_output})

            for _value in _legacy_inputs:
                # War das alte Output-Verzeichnis zugleich Suchpfad, dann
                # verweist jede Architektur nach der Migration auf ihren
                # eigenen Unterordner. Andere gemeinsame Bibliothekspfade
                # werden fuer beide Ziele erhalten.
                _mapped = _value
                if (
                    _legacy_output
                    and Path(_value).resolve() == Path(_legacy_output).resolve()
                    and _arch_output
                ):
                    _mapped = _arch_output
                entries[_settings["input_key"]].append({"path": _mapped})

    return entries


def save_project_ini(
    project_path: Path,
    entries: Dict[str, List[Dict[str, str]]],
) -> None:
    project_path = Path(project_path)
    project_path.parent.mkdir(parents=True, exist_ok=True)
    project_path.write_text(
        format_project_ini(entries, project_path),
        encoding="utf-8",
        newline="\n",
    )


def load_project_ini(project_path: Path) -> Dict[str, List[Dict[str, str]]]:
    project_path = Path(project_path)
    return parse_project_ini(
        project_path.read_text(encoding="utf-8-sig"),
        project_path,
    )



# ---------------------------------------------------------------------------
# COFF32/COFF64-Informationsanalyse fuer Projekt-Archive und Objektdateien.
# Die Analyse arbeitet direkt auf den Datei-Bytes und benoetigt keine externe
# Toolchain. Sie ist absichtlich vom Linker getrennt, damit auch fremde
# Microsoft-COFF-Objekte im Informations-Tab untersucht werden koennen.
# ---------------------------------------------------------------------------
COFF_IMAGE_SCN_CNT_CODE               = 0x00000020
COFF_IMAGE_SCN_CNT_INITIALIZED_DATA   = 0x00000040
COFF_IMAGE_SCN_CNT_UNINITIALIZED_DATA = 0x00000080
COFF_IMAGE_SCN_MEM_EXECUTE            = 0x20000000
COFF_IMAGE_SCN_MEM_READ               = 0x40000000
COFF_IMAGE_SCN_MEM_WRITE              = 0x80000000


def _coff_human_size(value: int) -> str:
    size = max(0, int(value or 0))
    if size < 1024:
        return f"{size:,} Bytes"
    if size < 1024 * 1024:
        return f"{size:,} Bytes ({size / 1024.0:.2f} KiB)"
    return f"{size:,} Bytes ({size / (1024.0 * 1024.0):.2f} MiB)"


def _coff_machine_text(machine: int) -> str:
    machine = int(machine or 0)
    if machine == IMAGE_FILE_MACHINE_I386:
        return "Windows PE32 / COFF32 (Intel i386, 0x014C)"
    if machine == IMAGE_FILE_MACHINE_AMD64:
        return "Windows PE64 / COFF64 (AMD64, 0x8664)"
    return f"Unbekannte COFF-Architektur (0x{machine:04X})"


def _coff_section_role(characteristics: int) -> str:
    value = int(characteristics or 0)
    if value & COFF_IMAGE_SCN_CNT_CODE or value & COFF_IMAGE_SCN_MEM_EXECUTE:
        return "Funktion / Code"
    if value & COFF_IMAGE_SCN_CNT_UNINITIALIZED_DATA:
        return "Data / BSS"
    if value & COFF_IMAGE_SCN_CNT_INITIALIZED_DATA:
        return "Data"
    return "Sonstige Daten"


def _coff_section_permissions(characteristics: int) -> str:
    value = int(characteristics or 0)
    flags = []
    if value & COFF_IMAGE_SCN_MEM_READ:
        flags.append("R")
    if value & COFF_IMAGE_SCN_MEM_WRITE:
        flags.append("W")
    if value & COFF_IMAGE_SCN_MEM_EXECUTE:
        flags.append("X")
    return "".join(flags) or "-"


def _coff_storage_class_text(value: int) -> str:
    return {
        0: "EndOfFunction",
        2: "External",
        3: "Static",
        6: "Label",
        101: "Function",
        103: "File",
        105: "WeakExternal",
    }.get(int(value), f"Class {int(value)}")


def _coff_string_from_table(table: bytes, offset: int) -> str:
    offset = int(offset or 0)
    if offset < 4 or offset >= len(table):
        return ""
    end = table.find(b"\0", offset)
    if end < 0:
        end = len(table)
    return table[offset:end].decode("utf-8", errors="replace")


def _coff_name_from_raw(raw_name: bytes, string_table: bytes) -> str:
    raw_name = bytes(raw_name[:8]).ljust(8, b"\0")
    zeroes, offset = struct.unpack("<II", raw_name)
    if zeroes == 0 and offset:
        return _coff_string_from_table(string_table, offset)
    return raw_name.rstrip(b"\0").decode("ascii", errors="replace")


def _coff_section_name(raw_name: bytes, string_table: bytes) -> str:
    short = bytes(raw_name[:8]).rstrip(b"\0").decode("ascii", errors="replace")
    # COFF long section names use '/<decimal-offset>' into the string table.
    if short.startswith("/") and short[1:].isdigit():
        resolved = _coff_string_from_table(string_table, int(short[1:]))
        if resolved:
            return resolved
    return short or "(ohne Namen)"


def analyze_coff_object_bytes(payload: bytes) -> Dict[str, object]:
    data = bytes(payload)
    if len(data) < 20:
        raise ValueError("COFF-Objekt ist zu klein.")
    (
        machine, section_count, timestamp, symbol_pointer, symbol_count,
        optional_size, characteristics,
    ) = struct.unpack_from("<HHIIIHH", data, 0)
    if machine not in {IMAGE_FILE_MACHINE_I386, IMAGE_FILE_MACHINE_AMD64}:
        raise ValueError(f"Unbekannte COFF-Machine 0x{machine:04X}.")
    section_table = 20 + int(optional_size)
    if section_table + int(section_count) * 40 > len(data):
        raise ValueError("COFF-Sektionstabelle ist beschaedigt.")

    string_table = b""
    string_table_offset = int(symbol_pointer) + int(symbol_count) * 18
    if symbol_pointer and symbol_count and string_table_offset + 4 <= len(data):
        string_size = struct.unpack_from("<I", data, string_table_offset)[0]
        if 4 <= string_size <= len(data) - string_table_offset:
            string_table = data[string_table_offset:string_table_offset + string_size]

    sections = []
    for index in range(int(section_count)):
        offset = section_table + index * 40
        raw_name = data[offset:offset + 8]
        virtual_size = struct.unpack_from("<I", data, offset + 0x08)[0]
        virtual_address = struct.unpack_from("<I", data, offset + 0x0C)[0]
        raw_size = struct.unpack_from("<I", data, offset + 0x10)[0]
        raw_pointer = struct.unpack_from("<I", data, offset + 0x14)[0]
        reloc_pointer = struct.unpack_from("<I", data, offset + 0x18)[0]
        line_pointer = struct.unpack_from("<I", data, offset + 0x1C)[0]
        reloc_count = struct.unpack_from("<H", data, offset + 0x20)[0]
        line_count = struct.unpack_from("<H", data, offset + 0x22)[0]
        section_chars = struct.unpack_from("<I", data, offset + 0x24)[0]
        sections.append({
            "index": index + 1,
            "name": _coff_section_name(raw_name, string_table),
            "virtual_size": int(virtual_size),
            "virtual_address": int(virtual_address),
            "raw_size": int(raw_size),
            "raw_pointer": int(raw_pointer),
            "reloc_pointer": int(reloc_pointer),
            "reloc_count": int(reloc_count),
            "line_pointer": int(line_pointer),
            "line_count": int(line_count),
            "characteristics": int(section_chars),
            "role": _coff_section_role(section_chars),
            "permissions": _coff_section_permissions(section_chars),
        })

    symbols = []
    if symbol_pointer and symbol_count:
        if int(symbol_pointer) + int(symbol_count) * 18 > len(data):
            raise ValueError("COFF-Symboltabelle liegt ausserhalb der Datei.")
        index = 0
        while index < int(symbol_count):
            offset = int(symbol_pointer) + index * 18
            name = _coff_name_from_raw(data[offset:offset + 8], string_table)
            value, section_number, symbol_type, storage_class, aux_count = struct.unpack_from(
                "<IhHBB", data, offset + 8
            )
            section = None
            if 1 <= section_number <= len(sections):
                section = sections[section_number - 1]
            role = "Extern / undefiniert"
            file_position = None
            if section is not None:
                role = section["role"]
                raw_pointer = int(section["raw_pointer"])
                raw_size = int(section["raw_size"])
                if raw_pointer and 0 <= int(value) < raw_size:
                    file_position = raw_pointer + int(value)
            # IMAGE_SYM_DTYPE_FUNCTION == 2 in bits 4..5 -> 0x20.
            if int(symbol_type) & 0x20:
                role = "Funktion"
            symbols.append({
                "index": index,
                "name": name or "(anonym)",
                "value": int(value),
                "section_number": int(section_number),
                "section": section["name"] if section is not None else "UNDEF",
                "type": int(symbol_type),
                "storage_class": int(storage_class),
                "storage": _coff_storage_class_text(storage_class),
                "aux_count": int(aux_count),
                "role": role,
                "file_position": file_position,
            })
            index += 1 + int(aux_count)

    return {
        "machine": int(machine),
        "architecture": _coff_machine_text(machine),
        "section_count": int(section_count),
        "timestamp": int(timestamp),
        "symbol_pointer": int(symbol_pointer),
        "symbol_count": int(symbol_count),
        "optional_size": int(optional_size),
        "characteristics": int(characteristics),
        "size": len(data),
        "sections": sections,
        "symbols": symbols,
    }


def analyze_coff_archive_bytes(payload: bytes) -> Dict[str, object]:
    data = bytes(payload)
    if not data.startswith(AR_MAGIC):
        raise ValueError("Datei ist kein ar/.a-Archiv.")
    members = []
    offset = len(AR_MAGIC)
    while offset + 60 <= len(data):
        header_offset = offset
        header = data[offset:offset + 60]
        if header[58:60] != b"`\n":
            raise ValueError(f"Archivkopf bei 0x{header_offset:X} ist beschaedigt.")
        raw_name = header[:16].decode("ascii", errors="replace").strip()
        try:
            size = int(header[48:58].decode("ascii", errors="replace").strip() or "0")
        except ValueError as exc:
            raise ValueError(f"Ungueltige Archivgroesse bei 0x{header_offset:X}.") from exc
        data_offset = header_offset + 60
        if data_offset + size > len(data):
            raise ValueError("Archivmitglied liegt ausserhalb der Datei.")
        member_data = data[data_offset:data_offset + size]
        name = raw_name.rstrip("/") or raw_name or "(Spezialmitglied)"
        object_info = None
        if len(member_data) >= 20:
            try:
                object_info = analyze_coff_object_bytes(member_data)
            except ValueError:
                object_info = None
        members.append({
            "name": name,
            "header_offset": int(header_offset),
            "data_offset": int(data_offset),
            "size": int(size),
            "object": object_info,
        })
        offset = data_offset + size + (size & 1)
    architectures = sorted({
        member["object"]["architecture"]
        for member in members
        if member.get("object") is not None
    })
    return {
        "size": len(data),
        "members": members,
        "architectures": architectures,
    }

