    @dataclass(frozen=True)
    # -----------------------------------------------------------------------
    # Positionen des per Kontextmenue angeklickten ASM-Operanden.
    # -----------------------------------------------------------------------
    class AssemblerOperandContext:
        insert_position: int
        replace_start: int
        replace_end: int
        original_value: str

    # -----------------------------------------------------------------------
    # Button-Rechner und Basisumrechner fuer ASM-Operanden.
    # -----------------------------------------------------------------------
    class NumberCalculatorDialog(QDialog):
        _memory_value: Optional[Fraction] = None

        PRIORITY_ITEMS = (
            ("Dezimal", "decimal"),
            ("Hexadezimal", "hex"),
            ("Binär", "binary"),
        )
        OPERATORS = ("+", "-", "*", "/")
        OPERATOR_LABELS = {
            "+": "+",
            "-": "−",
            "*": "×",
            "/": "÷",
        }
        PRECEDENCE = {
            "+": 1,
            "-": 1,
            "*": 2,
            "/": 2,
        }

        def __init__(
            self,
            editor: "SourceTextEdit",
            context: AssemblerOperandContext,
        ):
            super().__init__(editor)
            self.editor = editor
            self.context = context
            self._result: Optional[Fraction] = None
            self._tokens = []
            self._just_evaluated = False
            self._digit_buttons = {}

            self.setObjectName("assembler_number_calculator")
            self.setWindowTitle("Rechner für Assembler-Operand")
            self.setWindowModality(Qt.WindowModal)
            self.setMinimumWidth(620)

            layout = QVBoxLayout(self)
            layout.setContentsMargins(12, 12, 12, 12)
            layout.setSpacing(9)

            hint = QLabel(
                "Die Eingabe erfolgt über die Zahlentasten. "
                "Multiplikation und Division werden vor Addition und "
                "Subtraktion ausgewertet.",
                self,
            )
            hint.setWordWrap(True)
            layout.addWidget(hint)

            priority_layout = QHBoxLayout()
            priority_layout.addWidget(QLabel("Priorität der Umrechnung", self))
            self.priority_combo = self._make_combo(self.PRIORITY_ITEMS)
            self.priority_combo.setObjectName("calculator_priority")
            priority_layout.addWidget(self.priority_combo, 1)
            layout.addLayout(priority_layout)

            self.expression_display = QLineEdit(self)
            self.expression_display.setObjectName("calculator_expression")
            self.expression_display.setReadOnly(True)
            self.expression_display.setAlignment(Qt.AlignRight)
            expression_font = QFont(self.expression_display.font())
            expression_font.setPointSize(
                max(12, expression_font.pointSize() + 3)
            )
            expression_font.setBold(True)
            self.expression_display.setFont(expression_font)
            layout.addWidget(self.expression_display)

            keypad = QGridLayout()
            keypad.setHorizontalSpacing(6)
            keypad.setVerticalSpacing(6)
            for digit, row, column in (
                ("7", 0, 0), ("8", 0, 1), ("9", 0, 2),
                ("4", 1, 0), ("5", 1, 1), ("6", 1, 2),
                ("1", 2, 0), ("2", 2, 1), ("3", 2, 2),
                ("0", 3, 0),
                ("A", 0, 4), ("B", 0, 5),
                ("C", 1, 4), ("D", 1, 5),
                ("E", 2, 4), ("F", 2, 5),
            ):
                button = QPushButton(digit, self)
                button.setObjectName(f"calculator_digit_{digit}")
                button.setMinimumHeight(36)
                button.clicked.connect(
                    lambda checked=False, value=digit:
                    self._append_digit(value)
                )
                if digit == "0":
                    keypad.addWidget(button, row, column, 1, 3)
                else:
                    keypad.addWidget(button, row, column)
                self._digit_buttons[digit] = button

            for operator_name, row in (
                ("/", 0),
                ("*", 1),
                ("-", 2),
                ("+", 3),
            ):
                button = QPushButton(
                    self.OPERATOR_LABELS[operator_name],
                    self,
                )
                button.setObjectName(
                    "calculator_operator_" + {
                        "/": "divide",
                        "*": "multiply",
                        "-": "subtract",
                        "+": "add",
                    }[operator_name]
                )
                button.setMinimumHeight(36)
                button.clicked.connect(
                    lambda checked=False, value=operator_name:
                    self._append_operator(value)
                )
                keypad.addWidget(button, row, 3)

            self.backspace_button = QPushButton("←", self)
            self.backspace_button.setObjectName("calculator_backspace")
            self.backspace_button.setToolTip("Letzte Eingabe löschen")
            self.backspace_button.clicked.connect(self._backspace)
            keypad.addWidget(self.backspace_button, 3, 4)

            self.clear_button = QPushButton("Löschen", self)
            self.clear_button.setObjectName("calculator_clear")
            self.clear_button.setToolTip("Ausdruck und Ergebnis löschen")
            self.clear_button.clicked.connect(self._clear)
            keypad.addWidget(self.clear_button, 3, 5)

            self.equals_button = QPushButton("=", self)
            self.equals_button.setObjectName("calculator_equals")
            self.equals_button.setMinimumHeight(38)
            self.equals_button.setDefault(True)
            self.equals_button.clicked.connect(self._calculate_clicked)
            keypad.addWidget(self.equals_button, 4, 0, 1, 6)
            layout.addLayout(keypad)

            result_layout = QGridLayout()
            result_layout.setHorizontalSpacing(8)
            result_layout.setVerticalSpacing(6)
            self.result_copy_buttons = {}
            self.result_insert_buttons = {}
            self.decimal_result = self._add_result_row(
                result_layout,
                0,
                "Dezimal",
                "decimal",
            )
            self.hex_result = self._add_result_row(
                result_layout,
                1,
                "Hexadezimal",
                "hex",
            )
            self.binary_result = self._add_result_row(
                result_layout,
                2,
                "Binär",
                "binary",
            )
            layout.addLayout(result_layout)

            memory_layout = QHBoxLayout()
            self.memory_label = QLabel(self)
            self.memory_label.setObjectName("calculator_memory_label")
            memory_layout.addWidget(self.memory_label, 1)
            self.store_button = QPushButton("Speichern", self)
            self.recall_button = QPushButton("Abrufen", self)
            memory_layout.addWidget(self.store_button)
            memory_layout.addWidget(self.recall_button)
            layout.addLayout(memory_layout)

            self.error_label = QLabel(self)
            self.error_label.setObjectName("calculator_error")
            self.error_label.setWordWrap(True)
            self.error_label.setStyleSheet("color: #c02020; font-weight: bold;")
            layout.addWidget(self.error_label)

            button_layout = QHBoxLayout()
            self.calculate_button = QPushButton("Berechnen", self)
            self.change_button = QPushButton("Ändern", self)
            self.close_button = QPushButton("Schließen", self)
            button_layout.addWidget(self.calculate_button)
            button_layout.addStretch(1)
            button_layout.addWidget(self.change_button)
            button_layout.addWidget(self.close_button)
            layout.addLayout(button_layout)

            self.priority_combo.currentIndexChanged.connect(
                self._priority_changed
            )
            self.calculate_button.clicked.connect(self._calculate_clicked)
            self.change_button.clicked.connect(
                lambda checked=False: self._write_to_editor(replace=True)
            )
            self.store_button.clicked.connect(self._store_result)
            self.recall_button.clicked.connect(self._recall_result)
            self.close_button.clicked.connect(self.reject)

            original = context.original_value.strip()
            if original:
                self._select_detected_base(self.priority_combo, original)
                self._tokens = [self._strip_number_prefix(original)]
            else:
                self._tokens = ["0"]

            self._refresh_expression_display()
            self._update_digit_buttons()
            self._refresh_memory_label()
            self._update_result(silent=True)

        def _make_combo(self, items) -> QComboBox:
            combo = QComboBox(self)
            for label, item_data in items:
                combo.addItem(label, item_data)
            return combo

        def _add_result_row(
            self,
            layout: QGridLayout,
            row: int,
            label: str,
            base_name: str,
        ) -> QLineEdit:
            layout.addWidget(QLabel(label, self), row, 0)
            result = QLineEdit(self)
            result.setReadOnly(True)
            result.setObjectName("calculator_result")
            result.setAlignment(Qt.AlignRight)
            layout.addWidget(result, row, 1)

            copy_button = QPushButton("Kopieren", self)
            copy_button.setObjectName(
                f"calculator_copy_{base_name}"
            )
            copy_button.clicked.connect(
                lambda checked=False, selected_base=base_name:
                self._copy_result(selected_base)
            )
            layout.addWidget(copy_button, row, 2)

            insert_button = QPushButton("Einfügen", self)
            insert_button.setObjectName(
                f"calculator_insert_{base_name}"
            )
            insert_button.clicked.connect(
                lambda checked=False, selected_base=base_name:
                self._write_to_editor(
                    replace=False,
                    base_name=selected_base,
                )
            )
            layout.addWidget(insert_button, row, 3)

            self.result_copy_buttons[base_name] = copy_button
            self.result_insert_buttons[base_name] = insert_button
            return result

        @staticmethod
        def _select_detected_base(combo: QComboBox, text: str) -> None:
            value = text.strip().lstrip("#").lstrip("+-")
            if value.startswith("$") or value.lower().startswith("0x"):
                combo.setCurrentIndex(combo.findData("hex"))
            elif value.startswith("%") or value.lower().startswith("0b"):
                combo.setCurrentIndex(combo.findData("binary"))
            else:
                combo.setCurrentIndex(combo.findData("decimal"))

        @staticmethod
        def _strip_number_prefix(text: str) -> str:
            value = text.strip()
            if value.startswith("#"):
                value = value[1:].strip()
            sign = ""
            if value.startswith(("+", "-")):
                sign, value = value[0], value[1:]
            if value.startswith("$") or value.startswith("%"):
                value = value[1:]
            elif value.lower().startswith(("0x", "0b")):
                value = value[2:]
            return sign + value.upper()

        @staticmethod
        def _parse_integer(text: str, base_name: str) -> int:
            value = text.strip().replace("_", "")
            if value.startswith("#"):
                value = value[1:].strip()
            if not value:
                raise ValueError("Bitte einen Zahlenwert eingeben.")

            sign = 1
            if value[0] in "+-":
                if value[0] == "-":
                    sign = -1
                value = value[1:]
            if not value:
                raise ValueError("Der Zahlenwert ist unvollständig.")

            if base_name == "hex":
                if value.startswith("$"):
                    value = value[1:]
                elif value.lower().startswith("0x"):
                    value = value[2:]
                if value.lower().endswith("h"):
                    value = value[:-1]
                digits = r"[0-9A-Fa-f]+"
                radix = 16
                base_label = "Hexadezimalzahl"
            elif base_name == "binary":
                if value.startswith("%"):
                    value = value[1:]
                elif value.lower().startswith("0b"):
                    value = value[2:]
                digits = r"[01]+"
                radix = 2
                base_label = "Binärzahl"
            else:
                digits = r"[0-9]+"
                radix = 10
                base_label = "Dezimalzahl"

            if re.fullmatch(digits, value or "") is None:
                raise ValueError(f"Ungültige {base_label}: {text}")
            return sign * int(value, radix)

        @staticmethod
        def _decimal_text(value: Fraction) -> str:
            if value.denominator == 1:
                return str(value.numerator)
            with localcontext() as context:
                context.prec = 32
                decimal_value = (
                    Decimal(value.numerator) / Decimal(value.denominator)
                )
            text = format(decimal_value, "f")
            if "." in text:
                text = text.rstrip("0").rstrip(".")
            return text

        @staticmethod
        def _integer_text(
            value: Fraction,
            base_name: str,
            *,
            original: str = "",
            preserve_width: bool = False,
        ) -> Optional[str]:
            if value.denominator != 1:
                return None
            integer = value.numerator
            sign = "-" if integer < 0 else ""
            magnitude = abs(integer)

            original_body = original.strip().lstrip("#").lstrip("+-")
            if base_name == "hex":
                digits = format(magnitude, "X")
                prefix = "$"
                width = 0
                if preserve_width:
                    if original_body.startswith("$"):
                        width = len(original_body) - 1
                    elif original_body.lower().startswith("0x"):
                        width = len(original_body) - 2
                        prefix = original_body[:2]
                if width:
                    digits = digits.rjust(width, "0")
                return sign + prefix + digits

            if base_name == "binary":
                digits = format(magnitude, "b")
                prefix = "%"
                width = 0
                if preserve_width:
                    if original_body.startswith("%"):
                        width = len(original_body) - 1
                    elif original_body.lower().startswith("0b"):
                        width = len(original_body) - 2
                        prefix = original_body[:2]
                if width:
                    digits = digits.rjust(width, "0")
                return sign + prefix + digits

            return str(integer)

        def _priority_base(self) -> str:
            return str(self.priority_combo.currentData())

        @classmethod
        def _is_operator(cls, token) -> bool:
            return isinstance(token, str) and token in cls.OPERATORS

        def _token_display(self, token) -> str:
            if self._is_operator(token):
                return self.OPERATOR_LABELS[token]
            if isinstance(token, Fraction):
                if token.denominator != 1:
                    return self._decimal_text(token)
                text = self._integer_text(token, self._priority_base())
                if text is None:
                    return self._decimal_text(token)
                return self._strip_number_prefix(text)
            return str(token)

        def _refresh_expression_display(self) -> None:
            self.expression_display.setText(
                " ".join(self._token_display(token) for token in self._tokens)
            )

        def _digit_allowed(self, digit: str) -> bool:
            base_name = self._priority_base()
            if base_name == "binary":
                return digit in "01"
            if base_name == "decimal":
                return digit in "0123456789"
            return digit in "0123456789ABCDEF"

        def _update_digit_buttons(self) -> None:
            for digit, button in self._digit_buttons.items():
                button.setEnabled(self._digit_allowed(digit))

        def _append_digit(self, digit: str) -> None:
            digit = digit.upper()
            if not self._digit_allowed(digit):
                self.error_label.setText(
                    f"{digit} ist in dieser Zahlenbasis nicht zulässig."
                )
                return

            if self._just_evaluated:
                self._tokens = []
                self._just_evaluated = False

            if not self._tokens or self._is_operator(self._tokens[-1]):
                self._tokens.append(digit)
            elif isinstance(self._tokens[-1], Fraction):
                self._tokens = [digit]
            else:
                current = str(self._tokens[-1])
                if current == "0":
                    current = ""
                self._tokens[-1] = current + digit

            self._refresh_expression_display()
            self._update_result(silent=True)

        def _append_operator(self, operator_name: str) -> None:
            if operator_name not in self.OPERATORS:
                return
            if not self._tokens:
                self.error_label.setText("Zuerst einen Zahlenwert eingeben.")
                return

            if self._just_evaluated and self._result is not None:
                self._tokens = [self._result]
                self._just_evaluated = False

            if self._is_operator(self._tokens[-1]):
                self._tokens[-1] = operator_name
            else:
                self._tokens.append(operator_name)
            self.error_label.clear()
            self._refresh_expression_display()
            self._set_action_state()

        def _backspace(self, *_args) -> None:
            if not self._tokens:
                return
            self._just_evaluated = False
            last = self._tokens[-1]
            if self._is_operator(last) or isinstance(last, Fraction):
                self._tokens.pop()
            else:
                shortened = str(last)[:-1]
                if shortened and shortened not in ("+", "-"):
                    self._tokens[-1] = shortened
                else:
                    self._tokens.pop()
            if not self._tokens:
                self._tokens = ["0"]
            self._refresh_expression_display()
            self._update_result(silent=True)

        def _clear(self, *_args) -> None:
            self._tokens = ["0"]
            self._result = Fraction(0, 1)
            self._just_evaluated = False
            self.error_label.clear()
            self._refresh_expression_display()
            self._show_result()

        def _infix_to_rpn(self):
            if not self._tokens or self._is_operator(self._tokens[-1]):
                raise ValueError("Der Rechenausdruck ist unvollständig.")

            output = []
            operators = []
            expect_number = True
            base_name = self._priority_base()
            for token in self._tokens:
                if expect_number:
                    if self._is_operator(token):
                        raise ValueError("Zwei Operatoren folgen aufeinander.")
                    if isinstance(token, Fraction):
                        output.append(token)
                    else:
                        output.append(
                            Fraction(
                                self._parse_integer(str(token), base_name),
                                1,
                            )
                        )
                    expect_number = False
                    continue

                if not self._is_operator(token):
                    raise ValueError("Zwischen zwei Werten fehlt ein Operator.")
                while (
                    operators
                    and self.PRECEDENCE[operators[-1]]
                    >= self.PRECEDENCE[token]
                ):
                    output.append(operators.pop())
                operators.append(token)
                expect_number = True

            if expect_number:
                raise ValueError("Der Rechenausdruck ist unvollständig.")
            while operators:
                output.append(operators.pop())
            return output

        @classmethod
        def _evaluate_rpn(cls, rpn_tokens) -> Fraction:
            stack = []
            for token in rpn_tokens:
                if not cls._is_operator(token):
                    stack.append(Fraction(token))
                    continue
                if len(stack) < 2:
                    raise ValueError("Der Rechenausdruck ist unvollständig.")
                right = stack.pop()
                left = stack.pop()
                if token == "+":
                    stack.append(left + right)
                elif token == "-":
                    stack.append(left - right)
                elif token == "*":
                    stack.append(left * right)
                else:
                    if right == 0:
                        raise ValueError("Division durch 0 ist nicht zulässig.")
                    stack.append(left / right)
            if len(stack) != 1:
                raise ValueError("Der Rechenausdruck ist ungültig.")
            return stack[0]

        def _calculate(self) -> Fraction:
            return self._evaluate_rpn(self._infix_to_rpn())

        def _set_action_state(self) -> None:
            valid = self._result is not None
            for base_name, button in self.result_copy_buttons.items():
                available = self._result_text(base_name) is not None
                button.setEnabled(valid and available)
            for base_name, button in self.result_insert_buttons.items():
                available = self._result_text(base_name) is not None
                button.setEnabled(
                    valid and available and not self.editor.isReadOnly()
                )
            selected_available = self._selected_result_text() is not None
            self.change_button.setEnabled(
                valid and selected_available and not self.editor.isReadOnly()
            )
            self.store_button.setEnabled(valid)
            self.recall_button.setEnabled(self._memory_value is not None)

        def _show_result(self) -> None:
            if self._result is None:
                self.decimal_result.clear()
                self.hex_result.clear()
                self.binary_result.clear()
                self._set_action_state()
                return
            self.decimal_result.setText(self._decimal_text(self._result))
            hex_text = self._integer_text(self._result, "hex")
            binary_text = self._integer_text(self._result, "binary")
            self.hex_result.setText(
                hex_text if hex_text is not None else "nicht ganzzahlig"
            )
            self.binary_result.setText(
                binary_text if binary_text is not None else "nicht ganzzahlig"
            )
            self._set_action_state()

        def _update_result(self, *, silent: bool) -> bool:
            try:
                self._result = self._calculate()
            except ValueError as exc:
                self._result = None
                self._show_result()
                self.error_label.setText("" if silent else str(exc))
                return False
            self.error_label.clear()
            self._show_result()
            return True

        def _priority_changed(self, *_args) -> None:
            self._update_digit_buttons()
            self._refresh_expression_display()
            self._update_result(silent=True)

        def _calculate_clicked(self, *_args) -> None:
            if self._update_result(silent=False):
                self._just_evaluated = True

        def _selected_result_text(
            self,
            *,
            for_editor: bool = False,
        ) -> Optional[str]:
            return self._result_text(
                self._priority_base(),
                for_editor=for_editor,
            )

        def _result_text(
            self,
            base_name: str,
            *,
            for_editor: bool = False,
        ) -> Optional[str]:
            if self._result is None:
                return None
            if base_name == "decimal":
                return self._decimal_text(self._result)
            return self._integer_text(
                self._result,
                base_name,
                original=(
                    self.context.original_value if for_editor else ""
                ),
                preserve_width=for_editor,
            )

        def _copy_result(
            self,
            base_name: Optional[str] = None,
            *_args,
        ) -> None:
            selected_base = base_name or self._priority_base()
            text = self._result_text(selected_base)
            if text is None:
                self.error_label.setText(
                    "Hexadezimal und Binär benötigen ein ganzzahliges Ergebnis."
                )
                return
            QApplication.clipboard().setText(text)
            self.error_label.setText(f"Ergebnis kopiert: {text}")

        def _write_to_editor(
            self,
            *,
            replace: bool,
            base_name: Optional[str] = None,
        ) -> None:
            selected_base = base_name or self._priority_base()
            text = self._result_text(
                selected_base,
                for_editor=replace,
            )
            if text is None:
                self.error_label.setText(
                    "Dieses Ausgabeformat benötigt ein ganzzahliges Ergebnis."
                )
                return

            cursor = QTextCursor(self.editor.document())
            if replace:
                cursor.setPosition(self.context.replace_start)
                cursor.setPosition(
                    self.context.replace_end,
                    QTextCursor.KeepAnchor,
                )
            else:
                cursor.setPosition(self.context.insert_position)

            cursor.beginEditBlock()
            cursor.insertText(text)
            cursor.endEditBlock()
            self.editor.setTextCursor(cursor)
            self.editor.ensureCursorVisible()
            self.editor.setFocus(Qt.OtherFocusReason)
            self.accept()

        def _store_result(self, *_args) -> None:
            if self._result is None and not self._update_result(silent=False):
                return
            type(self)._memory_value = self._result
            self._refresh_memory_label()
            self._set_action_state()

        def _recall_result(self, *_args) -> None:
            if self._memory_value is None:
                return
            self._tokens = [self._memory_value]
            self._result = self._memory_value
            self._just_evaluated = True
            self.error_label.clear()
            self._refresh_expression_display()
            self._show_result()

        def _refresh_memory_label(self) -> None:
            if self._memory_value is None:
                self.memory_label.setText("Speicher: leer")
            else:
                self.memory_label.setText(
                    "Speicher: " + self._decimal_text(self._memory_value)
                )

        def keyPressEvent(self, event) -> None:
            text = event.text().upper()
            if text in "0123456789ABCDEF":
                self._append_digit(text)
                event.accept()
                return
            if text in self.OPERATORS:
                self._append_operator(text)
                event.accept()
                return
            if event.key() in (Qt.Key_Return, Qt.Key_Enter):
                self._calculate_clicked()
                event.accept()
                return
            if event.key() == Qt.Key_Backspace:
                self._backspace()
                event.accept()
                return
            if event.key() == Qt.Key_Delete:
                self._clear()
                event.accept()
                return
            super().keyPressEvent(event)

    # ---------------------------------------------------------------------------
    # GitHub-aehnliche Markdown-Vorschau auf Basis von QPlainTextEdit.
    # Kein WebEngine/HTML-Widget: das Markdown wird in einen formatierten
    # QTextDocument-Inhalt uebersetzt. Dadurch bleibt die Vorschau leichtgewichtig
    # und folgt direkt dem Text des Rohdaten-Editors.
    # ---------------------------------------------------------------------------
    class MarkdownPreviewEdit(QPlainTextEdit):
        _HEADING_RE = re.compile(r"^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$")
        _FENCE_RE = re.compile(r"^\s{0,3}(```+|~~~+)\s*([^`]*)$")
        _QUOTE_RE = re.compile(r"^\s{0,3}>\s?(.*)$")
        _TASK_RE = re.compile(r"^(\s*)[-+*]\s+\[([ xX])\]\s+(.*)$")
        _UL_RE = re.compile(r"^(\s*)[-+*]\s+(.*)$")
        _OL_RE = re.compile(r"^(\s*)(\d+)[.)]\s+(.*)$")
        _HR_RE = re.compile(r"^\s{0,3}(?:([-*_])\s*){3,}$")
        _TABLE_DELIMITER_RE = re.compile(
            r"^\s*\|?\s*:?-{3,}:?\s*(?:\|\s*:?-{3,}:?\s*)+\|?\s*$"
        )
        _INLINE_PATTERNS = (
            ("image", re.compile(r"!\[([^\]]*)\]\(([^)]+)\)")),
            ("link", re.compile(r"\[([^\]]+)\]\(([^)]+)\)")),
            ("code", re.compile(r"`([^`]+)`")),
            ("strong", re.compile(r"(?:\*\*|__)(.+?)(?:\*\*|__)")),
            ("strike", re.compile(r"~~(.+?)~~")),
            ("em", re.compile(r"(?<!\*)\*([^*\n]+)\*(?!\*)|(?<!_)_([^_\n]+)_(?!_)")),
        )

        def __init__(self, parent: Optional[QWidget] = None):
            super().__init__(parent)
            self.setObjectName("markdown_preview")
            self.setReadOnly(True)
            self.setUndoRedoEnabled(False)
            self.setLineWrapMode(QPlainTextEdit.WidgetWidth)
            self.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
            self.setCursorWidth(0)
            self.setTextInteractionFlags(
                Qt.TextSelectableByMouse
                | Qt.TextSelectableByKeyboard
                | Qt.LinksAccessibleByMouse
            )
            self.viewport().setCursor(Qt.ArrowCursor)

            preview_font = QFont("Segoe UI", 11)
            preview_font.setStyleHint(QFont.SansSerif)
            self.setFont(preview_font)

            self._dark_mode = False
            self._markdown_source = ""
            self._pending_source = ""
            self._render_timer = QTimer(self)
            self._render_timer.setSingleShot(True)
            self._render_timer.setInterval(35)
            self._render_timer.timeout.connect(self._render_pending)
            self._apply_theme()

        def set_dark_mode(self, enabled: bool) -> None:
            enabled = bool(enabled)
            if self._dark_mode == enabled:
                self._apply_theme()
                return
            self._dark_mode = enabled
            self._apply_theme()
            self._render_markdown(self._markdown_source)

        def _apply_theme(self) -> None:
            palette = QPalette(QApplication.palette())
            if self._dark_mode:
                palette.setColor(QPalette.Base, QColor("#0D1117"))
                palette.setColor(QPalette.Text, QColor("#C9D1D9"))
                palette.setColor(QPalette.Highlight, QColor("#264F78"))
                palette.setColor(QPalette.HighlightedText, QColor("#FFFFFF"))
            else:
                palette.setColor(QPalette.Base, QColor("#FFFFFF"))
                palette.setColor(QPalette.Text, QColor("#24292F"))
                palette.setColor(QPalette.Highlight, QColor("#0969DA"))
                palette.setColor(QPalette.HighlightedText, QColor("#FFFFFF"))
            self.setPalette(palette)
            self.viewport().setPalette(palette)

        def set_markdown_source(self, source: str, *, immediate: bool = False) -> None:
            self._pending_source = str(source)
            if immediate:
                self._render_timer.stop()
                self._render_pending()
            else:
                self._render_timer.start()

        def _render_pending(self) -> None:
            source = self._pending_source
            self._pending_source = source
            self._render_markdown(source)

        def _color(self, dark: str, light: str) -> QColor:
            return QColor(dark if self._dark_mode else light)

        def _base_format(self) -> QTextCharFormat:
            fmt = QTextCharFormat()
            fmt.setFontFamily("Segoe UI")
            fmt.setFontPointSize(11.0)
            fmt.setForeground(self._color("#C9D1D9", "#24292F"))
            return fmt

        def _muted_format(self) -> QTextCharFormat:
            fmt = self._base_format()
            fmt.setForeground(self._color("#8B949E", "#57606A"))
            return fmt

        def _code_format(self) -> QTextCharFormat:
            fmt = QTextCharFormat()
            fmt.setFontFamily("Consolas")
            fmt.setFontPointSize(10.5)
            fmt.setForeground(self._color("#C9D1D9", "#24292F"))
            fmt.setBackground(self._color("#161B22", "#F6F8FA"))
            return fmt

        @staticmethod
        def _copy_format(base: QTextCharFormat) -> QTextCharFormat:
            return QTextCharFormat(base)

        def _insert_inline(
            self,
            cursor: QTextCursor,
            text: str,
            base_format: Optional[QTextCharFormat] = None,
        ) -> None:
            base = QTextCharFormat(base_format or self._base_format())
            position = 0
            length = len(text)

            while position < length:
                best = None
                best_kind = ""
                for kind, pattern in self._INLINE_PATTERNS:
                    match = pattern.search(text, position)
                    if match is None:
                        continue
                    if best is None or match.start() < best.start():
                        best = match
                        best_kind = kind
                if best is None:
                    cursor.insertText(text[position:], base)
                    break

                if best.start() > position:
                    cursor.insertText(text[position:best.start()], base)

                if best_kind == "code":
                    fmt = self._code_format()
                    cursor.insertText(best.group(1), fmt)
                elif best_kind == "link":
                    fmt = self._copy_format(base)
                    fmt.setForeground(self._color("#58A6FF", "#0969DA"))
                    fmt.setFontUnderline(True)
                    fmt.setAnchor(True)
                    fmt.setAnchorHref(best.group(2).strip())
                    cursor.insertText(best.group(1), fmt)
                elif best_kind == "image":
                    fmt = self._copy_format(base)
                    fmt.setForeground(self._color("#8B949E", "#57606A"))
                    fmt.setFontItalic(True)
                    label = best.group(1).strip() or "Bild"
                    cursor.insertText(f"[Bild: {label}]", fmt)
                elif best_kind == "strong":
                    fmt = self._copy_format(base)
                    fmt.setFontWeight(QFont.Bold)
                    self._insert_inline(cursor, best.group(1), fmt)
                elif best_kind == "strike":
                    fmt = self._copy_format(base)
                    fmt.setFontStrikeOut(True)
                    fmt.setForeground(self._color("#8B949E", "#57606A"))
                    self._insert_inline(cursor, best.group(1), fmt)
                else:
                    fmt = self._copy_format(base)
                    fmt.setFontItalic(True)
                    content = best.group(1) if best.group(1) is not None else best.group(2)
                    self._insert_inline(cursor, content or "", fmt)

                position = best.end()

        def _start_block(
            self,
            cursor: QTextCursor,
            *,
            left_margin: float = 0.0,
            top_margin: float = 2.0,
            bottom_margin: float = 2.0,
            background: Optional[QColor] = None,
        ) -> None:
            if cursor.position() != 0 or cursor.block().text():
                cursor.insertBlock()
            block_format = QTextBlockFormat()
            block_format.setLeftMargin(float(left_margin))
            block_format.setTopMargin(float(top_margin))
            block_format.setBottomMargin(float(bottom_margin))
            if background is not None:
                block_format.setBackground(background)
            cursor.setBlockFormat(block_format)

        @staticmethod
        def _table_cells(line: str) -> list[str]:
            value = line.strip()
            if value.startswith("|"):
                value = value[1:]
            if value.endswith("|"):
                value = value[:-1]
            return [cell.strip() for cell in value.split("|")]

        def _render_table(self, cursor: QTextCursor, rows: list[list[str]]) -> None:
            if not rows:
                return
            columns = max(len(row) for row in rows)
            widths = [1] * columns
            for row in rows:
                for index, cell in enumerate(row):
                    widths[index] = min(40, max(widths[index], len(cell)))

            code_fmt = self._code_format()
            header_fmt = QTextCharFormat(code_fmt)
            header_fmt.setFontWeight(QFont.Bold)
            border_fmt = QTextCharFormat(code_fmt)
            border_fmt.setForeground(self._color("#30363D", "#D0D7DE"))

            for row_index, row in enumerate(rows):
                self._start_block(
                    cursor,
                    left_margin=8,
                    top_margin=0,
                    bottom_margin=0,
                    background=self._color("#0D1117", "#FFFFFF"),
                )
                cursor.insertText("│ ", border_fmt)
                for column in range(columns):
                    cell = row[column] if column < len(row) else ""
                    fmt = header_fmt if row_index == 0 else code_fmt
                    cursor.insertText(cell.ljust(widths[column]), fmt)
                    if column + 1 < columns:
                        cursor.insertText(" │ ", border_fmt)
                cursor.insertText(" │", border_fmt)
                if row_index == 0:
                    self._start_block(cursor, left_margin=8, top_margin=0, bottom_margin=0)
                    cursor.insertText(
                        "├─" + "─┼─".join("─" * width for width in widths) + "─┤",
                        border_fmt,
                    )

        def _render_markdown(self, source: str) -> None:
            source = str(source)
            scrollbar = self.verticalScrollBar()
            old_maximum = scrollbar.maximum()
            old_value = scrollbar.value()
            old_ratio = (old_value / float(old_maximum)) if old_maximum > 0 else 0.0

            self._markdown_source = source
            document = self.document()
            document.clear()
            cursor = QTextCursor(document)
            cursor.beginEditBlock()
            try:
                lines = source.splitlines()
                index = 0
                in_fence = False
                fence_marker = ""
                fence_language = ""

                while index < len(lines):
                    line = lines[index]
                    stripped = line.strip()

                    fence = self._FENCE_RE.match(line)
                    if fence is not None:
                        marker = fence.group(1)
                        if not in_fence:
                            in_fence = True
                            fence_marker = marker[0]
                            fence_language = fence.group(2).strip()
                            if fence_language:
                                self._start_block(cursor, left_margin=10, top_margin=5, bottom_margin=0)
                                label_fmt = self._muted_format()
                                label_fmt.setFontFamily("Consolas")
                                label_fmt.setFontPointSize(9.5)
                                cursor.insertText(fence_language, label_fmt)
                        elif marker.startswith(fence_marker):
                            in_fence = False
                            fence_marker = ""
                            fence_language = ""
                        index += 1
                        continue

                    if in_fence:
                        self._start_block(
                            cursor,
                            left_margin=10,
                            top_margin=0,
                            bottom_margin=0,
                            background=self._color("#161B22", "#F6F8FA"),
                        )
                        cursor.insertText(line if line else " ", self._code_format())
                        index += 1
                        continue

                    # GitHub-Flavoured Markdown Tabellen.
                    if (
                        index + 1 < len(lines)
                        and "|" in line
                        and self._TABLE_DELIMITER_RE.match(lines[index + 1]) is not None
                    ):
                        table_rows = [self._table_cells(line)]
                        index += 2
                        while index < len(lines) and "|" in lines[index] and lines[index].strip():
                            table_rows.append(self._table_cells(lines[index]))
                            index += 1
                        self._render_table(cursor, table_rows)
                        continue

                    heading = self._HEADING_RE.match(line)
                    if heading is not None:
                        level = len(heading.group(1))
                        sizes = {1: 23.0, 2: 19.0, 3: 17.0, 4: 15.0, 5: 13.0, 6: 12.0}
                        fmt = self._base_format()
                        fmt.setFontWeight(QFont.Bold)
                        fmt.setFontPointSize(sizes[level])
                        fmt.setForeground(self._color("#F0F6FC", "#1F2328"))
                        self._start_block(cursor, top_margin=8 if level <= 2 else 5, bottom_margin=4)
                        self._insert_inline(cursor, heading.group(2), fmt)
                        index += 1
                        continue

                    if self._HR_RE.match(line) is not None:
                        self._start_block(cursor, top_margin=6, bottom_margin=6)
                        rule = self._muted_format()
                        rule.setForeground(self._color("#30363D", "#D0D7DE"))
                        cursor.insertText("─" * 72, rule)
                        index += 1
                        continue

                    quote = self._QUOTE_RE.match(line)
                    if quote is not None:
                        self._start_block(cursor, left_margin=12, top_margin=2, bottom_margin=2)
                        marker_fmt = self._base_format()
                        marker_fmt.setForeground(self._color("#3FB950", "#1A7F37"))
                        marker_fmt.setFontWeight(QFont.Bold)
                        cursor.insertText("│ ", marker_fmt)
                        self._insert_inline(cursor, quote.group(1), self._muted_format())
                        index += 1
                        continue

                    task = self._TASK_RE.match(line)
                    if task is not None:
                        indent = len(task.group(1).replace("\t", "    "))
                        self._start_block(cursor, left_margin=12 + indent * 4, top_margin=1, bottom_margin=1)
                        marker_fmt = self._base_format()
                        marker_fmt.setForeground(self._color("#8B949E", "#57606A"))
                        cursor.insertText("☑ " if task.group(2).lower() == "x" else "☐ ", marker_fmt)
                        self._insert_inline(cursor, task.group(3))
                        index += 1
                        continue

                    unordered = self._UL_RE.match(line)
                    if unordered is not None:
                        indent = len(unordered.group(1).replace("\t", "    "))
                        self._start_block(cursor, left_margin=12 + indent * 4, top_margin=1, bottom_margin=1)
                        marker_fmt = self._base_format()
                        marker_fmt.setForeground(self._color("#8B949E", "#57606A"))
                        cursor.insertText("• ", marker_fmt)
                        self._insert_inline(cursor, unordered.group(2))
                        index += 1
                        continue

                    ordered = self._OL_RE.match(line)
                    if ordered is not None:
                        indent = len(ordered.group(1).replace("\t", "    "))
                        self._start_block(cursor, left_margin=12 + indent * 4, top_margin=1, bottom_margin=1)
                        marker_fmt = self._muted_format()
                        cursor.insertText(ordered.group(2) + ". ", marker_fmt)
                        self._insert_inline(cursor, ordered.group(3))
                        index += 1
                        continue

                    if not stripped:
                        self._start_block(cursor, top_margin=2, bottom_margin=2)
                        index += 1
                        continue

                    self._start_block(cursor, top_margin=2, bottom_margin=2)
                    self._insert_inline(cursor, line)
                    index += 1
            finally:
                cursor.endEditBlock()

            new_maximum = self.verticalScrollBar().maximum()
            self.verticalScrollBar().setValue(int(round(old_ratio * new_maximum)))
            self.document().setModified(False)

        def help_word_at_cursor(self) -> str:
            cursor = self.textCursor()
            cursor.select(QTextCursor.WordUnderCursor)
            return cursor.selectedText().strip()

        def mouseReleaseEvent(self, event) -> None:
            if event.button() == Qt.LeftButton:
                cursor = self.cursorForPosition(event.pos())
                href = cursor.charFormat().anchorHref()
                if href:
                    QDesktopServices.openUrl(QUrl(href))
                    event.accept()
                    return
            super().mouseReleaseEvent(event)


    # ---------------------------------------------------------------------------
    # Mini-Map fuer den Quelltexteditor.
    #
    # Die Mini-Map besitzt absichtlich KEINEN unabhaengigen Scrollzustand. Bis
    # zu 120 logischen Mini-Map-Pixeln/Zeilen wird der gesamte Inhalt gezeigt.
    # Wird dieser Bereich groesser, zeigt die Mini-Map ein mit dem Haupteditor
    # synchronisiertes 120-Pixel-Fenster. Dadurch wird langer Quelltext nicht
    # immer weiter zusammengedrueckt und Editor/Mini-Map koennen nicht driften.
    # Drag/Klick in der Mini-Map setzt weiterhin direkt die QScrollBar des
    # SourceTextEdit.
    # ---------------------------------------------------------------------------
    class SourceMiniMap(QWidget):
        MINI_MAP_WIDTH = 92
        MINI_MAP_SCROLL_HEIGHT = 120
        MINI_MAP_SCROLL_TRACK_WIDTH = 4
        MIN_VIEWPORT_HEIGHT = 18
        ASSEMBLER_MIN_VIEWPORT_HEIGHT = 120
        MAX_LINE_LENGTH = 160

        def __init__(
            self,
            editor,
            parent: Optional[QWidget] = None,
            *,
            min_viewport_height: Optional[int] = None,
        ):
            super().__init__(parent)
            self.editor = editor
            self.min_viewport_height = max(
                1,
                int(
                    self.MIN_VIEWPORT_HEIGHT
                    if min_viewport_height is None
                    else min_viewport_height
                ),
            )
            self._dragging = False
            self._drag_offset_y = 0
            self._line_lengths = []

            self.setObjectName("source_minimap")
            self.setFixedWidth(self.MINI_MAP_WIDTH)
            self.setMouseTracking(True)
            self.setCursor(Qt.PointingHandCursor)

            vertical = self.editor.verticalScrollBar()
            vertical.valueChanged.connect(self.update)
            vertical.rangeChanged.connect(
                lambda _minimum, _maximum: self.update()
            )
            self.editor.textChanged.connect(self._document_changed)
            self.editor.blockCountChanged.connect(
                lambda _count: self._document_changed()
            )
            self.editor.updateRequest.connect(
                lambda _rect, _dy: self.update()
            )

            self._rebuild_line_cache()

        def sizeHint(self) -> QSize:
            return QSize(self.MINI_MAP_WIDTH, 0)

        def set_min_viewport_height(self, height: int) -> None:
            self.min_viewport_height = max(1, int(height))
            self.update()

        def _rebuild_line_cache(self) -> None:
            result = []
            block = self.editor.document().firstBlock()
            while block.isValid():
                text = block.text().expandtabs(4)
                result.append(
                    min(self.MAX_LINE_LENGTH, len(text))
                )
                block = block.next()
            self._line_lengths = result

        def _document_changed(self) -> None:
            self._rebuild_line_cache()
            self.update()

        def _scroll_ratio(self) -> float:
            scrollbar = self.editor.verticalScrollBar()
            minimum = scrollbar.minimum()
            maximum = scrollbar.maximum()
            if maximum <= minimum:
                return 0.0
            return max(
                0.0,
                min(
                    1.0,
                    (scrollbar.value() - minimum)
                    / float(maximum - minimum),
                ),
            )

        def _visible_line_window(self):
            count = len(self._line_lengths)
            if count <= 0:
                return (0, 0)

            # Eine Quelltextzeile entspricht zunaechst einem logischen
            # Mini-Map-Pixel. Ab 120 Pixeln wird nicht weiter komprimiert,
            # sondern ein synchron mit dem Editor wanderndes Fenster benutzt.
            visible = min(count, self.MINI_MAP_SCROLL_HEIGHT)
            if count <= visible:
                return (0, count)

            maximum_start = count - visible
            first = int(round(self._scroll_ratio() * maximum_start))
            first = max(0, min(maximum_start, first))
            return (first, first + visible)

        def _mini_scroll_handle_rectangle(self) -> QRect:
            count = len(self._line_lengths)
            height = max(1, self.height())
            if count <= self.MINI_MAP_SCROLL_HEIGHT:
                return QRect()

            visible = self.MINI_MAP_SCROLL_HEIGHT
            handle_height = max(
                12,
                int(height * visible / float(count)),
            )
            handle_height = min(height, handle_height)
            available = max(0, height - handle_height)
            top = int(round(self._scroll_ratio() * available))
            return QRect(
                max(0, self.width() - self.MINI_MAP_SCROLL_TRACK_WIDTH),
                top,
                self.MINI_MAP_SCROLL_TRACK_WIDTH,
                handle_height,
            )

        def _viewport_rectangle(self) -> QRect:
            scrollbar = self.editor.verticalScrollBar()
            minimum = scrollbar.minimum()
            maximum = scrollbar.maximum()
            value = scrollbar.value()
            height = max(1, self.height())

            if maximum <= minimum:
                return QRect(0, 0, self.width(), height)

            page_step = max(1, scrollbar.pageStep())
            scroll_range = maximum - minimum
            total_range = scroll_range + page_step

            viewport_height = int(
                height * page_step / max(1, total_range)
            )
            # Stage 60: the draggable viewport may use a larger per-editor
            # minimum.  Assembly editors request 120 px so even very large
            # generated listings retain a comfortably clickable/dragable
            # thumb.  The value/position mapping below remains unchanged.
            viewport_height = max(
                self.min_viewport_height,
                viewport_height,
            )
            viewport_height = min(height, viewport_height)

            available_height = max(0, height - viewport_height)
            position = QStyle.sliderPositionFromValue(
                minimum,
                maximum,
                value,
                available_height,
                False,
            )
            return QRect(
                0,
                int(position),
                max(1, self.width() - 1),
                viewport_height,
            )

        def _set_scroll_from_thumb_top(self, thumb_top: int) -> None:
            scrollbar = self.editor.verticalScrollBar()
            minimum = scrollbar.minimum()
            maximum = scrollbar.maximum()

            if maximum <= minimum:
                scrollbar.setValue(minimum)
                return

            viewport_rect = self._viewport_rectangle()
            available_height = max(
                0,
                self.height() - viewport_rect.height(),
            )
            if available_height <= 0:
                scrollbar.setValue(minimum)
                return

            thumb_top = max(
                0,
                min(available_height, int(thumb_top)),
            )
            value = QStyle.sliderValueFromPosition(
                minimum,
                maximum,
                thumb_top,
                available_height,
                False,
            )
            scrollbar.setValue(value)

        def paintEvent(self, event) -> None:
            del event
            painter = QPainter(self)
            try:
                palette = self.editor.palette()
                background = palette.base().color()
                text_color = palette.text().color()
                highlight = palette.highlight().color()

                painter.fillRect(self.rect(), background)

                lines = self._line_lengths
                count = len(lines)
                if count:
                    height = max(1, self.height())
                    scroll_track = (
                        self.MINI_MAP_SCROLL_TRACK_WIDTH + 2
                        if count > self.MINI_MAP_SCROLL_HEIGHT
                        else 0
                    )
                    available_width = max(
                        1,
                        self.width() - 8 - scroll_track,
                    )
                    line_color = QColor(text_color)
                    line_color.setAlpha(145)
                    painter.setPen(line_color)

                    first, last = self._visible_line_window()
                    visible_lines = lines[first:last]
                    visible_count = len(visible_lines)
                    denominator = max(1, visible_count - 1)

                    for local_index, line_length in enumerate(visible_lines):
                        y = int(
                            local_index * (height - 1) / denominator
                        )
                        width = int(
                            available_width
                            * line_length
                            / self.MAX_LINE_LENGTH
                        )
                        if line_length:
                            width = max(2, width)
                        painter.drawLine(4, y, 4 + width, y)

                    # Schmaler eigener Mini-Map-Scrollindikator. Er besitzt
                    # keinen eigenen Wert, sondern wird direkt aus der
                    # Editor-QScrollBar berechnet.
                    scroll_handle = self._mini_scroll_handle_rectangle()
                    if not scroll_handle.isNull():
                        track_color = QColor(text_color)
                        track_color.setAlpha(55)
                        painter.fillRect(
                            QRect(
                                self.width() - self.MINI_MAP_SCROLL_TRACK_WIDTH,
                                0,
                                self.MINI_MAP_SCROLL_TRACK_WIDTH,
                                height,
                            ),
                            track_color,
                        )
                        handle_color = QColor(highlight)
                        handle_color.setAlpha(190)
                        painter.fillRect(scroll_handle, handle_color)

                viewport_rect = self._viewport_rectangle()
                viewport_fill = QColor(highlight)
                viewport_fill.setAlpha(55)
                painter.fillRect(viewport_rect, viewport_fill)

                border_color = QColor(highlight)
                border_color.setAlpha(220)
                painter.setPen(border_color)
                painter.drawRect(
                    viewport_rect.adjusted(0, 0, -1, -1)
                )
            finally:
                painter.end()

        def mousePressEvent(self, event) -> None:
            if event.button() != Qt.LeftButton:
                super().mousePressEvent(event)
                return

            viewport_rect = self._viewport_rectangle()
            if viewport_rect.contains(event.pos()):
                self._drag_offset_y = (
                    event.pos().y() - viewport_rect.top()
                )
            else:
                self._drag_offset_y = viewport_rect.height() // 2
                self._set_scroll_from_thumb_top(
                    event.pos().y() - self._drag_offset_y
                )

            self._dragging = True
            self.grabMouse()
            event.accept()

        def mouseMoveEvent(self, event) -> None:
            if self._dragging and event.buttons() & Qt.LeftButton:
                self._set_scroll_from_thumb_top(
                    event.pos().y() - self._drag_offset_y
                )
                event.accept()
                return
            super().mouseMoveEvent(event)

        def mouseReleaseEvent(self, event) -> None:
            if self._dragging and event.button() == Qt.LeftButton:
                self._dragging = False
                self.releaseMouse()
                event.accept()
                return
            super().mouseReleaseEvent(event)

        def wheelEvent(self, event) -> None:
            scrollbar = self.editor.verticalScrollBar()
            delta = event.angleDelta().y()
            if delta:
                steps = delta / 120.0
                movement = int(
                    steps
                    * max(1, scrollbar.singleStep())
                    * 3
                )
                scrollbar.setValue(
                    scrollbar.value() - movement
                )
            event.accept()

    # ---------------------------------------------------------------------------
    # Quelltexteditor mit Gutter und intelligenter Assemblerhilfe.
    # ---------------------------------------------------------------------------
    class SourceTextEdit(QPlainTextEdit):
        assembler_help_requested = pyqtSignal(str, str)
        context_help_requested = pyqtSignal(str)
        build_requested = pyqtSignal()
        find_requested = pyqtSignal(object)
        find_next_requested = pyqtSignal(object)
        breakpoints_changed = pyqtSignal()
        bookmarks_changed = pyqtSignal()
        # Stage ASM 4: meldet Aenderungen der sichtbaren Editor-/Viewport-
        # Geometrie an viewportgebundene Overlays.
        viewport_geometry_changed = pyqtSignal()

        GUTTER_MARKER_COLUMN_WIDTH = 13
        GUTTER_MARKER_COLUMNS = 2

        def __init__(self, parent: Optional[QWidget] = None):
            super().__init__(parent)
            self._dark_mode = False
            self._markdown_mode = False
            self._completion_enabled = False
            self._completion_context = None
            self._assembler_target = "c64"
            self._amiga_cpu_model = "mk68000"
            self._amiga_fpu_model = "FPU: None"
            self._assembler_navigation_enabled = False
            self._assembler_highlighter = None
            self._lisp_help_enabled = False
            # Stage ASM 54: C64 BASIC keeps semantic BASIC line numbers in
            # QTextBlock user data. They are painted in the gutter and are
            # materialized only when the file is saved/compiled.
            self._basic_line_number_mode = False
            self._basic_line_update_guard = False
            self._basic_gutter_font = None
            self._basic_first_overflow_block = -1
            self._basic_overflow_blocks = ()
            self._basic_max_columns = 80
            # Stage ASM 62: C64-artiger blinkender Blockcursor. Der Cursor ist
            # ausschließlich ein Paint-Overlay; der QTextDocument-Inhalt wird
            # niemals mit einem Ersatzzeichen überschrieben.
            self._basic_block_cursor_visible = True
            self._basic_block_cursor_timer = QTimer(self)
            self._basic_block_cursor_timer.setInterval(450)
            self._basic_block_cursor_timer.timeout.connect(
                self._toggle_basic_block_cursor
            )
            self._breakpoint_cursors = []
            self._bookmark_cursors = []
            self.line_number_area = LineNumberArea(self)
            self.viewport().setMouseTracking(True)

            # Stage 164: TAB erzeugt im Quelltext immer vier Leerzeichen.
            # Das historische #9-Tabulatorzeichen wird damit bei Tastatureingabe
            # nicht mehr in den Quelltext eingefügt.
            self.setTabChangesFocus(False)
            self.setTabStopDistance(
                max(1.0, float(self.fontMetrics().horizontalAdvance(" ") * 4))
            )

            self.completion_ghost = QLabel(self.viewport())
            self.completion_ghost.setObjectName("assembler_completion_ghost")
            self.completion_ghost.setAttribute(
                Qt.WA_TransparentForMouseEvents,
                True,
            )
            self.completion_ghost.hide()

            self.completion_frame = QFrame(self.viewport())
            self.completion_frame.setObjectName("assembler_completion_frame")
            self.completion_frame.setFrameShape(QFrame.StyledPanel)
            self.completion_frame.setAttribute(
                Qt.WA_TransparentForMouseEvents,
                True,
            )
            completion_layout = QVBoxLayout(self.completion_frame)
            completion_layout.setContentsMargins(9, 7, 9, 8)
            completion_layout.setSpacing(0)

            self.completion_header = QLabel(self.completion_frame)
            self.completion_header.setObjectName("assembler_completion_header")
            self.completion_header.setTextFormat(Qt.PlainText)
            self.completion_header.setWordWrap(False)
            completion_layout.addWidget(self.completion_header)
            completion_layout.addSpacing(self.fontMetrics().height())

            self.completion_description = QLabel(self.completion_frame)
            self.completion_description.setObjectName(
                "assembler_completion_description"
            )
            self.completion_description.setTextFormat(Qt.PlainText)
            self.completion_description.setWordWrap(True)
            completion_layout.addWidget(self.completion_description)
            self.completion_frame.hide()

            # Stage 80: compact, non-modal command description shown while
            # typing an assembler instruction or after clicking its mnemonic.
            self.instruction_help_frame = QFrame(self.viewport())
            self.instruction_help_frame.setObjectName(
                "assembler_instruction_help_frame"
            )
            self.instruction_help_frame.setAttribute(
                Qt.WA_TransparentForMouseEvents,
                True,
            )
            instruction_help_layout = QVBoxLayout(self.instruction_help_frame)
            instruction_help_layout.setContentsMargins(9, 6, 9, 7)
            instruction_help_layout.setSpacing(2)
            self.instruction_help_header = QLabel(self.instruction_help_frame)
            self.instruction_help_header.setObjectName(
                "assembler_instruction_help_header"
            )
            self.instruction_help_header.setTextFormat(Qt.PlainText)
            self.instruction_help_header.setWordWrap(True)
            self.instruction_help_current = QLabel(self.instruction_help_frame)
            self.instruction_help_current.setObjectName(
                "assembler_instruction_help_current"
            )
            self.instruction_help_current.setTextFormat(Qt.PlainText)
            self.instruction_help_current.setWordWrap(True)
            self.instruction_help_description = QLabel(
                self.instruction_help_frame
            )
            self.instruction_help_description.setObjectName(
                "assembler_instruction_help_description"
            )
            self.instruction_help_description.setTextFormat(Qt.PlainText)
            self.instruction_help_description.setWordWrap(True)
            instruction_help_layout.addWidget(self.instruction_help_header)
            instruction_help_layout.addWidget(self.instruction_help_current)
            instruction_help_layout.addWidget(self.instruction_help_description)
            self._instruction_help_mnemonic = ""
            self._instruction_help_operands = ""
            # Stage ASM 3: Maus-Hilfe und Cursor-Hilfe benutzen dasselbe
            # Overlay, besitzen aber getrennte Trigger.  Ein Hover darf nur
            # auf den tatsaechlich gezeichneten Mnemonic-Zeichen ausloesen.
            self._instruction_help_hover_active = False
            self._instruction_help_anchor_rect = None
            self.instruction_help_current.hide()
            self.instruction_help_frame.hide()

            self.blockCountChanged.connect(
                self.update_line_number_area_width
            )
            self.updateRequest.connect(self.update_line_number_area)
            self.textChanged.connect(self._schedule_completion_update)
            self.textChanged.connect(self._schedule_instruction_help_update)
            self.textChanged.connect(self._gutter_document_changed)
            self.textChanged.connect(self._basic_document_changed)
            self.cursorPositionChanged.connect(
                self._schedule_completion_update
            )
            self.cursorPositionChanged.connect(
                self._schedule_instruction_help_update
            )
            self.cursorPositionChanged.connect(
                self._update_current_line_highlight
            )
            self.cursorPositionChanged.connect(
                self._reset_basic_block_cursor_blink
            )
            self.textChanged.connect(self._reset_basic_block_cursor_blink)
            self.update_line_number_area_width(0)
            self._update_completion_theme()
            self._update_current_line_highlight()

        # -----------------------------------------------------------------------
        # Stage ASM 54: C64 BASIC line-number gutter / 80-column source model.
        # -----------------------------------------------------------------------
        def set_basic_gutter_font(self, font: QFont) -> None:
            self._basic_gutter_font = QFont(font)
            self.line_number_area.update()
            self.update_line_number_area_width(0)

        def set_basic_editor_mode(
            self,
            enabled: bool,
            *,
            initial_source: Optional[str] = None,
        ) -> None:
            enabled = bool(enabled)
            previous = self._basic_line_number_mode
            if enabled:
                self._basic_line_number_mode = True
                self.setLineWrapMode(QPlainTextEdit.NoWrap)
                # Den normalen Qt-I-Beam ausblenden; Stage 62 zeichnet den
                # blinkenden C64-Blockcursor selbst im Viewport.
                self.setCursorWidth(0)
                self._reset_basic_block_cursor_blink()
                self.set_basic_gutter_font(self.font())
                if initial_source is not None:
                    self.load_basic_editor_source(initial_source)
                elif not previous:
                    self.load_basic_editor_source(self.toPlainText())
                else:
                    self._basic_reconcile_line_numbers()
                return

            if not previous:
                self._basic_line_number_mode = False
                return

            # When a BASIC document is renamed to a non-BASIC extension, show
            # the actual serialized representation in the normal text editor.
            try:
                materialized = self.basic_source_with_line_numbers()
            except Exception:
                materialized = self.toPlainText()
            modified = self.document().isModified()
            self._basic_line_number_mode = False
            self._basic_block_cursor_timer.stop()
            self._basic_block_cursor_visible = False
            self.setCursorWidth(1)
            self.viewport().update()
            self._basic_line_update_guard = True
            try:
                self.setPlainText(materialized)
                self.document().setModified(modified)
            finally:
                self._basic_line_update_guard = False
            self._basic_first_overflow_block = -1
            self._basic_overflow_blocks = ()
            self.update_line_number_area_width(0)
            self._update_current_line_highlight()

        def load_basic_editor_source(self, source: str) -> None:
            from c64basic.editor_model import (
                assign_missing_basic_numbers,
                split_numbered_basic_source,
                wrap_basic_lines,
            )

            modified = self.document().isModified()
            lines, numbers = split_numbered_basic_source(source)
            lines, numbers = wrap_basic_lines(
                lines,
                numbers,
                max_columns=self._basic_max_columns,
            )
            numbers = assign_missing_basic_numbers(numbers)

            self._basic_line_update_guard = True
            try:
                self.setPlainText("\n".join(lines))
                block = self.document().firstBlock()
                index = 0
                while block.isValid():
                    number = numbers[index] if index < len(numbers) else None
                    block.setUserData(C64BasicLineBlockData(number))
                    block = block.next()
                    index += 1
                self.document().setModified(modified)
            finally:
                self._basic_line_update_guard = False

            self._basic_reconcile_line_numbers()
            self.update_line_number_area_width(0)
            self.line_number_area.update()
            self._update_current_line_highlight()

        def _basic_block_line_number(self, block) -> Optional[int]:
            data = block.userData() if block.isValid() else None
            if isinstance(data, C64BasicLineBlockData):
                return data.line_number
            return None

        def _basic_collect_lines_and_numbers(self):
            lines = []
            numbers = []
            block = self.document().firstBlock()
            while block.isValid():
                lines.append(block.text())
                numbers.append(self._basic_block_line_number(block))
                block = block.next()
            return lines, numbers

        def basic_source_with_line_numbers(self, newline: str = "\n") -> str:
            from c64basic.editor_model import serialize_numbered_basic_source

            lines, numbers = self._basic_collect_lines_and_numbers()
            return serialize_numbered_basic_source(
                lines,
                numbers,
                newline=newline,
            )

        def renumber_basic_lines(self, preferred_step: int = 10):
            """Stage ASM 58: BASIC-Gutter komplett neu nummerieren.

            Der sichtbare Editor enthaelt weiterhin nur BASIC-Code. Die neue
            Nummernfolge wird als QTextBlock-Metadaten gesetzt; direkte
            GOTO/GOSUB/THEN/RESTORE-Ziele werden auf die neuen Nummern
            umgeschrieben. Stage ASM 72 entfernt zusaetzlich ueberfluessige
            Leerzeichen an Ausdrucksoperatoren. Strings sowie REM-/Apostroph-
            Kommentare bleiben dabei unangetastet.
            """
            if not self._basic_line_number_mode:
                raise ValueError("Der Editor befindet sich nicht im C64-BASIC-Modus.")

            from c64basic.editor_model import renumber_basic_program

            lines, numbers = self._basic_collect_lines_and_numbers()
            new_lines, new_numbers, mapping = renumber_basic_program(
                lines,
                numbers,
                preferred_step=preferred_step,
                maximum=65535,
                max_columns=self._basic_max_columns,
                update_references=True,
            )

            cursor = self.textCursor()
            cursor_block = cursor.blockNumber()
            cursor_column = cursor.positionInBlock()
            anchor_cursor = QTextCursor(self.document())
            anchor_cursor.setPosition(cursor.anchor())
            anchor_block = anchor_cursor.blockNumber()
            anchor_column = anchor_cursor.positionInBlock()

            self._basic_line_update_guard = True
            try:
                self.setPlainText("\n".join(new_lines))
                block = self.document().firstBlock()
                index = 0
                while block.isValid():
                    number = new_numbers[index] if index < len(new_numbers) else None
                    block.setUserData(C64BasicLineBlockData(number))
                    block = block.next()
                    index += 1
                self.document().setModified(True)
            finally:
                self._basic_line_update_guard = False

            self._basic_overflow_blocks = ()
            self._basic_first_overflow_block = -1
            self.update_line_number_area_width(0)
            self.line_number_area.update()
            self._update_current_line_highlight()

            # Cursor/Selektion moeglichst auf derselben physischen Zeile halten.
            maximum_position = max(0, self.document().characterCount() - 1)
            new_anchor_block = self.document().findBlockByNumber(
                max(0, min(anchor_block, self.document().blockCount() - 1))
            )
            new_cursor_block = self.document().findBlockByNumber(
                max(0, min(cursor_block, self.document().blockCount() - 1))
            )
            restored = QTextCursor(self.document())
            anchor_position = min(
                maximum_position,
                new_anchor_block.position() + min(anchor_column, len(new_anchor_block.text())),
            )
            cursor_position = min(
                maximum_position,
                new_cursor_block.position() + min(cursor_column, len(new_cursor_block.text())),
            )
            restored.setPosition(anchor_position)
            restored.setPosition(cursor_position, QTextCursor.KeepAnchor)
            self.setTextCursor(restored)

            return new_numbers, mapping

        def basic_has_line_number_overflow(self) -> bool:
            return self._basic_first_overflow_block >= 0

        def _basic_split_overlong_blocks(self) -> None:
            if not self._basic_line_number_mode:
                return

            width = max(1, int(self._basic_max_columns))
            cursor_position = self.textCursor().position()
            anchor_position = self.textCursor().anchor()

            block = self.document().firstBlock()
            while block.isValid():
                if len(block.text()) <= width:
                    block = block.next()
                    continue

                split_position = block.position() + width
                edit = QTextCursor(self.document())
                edit.setPosition(split_position)
                edit.insertBlock()

                if split_position <= cursor_position:
                    cursor_position += 1
                if split_position <= anchor_position:
                    anchor_position += 1

                # Continue with the newly-created continuation block.  If it is
                # still longer than 80 columns, the loop splits it again.
                block = self.document().findBlock(split_position + 1)

            restored = QTextCursor(self.document())
            maximum = max(0, self.document().characterCount() - 1)
            restored.setPosition(max(0, min(anchor_position, maximum)))
            restored.setPosition(
                max(0, min(cursor_position, maximum)),
                QTextCursor.KeepAnchor,
            )
            self.setTextCursor(restored)

        def _basic_reconcile_line_numbers(self) -> None:
            if not self._basic_line_number_mode:
                return
            from c64basic.editor_model import assign_missing_basic_numbers

            blocks = []
            numbers = []
            block = self.document().firstBlock()
            while block.isValid():
                blocks.append(block)
                numbers.append(self._basic_block_line_number(block))
                block = block.next()

            assigned = assign_missing_basic_numbers(numbers)
            overflow_blocks = []
            for index, (block, number) in enumerate(zip(blocks, assigned)):
                data = block.userData()
                if not isinstance(data, C64BasicLineBlockData):
                    block.setUserData(C64BasicLineBlockData(number))
                else:
                    data.line_number = number
                if number is None:
                    overflow_blocks.append(index)

            self._basic_overflow_blocks = tuple(overflow_blocks)
            self._basic_first_overflow_block = (
                overflow_blocks[0] if overflow_blocks else -1
            )
            self.update_line_number_area_width(0)
            self.line_number_area.update()
            self._update_current_line_highlight()

        def _basic_document_changed(self) -> None:
            if (
                not self._basic_line_number_mode
                or self._basic_line_update_guard
            ):
                return
            self._basic_line_update_guard = True
            try:
                self._basic_split_overlong_blocks()
                self._basic_reconcile_line_numbers()
            finally:
                self._basic_line_update_guard = False

        # -----------------------------------------------------------------------
        # Hebt die aktuelle Cursorzeile theme-abhaengig hervor.
        # -----------------------------------------------------------------------
        def _update_current_line_highlight(self) -> None:
            selection = QTextEdit.ExtraSelection()
            selection.cursor = self.textCursor()
            selection.cursor.clearSelection()
            selection.format.setProperty(
                QTextFormat.FullWidthSelection,
                True,
            )

            if self._markdown_mode:
                if self._dark_mode:
                    selection.format.setBackground(QColor("#161B22"))
                    selection.format.setForeground(QColor("#C9D1D9"))
                else:
                    selection.format.setBackground(QColor("#F6F8FA"))
                    selection.format.setForeground(QColor("#24292F"))
            elif self._dark_mode:
                selection.format.setBackground(QColor("#182898"))
                selection.format.setForeground(QColor("#FFFFFF"))
            else:
                selection.format.setBackground(QColor("#FFF4B8"))
                selection.format.setForeground(QColor("#000000"))

            extra_selections = []
            if self._basic_line_number_mode and self._basic_overflow_blocks:
                overflow_set = set(self._basic_overflow_blocks)
                for block_number in self._basic_overflow_blocks:
                    overflow_block = self.document().findBlockByNumber(block_number)
                    if not overflow_block.isValid():
                        continue
                    overflow = QTextEdit.ExtraSelection()
                    overflow.cursor = QTextCursor(overflow_block)
                    overflow.cursor.select(QTextCursor.BlockUnderCursor)
                    overflow.format.setForeground(QColor("#FF4040"))
                    extra_selections.append(overflow)
                if self.textCursor().blockNumber() in overflow_set:
                    selection.format.setForeground(QColor("#FF4040"))

            extra_selections.append(selection)
            self.setExtraSelections(extra_selections)

        # -------------------------------------------------------------------
        # Stage ASM 62: C64-Blockcursor. Weil der Cursor nur nach dem normalen
        # QPlainTextEdit-Paint gezeichnet wird, muss kein darunterliegendes
        # Zeichen gespeichert/restauriert werden. Beim nächsten Repaint malt
        # Qt den Originaltext zuerst sauber neu und danach ggf. das Quadrat.
        # -------------------------------------------------------------------
        def _toggle_basic_block_cursor(self) -> None:
            if (
                not self._basic_line_number_mode
                or not self.hasFocus()
                or self.textCursor().hasSelection()
            ):
                self._basic_block_cursor_visible = False
                self.viewport().update()
                return
            self._basic_block_cursor_visible = not self._basic_block_cursor_visible
            self.viewport().update()

        def _reset_basic_block_cursor_blink(self) -> None:
            if not self._basic_line_number_mode:
                return
            self._basic_block_cursor_visible = True
            if self.hasFocus():
                self._basic_block_cursor_timer.start()
            self.viewport().update()

        def paintEvent(self, event) -> None:
            super().paintEvent(event)
            if (
                not self._basic_line_number_mode
                or not self._basic_block_cursor_visible
                or not self.hasFocus()
                or self.textCursor().hasSelection()
            ):
                return

            cursor = self.textCursor()
            rect = self.cursorRect(cursor)
            metrics = self.fontMetrics()
            cell_width = max(2, metrics.horizontalAdvance("M"))
            cell_height = max(2, rect.height())
            block_rect = QRect(rect.left(), rect.top(), cell_width, cell_height)
            block_rect = block_rect.intersected(self.viewport().rect())
            if block_rect.isEmpty():
                return

            painter = QPainter(self.viewport())
            painter.setPen(Qt.NoPen)
            # C64-nahe helle Cursorfläche auf dem navyfarbenen BASIC-Editor.
            painter.setBrush(QColor(210, 220, 255))
            painter.drawRect(block_rect)

            # Befindet sich der Cursor auf einem vorhandenen Zeichen, dieses
            # invers im Block nochmals zeichnen. Das Dokument bleibt unverändert.
            block = cursor.block()
            column = cursor.positionInBlock()
            text = block.text() if block.isValid() else ""
            if 0 <= column < len(text):
                painter.setFont(self.font())
                painter.setPen(QColor(0, 0, 128))
                painter.drawText(
                    block_rect,
                    int(Qt.AlignLeft | Qt.AlignVCenter | Qt.TextSingleLine),
                    text[column],
                )
            painter.end()

        def set_assembler_completion_enabled(self, enabled: bool) -> None:
            self._completion_enabled = bool(enabled) and not self.isReadOnly()
            if self._completion_enabled:
                self._schedule_completion_update()
            else:
                self._hide_completion()

        def set_assembler_target(self, target: str) -> None:
            normalized = str(target).strip().casefold()
            if normalized in {
                "pe64", "windows pe64", "windowspe64", "win64",
                "pe32+", "windows pe32+", "windowspe32+", "windows pe32 plus",
            }:
                self._assembler_target = "pe64"
            elif normalized in {"pe32", "windows", "windows pe32"}:
                self._assembler_target = "pe32"
            elif normalized == "amiga":
                self._assembler_target = "amiga"
            else:
                self._assembler_target = "c64"
            self._hide_completion()
            if self._completion_enabled:
                self._schedule_completion_update()

        def set_amiga_profile(self, cpu_model: str, fpu_model: str) -> None:
            self._amiga_cpu_model = normalize_amiga_cpu_model(cpu_model)
            self._amiga_fpu_model = normalize_amiga_fpu_model(fpu_model)
            self._hide_completion()
            if self._completion_enabled:
                self._schedule_completion_update()

        def _assembler_commands(self):
            if self._assembler_target == "pe64":
                return PE64_ASSEMBLER_COMMANDS
            if self._assembler_target == "pe32":
                return PE32_ASSEMBLER_COMMANDS
            if self._assembler_target == "amiga":
                filtered = {}
                for mnemonic, info in M68K_ASSEMBLER_COMMANDS.items():
                    minimum_cpu, needs_fpu = AMIGA_COMMAND_REQUIREMENTS.get(
                        mnemonic, ("mk68000", False)
                    )
                    if not amiga_cpu_at_least(self._amiga_cpu_model, minimum_cpu):
                        continue
                    if needs_fpu and self._amiga_fpu_model == "FPU: None":
                        continue
                    filtered[mnemonic] = info
                return filtered
            return ASSEMBLER_COMMANDS

        def set_assembler_navigation_highlighter(self, highlighter) -> None:
            self._assembler_highlighter = highlighter

        def set_assembler_navigation_enabled(self, enabled: bool) -> None:
            self._assembler_navigation_enabled = bool(enabled)
            if not self._assembler_navigation_enabled:
                self.viewport().setCursor(Qt.IBeamCursor)

        def _jump_target_at_point(self, point):
            if (
                not self._assembler_navigation_enabled
                or self._assembler_highlighter is None
            ):
                return None
            cursor = self.cursorForPosition(point)
            return self._assembler_highlighter.jump_target_at(
                cursor.block().text(),
                cursor.positionInBlock(),
            )

        def _jump_to_label(self, target: str) -> bool:
            if self._assembler_highlighter is None:
                return False
            position = self._assembler_highlighter.label_position(target)
            if position is None:
                return False

            self._hide_completion()
            cursor = QTextCursor(self.document())
            cursor.setPosition(position)
            self.setTextCursor(cursor)
            self.centerCursor()
            self.setFocus(Qt.MouseFocusReason)
            self.viewport().setCursor(Qt.IBeamCursor)
            return True

        def _assembler_operand_context_at_point(self, point):
            """Ermittelt den editierbaren Hauptwert rechts vom Mnemonic."""
            if (
                not self._assembler_navigation_enabled
                or self.isReadOnly()
            ):
                return None

            cursor = self.cursorForPosition(point)
            block = cursor.block()
            block_text = block.text()
            position = cursor.positionInBlock()
            code = block_text.split(";", 1)[0]
            match = re.match(
                r"^\s*(?:[A-Za-z_.$][A-Za-z0-9_.$]*\s*:\s*)?"
                r"(?P<opcode>[A-Za-z]{2,8})(?:\.[BbWwLl])?"
                r"(?P<spacing>\s+)"
                r"(?P<operand>.*?)\s*$",
                code,
            )
            if (
                match is None
                or match.group("opcode").upper() not in self._assembler_commands()
            ):
                return None

            operand_start, operand_end = match.span("operand")
            while (
                operand_start < operand_end
                and code[operand_start].isspace()
            ):
                operand_start += 1
            while (
                operand_end > operand_start
                and code[operand_end - 1].isspace()
            ):
                operand_end -= 1
            if operand_start >= operand_end:
                return None

            # cursorForPosition() kann die Position direkt hinter dem
            # angeklickten Zeichen liefern; deshalb wird auch das rechte Ende
            # des Operanden als Treffer akzeptiert.
            if not (
                operand_start <= position < operand_end
                or operand_start < position <= operand_end
            ):
                return None

            operand = code[operand_start:operand_end]
            primary = re.match(
                r"\s*[#(]*\s*(?P<value>"
                r"[+-]?(?:\$[0-9A-Fa-f]+|%[01]+|"
                r"0[xX][0-9A-Fa-f]+|0[bB][01]+|[0-9]+)"
                r"|[A-Za-z_.$][A-Za-z0-9_.$]*"
                r")",
                operand,
            )
            if primary is None:
                replace_start = operand_start
                replace_end = operand_end
                original_value = ""
            else:
                local_start, local_end = primary.span("value")
                replace_start = operand_start + local_start
                replace_end = operand_start + local_end
                candidate = primary.group("value")
                original_value = (
                    candidate
                    if re.fullmatch(
                        r"[+-]?(?:\$[0-9A-Fa-f]+|%[01]+|"
                        r"0[xX][0-9A-Fa-f]+|0[bB][01]+|[0-9]+)",
                        candidate,
                    )
                    else ""
                )

            block_position = block.position()
            return AssemblerOperandContext(
                insert_position=block_position + max(
                    operand_start,
                    min(position, operand_end),
                ),
                replace_start=block_position + replace_start,
                replace_end=block_position + replace_end,
                original_value=original_value,
            )

        def _open_operand_calculator(
            self,
            context: AssemblerOperandContext,
        ) -> None:
            self._hide_completion()
            dialog = NumberCalculatorDialog(self, context)
            dialog.exec_()

        def _assembler_instruction_match(self, block_text: str):
            """Stage ASM 3: parst eine ASM-Zeile und liefert nur echte Opcodes."""
            code = str(block_text).split(";", 1)[0]
            match = re.match(
                r"^\s*(?:[A-Za-z_.$][A-Za-z0-9_.$]*\s*:\s*)?"
                r"(?P<opcode>[A-Za-z]{2,8})(?:\.[BbWwLl])?"
                r"(?:\s+(?P<operand>.*?))?\s*$",
                code,
            )
            if match is None:
                return None
            mnemonic = match.group("opcode").upper()
            info = self._assembler_commands().get(mnemonic)
            if info is None:
                return None
            return code, match, info

        def _assembler_instruction_context_from_cursor(
            self,
            cursor: QTextCursor,
            *,
            require_opcode: bool = True,
        ):
            """Liefert Hilfe nur, wenn der Cursor wirklich im Mnemonic steht."""
            parsed = self._assembler_instruction_match(cursor.block().text())
            if parsed is None:
                return None
            code, match, info = parsed

            position = cursor.positionInBlock()
            opcode_start, opcode_end = match.span("opcode")
            if require_opcode and not (opcode_start <= position < opcode_end):
                return None

            operand = (match.group("operand") or "").strip()
            semantic = None
            if self._assembler_target == "c64":
                semantic = c64_assembler_call_description(
                    info.mnemonic, operand
                )
            return info, operand, semantic

        def _assembler_instruction_info_at_cursor(self):
            """Return command metadata only while the caret is on opcode text."""
            if not self._assembler_navigation_enabled:
                return None
            return self._assembler_instruction_context_from_cursor(
                self.textCursor(),
                require_opcode=True,
            )

        def _assembler_instruction_info_at_point(self, point: QPoint):
            """Stage ASM 3: pixelgenaue Mnemonic-Hitbox fuer Maus-Hilfe.

            ``cursorForPosition`` allein reicht nicht, weil Qt rechts neben dem
            Zeilenende weiterhin den naechsten Text-Cursor liefern kann.  Die
            X-Koordinate muss deshalb zusaetzlich innerhalb des gezeichneten
            Opcode-Rechtecks liegen.
            """
            if not self._assembler_navigation_enabled:
                return None

            cursor = self.cursorForPosition(point)
            parsed = self._assembler_instruction_match(cursor.block().text())
            if parsed is None:
                return None
            _code, match, info = parsed
            opcode_start, opcode_end = match.span("opcode")

            block = cursor.block()
            block_position = block.position()
            start_cursor = QTextCursor(self.document())
            start_cursor.setPosition(block_position + opcode_start)
            end_cursor = QTextCursor(self.document())
            end_cursor.setPosition(block_position + opcode_end)
            start_rect = self.cursorRect(start_cursor)
            end_rect = self.cursorRect(end_cursor)
            left = start_rect.left()
            right = max(left + 1, end_rect.left())
            top = min(start_rect.top(), end_rect.top())
            bottom = max(start_rect.bottom(), end_rect.bottom())

            # Ausschliesslich die sichtbaren Buchstaben des Mnemonics treffen.
            if not (left <= point.x() < right and top <= point.y() <= bottom):
                return None

            operand = (match.group("operand") or "").strip()
            semantic = None
            if self._assembler_target == "c64":
                semantic = c64_assembler_call_description(
                    info.mnemonic, operand
                )
            anchor = QRect(left, top, max(1, right - left), max(1, bottom - top + 1))
            return (info, operand, semantic), anchor

        def _schedule_instruction_help_update(self) -> None:
            QTimer.singleShot(0, self._update_instruction_help)

        def _update_instruction_help(self) -> None:
            # Solange die Maus direkt ueber einem Mnemonic steht, hat die
            # Hover-Hilfe Vorrang.  Cursorbewegungen duerfen sie nicht durch
            # eine Hilfe fuer eine andere Position ersetzen.
            if self._instruction_help_hover_active:
                return
            context = self._assembler_instruction_info_at_cursor()
            if context is None:
                self.instruction_help_frame.hide()
                self._instruction_help_anchor_rect = None
                return
            self._show_instruction_help_context(
                context,
                anchor_rect=self.cursorRect(),
            )

        def _show_instruction_help_context(
            self,
            context,
            *,
            anchor_rect: Optional[QRect] = None,
        ) -> None:
            if context is None:
                self.instruction_help_frame.hide()
                return

            info, operand, semantic = context
            self._instruction_help_mnemonic = str(info.mnemonic)
            self._instruction_help_operands = str(info.operands)
            self._instruction_help_anchor_rect = (
                QRect(anchor_rect) if anchor_rect is not None else self.cursorRect()
            )

            if operand:
                self.instruction_help_current.setText(f"Aktuell: {operand}")
                self.instruction_help_current.show()
            else:
                self.instruction_help_current.clear()
                self.instruction_help_current.hide()

            description = info.description
            if semantic:
                description += f"\nZielbeschreibung: {semantic}"
                if self._assembler_target == "c64":
                    stability = c64_assembler_call_stability(
                        info.mnemonic,
                        operand,
                    )
                    if stability and stability != "KERNAL-API":
                        description += (
                            "\n\nHinweis: interne ROM-Routine; "
                            "nicht Teil der stabilen KERNAL-Jump-Table."
                        )

            self.instruction_help_description.setText(description)
            self.instruction_help_frame.show()
            # Dieses Frame ist die gemeinsame Hilfe-Ebene fuer Hover und
            # Text-Cursor. Es muss ueber jedem Code-Erklaerungs-Overlay liegen.
            self.instruction_help_frame.raise_()
            self._position_instruction_help_frame()

        def _position_instruction_help_frame(self) -> None:
            if not self.instruction_help_frame.isVisible():
                return
            viewport_rectangle = self.viewport().rect()
            if viewport_rectangle.width() <= 20:
                return
            width = max(300, min(680, viewport_rectangle.width() - 12))
            content_width = max(40, width - 20)

            mnemonic = self._instruction_help_mnemonic
            operands = self._instruction_help_operands
            one_line = mnemonic
            if operands:
                one_line += "    " + operands
            metrics = self.instruction_help_header.fontMetrics()
            if operands and metrics.horizontalAdvance(one_line) > content_width:
                header = mnemonic + "\n" + operands
            else:
                header = one_line
            self.instruction_help_header.setText(header)
            self.instruction_help_header.setFixedWidth(content_width)
            self.instruction_help_current.setFixedWidth(content_width)
            self.instruction_help_description.setFixedWidth(content_width)
            self.instruction_help_frame.adjustSize()
            self.instruction_help_frame.resize(
                width,
                self.instruction_help_frame.sizeHint().height(),
            )

            anchor = self._instruction_help_anchor_rect
            if anchor is None or anchor.isNull():
                anchor = self.cursorRect()
            x_position = min(
                max(4, anchor.left()),
                max(4, viewport_rectangle.width() - width - 4),
            )
            y_position = anchor.bottom() + 5
            if (
                y_position + self.instruction_help_frame.height()
                > viewport_rectangle.bottom()
            ):
                y_position = max(
                    4,
                    anchor.top() - self.instruction_help_frame.height() - 5,
                )
            self.instruction_help_frame.move(x_position, y_position)
            self.instruction_help_frame.raise_()

        def _schedule_completion_update(self) -> None:
            QTimer.singleShot(0, self._update_completion)

        def _completion_candidates(self, prefix: str):
            wanted = prefix.upper()
            return tuple(
                info
                for mnemonic, info in self._assembler_commands().items()
                if mnemonic.startswith(wanted)
            )

        def _current_completion(self):
            if not self._completion_enabled or not self.hasFocus():
                return None

            cursor = self.textCursor()
            if cursor.hasSelection():
                return None

            block_text = cursor.block().text()
            position_in_block = cursor.positionInBlock()
            text_before_cursor = block_text[:position_in_block]
            if ";" in text_before_cursor:
                return None

            word_match = re.search(r"([A-Za-z]{1,8})$", text_before_cursor)
            if word_match is None:
                return None

            # -------------------------------------------------------------------
            # Nur die Opcode-Position vervollstaendigen: am Zeilenanfang oder
            # direkt hinter einer mit Doppelpunkt abgeschlossenen Marke.
            # -------------------------------------------------------------------
            prefix_text = text_before_cursor[:word_match.start()]
            if prefix_text.strip() and re.fullmatch(
                r"\s*[A-Za-z_.$][A-Za-z0-9_.$]*:\s*",
                prefix_text,
            ) is None:
                return None

            prefix = word_match.group(1)
            candidates = self._completion_candidates(prefix)
            if not candidates:
                return None

            start = cursor.block().position() + word_match.start(1)
            return (candidates[0], candidates, prefix, start, cursor.position())

        @staticmethod
        def _display_mnemonic(info: AssemblerCommandInfo, prefix: str) -> str:
            return info.mnemonic.lower() if prefix.islower() else info.mnemonic

        def _update_completion(self) -> None:
            context = self._current_completion()
            if context is None:
                self._hide_completion()
                return

            info, candidates, prefix, _start, _end = context
            self._completion_context = context
            display_mnemonic = self._display_mnemonic(info, prefix)
            suffix = display_mnemonic[len(prefix):]

            if suffix:
                self.completion_ghost.setFont(self.font())
                self.completion_ghost.setText(suffix)
                self.completion_ghost.adjustSize()
                self.completion_ghost.show()
            else:
                self.completion_ghost.hide()

            available = ", ".join(
                candidate.mnemonic for candidate in candidates[:8]
            )
            if len(candidates) > 8:
                available += ", ..."
            self.completion_header.setText(
                f"{info.mnemonic}    {info.operands}    Verfuegbar: {available}"
            )
            self.completion_description.setText(info.description)
            self.completion_frame.show()
            self.completion_frame.raise_()
            self.completion_ghost.raise_()
            self._position_completion_widgets()

        def _position_completion_widgets(self) -> None:
            if self._completion_context is None:
                return

            cursor_rectangle = self.cursorRect()
            if self.completion_ghost.isVisible():
                self.completion_ghost.move(
                    cursor_rectangle.right(),
                    cursor_rectangle.top(),
                )

            if not self.completion_frame.isVisible():
                return

            viewport_rectangle = self.viewport().rect()
            frame_width = max(
                280,
                min(620, viewport_rectangle.width() - 12),
            )
            self.completion_description.setFixedWidth(frame_width - 20)
            self.completion_frame.adjustSize()
            self.completion_frame.resize(
                frame_width,
                self.completion_frame.sizeHint().height(),
            )

            x_position = min(
                max(4, cursor_rectangle.left()),
                max(4, viewport_rectangle.width() - frame_width - 4),
            )
            y_position = cursor_rectangle.bottom() + 5
            if y_position + self.completion_frame.height() > viewport_rectangle.bottom():
                y_position = max(
                    4,
                    cursor_rectangle.top() - self.completion_frame.height() - 5,
                )
            self.completion_frame.move(x_position, y_position)

        def _hide_completion(self) -> None:
            self._completion_context = None
            self.completion_ghost.hide()
            self.completion_frame.hide()

        def _accept_completion(self) -> None:
            if self._completion_context is None:
                return

            info, _candidates, prefix, start, end = self._completion_context
            replacement = self._display_mnemonic(info, prefix)
            if info.default_operand:
                replacement += " " + info.default_operand

            cursor = self.textCursor()
            cursor.setPosition(start)
            cursor.setPosition(end, QTextCursor.KeepAnchor)
            cursor.insertText(replacement)
            self.setTextCursor(cursor)
            self._hide_completion()

        def _show_completion_help(self) -> None:
            if self._completion_context is None:
                return
            info = self._completion_context[0]
            help_text = (
                f"{info.mnemonic}\n\n"
                f"Syntax: {info.mnemonic} {info.operands}\n\n"
                f"{info.description}"
            )
            self.assembler_help_requested.emit(info.mnemonic, help_text)

        def set_lisp_help_enabled(self, enabled: bool) -> None:
            self._lisp_help_enabled = bool(enabled)

        def help_word_at_cursor(self) -> str:
            """Liefert Schluesselwort/Funktionsname am aktuellen Cursor.

            Neben dem normalen Bezeichner unter dem Cursor wird auch der
            Funktionsname direkt vor einer oeffnenden Klammer erkannt. Damit
            funktioniert F1 z. B. auf ``WriteLn(``, ``printf(`` oder
            ``CreateWindowExA(`` auch dann, wenn der Cursor bereits hinter dem
            Namen beziehungsweise auf der Klammer steht.
            """
            source = self.toPlainText()
            position = max(0, min(self.textCursor().position(), len(source)))
            identifier = re.compile(
                r"[A-Za-z_+\-*/<>=!?][A-Za-z0-9_+\-*/<>=!?]*"
                if self._lisp_help_enabled
                else r"[A-Za-z_][A-Za-z0-9_]*"
            )
            for match in identifier.finditer(source):
                if match.start() <= position <= match.end():
                    return match.group(0)
            if position > 0:
                for match in identifier.finditer(source):
                    if match.start() <= position - 1 < match.end():
                        return match.group(0)

            # Cursor auf/kurz hinter '(' -> naechsten Funktionsbezeichner links
            # davon verwenden. Beschraenkung auf die aktuelle Zeile verhindert,
            # dass versehentlich ein Bezeichner aus einer vorherigen Anweisung
            # als Hilfekontext dient.
            line_start = source.rfind("\n", 0, position) + 1
            prefix = source[line_start:position]
            function_pattern = (
                r"([A-Za-z_+\-*/<>=!?][A-Za-z0-9_+\-*/<>=!?]*)\s*\(?\s*$"
                if self._lisp_help_enabled
                else r"([A-Za-z_][A-Za-z0-9_]*)\s*\(?\s*$"
            )
            function_match = re.search(function_pattern, prefix)
            if function_match is not None:
                return function_match.group(1)
            return ""

        def request_context_help(self) -> None:
            word = self.help_word_at_cursor()
            if not word and self._completion_context is not None:
                word = self._completion_context[0].mnemonic
            self.context_help_requested.emit(word)

        def _update_completion_theme(self) -> None:
            if self._dark_mode:
                ghost_color = "#aeb4bf"
                frame_background = "#202630"
                frame_border = "#718198"
                frame_text = "#ffffff"
            else:
                ghost_color = "#808080"
                frame_background = "#ffffdc"
                frame_border = "#808080"
                frame_text = "#000000"

            self.completion_ghost.setStyleSheet(
                f"color: {ghost_color}; background: transparent;"
            )
            self.completion_frame.setStyleSheet(
                "QFrame#assembler_completion_frame {"
                f"background-color: {frame_background};"
                f"border: 1px solid {frame_border};"
                "}"
                "QLabel {"
                f"color: {frame_text};"
                "background: transparent; border: 0;"
                "}"
                "QLabel#assembler_completion_header { font-weight: bold; }"
            )
            self.instruction_help_frame.setStyleSheet(
                "QFrame#assembler_instruction_help_frame {"
                f"background-color: {frame_background};"
                f"border: 1px solid {frame_border};"
                "}"
                "QLabel {"
                f"color: {frame_text};"
                "background: transparent; border: 0;"
                "}"
                "QLabel#assembler_instruction_help_header {"
                "font-weight: bold; color: #FFD84D;"
                "}"
                "QLabel#assembler_instruction_help_current {"
                f"font-weight: bold; color: {('#66FF66' if self._dark_mode else '#008000')};"
                "}"
            )

        def _indent_line_range(self, *, outdent: bool = False) -> None:
            """Stage 164: markierte Zeilen um exakt vier Spalten ein-/ausrücken."""
            cursor = self.textCursor()
            document = self.document()

            if cursor.hasSelection():
                selection_start = min(cursor.anchor(), cursor.position())
                selection_end = max(cursor.anchor(), cursor.position())
                first_block = document.findBlock(selection_start)
                last_block = document.findBlock(selection_end)
                if not last_block.isValid():
                    last_block = document.lastBlock()
            else:
                first_block = cursor.block()
                last_block = first_block

            if not first_block.isValid() or not last_block.isValid():
                return

            start_pos = first_block.position()
            end_pos = last_block.position() + len(last_block.text())

            block_cursor = QTextCursor(document)
            block_cursor.setPosition(start_pos)
            block_cursor.setPosition(end_pos, QTextCursor.KeepAnchor)
            source = block_cursor.selectedText().replace("\u2029", "\n")
            lines = source.split("\n")

            if outdent:
                transformed = []
                for line in lines:
                    if line.startswith("\t"):
                        transformed.append(line[1:])
                        continue
                    remove_count = min(
                        4,
                        len(line) - len(line.lstrip(" ")),
                    )
                    transformed.append(line[remove_count:])
            else:
                transformed = ["    " + line for line in lines]

            replacement = "\n".join(transformed)
            block_cursor.beginEditBlock()
            block_cursor.insertText(replacement)
            block_cursor.endEditBlock()

            # Die bearbeiteten Zeilen bleiben markiert, damit TAB/Outdent
            # mehrfach hintereinander angewendet werden kann.
            selected_cursor = QTextCursor(document)
            selected_cursor.setPosition(start_pos)
            selected_cursor.setPosition(
                start_pos + len(replacement),
                QTextCursor.KeepAnchor,
            )
            self.setTextCursor(selected_cursor)
            self.ensureCursorVisible()

        def _insert_four_spaces(self) -> None:
            cursor = self.textCursor()
            cursor.insertText("    ")
            self.setTextCursor(cursor)

        # -------------------------------------------------------------------
        # Stage ASM 59: C64 BASIC arbeitet im Codebereich in Grossbuchstaben.
        # Strings und REM-Kommentare behalten dagegen exakt die vom Benutzer
        # eingegebene Gross-/Kleinschreibung. Ziffern und Shift-Sonderzeichen
        # werden niemals veraendert.
        # -------------------------------------------------------------------
        def _basic_transform_inserted_text(self, text: str) -> str:
            if not self._basic_line_number_mode:
                return str(text or "")
            from c64basic.editor_model import transform_basic_typed_text

            cursor = self.textCursor()
            prefix = cursor.block().text()[:cursor.positionInBlock()]
            return transform_basic_typed_text(prefix, str(text or ""))

        def insert_basic_keyboard_text(self, text: str) -> None:
            if self.isReadOnly():
                return
            cursor = self.textCursor()
            cursor.insertText(self._basic_transform_inserted_text(text))
            self.setTextCursor(cursor)
            self.ensureCursorVisible()

        def _insert_basic_petscii_byte(self, byte_value: int) -> None:
            if self.isReadOnly():
                return
            value = int(byte_value) & 0xFF
            # Direct-PETSCII-PUA von C64 Pro Mono: U+E000..U+E0FF.
            # Anders als die sichtbare Unicode-Näherung ist diese Darstellung
            # eineindeutig und kann vom BASIC-Compiler exakt zurückkodiert werden.
            glyph = chr(0xE000 + value)
            cursor = self.textCursor()
            cursor.insertText(glyph)
            self.setTextCursor(cursor)
            self.ensureCursorVisible()

        def _open_basic_petscii_dialog(self) -> None:
            if self.isReadOnly():
                return
            point_size = self.font().pointSize()
            if point_size <= 0:
                point_size = 11
            dialog = PetsciiCharacterDialog(
                self,
                byte_index=-1,
                current_value=-1,
                font_family=self.font().family(),
                point_size=point_size,
                basic_insert_mode=True,
            )
            dialog.byteSelected.connect(self._insert_basic_petscii_byte)
            dialog.exec_()

        def basic_keyboard_special_key(self, key: str) -> None:
            if self.isReadOnly():
                return
            name = str(key or "").strip().casefold()
            if name == "petscii":
                self._open_basic_petscii_dialog()
                return
            cursor = self.textCursor()
            if name == "backspace":
                if cursor.hasSelection():
                    cursor.removeSelectedText()
                else:
                    cursor.deletePreviousChar()
            elif name == "delete":
                if cursor.hasSelection():
                    cursor.removeSelectedText()
                else:
                    cursor.deleteChar()
            elif name == "return":
                cursor.insertBlock()
            elif name == "home":
                cursor.movePosition(QTextCursor.StartOfBlock)
            elif name == "end":
                cursor.movePosition(QTextCursor.EndOfBlock)
            elif name == "left":
                cursor.movePosition(QTextCursor.Left)
            elif name == "right":
                cursor.movePosition(QTextCursor.Right)
            elif name == "up":
                cursor.movePosition(QTextCursor.Up)
            elif name == "down":
                cursor.movePosition(QTextCursor.Down)
            else:
                return
            self.setTextCursor(cursor)
            self.ensureCursorVisible()

        def insertFromMimeData(self, source) -> None:
            if (
                self._basic_line_number_mode
                and not self.isReadOnly()
                and source is not None
                and source.hasText()
            ):
                cursor = self.textCursor()
                cursor.insertText(
                    self._basic_transform_inserted_text(source.text())
                )
                self.setTextCursor(cursor)
                return
            super().insertFromMimeData(source)

        def keyPressEvent(self, event) -> None:
            # Stage 166: explizite Windows-Shortcuts fuer Undo/Redo in allen
            # Code-Editoren. QPlainTextEdit besitzt zwar eigene Standard-
            # Bindings, die festen Tasten halten das Verhalten aber unabhaengig
            # von Plattform-/KeySequence-Abweichungen bei CTRL+Z / CTRL+Y.
            modifiers = event.modifiers()
            if (
                event.key() == Qt.Key_Z
                and modifiers == Qt.ControlModifier
            ):
                if not self.isReadOnly():
                    self.undo()
                event.accept()
                return
            if (
                event.key() == Qt.Key_Y
                and modifiers == Qt.ControlModifier
            ):
                if not self.isReadOnly():
                    self.redo()
                event.accept()
                return

            # Stage 162: Standard-Shortcut CTRL+F in jedem SourceTextEdit.
            if event.matches(QKeySequence.Find):
                self.find_requested.emit(self)
                event.accept()
                return
            if event.key() == Qt.Key_F3:
                self.find_next_requested.emit(self)
                event.accept()
                return
            if event.key() == Qt.Key_F1:
                self.request_context_help()
                event.accept()
                return
            if event.key() == Qt.Key_F2:
                self.build_requested.emit()
                event.accept()
                return

            # Stage 164: Einrückung mit vier Leerzeichen.
            # ALT+TAB wird von Windows normalerweise als System-Shortcut
            # abgefangen; falls Qt das Ereignis erhält, wird es als Outdent
            # behandelt. SHIFT+TAB/Backtab ist die zuverlässige Alternative.
            modifiers = event.modifiers()
            if event.key() in (Qt.Key_Tab, Qt.Key_Backtab):
                outdent = bool(
                    event.key() == Qt.Key_Backtab
                    or (modifiers & Qt.ShiftModifier)
                    or (modifiers & Qt.AltModifier)
                )
                if outdent:
                    self._indent_line_range(outdent=True)
                elif self.textCursor().hasSelection():
                    self._indent_line_range(outdent=False)
                else:
                    self._insert_four_spaces()
                event.accept()
                return

            if self._basic_line_number_mode and not self.isReadOnly():
                # Stage ASM 62: C64-DEL-Verhalten auch auf der Windows-Tastatur.
                # Sowohl Backspace (Taste oberhalb RETURN) als auch Delete
                # löschen im BASIC-Editor das Zeichen LINKS vom Cursor. Dadurch
                # darf das von manchen Layouts gelieferte Steuer-/Ersatzzeichen
                # niemals als sichtbares Kästchen in den Quelltext gelangen.
                if event.key() in (Qt.Key_Backspace, Qt.Key_Delete):
                    cursor = self.textCursor()
                    if cursor.hasSelection():
                        cursor.removeSelectedText()
                    else:
                        cursor.deletePreviousChar()
                    self.setTextCursor(cursor)
                    self.ensureCursorVisible()
                    self._reset_basic_block_cursor_blink()
                    event.accept()
                    return

                text = event.text()
                shortcut_modifiers = modifiers & (
                    Qt.ControlModifier | Qt.AltModifier | Qt.MetaModifier
                )
                if text and not shortcut_modifiers and text not in ("\r", "\n", "\t"):
                    cursor = self.textCursor()
                    cursor.insertText(self._basic_transform_inserted_text(text))
                    self.setTextCursor(cursor)
                    event.accept()
                    return

            if self.completion_frame.isVisible():
                if event.key() in (Qt.Key_Return, Qt.Key_Enter):
                    self._accept_completion()
                    event.accept()
                    return
                if event.key() == Qt.Key_Escape:
                    self._hide_completion()
                    event.accept()
                    return
            super().keyPressEvent(event)

        def focusInEvent(self, event) -> None:
            super().focusInEvent(event)
            if self._basic_line_number_mode:
                self._reset_basic_block_cursor_blink()

        def focusOutEvent(self, event) -> None:
            if self._basic_line_number_mode:
                self._basic_block_cursor_timer.stop()
                self._basic_block_cursor_visible = False
                self.viewport().update()
            self._hide_completion()
            self._instruction_help_hover_active = False
            self._instruction_help_anchor_rect = None
            self.instruction_help_frame.hide()
            super().focusOutEvent(event)

        def mouseMoveEvent(self, event) -> None:
            # Stage ASM 3: Live-Hilfe nur auf den sichtbaren Opcode-Buchstaben.
            # Operand, Kommentar und freier Zeilenbereich sind keine Treffer.
            hover = self._assembler_instruction_info_at_point(event.pos())
            if hover is not None:
                context, anchor = hover
                self._instruction_help_hover_active = True
                self._show_instruction_help_context(
                    context,
                    anchor_rect=anchor,
                )
            elif self._instruction_help_hover_active:
                self._instruction_help_hover_active = False
                self._instruction_help_anchor_rect = None
                self._update_instruction_help()

            if self._jump_target_at_point(event.pos()) is not None:
                self.viewport().setCursor(Qt.PointingHandCursor)
            else:
                self.viewport().setCursor(Qt.IBeamCursor)
            super().mouseMoveEvent(event)

        def mousePressEvent(self, event) -> None:
            if event.button() == Qt.LeftButton:
                target = self._jump_target_at_point(event.pos())
                if target is not None and self._jump_to_label(target):
                    event.accept()
                    return
            super().mousePressEvent(event)
            if event.button() == Qt.LeftButton:
                # cursorForPosition has now been applied by QPlainTextEdit.
                QTimer.singleShot(0, self._update_instruction_help)

        def contextMenuEvent(self, event) -> None:
            operand_context = self._assembler_operand_context_at_point(
                event.pos()
            )
            menu = self.createStandardContextMenu()
            if operand_context is not None:
                menu.addSeparator()
                calculator_action = menu.addAction("Rechner für Operand...")
                calculator_action.triggered.connect(
                    lambda checked=False, value=operand_context:
                    self._open_operand_calculator(value)
                )
            menu.exec_(event.globalPos())
            menu.deleteLater()

        def leaveEvent(self, event) -> None:
            self._instruction_help_hover_active = False
            self._instruction_help_anchor_rect = None
            self._update_instruction_help()
            self.viewport().setCursor(Qt.IBeamCursor)
            super().leaveEvent(event)

        def _marker_area_width(self) -> int:
            return (
                self.GUTTER_MARKER_COLUMN_WIDTH
                * self.GUTTER_MARKER_COLUMNS
            )

        @staticmethod
        def _cursor_line_numbers(cursors) -> Tuple[int, ...]:
            result = set()
            for cursor in cursors:
                block = cursor.block()
                if block.isValid():
                    result.add(block.blockNumber() + 1)
            return tuple(sorted(result))

        def breakpoint_lines(self) -> Tuple[int, ...]:
            return self._cursor_line_numbers(self._breakpoint_cursors)

        def bookmark_lines(self) -> Tuple[int, ...]:
            return self._cursor_line_numbers(self._bookmark_cursors)

        def replace_gutter_markers(
            self,
            marker_kind: str,
            line_numbers: Iterable[int],
            *,
            emit_change: bool = True,
        ) -> None:
            """Stage 246: ersetzt einen Marker-Satz atomar durch beliebig viele Zeilen."""
            normalized = []
            for value in line_numbers or ():
                try:
                    line_number = int(value)
                except (TypeError, ValueError):
                    continue
                if line_number <= 0 or line_number in normalized:
                    continue
                block = self.document().findBlockByNumber(line_number - 1)
                if block.isValid():
                    normalized.append(line_number)

            cursors = []
            for line_number in sorted(normalized):
                block = self.document().findBlockByNumber(line_number - 1)
                cursor = QTextCursor(self.document())
                cursor.setPosition(block.position())
                cursors.append(cursor)

            if marker_kind == "breakpoint":
                self._breakpoint_cursors = cursors
            elif marker_kind == "bookmark":
                self._bookmark_cursors = cursors
            else:
                raise ValueError(f"Unbekannter Gutter-Marker: {marker_kind}")

            self.line_number_area.update()
            if emit_change:
                if marker_kind == "breakpoint":
                    self.breakpoints_changed.emit()
                else:
                    self.bookmarks_changed.emit()

        def _marker_cursors(self, marker_kind: str):
            if marker_kind == "breakpoint":
                return self._breakpoint_cursors
            if marker_kind == "bookmark":
                return self._bookmark_cursors
            raise ValueError(f"Unbekannter Gutter-Marker: {marker_kind}")

        def _set_gutter_marker(self, marker_kind: str, line_number: int) -> bool:
            block = self.document().findBlockByNumber(int(line_number) - 1)
            if not block.isValid():
                return False
            cursors = self._marker_cursors(marker_kind)
            if int(line_number) in self._cursor_line_numbers(cursors):
                return False
            cursor = QTextCursor(self.document())
            cursor.setPosition(block.position())
            cursors.append(cursor)
            self.line_number_area.update()
            if marker_kind == "breakpoint":
                self.breakpoints_changed.emit()
            else:
                self.bookmarks_changed.emit()
            return True

        def _remove_gutter_marker(self, marker_kind: str, line_number: int) -> bool:
            cursors = self._marker_cursors(marker_kind)
            line_number = int(line_number)
            kept = []
            removed = False
            for cursor in cursors:
                block = cursor.block()
                current_line = block.blockNumber() + 1 if block.isValid() else -1
                if current_line == line_number:
                    removed = True
                    continue
                kept.append(cursor)
            if not removed:
                return False
            if marker_kind == "breakpoint":
                self._breakpoint_cursors = kept
                self.breakpoints_changed.emit()
            else:
                self._bookmark_cursors = kept
                self.bookmarks_changed.emit()
            self.line_number_area.update()
            return True

        def clear_gutter_markers(self) -> None:
            had_breakpoints = bool(self._breakpoint_cursors)
            had_bookmarks = bool(self._bookmark_cursors)
            self._breakpoint_cursors = []
            self._bookmark_cursors = []
            self.line_number_area.update()
            if had_breakpoints:
                self.breakpoints_changed.emit()
            if had_bookmarks:
                self.bookmarks_changed.emit()

        def _gutter_document_changed(self) -> None:
            if not (self._breakpoint_cursors or self._bookmark_cursors):
                return
            # QTextCursor-Positionen wandern bei Einfügungen/Löschungen mit.
            # Dadurch bleiben Marker an ihrem Textblock gebunden und das
            # Favoriten-Menü bekommt automatisch die aktualisierte Zeilennummer.
            self.line_number_area.update()
            self.breakpoints_changed.emit()
            self.bookmarks_changed.emit()

        def _line_number_at_gutter_y(self, y: int) -> Optional[int]:
            cursor = self.cursorForPosition(QPoint(0, int(y)))
            block = cursor.block()
            if not block.isValid():
                return None
            return block.blockNumber() + 1

        def handle_line_number_area_mouse_press(self, event) -> bool:
            x = int(event.pos().x())
            marker_width = self._marker_area_width()
            if x < 0 or x >= marker_width:
                return False
            line_number = self._line_number_at_gutter_y(event.pos().y())
            if line_number is None:
                return False
            marker_kind = (
                "breakpoint"
                if x < self.GUTTER_MARKER_COLUMN_WIDTH
                else "bookmark"
            )
            if event.button() == Qt.LeftButton:
                self._set_gutter_marker(marker_kind, line_number)
                return True
            if event.button() == Qt.RightButton:
                self._remove_gutter_marker(marker_kind, line_number)
                return True
            return False

        def line_number_area_width(self) -> int:
            if self._basic_line_number_mode:
                gutter_font = self._basic_gutter_font or self.font()
                metrics = QFontMetrics(gutter_font)
                # C64 BASIC line numbers are deliberately capped at 65535.
                # Reserve five digits permanently so the editor does not jump
                # horizontally while line numbers grow.
                return (
                    self._marker_area_width()
                    + 10
                    + metrics.horizontalAdvance("9") * 5
                )
            digits = max(1, len(str(max(1, self.blockCount()))))
            return (
                self._marker_area_width()
                + 10
                + self.fontMetrics().horizontalAdvance("9") * digits
            )

        def update_line_number_area_width(self, _new_block_count: int = 0) -> None:
            self.setViewportMargins(self.line_number_area_width(), 0, 0, 0)
            self.line_number_area.update()

        def update_line_number_area(self, rect: QRect, dy: int) -> None:
            if dy:
                self.line_number_area.scroll(0, dy)
            else:
                self.line_number_area.update(
                    0,
                    rect.y(),
                    self.line_number_area.width(),
                    rect.height(),
                )

            if rect.contains(self.viewport().rect()):
                self.update_line_number_area_width(0)
            self._position_completion_widgets()
            self._position_instruction_help_frame()

        def resizeEvent(self, event) -> None:
            super().resizeEvent(event)
            contents = self.contentsRect()
            self.line_number_area.setGeometry(
                QRect(
                    contents.left(),
                    contents.top(),
                    self.line_number_area_width(),
                    contents.height(),
                )
            )
            self._position_completion_widgets()
            self._position_instruction_help_frame()
            self.viewport_geometry_changed.emit()

        def set_gutter_dark_mode(self, enabled: bool) -> None:
            self._dark_mode = bool(enabled)
            self.line_number_area.update()
            self._update_completion_theme()
            self._update_current_line_highlight()

        def set_markdown_mode(self, enabled: bool) -> None:
            self._markdown_mode = bool(enabled)
            self.line_number_area.update()
            self._update_current_line_highlight()

        def line_number_area_paint_event(self, event) -> None:
            painter = QPainter(self.line_number_area)
            if self._markdown_mode and self._dark_mode:
                background = QColor("#161B22")
                foreground = QColor("#8B949E")
                separator = QColor("#30363D")
            elif self._markdown_mode:
                background = QColor("#F6F8FA")
                foreground = QColor("#57606A")
                separator = QColor("#D0D7DE")
            elif self._dark_mode:
                background = QColor(16, 24, 95)
                foreground = QColor(220, 220, 220)
                separator = QColor(51, 69, 141)
            else:
                background = QColor(232, 232, 232)
                foreground = QColor(0, 0, 0)
                separator = QColor(184, 184, 184)

            painter.fillRect(event.rect(), background)
            gutter_font = (
                self._basic_gutter_font
                if self._basic_line_number_mode and self._basic_gutter_font is not None
                else self.font()
            )
            painter.setFont(gutter_font)
            gutter_metrics = QFontMetrics(gutter_font)

            block = self.firstVisibleBlock()
            block_number = block.blockNumber()
            top = round(
                self.blockBoundingGeometry(block)
                .translated(self.contentOffset())
                .top()
            )
            bottom = top + round(self.blockBoundingRect(block).height())

            breakpoint_lines = set(self.breakpoint_lines())
            bookmark_lines = set(self.bookmark_lines())
            marker_column_width = self.GUTTER_MARKER_COLUMN_WIDTH
            marker_area_width = self._marker_area_width()
            painter.setRenderHint(QPainter.Antialiasing, True)

            while block.isValid() and top <= event.rect().bottom():
                if block.isVisible() and bottom >= event.rect().top():
                    line_number = block_number + 1
                    marker_diameter = min(9, max(6, self.fontMetrics().height() - 5))
                    marker_y = top + max(1, (self.fontMetrics().height() - marker_diameter) // 2)
                    if line_number in breakpoint_lines:
                        painter.setPen(QPen(QColor("#c85c5c"), 1))
                        painter.setBrush(QColor("#ff8f8f"))
                        painter.drawEllipse(
                            2, marker_y, marker_diameter, marker_diameter
                        )
                    if line_number in bookmark_lines:
                        painter.setPen(QPen(QColor("#4f8fbd"), 1))
                        painter.setBrush(QColor("#8fd0ff"))
                        painter.drawEllipse(
                            marker_column_width + 2,
                            marker_y,
                            marker_diameter,
                            marker_diameter,
                        )
                    painter.setBrush(Qt.NoBrush)
                    gutter_label = str(line_number)
                    gutter_color = foreground
                    if self._basic_line_number_mode:
                        basic_number = self._basic_block_line_number(block)
                        if basic_number is None:
                            gutter_label = "-----"
                            gutter_color = QColor("#FF4040")
                        else:
                            gutter_label = str(min(65535, int(basic_number)))
                    painter.setPen(gutter_color)
                    painter.drawText(
                        marker_area_width,
                        top,
                        self.line_number_area.width() - marker_area_width - 5,
                        gutter_metrics.height(),
                        Qt.AlignRight,
                        gutter_label,
                    )

                block = block.next()
                top = bottom
                block_number += 1
                if block.isValid():
                    bottom = top + round(self.blockBoundingRect(block).height())

            painter.setPen(separator)
            painter.drawLine(
                self.GUTTER_MARKER_COLUMN_WIDTH,
                event.rect().top(),
                self.GUTTER_MARKER_COLUMN_WIDTH,
                event.rect().bottom(),
            )
            painter.drawLine(
                self._marker_area_width(),
                event.rect().top(),
                self._marker_area_width(),
                event.rect().bottom(),
            )
            painter.drawLine(
                self.line_number_area.width() - 1,
                event.rect().top(),
                self.line_number_area.width() - 1,
                event.rect().bottom(),
            )

    # -----------------------------------------------------------------------
    # SourceTextEdit + Mini-Map als gemeinsamer Layout-Container.
    # Der Editor selbst bleibt unverändert; insbesondere Gutter, Breakpoints,
    # Bookmarks, Completion und Syntax-Highlighter arbeiten weiter direkt auf
    # SourceTextEdit.
    # -----------------------------------------------------------------------
    class SourceEditorWithMiniMap(QWidget):
        def __init__(
            self,
            parent: Optional[QWidget] = None,
            *,
            min_viewport_height: Optional[int] = None,
        ):
            super().__init__(parent)
            self.setObjectName("source_editor_with_minimap")

            layout = QHBoxLayout(self)
            layout.setContentsMargins(0, 0, 0, 0)
            layout.setSpacing(0)

            self.editor = SourceTextEdit(self)
            if min_viewport_height is None:
                # Keep the long-standing default construction path intact.
                self.minimap = SourceMiniMap(self.editor, self)
            else:
                self.minimap = SourceMiniMap(
                    self.editor,
                    self,
                    min_viewport_height=min_viewport_height,
                )

            layout.addWidget(self.editor, 1)
            layout.addWidget(self.minimap)

    # -----------------------------------------------------------------------
    # Character-Editor für 255 editierbare C64-Zeichen ($01-$FF).
    # -----------------------------------------------------------------------
    def _c64_character_pixmap(
        rows: Sequence[int],
        foreground: QColor,
        background: QColor,
        size: int = 32,
    ) -> QPixmap:
        pixmap = QPixmap(max(8, int(size)), max(8, int(size)))
        pixmap.fill(background)
        painter = QPainter(pixmap)
        try:
            cell = max(1, pixmap.width() // 8)
            offset_x = (pixmap.width() - cell * 8) // 2
            offset_y = (pixmap.height() - cell * 8) // 2
            painter.setPen(Qt.NoPen)
            painter.setBrush(foreground)
            normalized = tuple(int(value) & 0xFF for value in rows)
            for y, row in enumerate(normalized[:8]):
                for x in range(8):
                    if row & (0x80 >> x):
                        painter.drawRect(
                            offset_x + x * cell,
                            offset_y + y * cell,
                            cell,
                            cell,
                        )
        finally:
            painter.end()
        return pixmap


    class CharacterPixelGrid(QWidget):
        rowsChanged = pyqtSignal(object)

        def __init__(self, parent: Optional[QWidget] = None):
            super().__init__(parent)
            self.setObjectName("character_pixel_grid")
            self.setFocusPolicy(Qt.StrongFocus)
            self.setMouseTracking(True)
            self.setMinimumSize(336, 336)
            self._rows = [0] * 8
            self._foreground = QColor("#FFFFFF")
            self._background = QColor("#000000")
            self._cursor_x = 0
            self._cursor_y = 0
            self._drawing_value = None

        def rows(self) -> Tuple[int, ...]:
            return tuple(self._rows)

        def set_rows(self, rows: Sequence[int]) -> None:
            normalized = [int(value) & 0xFF for value in rows]
            if len(normalized) != 8:
                raise ValueError("Ein Zeichen muss genau acht Zeilen besitzen.")
            self._rows = normalized
            self.update()

        def set_colors(self, foreground: QColor, background: QColor) -> None:
            self._foreground = QColor(foreground)
            self._background = QColor(background)
            self.update()

        def sizeHint(self) -> QSize:
            return QSize(416, 416)

        def _geometry(self) -> Tuple[int, int, int]:
            margin = 12
            cell = max(
                8,
                min(
                    (self.width() - margin * 2) // 8,
                    (self.height() - margin * 2) // 8,
                ),
            )
            grid_size = cell * 8
            return (
                (self.width() - grid_size) // 2,
                (self.height() - grid_size) // 2,
                cell,
            )

        def paintEvent(self, event) -> None:
            painter = QPainter(self)
            painter.fillRect(event.rect(), self.palette().window())
            origin_x, origin_y, cell = self._geometry()
            grid_rect = QRect(origin_x, origin_y, cell * 8, cell * 8)
            painter.fillRect(grid_rect, self._background)

            painter.setPen(Qt.NoPen)
            painter.setBrush(self._foreground)
            for y, row in enumerate(self._rows):
                for x in range(8):
                    if row & (0x80 >> x):
                        painter.drawRect(
                            origin_x + x * cell,
                            origin_y + y * cell,
                            cell,
                            cell,
                        )

            grid_color = self.palette().mid().color()
            painter.setPen(QPen(grid_color, 1))
            for index in range(9):
                x = origin_x + index * cell
                y = origin_y + index * cell
                painter.drawLine(x, origin_y, x, origin_y + cell * 8)
                painter.drawLine(origin_x, y, origin_x + cell * 8, y)

            cursor_color = self.palette().highlight().color()
            painter.setPen(QPen(cursor_color, 2))
            painter.drawRect(
                origin_x + self._cursor_x * cell + 1,
                origin_y + self._cursor_y * cell + 1,
                max(1, cell - 2),
                max(1, cell - 2),
            )

        def _position_to_cell(self, position) -> Optional[Tuple[int, int]]:
            origin_x, origin_y, cell = self._geometry()
            x = (int(position.x()) - origin_x) // cell
            y = (int(position.y()) - origin_y) // cell
            if 0 <= x < 8 and 0 <= y < 8:
                return x, y
            return None

        def _set_pixel(self, x: int, y: int, enabled: bool) -> None:
            mask = 0x80 >> int(x)
            previous = self._rows[y]
            if enabled:
                self._rows[y] |= mask
            else:
                self._rows[y] &= (~mask) & 0xFF
            self._cursor_x = int(x)
            self._cursor_y = int(y)
            if self._rows[y] != previous:
                self.rowsChanged.emit(tuple(self._rows))
            self.update()

        def mousePressEvent(self, event) -> None:
            cell = self._position_to_cell(event.pos())
            if cell is None:
                return
            x, y = cell
            if event.button() == Qt.RightButton:
                self._drawing_value = False
            elif event.button() == Qt.LeftButton:
                self._drawing_value = True
            else:
                return
            self._set_pixel(x, y, self._drawing_value)
            self.setFocus(Qt.MouseFocusReason)

        def mouseMoveEvent(self, event) -> None:
            if self._drawing_value is None:
                cell = self._position_to_cell(event.pos())
                if cell is not None:
                    self._cursor_x, self._cursor_y = cell
                    self.update()
                return
            cell = self._position_to_cell(event.pos())
            if cell is not None:
                self._set_pixel(cell[0], cell[1], self._drawing_value)

        def mouseReleaseEvent(self, event) -> None:
            self._drawing_value = None

        def keyPressEvent(self, event) -> None:
            key = event.key()
            if key == Qt.Key_Left:
                self._cursor_x = max(0, self._cursor_x - 1)
            elif key == Qt.Key_Right:
                self._cursor_x = min(7, self._cursor_x + 1)
            elif key == Qt.Key_Up:
                self._cursor_y = max(0, self._cursor_y - 1)
            elif key == Qt.Key_Down:
                self._cursor_y = min(7, self._cursor_y + 1)
            elif key in (Qt.Key_Space, Qt.Key_Return, Qt.Key_Enter):
                mask = 0x80 >> self._cursor_x
                enabled = not bool(self._rows[self._cursor_y] & mask)
                self._set_pixel(self._cursor_x, self._cursor_y, enabled)
                return
            elif key in (Qt.Key_Delete, Qt.Key_Backspace):
                self._set_pixel(self._cursor_x, self._cursor_y, False)
                return
            else:
                super().keyPressEvent(event)
                return
            self.update()


    class CharacterPreviewWidget(QWidget):
        def __init__(self, parent: Optional[QWidget] = None):
            super().__init__(parent)
            self.setObjectName("character_preview")
            self.setMinimumSize(144, 144)
            self.setMaximumSize(224, 224)
            self._rows = [0] * 8
            self._foreground = QColor("#FFFFFF")
            self._background = QColor("#000000")

        def set_rows(self, rows: Sequence[int]) -> None:
            self._rows = [int(value) & 0xFF for value in rows]
            self.update()

        def set_colors(self, foreground: QColor, background: QColor) -> None:
            self._foreground = QColor(foreground)
            self._background = QColor(background)
            self.update()

        def paintEvent(self, event) -> None:
            painter = QPainter(self)
            painter.fillRect(event.rect(), self.palette().window())
            side = min(self.width(), self.height()) - 16
            cell = max(1, side // 8)
            side = cell * 8
            left = (self.width() - side) // 2
            top = (self.height() - side) // 2
            painter.fillRect(QRect(left, top, side, side), self._background)
            painter.setPen(Qt.NoPen)
            painter.setBrush(self._foreground)
            for y, row in enumerate(self._rows):
                for x in range(8):
                    if row & (0x80 >> x):
                        painter.drawRect(
                            left + x * cell,
                            top + y * cell,
                            cell,
                            cell,
                        )


    class C64CharacterEditorDialog(QDialog):
        def __init__(
            self,
            parent: QWidget,
            *,
            initial_directory: Path,
            initial_path: Optional[Path] = None,
        ):
            super().__init__(parent)
            self.setObjectName("c64_character_editor_dialog")
            self.setWindowTitle("C64 Character-Editor")
            self.setModal(False)
            self.resize(1120, 760)

            self.initial_directory = Path(initial_directory)
            self.charset = bytearray(C64_CHARACTER_FILE_SIZE)
            self.current_code = 1
            self.current_path = None
            self.modified = False
            self.dirty_characters = set()
            self.character_items = {}

            self._create_ui()
            self._build_character_list()
            self._select_character(1)
            self._set_modified(False)

            if initial_path is not None:
                QTimer.singleShot(0, lambda: self.load_file(Path(initial_path)))

        def _create_ui(self) -> None:
            root_layout = QVBoxLayout(self)
            root_layout.setContentsMargins(10, 10, 10, 10)
            root_layout.setSpacing(8)

            file_row = QHBoxLayout()
            self.new_button = QPushButton("Neu", self)
            self.load_button = QPushButton("Laden …", self)
            self.save_button = QPushButton("Speichern", self)
            self.save_as_button = QPushButton("Speichern unter …", self)
            file_row.addWidget(self.new_button)
            file_row.addWidget(self.load_button)
            file_row.addWidget(self.save_button)
            file_row.addWidget(self.save_as_button)
            file_row.addStretch(1)
            root_layout.addLayout(file_row)

            self.path_label = QLabel("Neuer Zeichensatz – 2048 Bytes", self)
            self.path_label.setTextInteractionFlags(Qt.TextSelectableByMouse)
            root_layout.addWidget(self.path_label)

            splitter = QSplitter(Qt.Horizontal, self)
            splitter.setChildrenCollapsible(False)
            root_layout.addWidget(splitter, 1)

            left_panel = QWidget(splitter)
            left_layout = QVBoxLayout(left_panel)
            left_layout.setContentsMargins(0, 0, 0, 0)
            left_layout.setSpacing(6)

            search_row = QHBoxLayout()
            self.code_input = QLineEdit(left_panel)
            self.code_input.setPlaceholderText("Zeichen anspringen: $01, 0x41 oder 65")
            self.jump_button = QPushButton("Gehe zu", left_panel)
            search_row.addWidget(self.code_input, 1)
            search_row.addWidget(self.jump_button)
            left_layout.addLayout(search_row)

            self.character_list = QListWidget(left_panel)
            self.character_list.setObjectName("character_editor_list")
            self.character_list.setViewMode(QListWidget.IconMode)
            self.character_list.setResizeMode(QListWidget.Adjust)
            self.character_list.setMovement(QListWidget.Static)
            self.character_list.setIconSize(QSize(36, 36))
