        def _make_compact_new_action(
            self,
            text: str,
            callback,
            status_tip: str,
        ) -> QAction:
            action = QAction(text, self)
            action.setStatusTip(status_tip)
            action.triggered.connect(
                lambda _checked=False, fn=callback: fn()
            )
            return action

        def _create_compact_new_actions(self) -> None:
            """Erzeugt die Aktionen für die acht kompakten Neu-Untermenüs."""
            profiles = {
                "windows_pe32": {
                    "project_kind": "windows_pe32",
                    "language": "c",
                    "target": "pe32",
                    "title": "Windows PE32",
                },
                "windows_pe64": {
                    "project_kind": "windows_pe64",
                    "language": "c",
                    "target": "pe64",
                    "title": "Windows PE32+",
                },
                "amiga500": {
                    "project_kind": "amiga500",
                    "language": "c",
                    "target": "amiga",
                    "title": "Amiga 500 ADF",
                },
                "c64": {
                    "project_kind": "c64",
                    "language": "basic",
                    "target": "c64",
                    "title": "C= 64 mk68x",
                },
                "prolog": {
                    "project_kind": "prolog",
                    "language": "prolog",
                    "target": "pe32",
                    "title": "PROLOG",
                },
                "logo": {
                    "project_kind": "logo",
                    "language": "logo",
                    "target": "pe32",
                    "title": "LOGO",
                },
                "dbase": {
                    "project_kind": "dbase",
                    "language": "dbase",
                    "target": "pe32",
                    "title": "dBase",
                },
                "assembler": {
                    "project_kind": "assembler",
                    "language": "assembler",
                    "target": "c64",
                    "title": "Assembler",
                },
            }
            self.compact_new_profiles = profiles
            self.compact_new_actions = {}
            for profile_key, spec in profiles.items():
                title = spec["title"]
                self.compact_new_actions[profile_key] = {
                    "project": self._make_compact_new_action(
                        "Projekt",
                        lambda key=profile_key: self.new_project(
                            profiles[key]["project_kind"]
                        ),
                        f"Bestehendes Projekt speichern und neues {title}-Projekt anlegen",
                    ),
                    "application": self._make_compact_new_action(
                        "Anwendung",
                        lambda key=profile_key: self.new_profile_source_document(
                            key, use_template=True
                        ),
                        f"Neue {title}-Anwendung mit Template im Projekt anlegen",
                    ),
                    "program": self._make_compact_new_action(
                        "Programm",
                        lambda key=profile_key: self.new_profile_source_document(
                            key, use_template=False
                        ),
                        f"Neue leere {title}-Programmdatei im Projekt anlegen",
                    ),
                }

            # Stage 84: dBase bekommt unterhalb von "Programm" einen eigenen
            # visuellen Formulardesigner.
            self.compact_new_actions["dbase"]["form"] = (
                self._make_compact_new_action(
                    "Formular",
                    self.show_dbase_form_designer,
                    "dBase-Formulardesigner mit Eigenschaften und Komponentenpalette öffnen",
                )
            )
            self.compact_new_actions["dbase"]["table"] = (
                self._make_compact_new_action(
                    "Tabelle",
                    self.show_dbase_table_designer,
                    "dBase-Tabellendesigner für lokale DBF-Dateien öffnen",
                )
            )
            self.compact_new_actions["dbase"]["sql_builder"] = (
                self._make_compact_new_action(
                    "SQL Builder",
                    self.show_dbase_sql_builder,
                    "Grafischen dBase SQL Builder für lokale DBF-Tabellen öffnen",
                )
            )
            self.compact_new_actions["dbase"]["report"] = (
                self._make_compact_new_action(
                    "Bericht",
                    self.new_dbase_report,
                    "Neuen dBase Bericht mit Kopf-, Detail- und Fußbereichen öffnen",
                )
            )
            self.compact_new_actions["dbase"]["labels"] = (
                self._make_compact_new_action(
                    "Etiketten",
                    self.show_dbase_label_designer,
                    "dBase-Etiketten-Designer mit Formatbibliothek und Tabellen-/SQL-Feldern öffnen",
                )
            )

            # Die bisherigen Sprachaktionen werden nicht gelöscht.  Sie werden
            # als zielgebundene Proxy-Aktionen in die passenden neuen Untermenüs
            # verschoben.  Damit bleibt die alte Programmlogik erhalten, ohne
            # die erste Neu-Ebene wieder zu verbreitern.
            def language_action(label: str, language: str, target: str) -> QAction:
                return self._make_compact_new_action(
                    label,
                    lambda lang=language, tgt=target: self.new_source_document(
                        lang, target=tgt, use_template=True
                    ),
                    f"{label} mit der bisherigen Vorlage anlegen",
                )

            self.compact_new_legacy_actions = {
                "windows_pe32": (
                    language_action("Pascal-Programm", "pascal", "pe32"),
                    language_action("C-Programm", "c", "pe32"),
                    language_action("LISP-Programm", "lisp", "pe32"),
                ),
                "windows_pe64": (
                    language_action("Pascal-Programm", "pascal", "pe64"),
                    language_action("C-Programm", "c", "pe64"),
                    language_action("LISP-Programm", "lisp", "pe64"),
                ),
                "amiga500": (
                    language_action("Pascal-Programm", "pascal", "amiga"),
                    language_action("C-Programm", "c", "amiga"),
                    language_action("Assembler-Programm", "assembler", "amiga"),
                ),
                "c64": (
                    language_action("BASIC-Programm", "basic", "c64"),
                    language_action("Pascal-Programm", "pascal", "c64"),
                    language_action("C-Programm", "c", "c64"),
                    language_action("Assembler-Programm", "assembler", "c64"),
                ),
                "prolog": (),
                "logo": (),
                "dbase": (),
                "assembler": (),
            }

        def _populate_new_document_menu(self, menu: QMenu) -> QMenu:
            """Baut das kompakte Datei->Neu-Menü.

            Die frühere flache Liste aus Projekt- und Sprachaktionen bleibt
            funktional erhalten, wird aber nach Plattform/Sprache gruppiert.
            Jeder Hauptpunkt besitzt die drei einheitlichen Aktionen
            ``Projekt``, ``Anwendung`` und ``Programm``.  ``Anwendung`` erzeugt
            eine neue Quelldatei mit dem vorhandenen Template; ``Programm``
            erzeugt dieselbe Dateikategorie leer.
            """
            profile_specs = (
                ("windows_pe32", "Windows PE32"),
                ("windows_pe64", "Windows PE32+"),
                ("amiga500", "Amiga 500 ADF"),
                ("c64", "C= 64 mk68x"),
                ("prolog", "PROLOG"),
                ("logo", "LOGO"),
                ("dbase", "dBase"),
                ("assembler", "Assembler"),
            )
            self.compact_new_menus = {}
            for profile_key, title in profile_specs:
                submenu = menu.addMenu(title)
                submenu.setObjectName(f"new_{profile_key}_menu")
                actions = self.compact_new_actions[profile_key]
                submenu.addAction(actions["project"])
                submenu.addAction(actions["application"])
                submenu.addAction(actions["program"])
                if profile_key == "dbase":
                    submenu.addSeparator()
                    submenu.addAction(actions["form"])
                    submenu.addAction(actions["table"])
                    submenu.addAction(actions["sql_builder"])
                    submenu.addAction(actions["report"])
                    submenu.addAction(actions["labels"])

                legacy_actions = self.compact_new_legacy_actions.get(
                    profile_key, ()
                )
                if legacy_actions:
                    submenu.addSeparator()
                    for action in legacy_actions:
                        submenu.addAction(action)
                self.compact_new_menus[profile_key] = submenu

            # Alle übrigen bisherigen Einträge bleiben auf derselben Ebene.
            menu.addSeparator()
            menu.addAction(self.new_character_map_action)
            menu.addAction(self.new_text_screen_action)
            menu.addAction(self.new_pixel_screen_action)
            menu.addSeparator()
            menu.addAction(self.new_text_file_action)
            return menu

        def resource_dialog(self) -> None:
            res_window = ResourceBuilderToolWindow(self)
            res_window.exec_()
            return
            

        def _math_learning_dock_visibility_changed(self, visible: bool) -> None:
            """Blendet Dateisystem + zentrale Dokumentfläche zugunsten des Mathematik-Docks aus."""
            if visible:
                for dock_name in (
                    'prolog_knowledge_dock',
                    'localize_dock',
                    'doxygen_dock',
                ):
                    candidate = getattr(self, dock_name, None)
                    if (
                        candidate is not None
                        and candidate is not self.math_learning_dock
                        and candidate.isVisible()
                    ):
                        candidate.hide()

                if hasattr(self, 'left_dock') and self.left_dock.isVisible():
                    self._math_learning_replaced_filesystem_dock = True
                    self.left_dock.hide()

                central = self.centralWidget()
                if central is not None and central.isVisible():
                    self._math_learning_replaced_central_widget = True
                    central.hide()

                self._enforce_math_learning_height_limit()
                QTimer.singleShot(
                    0,
                    self._enforce_math_learning_height_limit,
                )
                QTimer.singleShot(
                    0,
                    self._expand_math_learning_dock,
                )
            else:
                if (
                    self._math_learning_replaced_filesystem_dock
                    and hasattr(self, 'left_dock')
                ):
                    self.left_dock.show()
                self._math_learning_replaced_filesystem_dock = False

                if self._math_learning_replaced_central_widget:
                    central = self.centralWidget()
                    if central is not None:
                        central.show()
                self._math_learning_replaced_central_widget = False

        def _math_learning_dock_top_level_changed(self, floating: bool) -> None:
            """Stage 151: Floating-Dock bleibt normal mit der Maus resizbar."""
            dock = getattr(self, 'math_learning_dock', None)
            widget = getattr(self, 'math_learning_widget', None)
            if dock is None:
                return

            # Floatable / Movable / Closable explizit beibehalten.
            dock.setFeatures(
                QDockWidget.DockWidgetMovable
                | QDockWidget.DockWidgetFloatable
                | QDockWidget.DockWidgetClosable
            )
            dock.setSizePolicy(
                QSizePolicy.Expanding,
                QSizePolicy.Expanding,
            )
            dock.setMaximumSize(
                16777215,
                self.MAX_MATH_DOCK_HEIGHT,
            )

            if widget is not None:
                widget.setSizePolicy(
                    QSizePolicy.Expanding,
                    QSizePolicy.Expanding,
                )
                widget.setMaximumSize(
                    16777215,
                    self.MAX_MATH_DOCK_HEIGHT,
                )

            if floating:
                # Eine echte Größen-Spanne statt FixedSize: der Benutzer
                # kann das freistehende Fenster an allen Rändern verändern.
                dock.setMinimumSize(
                    self.MIN_MATH_FLOATING_WIDTH,
                    self.MIN_MATH_FLOATING_HEIGHT,
                )
                if widget is not None:
                    widget.setMinimumSize(0, 0)

                # Nur dann eingreifen, wenn die 900-px-Grenze überschritten
                # wurde. Jede kleinere vom Benutzer gewählte Größe bleibt.
                if dock.height() > self.MAX_MATH_DOCK_HEIGHT:
                    dock.resize(
                        dock.width(),
                        self.MAX_MATH_DOCK_HEIGHT,
                    )
            else:
                # Angedockt darf Qt die verfügbare Dock-Fläche frei verteilen.
                dock.setMinimumSize(0, 0)
                if widget is not None:
                    widget.setMinimumSize(0, 0)

            QTimer.singleShot(
                0,
                self._enforce_math_learning_height_limit,
            )

        def _enforce_math_learning_height_limit(self) -> None:
            """Stage 151: Mathe-Dock max. 900 px, kleinere Floating-Größen bleiben unangetastet."""
            window_maximum = int(self.MAX_WINDOW_HEIGHT)
            math_maximum = int(self.MAX_MATH_DOCK_HEIGHT)

            # Hauptfenster behält seine eigene Obergrenze von 1000 Pixel.
            self.setMaximumHeight(window_maximum)

            if self.isMaximized() or self.isFullScreen():
                state = self.windowState()
                state &= ~Qt.WindowMaximized
                state &= ~Qt.WindowFullScreen
                self.setWindowState(state)

            if self.height() > window_maximum:
                self.resize(
                    self.width(),
                    window_maximum,
                )

            dock = getattr(self, 'math_learning_dock', None)
            if dock is not None:
                dock.setMaximumHeight(math_maximum)

                # Ein frei schwebendes Mathematik-Dock wird unmittelbar
                # auf maximal 900 Pixel Höhe begrenzt.
                if dock.isFloating() and dock.height() > math_maximum:
                    dock.resize(
                        dock.width(),
                        math_maximum,
                    )

            widget = getattr(self, 'math_learning_widget', None)
            if widget is not None:
                widget.setMaximumHeight(math_maximum)
                if widget.height() > math_maximum:
                    widget.resize(
                        widget.width(),
                        math_maximum,
                    )

        def _expand_math_learning_dock(self) -> None:
            dock = getattr(self, 'math_learning_dock', None)
            if dock is None or not dock.isVisible():
                return

            self._enforce_math_learning_height_limit()

            # Stage 151:
            # Bei einem freistehenden QDockWidget gehört die Fenstergröße
            # dem Benutzer. resizeDocks() darf sie nicht erneut vorgeben.
            if dock.isFloating():
                self._math_learning_dock_top_level_changed(True)
                self._assign_widget_property_ids(dock)
                return

            self.resizeDocks([dock], [100000], Qt.Horizontal)
            self.resizeDocks(
                [dock],
                [self.MAX_MATH_DOCK_HEIGHT],
                Qt.Vertical,
            )
            widget = getattr(self, 'math_learning_widget', None)
            if widget is not None:
                widget.setMinimumSize(0, 0)
                widget.setSizePolicy(
                    QSizePolicy.Expanding,
                    QSizePolicy.Expanding,
                )
                widget.updateGeometry()
            self._assign_widget_property_ids(dock)

        def _ensure_math_learning_dock(self):
            dock = getattr(self, 'math_learning_dock', None)
            widget = getattr(self, 'math_learning_widget', None)
            if dock is not None and widget is not None:
                return dock, widget

            dock = QDockWidget('Mathematik', self)
            dock.setObjectName('math_learning_dock')
            dock.setFeatures(self._dock_features())
            dock.setAllowedAreas(Qt.LeftDockWidgetArea | Qt.RightDockWidgetArea)
            dock.setMinimumSize(0, 0)
            dock.setMaximumSize(16777215, self.MAX_MATH_DOCK_HEIGHT)
            dock.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)

            widget = MathematicsLearningDockWidget(dock)
            widget.setMinimumSize(0, 0)
            widget.setMaximumSize(16777215, self.MAX_MATH_DOCK_HEIGHT)
            widget.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
            widget.set_dark_mode(self.dark_mode_enabled)
            dock.setWidget(widget)
            dock.hide()
            self.addDockWidget(Qt.LeftDockWidgetArea, dock)
            dock.visibilityChanged.connect(self._math_learning_dock_visibility_changed)
            dock.topLevelChanged.connect(
                self._math_learning_dock_top_level_changed
            )

            self.math_learning_dock = dock
            self.math_learning_widget = widget
            self._math_learning_dock_top_level_changed(
                dock.isFloating()
            )
            self._assign_widget_property_ids(dock)
            return dock, widget

        def show_math_learning_dock(
            self,
            _checked: bool = False,
            *,
            game_key: Optional[str] = None,
        ) -> None:
            dock, widget = self._ensure_math_learning_dock()

            if hasattr(self, 'left_dock'):
                if self.left_dock.isVisible():
                    self._math_learning_replaced_filesystem_dock = True
                self.left_dock.hide()

            # Stage 149: bereits VOR show() die maximale Fensterhöhe
            # erzwingen, damit Qt beim Einblenden des großen Dock-Inhalts
            # das Hauptfenster nicht über 1000 Pixel aufzieht.
            self._enforce_math_learning_height_limit()

            dock.show()
            dock.raise_()

            self._enforce_math_learning_height_limit()
            self._expand_math_learning_dock()

            # Nach dem ersten Layout-Pass nochmals begrenzen, weil QDockWidget
            # seine Geometrie beim show()/Dock-Layout verzögert aktualisiert.
            QTimer.singleShot(
                0,
                self._enforce_math_learning_height_limit,
            )
            QTimer.singleShot(
                0,
                self._expand_math_learning_dock,
            )

            if game_key:
                title = ''
                if game_key == 'numbers_wall_100':
                    title = 'Zahlenmauer bis 100'
                elif game_key == 'numbers_wall_1000':
                    title = 'Zahlenmauer bis 1000'
                elif game_key == 'memory_math':
                    title = 'Memory'
                widget.open_game(game_key, title)
            else:
                widget.left_tabs.setFocus(Qt.OtherFocusReason)
                widget.games_tree.setFocus(Qt.OtherFocusReason)
            self.statusBar().showMessage('Mathematik-Arbeitsfläche geöffnet')

        def _restore_music_workspace(self) -> None:
            if not getattr(self, '_music_workspace_active', False):
                return
            self._music_workspace_active = False

            instrument = getattr(self, 'music_instrument_widget', None)
            if instrument is not None:
                instrument.shutdown()

            instrument_dock = getattr(self, 'music_instrument_dock', None)
            if instrument_dock is not None and instrument_dock.isVisible():
                instrument_dock.hide()

            if self._music_workspace_replaced_central_widget:
                central = self.centralWidget()
                if central is not None:
                    central.show()
            self._music_workspace_replaced_central_widget = False

            saved = list(getattr(self, '_music_workspace_hidden_docks', []))
            self._music_workspace_hidden_docks = []
            for candidate in saved:
                try:
                    if candidate is not None:
                        candidate.show()
                except RuntimeError:
                    pass

        def _music_keyboard_dock_visibility_changed(self, visible: bool) -> None:
            """Stage 264: Musik + Instrument bilden einen exklusiven Dock-Arbeitsbereich."""
            if not visible:
                self._restore_music_workspace()

        def _prepare_music_workspace(self, music_dock, instrument_dock) -> None:
            """Alle bisherigen Docks schließen und den Central-Editor freigeben."""
            if not self._music_workspace_active:
                self._music_workspace_hidden_docks = []
                for candidate in self.findChildren(QDockWidget):
                    if candidate in (music_dock, instrument_dock):
                        continue
                    if candidate.isVisible():
                        self._music_workspace_hidden_docks.append(candidate)

                # Zuerst Tool-Docks schließen. left_dock kommt absichtlich zuletzt,
                # weil Visibility-Handler anderer Arbeitsbereiche es ggf. wieder zeigen.
                left = getattr(self, 'left_dock', None)
                for candidate in list(self._music_workspace_hidden_docks):
                    if candidate is left:
                        continue
                    try:
                        candidate.close()
                    except RuntimeError:
                        pass
                if left is not None and left.isVisible():
                    left.close()

                # Nach eventgetriebenen Restore-Handlern nochmals jeden Fremd-Dock
                # sicher schließen. Damit ist vor Musik.show() garantiert alles weg.
                for candidate in self.findChildren(QDockWidget):
                    if candidate in (music_dock, instrument_dock):
                        continue
                    if candidate.isVisible():
                        candidate.hide()

                central = self.centralWidget()
                self._music_workspace_replaced_central_widget = bool(
                    central is not None and central.isVisible()
                )
                if self._music_workspace_replaced_central_widget:
                    central.hide()

                self._music_workspace_active = True

        def _expand_music_workspace(self) -> None:
            music = getattr(self, 'music_keyboard_dock', None)
            instrument = getattr(self, 'music_instrument_dock', None)
            if music is None or instrument is None:
                return
            if not music.isVisible() or not instrument.isVisible():
                return

            # Instrument bleibt kompakt rechts. Musik erhält exakt den Rest.
            instrument_width = max(340, min(410, int(self.width() * 0.23)))
            music_width = max(680, self.width() - instrument_width)
            try:
                self.resizeDocks(
                    [music, instrument],
                    [music_width, instrument_width],
                    Qt.Horizontal,
                )
                self.resizeDocks(
                    [music, instrument],
                    [max(520, self.height() - 80), max(520, self.height() - 80)],
                    Qt.Vertical,
                )
            except Exception:
                pass

        def _ensure_music_keyboard_dock(self):
            dock = getattr(self, 'music_keyboard_dock', None)
            widget = getattr(self, 'music_keyboard_widget', None)
            instrument_dock = getattr(self, 'music_instrument_dock', None)
            instrument_widget = getattr(self, 'music_instrument_widget', None)
            if (
                dock is not None and widget is not None
                and instrument_dock is not None and instrument_widget is not None
            ):
                return dock, widget, instrument_dock, instrument_widget

            dock = QDockWidget('Musik - Keyboard', self)
            dock.setObjectName('music_keyboard_dock')
            dock.setFeatures(self._dock_features())
            dock.setAllowedAreas(Qt.LeftDockWidgetArea | Qt.RightDockWidgetArea)
            dock.setMinimumSize(680, 440)
            dock.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)

            widget = MusicKeyboardDockWidget(dock)
            widget.set_dark_mode(self.dark_mode_enabled)
            dock.setWidget(widget)
            dock.hide()
            self.addDockWidget(Qt.LeftDockWidgetArea, dock)

            instrument_dock = QDockWidget('Instrument', self)
            instrument_dock.setObjectName('music_instrument_dock')
            instrument_dock.setFeatures(self._dock_features())
            instrument_dock.setAllowedAreas(Qt.RightDockWidgetArea)
            instrument_dock.setMinimumWidth(340)
            instrument_dock.setMaximumWidth(430)
            instrument_dock.setMinimumHeight(440)
            instrument_widget = InstrumentDockWidget(widget, instrument_dock)
            instrument_widget.set_dark_mode(self.dark_mode_enabled)
            instrument_dock.setWidget(instrument_widget)
            instrument_dock.hide()
            self.addDockWidget(Qt.RightDockWidgetArea, instrument_dock)

            dock.visibilityChanged.connect(
                self._music_keyboard_dock_visibility_changed
            )

            self.music_keyboard_dock = dock
            self.music_keyboard_widget = widget
            self.music_instrument_dock = instrument_dock
            self.music_instrument_widget = instrument_widget
            self._assign_widget_property_ids(dock)
            self._assign_widget_property_ids(instrument_dock)
            return dock, widget, instrument_dock, instrument_widget

        def show_music_keyboard_dock(self, _checked: bool = False) -> None:
            """Lernen -> Keyboard: nur Musik links/zentral und Instrument rechts."""
            dock, widget, instrument_dock, instrument_widget = (
                self._ensure_music_keyboard_dock()
            )

            # MUSS vollständig vor show() passieren.
            self._prepare_music_workspace(dock, instrument_dock)

            # Falls beide Docks bereits irgendwo umgeordnet waren, ihre Bereiche
            # vor dem Anzeigen wieder eindeutig herstellen.
            if not dock.isFloating():
                self.addDockWidget(Qt.LeftDockWidgetArea, dock)
            if not instrument_dock.isFloating():
                self.addDockWidget(Qt.RightDockWidgetArea, instrument_dock)

            instrument_dock.show()
            instrument_dock.raise_()
            dock.show()
            dock.raise_()

            QTimer.singleShot(0, self._expand_music_workspace)
            QTimer.singleShot(60, self._expand_music_workspace)

            widget.tabs.setCurrentIndex(0)
            widget.staff_canvas.setFocus(Qt.OtherFocusReason)
            self._assign_widget_property_ids(dock)
            self._assign_widget_property_ids(instrument_dock)
            self.statusBar().showMessage(
                'Musik - Keyboard geöffnet • Instrument rechts • übriger Platz vollständig Musik'
            )

        def _localize_dock_visibility_changed(self, visible: bool) -> None:
            """Replace the normal work area while Localize PO/MO is visible.

            Stage 80 mirrors the knowledge-browser docking behaviour: the
            filesystem dock and the central document tabs are hidden so the
            Localize dock can consume the complete free QMainWindow area.
            Right/bottom docks remain managed by Qt and are therefore still
            available when visible.
            """
            if visible:
                # Only one large left-side tool occupies this workspace at a
                # time.  If the PROLOG knowledge browser is open, hide it
                # first; its visibility handler may briefly restore the file
                # dock/central widget, which are hidden again below.
                knowledge_dock = getattr(self, "prolog_knowledge_dock", None)
                if knowledge_dock is not None and knowledge_dock.isVisible():
                    knowledge_dock.hide()

                if hasattr(self, "left_dock") and self.left_dock.isVisible():
                    self._localize_replaced_filesystem_dock = True
                    self.left_dock.hide()

                central = self.centralWidget()
                if central is not None and central.isVisible():
                    self._localize_replaced_central_widget = True
                    central.hide()

                QTimer.singleShot(0, self._expand_localize_dock)
            else:
                tool = getattr(self, "localize_tool_window", None)
                if tool is not None:
                    try:
                        tool._save_state()
                    except Exception:
                        pass

                if (
                    self._localize_replaced_filesystem_dock
                    and hasattr(self, "left_dock")
                ):
                    self.left_dock.show()
                self._localize_replaced_filesystem_dock = False

                if self._localize_replaced_central_widget:
                    central = self.centralWidget()
                    if central is not None:
                        central.show()
                self._localize_replaced_central_widget = False

        def _expand_localize_dock(self) -> None:
            dock = getattr(self, "localize_dock", None)
            if dock is None or not dock.isVisible():
                return

            # With the central widget hidden, a deliberately huge requested
            # size makes Qt give Localize every remaining pixel while still
            # respecting any visible right/bottom docks.
            self.resizeDocks([dock], [100000], Qt.Horizontal)
            self.resizeDocks([dock], [100000], Qt.Vertical)
            tool = getattr(self, "localize_tool_window", None)
            if tool is not None:
                tool.setMinimumSize(0, 0)
                tool.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
                tool.updateGeometry()
            self._assign_widget_property_ids(dock)

        def _ensure_localize_dock(self):
            dock = getattr(self, "localize_dock", None)
            tool = getattr(self, "localize_tool_window", None)
            if dock is not None and tool is not None:
                return dock, tool

            dock = QDockWidget("Localize PO/MO", self)
            dock.setObjectName("localize_po_mo_dock")
            dock.setFeatures(self._dock_features())
            dock.setAllowedAreas(Qt.LeftDockWidgetArea | Qt.RightDockWidgetArea)
            dock.setMinimumWidth(0)
            dock.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)

            tool = LocalizeToolWindow(self, dock, embedded=True)
            tool.dock_close_requested.connect(dock.hide)
            dock.setWidget(tool)
            # Keep the lazily created dock hidden until localize_dialog()
            # explicitly replaces the filesystem view.
            dock.hide()
            self.addDockWidget(Qt.LeftDockWidgetArea, dock)
            dock.visibilityChanged.connect(self._localize_dock_visibility_changed)

            self.localize_dock = dock
            self.localize_tool_window = tool
            self._assign_widget_property_ids(dock)
            return dock, tool

        def localize_dialog(self) -> None:
            dock, tool = self._ensure_localize_dock()

            # Replace the left filesystem view, as requested.
            if hasattr(self, "left_dock"):
                if self.left_dock.isVisible():
                    self._localize_replaced_filesystem_dock = True
                self.left_dock.hide()

            dock.show()
            dock.raise_()
            self._expand_localize_dock()
            QTimer.singleShot(0, self._expand_localize_dock)
            try:
                tool.tabs.setFocus(Qt.OtherFocusReason)
            except Exception:
                tool.setFocus(Qt.OtherFocusReason)
            return
            
        def _doxygen_dock_visibility_changed(self, visible: bool) -> None:
            """Stage 115: Doxygen belegt den freien Platz links vom Projekt-Dock.

            Das Dateisystem wird zuerst ausgeblendet. Danach wird die zentrale
            Dokumentfläche verborgen, damit QMainWindow den kompletten freien
            Bereich dem Doxygen-Dock geben kann. Projekt/Informationen und das
            untere Protokoll-Dock bleiben von dieser Umschaltung unberührt.
            """
            if visible:
                # Nur ein großflächiges Werkzeug soll die Arbeitsfläche belegen.
                # Deren Hide-Handler können Dateisystem/Zentralfläche kurz
                # wiederherstellen; deshalb werden diese anschließend nochmals
                # verbindlich ausgeblendet.
                for other_name in ("localize_dock", "prolog_knowledge_dock"):
                    other = getattr(self, other_name, None)
                    if other is not None and other is not self.doxygen_dock and other.isVisible():
                        other.hide()

                # Vorgabe: Dateisystem-Dock ZUERST ausblenden.
                left = getattr(self, "left_dock", None)
                if left is not None and left.isVisible():
                    self._doxygen_replaced_filesystem_dock = True
                    left.hide()

                central = self.centralWidget()
                if central is not None and central.isVisible():
                    self._doxygen_replaced_central_widget = True
                    central.hide()

                # Das Projekt-/Informations-Dock soll rechts bestehen bleiben.
                right = getattr(self, "right_dock", None)
                if right is not None and not right.isVisible():
                    right.show()

                QTimer.singleShot(0, self._expand_doxygen_dock)
            else:
                if (
                    self._doxygen_replaced_filesystem_dock
                    and hasattr(self, "left_dock")
                ):
                    self.left_dock.show()
                self._doxygen_replaced_filesystem_dock = False

                if self._doxygen_replaced_central_widget:
                    central = self.centralWidget()
                    if central is not None:
                        central.show()
                self._doxygen_replaced_central_widget = False

        def _expand_doxygen_dock(self) -> None:
            """Gibt Doxygen jeden freien Pixel links vom rechten Projekt-Dock."""
            dock = getattr(self, "doxygen_dock", None)
            if dock is None or not dock.isVisible():
                return

            # Doxygen gehört in die linke Dock-Area. Bei verborgener zentraler
            # Fläche reicht diese Area bis direkt an das rechte Projekt-Dock.
            self.addDockWidget(Qt.LeftDockWidgetArea, dock)
            self.resizeDocks([dock], [100000], Qt.Horizontal)
            self.resizeDocks([dock], [100000], Qt.Vertical)

            tool = getattr(self, "doxygen_tool_window", None)
            if tool is not None:
                try:
                    tool.setMinimumSize(0, 0)
                    tool.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
                    tool.updateGeometry()
                except Exception:
                    pass
            self._assign_widget_property_ids(dock)

        def _ensure_doxygen_dock(self):
            """Erzeugt das Doxygen-Werkzeug einmalig als echtes QDockWidget.

            Die eigentliche Oberfläche bleibt in doxygen.py. Der Import erfolgt
            absichtlich erst beim Öffnen des Werkzeugs, damit optionale
            Doxygen-/ANTLR-/QtWebEngine-Abhängigkeiten den Programmstart nicht
            beeinträchtigen.
            """
            dock = getattr(self, "doxygen_dock", None)
            tool = getattr(self, "doxygen_tool_window", None)
            if dock is not None and tool is not None:
                return dock, tool

            try:
                import importlib.util

                source_path = Path(__file__).resolve().with_name("doxygen.py")
                if not source_path.is_file():
                    raise FileNotFoundError(
                        f"Doxygen-Modul nicht gefunden: {source_path}"
                    )

                module_name = "_d64_doxygen_tool"
                module = sys.modules.get(module_name)
                if module is None:
                    spec = importlib.util.spec_from_file_location(
                        module_name,
                        str(source_path),
                    )
                    if spec is None or spec.loader is None:
                        raise ImportError(
                            f"Doxygen-Modul kann nicht geladen werden: {source_path}"
                        )
                    module = importlib.util.module_from_spec(spec)
                    # Stage 116 additive preload: import-time Doxygen MessageBoxes
                    # already know the host theme before module execution starts.
                    module._DOXYGEN_PRELOAD_THEME_HOST = self
                    sys.modules[module_name] = module
                    try:
                        spec.loader.exec_module(module)
                    except Exception:
                        sys.modules.pop(module_name, None)
                        raise

                # Stage 116 additive extension supplied by doxygen.py.
                install_theme = getattr(module, "install_doxygen_messagebox_theme", None)
                if callable(install_theme):
                    install_theme(self)

                tool_class = getattr(module, "DoxyGenToolWindow", None)
                if tool_class is None:
                    raise ImportError(
                        "doxygen.py enthält keine Klasse DoxyGenToolWindow."
                    )

                dock = QDockWidget("Doxygen Dokumentation", self)
                dock.setObjectName("doxygen_documentation_dock")
                dock.setFeatures(self._dock_features())
                dock.setAllowedAreas(Qt.AllDockWidgetAreas)
                dock.setMinimumSize(0, 0)
                dock.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)

                # DoxyGenToolWindow ist in der gelieferten Datei bereits ein
                # QWidget. Dadurch kann die komplette bestehende Oberfläche
                # ohne Kopie oder Dialog-Wrapper direkt in das Dock wandern.
                tool = tool_class(dock)
                try:
                    tool.setObjectName("doxygen_documentation_tool")
                    tool.setMinimumSize(0, 0)
                    tool.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
                except Exception:
                    pass

                dock.setWidget(tool)
                # Stage 115: Doxygen gehört links vom Projekt-Dock. Die genaue
                # Großflächen-Anordnung erfolgt beim Sichtbarwerden, nachdem das
                # Dateisystem zuerst ausgeblendet wurde.
                self.addDockWidget(Qt.LeftDockWidgetArea, dock)
                dock.hide()

                self.doxygen_dock = dock
                self.doxygen_tool_window = tool
                dock.visibilityChanged.connect(
                    self._doxygen_dock_visibility_changed
                )
                self._assign_widget_property_ids(dock)
                return dock, tool

            except Exception as exc:
                self.doxygen_dock = None
                self.doxygen_tool_window = None
                # Stage 114: Auch der Doxygen-Importfehler benutzt die zentrale
                # thematisierte MessageBox. Direkte QMessageBox.critical()-Aufrufe
                # koennen unter dem nativen Windows/Qt5-Style im Dark-Mode einen
                # hellen bzw. unlesbaren Text-/Hintergrund-Mix erzeugen.
                self._show_message_box(
                    QMessageBox.Critical,
                    "Doxygen",
                    "Das Doxygen-Docking-Fenster konnte nicht geöffnet werden.\n\n"
                    + str(exc),
                )
                return None, None

        def show_doxygen_dock(self, _checked: bool = False) -> None:
            """Öffnet Doxygen links vom Projekt-Dock auf maximaler Fläche."""
            dock, tool = self._ensure_doxygen_dock()
            if dock is None or tool is None:
                return

            # Vorgabe: Das Dateisystem muss bereits verschwunden sein, bevor
            # Doxygen eingeblendet und in seinen Platz eingesetzt wird.
            left = getattr(self, "left_dock", None)
            if left is not None and left.isVisible():
                self._doxygen_replaced_filesystem_dock = True
                left.hide()

            # Falls ein anderes Großflächen-Dock aktiv ist, zuerst schließen.
            # Dessen Visibility-Handler darf danach die normale Arbeitsfläche
            # restaurieren; wir blenden sie direkt vor Doxygen wieder aus.
            for other_name in ("localize_dock", "prolog_knowledge_dock"):
                other = getattr(self, other_name, None)
                if other is not None and other is not dock and other.isVisible():
                    other.hide()

            left = getattr(self, "left_dock", None)
            if left is not None and left.isVisible():
                self._doxygen_replaced_filesystem_dock = True
                left.hide()

            central = self.centralWidget()
            if central is not None and central.isVisible():
                self._doxygen_replaced_central_widget = True
                central.hide()

            right = getattr(self, "right_dock", None)
            if right is not None and not right.isVisible():
                right.show()

            self.addDockWidget(Qt.LeftDockWidgetArea, dock)
            dock.show()
            dock.raise_()
            self._expand_doxygen_dock()
            QTimer.singleShot(0, self._expand_doxygen_dock)

            try:
                tool.setFocus(Qt.OtherFocusReason)
            except Exception:
                pass
            self.statusBar().showMessage(
                "Doxygen-Docking-Fenster links neben Projekt geöffnet"
            )

        def create_coff32_archive_dialog(self) -> None:
            filenames, _selected = QFileDialog.getOpenFileNames(
                self,
                "COFF32-Objektdateien auswählen",
                str(self.current_directory),
                "COFF32-Objekte (*.o *.obj);;Alle Dateien (*)",
            )
            if not filenames:
                return
            target_name, _selected = QFileDialog.getSaveFileName(
                self,
                "COFF32-Archiv speichern",
                str(self.current_directory / "library.a"),
                "Statisches Archiv (*.a);;Alle Dateien (*)",
            )
            if not target_name:
                return
            target = Path(target_name)
            if not target.suffix:
                target = target.with_suffix(".a")
            try:
                members = [(Path(name).name, Path(name).read_bytes()) for name in filenames]
                target.write_bytes(create_coff32_archive(members))
            except (OSError, PE32AssemblerError) as exc:
                self.show_error("COFF32-Archiv fehlgeschlagen", str(exc))
                return
            self.log(f"COFF32 ARCHIVE: {len(filenames)} Objekt(e) -> {target}")
            self.statusBar().showMessage(f"COFF32-Archiv erzeugt: {target.name}")
            if target.parent.resolve() == self.current_directory:
                self.populate_file_list()

        def link_pe32_dialog(self) -> None:
            filenames, _selected = QFileDialog.getOpenFileNames(
                self,
                "COFF32-Objekte/Archive linken",
                str(self.current_directory),
                "COFF32 (*.o *.obj *.a *.lib);;Alle Dateien (*)",
            )
            if not filenames:
                return
            target_name, selected_filter = QFileDialog.getSaveFileName(
                self,
                "Windows-PE32 EXE/DLL speichern",
                str(self.current_directory / "program.exe"),
                "Windows PE32 EXE (*.exe);;Windows PE32 DLL (*.dll);;Alle Dateien (*)",
            )
            if not target_name:
                return
            target = Path(target_name)
            if not target.suffix:
                target = target.with_suffix(
                    ".dll" if "DLL" in selected_filter else ".exe"
                )
            is_dll = target.suffix.casefold() == ".dll"
            try:
                program = link_coff32_inputs(
                    [Path(name) for name in filenames],
                    entry_symbol="__d64_dll_entry" if is_dll else "_start",
                    gui=True,
                    dll=is_dll,
                    dll_name=target.name if is_dll else None,
                )
                target.write_bytes(program.executable)
            except (OSError, PE32AssemblerError) as exc:
                self.show_error("PE32-Linkerfehler", str(exc))
                return
            self.log(
                f"PE32 LINK: {len(filenames)} Eingabe(n) -> {target}, "
                f"{len(program.executable)} Bytes"
            )
            self.statusBar().showMessage(f"PE32-Programm gelinkt: {target.name}")
            if target.parent.resolve() == self.current_directory:
                self.populate_file_list()

        def create_coff64_archive_dialog(self) -> None:
            filenames, _selected = QFileDialog.getOpenFileNames(
                self, "COFF64-Objektdateien auswählen", str(self.current_directory),
                "AMD64 COFF64-Objekte (*.o *.obj);;Alle Dateien (*)",
            )
            if not filenames:
                return
            target_name, _selected = QFileDialog.getSaveFileName(
                self, "COFF64-Archiv speichern", str(self.current_directory / "library64.a"),
                "Statisches Archiv (*.a);;Alle Dateien (*)",
            )
            if not target_name:
                return
            target=Path(target_name)
            if not target.suffix:
                target=target.with_suffix(".a")
            try:
                members=[(Path(name).name,Path(name).read_bytes()) for name in filenames]
                # Vor dem Archivieren sicherstellen, dass keine i386-Objekte
                # versehentlich in ein PE64-Archiv geraten.
                for _name,data in members:
                    parse_coff64_object(data)
                target.write_bytes(create_coff64_archive(members))
            except (OSError,PE64AssemblerError) as exc:
                self.show_error("COFF64-Archiv fehlgeschlagen",str(exc)); return
            self.log(f"COFF64 ARCHIVE: {len(filenames)} Objekt(e) -> {target}")
            self.statusBar().showMessage(f"COFF64-Archiv erzeugt: {target.name}")
            if target.parent.resolve()==self.current_directory:
                self.populate_file_list()

