        def set_project_windows_search_paths(
            self,
            target: str,
            paths: Iterable[Path | str],
            *,
            mark_modified: bool = True,
        ) -> None:
            target_key = self._project_windows_target_key(target)
            # Reihenfolge absichtlich nicht sortieren: die ListBox-Reihenfolge
            # ist die Suchprioritaet fuer genau diese Zielarchitektur.
            normalized: List[str] = []
            seen = set()
            for value in paths or ():
                text = str(value).strip()
                if not text:
                    continue
                try:
                    path = Path(self._project_windows_absolute_directory(text))
                except (OSError, RuntimeError, ValueError):
                    path = Path(text).expanduser().absolute()
                key = str(path).casefold()
                if key in seen:
                    continue
                seen.add(key)
                normalized.append(str(path))
            current = list(self.project_windows_search_paths.get(target_key, ()))
            changed = normalized != current
            self.project_windows_search_paths[target_key] = normalized
            panel = getattr(self, "project_settings_panel", None)
            if panel is not None and tuple(panel.paths(target_key)) != tuple(normalized):
                panel.set_paths(target_key, normalized)
            if changed and mark_modified:
                self.set_project_modified(True)
                if self.current_project_path is not None:
                    self.save_project()

        def set_project_windows_output_directory(
            self,
            target: str,
            value: Optional[Path | str],
            *,
            mark_modified: bool = True,
        ) -> None:
            target_key = self._project_windows_target_key(target)
            text = str(value or "").strip()
            normalized = ""
            if text:
                normalized = self._project_windows_absolute_directory(text)
            current = str(
                self.project_windows_output_directories.get(target_key, "") or ""
            )
            changed = normalized != current
            self.project_windows_output_directories[target_key] = normalized
            panel = getattr(self, "project_settings_panel", None)
            if (
                panel is not None
                and panel.output_directory(target_key) != normalized
            ):
                panel.set_output_directory(target_key, normalized)
            if changed and mark_modified:
                self.set_project_modified(True)
                if self.current_project_path is not None:
                    self.save_project()

        def _project_windows_link_search_paths(
            self,
            target: str,
        ) -> Tuple[Path, ...]:
            target_key = self._project_windows_target_key(target)
            result: List[Path] = []
            for value in self.project_windows_search_paths.get(target_key, ()):
                try:
                    path = Path(value).expanduser().resolve()
                except (OSError, RuntimeError, ValueError):
                    path = Path(value).expanduser().absolute()
                if path not in result:
                    result.append(path)
            return tuple(result)

        def _project_windows_ordinal_search_paths(
            self,
            document: DocumentEditor,
        ) -> Tuple[Path, ...]:
            candidates: List[Path] = []
            if document.path is not None:
                candidates.append(Path(document.path).expanduser().resolve().parent)
            output = self._document_windows_output_path(document)
            if output is not None:
                candidates.append(output)
            candidates.append(self._project_windows_base_directory())
            candidates.extend(
                self._project_windows_link_search_paths(document.build_target)
            )
            result: List[Path] = []
            seen = set()
            for candidate in candidates:
                try:
                    path = Path(candidate).expanduser().resolve()
                except (OSError, RuntimeError, ValueError):
                    path = Path(candidate).expanduser().absolute()
                key = str(path).casefold()
                if key not in seen:
                    seen.add(key)
                    result.append(path)
            return tuple(result)

        def _apply_project_ordinal_imports(self, document, generated):
            target = self._project_windows_target_key(document.build_target)
            enabled = bool(
                self.project_windows_link_with_ordinals.get(target, False)
            )
            if document.build_target not in {"pe32", "pe64"} or not enabled:
                return generated
            search_paths = self._project_windows_ordinal_search_paths(document)
            assembly = rewrite_pe_assembly_imports_to_ordinals(
                generated.assembly,
                target=target,
                search_paths=search_paths,
                require_all=True,
            )
            changes = {"assembly": assembly}
            linked_modules = tuple(
                getattr(generated, "linked_pe32_modules", ()) or ()
            )
            if linked_modules:
                changes["linked_pe32_modules"] = tuple(
                    (
                        module_name,
                        rewrite_pe_assembly_imports_to_ordinals(
                            str(module_assembly),
                            target=target,
                            search_paths=search_paths,
                            require_all=True,
                        ),
                    )
                    for module_name, module_assembly in linked_modules
                )
            return replace(generated, **changes)

        def _project_windows_output_path(
            self,
            target: str,
        ) -> Optional[Path]:
            target_key = self._project_windows_target_key(target)
            value = str(
                self.project_windows_output_directories.get(target_key, "") or ""
            ).strip()
            if not value:
                return None
            try:
                path = Path(value).expanduser().resolve()
            except (OSError, RuntimeError, ValueError):
                path = Path(value).expanduser().absolute()
            return path

        def _document_windows_output_path(
            self,
            document: DocumentEditor,
        ) -> Optional[Path]:
            override = getattr(
                document, "project_tree_compile_output_directory", None
            )
            if override:
                try:
                    return Path(override).expanduser().resolve()
                except (OSError, RuntimeError, ValueError):
                    return Path(override).expanduser().absolute()
            return self._project_windows_output_path(document.build_target)

        def _project_generated_object_path(
            self,
            source_path: Path,
            target: str,
            output_directory: Optional[Path] = None,
        ) -> Path:
            source = Path(source_path).expanduser().resolve()
            output = (
                Path(output_directory).expanduser().resolve()
                if output_directory is not None
                else self._project_windows_output_path(target)
            )
            return (
                (output / source.with_suffix(".o").name).resolve()
                if output is not None
                else source.with_suffix(".o").resolve()
            )

        def _resolve_project_link_input(
            self,
            value: Path | str,
            *,
            source_path: Optional[Path] = None,
            target: str = "pe32",
        ) -> Path:
            candidate = Path(value).expanduser()
            if candidate.is_file():
                return candidate.resolve()
            candidates: List[Path] = []
            if candidate.is_absolute():
                candidates.append(candidate)
                leaf = Path(candidate.name)
            else:
                leaf = candidate
                if source_path is not None:
                    candidates.append(
                        Path(source_path).expanduser().resolve().parent / candidate
                    )
                if self.current_project_path is not None:
                    candidates.append(self.current_project_path.parent / candidate)
            # Die Reihenfolge der aktiven 32-/64-Bit-ListBox wird 1:1
            # eingehalten; die andere Architektur wird niemals durchsucht.
            for directory in self._project_windows_link_search_paths(target):
                candidates.append(directory / leaf)
            for path in candidates:
                if path.is_file():
                    return path.resolve()
            try:
                return candidate.resolve()
            except (OSError, RuntimeError):
                return candidate.absolute()

        def _create_language_menu(self) -> None:
            """Stage 167: Ansicht->Sprache mit 68 Einträgen in 4 Spalten."""
            self.language_menu = self.view_menu.addMenu("Sprache")
            self.language_menu.setObjectName("language_menu")

            host = QWidget(self.language_menu)
            host.setObjectName("language_menu_grid")
            grid = QGridLayout(host)
            grid.setContentsMargins(6, 5, 6, 5)
            grid.setHorizontalSpacing(10)
            grid.setVerticalSpacing(0)

            self.language_button_group = QButtonGroup(self.language_menu)
            self.language_button_group.setExclusive(True)
            self.language_menu_entries = {}

            # LANGUAGE_CODES ist die alleinige Datenquelle. Bei 68 Einträgen
            # entstehen 17 Zeilen mit jeweils vier Spalten. Die Reihenfolge
            # bleibt exakt die Reihenfolge der Konstantenliste.
            column_count = 4
            for index, (code, title, flag_path) in enumerate(LANGUAGE_CODES):
                row = index // column_count
                column = index % column_count
                entry = LanguageMenuChoice(
                    code,
                    title,
                    flag_path,
                    host,
                )
                entry.selected.connect(self._select_ui_language)
                self.language_button_group.addButton(entry.radio)
                self.language_menu_entries[str(code).upper()] = entry
                grid.addWidget(entry, row, column)

            for column in range(column_count):
                grid.setColumnStretch(column, 1)

            self.language_menu_action = QWidgetAction(self.language_menu)
            self.language_menu_action.setObjectName("language_menu_grid_action")
            self.language_menu_action.setDefaultWidget(host)
            self.language_menu.addAction(self.language_menu_action)
            self.language_menu.aboutToShow.connect(
                self._sync_ui_language_menu_selection
            )
            self._sync_ui_language_menu_selection()

        def _sync_ui_language_menu_selection(self) -> None:
            entry = self.language_menu_entries.get(self.ui_language_code)
            if entry is None:
                entry = self.language_menu_entries.get("DEU")
            if entry is not None and not entry.radio.isChecked():
                blocker = entry.radio.blockSignals(True)
                entry.radio.setChecked(True)
                entry.radio.blockSignals(blocker)

        def _select_ui_language(self, code: str) -> None:
            normalized = str(code).strip().upper()
            entry = self.language_menu_entries.get(normalized)
            if entry is None:
                return

            self.ui_language_code = normalized
            self.settings.setValue("view/language_code", normalized)
            self.settings.sync()
            self.statusBar().showMessage(
                f"Sprache: {normalized} - {entry.title}"
            )

            # Das eingebettete QWidgetAction schließt QMenu nicht automatisch.
            # Nach einer Auswahl verhalten wir uns deshalb wie ein normales
            # Submenü und schließen die Menükette explizit.
            if self.language_menu is not None:
                self.language_menu.close()
            if getattr(self, "view_menu", None) is not None:
                self.view_menu.close()

