        def _apply_message_box_theme(self, dialog: QMessageBox) -> QMessageBox:
            """Apply the active dark/light colors to every save/close prompt."""
            dialog.setObjectName("themed_message_box")
            dialog.setAttribute(Qt.WA_StyledBackground, True)
            dialog.setAutoFillBackground(True)
            dialog.setPalette(self._message_box_palette())
            dialog.setStyleSheet(self._message_box_stylesheet())
            # Child labels can otherwise retain a native Windows palette in
            # some Qt5 styles. Set their palette explicitly as well.
            for child in dialog.findChildren(QWidget):
                child.setPalette(dialog.palette())
            return dialog

        def _create_message_box(
            self,
            icon,
            title: str,
            text: str,
            *,
            buttons=QMessageBox.Ok,
            default_button=QMessageBox.NoButton,
            rich_text: bool = False,
        ) -> QMessageBox:
            """Erzeugt eine garantiert zum aktuellen Modus passende MessageBox."""
            dialog = QMessageBox(self)
            dialog.setWindowIcon(self.windowIcon())
            dialog.setWindowTitle(title)
            dialog.setIcon(icon)
            dialog.setTextFormat(Qt.RichText if rich_text else Qt.PlainText)
            dialog.setText(text)
            dialog.setStandardButtons(buttons)
            if default_button != QMessageBox.NoButton:
                dialog.setDefaultButton(default_button)

            self._apply_message_box_theme(dialog)
            return dialog

        def _show_message_box(self, icon, title: str, text: str, **options):
            dialog = self._create_message_box(icon, title, text, **options)
            return dialog.exec_()

        def _apply_application_theme(self, enabled: bool) -> None:
            application = QApplication.instance()
            if enabled:
                application.setPalette(self._dark_application_palette())
                dark_stylesheet = self._dark_application_stylesheet()
                if self.light_application_stylesheet:
                    dark_stylesheet = (
                        self.light_application_stylesheet
                        + "\n"
                        + dark_stylesheet
                    )
                application.setStyleSheet(dark_stylesheet)
            else:
                application.setPalette(self.light_application_palette)
                application.setStyleSheet(self.light_application_stylesheet)

            # QApplication verteilt den Palettenwechsel an alle vorhandenen
            # Widgets. update() sorgt zusaetzlich dafuer, dass auch Dock-Titel
            # und bereits sichtbare Item-Views sofort neu gezeichnet werden.
            if hasattr(self, "project_tree"):
                self.project_tree.setStyleSheet(
                    self._project_tree_checkbox_stylesheet()
                )

            for widget in application.allWidgets():
                widget.update()
                if isinstance(widget, ChmViewerDialog):
                    widget.set_dark_mode(enabled)
                elif isinstance(widget, PrologKnowledgeDialog):
                    widget.set_dark_mode(enabled)
                elif isinstance(widget, DBaseTableDesignerWidget):
                    widget.set_dark_mode(enabled)
                elif isinstance(widget, DBaseLabelDesignerWidget):
                    widget.set_dark_mode(enabled)
                elif isinstance(widget, DBaseFormPropertyPanel):
                    widget.set_dark_mode(enabled)
                elif isinstance(widget, MathematicsLearningDockWidget):
                    widget.set_dark_mode(enabled)
                elif isinstance(widget, MusicKeyboardDockWidget):
                    widget.set_dark_mode(enabled)
                elif isinstance(widget, InstrumentDockWidget):
                    widget.set_dark_mode(enabled)
                elif isinstance(widget, DockTitleBar):
                    widget.set_dark_mode(enabled)
                elif isinstance(widget, DockSnapOverlay):
                    widget.set_dark_mode(enabled)

            project_settings_panel = getattr(self, "project_settings_panel", None)
            if project_settings_panel is not None:
                project_settings_panel.set_dark_mode(enabled)

            # Stage 161: die WFM-Quellstruktur ist ein normales QTreeWidget
            # und besitzt deshalb einen eigenen Dark-/Light-Mode-Stil.
            self._apply_dbase_form_source_outline_theme(enabled)

            # Stage 162: der nicht-modale Suchdialog bleibt ebenfalls
            # synchron zum aktuellen Dark-/Light-Mode.
            if self.source_find_dialog is not None:
                self.source_find_dialog.set_dark_mode(enabled)

            # Stage 76: der Titelverlauf bleibt als Markenfarbe erhalten;
            # die Menueleiste wird nach dem globalen Theme-Wechsel erneut
            # angewendet, damit Dark=navy/gelb und Light=beige/schwarz gilt.
            self._apply_green_beige_chrome_style()

        def toggle_editor_theme(self) -> None:
            self.dark_mode_enabled = not self.dark_mode_enabled
            self._apply_application_theme(self.dark_mode_enabled)
            for document in self._documents():
                document.set_dark_mode(self.dark_mode_enabled)
            if self.dbase_sql_builder_widget is not None:
                self.dbase_sql_builder_widget.set_dark_mode(
                    self.dark_mode_enabled
                )

            self.chm_viewer_action.setIcon(self._toolbar_symbol_icon("help"))
            self.zoom_in_action.setIcon(self._toolbar_symbol_icon("zoom_in"))
            self.zoom_out_action.setIcon(self._toolbar_symbol_icon("zoom_out"))
            self.dism_start_menu.setIcon(self._toolbar_symbol_icon("play"))

            if self.dark_mode_enabled:
                self.theme_action.setIcon(self._toolbar_symbol_icon("sun"))
                self.theme_action.setText("Hellmodus einschalten")
                self.theme_action.setToolTip("Hellmodus einschalten")
                self.theme_action.setStatusTip(
                    "Gesamte Anwendung auf Hellmodus umschalten"
                )
                mode_text = "Dunkelmodus"
            else:
                self.theme_action.setIcon(self._toolbar_symbol_icon("moon"))
                self.theme_action.setText("Dunkelmodus einschalten")
                self.theme_action.setToolTip("Dunkelmodus einschalten")
                self.theme_action.setStatusTip(
                    "Gesamte Anwendung auf Dunkelmodus umschalten"
                )
                mode_text = "Hellmodus"

            self.statusBar().showMessage(f"{mode_text} eingeschaltet")

        def _active_text_edit_widget(self):
            """Stage 166: aktives Text-Widget fuer das Bearbeiten-Menue liefern."""
            focus_widget = QApplication.focusWidget()
            if isinstance(
                focus_widget,
                (QLineEdit, QTextEdit, QPlainTextEdit),
            ):
                return focus_widget

            document = self.current_document()
            if document is not None:
                return document.active_text_editor()
            return None

        @staticmethod
        def _text_widget_is_read_only(widget) -> bool:
            checker = getattr(widget, "isReadOnly", None)
            return bool(checker()) if callable(checker) else False

        @staticmethod
        def _text_widget_has_selection(widget) -> bool:
            if isinstance(widget, QLineEdit):
                return bool(widget.hasSelectedText())
            if isinstance(widget, (QTextEdit, QPlainTextEdit)):
                return bool(widget.textCursor().hasSelection())
            return False

        @staticmethod
        def _text_widget_undo_available(widget) -> bool:
            checker = getattr(widget, "isUndoAvailable", None)
            if callable(checker):
                try:
                    return bool(checker())
                except Exception:
                    pass
            document_getter = getattr(widget, "document", None)
            if callable(document_getter):
                try:
                    return bool(document_getter().isUndoAvailable())
                except Exception:
                    pass
            return False

        @staticmethod
        def _text_widget_redo_available(widget) -> bool:
            checker = getattr(widget, "isRedoAvailable", None)
            if callable(checker):
                try:
                    return bool(checker())
                except Exception:
                    pass
            document_getter = getattr(widget, "document", None)
            if callable(document_getter):
                try:
                    return bool(document_getter().isRedoAvailable())
                except Exception:
                    pass
            return False

        def _run_current_text_command(self, command: str) -> None:
            widget = self._active_text_edit_widget()
            if widget is None:
                return
            if (
                command in {"undo", "redo", "paste", "cut"}
                and self._text_widget_is_read_only(widget)
            ):
                return
            handler = getattr(widget, command, None)
            if callable(handler):
                handler()
            QTimer.singleShot(0, self._update_edit_actions)

        def undo_current_editor(self, _checked: bool = False) -> None:
            self._run_current_text_command("undo")

        def redo_current_editor(self, _checked: bool = False) -> None:
            self._run_current_text_command("redo")

        def copy_current_editor(self, _checked: bool = False) -> None:
            self._run_current_text_command("copy")

        def paste_current_editor(self, _checked: bool = False) -> None:
            self._run_current_text_command("paste")

        def cut_current_editor(self, _checked: bool = False) -> None:
            self._run_current_text_command("cut")

        def _update_edit_actions(self) -> None:
            """Bearbeiten-Aktionen passend zum aktuellen Editorzustand setzen."""
            if not hasattr(self, "undo_action"):
                return
            widget = self._active_text_edit_widget()
            has_widget = widget is not None
            read_only = (
                self._text_widget_is_read_only(widget)
                if has_widget
                else True
            )
            has_selection = (
                self._text_widget_has_selection(widget)
                if has_widget
                else False
            )

            self.undo_action.setEnabled(
                has_widget
                and not read_only
                and self._text_widget_undo_available(widget)
            )
            self.redo_action.setEnabled(
                has_widget
                and not read_only
                and self._text_widget_redo_available(widget)
            )
            self.copy_action.setEnabled(has_widget and has_selection)
            self.cut_action.setEnabled(
                has_widget and not read_only and has_selection
            )
            self.paste_action.setEnabled(
                has_widget
                and not read_only
                and QApplication.clipboard().mimeData().hasText()
            )

        def current_document(self) -> Optional[DocumentEditor]:
            widget = self.document_tabs.currentWidget()
            return widget if isinstance(widget, DocumentEditor) else None

        def _document_index(self, document: DocumentEditor) -> int:
            return self.document_tabs.indexOf(document)

        def _find_open_document(self, path: Path) -> Optional[DocumentEditor]:
            wanted = os.path.normcase(str(Path(path).resolve()))
            for index in range(self.document_tabs.count()):
                document = self.document_tabs.widget(index)
                if not isinstance(document, DocumentEditor):
                    continue
                if document.path is None:
                    continue
                current = os.path.normcase(str(document.path.resolve()))
                if current == wanted:
                    return document
            return None

        @staticmethod
        def _source_find_searchable_extensions() -> set:
            """Text-/Quellformate für 'Im Projekt suchen'."""
            return (
                set(DocumentEditor.BASIC_EXTENSIONS)
                | set(DocumentEditor.ASSEMBLER_EXTENSIONS)
                | set(DocumentEditor.PASCAL_EXTENSIONS)
                | set(DocumentEditor.C_EXTENSIONS)
                | set(DocumentEditor.C_HEADER_EXTENSIONS)
                | set(DocumentEditor.LISP_EXTENSIONS)
                | set(DocumentEditor.PROLOG_EXTENSIONS)
                | set(DocumentEditor.LOGO_EXTENSIONS)
                | set(DocumentEditor.DBASE_EXTENSIONS)
                | set(DocumentEditor.MARKDOWN_EXTENSIONS)
                | {".txt", ".text", ".log"}
            )

        def _source_find_project_paths(self) -> list:
            tree = getattr(self, "project_tree", None)
            if tree is None:
                return []

            extensions = self._source_find_searchable_extensions()
            result = []
            seen = set()

            iterator = QTreeWidgetItemIterator(tree)
            while iterator.value() is not None:
                item = iterator.value()
                iterator += 1

                path_text = str(
                    item.data(0, Qt.UserRole + 302) or ""
                ).strip()
                if not path_text:
                    continue

                candidate = Path(path_text).expanduser()
                if candidate.suffix.casefold() not in extensions:
                    continue

                try:
                    resolved = candidate.resolve()
                except OSError:
                    resolved = candidate

                key = os.path.normcase(str(resolved))
                if key in seen:
                    continue
                seen.add(key)

                if resolved.is_file():
                    result.append(resolved)

            return result

        def _source_find_context_path(
            self,
            document: Optional[DocumentEditor],
        ) -> Optional[Path]:
            if document is None:
                return None

            if document.path is not None:
                try:
                    return Path(document.path).resolve()
                except OSError:
                    return Path(document.path)

            if (
                document is self.dbase_form_build_document
                and self.dbase_form_current_path is not None
            ):
                try:
                    return Path(
                        self.dbase_form_current_path
                    ).resolve()
                except OSError:
                    return Path(self.dbase_form_current_path)

            return None

        @staticmethod
        def _source_find_path_key(path: Optional[Path]) -> str:
            if path is None:
                return ""
            try:
                return os.path.normcase(str(Path(path).resolve()))
            except OSError:
                return os.path.normcase(str(Path(path)))

        def _source_find_project_text(
            self,
            path: Path,
        ) -> Optional[str]:
            key = self._source_find_path_key(path)

            document = self._find_open_document(path)
            if document is not None:
                return document.raw_editor.toPlainText()

            current_form = self._source_find_context_path(
                self.dbase_form_build_document
            )
            if (
                current_form is not None
                and self._source_find_path_key(current_form) == key
                and self.dbase_form_build_document is not None
            ):
                return (
                    self.dbase_form_build_document
                    .raw_editor
                    .toPlainText()
                )

            try:
                value, _encoding, _newline, _raw = (
                    self._decode_text_file(path)
                )
                return value
            except (OSError, UnicodeError):
                return None

        @staticmethod
        def _source_find_compile_pattern(criteria: dict):
            use_regex = bool(criteria.get("regex"))
            source = (
                str(criteria.get("regex_text", ""))
                if use_regex
                else str(criteria.get("text", ""))
            )

            if not source:
                raise ValueError(
                    tr(
                        "Bitte einen Suchtext bzw. regulären Ausdruck eingeben."
                    )
                )

            pattern_text = source if use_regex else re.escape(source)

            if bool(criteria.get("whole_words")):
                pattern_text = (
                    r"(?<!\w)(?:"
                    + pattern_text
                    + r")(?!\w)"
                )

            flags = (
                0
                if bool(criteria.get("case_sensitive"))
                else re.IGNORECASE
            )

            try:
                pattern = re.compile(pattern_text, flags)
            except re.error as exc:
                raise ValueError(
                    tr("Ungültiger regulärer Ausdruck: {error}").format(
                        error=str(exc)
                    )
                ) from exc

            empty = pattern.search("")
            if empty is not None and empty.start() == empty.end():
                raise ValueError(
                    tr(
                        "Der reguläre Ausdruck darf keine leere "
                        "Zeichenfolge als Treffer liefern."
                    )
                )

            return pattern

        @staticmethod
        def _source_find_span(
            source: str,
            pattern,
            start_position: int,
            forward: bool,
        ) -> Optional[Tuple[int, int]]:
            text_value = str(source)
            position = max(
                0,
                min(int(start_position), len(text_value)),
            )

            if forward:
                match = pattern.search(text_value, position)
                return match.span() if match is not None else None

            last_match = None
            for match in pattern.finditer(
                text_value,
                0,
                position,
            ):
                if match.end() <= position:
                    last_match = match

            return (
                last_match.span()
                if last_match is not None
                else None
            )

        @staticmethod
        def _source_find_select_span(
            editor: SourceTextEdit,
            start: int,
            end: int,
            forward: bool,
        ) -> None:
            cursor = editor.textCursor()

            if forward:
                cursor.setPosition(int(start))
                cursor.setPosition(
                    int(end),
                    QTextCursor.KeepAnchor,
                )
            else:
                cursor.setPosition(int(end))
                cursor.setPosition(
                    int(start),
                    QTextCursor.KeepAnchor,
                )

            editor.setTextCursor(cursor)
            editor.ensureCursorVisible()
            editor.setFocus(Qt.OtherFocusReason)

        def _source_find_build_project_order(
            self,
            *,
            current_path: Optional[Path],
            forward: bool,
        ) -> list:
            paths = self._source_find_project_paths()
            if not paths:
                return []

            ordered_base = list(paths)
            if not forward:
                ordered_base.reverse()

            current_key = self._source_find_path_key(current_path)
            if not current_key:
                return ordered_base

            current_item = None
            others = []
            for path in ordered_base:
                if self._source_find_path_key(path) == current_key:
                    current_item = path
                else:
                    others.append(path)

            return (
                [current_item] + others
                if current_item is not None
                else ordered_base
            )

        def _source_find_navigate_project_result(
            self,
            path: Path,
            span: Tuple[int, int],
            *,
            forward: bool,
        ) -> bool:
            path = Path(path)

            if not self.open_document(path):
                return False

            if path.suffix.casefold() == ".wfm":
                document = self.dbase_form_build_document
                editor = (
                    document.raw_editor
                    if document is not None
                    else None
                )
                if (
                    editor is not None
                    and self.dbase_form_tabs is not None
                    and self.dbase_form_source_page is not None
                ):
                    self.dbase_form_tabs.setCurrentWidget(
                        self.dbase_form_source_page
                    )
            else:
                document = self._find_open_document(path)
                editor = (
                    document.raw_editor
                    if document is not None
                    else None
                )
                if document is not None:
                    document.views.setCurrentWidget(
                        document.source_page
                    )

            if document is None or editor is None:
                return False

            self._source_find_document = document
            self._source_find_editor = editor

            self._source_find_select_span(
                editor,
                span[0],
                span[1],
                forward,
            )

            dialog = self.source_find_dialog
            if dialog is not None:
                dialog.set_target(
                    document.display_name,
                    project_file_count=len(
                        self._source_find_project_paths()
                    ),
                )

            return True

        def show_source_find_dialog(
            self,
            document: DocumentEditor,
            editor: SourceTextEdit,
        ) -> None:
            if document is None or editor is None:
                return

            dialog = self.source_find_dialog
            if dialog is None:
                dialog = SourceFindDialog(self)
                dialog.search_requested.connect(
                    self._execute_source_find
                )
                dialog.abort_requested.connect(
                    self._abort_source_find
                )
                dialog.set_dark_mode(self.dark_mode_enabled)
                self.source_find_dialog = dialog

            self._source_find_document = document
            self._source_find_editor = editor
            self._source_find_cancel_requested = False
            self._source_find_project_order = []
            self._source_find_project_signature = None

            selected = editor.textCursor().selectedText()

            dialog.set_target(
                document.display_name,
                selected_text=selected,
                project_file_count=len(
                    self._source_find_project_paths()
                ),
            )
            dialog.set_dark_mode(self.dark_mode_enabled)
            dialog.show()
            dialog.raise_()
            dialog.activateWindow()
            dialog.focus_search_text()

        def repeat_source_find(
            self,
            document: DocumentEditor,
            editor: SourceTextEdit,
        ) -> None:
            """F3 setzt die letzte Editorsuche fort und läuft am Ende um."""
            dialog = self.source_find_dialog
            if dialog is None:
                self.show_source_find_dialog(document, editor)
                return

            criteria = dialog.criteria()
            search_value = (
                str(criteria.get("regex_text", ""))
                if criteria.get("regex")
                else str(criteria.get("text", ""))
            )
            if not search_value:
                self.show_source_find_dialog(document, editor)
                return

            self._source_find_document = document
            self._source_find_editor = editor
            dialog.set_target(
                document.display_name,
                project_file_count=len(self._source_find_project_paths()),
            )
            self._execute_source_find(True, allow_wrap=True)

        def _abort_source_find(self) -> None:
            self._source_find_cancel_requested = True
            self._source_find_project_order = []
            self._source_find_project_signature = None

            if self.source_find_dialog is not None:
                self.source_find_dialog.set_status(
                    tr("Suche abgebrochen.")
                )

        def _execute_source_find(
            self,
            continue_search: bool,
            allow_wrap: bool = False,
        ) -> None:
            dialog = self.source_find_dialog
            document = self._source_find_document
            editor = self._source_find_editor

            if (
                dialog is None
                or document is None
                or editor is None
            ):
                return

            criteria = dialog.criteria()

            try:
                pattern = self._source_find_compile_pattern(
                    criteria
                )
            except ValueError as exc:
                dialog.set_status(str(exc), error=True)
                return

            self._source_find_cancel_requested = False
            forward = bool(criteria.get("forward"))
            project_mode = bool(criteria.get("project"))

            signature = (
                str(criteria.get("text", "")),
                str(criteria.get("regex_text", "")),
                bool(criteria.get("regex")),
                bool(criteria.get("whole_words")),
                bool(criteria.get("case_sensitive")),
                forward,
                project_mode,
            )

            current_path = self._source_find_context_path(
                document
            )

            if (
                not continue_search
                or signature != self._source_find_project_signature
            ):
                self._source_find_project_signature = signature
                self._source_find_project_order = (
                    self._source_find_build_project_order(
                        current_path=current_path,
                        forward=forward,
                    )
                    if project_mode
                    else []
                )

            current_text = editor.toPlainText()

            if continue_search:
                start_position = editor.textCursor().position()
            else:
                start_position = (
                    0
                    if forward
                    else len(current_text)
                )

            span = self._source_find_span(
                current_text,
                pattern,
                start_position,
                forward,
            )

            if span is not None:
                self._source_find_select_span(
                    editor,
                    span[0],
                    span[1],
                    forward,
                )
                line = current_text.count(
                    "\n",
                    0,
                    span[0],
                ) + 1
                dialog.set_status(
                    tr("Treffer in {name}, Zeile {line}.").format(
                        name=document.display_name,
                        line=line,
                    )
                )
                return

            if not project_mode:
                if continue_search and allow_wrap:
                    wrap_position = 0 if forward else len(current_text)
                    wrapped_span = self._source_find_span(
                        current_text,
                        pattern,
                        wrap_position,
                        forward,
                    )
                    if wrapped_span is not None:
                        self._source_find_select_span(
                            editor,
                            wrapped_span[0],
                            wrapped_span[1],
                            forward,
                        )
                        line = current_text.count(
                            "\n", 0, wrapped_span[0]
                        ) + 1
                        dialog.set_status(
                            tr(
                                "Suche am {boundary} fortgesetzt; "
                                "Treffer in {name}, Zeile {line}."
                            ).format(
                                boundary=(
                                    tr("Dokumentanfang")
                                    if forward
                                    else tr("Dokumentende")
                                ),
                                name=document.display_name,
                                line=line,
                            )
                        )
                        return
                dialog.set_status(
                    tr("Kein weiterer Treffer gefunden.")
                    if continue_search
                    else tr("Kein Treffer gefunden.")
                )
                return

            order = list(self._source_find_project_order)
            current_key = self._source_find_path_key(
                current_path
            )

            start_index = 0
            if current_key:
                for index, project_path in enumerate(order):
                    if (
                        self._source_find_path_key(project_path)
                        == current_key
                    ):
                        start_index = index + 1
                        break

            for project_path in order[start_index:]:
                QApplication.processEvents()
                if self._source_find_cancel_requested:
                    dialog.set_status(
                        tr("Suche abgebrochen.")
                    )
                    return

                project_text = self._source_find_project_text(
                    project_path
                )
                if project_text is None:
                    continue

                boundary = (
                    0
                    if forward
                    else len(project_text)
                )

                project_span = self._source_find_span(
                    project_text,
                    pattern,
                    boundary,
                    forward,
                )
                if project_span is None:
                    continue

                if not self._source_find_navigate_project_result(
                    project_path,
                    project_span,
                    forward=forward,
                ):
                    continue

                line = project_text.count(
                    "\n",
                    0,
                    project_span[0],
                ) + 1
                dialog.set_status(
                    tr("Treffer in {name}, Zeile {line}.").format(
                        name=project_path.name,
                        line=line,
                    )
                )
                return

            dialog.set_status(
                tr("Kein weiterer Treffer im Projekt gefunden.")
                if continue_search
                else tr("Kein Treffer im Projekt gefunden.")
            )

        @staticmethod
        def _decode_text_file(path: Path) -> Tuple[str, str, str, bytes]:
            raw = path.read_bytes()

            if raw.startswith(b"\xef\xbb\xbf"):
                encodings = ("utf-8-sig",)
            elif raw.startswith((b"\xff\xfe", b"\xfe\xff")):
                encodings = ("utf-16",)
            else:
                encodings = ("utf-8", "cp1252", "latin-1")

            text = None
            selected_encoding = "utf-8"
            for encoding in encodings:
                try:
                    text = raw.decode(encoding)
                    selected_encoding = encoding
                    break
                except UnicodeDecodeError:
                    continue

            if text is None:
                raise UnicodeError("Die Zeichenkodierung konnte nicht erkannt werden.")

            crlf_count = raw.count(b"\r\n")
            lf_count = raw.count(b"\n") - crlf_count
            cr_count = raw.count(b"\r") - crlf_count
            if crlf_count >= max(lf_count, cr_count) and crlf_count:
                newline = "\r\n"
            elif cr_count > lf_count:
                newline = "\r"
            else:
                newline = "\n"

            return text, selected_encoding, newline, raw

        def new_document(
            self,
            _checked: bool = False,
            *,
            text: str = "",
            display_name: Optional[str] = None,
        ) -> DocumentEditor:
            self.untitled_counter += 1
            dark_mode = self.application_dark_mode(
                self.dark_mode_enabled
            )
            document = DocumentEditor(
                self.document_tabs,
                untitled_number=self.untitled_counter,
                text=text,
                editor_font=self._make_editor_font(),
                dark_mode=dark_mode,
            )
            if display_name:
                document.custom_display_name = display_name
                document.update_syntax_highlighting()
            self._add_document_tab(document)
            document.focus_preferred_editor()
            self.log(f"Neue Textdatei angelegt: {document.display_name}")
            return document

        def _ensure_project_for_new_document(self) -> Path:
            """Stellt eine speicherbare .pro-Datei für neue Dokumente bereit."""
            if self.current_project_path is None:
                number = 1
                while True:
                    candidate = self.current_directory / (
                        f"Unbenannt_Projekt_{number}.pro"
                    )
                    if not candidate.exists():
                        break
                    number += 1
                self.current_project_path = candidate.resolve()
                if hasattr(self, "project_path_edit"):
                    self.project_path_edit.setText(
                        str(self.current_project_path)
                    )
                save_project_ini(
                    self.current_project_path,
                    self.collect_project_entries()
                    if hasattr(self, "project_tree")
                    else empty_project_entries(),
                )
                self.set_project_modified(False)
                self.log(
                    f"Automatisches Projekt angelegt: {self.current_project_path}"
                )
                self._remember_recent_project(self.current_project_path)
            return Path(self.current_project_path)

        def _create_new_dbase_program_item(
            self,
            *,
            use_template: bool = True,
        ) -> Optional[QTreeWidgetItem]:
            """Stage ASM 29: neue dBase-Programme als *.prg unter Programme."""
            self._ensure_project_for_new_document()
            directory = self._project_new_file_directory()
            used = {name.casefold() for name in self._project_existing_names()}
            number = 1
            while True:
                filename = f"Unbenannt_{number}.prg"
                if filename.casefold() not in used and not (directory / filename).exists():
                    break
                number += 1
            path = directory / filename
            try:
                self._write_new_project_file(
                    "dbase", path, use_template=use_template
                )
            except (OSError, ValueError) as exc:
                self.show_error(
                    "Neues dBase-Programm konnte nicht angelegt werden",
                    f"Die Datei konnte nicht erzeugt werden:\n{path}\n\n{exc}",
                )
                return None
            child = self._add_project_dbase_entry(
                "programs", path, title=filename
            )
            if child is None:
                return None
            self.project_tree.setCurrentItem(child)
            if self.current_project_path is not None:
                self.save_project()
            self.open_document(path, language_override="dbase")
            self.statusBar().showMessage(f"Neues dBase-Programm angelegt: {filename}")
            self.log(f"Neues dBase-Programm angelegt: {path}")
            return child

        def _new_project_item_for_category(
            self,
            category_key: str,
            *,
            use_template: bool = True,
        ) -> Optional[QTreeWidgetItem]:
            self._ensure_project_for_new_document()
            root = self.project_root_items.get(category_key)
            if root is None:
                return None
            return self.create_new_project_item(
                root,
                use_template=use_template,
            )

        def new_source_document(
            self,
            language: str,
            *,
            target: Optional[str] = None,
            use_template: bool = True,
        ) -> Optional[DocumentEditor]:
            """Legt eine Quelldatei im aktuellen Projekt an.

            ``use_template=True`` entspricht der bisherigen Neu-Programmlogik.
            ``False`` ist die neue Menüfunktion "Programm" und erzeugt eine
            wirklich leere Quellcodedatei derselben Kategorie.
            """
            key = str(language).casefold()
            category_map = {
                "basic": "basic",
                "assembler": "assembler",
                "pascal": "pascal",
                "c": "c",
                "lisp": "lisp",
                "prolog": "prolog",
                "logo": "logo",
                "dbase": "dbase",
                "text": "text_files",
            }
            category_key = category_map.get(key, "text_files")
            if category_key == "dbase":
                child = self._create_new_dbase_program_item(
                    use_template=use_template
                )
            else:
                child = self._new_project_item_for_category(
                    category_key,
                    use_template=use_template,
                )
            if child is None:
                return None
            document = self.current_document()
            if isinstance(document, DocumentEditor) and target:
                document.set_build_target(target)
            return document

        def new_profile_source_document(
            self,
            profile_key: str,
            *,
            use_template: bool,
        ) -> Optional[DocumentEditor]:
            spec = self.compact_new_profiles.get(str(profile_key))
            if spec is None:
                return None
            return self.new_source_document(
                spec["language"],
                target=spec["target"],
                use_template=use_template,
            )

        def new_character_map(self, _checked: bool = False) -> None:
            self._new_project_item_for_category("character_maps")

        def new_text_screen(self, _checked: bool = False) -> None:
            self._new_project_item_for_category("char_screens")

        def new_pixel_screen(self, _checked: bool = False) -> None:
            self._new_project_item_for_category("pixel_screens")
            self._update_editor_status_panels()

        def _open_dialog_supported_extensions(self) -> List[str]:
            extensions = set(self.EDITOR_EXTENSIONS)
            for values in self.FILTERS.values():
                if values:
                    extensions.update(values)
            extensions.update({
                ".exe", ".o", ".obj", ".a", ".lib", ".sid", ".d64", ".dbf", ".d64report"
            })
            return sorted(extensions)

        def _register_opened_file_in_project(self, path: Path) -> None:
            path = Path(path)
            suffix = path.suffix.casefold()
            if suffix == ".pro":
                return
            self._ensure_project_for_new_document()

            # Stage ASM 29: nur ein explizites dBase-Projekt ordnet die
            # Ressourcen automatisch den festen dBase-Unterknoten zu. So
            # bleibt z. B. die vorhandene Pascal-DBF-Projektlogik unangetastet.
            role = ""
            if str(getattr(self, "current_project_kind", "")).casefold() == "dbase":
                role = {
                    ".prg": "programs",
                    ".wfm": "forms",
                    ".dbf": "tables",
                    ".d64sql": "queries",
                    ".d64report": "reports",
                    ".o": "objects",
                    ".a": "archives",
                }.get(suffix, "")
            if role:
                child = self._add_project_dbase_entry(role, path, title=path.name)
            else:
                category_key = project_category_for_path(path)
                child = self._add_project_entry(
                    category_key,
                    path,
                    title=path.name,
                )
            if child is None:
                return
            self.project_tree.setCurrentItem(child)
            root = child.parent()
            if root is not None:
                root.setExpanded(True)
            if self.current_project_path is not None:
                self.save_project()

        def open_document_dialog(self) -> None:
            dialog = ProjectOpenFileDialog(
                self,
                initial_directory=self.current_directory,
                supported_extensions=self._open_dialog_supported_extensions(),
            )

            # Der zuletzt im eigenen Datei-Öffnen-Dialog angezeigte Ordner ist
            # zugleich das Arbeits-/Ausgabeverzeichnis der IDE. Das gilt auch
            # bei Abbrechen bzw. Schliessen ueber die Titlebar: dBase-Build und
            # Start suchen/erzeugen die EXE danach genau in diesem Ordner.
            result = dialog.exec_()
            dialog_directory = Path(dialog.current_directory)
            if dialog_directory.is_dir():
                self.set_current_directory(dialog_directory)

            if result != QDialog.Accepted or not dialog.fileName:
                self.statusBar().showMessage(
                    f"Öffnen abgebrochen - Arbeitsverzeichnis: {self.current_directory}"
                )
                return

            path = Path(dialog.fileName)
            _dbase_prg = (
                path.suffix.casefold() == ".prg"
                and str(getattr(self, "current_project_kind", "")).casefold() == "dbase"
            )
            if self.open_document(
                path, language_override="dbase" if _dbase_prg else ""
            ):
                # Eine manuell in der unteren ComboBox eingegebene absolute
                # Datei kann ausserhalb des gerade angezeigten Ordners liegen.
                # In diesem Sonderfall folgt das Arbeitsverzeichnis der
                # tatsaechlich geoeffneten Datei.
                if path.parent.resolve() != self.current_directory:
                    self.set_current_directory(path.parent)
                self._register_opened_file_in_project(path)
                self.statusBar().showMessage(f"Geöffnet: {path.name}")

        def open_document(
            self,
            path: Path,
            *,
            assembler_text_mode: bool = False,
            language_override: str = "",
        ) -> bool:
            try:
                path = Path(path).expanduser().resolve()
            except OSError as exc:
                self.show_error("Pfadfehler", str(exc))
                return False

            language_override = str(language_override or "").strip().casefold()
            # Stage ASM 29: .prg bleibt standardmaessig ein C64-Binaerprogramm.
            # Nur ein Blatt unter dBase-Programme -> Programme erzwingt den
            # dBase-Textmodus.
            if path.suffix.casefold() == ".prg" and language_override != "dbase":
                assembler_text_mode = False

            if path.suffix.lower() == ".wfm":
                opened = self.open_dbase_form_file(path)
                if opened:
                    self._remember_recent_file(path)
                return opened

            if path.suffix.lower() == ".dbf":
                opened = self.open_dbase_table_file(path)
                if opened:
                    self._remember_recent_file(path)
                return opened

            if path.suffix.lower() == ".d64report":
                opened = self.open_dbase_report_file(path)
                if opened:
                    self._remember_recent_file(path)
                return opened

            if path.suffix.lower() in {".chr", ".charset"}:
                self.show_character_editor(initial_path=path)
                self._remember_recent_file(path)
                return True

            if path.suffix.lower() in {".pal", ".palette"}:
                self.show_palette_editor(initial_path=path)
                self._remember_recent_file(path)
                return True

            if path.suffix.lower() in {".scr", ".screen"}:
                self.show_text_screen_editor(initial_path=path)
                self._remember_recent_file(path)
                return True

            if path.suffix.lower() in {".px16", ".pixel", ".pix"}:
                self.show_pixel_screen_editor(initial_path=path)
                self._remember_recent_file(path)
                return True

            if path.suffix.lower() == ".pro":
                return self.load_project_file(path)

            existing = self._find_open_document(path)
            if (
                existing is not None
                and (not language_override or existing.source_language() == language_override)
            ):
                self.document_tabs.setCurrentWidget(existing)
                self._apply_document_theme(existing)
                existing.focus_preferred_editor()
                self._remember_recent_file(path)
                if existing.source_language() == "basic":
                    self._last_opened_c64_basic_path = Path(path)
                self.statusBar().showMessage(f"Bereits geöffnet: {path.name}")
                return True

            binary_disassembly_mode = (
                not assembler_text_mode
                and not language_override
                and path.suffix.casefold() in {".prg", ".bin"}
            )
            if binary_disassembly_mode:
                # Stage 257: Weder read_bytes() noch der Disassembler laufen
                # hier im GUI-Thread. Der Editor wird sofort sichtbar; sein
                # Worker übernimmt Dateigröße, Laden und 6510-Disassembly.
                if not path.is_file():
                    self.show_error(
                        "C64-Binärdatei konnte nicht geöffnet werden",
                        f"Datei nicht gefunden:\n{path}",
                    )
                    return False
                raw_bytes = b""
                text = "; C64-Disassembly wird vorbereitet ...\n"
                encoding = "utf-8"
                newline = "\n"
            else:
                try:
                    text, encoding, newline, raw_bytes = self._decode_text_file(path)
                except (OSError, UnicodeError) as exc:
                    self.show_error(
                        "Datei konnte nicht geöffnet werden",
                        f"Die Datei konnte nicht als Text geladen werden:\n{path}\n\n{exc}",
                    )
                    return False

            self.untitled_counter += 1
            dark_mode = self.application_dark_mode(
                self.dark_mode_enabled
            )
            document = DocumentEditor(
                self.document_tabs,
                untitled_number=self.untitled_counter,
                path=path,
                text=text,
                encoding=encoding,
                newline=newline,
                raw_bytes=raw_bytes,
                editor_font=self._make_editor_font(),
                dark_mode=dark_mode,
                binary_disassembly_mode=binary_disassembly_mode,
                assembler_text_mode=assembler_text_mode,
                language_override=language_override,
            )
            self._add_document_tab(document)
            if document.source_language() == "basic":
                self._last_opened_c64_basic_path = Path(path)
            document.focus_preferred_editor()
            if binary_disassembly_mode:
                self._start_c64_document_disassembly(document, path)
            self.log(f"Datei im Editor geöffnet: {path}")
            if assembler_text_mode:
                self.log(
                    f"ASM-TEXTMODUS: {path.name} -> textueller Assembler-Editor"
                )
            if binary_disassembly_mode:
                self.log(
                    f"C64-DISASSEMBLY: {path.name} -> Rohdaten-Tab "
                    "(Binärbytes bleiben im Hex-Editor erhalten)"
                )
                self.statusBar().showMessage(
                    f"{path.name} - C64-Disassembly im Rohdaten-Tab"
                )
            else:
                self.statusBar().showMessage(
                    f"{path.name} - Kodierung: {encoding}"
                )
            self._remember_recent_file(path)
            return True

        def _start_c64_document_disassembly(
            self,
            document: DocumentEditor,
            path: Path,
        ) -> None:
            """Startet Stage-257-C64-Disassembly ohne Arbeit im GUI-Thread."""
            key = id(document)
            old_job = self._c64_disassembly_jobs.get(key)
            if old_job is not None and old_job[0].isRunning():
                return

            document.begin_c64_disassembly()
            thread = QThread(self)
            worker = C64DisassemblyWorker(path)
            worker.moveToThread(thread)
            self._c64_disassembly_jobs[key] = (thread, worker, document)

            thread.started.connect(worker.run)
            worker.size_ready.connect(document.set_c64_disassembly_size)
            worker.progress.connect(document.set_c64_disassembly_progress)
            worker.succeeded.connect(
                lambda raw, listing, load_address, doc=document:
                    self._c64_document_disassembly_finished(
                        doc, raw, listing, load_address
                    )
            )
            worker.failed.connect(
                lambda message, doc=document:
                    self._c64_document_disassembly_failed(doc, message)
            )
            worker.succeeded.connect(thread.quit)
            worker.failed.connect(thread.quit)
            worker.succeeded.connect(worker.deleteLater)
            worker.failed.connect(worker.deleteLater)
            thread.finished.connect(
                lambda job_key=key: self._c64_disassembly_thread_finished(job_key)
            )
            thread.finished.connect(thread.deleteLater)

            # Stage 259: Nicht im selben Call-Stack wie show()/Tab-Aufbau starten.
            # 40 ms geben Qt sicher Gelegenheit, die 1-%-Leiste zu layouten und
            # auf den Bildschirm zu zeichnen. Danach bleibt alles asynchron.
            QTimer.singleShot(40, thread.start)

        def _c64_document_disassembly_finished(
            self,
            document: DocumentEditor,
            raw_bytes: bytes,
            listing: str,
            load_address: int,
        ) -> None:
            try:
                if self._document_index(document) < 0:
                    return
                document.finish_c64_disassembly(raw_bytes, listing)
            except RuntimeError:
                return
            self.log(
                f"C64-DISASSEMBLY FERTIG: {document.display_name}; "
                f"{len(raw_bytes)} Bytes; Ladeadresse ${int(load_address) & 0xFFFF:04X}"
            )
            self.statusBar().showMessage(
                f"{document.display_name} – C64-Disassembly abgeschlossen"
            )
            self._update_editor_status_panels()

        def _c64_document_disassembly_failed(
            self,
            document: DocumentEditor,
            message: str,
        ) -> None:
            try:
                if self._document_index(document) >= 0:
                    document.fail_c64_disassembly(message)
            except RuntimeError:
                pass
            self.log(f"C64-DISASSEMBLY FEHLER: {message}")
            self.show_error(
                "C64-Binärdatei konnte nicht disassembliert werden",
                str(message),
            )

        def _c64_disassembly_thread_finished(self, job_key: int) -> None:
            self._c64_disassembly_jobs.pop(int(job_key), None)

        def show_character_editor(
            self,
            _checked: bool = False,
            *,
            initial_path: Optional[Path] = None,
        ) -> None:
            dialog = self.character_editor_dialog
            if dialog is None or dialog.isHidden():
                dialog = C64CharacterEditorDialog(
                    self,
                    initial_directory=self.current_directory,
                    initial_path=initial_path,
                )
                dialog.setAttribute(Qt.WA_DeleteOnClose, True)
                dialog.destroyed.connect(
                    lambda _object=None: setattr(
                        self,
                        "character_editor_dialog",
                        None,
                    )
                )
                self.character_editor_dialog = dialog
            elif initial_path is not None:
                dialog.load_file(Path(initial_path))

            dialog.show()
            dialog.raise_()
            dialog.activateWindow()
            self.statusBar().showMessage("C64 Character-Editor geöffnet")

