        def _add_document_tab(self, document: DocumentEditor) -> None:
            index = self.document_tabs.addTab(document, document.display_name)
            self.document_tabs.setTabToolTip(index, self._document_tooltip(document))

            close_button = QToolButton(self.document_tabs.tabBar())
            close_button.setObjectName("document_tab_close_button")
            close_button.setAutoRaise(True)
            close_button.setIcon(self._toolbar_symbol_icon("close_white"))
            close_button.setIconSize(QSize(12, 12))
            close_button.setFixedSize(18, 18)
            close_button.setStyleSheet(
                "QToolButton { background-color:#475365;"
                "border:1px solid #66758a; border-radius:3px; padding:1px; }"
                "QToolButton:hover { background-color:#b23b3b;"
                "border-color:#e06a6a; }"
                "QToolButton:pressed { background-color:#7d2828; }"
            )
            close_button.setToolTip("Registerkarte schließen")
            close_button.clicked.connect(
                lambda checked=False, value=document: self.close_document(value)
            )
            self.document_tabs.tabBar().setTabButton(
                index, QTabBar.LeftSide, close_button
            )
            self.document_tabs.tabBar().setTabButton(index, QTabBar.RightSide, None)

            document.modification_changed.connect(
                lambda modified=False, value=document: self._document_modified(
                    value, modified
                )
            )
            document.assemble_requested.connect(self.assemble_document)
            document.start_requested.connect(self.start_assembled_document)
            document.assemble_generated_requested.connect(
                self.assemble_generated_document
            )
            document.start_generated_requested.connect(
                self.start_generated_assembly_document
            )
            document.coff_requested.connect(self.create_coff32_object_document)
            document.context_help_requested.connect(
                self.show_context_help_for_document
            )
            document.c64_help_topic_requested.connect(
                self.show_c64_help_topic
            )
            document.build_requested.connect(
                self.build_and_run_source_document
            )
            document.build_generated_requested.connect(
                self.build_and_run_generated_assembly_document
            )
            document.find_requested.connect(
                self.show_source_find_dialog
            )
            document.find_next_requested.connect(
                self.repeat_source_find
            )
            document.basic_renumber_requested.connect(
                self.renumber_c64_basic_document
            )
            document.basic_keyboard_visibility_changed.connect(
                self._c64_basic_keyboard_visibility_changed
            )
            # Stage 246: Projektmarker werden zuerst atomar in den Editor geladen,
            # danach synchronisieren weitere Gutter-Klicks zurück in den Baum.
            self._restore_project_markers_for_document(document)
            document.raw_editor.breakpoints_changed.connect(
                lambda value=document: self._sync_document_marker_to_project(
                    value, "breakpoint", persist=True
                )
            )
            document.raw_editor.bookmarks_changed.connect(
                lambda value=document: self._sync_document_marker_to_project(
                    value, "bookmark", persist=True
                )
            )
            document.raw_editor.bookmarks_changed.connect(
                self._refresh_favorites_menu
            )
            document.generated_assembly_editor.bookmarks_changed.connect(
                self._refresh_favorites_menu
            )
            document.raw_editor.cursorPositionChanged.connect(
                self._update_editor_status_panels
            )
            document.raw_editor.textChanged.connect(
                self._update_editor_status_panels
            )
            document.generated_assembly_editor.cursorPositionChanged.connect(
                self._update_editor_status_panels
            )
            document.generated_assembly_editor.textChanged.connect(
                self._update_editor_status_panels
            )
            document.views.currentChanged.connect(
                self._update_editor_status_panels
            )
            document.hex_editor.dataChanged.connect(
                self._update_editor_status_panels
            )
            self.document_tabs.setCurrentWidget(document)
            if document.source_language() == "basic":
                _show_keyboard, _profile = (
                    self._project_c64_screen_keyboard_configuration()
                )
                _keyboard_layout, _layout_profile = (
                    self._project_c64_keyboard_layout_configuration()
                )
                document.set_basic_keyboard_layout(_keyboard_layout)
                document.set_basic_screen_keyboard_visible(
                    _show_keyboard, notify=True
                )
            self._update_document_actions()
            self._update_document_tab(document)
            self._apply_document_theme(document)
            self._refresh_favorites_menu()

            # Nach der Rueckkehr in die Qt-Ereignisschleife ist der neue Tab
            # vollstaendig in seine Widget-Hierarchie eingebunden. Eine zweite
            # explizite Anwendung verhindert, dass eine spaete PaletteChange-
            # Verarbeitung die ASM-Farben wieder mit Standardwerten ersetzt.
            QTimer.singleShot(
                0,
                lambda value=document: self._apply_document_theme(value),
            )

        def _apply_document_theme(self, document: DocumentEditor) -> None:
            """Setzt die aktiven Editorfarben nach Erzeugen/Oeffnen erneut."""
            if self._document_index(document) < 0:
                return
            dark_mode = self.application_dark_mode(
                self.dark_mode_enabled
            )
            document.set_dark_mode(dark_mode)

        @staticmethod
        def _document_tooltip(document: DocumentEditor) -> str:
            if document.path is None:
                return "Noch nicht gespeichert"
            return str(document.path)

        def _document_modified(
            self, document: DocumentEditor, _modified: bool
        ) -> None:
            self._update_document_tab(document)

        def _update_document_tab(self, document: DocumentEditor) -> None:
            index = self._document_index(document)
            if index < 0:
                return
            marker = " *" if document.is_modified else ""
            self.document_tabs.setTabText(
                index, f"{document.display_name}{marker}"
            )
            self.document_tabs.setTabToolTip(
                index, self._document_tooltip(document)
            )
            if document is self.current_document():
                self.setWindowTitle(
                    f"{document.display_name}{marker} - Qt5 D64-Explorer"
                )

        def _current_document_changed(self, _index: int) -> None:
            self._update_document_actions()
            document = self.current_document()

            # Stage ASM 68: Der temporaere Dockzustand gehoert ausschliesslich
            # zum aktuell sichtbaren BASIC-Editor. Beim Tabwechsel oder wenn der
            # letzte Editor geschlossen wird, zuerst den vorherigen Zustand
            # zurueckholen. Ein neu aktiver BASIC-Tab mit sichtbarer Tastatur
            # baut danach seinen eigenen temporaeren Stack auf.
            _snapshot = getattr(self, "_c64_keyboard_layout_snapshot", None)
            _owner = getattr(self, "_c64_keyboard_layout_owner", None)
            if _snapshot is not None and document is not _owner:
                self._restore_c64_keyboard_layout_snapshot()

            if document is None:
                self.setWindowTitle("Qt5 D64- und Dateisystem-Explorer")
                self._update_editor_status_panels()
                return

            if (
                isinstance(document, DocumentEditor)
                and document.is_basic_document
                and document.basic_screen_keyboard_visible()
                and getattr(self, "_c64_keyboard_layout_snapshot", None) is None
            ):
                self._c64_basic_keyboard_visibility_changed(document, True)

            self._update_document_tab(document)
            self._update_editor_status_panels()

        def _dbase_form_is_active(self) -> bool:
            return bool(
                self._dbase_form_workspace_active
                and self.dbase_form_scene is not None
                and self.dbase_form_designer_dock is not None
                and self.dbase_form_designer_dock.isVisible()
            )

        def _update_document_actions(self) -> None:
            has_document = self.current_document() is not None
            has_form = self._dbase_form_is_active()
            self.save_file_action.setEnabled(has_document or has_form)
            self.save_as_action.setEnabled(has_document or has_form)
            self.close_document_action.setEnabled(has_document)
            self._update_edit_actions()

        def renumber_c64_basic_document(self, document: DocumentEditor) -> None:
            """Stage ASM 58: Gutter neu nummerieren und Quelle direkt speichern."""
            if document is None or not document.is_basic_document:
                return
            self.document_tabs.setCurrentWidget(document)
            try:
                new_numbers, mapping = document.raw_editor.renumber_basic_lines(10)
            except Exception as exc:
                self.show_error(
                    "BASIC-Zeilennummern",
                    "Die C64-BASIC-Zeilennummern konnten nicht neu geordnet werden:\n\n"
                    + str(exc),
                )
                return

            document.invalidate_assembly_result("BASIC-Zeilennummern aktualisiert")
            self._update_document_tab(document)
            self._update_editor_status_panels()

            # Der Benutzer hat explizit verlangt, dass Aktualisieren nicht nur
            # den Gutter aendert, sondern auch die nummerierte Quelldatei. Bei
            # einem noch unbenannten BASIC-Dokument wird deshalb derselbe
            # Speichern-unter-Dialog wie bei Ctrl+S verwendet.
            save_as = document.path is None
            if not self._save_document(document, save_as=save_as):
                self.statusBar().showMessage(
                    "BASIC-Zeilennummern neu geordnet – Quelldatei noch nicht gespeichert"
                )
                return

            if new_numbers:
                step = new_numbers[0] if len(new_numbers) == 1 else (
                    new_numbers[1] - new_numbers[0]
                )
                scheme = "10, 20, 30, ..." if step == 10 else f"Schrittweite {step}"
            else:
                scheme = "keine Zeilen"
            changed_targets = sum(1 for old, new in mapping.items() if int(old) != int(new))
            self.log(
                f"C64 BASIC aktualisiert: {len(new_numbers)} Zeilen, {scheme}, "
                f"{changed_targets} alte Zeilennummer(n) neu zugeordnet; "
                "Ausdrucks-Leerzeichen kompakt formatiert."
            )
            self.statusBar().showMessage(
                f"BASIC aktualisiert, Ausdrucke formatiert und gespeichert: {scheme}"
            )

        def save_current_document(self) -> bool:
            if self._dbase_form_is_active():
                return self.save_dbase_form(save_as=False)
            document = self.current_document()
            if document is None:
                return False
            return self._save_document(document, save_as=False)

        def save_current_document_as(self) -> bool:
            if self._dbase_form_is_active():
                return self.save_dbase_form(save_as=True)
            document = self.current_document()
            if document is None:
                return False
            return self._save_document(document, save_as=True)

        def _choose_document_filename(
            self, document: DocumentEditor
        ) -> Optional[Path]:
            if (
                document.binary_disassembly_mode
                and document.raw_editor.document().isModified()
                and document.path is not None
            ):
                # Dokumentierte Disassemblies werden als ASM-Quelle gespeichert,
                # niemals still ueber die geoeffnete PRG/BIN-Datei geschrieben.
                initial = str(document.path.with_suffix(".asm"))
            elif document.path is not None:
                initial = str(document.path)
            else:
                suggested_name = document.display_name
                if not Path(suggested_name).suffix:
                    suggested_name += ".txt"
                initial = str(self.current_directory / suggested_name)

            filename, _selected_filter = QFileDialog.getSaveFileName(
                self,
                "Datei speichern unter",
                initial,
                (
                    "BASIC-Dateien (*.bas *.basic);;"
                    "C-Dateien (*.c *.h);;"
                    "LISP-Dateien (*.lisp *.lsp);;"
                    "PROLOG-Dateien (*.pl *.prolog);;LOGO-Dateien (*.logo *.lgo);;"
                    "dBase-Dateien (*.dbase *.dbp);;"
                    "Pascaldateien (*.pas *.pp);;"
                    "Assemblerdateien (*.asm *.s *.a65 *.m68k *.inc);;"
                    "Textdateien (*.txt);;"
                    "Binärdateien (*.prg *.amiga *.adf *.ram *.bin);;"
                    "Alle Dateien (*)"
                ),
            )
            return Path(filename).resolve() if filename else None

        def _save_document(
            self, document: DocumentEditor, *, save_as: bool
        ) -> bool:
            previous_path = document.path
            save_disassembly_source = bool(
                document.binary_disassembly_mode
                and document.raw_editor.document().isModified()
            )
            if save_disassembly_source and not save_as:
                # Ctrl+S an einer bearbeiteten Binary-Disassembly fuehrt
                # absichtlich zu "Speichern unter" als .asm. Das Original-
                # PRG/BIN bleibt unangetastet.
                save_as = True

            target = document.path
            if save_as or target is None:
                target = self._choose_document_filename(document)
                if target is None:
                    self.statusBar().showMessage("Speichern abgebrochen")
                    return False

            conflicting = self._find_open_document(target)
            if conflicting is not None and conflicting is not document:
                self.show_error(
                    "Datei bereits geöffnet",
                    "Die Zieldatei ist bereits in einer anderen Registerkarte "
                    f"geöffnet:\n{target}",
                )
                return False

            try:
                if save_disassembly_source:
                    data = document.text_for_saving(
                        target.suffix.casefold()
                    ).encode("utf-8")
                else:
                    data = document.data_for_saving(
                        target.suffix.casefold()
                    )
                target.parent.mkdir(parents=True, exist_ok=True)
                file_descriptor, temporary_name = tempfile.mkstemp(
                    prefix=f".{target.name}.",
                    suffix=".tmp",
                    dir=str(target.parent),
                )
                try:
                    with os.fdopen(file_descriptor, "wb") as stream:
                        stream.write(data)
                        stream.flush()
                        os.fsync(stream.fileno())
                    os.replace(temporary_name, target)
                except Exception:
                    try:
                        os.unlink(temporary_name)
                    except OSError:
                        pass
                    raise
            except (OSError, UnicodeError, ValueError) as exc:
                self.show_error(
                    "Datei konnte nicht gespeichert werden",
                    f"Die Datei wurde nicht gespeichert:\n{target}\n\n{exc}",
                )
                self.document_tabs.setCurrentWidget(document)
                return False

            document.path = target.resolve()
            document.custom_display_name = None
            if document.source_language() == "basic":
                self._last_opened_c64_basic_path = Path(document.path)
            if save_disassembly_source:
                # Aus der Binary-Ansicht wird nach dem Speichern eine normale
                # ASM-Quelle. Hex-Editor und Rohdaten-Editor zeigen danach
                # wieder denselben Textinhalt.
                document.binary_disassembly_mode = False
                document.encoding = "utf-8"
                document.newline = "\n"
                document._data_source = "text"
                document._syncing_views = True
                try:
                    document.hex_editor.set_data(data, modified=False)
                finally:
                    document._syncing_views = False
            document.update_syntax_highlighting()
            if document.source_language() == "basic":
                _show_keyboard, _profile = (
                    self._project_c64_screen_keyboard_configuration()
                )
                _keyboard_layout, _layout_profile = (
                    self._project_c64_keyboard_layout_configuration()
                )
                document.set_basic_keyboard_layout(_keyboard_layout)
                document.set_basic_screen_keyboard_visible(
                    _show_keyboard, notify=True
                )
            self._apply_document_theme(document)
            if previous_path != document.path:
                document.invalidate_assembly_result("Dateipfad geändert")
            document.mark_saved()
            self._update_document_tab(document)
            self.log(f"Datei gespeichert: {document.path}")
            self.statusBar().showMessage(f"Gespeichert: {document.path}")
            self._update_editor_status_panels()
            self._refresh_favorites_menu()
            if document.path.parent == self.current_directory:
                self.populate_file_list()
            self._remember_recent_file(document.path)

            # Stage 246: bei Speichern unter wandern Breakpoint-/Bookmark-Knoten
            # auf den neuen Dateipfad; verwaiste alte Dateiknoten werden entfernt.
            marker_changed = False
            if previous_path is not None and previous_path != document.path:
                marker_changed |= self._replace_project_marker_file(
                    "breakpoint", previous_path, (), mark_modified=True, persist=False
                )
                marker_changed |= self._replace_project_marker_file(
                    "bookmark", previous_path, (), mark_modified=True, persist=False
                )
            marker_changed |= self._sync_document_marker_to_project(
                document, "breakpoint", persist=False
            )
            marker_changed |= self._sync_document_marker_to_project(
                document, "bookmark", persist=False
            )
            if marker_changed and self.current_project_path is not None:
                self.save_project()
            return True

        @staticmethod
        def _document_output_path(
            document: DocumentEditor,
            filename: str,
        ) -> Path:
            """Zielpfad für einen gezielten Projektbaum-Compilelauf."""
            return _project_document_output_path(document, filename)

        @staticmethod
        def _assembler_output_path(
            document: DocumentEditor,
            assembly_source: str = "",
        ) -> Path:
            if document.path is None:
                raise AssemblerError(
                    "Der Quelltext muss vor dem Erzeugen eines Programms "
                    "gespeichert werden."
                )
            # Ein aus einer binaeren C64-Datei erzeugtes Disassembly darf
            # die Originaldatei niemals ueberschreiben. Das Build-Ergebnis
            # liegt deshalb separat neben der Quelle.
            if document.binary_disassembly_mode and document.build_target == "c64":
                return document.path.with_name(
                    document.path.stem + ".reassembled.prg"
                )

            suffix = ".prg"
            if document.build_target in {"pe32", "pe64"}:
                suffix = (
                    ".dll"
                    if getattr(document, "generated_source_kind", "program") == "library"
                    else ".exe"
                )
            elif document.build_target == "amiga":
                suffix = ".amiga"
                if assembly_source:
                    #from amiga500 import is_amiga_boot_source
                    if is_amiga_boot_source(assembly_source):
                        suffix = ".adf"
            return _project_document_output_path(
                document, document.path.with_suffix(suffix).name
            )

        @staticmethod
        def _basic_assembly_output_path(document: DocumentEditor) -> Path:
            if document.path is None:
                raise AssemblerError(
                    "Der BASIC-Quelltext muss zuerst gespeichert werden."
                )
            return _project_document_output_path(
                document, document.path.stem + ".generated.asm"
            )

        @staticmethod
        def _pascal_assembly_output_path(document: DocumentEditor) -> Path:
            if document.path is None:
                raise AssemblerError(
                    "Der Pascal-Quelltext muss zuerst gespeichert werden."
                )
            return _project_document_output_path(
                document,
                document.path.stem
                + (
                    ".generated.amiga.asm"
                    if document.build_target == "amiga"
                    else (
                        ".generated.pe64.asm"
                        if document.build_target == "pe64"
                        else (
                            ".generated.pe32.asm"
                            if document.build_target == "pe32"
                            else ".generated.asm"
                        )
                    )
                )
            )

        @staticmethod
        def _c_assembly_output_path(document: DocumentEditor) -> Path:
            if document.path is None:
                raise AssemblerError(
                    "Der C-Quelltext muss zuerst gespeichert werden."
                )
            return _project_document_output_path(
                document,
                document.path.stem
                + (
                    ".generated.amiga.asm"
                    if document.build_target == "amiga"
                    else (
                        ".generated.pe64.asm"
                        if document.build_target == "pe64"
                        else (
                            ".generated.pe32.asm"
                            if document.build_target == "pe32"
                            else ".generated.asm"
                        )
                    )
                )
            )

        @staticmethod
        def _write_assembled_program(path: Path, data: bytes) -> None:
            path.parent.mkdir(parents=True, exist_ok=True)
            file_descriptor, temporary_name = tempfile.mkstemp(
                prefix=f".{path.name}.",
                suffix=".tmp",
                dir=str(path.parent),
            )
            try:
                with os.fdopen(file_descriptor, "wb") as stream:
                    stream.write(data)
                    stream.flush()
                    os.fsync(stream.fileno())
                os.replace(temporary_name, path)
            except Exception:
                try:
                    os.unlink(temporary_name)
                except OSError:
                    pass
                raise

        def _finish_compile_stage(
            self,
            document: DocumentEditor,
            generated,
            assembly_path: Path,
            language_name: str,
            *,
            is_unit: bool = False,
        ) -> bool:
            """Beendet nur Compile: ASM speichern, aber noch nicht assemblieren."""
            try:
                generated = self._apply_project_ordinal_imports(
                    document, generated
                )
            except (PE32AssemblerError, PE64AssemblerError) as exc:
                message = str(exc)
                document.show_assembly_error(
                    message,
                    getattr(exc, "line", 0) or 0,
                    "Ordinalimport-Fehler",
                )
                self.show_error("Ordinalimporte konnten nicht erzeugt werden", message)
                self.statusBar().showMessage("Ordinalimport-Erzeugung fehlgeschlagen")
                return False
            open_assembly = self._find_open_document(assembly_path)
            if open_assembly is not None and open_assembly.is_modified:
                message = (
                    "Die erzeugte ASM-Datei ist bereits geöffnet und enthält "
                    "ungespeicherte Änderungen:\n"
                    f"{assembly_path}\n\n"
                    "Speichere oder schließe diese Registerkarte vor dem "
                    "erneuten Kompilieren."
                )
                document.show_assembly_error(
                    message,
                    status_text="Ausgabe ist geöffnet",
                )
                self.show_error("ASM-Ausgabe kann nicht ersetzt werden", message)
                return False

            try:
                self._write_assembled_program(
                    assembly_path,
                    generated.assembly.encode("utf-8"),
                )
            except OSError as exc:
                message = (
                    "Die erzeugte Assemblerdatei konnte nicht gespeichert werden:\n"
                    f"{assembly_path}\n\n{exc}"
                )
                document.show_assembly_error(
                    message,
                    status_text="Ausgabefehler",
                )
                self.show_error("ASM-Ausgabe konnte nicht gespeichert werden", message)
                return False

            if open_assembly is not None:
                open_assembly.raw_editor.setPlainText(generated.assembly)
                open_assembly.mark_saved()
                open_assembly.invalidate_assembly_result("Neu erzeugt")
                self._update_document_tab(open_assembly)

            document.invalidate_assembly_result("Neu kompiliert")
            document.set_generated_assembly(
                generated.assembly,
                assembly_path,
                select_tab=True,
            )
            document.generated_source_kind = getattr(
                generated, "source_kind", "program"
            )
            document.generated_linked_assembly_files = tuple(
                getattr(generated, "linked_assembly_files", ()) or ()
            )
            document.generated_pe32_modules = tuple(
                getattr(generated, "linked_pe32_modules", ()) or ()
            )
            document.generated_link_object_files = tuple(
                getattr(generated, "linked_object_files", ()) or ()
            )
            if document.is_dbase_document:
                document.set_dbase_debug_visible(
                    bool(getattr(generated, "uses_debug_output", False))
                )
            if is_unit:
                document.assemble_generated_button.setEnabled(False)
                document.generated_assembly_status_label.setText(
                    "Unit-ASM erzeugt – kein eigenständiges Programm"
                )

            target_name = document._build_target_name()
            warnings = tuple(getattr(generated, "warnings", ()) or ())
            notes = tuple(getattr(generated, "notes", ()) or ())
            diagnostic_lines = []
            if notes:
                diagnostic_lines.append("Hinweise:")
                diagnostic_lines.extend(f"  {item}" for item in notes)
            if warnings:
                if diagnostic_lines:
                    diagnostic_lines.append("")
                diagnostic_lines.append("Warnungen:")
                diagnostic_lines.extend(f"  {item}" for item in warnings)
            diagnostics = (
                "\n\n" + "\n".join(diagnostic_lines)
                if diagnostic_lines
                else ""
            )
            unit_note = (
                "\nProgramm     : Unit – kein eigenständiges Programm"
                if is_unit
                else "\nProgramm     : noch nicht erzeugt – jetzt Assemble verwenden"
            )
            document.hints_editor.setPlainText(
                f"{language_name} erfolgreich nach {target_name}-Assembler "
                "kompiliert\n\n"
                f"Quelle       : {document.display_name}\n"
                f"Assembler    : {assembly_path}"
                f"{unit_note}"
                f"{diagnostics}"
            )
            document.assembly_status_label.setText(
                f"ASM erzeugt: {assembly_path.name}"
            )
            if is_unit and getattr(document, "generated_unit_coff_paths", ()):
                unit_paths = tuple(
                    Path(item).expanduser().resolve()
                    for item in document.generated_unit_coff_paths
                )
                document.hints_editor.appendPlainText(
                    "\nUNIT-Objekt  : "
                    + ", ".join(path.name for path in unit_paths)
                )
                document.generated_assembly_status_label.setText(
                    "UNIT-COFF erzeugt: "
                    + ", ".join(path.name for path in unit_paths)
                )
            self.log(
                f"COMPILE {language_name.upper()}: "
                f"{document.display_name} -> {assembly_path.name} "
                f"({target_name})"
            )
            message = (
                f"{language_name} mit {len(warnings)} Warnung(en) nach "
                f"Assembler kompiliert: {assembly_path.name}"
                if warnings
                else f"{language_name} nach Assembler kompiliert: "
                f"{assembly_path.name}"
            )
            self.statusBar().showMessage(message)
            if assembly_path.parent == self.current_directory:
                self.populate_file_list()
            return True

        @staticmethod
        def _logo_assembly_output_path(document: DocumentEditor) -> Path:
            if document.path is None:
                raise AssemblerError("Der LOGO-Quelltext muss zuerst gespeichert werden.")
            if document.build_target != "pe32":
                raise AssemblerError("LOGO unterstützt im ersten Stand ausschließlich Windows PE32.")
            return _project_document_output_path(
                document, document.path.stem + ".generated.pe32.asm"
            )

        @staticmethod
        def _dbase_assembly_output_path(document: DocumentEditor) -> Path:
            if document.path is None:
                raise AssemblerError("Der dBase-Quelltext muss zuerst gespeichert werden.")
            if document.build_target not in {"pe32", "pe64"}:
                raise AssemblerError("dBase unterstützt nur Windows PE32 und Windows PE32+/PE64.")
            suffix = ".generated.pe64.asm" if document.build_target == "pe64" else ".generated.pe32.asm"
            return _project_document_output_path(
                document, document.path.stem + suffix
            )

        @staticmethod
        def _prolog_assembly_output_path(document: DocumentEditor) -> Path:
            if document.path is None:
                raise AssemblerError("Der PROLOG-Quelltext muss zuerst gespeichert werden.")
            if document.build_target not in {"pe32", "pe64"}:
                raise AssemblerError("PROLOG unterstützt nur Windows PE32 und Windows PE64/PE32+.")
            suffix = ".generated.pe64.asm" if document.build_target == "pe64" else ".generated.pe32.asm"
            return _project_document_output_path(
                document, document.path.stem + suffix
            )

        @staticmethod
        def _lisp_assembly_output_path(document: DocumentEditor) -> Path:
            if document.path is None:
                raise AssemblerError("Der LISP-Quelltext muss zuerst gespeichert werden.")
            if document.build_target not in {"pe32", "pe64"}:
                raise AssemblerError("LISP unterstützt derzeit nur Windows PE32 und Windows PE64/PE32+.")
            suffix = ".generated.pe64.asm" if document.build_target == "pe64" else ".generated.pe32.asm"
            return _project_document_output_path(
                document, document.path.stem + suffix
            )

        def _compile_basic_document(self, document: DocumentEditor) -> bool:
            """C64 BASIC -> editierbarer MOS-6510-Assemblercode."""
            if document.build_target != "c64":
                document.set_build_target("c64")
            try:
                from c64basic import C64BasicError, compile_basic_to_assembly
                source = document.basic_source_for_compiler()
                assembly_path = self._basic_assembly_output_path(document)
                _optimizer_enabled, _optimizer_strategy, _optimizer_profile = (
                    self._project_c64_optimizer_configuration()
                )
                generated = compile_basic_to_assembly(
                    source,
                    filename=str(document.path),
                    target="c64",
                    optimizer_enabled=_optimizer_enabled,
                    optimizer_strategy=_optimizer_strategy,
                )
                self.statusBar().showMessage(
                    "C64 BASIC Optimizer: "
                    + (
                        f"{_optimizer_profile} / {_optimizer_strategy}"
                        if _optimizer_enabled else f"{_optimizer_profile} / deaktiviert"
                    )
                )
            except (ImportError, C64BasicError, ValueError) as exc:
                message = str(exc)
                error_line = getattr(exc, "line", 0) or 0
                document.show_assembly_error(
                    message,
                    error_line,
                    "Compilerfehler",
                )
                self.show_error("BASIC-Compilerfehler", message)
                self.statusBar().showMessage("BASIC-Kompilierung fehlgeschlagen")
                return False
            return self._finish_compile_stage(
                document, generated, assembly_path, "C64 BASIC"
            )

        def _pascal_progress_source_files(
            self,
            document: DocumentEditor,
        ) -> Tuple[Path, ...]:
            """Bekannte Pascal-Quellen für die Stage-198-Dateigewichtung."""
            result: List[Path] = []
            seen = set()

            def add(path) -> None:
                if path is None:
                    return
                try:
                    candidate = Path(path).expanduser().resolve()
                except (OSError, RuntimeError, ValueError):
                    candidate = Path(path).expanduser().absolute()
                if candidate.suffix.casefold() not in DocumentEditor.PASCAL_EXTENSIONS:
                    return
                key = str(candidate).casefold()
                if key in seen:
                    return
                seen.add(key)
                result.append(candidate)

            add(document.path)

            # Bei einem Stage-197-Pascal-Projekt sind die Unit-/Modulquellen
            # bereits im Projektbaum bekannt. Sie werden vor dem Workerstart
            # eingerechnet; zusätzlich entdeckte USES-Units fügt der Worker
            # während des Compilerlaufs dynamisch hinzu.
            if document.build_target in {"pe32", "pe64"}:
                for group_name in ("units", "modules"):
                    try:
                        project_paths = self._project_pascal_group_paths(
                            document.build_target,
                            group_name,
                        )
                    except Exception:
                        project_paths = ()
                    for project_path in project_paths:
                        add(project_path)

            return tuple(result)

        def _run_pascal_compile_worker(
            self,
            document: DocumentEditor,
            compile_callable,
            source_files: Sequence[Path],
        ):
            """QThread-Compile mit lokalem EventLoop für Stage-197-Kompatibilität.

            Der lokale EventLoop hält Qt vollständig reaktionsfähig, während
            die Methode synchron erst nach dem Compilerlauf zurückkehrt. Damit
            bleiben die bestehenden F2-/Projekt-Build-Ketten unverändert.
            """
            if document._pascal_compile_running:
                raise RuntimeError("Eine Pascal-Kompilierung läuft bereits.")

            source_files = tuple(source_files) or (
                (document.path,) if document.path is not None else ()
            )
            document.begin_pascal_compile_progress(len(source_files))

            thread = QThread(self)
            worker = PascalCompileWorker(
                compile_callable,
                source_files,
                editor_filename=document.path,
                editor_line_count=document.raw_editor.document().blockCount(),
            )
            worker.moveToThread(thread)

            event_loop = QEventLoop(self)
            state = {"result": None, "error": None}

            def succeeded(result) -> None:
                state["result"] = result

            def failed(exc) -> None:
                state["error"] = exc

            thread.started.connect(worker.run)
            worker.progress.connect(document.set_pascal_compile_progress)
            worker.status.connect(document.set_pascal_compile_status)
            worker.succeeded.connect(succeeded)
            worker.failed.connect(failed)
            worker.succeeded.connect(worker.deleteLater)
            worker.failed.connect(worker.deleteLater)
            worker.succeeded.connect(thread.quit)
            worker.failed.connect(thread.quit)
            thread.finished.connect(event_loop.quit)
            thread.finished.connect(thread.deleteLater)

            # Referenzen für die Dauer des verschachtelten EventLoops halten.
            document._pascal_compile_thread = thread
            document._pascal_compile_worker = worker

            thread.start()
            event_loop.exec_()

            # Der EventLoop endet erst mit QThread.finished. Damit bleibt die
            # Stage-197-Aufrufkette synchron, ohne einen laufenden Thread
            # zurückzulassen oder die Qt-Ereignisverarbeitung zu blockieren.
            error = state["error"]
            success = error is None
            document.finish_pascal_compile_progress(success)
            document._pascal_compile_thread = None
            document._pascal_compile_worker = None

            if error is not None:
                raise error
            return state["result"]

        def _compile_pascal_document(self, document: DocumentEditor) -> bool:
            """ANTLR-Pascal -> zielabhängiger ASM-Code; kein Binärprogramm."""
            if document._pascal_compile_running:
                self.statusBar().showMessage("Pascal-Kompilierung läuft bereits")
                return False
            source = document.raw_editor.toPlainText()
            try:
                pascal_frontend_sync = prepare_pascal_frontend_for_compile(
                    document.path
                )
                from c64pascal import C64PascalError, compile_pascal_to_assembly
            except ImportError as exc:
                message = (
                    "Der ANTLR-basierte Pascal-Compiler konnte nicht geladen "
                    "werden. Stelle sicher, dass der Ordner 'c64pascal' neben "
                    "d64_dism.py liegt und installiere:\n\n"
                    "py -m pip install antlr4-python3-runtime==4.13.2\n\n"
                    f"Technischer Fehler: {exc}"
                )
                document.show_assembly_error(
                    message,
                    status_text="Compiler nicht verfügbar",
                )
                self.show_error("Pascal-Compiler nicht verfügbar", message)
                return False

            if pascal_frontend_sync.get("ready"):
                self.log(
                    "PASCAL FRONTEND: compiler="
                    + str(pascal_frontend_sync.get("compiler", ""))
                    + "; lexer="
                    + str(pascal_frontend_sync.get("lexer", ""))
                    + "; parser="
                    + str(pascal_frontend_sync.get("parser", ""))
                    + (
                        "; ANTLR regenerated"
                        if pascal_frontend_sync.get("regenerated")
                        else ""
                    )
                )

            try:
                compiler_parameters = inspect.signature(
                    compile_pascal_to_assembly
                ).parameters.values()
                compiler_supports_target = any(
                    parameter.name == "target"
                    or parameter.kind is inspect.Parameter.VAR_KEYWORD
                    for parameter in compiler_parameters
                )
            except (TypeError, ValueError):
                compiler_supports_target = False

            if not compiler_supports_target:
                compiler_file = inspect.getsourcefile(
                    compile_pascal_to_assembly
                ) or getattr(
                    sys.modules.get(compile_pascal_to_assembly.__module__),
                    "__file__",
                    "<unbekannt>",
                )
                message = (
                    "Die geladene Pascal-Compiler-Version ist zu alt für "
                    "die Zielauswahl C-64/Amiga/Windows PE32/Windows PE64. Ihre Funktion "
                    "compile_pascal_to_assembly() besitzt keinen Parameter "
                    "'target'.\n\nGeladenes Modul:\n"
                    f"{compiler_file}"
                )
                document.show_assembly_error(
                    message,
                    status_text="Pascal-Compiler ist veraltet",
                )
                self.show_error("Pascal-Compiler ist veraltet", message)
                return False

            try:
                assembly_path = self._pascal_assembly_output_path(document)
                include_paths = [
                    document.path.parent,
                    ".",
                    "./include",
                    self.current_directory,
                ]
                if self.workspace_root not in include_paths:
                    include_paths.append(self.workspace_root)
                _project_output_directory = (
                    self._document_windows_output_path(document)
                    if document.build_target in {"pe32", "pe64"}
                    else None
                )
                if (
                    _project_output_directory is not None
                    and _project_output_directory not in include_paths
                ):
                    include_paths.append(_project_output_directory)
                compiler_kwargs = {
                    "filename": str(document.path),
                    "include_paths": include_paths,
                    "target": document.build_target,
                }
                try:
                    parameter_map = inspect.signature(
                        compile_pascal_to_assembly
                    ).parameters
                except (TypeError, ValueError):
                    parameter_map = {}
                if document.build_target == "amiga":
                    if "cpu_model" in parameter_map:
                        compiler_kwargs["cpu_model"] = document.amiga_cpu_model
                    if "fpu_model" in parameter_map:
                        compiler_kwargs["fpu_model"] = document.amiga_fpu_model
                if document.build_target in {"pe32", "pe64"}:
                    if "graphics_backend" in parameter_map:
                        compiler_kwargs["graphics_backend"] = (
                            document.windows_graphics_backend
                        )
                    if "windows_application_mode" in parameter_map:
                        compiler_kwargs["windows_application_mode"] = (
                            document.windows_application_mode
                        )
                    if "predefined_macros" in parameter_map:
                        compiler_kwargs["predefined_macros"] = (
                            windows_application_predefined_macros(
                                document.windows_application_mode, document.build_target
                            )
                        )
                    if (
                        "breakpoint_lines" in parameter_map
                        and normalize_windows_application_mode(
                            document.windows_application_mode
                        ) == "Console"
                    ):
                        _editor_breakpoints = set(
                            document.raw_editor.breakpoint_lines()
                        )
                        _project_breakpoints = set()
                        if document.path is not None:
                            _project_breakpoints.update(
                                self._project_marker_lines_for_path(
                                    "breakpoint", document.path
                                )
                            )
                        _breakpoint_lines = tuple(
                            sorted(_editor_breakpoints | _project_breakpoints)
                        )
                        compiler_kwargs["breakpoint_lines"] = _breakpoint_lines
                        if _breakpoint_lines:
                            self.log(
                                "PASCAL DEBUG BREAKPOINTS: "
                                + ", ".join(str(line) for line in _breakpoint_lines)
                            )
                _project_link_search_paths = (
                    self._project_windows_link_search_paths(document.build_target)
                    if document.build_target in {"pe32", "pe64"}
                    else ()
                )
                pascal_preprocessed = preprocess_pascal_source(
                    source,
                    filename=str(document.path),
                    predefined_macros=compiler_kwargs.get(
                        "predefined_macros", {}
                    ),
                    link_search_paths=_project_link_search_paths,
                )
                if "predefined_macros" in parameter_map:
                    compiler_kwargs["predefined_macros"] = dict(
                        pascal_preprocessed.macros
                    )
                if "link_search_paths" in parameter_map:
                    compiler_kwargs["link_search_paths"] = tuple(
                        str(path) for path in _project_link_search_paths
                    )
                if "output_directory" in parameter_map:
                    compiler_kwargs["output_directory"] = (
                        str(_project_output_directory)
                        if _project_output_directory is not None
                        else None
                    )
                self.log(
                    "PASCAL PREPROCESS: "
                    f"Kommentare={pascal_preprocessed.removed_comment_count}; "
                    f"Direktiven={len(pascal_preprocessed.directives)}; "
                    f"Defines={len(pascal_preprocessed.defined_symbols)}; "
                    f"Zeilen={pascal_preprocessed.original_line_count}"
                )
                for _pascal_warning in pascal_preprocessed.warnings:
                    self.log("PASCAL PREPROCESS: " + _pascal_warning)
                source = pascal_preprocessed.source
                if "linked_object_files" in parameter_map:
                    compiler_kwargs["linked_object_files"] = tuple(
                        getattr(pascal_preprocessed, "link_files", ()) or ()
                    )
                pascal_progress_sources = self._pascal_progress_source_files(
                    document
                )

                def _compile_in_worker(progress_callback):
                    worker_kwargs = dict(compiler_kwargs)
                    if "progress_callback" in parameter_map:
                        worker_kwargs["progress_callback"] = progress_callback
                    return compile_pascal_to_assembly(
                        source, **worker_kwargs
                    )

                generated = self._run_pascal_compile_worker(
                    document,
                    _compile_in_worker,
                    pascal_progress_sources,
                )
                # Stage 183: {$L file.o}/{$LINK file.o} is consumed by the IDE
                # preprocessor before c64pascal sees the source. Merge those
                # object/archive paths back into the compiler result so the
                # existing internal COFF link path receives them.
                if hasattr(generated, "linked_object_files"):
                    generated = replace(
                        generated,
                        linked_object_files=tuple(
                            dict.fromkeys(
                                list(getattr(generated, "linked_object_files", ()) or ())
                                + list(getattr(pascal_preprocessed, "link_files", ()) or ())
                            )
                        ),
                    )
                # Vor dem sofortigen Unit-COFF-Schritt umschreiben, damit
                # nicht nur die sichtbare ASM-Datei, sondern auch die in der
                # .drectve-Sektion gespeicherten Importmetadaten Ordinale sind.
                generated = self._apply_project_ordinal_imports(
                    document, generated
                )
                # Stage 171: A Pascal UNIT for Windows immediately receives an
                # architecture-specific relocatable COFF companion on Compile.
                # This is in addition to the existing F2/.o path.
                if (
                    getattr(generated, "source_kind", "program") == "unit"
                    and document.build_target in {"pe32", "pe64"}
                ):
                    unit_object_path = _pascal_unit_coff_output_path(
                        document.path,
                        document.build_target,
                        output_directory=_project_output_directory,
                    )
                    try:
                        unit_object_data = (
                            assemble_pe64_coff_object(
                                generated.assembly,
                                filename=assembly_path.name,
                            )
                            if document.build_target == "pe64"
                            else assemble_pe32_coff_object(
                                generated.assembly,
                                filename=assembly_path.name,
                            )
                        )
                        _write_cli_file(unit_object_path, unit_object_data)
                        document.generated_unit_coff_paths = (
                            unit_object_path,
                        )
                    except (OSError, PE32AssemblerError, PE64AssemblerError) as exc:
                        message = str(exc)
                        document.show_assembly_error(
                            message,
                            getattr(exc, "line", 0) or 0,
                            "UNIT-COFF-Fehler",
                        )
                        self.show_error(
                            "Pascal-UNIT-COFF konnte nicht erzeugt werden",
                            message,
                        )
                        self.statusBar().showMessage(
                            "Pascal-UNIT-COFF-Erzeugung fehlgeschlagen"
                        )
                        return False
            except PascalPreprocessorError as exc:
                message = str(exc)
                document.show_assembly_error(
                    message,
                    getattr(exc, "line", 0) or 0,
                    "Pascal-Vorverarbeitungsfehler",
                )
                self.show_error("Pascal-Vorverarbeitungsfehler", message)
                self.statusBar().showMessage("Pascal-Vorverarbeitung fehlgeschlagen")
                return False
            except (PE32AssemblerError, PE64AssemblerError) as exc:
                message = str(exc)
                document.show_assembly_error(
                    message,
                    getattr(exc, "line", 0) or 0,
                    "Ordinalimport-Fehler",
                )
                self.show_error("Ordinalimporte konnten nicht erzeugt werden", message)
                self.statusBar().showMessage("Ordinalimport-Erzeugung fehlgeschlagen")
                return False
            except C64PascalError as exc:
                message = str(exc)
                if not pascal_frontend_sync.get("ready"):
                    message += (
                        "\n\nPascal-Frontend-Synchronisierung: "
                        + str(pascal_frontend_sync.get("reason", "unbekannt"))
                        + "\nParser: "
                        + str(pascal_frontend_sync.get("parser", ""))
                    )
                document.show_assembly_error(
                    message,
                    exc.line or 0,
                    "Compilerfehler",
                )
                self.show_error("Pascal-Compilerfehler", message)
                self.statusBar().showMessage("Pascal-Kompilierung fehlgeschlagen")
                return False

            return self._finish_compile_stage(
                document,
                generated,
                assembly_path,
                "Pascal",
                is_unit=(
                    getattr(generated, "source_kind", "program") == "unit"
                ),
            )

        def _compile_c_document(self, document: DocumentEditor) -> bool:
            """ANTLR-C -> zielabhängiger ASM-Code; kein Binärprogramm."""
            source = document.raw_editor.toPlainText()
            try:
                from c64c import C64CError, compile_c_to_assembly
            except ImportError as exc:
                message = (
                    "Der ANTLR-basierte C-Compiler konnte nicht geladen "
                    "werden. Stelle sicher, dass die Ordner 'c64c' und "
                    "'c64pascal' neben d64_dism.py liegen und installiere:\n\n"
                    "py -m pip install antlr4-python3-runtime==4.13.2\n\n"
                    f"Technischer Fehler: {exc}"
                )
                document.show_assembly_error(
                    message,
                    status_text="Compiler nicht verfügbar",
                )
                self.show_error("C-Compiler nicht verfügbar", message)
                return False

            try:
                assembly_path = self._c_assembly_output_path(document)
                include_paths = [
                    document.path.parent,
                    ".",
                    "./include",
                    self.current_directory,
                ]
                if self.workspace_root not in include_paths:
                    include_paths.append(self.workspace_root)
                compiler_kwargs = {
                    "filename": str(document.path),
                    "include_paths": include_paths,
                    "target": document.build_target,
                }
                try:
                    parameter_map = inspect.signature(
                        compile_c_to_assembly
                    ).parameters
                except (TypeError, ValueError):
                    parameter_map = {}
                if document.build_target == "amiga":
                    if "cpu_model" in parameter_map:
                        compiler_kwargs["cpu_model"] = document.amiga_cpu_model
                    if "fpu_model" in parameter_map:
                        compiler_kwargs["fpu_model"] = document.amiga_fpu_model
                if document.build_target in {"pe32", "pe64"}:
                    if "graphics_backend" in parameter_map:
                        compiler_kwargs["graphics_backend"] = (
                            document.windows_graphics_backend
                        )
                    if "windows_application_mode" in parameter_map:
                        compiler_kwargs["windows_application_mode"] = (
                            document.windows_application_mode
                        )
                    if "predefined_macros" in parameter_map:
                        compiler_kwargs["predefined_macros"] = (
                            windows_application_predefined_macros(
                                document.windows_application_mode, document.build_target
                            )
                        )
                generated = compile_c_to_assembly(source, **compiler_kwargs)
            except C64CError as exc:
                message = str(exc)
                error_line = 0
                if exc.line and exc.filename:
                    try:
                        if Path(exc.filename).resolve() == document.path.resolve():
                            error_line = exc.line
                    except (OSError, RuntimeError):
                        pass
                document.show_assembly_error(
                    message,
                    error_line,
                    "Compilerfehler",
                )
                self.show_error("C-Compilerfehler", message)
                self.statusBar().showMessage("C-Kompilierung fehlgeschlagen")
                return False

            return self._finish_compile_stage(
                document,
                generated,
                assembly_path,
                "C",
            )

        def _compile_lisp_document(self, document: DocumentEditor) -> bool:
            """LISP -> IA-32/AMD64-Assembler; Binärstufen bleiben intern in d64_dism."""
            if document.build_target not in {"pe32", "pe64"}:
                document.set_build_target("pe32")
            source = document.raw_editor.toPlainText()
            try:
                from d64lisp import LispCompilerError, compile_lisp_to_assembly
                assembly_path = self._lisp_assembly_output_path(document)
                generated = compile_lisp_to_assembly(
                    source,
                    filename=str(document.path),
                    target=document.build_target,
                    windows_application_mode=document.windows_application_mode,
                )
            except (ImportError, LispCompilerError, AssemblerError) as exc:
                message = str(exc)
                error_line = getattr(exc, "line", 0) or 0
                document.show_assembly_error(message, error_line, "Compilerfehler")
                self.show_error("LISP-Compilerfehler", message)
                self.statusBar().showMessage("LISP-Kompilierung fehlgeschlagen")
                return False
            is_module = getattr(generated, "source_kind", "program") == "unit"
            ok = self._finish_compile_stage(
                document, generated, assembly_path, "LISP", is_unit=is_module,
            )
            if ok and is_module:
                document.generated_assembly_status_label.setText(
                    "LISP-Modul-ASM erzeugt – F2 erzeugt COFF32/COFF64"
                )
                document.hints_editor.appendPlainText(
                    "\nLISP-Modul    : kein _start; beim Hauptprogramm als .o linken"
                )
            return ok

        def _compile_prolog_document(self, document: DocumentEditor) -> bool:
            """PROLOG -> IA-32/AMD64-Assembler; Assemblieren/Linken bleibt intern."""
            if document.build_target not in {"pe32", "pe64"}:
                document.set_build_target("pe32")
            source = document.raw_editor.toPlainText()
            try:
                from d64prolog import PrologCompilerError, compile_prolog_to_assembly
                assembly_path = self._prolog_assembly_output_path(document)
                generated = compile_prolog_to_assembly(
                    source,
                    filename=str(document.path),
                    target=document.build_target,
                    windows_application_mode=document.windows_application_mode,
                    verbose=document.prolog_verbose,
                )
            except (ImportError, PrologCompilerError, AssemblerError) as exc:
                message = str(exc)
                error_line = getattr(exc, "line", 0) or 0
                document.show_assembly_error(message, error_line, "Compilerfehler")
                self.show_error("PROLOG-Compilerfehler", message)
                self.statusBar().showMessage("PROLOG-Kompilierung fehlgeschlagen")
                return False
            return self._finish_compile_stage(
                document, generated, assembly_path, "PROLOG"
            )

        def _compile_dbase_document(self, document: DocumentEditor) -> bool:
            """dBase -> IA-32/AMD64-Assembler mit eigener Qt5-GUI-Runtime."""
            if document.build_target not in {"pe32", "pe64"}:
                document.set_build_target("pe32")
            # dBase besitzt ab dieser Stufe immer eine eigene Qt5-GUI.
            document.set_windows_application_mode("GUI")
            source = document.raw_editor.toPlainText()
            try:
                from d64dbase import DBaseCompilerError, compile_dbase_to_assembly
                assembly_path = self._dbase_assembly_output_path(document)
                generated = compile_dbase_to_assembly(
                    source,
                    filename=str(document.path),
                    target=document.build_target,
                    windows_application_mode=document.windows_application_mode,
                )
            except (ImportError, DBaseCompilerError, AssemblerError) as exc:
                message = str(exc)
                error_line = getattr(exc, "line", 0) or 0
                document.show_assembly_error(message, error_line, "Compilerfehler")
                self.show_error("dBase-Compilerfehler", message)
                self.statusBar().showMessage("dBase-Kompilierung fehlgeschlagen")
                return False
            return self._finish_compile_stage(
                document, generated, assembly_path, "dBase"
            )

        def _compile_logo_document(self, document: DocumentEditor) -> bool:
            """LOGO -> nativer IA-32-Assembler fuer Console oder 320x200-GUI."""
            if document.build_target != "pe32":
                document.set_build_target("pe32")
            source = document.raw_editor.toPlainText()
            try:
                from d64logo import LogoCompilerError, compile_logo_to_assembly
                assembly_path = self._logo_assembly_output_path(document)
                generated = compile_logo_to_assembly(
                    source,
                    filename=str(document.path),
                    target="pe32",
                    windows_application_mode=document.windows_application_mode,
                )
            except (ImportError, LogoCompilerError, AssemblerError) as exc:
                message = str(exc)
                error_line = getattr(exc, "line", 0) or 0
                document.show_assembly_error(message, error_line, "Compilerfehler")
                self.show_error("LOGO-Compilerfehler", message)
                self.statusBar().showMessage("LOGO-Kompilierung fehlgeschlagen")
                return False
            return self._finish_compile_stage(
                document, generated, assembly_path, "LOGO"
            )

        def create_coff32_object_document(
            self,
            document: DocumentEditor,
        ) -> bool:
            """Erzeugt PE32/PE64-Hauptmodul und Abhaengigkeiten als COFF-Objekte."""
            if not isinstance(document, DocumentEditor):
                return False
            self.document_tabs.setCurrentWidget(document)
            if document.build_target not in {"pe32", "pe64"}:
                self.show_error(
                    "COFF nur für Windows",
                    "Wähle zuerst das Ziel 'Windows PE32' oder 'Windows PE64'.",
                )
                return False
            is64 = document.build_target == "pe64"
            label = "COFF64" if is64 else "COFF32"
            source = document.generated_assembly_editor.toPlainText()
            if not source.strip():
                self.show_error(
                    f"Keine {'PE64' if is64 else 'PE32'}-Assemblerdaten",
                    "Kompiliere zuerst die Pascal-, C-, LISP-, PROLOG-, LOGO- oder dBase-Quelle.",
                )
                return False
            if document.path is None and not self._save_document(document, save_as=True):
                return False

            assembly_path = (
                document.generated_assembly_path
                if document.generated_assembly_path is not None
                else document.path.with_suffix(".generated.pe64.asm" if is64 else ".generated.pe32.asm")
            )
            proxy = argparse.Namespace(
                assembly=source,
                linked_pe32_modules=getattr(document, "generated_pe32_modules", ()),
                linked_assembly_files=getattr(document, "generated_linked_assembly_files", ()),
            )
            writer = _write_pe64_generated_objects if is64 else _write_pe32_generated_objects
            error_type = PE64AssemblerError if is64 else PE32AssemblerError
            _project_output_directory = self._document_windows_output_path(document)
            try:
                object_paths = writer(
                    proxy,
                    source_path=document.path,
                    assembly_path=assembly_path,
                    main_object_path=self._project_generated_object_path(
                        document.path,
                        document.build_target,
                        output_directory=_project_output_directory,
                    ),
                    output_directory=_project_output_directory,
                )
                if (
                    document.is_pascal_document
                    and str(getattr(document, "generated_source_kind", "program")).casefold() == "unit"
                    and object_paths
                ):
                    unit_companion = _write_pascal_unit_coff_companion(
                        object_paths[0],
                        document.path,
                        document.build_target,
                        output_directory=_project_output_directory,
                    )
                    if unit_companion not in object_paths:
                        object_paths.append(unit_companion)
                    document.generated_unit_coff_paths = (
                        unit_companion,
                    )
            except (OSError, error_type) as exc:
                message = str(exc)
                document.show_generated_assembly_error(
                    message, getattr(exc, "line", 0) or 0, f"{label}-Fehler"
                )
                self.show_error(f"{label}-Objekt konnte nicht erzeugt werden", message)
                return False

            details=[]; total_size=0
            for path in object_paths:
                try: size=path.stat().st_size
                except OSError: size=0
                total_size += size; details.append(f"  {path.name} ({size} Bytes)")
            document.hints_editor.setPlainText(
                f"{label}-Objekt(e) erfolgreich erzeugt\n\n"
                f"Quelle : {document.display_name}\nObjekte:\n"
                + "\n".join(details)
                + f"\nGesamt : {total_size} Bytes\n"
                + ("Format : Microsoft COFF AMD64 / relocierbar\n" if is64
                   else "Format : Microsoft COFF i386 / relocierbar\n")
            )
            document.generated_assembly_status_label.setText(
                f"{label} erzeugt: {len(object_paths)} Objekt(e)"
            )
            self.log(f"{label} OBJECTS: {document.display_name} -> " + ", ".join(path.name for path in object_paths))
            self.statusBar().showMessage(f"{label} erzeugt: {len(object_paths)} Objekt(e)")
            if any(path.parent.resolve() == self.current_directory for path in object_paths):
                self.populate_file_list()
            return True

        def assemble_generated_document(
            self,
            document: DocumentEditor,
            extra_link_inputs: Sequence[Path] = (),
        ) -> bool:
            """Übersetzt den editierbaren ASM-Tab für das gewählte Ziel.

            ``extra_link_inputs`` wird vom vereinheitlichten F2-Projektbuild
            benutzt. So koennen bereits erzeugte .o/.obj- und .a/.lib-Dateien
            der Projektliste beim Hauptprogramm automatisch mitgelinkt werden.
            """
            if not isinstance(document, DocumentEditor):
                return False
            self.document_tabs.setCurrentWidget(document)
            if not (
                document.is_basic_document
                or document.is_pascal_document
                or document.is_c_document
                or document.is_lisp_document
                or document.is_prolog_document
                or document.is_logo_document
                or document.is_dbase_document
            ):
                return False

            assembly_source = (
                document.generated_assembly_editor.toPlainText()
            )
            if not assembly_source.strip():
                message = (
                    "Es sind noch keine ASM-Daten vorhanden. Kompiliere "
                    "zuerst den BASIC-, C-, Pascal-, LISP-, PROLOG-, LOGO- oder dBase-Quelltext."
                )
                document.show_generated_assembly_error(
                    message,
                    status_text="Keine ASM-Daten",
                )
                self.show_error("Keine ASM-Daten", message)
                return False

            packer_stats = None
            try:
                #from amiga500 import (
                #    AmigaAssemblerError,
                #    assemble_amiga_boot_source,
                #    assemble_amiga_source,
                #    is_amiga_boot_source,
                #)
                amiga_bootable = (
                    document.build_target == "amiga"
                    and is_amiga_boot_source(assembly_source)
                )
                output_path = self._assembler_output_path(
                    document,
                    assembly_source,
                )
                # dBase-EXE liegt nach dem Linken bewusst im aktuellen
                # Arbeitsverzeichnis der IDE. Der Start-Button sucht genau
                # dieses bereits erzeugte Artefakt und startet niemals einen Build.
                if (
                    document.is_dbase_document
                    and document.build_target in {"pe32", "pe64"}
                    and getattr(document, "generated_source_kind", "program") != "library"
                ):
                    output_path = (self.current_directory / output_path.name).resolve()
                assembly_path = document.generated_assembly_path
                if assembly_path is None:
                    if document.is_basic_document:
                        assembly_path = self._basic_assembly_output_path(document)
                    elif document.is_pascal_document:
                        assembly_path = self._pascal_assembly_output_path(document)
                    elif document.is_lisp_document:
                        assembly_path = self._lisp_assembly_output_path(document)
                    elif document.is_prolog_document:
                        assembly_path = self._prolog_assembly_output_path(document)
                    elif document.is_logo_document:
                        assembly_path = self._logo_assembly_output_path(document)
                    elif document.is_dbase_document:
                        assembly_path = self._dbase_assembly_output_path(document)
                    else:
                        assembly_path = self._c_assembly_output_path(document)
                if document.build_target == "amiga":
                    assembler = (
                        assemble_amiga_boot_source
                        if amiga_bootable
                        else assemble_amiga_source
                    )
                    program = assembler(
                        assembly_source,
                        filename=assembly_path.name,
                        cpu_model=document.amiga_cpu_model,
                        fpu_model=document.amiga_fpu_model,
                    )
                elif document.build_target in {"pe32", "pe64"}:
                    is64 = document.build_target == "pe64"
                    proxy = argparse.Namespace(
                        assembly=assembly_source,
                        linked_pe32_modules=getattr(
                            document, "generated_pe32_modules", ()
                        ),
                        linked_assembly_files=getattr(
                            document, "generated_linked_assembly_files", ()
                        ),
                    )
                    object_writer = (
                        _write_pe64_generated_objects if is64
                        else _write_pe32_generated_objects
                    )
                    _project_output_directory = self._document_windows_output_path(document)
                    object_paths = object_writer(
                        proxy,
                        source_path=document.path,
                        assembly_path=assembly_path,
                        output_directory=_project_output_directory,
                    )
                    # Bereits erzeugte Projektobjekte/-archive beim F2-Build
                    # eines Hauptprogramms ebenfalls an den internen Linker
                    # uebergeben. Duplikate werden pfadbezogen entfernt.
                    known_inputs = {
                        str(Path(path).expanduser().resolve()).casefold()
                        for path in object_paths
                    }
                    # dBase #pragma link: vorhandene .o/.obj/.a/.lib-Dateien
                    # werden als echte Linkereingaben uebernommen, nicht als ASM.
                    pragma_inputs = tuple(
                        getattr(document, "generated_link_object_files", ()) or ()
                    )
                    for pragma_name in pragma_inputs:
                        pragma_path = self._resolve_project_link_input(
                            pragma_name,
                            source_path=document.path,
                            target=document.build_target,
                        )
                        key = str(pragma_path).casefold()
                        if key in known_inputs:
                            continue
                        if not pragma_path.is_file():
                            raise PE64AssemblerError(
                                f"Linkdatei nicht gefunden (inkl. Projekt-Suchpfade): {pragma_path}"
                            ) if is64 else PE32AssemblerError(
                                f"Linkdatei nicht gefunden (inkl. Projekt-Suchpfade): {pragma_path}"
                            )
                        if pragma_path.suffix.casefold() not in {".o", ".obj", ".a", ".lib"}:
                            raise PE64AssemblerError(
                                f"Linkeingabe erwartet .o/.obj/.a/.lib: {pragma_path}"
                            ) if is64 else PE32AssemblerError(
                                f"Linkeingabe erwartet .o/.obj/.a/.lib: {pragma_path}"
                            )
                        object_paths.append(pragma_path)
                        known_inputs.add(key)
                    for extra_path in extra_link_inputs or ():
                        resolved_extra = self._resolve_project_link_input(
                            extra_path,
                            source_path=document.path,
                            target=document.build_target,
                        )
                        key = str(resolved_extra).casefold()
                        if key in known_inputs:
                            continue
                        if not resolved_extra.is_file():
                            continue
                        if resolved_extra.suffix.casefold() not in {
                            ".o", ".obj", ".a", ".lib"
                        }:
                            continue
                        object_paths.append(resolved_extra)
                        known_inputs.add(key)
                    source_kind = str(
                        getattr(document, "generated_source_kind", "program")
                        or "program"
                    ).casefold()
                    is_library = source_kind == "library"
                    is_form = source_kind == "form"
                    linker = link_coff64_inputs if is64 else link_coff32_inputs

                    # Stage 127:
                    # FORM/WFM ist immer eine GUI-Anwendung und besitzt einen
                    # eigenen Programmeinstieg. Der bisher hart verwendete
                    # `_start` ist der normale dBase-Console-Einstieg und darf
                    # fuer WFM niemals als PE-Entry verwendet werden.
                    if is_library:
                        entry_symbol = "__d64_dll_entry"
                    elif is_form:
                        entry_symbol = "__d64_wfm_entry"
                    else:
                        entry_symbol = "_start"

                    program = linker(
                        object_paths,
                        entry_symbol=entry_symbol,
                        gui=(
                            True
                            if is_form
                            else normalize_windows_application_mode(
                                document.windows_application_mode
                            ) != "Console"
                        ),
                        dll=is_library,
                        dll_name=(
                            document.path.with_suffix(".dll").name
                            if is_library else None
                        ),
                    )
                else:
                    program = assemble_mos6510_source(
                        assembly_source,
                        filename=assembly_path.name,
                    )
                    if not bool(getattr(document, "d64pack_generated_source", False)):
                        program, packer_stats = self._apply_c64_image_packer(program)
            except (AssemblerError, AmigaAssemblerError, PE32AssemblerError, PE64AssemblerError) as exc:
                message = str(exc)
                document.show_generated_assembly_error(
                    message,
                    exc.line or 0,
                )
                self.show_error("Assemblerfehler", message)
                self.statusBar().showMessage("Assemblieren fehlgeschlagen")
                return False

            open_assembly = self._find_open_document(assembly_path)
            if open_assembly is not None and open_assembly.is_modified:
                message = (
                    "Die erzeugte ASM-Datei ist zusätzlich geöffnet und "
                    "enthält ungespeicherte Änderungen:\n"
                    f"{assembly_path}\n\n"
                    "Speichere oder schließe diese Registerkarte vor dem "
                    "Assemblieren des ASM-Tabs."
                )
                document.show_generated_assembly_error(
                    message,
                    status_text="ASM-Datei ist geöffnet",
                )
                self.show_error("ASM-Ausgabe kann nicht ersetzt werden", message)
                return False

            try:
                self._write_assembled_program(
                    assembly_path,
                    assembly_source.encode("utf-8"),
                )
                program_data = (
                    program.adf
                    if amiga_bootable
                    else program.executable
                    if document.build_target in {"amiga", "pe32", "pe64"}
                    else program.prg
                )
                self._write_assembled_program(output_path, program_data)
            except OSError as exc:
                message = (
                    "Die Assembler-Ausgabe konnte nicht gespeichert werden:\n"
                    f"ASM: {assembly_path}\n"
                    f"Programm: {output_path}\n\n{exc}"
                )
                document.show_generated_assembly_error(
                    message,
                    status_text="Ausgabefehler",
                )
                self.show_error(
                    "Assembler-Ausgabe konnte nicht gespeichert werden",
                    message,
                )
                return False

            if open_assembly is not None:
                open_assembly.raw_editor.setPlainText(assembly_source)
                open_assembly.mark_saved()
                open_assembly.invalidate_assembly_result("Neu erzeugt")
                self._update_document_tab(open_assembly)

            if (
                document.build_target not in {"amiga", "pe32", "pe64"}
                and packer_stats is not None
            ):
                self._open_c64_packed_assembly_editor(
                    packer_stats, output_path
                )

            document.generated_assembly_path = Path(assembly_path).resolve()
            document.generated_assembly_editor.document().setModified(False)
            source_digest = hashlib.sha256(
                document.raw_editor.toPlainText().encode("utf-8")
            ).hexdigest()
            assembly_digest = hashlib.sha256(
                assembly_source.encode("utf-8")
            ).hexdigest()
            document.set_assembly_result(
                program,
                output_path,
                source_digest,
                assembly_digest,
                "assembly",
            )
            if document.build_target == "amiga":
                if amiga_bootable:
                    document.hints_editor.setPlainText(
                        "Amiga-Standalone-Assembler aus dem ASM-Tab beendet\n"
                        "\n"
                        f"Quelle        : {assembly_path}\n"
                        f"Boot-ADF      : {output_path}\n"
                        f"Boot-Einsprung: +${program.entry_offset:08X}\n"
                        f"Code-Größe    : {len(program.code)} Bytes\n"
                        f"ADF-Größe     : {len(program.adf)} Bytes\n"
                        f"Instruktionen : {program.instruction_count}\n"
                        "Workbench-Libs : keine\n"
                    )
                    self.log(
                        "ASSEMBLE AMIGA BOOT ASM-TAB: "
                        f"{assembly_path.name} -> {output_path.name}, "
                        f"{len(program.adf)} Bytes"
                    )
                else:
                    document.hints_editor.setPlainText(
                        "Amiga-Assembler aus dem ASM-Tab erfolgreich beendet\n"
                        "\n"
                        f"Quelle        : {assembly_path}\n"
                        f"Hunk-Ausgabe  : {output_path}\n"
                        f"Einsprung     : +${program.entry_offset:08X}\n"
                        f"Code-Größe    : {len(program.code)} Bytes\n"
                        f"Hunk-Größe    : {len(program.executable)} Bytes\n"
                        f"Instruktionen : {program.instruction_count}\n"
                    )
                    self.log(
                        "ASSEMBLE AMIGA ASM-TAB: "
                        f"{assembly_path.name} -> {output_path.name}, "
                        f"{len(program.executable)} Bytes"
                    )
            elif document.build_target in {"pe32", "pe64"}:
                target_label = "PE64" if document.build_target == "pe64" else "PE32"
                document.hints_editor.setPlainText(
                    f"Windows-{target_label}-Assembler aus dem ASM-Tab erfolgreich beendet\n"
                    "\n"
                    f"Quelle       : {assembly_path}\n"
                    f"{target_label}-Ausgabe : {output_path}\n"
                    f"Einsprung    : +${program.entry_offset:08X}\n"
                    f"Code-Größe   : {len(program.code)} Bytes\n"
                    f"EXE/DLL-Größe: {len(program.executable)} Bytes\n"
                    f"Windows-Modus: {document.windows_application_mode}\n"
                )
                self.log(
                    f"ASSEMBLE {target_label} ASM-TAB: "
                    f"{assembly_path.name} -> {output_path.name}, "
                    f"{len(program.executable)} Bytes"
                )
            else:
                document.hints_editor.setPlainText(
                    "C64-Assembler aus dem ASM-Tab erfolgreich beendet\n"
                    "\n"
                    f"Quelle       : {assembly_path}\n"
                    f"Ausgabe      : {output_path}\n"
                    f"Ladeadresse  : ${program.load_address:04X}\n"
                    f"Einsprung    : ${program.entry_address:04X}\n"
                    f"Letztes Byte : ${program.end_address:04X}\n"
                    f"PRG-Größe    : {len(program.prg)} Bytes\n"
                    f"Instruktionen: {program.instruction_count}\n"
                    f"BASIC-Stub   : {'ja' if program.has_basic_stub else 'nein'}\n"
                    + (
                        f"Image-Packer : {packer_stats.selected_mode.upper()} / {packer_stats.search_mode}\n"
                        f"Original     : {packer_stats.original_size} Bytes\n"
                        f"Ersparnis    : {packer_stats.saved_bytes:+d} Bytes\n"
                        f"Decruncher   : {packer_stats.decruncher_size} Bytes\n"
                        if packer_stats is not None else
                        "Image-Packer : deaktiviert\n"
                    )
                )
                self.log(
                    "ASSEMBLE C64 ASM-TAB: "
                    f"{assembly_path.name} -> {output_path.name}, "
                    f"${program.load_address:04X}-${program.end_address:04X}, "
                    f"Start ${program.entry_address:04X}"
                )
            self.statusBar().showMessage(
                f"ASM-Tab erfolgreich assembliert: {output_path.name}"
            )
            if output_path.parent == self.current_directory:
                self.populate_file_list()
            return True

        @staticmethod
        def _c_source_has_main_definition(source: str) -> bool:
            """Erkennt eine echte C-main-Definition, nicht nur einen Prototyp.

            Kommentare sowie String-/Zeichenliterale werden vor der Suche
            neutralisiert. Ein ``int main(...);`` gilt deshalb nicht als
            Hauptprogramm; erst ``main(...) {`` markiert die Translation-Unit
            als Link-/Startmodul.
            """
            pattern = re.compile(
                r'"(?:\\.|[^"\\])*"'
                r"|'(?:\\.|[^'\\])*'"
                r"|//[^\r\n]*"
                r"|/\*.*?\*/",
                re.DOTALL,
            )

            def blank(match) -> str:
                text = match.group(0)
                # Zeilenumbrueche erhalten, damit spaetere Diagnosen/Debugging
                # die gleiche Zeilenstruktur sehen.
                return "".join("\n" if char == "\n" else " " for char in text)

            cleaned = pattern.sub(blank, str(source or ""))
            return bool(re.search(
                r"\bmain\s*\([^;{}]*\)\s*\{",
                cleaned,
                re.IGNORECASE | re.DOTALL,
            ))

        def _f2_document_is_main_program(self, document: DocumentEditor) -> bool:
            if document.is_basic_document:
                # Der vorhandene BASIC-Compiler erzeugt derzeit ein komplettes
                # C64-Hauptprogramm; ein separates BASIC-Unit-Modell existiert
                # noch nicht.
                return True
            if document.is_c_document:
                return self._c_source_has_main_definition(
                    document.raw_editor.toPlainText()
                )
            if document.is_prolog_document or document.is_logo_document or document.is_dbase_document:
                return True
            if document.is_pascal_document or document.is_lisp_document:
                return (
                    str(getattr(document, "generated_source_kind", "program"))
                    .strip().casefold() == "program"
                )
            return False

        def _project_link_inputs_for_document(
            self,
            document: DocumentEditor,
        ) -> Tuple[Path, ...]:
            """Sammelt vorhandene Objekt-/Archivdateien fuer den F2-Link.

            Nicht-Hauptdateien werden mit F2 zu ``.o`` erzeugt. Beim spaeteren
            F2 auf dem Hauptprogramm werden diese vorhandenen Objektdateien
            automatisch mitgelinkt. Fuer C werden ausserdem die unter
            ``C-Programme -> Archive`` eingetragenen Archive/Objekte verwendet.
            """
            if document.build_target not in {"pe32", "pe64"}:
                return ()
            category_key = (
                "c" if document.is_c_document
                else "pascal" if document.is_pascal_document
                else "lisp" if document.is_lisp_document
                else "prolog" if document.is_prolog_document
                else "logo" if document.is_logo_document
                else "dbase" if document.is_dbase_document
                else ""
            )
            if not category_key:
                return ()

            result: List[Path] = []
            seen = set()

            def add(path_value) -> None:
                if not path_value:
                    return
                try:
                    path = Path(path_value).expanduser().resolve()
                except OSError:
                    path = Path(path_value).expanduser()
                if (
                    document.is_pascal_document
                    and document.build_target in {"pe32", "pe64"}
                ):
                    path = _pascal_preferred_object_for_legacy_o(
                        path,
                        document.build_target,
                    )
                if not path.is_file():
                    return
                if path.suffix.casefold() not in {".o", ".obj", ".a", ".lib"}:
                    return
                key = str(path).casefold()
                if key in seen:
                    return
                seen.add(key)
                result.append(path)

            root = getattr(self, "project_root_items", {}).get(category_key)
            current_path = document.path.resolve() if document.path is not None else None
            if root is not None:
                for index in range(root.childCount()):
                    child = root.child(index)
                    if self._project_item_kind(child) in {
                        PROJECT_NODE_ARCHIVE_ROOT,
                        PROJECT_NODE_PROLOG_KNOWLEDGE_ROOT,
                    }:
                        continue
                    source_text = str(child.data(0, Qt.UserRole + 302) or "")
                    if not source_text:
                        continue
                    try:
                        source_path = Path(source_text).expanduser().resolve()
                    except OSError:
                        source_path = Path(source_text).expanduser()
                    if current_path is not None and source_path == current_path:
                        continue
                    # Direkte Objekt-/Archiv-Eintraege werden unveraendert
                    # verwendet; nur passende Quelltexte liefern ihr
                    # gleichnamiges .o. Header/sonstige Projektdateien werden
                    # nicht versehentlich als Linkmodul interpretiert.
                    suffix = source_path.suffix.casefold()
                    if suffix in {".o", ".obj", ".a", ".lib"}:
                        add(source_path)
                    elif (
                        document.is_c_document and suffix == ".c"
                    ) or (
                        document.is_pascal_document
                        and suffix in DocumentEditor.PASCAL_EXTENSIONS
                    ) or (
                        document.is_lisp_document
                        and suffix in DocumentEditor.LISP_EXTENSIONS
                    ) or (
                        document.is_prolog_document
                        and suffix in DocumentEditor.PROLOG_EXTENSIONS
                    ):
                        add(source_path.with_suffix(".o"))

            if document.is_dbase_document:
                # Stage ASM 29: explizite dBase-Linkerressourcen.
                # .o-Dateien werden direkt zugelinkt; .a-Dateien werden vom
                # vorhandenen internen Linker nach benötigten Symbolen durchsucht.
                for _role in ("objects", "archives"):
                    _group = getattr(self, "project_dbase_group_nodes", {}).get(_role)
                    if _group is None:
                        continue
                    for _index in range(_group.childCount()):
                        _child = _group.child(_index)
                        if self._project_item_kind(_child) != PROJECT_NODE_DBASE_FILE:
                            continue
                        add(_child.data(0, Qt.UserRole + 302))

            if document.is_c_document:
                archive_root = getattr(self, "project_archive_root", None)
                if archive_root is not None:
                    for index in range(archive_root.childCount()):
                        archive_item = archive_root.child(index)
                        if self._project_item_kind(archive_item) != PROJECT_NODE_ARCHIVE:
                            continue
                        archive_path = str(
                            archive_item.data(0, Qt.UserRole + 302) or ""
                        )
                        if archive_path and Path(archive_path).expanduser().is_file():
                            add(archive_path)
                            continue
                        # Noch nicht erzeugtes Archiv: vorhandene Objektkinder
                        # einzeln linken.
                        for child_index in range(archive_item.childCount()):
                            object_item = archive_item.child(child_index)
                            if self._project_item_kind(object_item) != PROJECT_NODE_ARCHIVE_OBJECT:
                                continue
                            add(object_item.data(0, Qt.UserRole + 302))
            return tuple(result)

        def build_and_run_source_document(self, document: DocumentEditor) -> bool:
            """F2: Compile -> Assemble/Object -> Link -> Start vereinheitlichen.

            Hauptprogramme werden bis zum lauffaehigen Ziel gebaut und direkt
            gestartet. C-Dateien ohne ``main`` und Pascal-Units werden unter
            Windows lediglich als COFF32/COFF64-Objekt erzeugt. Dadurch bleibt
            genau ein F2-Arbeitsablauf fuer BASIC, Assembler, C, Pascal, LISP, PROLOG, LOGO und dBase bestehen.
            """
            if not isinstance(document, DocumentEditor):
                return False
            if not (
                document.is_basic_document
                or document.is_assembler_document
                or document.is_c_document
                or document.is_pascal_document
                or document.is_lisp_document
                or document.is_prolog_document
                or document.is_logo_document
                or document.is_dbase_document
            ):
                self.statusBar().showMessage(
                    "F2-Build gilt für BASIC-, Assembler-, C-, Pascal-, LISP-, PROLOG-, LOGO- und dBase-Quelltexte",
                    5000,
                )
                return False
            self.document_tabs.setCurrentWidget(document)
            document.views.setCurrentWidget(document.source_page)
            if document.path is None and not self._save_document(document, save_as=True):
                return False

            # Stage 59: Reiner Assembler ist bereits die letzte Quellstufe.
            # F2 assembliert und linkt deshalb direkt mit der internen
            # Toolchain. Nur ein tatsaechliches EXE-Ergebnis wird anschliessend
            # gestartet; PRG/ADF/Amiga-Hunk/DLL bleiben als Build-Artefakt liegen.
            if document.is_assembler_document:
                if not self.assemble_document(document):
                    return False
                output_path = document.assembled_program_path
                if (
                    output_path is not None
                    and output_path.suffix.casefold() == ".exe"
                    and output_path.is_file()
                ):
                    return self._launch_assembled_document(document)
                if output_path is not None:
                    self.statusBar().showMessage(
                        f"F2: Assembler erzeugt: {output_path.name}",
                        7000,
                    )
                return True

            # Bestehenden Compilepfad verwenden. Compilerfehler, Warnungen und
            # Hinweise bleiben dadurch exakt an ihrer bisherigen Stelle.
            if not self.assemble_document(document):
                return False

            if not self._f2_document_is_main_program(document):
                if document.build_target in {"pe32", "pe64"}:
                    ok = self.create_coff32_object_document(document)
                    if ok:
                        label = "COFF64" if document.build_target == "pe64" else "COFF32"
                        self.statusBar().showMessage(
                            f"F2: Modul als {label}-Objekt erzeugt: "
                            f"{document.path.with_suffix('.o').name}",
                            7000,
                        )
                    return ok
                # Fuer C64/Amiga existiert derzeit kein relocierbarer
                # Objektwriter. Das Compile-Ergebnis bleibt als ASM erhalten;
                # wir erzeugen bewusst kein falsches 'Objekt'.
                document.hints_editor.appendPlainText(
                    "\nF2: Kein Hauptprogramm erkannt. Für dieses Ziel gibt es "
                    "noch kein relocierbares Objektformat; ASM wurde erzeugt."
                )
                self.statusBar().showMessage(
                    "F2: Modul kompiliert; Objektgenerierung ist aktuell nur für PE32/PE64 verfügbar",
                    7000,
                )
                return True

            extra_inputs = self._project_link_inputs_for_document(document)
            if not self.assemble_generated_document(
                document,
                extra_link_inputs=extra_inputs,
            ):
                return False
            if extra_inputs:
                self.log(
                    "F2 LINK INPUTS: "
                    + ", ".join(path.name for path in extra_inputs)
                )
            # Nach erfolgreichem Compile -> Assemble -> Link wird die erzeugte
            # EXE unmittelbar gestartet. dBase besitzt keine IDE-Konsole mehr;
            # seine Ausgabe-Tabs leben ausschliesslich in der Qt5-Anwendung.
            return self._launch_assembled_document(document)

        def build_and_run_generated_assembly_document(
            self,
            document: DocumentEditor,
        ) -> bool:
            """F2 im ASM-Tab: sichtbaren ASM-Code assembliert/linkt und EXE startet.

            Dieser Pfad kompiliert die Hochsprache bewusst nicht erneut. Der
            editierbare Inhalt von ``generated_assembly_editor`` ist die
            verbindliche Eingabe. Fuer PE32/PE64 werden vorhandene Projekt-
            objekte/-archive wie beim normalen F2-Hauptbuild an den internen
            Linker weitergereicht. Externe Buildwerkzeuge werden nicht benutzt.
            """
            if not isinstance(document, DocumentEditor):
                return False
            self.document_tabs.setCurrentWidget(document)
            document.views.setCurrentWidget(document.generated_assembly_page)
            if document.path is None and not self._save_document(
                document, save_as=True
            ):
                return False

            extra_inputs = self._project_link_inputs_for_document(document)
            if not self.assemble_generated_document(
                document,
                extra_link_inputs=extra_inputs,
            ):
                return False
            if extra_inputs:
                self.log(
                    "F2 ASM LINK INPUTS: "
                    + ", ".join(path.name for path in extra_inputs)
                )

            output_path = document.assembled_program_path
            if (
                output_path is not None
                and output_path.suffix.casefold() == ".exe"
                and output_path.is_file()
            ):
                return self._launch_assembled_document(document)

            if output_path is not None:
                self.statusBar().showMessage(
                    f"F2: ASM-Tab erzeugt: {output_path.name}",
                    7000,
                )
            return True

        def assemble_document(self, document: DocumentEditor) -> bool:
            """Compile für BASIC/C/Pascal/LISP/PROLOG/LOGO/dBase oder Assemble für ASM."""
            if not isinstance(document, DocumentEditor):
                return False
            self.document_tabs.setCurrentWidget(document)
            if document.is_build_document and document.path is None:
                # Neue Dokumente aus Datei -> Neu erhalten vor dem ersten
                # Build denselben Save-As-Ablauf wie geöffnete Dateien.
                if not self._save_document(document, save_as=True):
                    return False
            if document.is_basic_document:
                return self._compile_basic_document(document)
            if document.is_pascal_document:
                return self._compile_pascal_document(document)
            if document.is_c_document:
                return self._compile_c_document(document)
            if document.is_lisp_document:
                return self._compile_lisp_document(document)
            if document.is_prolog_document:
                return self._compile_prolog_document(document)
            if document.is_logo_document:
                return self._compile_logo_document(document)
            if document.is_dbase_document:
                return self._compile_dbase_document(document)
            if not document.is_assembler_document:
                self.show_error(
                    "Kein übersetzbares Dokument",
                    "Compile/Assemble steht für .bas, .basic, .c, .pas, .pp, "
                    ".lisp, .lsp, .pl, .prolog, .logo, .lgo, .dbase, .dbp, .asm, .s, .a65 und .inc zur Verfügung.",
                )
                return False

            source = document.raw_editor.toPlainText()
            source_digest = hashlib.sha256(
                source.encode("utf-8")
            ).hexdigest()
            packer_stats = None
            try:
                #from amiga500 import (
                #    AmigaAssemblerError,
                #    assemble_amiga_boot_source,
                #    assemble_amiga_source,
                #    is_amiga_boot_source,
                #)
                amiga_bootable = (
                    document.build_target == "amiga"
                    and is_amiga_boot_source(source)
                )
                output_path = self._assembler_output_path(document, source)
                if document.build_target == "amiga":
                    assembler = (
                        assemble_amiga_boot_source
                        if amiga_bootable
                        else assemble_amiga_source
                    )
                    program = assembler(
                        source,
                        filename=document.display_name,
                        cpu_model=document.amiga_cpu_model,
                        fpu_model=document.amiga_fpu_model,
                    )
                    program_data = (
                        program.adf
                        if amiga_bootable
                        else program.executable
                    )
                elif document.build_target == "pe32":
                    program = assemble_pe32_source(
                        source,
                        filename=document.display_name,
                        gui=(normalize_windows_application_mode(document.windows_application_mode) != "Console"),
                    )
                    program_data = program.executable
                elif document.build_target == "pe64":
                    program = assemble_pe64_source(
                        source,
                        filename=document.display_name,
                        gui=(normalize_windows_application_mode(document.windows_application_mode) != "Console"),
                    )
                    program_data = program.executable
                else:
                    program = assemble_mos6510_source(
                        source,
                        filename=document.display_name,
                    )
                    if not bool(getattr(document, "d64pack_generated_source", False)):
                        program, packer_stats = self._apply_c64_image_packer(program)
                    program_data = program.prg
                self._write_assembled_program(output_path, program_data)
            except (AssemblerError, AmigaAssemblerError, PE32AssemblerError, PE64AssemblerError) as exc:
                message = str(exc)
                document.show_assembly_error(message, exc.line or 0)
                self.show_error("Assemblerfehler", message)
                self.statusBar().showMessage("Assemblieren fehlgeschlagen")
                return False
            except OSError as exc:
                message = (
                    "Das Zielprogramm konnte nicht gespeichert werden:\n"
                    f"{output_path}\n\n{exc}"
                )
                document.show_assembly_error(message)
                self.show_error("PRG konnte nicht gespeichert werden", message)
                self.statusBar().showMessage("Assemblieren fehlgeschlagen")
                return False

            if (
                document.build_target not in {"amiga", "pe32", "pe64"}
                and packer_stats is not None
            ):
                self._open_c64_packed_assembly_editor(
                    packer_stats, output_path
                )

            document.set_assembly_result(
                program,
                output_path,
                source_digest,
            )
            if document.build_target == "amiga":
                if amiga_bootable:
                    document.hints_editor.setPlainText(
                        "Amiga-Standalone-Assembler erfolgreich beendet\n"
                        "\n"
                        f"Quelle        : {document.display_name}\n"
                        f"Boot-ADF      : {output_path}\n"
                        f"Boot-Einsprung: +${program.entry_offset:08X}\n"
                        f"Code-Größe    : {len(program.code)} Bytes\n"
                        f"ADF-Größe     : {len(program.adf)} Bytes\n"
                        f"Instruktionen : {program.instruction_count}\n"
                        "Workbench-Libs : keine\n"
                    )
                    self.log(
                        "ASSEMBLE AMIGA BOOT: "
                        f"{document.display_name} -> {output_path.name}, "
                        f"{len(program.adf)} Bytes"
                    )
                else:
                    document.hints_editor.setPlainText(
                        "Amiga-Assembler erfolgreich beendet\n"
                        "\n"
                        f"Quelle        : {document.display_name}\n"
                        f"Hunk-Ausgabe  : {output_path}\n"
                        f"Einsprung     : +${program.entry_offset:08X}\n"
                        f"Code-Größe    : {len(program.code)} Bytes\n"
                        f"Hunk-Größe    : {len(program.executable)} Bytes\n"
                        f"Instruktionen : {program.instruction_count}\n"
                    )
                    self.log(
                        "ASSEMBLE AMIGA: "
                        f"{document.display_name} -> {output_path.name}, "
                        f"{len(program.executable)} Bytes"
                    )
            elif document.build_target in {"pe32", "pe64"}:
                target_label = "PE64" if document.build_target == "pe64" else "PE32"
                document.hints_editor.setPlainText(
                    f"Windows-{target_label}-Assembler erfolgreich beendet\n"
                    "\n"
                    f"Quelle       : {document.display_name}\n"
                    f"{target_label}-Ausgabe : {output_path}\n"
                    f"Einsprung    : +${program.entry_offset:08X}\n"
                    f"Code-Größe   : {len(program.code)} Bytes\n"
                    f"EXE-Größe    : {len(program.executable)} Bytes\n"
                    f"Windows-Modus: {document.windows_application_mode}\n"
                )
                self.log(
                    f"ASSEMBLE {target_label}: "
                    f"{document.display_name} -> {output_path.name}, "
                    f"{len(program.executable)} Bytes"
                )
            else:
                document.hints_editor.setPlainText(
                    "C64-Assembler erfolgreich beendet\n"
                    "\n"
                    f"Quelle       : {document.display_name}\n"
                    f"Ausgabe      : {output_path}\n"
                    f"Ladeadresse  : ${program.load_address:04X}\n"
                    f"Einsprung    : ${program.entry_address:04X}\n"
                    f"Letztes Byte : ${program.end_address:04X}\n"
                    f"PRG-Größe    : {len(program.prg)} Bytes\n"
                    f"Instruktionen: {program.instruction_count}\n"
                    f"BASIC-Stub   : {'ja' if program.has_basic_stub else 'nein'}\n"
                    + (
                        f"Image-Packer : {packer_stats.selected_mode.upper()} / {packer_stats.search_mode}\n"
                        f"Original     : {packer_stats.original_size} Bytes\n"
                        f"Ersparnis    : {packer_stats.saved_bytes:+d} Bytes\n"
                        f"Decruncher   : {packer_stats.decruncher_size} Bytes\n"
                        if packer_stats is not None else
                        "Image-Packer : deaktiviert\n"
                    )
                )
                self.log(
                    "ASSEMBLE C64: "
                    f"{document.display_name} -> {output_path.name}, "
                    f"${program.load_address:04X}-${program.end_address:04X}, "
                    f"Start ${program.entry_address:04X}"
                )
            self.statusBar().showMessage(
                f"Assemblieren erfolgreich: {output_path.name}"
            )
            if output_path.parent == self.current_directory:
                self.populate_file_list()
            return True

        def _resolve_vice_for_program_start(self) -> Optional[Path]:
            if self.dism_vice_path:
                configured = Path(self.dism_vice_path).expanduser()
                if configured.is_file():
                    return configured.resolve()
                self.show_error(
                    "VICE nicht gefunden",
                    "Das gespeicherte VICE-Programm existiert nicht mehr:\n"
                    f"{configured}\n\nBitte wähle VICE erneut aus.",
                )
                self.dism_vice_path = ""

            executable = (
                shutil.which("x64sc.exe")
                or shutil.which("x64sc")
                or shutil.which("x64.exe")
                or shutil.which("x64")
            )
            if executable:
                return Path(executable).resolve()

            self.choose_dism_vice()
            if self.dism_vice_path:
                selected = Path(self.dism_vice_path)
                if selected.is_file():
                    return selected.resolve()
            self.statusBar().showMessage("VICE-Start abgebrochen")
            return None

        def _resolve_winuae_for_program_start(self) -> Optional[Path]:
            if self.winuae_path:
                configured = Path(self.winuae_path).expanduser()
                if configured.is_file():
                    return configured.resolve()
                self.show_error(
                    "WinUAE nicht gefunden",
                    "Das gespeicherte WinUAE-Programm existiert nicht mehr:\n"
                    f"{configured}\n\nBitte wähle WinUAE erneut aus.",
                )
                self.winuae_path = ""

            executable = (
                shutil.which("winuae64.exe")
                or shutil.which("winuae.exe")
                or shutil.which("winuae64")
                or shutil.which("winuae")
            )
            if executable:
                return Path(executable).resolve()

            self.choose_winuae()
            if self.winuae_path:
                selected = Path(self.winuae_path)
                if selected.is_file():
                    return selected.resolve()
            self.statusBar().showMessage("WinUAE-Start abgebrochen")
            return None

        def _start_existing_dbase_executable(
            self,
            document: DocumentEditor,
        ) -> bool:
            """Startet ausschliesslich die bereits gelinkte dBase-EXE.

            Der Start-Button ist absichtlich kein Build-Button: Weder Compiler
            noch Assembler noch Linker werden von hier aus aufgerufen.
            """
            if not isinstance(document, DocumentEditor) or not document.is_dbase_document:
                return False
            if document.path is None:
                self.show_error(
                    "dBase-Start",
                    "Die dBase-Quelldatei muss gespeichert sein, damit der Name der EXE bekannt ist.",
                )
                return False
            if document.build_target not in {"pe32", "pe64"}:
                self.show_error("dBase-Start", "dBase unterstuetzt nur Windows PE32/PE32+.")
                return False
            executable = (self.current_directory / document.path.with_suffix(".exe").name).resolve()
            if not executable.is_file():
                self.show_error(
                    "dBase-EXE nicht gefunden",
                    "Der Start-Button baut nicht automatisch.\n\n"
                    "Kompiliere/assembliere/linke zuerst mit F2 oder Assemble.\n"
                    f"Erwartete EXE im Arbeitsverzeichnis:\n{executable}",
                )
                self.statusBar().showMessage("dBase-Start: vorhandene EXE fehlt", 6000)
                return False
            document.assembled_program_path = executable
            document.assembled_target = document.build_target
            return self._launch_assembled_document(document)

        def start_assembled_document(self, document: DocumentEditor) -> bool:
            """Startet das zuletzt erzeugte Programm; dBase baut hier niemals neu."""
            if not isinstance(document, DocumentEditor):
                return False
            self.document_tabs.setCurrentWidget(document)
            if document.is_dbase_document:
                return self._start_existing_dbase_executable(document)

            current_digest = hashlib.sha256(
                document.raw_editor.toPlainText().encode("utf-8")
            ).hexdigest()
            output_path = document.assembled_program_path
            if (
                output_path is None
                or document.assembled_target != document.build_target
                or document.assembled_input_kind != "source"
                or document.assembled_source_digest != current_digest
                or not output_path.is_file()
            ):
                if not self.assemble_document(document):
                    return False
            return self._launch_assembled_document(document)

        def start_generated_assembly_document(
            self,
            document: DocumentEditor,
        ) -> bool:
            """Startet vorhandene Ausgabe; der dBase-Start fuehrt keinen Build aus."""
            if not isinstance(document, DocumentEditor):
                return False
            self.document_tabs.setCurrentWidget(document)
            if document.is_dbase_document:
                return self._start_existing_dbase_executable(document)
            current_digest = document.generated_assembly_digest()
            output_path = document.assembled_program_path
            if (
                output_path is None
                or document.assembled_target != document.build_target
                or document.assembled_assembly_digest != current_digest
                or not output_path.is_file()
            ):
                if not self.assemble_generated_document(document):
                    return False
            return self._launch_assembled_document(document)

        @staticmethod
        def _decode_dbase_process_output(data) -> str:
            raw = bytes(data)
            if not raw:
                return ""
            # Der dBase-Compiler legt Stringliterale als Windows-1252 ab.
            return raw.decode("cp1252", errors="replace")

        def _launch_dbase_qt5_gui(
            self,
            document: DocumentEditor,
            output_path: Path,
        ) -> bool:
            """Startet die generierte dBase-Qt5-GUI ohne Textkonsole."""
            if os.name != "nt":
                self.show_error(
                    "Windows-PE-Start",
                    "PE32/PE32+-dBase-Qt5-Programme koennen aus d64_dism nur "
                    "unter Windows direkt gestartet werden. Die erzeugte EXE "
                    "bleibt erhalten:\n" + str(output_path),
                )
                return False
            options = {
                "cwd": str(output_path.parent),
                "stdin": subprocess.DEVNULL,
                "stdout": subprocess.DEVNULL,
                "stderr": subprocess.DEVNULL,
            }
            flags = 0
            if hasattr(subprocess, "CREATE_NEW_PROCESS_GROUP"):
                flags |= subprocess.CREATE_NEW_PROCESS_GROUP
            if hasattr(subprocess, "CREATE_NO_WINDOW"):
                flags |= subprocess.CREATE_NO_WINDOW
            if flags:
                options["creationflags"] = flags
            try:
                process = subprocess.Popen([str(output_path)], **options)
            except OSError as exc:
                self.show_error(
                    "dBase Qt5-Programm konnte nicht gestartet werden",
                    f"Programm: {output_path}\n\n{exc}\n\n"
                    "Der Start-Button startet ausschliesslich die bereits vom "
                    "internen Linker erzeugte EXE. Stelle sicher, dass die bereits "
                    "manuell erzeugte libd64_qt5.dll sowie ihre Qt5-Abhaengigkeiten "
                    "ueber das EXE-Verzeichnis oder den Windows-DLL-Suchpfad "
                    "verfuegbar sind.",
                )
                return False
            processes = [
                running for running in getattr(self, "_dbase_qt5_processes", [])
                if running.poll() is None
            ]
            processes.append(process)
            self._dbase_qt5_processes = processes
            document.assembly_status_label.setText(
                f"dBase Qt5-GUI gestartet: {output_path.name}"
            )
            if document.generated_assembly_path is not None:
                document.generated_assembly_status_label.setText(
                    f"dBase Qt5-GUI gestartet: {output_path.name}"
                )
            self.log(f"DBASE QT5 START: {output_path}")
            self.statusBar().showMessage(
                f"dBase Qt5-GUI gestartet: {output_path.name}"
            )
            return True

        # Kompatibler Alias fuer aeltere Aufrufer; es wird keine eingebettete
        # Textkonsole mehr verwendet.
        def _launch_dbase_embedded_console(
            self,
            document: DocumentEditor,
            output_path: Path,
        ) -> bool:
            return self._launch_dbase_qt5_gui(document, output_path)

        @staticmethod
        def _d64_workstation_is_open() -> bool:
            'Advisory check for the existing d64qt5 Workstation singleton.'
            if os.name != "nt":
                return False
            try:
                import ctypes
                from ctypes import wintypes

                SYNCHRONIZE = 0x00100000
                kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)

                open_mutex = kernel32.OpenMutexW
                open_mutex.argtypes = [
                    wintypes.DWORD,
                    wintypes.BOOL,
                    wintypes.LPCWSTR,
                ]
                open_mutex.restype = wintypes.HANDLE

                close_handle = kernel32.CloseHandle
                close_handle.argtypes = [wintypes.HANDLE]
                close_handle.restype = wintypes.BOOL

                handle = open_mutex(
                    SYNCHRONIZE,
                    False,
                    r"Global\\dBase2Many.D64Workstation.Singleton",
                )
                if not handle:
                    return False
                close_handle(handle)
                return True
            except Exception:
                # Advisory only. The C++ runtime performs the authoritative
                # mutex/ready-event check before QApplication/QWidget creation.
                return False

        @staticmethod
        def _workstation_runner_pipe_name() -> str:
            return r"\\.\pipe\dBase2Many.D64Workstation.Runner.v1"

        def _workstation_runner_candidates(self) -> List[Path]:
            """Liefert moegliche Pfade des einmalig gebauten Runner-Programms."""
            name = "d64_workstation_runner.exe"
            candidates: List[Path] = []

            try:
                source_dir = Path(__file__).resolve().parent
            except Exception:
                source_dir = Path.cwd()

            candidates.extend([
                source_dir / "d64qt5" / "build-mingw32" / name,
                source_dir / "d64qt5" / name,
                source_dir / name,
            ])

            try:
                exe_dir = Path(sys.executable).resolve().parent
                candidates.extend([
                    exe_dir / name,
                    exe_dir / "d64qt5" / "build-mingw32" / name,
                ])
            except Exception:
                pass

            meipass = getattr(sys, "_MEIPASS", None)
            if meipass:
                base = Path(meipass)
                candidates.extend([
                    base / name,
                    base / "d64qt5" / "build-mingw32" / name,
                ])

            unique: List[Path] = []
            seen = set()
            for candidate in candidates:
                try:
                    resolved = candidate.resolve()
                except Exception:
                    resolved = candidate
                key = os.path.normcase(str(resolved))
                if key in seen:
                    continue
                seen.add(key)
                unique.append(resolved)
            return unique

        def _find_workstation_runner(self) -> Optional[Path]:
            for candidate in self._workstation_runner_candidates():
                if candidate.is_file():
                    return candidate
            return None

        def _send_workstation_runner_request(
            self,
            output_path: Path,
            *,
            console_mode: bool,
            timeout_ms: int = 200,
        ) -> bool:
            """Uebergibt eine fertige PE-EXE an den laufenden Runner."""
            if os.name != "nt":
                return False

            try:
                import ctypes
                from ctypes import wintypes

                pipe_name = self._workstation_runner_pipe_name()
                kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)

                wait_named_pipe = kernel32.WaitNamedPipeW
                wait_named_pipe.argtypes = [wintypes.LPCWSTR, wintypes.DWORD]
                wait_named_pipe.restype = wintypes.BOOL

                create_file = kernel32.CreateFileW
                create_file.argtypes = [
                    wintypes.LPCWSTR,
                    wintypes.DWORD,
                    wintypes.DWORD,
                    wintypes.LPVOID,
                    wintypes.DWORD,
                    wintypes.DWORD,
                    wintypes.HANDLE,
                ]
                create_file.restype = wintypes.HANDLE

                write_file = kernel32.WriteFile
                write_file.argtypes = [
                    wintypes.HANDLE,
                    wintypes.LPCVOID,
                    wintypes.DWORD,
                    ctypes.POINTER(wintypes.DWORD),
                    wintypes.LPVOID,
                ]
                write_file.restype = wintypes.BOOL

                close_handle = kernel32.CloseHandle
                close_handle.argtypes = [wintypes.HANDLE]
                close_handle.restype = wintypes.BOOL

                if not wait_named_pipe(pipe_name, max(0, int(timeout_ms))):
                    return False

                GENERIC_WRITE = 0x40000000
                OPEN_EXISTING = 3
                handle = create_file(
                    pipe_name,
                    GENERIC_WRITE,
                    0,
                    None,
                    OPEN_EXISTING,
                    0,
                    None,
                )
                invalid_handle = ctypes.c_void_p(-1).value
                handle_value = int(handle) if handle else 0
                if not handle_value or handle_value == int(invalid_handle):
                    return False

                try:
                    exe = str(Path(output_path).resolve())
                    cwd = str(Path(output_path).resolve().parent)
                    exe_bytes = exe.encode("utf-16-le")
                    cwd_bytes = cwd.encode("utf-16-le")
                    flags = 1 if console_mode else 0
                    payload = (
                        struct.pack(
                            "<IIII",
                            0x31525744,  # DWR1
                            flags,
                            len(exe_bytes),
                            len(cwd_bytes),
                        )
                        + exe_bytes
                        + cwd_bytes
                    )
                    buffer = ctypes.create_string_buffer(payload)
                    written = wintypes.DWORD(0)
                    ok = write_file(
                        handle,
                        buffer,
                        len(payload),
                        ctypes.byref(written),
                        None,
                    )
                    return bool(ok) and int(written.value) == len(payload)
                finally:
                    close_handle(handle)
            except Exception:
                return False

        def _start_workstation_runner_process(
            self,
            runner: Path,
            output_path: Path,
            *,
            console_mode: bool,
        ) -> bool:
            """Startet Runner + Anwendung direkt; kein Compiler/Make-Aufruf.

            Eine bereits laufende Runner-Instanz wird vom C++-Runner selbst
            erkannt. Die kurzlebige zweite Instanz leitet den Startauftrag
            dann ueber die bestehende Named Pipe an den OWNER weiter.
            """
            try:
                output_path = Path(output_path).resolve()
                mode_switch = "--console" if console_mode else "--gui"
                command = [str(runner), mode_switch, str(output_path)]
                options = {
                    "cwd": str(runner.parent),
                    "stdin": subprocess.DEVNULL,
                    "stdout": subprocess.DEVNULL,
                    "stderr": subprocess.DEVNULL,
                }
                creationflags = 0
                if hasattr(subprocess, "CREATE_NEW_PROCESS_GROUP"):
                    creationflags |= subprocess.CREATE_NEW_PROCESS_GROUP
                if creationflags:
                    options["creationflags"] = creationflags
                process = subprocess.Popen(command, **options)
            except OSError as exc:
                self.show_error(
                    "Workstation Mode",
                    "Der Workstation Runner konnte nicht gestartet werden:\n\n"
                    f"{runner}\n\n{exc}",
                )
                return False

            processes = [
                p for p in getattr(self, "_workstation_runner_processes", [])
                if p.poll() is None
            ]
            processes.append(process)
            self._workstation_runner_processes = processes
            return True

        def _launch_via_workstation_runner(
            self,
            output_path: Path,
            *,
            console_mode: bool,
        ) -> bool:
            """Startet PE32/PE32+ direkt ueber den Workstation Runner.

            Der Runner linkt src/d64qt5/d64_workstation.cpp und entscheidet
            selbst race-sicher zwischen OWNER und bestehender Session. Bei
            einem bereits residenten Runner leitet eine zweite, kurzlebige
            Runner-Instanz den Auftrag ueber die kompatible Named Pipe weiter.
            d64_dism baut den Runner beim Start ausdruecklich NICHT.
            """
            if os.name != "nt":
                self.show_error(
                    "Workstation Mode",
                    "Workstation Mode steht nur unter Windows zur Verfügung.",
                )
                return False

            output_path = Path(output_path).resolve()
            workstation_was_open = self._d64_workstation_is_open()

            runner = self._find_workstation_runner()
            if runner is None:
                expected = "\n".join(
                    f"  - {candidate}"
                    for candidate in self._workstation_runner_candidates()[:4]
                )
                self.show_error(
                    "Workstation Mode",
                    "Der einmalig gebaute Workstation Runner fehlt.\n\n"
                    "Baue ihn einmal mit:\n"
                    "  src\\d64qt5\\build_workstation_runner_mingw32.bat\n\n"
                    "Beim normalen Projekt-Start wird dieser Build NICHT "
                    "automatisch ausgeführt.\n\n"
                    "Gesuchte Pfade:\n" + expected,
                )
                return False

            if not self._start_workstation_runner_process(
                runner,
                output_path,
                console_mode=console_mode,
            ):
                return False

            if workstation_was_open:
                message = (
                    "Workstation Mode: Startauftrag an vorhandene "
                    "Workstation-Session übergeben"
                )
            else:
                message = (
                    "Workstation Mode: Runner startet neue Workstation-Session; "
                    f"{output_path.name} wird geladen"
                )

            self.log(
                "WORKSTATION RUNNER DIRECT START: "
                f"{runner} {'--console' if console_mode else '--gui'} "
                f"{output_path}"
            )
            self.statusBar().showMessage(message, 7000)
            return True

        def _launch_assembled_document(
            self,
            document: DocumentEditor,
        ) -> bool:
            output_path = document.assembled_program_path
            if output_path is None:
                return False
            if document.build_target == "amiga":
                return self._launch_amiga_document(document, output_path)
            if document.build_target in {"pe32", "pe64"}:
                target_key = self._project_windows_target_key(
                    document.build_target
                )
                workstation_mode = bool(
                    self.project_windows_workstation_mode.get(
                        target_key, False
                    )
                )
                if document.is_dbase_document:
                    return self._launch_dbase_qt5_gui(document, output_path)
                target_label = "PE64" if document.build_target == "pe64" else "PE32"
                if os.name != "nt":
                    self.show_error(
                        "Windows-PE-Start",
                        "PE32/PE64-Programme können aus d64_dism nur unter Windows "
                        "direkt gestartet werden. Die erzeugte EXE bleibt erhalten:\n"
                        f"{output_path}",
                    )
                    return False
                # Konsolenprogramme duerfen ihre Standard-Handles nicht auf
                # DEVNULL umgeleitet bekommen. Der Windows-Code oeffnet seine
                # Konsole mit AllocConsole und verwendet CONIN$/CONOUT$ fuer
                # ReadLn/WriteLn. Eine Popen-Umleitung auf DEVNULL fuehrt sonst
                # exakt dazu, dass WriteFile unsichtbar schreibt und ReadFile
                # sofort EOF liefert.
                console_mode = (
                    normalize_windows_application_mode(
                        document.windows_application_mode
                    ) == "Console"
                )

                if document.is_logo_document and not console_mode:
                    runtime_dll = output_path.parent / "d64graphics.dll"
                    if not runtime_dll.is_file():
                        try:
                            build_windows_graphics_runtime_dll(
                                runtime_dll, document.windows_graphics_backend
                            )
                        except (OSError, PE32AssemblerError) as exc:
                            self.show_error(
                                "LOGO-Grafik-Runtime fehlt",
                                "Für LOGO-GUI wird d64graphics.dll benötigt. "
                                "Der automatische Build ist fehlgeschlagen:\n\n" + str(exc),
                            )
                            return False
                if workstation_mode:
                    return self._launch_via_workstation_runner(
                        output_path,
                        console_mode=console_mode,
                    )
                options = {"cwd": str(output_path.parent)}
                if not console_mode:
                    options.update({
                        "stdin": subprocess.DEVNULL,
                        "stdout": subprocess.DEVNULL,
                        "stderr": subprocess.DEVNULL,
                    })
                creationflags = 0
                if console_mode and hasattr(subprocess, "CREATE_NEW_CONSOLE"):
                    # Ein Console-Target soll niemals die Konsole des IDE-/Starter-
                    # Prozesses erben. Andernfalls veraendern SetConsoleWindowInfo
                    # und SetConsoleScreenBufferSize das bereits laufende Fenster.
                    creationflags |= subprocess.CREATE_NEW_CONSOLE
                if hasattr(subprocess, "CREATE_NEW_PROCESS_GROUP"):
                    creationflags |= subprocess.CREATE_NEW_PROCESS_GROUP
                if creationflags:
                    options["creationflags"] = creationflags
                try:
                    process = subprocess.Popen([str(output_path)], **options)
                except OSError as exc:
                    self.show_error(
                        "Windows-Programm konnte nicht gestartet werden",
                        f"Programm: {output_path}\n\n{exc}",
                    )
                    return False
                processes = [
                    running for running in getattr(self, "_pe32_processes", [])
                    if running.poll() is None
                ]
                processes.append(process)
                self._pe32_processes = processes
                document.assembly_status_label.setText(
                    f"Unter Windows gestartet: {output_path.name}"
                )
                if document.generated_assembly_path is not None:
                    document.generated_assembly_status_label.setText(
                        f"Unter Windows gestartet: {output_path.name}"
                    )
                self.log(f"WINDOWS PE START: {output_path}")
                self.statusBar().showMessage(
                    f"Windows-PE gestartet: {output_path.name}"
                )
                return True
            vice_path = self._resolve_vice_for_program_start()
            if vice_path is None:
                return False

            command = [
                str(vice_path),
                "-autostartprgmode",
                "1",
                "-autostart",
                str(output_path),
            ]
            options = {
                "cwd": str(output_path.parent),
                "stdin": subprocess.DEVNULL,
                "stdout": subprocess.DEVNULL,
                "stderr": subprocess.DEVNULL,
            }
            if os.name == "nt" and hasattr(
                subprocess,
                "CREATE_NEW_PROCESS_GROUP",
            ):
                options["creationflags"] = subprocess.CREATE_NEW_PROCESS_GROUP

            try:
                process = subprocess.Popen(command, **options)
            except OSError as exc:
                self.show_error(
                    "VICE konnte nicht gestartet werden",
                    f"Programm: {vice_path}\nPRG: {output_path}\n\n{exc}",
                )
                return False

            processes = [
                running
                for running in getattr(self, "_vice_processes", [])
                if running.poll() is None
            ]
            processes.append(process)
            self._vice_processes = processes
            document.assembly_status_label.setText(
                f"In VICE gestartet: {output_path.name}"
            )
            if document.generated_assembly_path is not None:
                document.generated_assembly_status_label.setText(
                    f"In VICE gestartet: {output_path.name}"
                )
            self.log(
                "VICE START: "
                + self._display_dism_command(command)
            )
            self.statusBar().showMessage(
                f"In VICE gestartet: {output_path.name}"
            )
            return True

        def _launch_amiga_document(
            self,
            document: DocumentEditor,
            output_path: Path,
        ) -> bool:
            winuae_path = self._resolve_winuae_for_program_start()
            if winuae_path is None:
                return False

            if output_path.suffix.casefold() == ".adf":
                command = [
                    str(winuae_path),
                    "-s",
                    "quickstart=a500,1",
                    "-s",
                    f"cpu_model={document.amiga_cpu_model.replace('mk', '')}",
                    "-s",
                    f"fpu_model={document.amiga_fpu_model.split(':', 1)[1].strip() if document.amiga_fpu_model != 'FPU: None' else '0'}",
                    "-s",
                    "use_gui=no",
                    "-0",
                    str(output_path),
                ]
                options = {
                    "cwd": str(output_path.parent),
                    "stdin": subprocess.DEVNULL,
                    "stdout": subprocess.DEVNULL,
                    "stderr": subprocess.DEVNULL,
                }
                if os.name == "nt" and hasattr(
                    subprocess,
                    "CREATE_NEW_PROCESS_GROUP",
                ):
                    options["creationflags"] = (
                        subprocess.CREATE_NEW_PROCESS_GROUP
                    )
                try:
                    process = subprocess.Popen(command, **options)
                except OSError as exc:
                    self.show_error(
                        "WinUAE konnte nicht gestartet werden",
                        f"Programm: {winuae_path}\n"
                        f"Boot-ADF: {output_path}\n\n{exc}",
                    )
                    return False

                processes = [
                    running
                    for running in getattr(self, "_winuae_processes", [])
                    if running.poll() is None
                ]
                processes.append(process)
                self._winuae_processes = processes
                document.assembly_status_label.setText(
                    f"Standalone in WinUAE gestartet: {output_path.name}"
                )
                if document.generated_assembly_path is not None:
                    document.generated_assembly_status_label.setText(
                        f"Standalone in WinUAE gestartet: {output_path.name}"
                    )
                self.log(
                    "WINUAE ADF START: "
                    + self._display_dism_command(command)
                )
                self.statusBar().showMessage(
                    f"Standalone-ADF in WinUAE gestartet: {output_path.name}"
                )
                return True

            active_directories = []
            for process, temporary in self._winuae_boot_directories:
                if process.poll() is None:
                    active_directories.append((process, temporary))
                else:
                    temporary.cleanup()
            self._winuae_boot_directories = active_directories

            temporary = tempfile.TemporaryDirectory(
                prefix="d64_dism_winuae_"
            )
            boot_root = Path(temporary.name)
            startup_directory = boot_root / "S"
            startup_directory.mkdir(parents=True, exist_ok=True)
            mounted_program = boot_root / "program"
            shutil.copy2(output_path, mounted_program)
            (startup_directory / "startup-sequence").write_text(
                "program\n",
                encoding="ascii",
                newline="\n",
            )

            command = [
                str(winuae_path),
                "-s",
                "quickstart=a500,1",
                "-s",
                f"cpu_model={document.amiga_cpu_model.replace('mk', '')}",
                "-s",
                f"fpu_model={document.amiga_fpu_model.split(':', 1)[1].strip() if document.amiga_fpu_model != 'FPU: None' else '0'}",
                "-s",
                "use_gui=no",
                "-s",
                f"filesystem2=rw,DH0:DH0:{boot_root},0",
            ]
            options = {
                "cwd": str(output_path.parent),
                "stdin": subprocess.DEVNULL,
                "stdout": subprocess.DEVNULL,
                "stderr": subprocess.DEVNULL,
            }
            if os.name == "nt" and hasattr(
                subprocess,
                "CREATE_NEW_PROCESS_GROUP",
            ):
                options["creationflags"] = subprocess.CREATE_NEW_PROCESS_GROUP

            try:
                process = subprocess.Popen(command, **options)
            except OSError as exc:
                temporary.cleanup()
                self.show_error(
                    "WinUAE konnte nicht gestartet werden",
                    f"Programm: {winuae_path}\n"
                    f"Amiga-Hunk: {output_path}\n\n{exc}",
                )
                return False

            self._winuae_boot_directories.append((process, temporary))
            document.assembly_status_label.setText(
                f"In WinUAE gestartet: {output_path.name}"
            )
            if document.generated_assembly_path is not None:
                document.generated_assembly_status_label.setText(
                    f"In WinUAE gestartet: {output_path.name}"
                )
            self.log(
                "WINUAE START: "
                + self._display_dism_command(command)
            )
            self.statusBar().showMessage(
                f"In WinUAE gestartet: {output_path.name}"
            )
            return True

        def _confirm_close_document(self, document: DocumentEditor) -> bool:
            if not document.is_modified:
                return True

            answer = self._show_message_box(
                QMessageBox.Question,
                "Änderungen speichern?",
                f"Soll die Datei '{document.display_name}' vor dem Schließen "
                "gespeichert werden?",
                buttons=(
                    QMessageBox.Save
                    | QMessageBox.Discard
                    | QMessageBox.Cancel
                ),
                default_button=QMessageBox.Save,
            )
            if answer == QMessageBox.Save:
                self.document_tabs.setCurrentWidget(document)
                return self._save_document(document, save_as=False)
            return answer == QMessageBox.Discard

        def close_current_document(self) -> bool:
            document = self.current_document()
            if document is None:
                return True
            return self.close_document(document)

        def close_document(self, document: DocumentEditor) -> bool:
            index = self._document_index(document)
            if index < 0:
                return True
            if not self._confirm_close_document(document):
                self.document_tabs.setCurrentWidget(document)
                return False

            # Stage ASM 68: Wird der aktive C64-BASIC-Editor geschlossen,
            # waehrend sein Keyboard-Layout-Snapshot aktiv ist, muss zuerst
            # die vorherige Projekt/Dateisystem-Anordnung restauriert werden.
            # Sonst bleibt nach deleteLater() der temporaere Tastaturzustand
            # (z.B. nur das Projekt-Dock) im Hauptfenster zurueck.
            _keyboard_snapshot = getattr(
                self, "_c64_keyboard_layout_snapshot", None
            )
            _keyboard_owner = getattr(
                self, "_c64_keyboard_layout_owner", None
            )
            if (
                isinstance(document, DocumentEditor)
                and document.is_basic_document
                and _keyboard_snapshot is not None
                and (
                    _keyboard_owner is document
                    or document is self.current_document()
                )
            ):
                self._restore_c64_keyboard_layout_snapshot()

            name = document.display_name
            if document.is_dbase_document and getattr(document, "dbase_process", None) is not None:
                try:
                    if document.dbase_process.state() != QProcess.NotRunning:
                        document.dbase_process.kill()
                        document.dbase_process.waitForFinished(500)
                except RuntimeError:
                    pass
            self.document_tabs.removeTab(index)
            document.deleteLater()
            self._refresh_favorites_menu()
            self._update_document_actions()
            self._update_editor_status_panels()
            self.log(f"Editor geschlossen: {name}")
            return True

        def _ensure_dock_snap_overlay(self) -> DockSnapOverlay:
            overlay = getattr(self, "_dock_snap_overlay", None)
            if overlay is None:
                overlay = DockSnapOverlay(self)
                self._dock_snap_overlay = overlay
            overlay.set_dark_mode(self.dark_mode_enabled)
            return overlay

        def _is_primary_side_dock(self, dock: QDockWidget) -> bool:
            return dock in (
                getattr(self, "left_dock", None),
                getattr(self, "right_dock", None),
            )

        def _other_primary_side_dock(self, dock: QDockWidget):
            if dock is getattr(self, "left_dock", None):
                return getattr(self, "right_dock", None)
            if dock is getattr(self, "right_dock", None):
                return getattr(self, "left_dock", None)
            return None

        def _begin_project_dock_snap(self, dock: QDockWidget) -> None:
            """Stage ASM 66: Overlay fuer Projekt UND Dateisystem anzeigen."""
            if not self._is_primary_side_dock(dock):
                return
            overlay = self._ensure_dock_snap_overlay()
            overlay.show_for_dock(dock)

        def _update_project_dock_snap(
            self,
            dock: QDockWidget,
            global_pos: QPoint,
        ):
            if not self._is_primary_side_dock(dock):
                return Qt.NoDockWidgetArea
            overlay = self._ensure_dock_snap_overlay()
            if not overlay.isVisible():
                overlay.show_for_dock(dock)
            return overlay.update_target(global_pos)

        def _apply_primary_side_dock_layout(
            self,
            dock: QDockWidget,
            area,
            orientation,
            order: str,
        ) -> bool:
            """Projekt/Dateisystem links/rechts neben dem Editor anordnen.

            ``orientation == Horizontal`` ergibt zwei Docks nebeneinander.
            ``orientation == Vertical`` ergibt eine gemeinsame Seiten-Spalte.
            In keinem Fall wird eines der beiden Fenster in Top/BottomArea gelegt;
            damit kann das Dateisystem niemals die gesamte Fensterbreite belegen.
            """
            width_before = int(self.width())
            other = self._other_primary_side_dock(dock)
            if other is None:
                # Stage-64-kompatibler Einzel-Dock-Fallback. Normalerweise sind
                # in Stage 66 beide Primaer-Docks vorhanden.
                self.addDockWidget(area, dock)
                dock.setFloating(False)
                dock.show()
                return True
            if area not in (Qt.LeftDockWidgetArea, Qt.RightDockWidgetArea):
                return False
            if not bool(dock.allowedAreas() & area) or not bool(other.allowedAreas() & area):
                return False

            if str(order) == "before":
                first, second = dock, other
            else:
                first, second = other, dock

            # Erst das erste Fenster auf die gewuenschte Hauptseite setzen,
            # danach das zweite relativ dazu splitten. splitDockWidget() ist
            # genau fuer die verschachtelten QMainWindow-Dockbereiche gedacht.
            self.addDockWidget(area, first)
            first.setFloating(False)
            first.show()
            self.addDockWidget(area, second)
            second.setFloating(False)
            second.show()
            self.splitDockWidget(first, second, orientation)

            # Angenehme Ausgangsgroessen. Der Benutzer kann sie danach frei
            # veraendern; Stage 65 speichert sie mit saveState().
            try:
                if orientation == Qt.Horizontal:
                    self.resizeDocks([first, second], [340, 360], Qt.Horizontal)
                else:
                    available_h = max(260, self.height() - 180)
                    self.resizeDocks(
                        [first, second],
                        [available_h // 2, available_h // 2],
                        Qt.Vertical,
                    )
            except Exception:
                pass

            first.raise_()
            second.raise_()
            if getattr(self, "document_tabs", None) is not None:
                self.document_tabs.updateGeometry()
            self.updateGeometry()
            if int(self.width()) > width_before > 0:
                self.resize(width_before, self.height())
            return True

        def _finish_project_dock_snap(
            self,
            dock: QDockWidget,
            global_pos: QPoint,
        ) -> bool:
            if not self._is_primary_side_dock(dock):
                return False
            overlay = self._ensure_dock_snap_overlay()
            area = overlay.update_target(global_pos)
            target = overlay.active_target
            spec = overlay.target_spec(target)
            overlay.hide_overlay()
            if not spec:
                return False
            _rect, spec_area, orientation, order, _label = spec
            if area != spec_area:
                return False

            if not self._apply_primary_side_dock_layout(
                dock, spec_area, orientation, order
            ):
                return False

            # Stage ASM 69: Nur dieser echte Benutzer-Snap veraendert den
            # autoritativen Layoutzustand. Keyboard Ein/Aus darf ihn niemals
            # ueberschreiben oder aus Geometrien neu ableiten.
            other = self._other_primary_side_dock(dock)
            if other is not None:
                if str(order) == "before":
                    first, second = dock, other
                else:
                    first, second = other, dock
                first_name = (
                    "left_dock"
                    if first is getattr(self, "left_dock", None)
                    else "right_dock"
                )
                second_name = (
                    "left_dock"
                    if second is getattr(self, "left_dock", None)
                    else "right_dock"
                )
                if orientation == Qt.Horizontal:
                    sizes = [max(1, first.width()), max(1, second.width())]
                else:
                    sizes = [max(1, first.height()), max(1, second.height())]
                self._set_authoritative_primary_side_dock_layout({
                    "paired": True,
                    "area": int(spec_area),
                    "orientation": int(orientation),
                    "first": first_name,
                    "second": second_name,
                    "sizes": sizes,
                })

            side_text = "links" if spec_area == Qt.LeftDockWidgetArea else "rechts"
            layout_text = "nebeneinander" if orientation == Qt.Horizontal else "gestapelt"
            dock_text = (
                "Dateisystem"
                if dock is getattr(self, "left_dock", None)
                else "Projekt / Informationen"
            )
            self.statusBar().showMessage(
                f"{dock_text} {side_text} {layout_text} angedockt"
            )
            self.log(
                f"DOCK-SNAP: {dock_text} {side_text}, {layout_text}, Reihenfolge={order}"
            )
            return True

        @staticmethod
        def _dock_features():
            return (
                QDockWidget.DockWidgetMovable
                | QDockWidget.DockWidgetFloatable
                | QDockWidget.DockWidgetClosable
            )

        def _create_left_dock(self) -> None:
            self.left_dock = QDockWidget("Dateisystem und Dateien", self)
            self.left_dock.setObjectName("filesystem_dock")
            self.left_dock.setFeatures(self._dock_features())
            self.left_dock.setAllowedAreas(
                Qt.LeftDockWidgetArea | Qt.RightDockWidgetArea
            )
            self.left_dock.setMinimumWidth(320)

            container = QWidget(self.left_dock)
            layout = QVBoxLayout(container)
            layout.setContentsMargins(6, 6, 6, 6)
            layout.setSpacing(6)

            path_layout = QHBoxLayout()
            self.browse_button = QPushButton(container)
            self.browse_button.setIcon(
                self.style().standardIcon(QStyle.SP_DirOpenIcon)
            )
            self.browse_button.setToolTip("Arbeitsverzeichnis auswählen")
            self.browse_button.setFixedWidth(38)
            self.browse_button.clicked.connect(self.choose_workspace_directory)

            self.path_edit = QLineEdit(container)
            self.path_edit.setClearButtonEnabled(True)
            self.path_edit.setPlaceholderText("Ordnerpfad eingeben und Enter drücken")
            self.path_edit.returnPressed.connect(self.navigate_from_path_edit)

            path_layout.addWidget(self.browse_button)
            path_layout.addWidget(self.path_edit, 1)
            layout.addLayout(path_layout)

            self.file_system_model = QFileSystemModel(self)
            self.file_system_model.setFilter(
                QDir.AllDirs | QDir.NoDotAndDotDot | QDir.Drives
            )
            self.file_system_model.setReadOnly(True)

            self.directory_tree = QTreeView(container)
            self.directory_tree.setObjectName("directory_tree")
            self.directory_tree.setModel(self.file_system_model)
            self.directory_tree.setAnimated(True)
            self.directory_tree.setUniformRowHeights(True)
            self.directory_tree.setHeaderHidden(True)
            self.directory_tree.setExpandsOnDoubleClick(True)
            self.directory_tree.setMinimumHeight(120)
            for column in range(1, 4):
                self.directory_tree.hideColumn(column)
            self.directory_tree.clicked.connect(self.directory_tree_clicked)

            filter_widget = QWidget(container)
            filter_layout = QHBoxLayout(filter_widget)
            filter_layout.setContentsMargins(0, 0, 0, 0)
            filter_layout.setSpacing(4)
            # Die frühere große Filtermatrix bleibt funktional über FILTERS,
            # sichtbar sind aber nur noch die drei Plattform-Schaltflächen.
            self.filter_group = QButtonGroup(self)
            self.filter_group.setExclusive(False)
            self.filter_buttons = {}
            self.platform_filter_buttons = {}

            def add_filter_action(menu: QMenu, text: str, filter_name: str):
                action = menu.addAction(text)
                action.triggered.connect(
                    lambda _checked=False, name=filter_name: self.set_filter(name)
                )
                return action

            platform_tools = {
                "C-64": (
                    ("D64 Disketten-Images", "D64"),
                    ("PRG Programme", "PRG"),
                    ("RAM Images", "RAM"),
                    ("Character Maps", "CHR"),
                    ("Paletten", "PAL"),
                    ("Screens", "SCREEN"),
                    ("Pixel Screens", "PIXEL"),
                ),
                "Amiga": (
                    ("Amiga Programme / ADF", "AMIGA"),
                    ("RAM Images", "RAM"),
                ),
                "Windows": (
                    ("PE32 Programme", "PE32"),
                    ("COFF32 Objekte / Archive", "OBJ"),
                ),
            }

            for platform_name in ("C-64", "Amiga", "Windows"):
                button = QPushButton(platform_name, filter_widget)
                button.setObjectName(
                    "platform_filter_"
                    + platform_name.casefold().replace("-", "").replace(" ", "_")
                )
                button.setMinimumWidth(78)
                button.setMaximumHeight(26)
                button.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)

                menu = QMenu(button)
                source_menu = menu.addMenu("Quellcode")
                add_filter_action(source_menu, "BASIC", "BASIC")
                add_filter_action(source_menu, "Pascal", "PAS")
                add_filter_action(source_menu, "C", "C")
