        @staticmethod
        def _project_marker_path_key(path: Path | str) -> str:
            try:
                return os.path.normcase(str(Path(path).expanduser().resolve())).casefold()
            except (OSError, RuntimeError, ValueError):
                return os.path.normcase(str(Path(path).expanduser())).casefold()

        def _project_marker_root(self, marker_kind: str) -> Optional[QTreeWidgetItem]:
            return getattr(self, "project_marker_roots", {}).get(str(marker_kind))

        def _project_marker_file_item(
            self,
            marker_kind: str,
            path: Path | str,
        ) -> Optional[QTreeWidgetItem]:
            root = self._project_marker_root(marker_kind)
            if root is None:
                return None
            wanted = self._project_marker_path_key(path)
            for index in range(root.childCount()):
                child = root.child(index)
                if self._project_item_kind(child) != PROJECT_NODE_MARKER_FILE:
                    continue
                existing = str(child.data(0, Qt.UserRole + 302) or "")
                if existing and self._project_marker_path_key(existing) == wanted:
                    return child
            return None

        @staticmethod
        def _project_marker_line_values(file_item: QTreeWidgetItem) -> Tuple[int, ...]:
            values = set()
            for index in range(file_item.childCount()):
                leaf = file_item.child(index)
                try:
                    value = int(leaf.data(0, Qt.UserRole + 311) or leaf.text(0))
                except (TypeError, ValueError):
                    continue
                if value > 0:
                    values.add(value)
            return tuple(sorted(values))

        def _project_marker_lines_for_path(
            self,
            marker_kind: str,
            path: Path | str,
        ) -> Tuple[int, ...]:
            item = self._project_marker_file_item(marker_kind, path)
            if item is None:
                return ()
            return self._project_marker_line_values(item)

        def _replace_project_marker_file(
            self,
            marker_kind: str,
            path: Path | str,
            line_numbers: Iterable[int],
            *,
            title: str = "",
            mark_modified: bool = True,
            persist: bool = False,
        ) -> bool:
            root = self._project_marker_root(marker_kind)
            if root is None:
                return False
            try:
                resolved = Path(path).expanduser().resolve()
            except (OSError, RuntimeError, ValueError):
                resolved = Path(path).expanduser()
            path_text = str(resolved)
            lines = tuple(sorted({
                int(value)
                for value in (line_numbers or ())
                if str(value).strip() and int(value) > 0
            }))
            current = self._project_marker_file_item(marker_kind, resolved)
            old_lines = self._project_marker_line_values(current) if current is not None else ()
            old_title = current.text(0) if current is not None else ""
            new_title = str(title).strip() or resolved.name or path_text
            if old_lines == lines and (current is None or old_title == new_title):
                return False

            _signals_were_blocked = self.project_tree.signalsBlocked()
            self.project_tree.blockSignals(True)
            try:
                if not lines:
                    if current is not None:
                        root.takeChild(root.indexOfChild(current))
                else:
                    if current is None:
                        current = QTreeWidgetItem(root, [new_title])
                        current.setData(0, Qt.UserRole + 303, PROJECT_NODE_MARKER_FILE)
                        current.setData(0, Qt.UserRole + 310, marker_kind)
                    current.setText(0, new_title)
                    current.setData(0, Qt.UserRole + 302, path_text)
                    current.setToolTip(0, path_text)
                    current.setIcon(0, self.icon_provider.icon(QFileInfo(path_text)))
                    current.takeChildren()
                    for line_number in lines:
                        leaf = QTreeWidgetItem(current, [str(line_number)])
                        leaf.setData(0, Qt.UserRole + 302, path_text)
                        leaf.setData(0, Qt.UserRole + 303, PROJECT_NODE_MARKER_LINE)
                        leaf.setData(0, Qt.UserRole + 310, marker_kind)
                        leaf.setData(0, Qt.UserRole + 311, int(line_number))
                        leaf.setToolTip(
                            0,
                            f"{resolved.name}, Zeile {line_number} – Doppelklick zum Navigieren",
                        )
                    current.setExpanded(True)
                    root.setExpanded(True)
                root.sortChildren(0, Qt.AscendingOrder)
            finally:
                self.project_tree.blockSignals(_signals_were_blocked)

            if mark_modified:
                self.set_project_modified(True)
            if persist and self.current_project_path is not None:
                self.save_project()
            return True

        def _project_marker_entries(self, marker_kind: str) -> List[Dict[str, object]]:
            root = self._project_marker_root(marker_kind)
            if root is None:
                return []
            result = []
            for index in range(root.childCount()):
                child = root.child(index)
                if self._project_item_kind(child) != PROJECT_NODE_MARKER_FILE:
                    continue
                path_value = str(child.data(0, Qt.UserRole + 302) or "").strip()
                lines = self._project_marker_line_values(child)
                if path_value and lines:
                    result.append({
                        "title": child.text(0),
                        "path": path_value,
                        "lines": list(lines),
                    })
            return result

        def _sync_document_marker_to_project(
            self,
            document: DocumentEditor,
            marker_kind: str,
            *,
            persist: bool = True,
        ) -> bool:
            if getattr(self, "_project_marker_restore_guard", False):
                return False
            if document.path is None:
                return False
            if marker_kind == "breakpoint" and not document.is_pascal_document:
                return False
            editor = document.raw_editor
            lines = (
                editor.breakpoint_lines()
                if marker_kind == "breakpoint"
                else editor.bookmark_lines()
            )
            previous = self._project_marker_lines_for_path(marker_kind, document.path)
            if tuple(previous) == tuple(lines):
                return False
            return self._replace_project_marker_file(
                marker_kind,
                document.path,
                lines,
                title=document.path.name,
                mark_modified=True,
                persist=persist,
            )

        def _restore_project_markers_for_document(self, document: DocumentEditor) -> None:
            if document.path is None:
                return
            self._project_marker_restore_guard = True
            try:
                breakpoints = (
                    self._project_marker_lines_for_path("breakpoint", document.path)
                    if document.is_pascal_document
                    else ()
                )
                bookmarks = self._project_marker_lines_for_path("bookmark", document.path)
                document.raw_editor.replace_gutter_markers(
                    "breakpoint", breakpoints, emit_change=False
                )
                document.raw_editor.replace_gutter_markers(
                    "bookmark", bookmarks, emit_change=False
                )
                if document.is_pascal_document and breakpoints:
                    document.invalidate_assembly_result("Breakpoints aus Projekt geladen")
            finally:
                self._project_marker_restore_guard = False

        def _restore_project_markers_for_open_documents(self) -> None:
            tabs = getattr(self, "document_tabs", None)
            if tabs is None:
                return
            for index in range(tabs.count()):
                document = tabs.widget(index)
                if isinstance(document, DocumentEditor):
                    self._restore_project_markers_for_document(document)
            self._refresh_favorites_menu()

        def _jump_to_project_marker(self, item: QTreeWidgetItem) -> None:
            path_value = str(item.data(0, Qt.UserRole + 302) or "").strip()
            try:
                line_number = int(item.data(0, Qt.UserRole + 311) or item.text(0))
            except (TypeError, ValueError):
                return
            if not path_value or line_number <= 0:
                return
            path = Path(path_value)
            if not path.is_file():
                self.show_error(
                    "Quelldatei nicht gefunden",
                    f"Die Marker-Datei wurde nicht gefunden:\n{path}",
                )
                return
            if not self.open_document(path):
                return
            document = self._find_open_document(path)
            if not isinstance(document, DocumentEditor):
                return
            block = document.raw_editor.document().findBlockByNumber(line_number - 1)
            if not block.isValid():
                self.show_error(
                    "Zeile nicht vorhanden",
                    f"{path.name} besitzt keine Zeile {line_number}.",
                )
                return
            self.document_tabs.setCurrentWidget(document)
            document.views.setCurrentWidget(document.source_page)
            cursor = QTextCursor(block)
            cursor.clearSelection()
            document.raw_editor.setTextCursor(cursor)
            document.raw_editor.centerCursor()
            document.raw_editor.setFocus(Qt.OtherFocusReason)
            marker_kind = str(item.data(0, Qt.UserRole + 310) or "")
            marker_name = "Breakpoint" if marker_kind == "breakpoint" else "Bookmark"
            self.statusBar().showMessage(
                f"{marker_name}: {path.name}, Zeile {line_number}", 6000
            )

        def reset_project_tree(
            self,
            entries: Optional[Dict[str, List[Dict[str, str]]]] = None,
        ) -> None:
            if not hasattr(self, "project_tree"):
                return
            values = entries or empty_project_entries()
            for _target, _settings in PROJECT_WINDOWS_TARGET_SETTINGS.items():
                _input_relative = _project_bool_entry(
                    values, _settings["input_relative_key"], True
                )
                _output_relative = _project_bool_entry(
                    values, _settings["output_relative_key"], True
                )
                self.set_project_windows_relative_paths(
                    _target, "input", _input_relative, mark_modified=False
                )
                self.set_project_windows_relative_paths(
                    _target, "output", _output_relative, mark_modified=False
                )
                self.set_project_windows_search_paths(
                    _target,
                    [
                        entry.get("path", "")
                        for entry in values.get(_settings["input_key"], ())
                    ],
                    mark_modified=False,
                )
                _output_entries = values.get(_settings["output_key"], ())
                self.set_project_windows_output_directory(
                    _target,
                    _output_entries[0].get("path", "")
                    if _output_entries else "",
                    mark_modified=False,
                )
                self.set_project_windows_link_with_ordinals(
                    _target,
                    _project_bool_entry(
                        values,
                        _settings["link_with_ordinals_key"],
                        False,
                    ),
                    mark_modified=False,
                )
                self.set_project_windows_workstation_mode(
                    _target,
                    _project_bool_entry(
                        values,
                        _settings["workstation_mode_key"],
                        False,
                    ),
                    mark_modified=False,
                )
            _active_entries = values.get(PROJECT_C64_OPTIMIZER_ACTIVE_PROFILE_KEY, ())
            _active_profile = (
                str(_active_entries[0].get("value", "68000") or "68000")
                if _active_entries else "68000"
            )
            self.set_project_c64_active_profile(
                _active_profile, mark_modified=False
            )
            for _profile, _profile_settings in PROJECT_C64_ENVIRONMENT_PROFILES.items():
                _screen_keyboard = _project_bool_entry(
                    values, _profile_settings["screen_keyboard_key"], False
                )
                _layout_entries = values.get(_profile_settings["keyboard_layout_key"], ())
                _keyboard_layout = _normalize_project_c64_keyboard_layout(
                    _layout_entries[0].get("value", "qwertz")
                    if _layout_entries else "qwertz"
                )
                self.set_project_c64_environment_settings(
                    _profile, _screen_keyboard, _keyboard_layout, mark_modified=False
                )
            for _profile, _profile_settings in PROJECT_C64_OPTIMIZER_PROFILES.items():
                _enabled = _project_bool_entry(
                    values, _profile_settings["enabled_key"], True
                )
                _strategy_entries = values.get(_profile_settings["strategy_key"], ())
                _strategy = (
                    str(_strategy_entries[0].get("value", "direct") or "direct")
                    if _strategy_entries else "direct"
                )
                self.set_project_c64_optimizer_settings(
                    _profile, _enabled, _strategy, mark_modified=False
                )
            for _profile, _profile_settings in PROJECT_C64_PACKER_PROFILES.items():
                _enabled = _project_bool_entry(
                    values, _profile_settings["enabled_key"], False
                )
                _mode_entries = values.get(_profile_settings["mode_key"], ())
                _mode = (
                    str(_mode_entries[0].get("value", "none") or "none")
                    if _mode_entries else "none"
                )
                _search_entries = values.get(_profile_settings["search_key"], ())
                _search = (
                    str(_search_entries[0].get("value", "balanced") or "balanced")
                    if _search_entries else "balanced"
                )
                _include_decruncher_source = _project_bool_entry(
                    values,
                    _profile_settings["include_decruncher_source_key"],
                    True,
                )
                self.set_project_c64_packer_settings(
                    _profile,
                    _enabled,
                    _mode,
                    _search,
                    _include_decruncher_source,
                    mark_modified=False,
                )
            self.project_tree.blockSignals(True)
            self.project_tree.clear()
            self.project_root_items = {}
            self.project_marker_roots = {}
            self.project_archive_root = None
            self.project_prolog_knowledge_root = None
            self.project_pascal_target_nodes = {}
            self.project_pascal_group_nodes = {}
            self.project_pascal_table_nodes = {}
            self.project_dbase_group_nodes = {}
            self.project_pascal_unit_namespace_nodes = {}
            self._project_pascal_entry_sequence = {}
            self.project_pascal_last_programs = getattr(
                self, "project_pascal_last_programs", {}
            )
            self.project_pascal_last_dlls = getattr(
                self, "project_pascal_last_dlls", {}
            )
            self._project_checkbox_guard = False
            folder_icon = self.style().standardIcon(QStyle.SP_DirClosedIcon)

            # Stage 246: exakt die beiden Debug-Navigationsbereiche stehen
            # vor allen bisherigen Projektkategorien.
            for _marker_kind, _marker_title, _entry_key in (
                ("breakpoint", "Break points", PROJECT_BREAKPOINTS_KEY),
                ("bookmark", "Bookmarks", PROJECT_BOOKMARKS_KEY),
            ):
                _marker_root = QTreeWidgetItem(self.project_tree, [_marker_title])
                _marker_root.setData(0, Qt.UserRole + 303, PROJECT_NODE_MARKER_ROOT)
                _marker_root.setData(0, Qt.UserRole + 310, _marker_kind)
                _marker_root.setIcon(0, folder_icon)
                _marker_root.setToolTip(
                    0,
                    "Gespeicherte Breakpoints"
                    if _marker_kind == "breakpoint"
                    else "Gespeicherte Bookmarks",
                )
                self.project_marker_roots[_marker_kind] = _marker_root
                for _entry in values.get(_entry_key, ()):
                    _path_text = str(_entry.get("path", "")).strip()
                    if _path_text:
                        self._replace_project_marker_file(
                            _marker_kind,
                            Path(_path_text),
                            _entry.get("lines", ()),
                            title=str(_entry.get("title", "")),
                            mark_modified=False,
                            persist=False,
                        )
                _marker_root.setExpanded(True)

            for key, title, _extensions in PROJECT_CATEGORIES:
                root = QTreeWidgetItem(self.project_tree, [title])
                root.setData(0, Qt.UserRole + 301, key)
                root.setIcon(0, folder_icon)
                root.setToolTip(0, "Geschützte Projektkategorie")
                self.project_root_items[key] = root

                if key == "c":
                    archive_root = QTreeWidgetItem(root, ["Archive"])
                    archive_root.setData(0, Qt.UserRole + 301, "c")
                    archive_root.setData(0, Qt.UserRole + 303, PROJECT_NODE_ARCHIVE_ROOT)
                    archive_root.setIcon(0, folder_icon)
                    archive_root.setToolTip(
                        0,
                        "Geschützter Archivknoten für COFF32-/COFF64-Archive",
                    )
                    self.project_archive_root = archive_root

                if key == "dbase":
                    # Stage ASM 29: dBase-Dateien werden nicht mehr direkt
                    # unter dem Hauptknoten gemischt, sondern nach Ressourcentyp
                    # in acht geschützten Unterknoten organisiert.
                    for _role, _role_title, _role_exts, _entry_key in PROJECT_DBASE_GROUPS:
                        _group = QTreeWidgetItem(root, [_role_title])
                        _group.setData(0, Qt.UserRole + 301, "dbase")
                        _group.setData(0, Qt.UserRole + 303, PROJECT_NODE_DBASE_GROUP)
                        _group.setData(0, Qt.UserRole + 306, _role)
                        _group.setIcon(0, folder_icon)
                        _group.setToolTip(
                            0,
                            f"dBase {_role_title}; Dateien: "
                            + ", ".join(f"*{ext}" for ext in _role_exts),
                        )
                        self.project_dbase_group_nodes[_role] = _group
                        for _entry in values.get(_entry_key, ()):
                            _path_text = str(_entry.get("path", "")).strip()
                            if _path_text:
                                self._add_project_dbase_entry(
                                    _role,
                                    Path(_path_text),
                                    title=str(_entry.get("title", "")),
                                    mark_modified=False,
                                )
                        _group.setExpanded(True)

                if key == "pascal":
                    for _target, _target_title in (
                        ("pe32", "Windows PE32"),
                        ("pe64", "Windows PE32+"),
                    ):
                        _target_item = QTreeWidgetItem(root, [_target_title])
                        _target_item.setData(0, Qt.UserRole + 301, "pascal")
                        _target_item.setData(0, Qt.UserRole + 303, PROJECT_NODE_PASCAL_TARGET)
                        _target_item.setData(0, Qt.UserRole + 305, _target)
                        _target_item.setIcon(0, folder_icon)
                        _target_item.setToolTip(
                            0, _target_title + "-Buildziel; Rechtsklick für Programm/DLL/Starten"
                        )
                        self.project_pascal_target_nodes[_target] = _target_item

                        for _role, _role_title, _role_kind in (
                            ("modules", "Module", PROJECT_NODE_PASCAL_MODULE_ROOT),
                            ("units", "Units", PROJECT_NODE_PASCAL_UNIT_ROOT),
                        ):
                            _group = QTreeWidgetItem(_target_item, [_role_title])
                            _group.setData(0, Qt.UserRole + 301, "pascal")
                            _group.setData(0, Qt.UserRole + 303, _role_kind)
                            _group.setData(0, Qt.UserRole + 305, _target)
                            _group.setData(0, Qt.UserRole + 306, _role)
                            _group.setIcon(0, folder_icon)
                            _group.setToolTip(
                                0,
                                ("Pascal-Module" if _role == "modules" else "Pascal-Units")
                                + " für " + _target_title,
                            )
                            self.project_pascal_group_nodes[(_target, _role)] = _group
                            _entry_key = PROJECT_PASCAL_TARGET_ENTRY_KEYS[(_target, _role)]
                            for _entry in values.get(_entry_key, ()):
                                _path_text = str(_entry.get("path", "")).strip()
                                if _path_text:
                                    self._add_project_pascal_target_entry(
                                        _group,
                                        Path(_path_text),
                                        title=str(_entry.get("title", "")),
                                        mark_modified=False,
                                    )
                            _group.setExpanded(True)

                        # Stage 236: DBF-Tabellen liegen als eigener geschützter
                        # Ressourcen-Zweig direkt unter dem jeweiligen Windows-Ziel.
                        _table_group = QTreeWidgetItem(_target_item, ["Tabellen"])
                        _table_group.setData(0, Qt.UserRole + 301, "pascal")
                        _table_group.setData(0, Qt.UserRole + 303, PROJECT_NODE_PASCAL_TABLE_ROOT)
                        _table_group.setData(0, Qt.UserRole + 305, _target)
                        _table_group.setData(0, Qt.UserRole + 306, "tables")
                        _table_group.setIcon(0, folder_icon)
                        _table_group.setToolTip(
                            0,
                            "DBF-Tabellen für " + _target_title
                            + "; Rechtsklick zum Hinzufügen, Doppelklick auf eine Datei öffnet Designer/Editor",
                        )
                        self.project_pascal_table_nodes[_target] = _table_group
                        _table_key = PROJECT_PASCAL_TABLE_ENTRY_KEYS[_target]
                        for _entry in values.get(_table_key, ()):
                            _path_text = str(_entry.get("path", "")).strip()
                            if _path_text:
                                self._add_project_pascal_table_entry(
                                    _table_group,
                                    Path(_path_text),
                                    title=str(_entry.get("title", "")),
                                    mark_modified=False,
                                )
                        _table_group.setExpanded(True)
                        _target_item.setExpanded(True)

                if key == "prolog":
                    knowledge_root = QTreeWidgetItem(root, ["Wissen-Datenbanken"])
                    knowledge_root.setData(0, Qt.UserRole + 301, "prolog")
                    knowledge_root.setData(
                        0, Qt.UserRole + 303, PROJECT_NODE_PROLOG_KNOWLEDGE_ROOT
                    )
                    knowledge_root.setIcon(0, folder_icon)
                    knowledge_root.setToolTip(
                        0,
                        "Geschützter Knoten für externe PROLOG-Wissen-Datenbanken",
                    )
                    self.project_prolog_knowledge_root = knowledge_root

                if key != "dbase":
                    for entry in values.get(key, ()):
                        self._add_project_entry(
                            key,
                            Path(str(entry.get("path", ""))),
                            title=str(entry.get("title", "")),
                            mark_modified=False,
                        )
                root.setExpanded(True)

            for knowledge in values.get(PROJECT_PROLOG_KNOWLEDGE_KEY, ()):
                path_value = str(knowledge.get("path", "")).strip()
                if path_value:
                    self._add_project_knowledge_database(
                        Path(path_value),
                        title=str(knowledge.get("title", "")),
                        mark_modified=False,
                    )
            if self.project_prolog_knowledge_root is not None:
                self.project_prolog_knowledge_root.setExpanded(True)

            for archive in values.get(PROJECT_C_ARCHIVES_KEY, ()):
                archive_item = self._add_project_archive(
                    Path(str(archive.get("path", ""))) if archive.get("path") else None,
                    title=str(archive.get("title", "")),
                    mark_modified=False,
                )
                if archive_item is None:
                    continue
                for obj in archive.get("objects", ()):
                    object_path = str(obj.get("path", "")).strip()
                    if object_path:
                        self._add_project_archive_object(
                            archive_item,
                            Path(object_path),
                            title=str(obj.get("title", "")),
                            mark_modified=False,
                        )
                archive_item.setExpanded(True)
            if self.project_archive_root is not None:
                self.project_archive_root.setExpanded(True)
            self.project_tree.blockSignals(False)
            self._restore_project_markers_for_open_documents()

        def _add_project_entry(
            self,
            category_key: str,
            path: Path,
            *,
            title: str = "",
            mark_modified: bool = True,
        ) -> Optional[QTreeWidgetItem]:
            root = self.project_root_items.get(category_key)
            if root is None:
                return None
            try:
                resolved = Path(path).expanduser().resolve()
            except OSError:
                resolved = Path(path).expanduser()
            path_text = str(resolved)
            for index in range(root.childCount()):
                child = root.child(index)
                if str(child.data(0, Qt.UserRole + 302) or "").casefold() == path_text.casefold():
                    self.project_tree.setCurrentItem(child)
                    return child
            display_title = title.strip() or resolved.name or path_text
            child = QTreeWidgetItem(root, [display_title])
            child.setData(0, Qt.UserRole + 301, category_key)
            child.setData(0, Qt.UserRole + 302, path_text)
            child.setToolTip(0, path_text)
            child.setIcon(0, self.icon_provider.icon(QFileInfo(path_text)))
            root.setExpanded(True)
            if mark_modified:
                self.set_project_modified(True)
            return child

        def _add_project_dbase_entry(
            self,
            role: str,
            path: Path,
            *,
            title: str = "",
            mark_modified: bool = True,
        ) -> Optional[QTreeWidgetItem]:
            """Fuegt eine Datei in einen festen dBase-Unterknoten ein."""
            role = str(role or "").strip().casefold()
            group = getattr(self, "project_dbase_group_nodes", {}).get(role)
            spec = PROJECT_DBASE_GROUP_BY_ROLE.get(role)
            if group is None or spec is None:
                return None
            _role_title, extensions, _entry_key = spec
            try:
                resolved = Path(path).expanduser().resolve()
            except OSError:
                resolved = Path(path).expanduser()
            if resolved.suffix.casefold() not in set(extensions):
                return None
            path_text = str(resolved)
            for index in range(group.childCount()):
                child = group.child(index)
                existing = str(child.data(0, Qt.UserRole + 302) or "")
                if existing.casefold() == path_text.casefold():
                    self.project_tree.setCurrentItem(child)
                    return child
            display_title = str(title or "").strip() or resolved.name or path_text
            child = QTreeWidgetItem(group, [display_title])
            child.setData(0, Qt.UserRole + 301, "dbase")
            child.setData(0, Qt.UserRole + 302, path_text)
            child.setData(0, Qt.UserRole + 303, PROJECT_NODE_DBASE_FILE)
            child.setData(0, Qt.UserRole + 306, role)
            child.setToolTip(0, path_text)
            child.setIcon(0, self.icon_provider.icon(QFileInfo(path_text)))
            group.setExpanded(True)
            if mark_modified:
                self.set_project_modified(True)
            return child

        def _add_project_knowledge_database(
            self,
            path: Path,
            *,
            title: str = "",
            mark_modified: bool = True,
        ) -> Optional[QTreeWidgetItem]:
            root = getattr(self, "project_prolog_knowledge_root", None)
            if root is None:
                return None
            try:
                resolved = Path(path).expanduser().resolve()
            except OSError:
                resolved = Path(path).expanduser()
            if resolved.suffix.casefold() not in DocumentEditor.PROLOG_EXTENSIONS:
                return None
            path_text = str(resolved)
            for index in range(root.childCount()):
                child = root.child(index)
                existing = str(child.data(0, Qt.UserRole + 302) or "")
                if existing.casefold() == path_text.casefold():
                    self.project_tree.setCurrentItem(child)
                    return child
            item = QTreeWidgetItem(root, [title.strip() or resolved.name])
            item.setData(0, Qt.UserRole + 301, "prolog")
            item.setData(0, Qt.UserRole + 302, path_text)
            item.setData(
                0, Qt.UserRole + 303, PROJECT_NODE_PROLOG_KNOWLEDGE_FILE
            )
            item.setToolTip(0, path_text)
            item.setIcon(0, self.icon_provider.icon(QFileInfo(path_text)))
            root.setExpanded(True)
            if mark_modified:
                self.set_project_modified(True)
            return item

        def _project_item_kind(self, item: Optional[QTreeWidgetItem]) -> str:
            if item is None:
                return ""
            return str(item.data(0, Qt.UserRole + 303) or "")

        def _set_archive_item_checkable(self, item: QTreeWidgetItem) -> None:
            item.setFlags(
                item.flags()
                | Qt.ItemIsUserCheckable
                | Qt.ItemIsSelectable
                | Qt.ItemIsEnabled
            )
            item.setCheckState(0, Qt.Unchecked)

        def _add_project_archive(
            self,
            path: Optional[Path],
            *,
            title: str = "",
            mark_modified: bool = True,
        ) -> Optional[QTreeWidgetItem]:
            root = getattr(self, "project_archive_root", None)
            if root is None:
                return None
            path_text = ""
            resolved = None
            if path is not None and str(path):
                try:
                    resolved = Path(path).expanduser().resolve()
                except OSError:
                    resolved = Path(path).expanduser()
                path_text = str(resolved)
                for index in range(root.childCount()):
                    child = root.child(index)
                    existing = str(child.data(0, Qt.UserRole + 302) or "")
                    if existing and existing.casefold() == path_text.casefold():
                        self.project_tree.setCurrentItem(child)
                        return child
            display_title = title.strip()
            if not display_title:
                display_title = resolved.name if resolved is not None else "library.a"
            if Path(display_title).suffix.casefold() != ".a":
                display_title += ".a"
            item = QTreeWidgetItem(root, [display_title])
            item.setData(0, Qt.UserRole + 301, "c")
            item.setData(0, Qt.UserRole + 302, path_text)
            item.setData(0, Qt.UserRole + 303, PROJECT_NODE_ARCHIVE)
            # Merkt, ob der Archivknoten selbst explizit angehakt wurde. So
            # führt das manuelle Anhaken aller Objektkinder nicht automatisch
            # zum Löschen des gesamten Archivknotens.
            item.setData(0, Qt.UserRole + 304, False)
            item.setToolTip(0, path_text or "Archivdatei wird beim Erstellen erzeugt")
            item.setIcon(0, self.style().standardIcon(QStyle.SP_FileIcon))
            self._set_archive_item_checkable(item)
            root.setExpanded(True)
            if mark_modified:
                self.set_project_modified(True)
            return item

        def _add_project_archive_object(
            self,
            archive_item: QTreeWidgetItem,
            path: Path,
            *,
            title: str = "",
            mark_modified: bool = True,
        ) -> Optional[QTreeWidgetItem]:
            if self._project_item_kind(archive_item) != PROJECT_NODE_ARCHIVE:
                return None
            try:
                resolved = Path(path).expanduser().resolve()
            except OSError:
                resolved = Path(path).expanduser()
            path_text = str(resolved)
            for index in range(archive_item.childCount()):
                child = archive_item.child(index)
                existing = str(child.data(0, Qt.UserRole + 302) or "")
                if existing.casefold() == path_text.casefold():
                    self.project_tree.setCurrentItem(child)
                    return child
            item = QTreeWidgetItem(archive_item, [title.strip() or resolved.name])
            item.setData(0, Qt.UserRole + 301, "c")
            item.setData(0, Qt.UserRole + 302, path_text)
            item.setData(0, Qt.UserRole + 303, PROJECT_NODE_ARCHIVE_OBJECT)
            item.setToolTip(0, path_text)
            item.setIcon(0, self.icon_provider.icon(QFileInfo(path_text)))
            self._set_archive_item_checkable(item)
            archive_item.setExpanded(True)
            if mark_modified:
                self.set_project_modified(True)
            return item

        def _on_project_item_changed(
            self, item: QTreeWidgetItem, column: int
        ) -> None:
            if column != 0 or getattr(self, "_project_checkbox_guard", False):
                return
            kind = self._project_item_kind(item)
            if kind not in {PROJECT_NODE_ARCHIVE, PROJECT_NODE_ARCHIVE_OBJECT}:
                return
            self._project_checkbox_guard = True
            try:
                if kind == PROJECT_NODE_ARCHIVE:
                    state = item.checkState(0)
                    if state in {Qt.Checked, Qt.Unchecked}:
                        item.setData(
                            0, Qt.UserRole + 304, state == Qt.Checked
                        )
                        for index in range(item.childCount()):
                            item.child(index).setCheckState(0, state)
                else:
                    parent = item.parent()
                    if parent is None or self._project_item_kind(parent) != PROJECT_NODE_ARCHIVE:
                        return
                    # Eine Änderung an einem Kind bedeutet: die Auswahl
                    # stammt nicht mehr vom Archivknoten selbst.
                    parent.setData(0, Qt.UserRole + 304, False)
                    states = [
                        parent.child(index).checkState(0)
                        for index in range(parent.childCount())
                    ]
                    if states and all(state == Qt.Checked for state in states):
                        parent.setCheckState(0, Qt.Checked)
                    elif states and all(state == Qt.Unchecked for state in states):
                        parent.setCheckState(0, Qt.Unchecked)
                    else:
                        parent.setCheckState(0, Qt.PartiallyChecked)
            finally:
                self._project_checkbox_guard = False

        def _refresh_archive_check_state(self, archive_item: QTreeWidgetItem) -> None:
            if self._project_item_kind(archive_item) != PROJECT_NODE_ARCHIVE:
                return
            self._project_checkbox_guard = True
            try:
                archive_item.setData(0, Qt.UserRole + 304, False)
                states = [
                    archive_item.child(index).checkState(0)
                    for index in range(archive_item.childCount())
                ]
                if not states or all(state == Qt.Unchecked for state in states):
                    archive_item.setCheckState(0, Qt.Unchecked)
                elif all(state == Qt.Checked for state in states):
                    archive_item.setCheckState(0, Qt.Checked)
                else:
                    archive_item.setCheckState(0, Qt.PartiallyChecked)
            finally:
                self._project_checkbox_guard = False

        def collect_project_entries(self) -> Dict[str, List[Dict[str, str]]]:
            entries = empty_project_entries()
            for key, _title, _extensions in PROJECT_CATEGORIES:
                root = self.project_root_items.get(key)
                if root is None:
                    continue
                for index in range(root.childCount()):
                    child = root.child(index)
                    if self._project_item_kind(child) == PROJECT_NODE_ARCHIVE_ROOT:
                        continue
                    if self._project_item_kind(child) == PROJECT_NODE_DBASE_GROUP:
                        continue
                    if self._project_item_kind(child) in {
                        PROJECT_NODE_PASCAL_TARGET,
                        PROJECT_NODE_PASCAL_MODULE_ROOT,
                        PROJECT_NODE_PASCAL_UNIT_ROOT,
                        PROJECT_NODE_PASCAL_TABLE_ROOT,
                    }:
                        continue
                    path_value = str(child.data(0, Qt.UserRole + 302) or "")
                    if path_value:
                        entries[key].append(
                            {
                                "title": child.text(0),
                                "path": path_value,
                            }
                        )

            # Stage ASM 29: feste dBase-Unterknoten getrennt persistieren.
            for _role, _title, _extensions, _entry_key in PROJECT_DBASE_GROUPS:
                _group = getattr(self, "project_dbase_group_nodes", {}).get(_role)
                if _group is None:
                    continue
                for _index in range(_group.childCount()):
                    _child = _group.child(_index)
                    if self._project_item_kind(_child) != PROJECT_NODE_DBASE_FILE:
                        continue
                    _path_value = str(_child.data(0, Qt.UserRole + 302) or "").strip()
                    if _path_value:
                        entries[_entry_key].append({
                            "title": _child.text(0),
                            "path": _path_value,
                        })

            archive_root = getattr(self, "project_archive_root", None)
            if archive_root is not None:
                for index in range(archive_root.childCount()):
                    archive_item = archive_root.child(index)
                    if self._project_item_kind(archive_item) != PROJECT_NODE_ARCHIVE:
                        continue
                    objects = []
                    for obj_index in range(archive_item.childCount()):
                        obj_item = archive_item.child(obj_index)
                        path_value = str(obj_item.data(0, Qt.UserRole + 302) or "")
                        if path_value:
                            objects.append({
                                "title": obj_item.text(0),
                                "path": path_value,
                            })
                    entries[PROJECT_C_ARCHIVES_KEY].append({
                        "title": archive_item.text(0),
                        "path": str(archive_item.data(0, Qt.UserRole + 302) or ""),
                        "objects": objects,
                    })

            knowledge_root = getattr(self, "project_prolog_knowledge_root", None)
            if knowledge_root is not None:
                for index in range(knowledge_root.childCount()):
                    child = knowledge_root.child(index)
                    if self._project_item_kind(child) != PROJECT_NODE_PROLOG_KNOWLEDGE_FILE:
                        continue
                    path_value = str(child.data(0, Qt.UserRole + 302) or "")
                    if path_value:
                        entries[PROJECT_PROLOG_KNOWLEDGE_KEY].append({
                            "title": child.text(0),
                            "path": path_value,
                        })
            for (_target, _role), _entry_key in PROJECT_PASCAL_TARGET_ENTRY_KEYS.items():
                _group = getattr(self, "project_pascal_group_nodes", {}).get((_target, _role))
                if _group is None:
                    continue
                for _child in self._project_pascal_source_items_ordered(_group):
                    _path_value = str(_child.data(0, Qt.UserRole + 302) or "").strip()
                    if _path_value:
                        entries[_entry_key].append({
                            "title": str(
                                _child.data(0, Qt.UserRole + 309)
                                or _child.text(0)
                            ),
                            "path": _path_value,
                        })
            for _target, _entry_key in PROJECT_PASCAL_TABLE_ENTRY_KEYS.items():
                _group = getattr(self, "project_pascal_table_nodes", {}).get(_target)
                if _group is None:
                    continue
                for _index in range(_group.childCount()):
                    _child = _group.child(_index)
                    if self._project_item_kind(_child) != PROJECT_NODE_PASCAL_TABLE_FILE:
                        continue
                    _path_value = str(_child.data(0, Qt.UserRole + 302) or "").strip()
                    if _path_value:
                        entries[_entry_key].append({
                            "title": _child.text(0),
                            "path": _path_value,
                        })

            entries[PROJECT_BREAKPOINTS_KEY] = self._project_marker_entries("breakpoint")
            entries[PROJECT_BOOKMARKS_KEY] = self._project_marker_entries("bookmark")

            for _target, _settings in PROJECT_WINDOWS_TARGET_SETTINGS.items():
                entries[_settings["input_key"]] = [
                    {"path": path}
                    for path in self.project_windows_search_paths.get(_target, ())
                    if str(path).strip()
                ]
                _output_value = str(
                    self.project_windows_output_directories.get(_target, "") or ""
                ).strip()
                entries[_settings["output_key"]] = (
                    [{"path": _output_value}] if _output_value else []
                )
                _modes = self.project_windows_relative_paths.get(
                    _target, {"input": True, "output": True}
                )
                entries[_settings["input_relative_key"]] = [{
                    "value": "true" if bool(_modes.get("input", True)) else "false"
                }]
                entries[_settings["output_relative_key"]] = [{
                    "value": "true" if bool(_modes.get("output", True)) else "false"
                }]
                entries[_settings["link_with_ordinals_key"]] = [{
                    "value": (
                        "true"
                        if bool(
                            self.project_windows_link_with_ordinals.get(
                                _target, False
                            )
                        )
                        else "false"
                    )
                }]
                entries[_settings["workstation_mode_key"]] = [{
                    "value": (
                        "true"
                        if bool(
                            self.project_windows_workstation_mode.get(
                                _target, False
                            )
                        )
                        else "false"
                    )
                }]
            entries[PROJECT_C64_OPTIMIZER_ACTIVE_PROFILE_KEY] = [{
                "value": str(self.project_c64_active_profile or "68000")
            }]
            for _profile, _profile_settings in PROJECT_C64_ENVIRONMENT_PROFILES.items():
                entries[_profile_settings["screen_keyboard_key"]] = [{
                    "value": (
                        "true"
                        if bool(self.project_c64_screen_keyboard.get(_profile, False))
                        else "false"
                    )
                }]
                entries[_profile_settings["keyboard_layout_key"]] = [{
                    "value": _normalize_project_c64_keyboard_layout(
                        self.project_c64_keyboard_layout.get(_profile, "qwertz")
                    )
                }]
            for _profile, _profile_settings in PROJECT_C64_OPTIMIZER_PROFILES.items():
                entries[_profile_settings["enabled_key"]] = [{
                    "value": (
                        "true"
                        if bool(self.project_c64_optimizer_enabled.get(_profile, True))
                        else "false"
                    )
                }]
                entries[_profile_settings["strategy_key"]] = [{
                    "value": _normalize_project_c64_optimizer_strategy(
                        self.project_c64_optimizer_strategy.get(_profile, "direct")
                    )
                }]
            for _profile, _profile_settings in PROJECT_C64_PACKER_PROFILES.items():
                entries[_profile_settings["enabled_key"]] = [{
                    "value": (
                        "true"
                        if bool(self.project_c64_packer_enabled.get(_profile, False))
                        else "false"
                    )
                }]
                entries[_profile_settings["mode_key"]] = [{
                    "value": _normalize_project_c64_packer_mode(
                        self.project_c64_packer_mode.get(_profile, "none")
                    )
                }]
                entries[_profile_settings["search_key"]] = [{
                    "value": _normalize_project_c64_packer_search(
                        self.project_c64_packer_search.get(_profile, "balanced")
                    )
                }]
                entries[_profile_settings["include_decruncher_source_key"]] = [{
                    "value": (
                        "true"
                        if bool(
                            self.project_c64_packer_include_decruncher_source.get(
                                _profile, True
                            )
                        )
                        else "false"
                    )
                }]

            # Stage ASM 67: offene C64-BASIC-Editoren als Dateireferenzen
            # projektbezogen sichern. Nur gespeicherte Dateien werden aufgenommen;
            # unbenannte Dokumente besitzen noch keine wiederherstellbare Referenz.
            _active_document = self.current_document()
            _open_c64_editors = []
            for _tab_index in range(self.document_tabs.count()):
                _document = self.document_tabs.widget(_tab_index)
                if not isinstance(_document, DocumentEditor):
                    continue
                if _document.path is None:
                    continue
                if _document.effective_suffix not in DocumentEditor.BASIC_EXTENSIONS:
                    continue
                _splitter = getattr(_document, "basic_editor_splitter", None)
                _splitter_sizes = list(_splitter.sizes()[:2]) if _splitter is not None else []
                _last_sizes = list(
                    getattr(_document, "_basic_keyboard_last_sizes", _splitter_sizes) or []
                )[:2]
                _keyboard = getattr(_document, "basic_screen_keyboard", None)
                _keyboard_host = getattr(_document, "basic_screen_keyboard_scroll", None)
                _entry = {
                    "path": str(_document.path),
                    "active": _document is _active_document,
                    "keyboard_visible": bool(_document.basic_screen_keyboard_visible()),
                    "splitter_sizes": [max(0, int(v)) for v in _splitter_sizes],
                    "keyboard_last_sizes": [max(0, int(v)) for v in _last_sizes],
                }
                # Stage ASM 71: QSplitter.saveState() enthält zusätzlich zu
                # sizes() auch den internen Splitterzustand. Das verhindert,
                # dass Qt beim erneuten Anzeigen der ScrollArea eine andere
                # Tastaturhöhe aus SizeHints ableitet.
                if _splitter is not None:
                    try:
                        _entry["splitter_state"] = base64.b64encode(
                            bytes(_splitter.saveState())
                        ).decode("ascii")
                    except Exception:
                        _entry["splitter_state"] = ""
                    _entry["splitter_handle_width"] = int(_splitter.handleWidth())
                if _keyboard is not None:
                    _entry["keyboard_width"] = int(_keyboard.width())
                    _entry["keyboard_height"] = int(_keyboard.height())
                if _keyboard_host is not None:
                    _entry["keyboard_host_width"] = int(_keyboard_host.width())
                    _entry["keyboard_host_height"] = int(_keyboard_host.height())
                    _entry["keyboard_scroll_x"] = int(
                        _keyboard_host.horizontalScrollBar().value()
                    )
                    _entry["keyboard_scroll_y"] = int(
                        _keyboard_host.verticalScrollBar().value()
                    )
                _open_c64_editors.append(_entry)
            entries[PROJECT_C64_OPEN_EDITORS_KEY] = _open_c64_editors

            _last_basic = getattr(self, "_last_opened_c64_basic_path", None)
            entries[PROJECT_C64_LAST_BASIC_FILE_KEY] = (
                [{"path": str(_last_basic)}] if _last_basic else []
            )

            # Stage ASM 63: Der Pfad im Dateisystem-Dock ist current_directory;
            # die sichtbare TreeList-Wurzel ist workspace_root. Beide Zustände
            # gehören zum Projekt und werden getrennt gespeichert.
            _working_directory = str(
                getattr(self, "current_directory", "") or ""
            ).strip()
            _workspace_root = str(
                getattr(self, "workspace_root", "") or ""
            ).strip()
            entries[PROJECT_WORKING_DIRECTORY_KEY] = (
                [{"path": _working_directory}] if _working_directory else []
            )
            entries[PROJECT_WORKSPACE_ROOT_KEY] = (
                [{"path": _workspace_root}] if _workspace_root else []
            )

            # Stage ASM 70: alle benutzerrelevanten Fenster-/Dockgeometrien
            # explizit projektbezogen sichern. Die PrimaryDockLayout-Struktur
            # bleibt für Anordnung/Orientierung weiterhin autoritativ.
            _session_geometry = self._capture_project_session_geometry()
            entries[PROJECT_SESSION_GEOMETRY_KEY] = (
                [{"value": _session_geometry}] if _session_geometry else []
            )

            # Stage ASM 65: Beim Projekt-Speichern wird genau die aktuelle
            # Anordnung der Anwendung festgehalten. QMainWindow.saveState()
            # erfasst u.a. Projekt-Dock links/rechts, Dateisystem-Dock,
            # Protokoll-Dock, Dockgrößen und Sichtbarkeit.
            try:
                # Solange die C64-Bildschirmtastatur sichtbar ist, ist das
                # Dateisystem-Dock nur temporaer verborgen. Beim Projekt-Speichern
                # darf deshalb nicht dieser Zwischenzustand als dauerhaftes Layout
                # landen, sondern der unmittelbar davor gesicherte ViewState.
                _keyboard_snapshot = getattr(
                    self, "_c64_keyboard_layout_snapshot", None
                )
                _snapshot_state = (
                    _keyboard_snapshot.get("state", b"")
                    if isinstance(_keyboard_snapshot, dict)
                    else b""
                )
                _state_bytes = bytes(_snapshot_state or self.saveState())
                _state_b64 = base64.b64encode(_state_bytes).decode("ascii")
            except Exception:
                _state_b64 = ""
            entries[PROJECT_VIEW_STATE_KEY] = (
                [{"value": _state_b64}] if _state_b64 else []
            )

            # Stage ASM 69: dauerhafte Projekt-/Dateisystem-Dockbeziehung
            # separat speichern. Wenn die Tastatur gerade offen ist, stammt
            # diese Relation aus dem Vor-Tastatur-Snapshot bzw. aus dem letzten
            # Benutzer-Snap und niemals aus dem temporaeren Projekt-oben-Stack.
            _primary_layout = self._capture_primary_side_dock_relationship()
            if not (
                isinstance(_primary_layout, dict)
                and _primary_layout.get("paired")
            ):
                _keyboard_snapshot = getattr(
                    self, "_c64_keyboard_layout_snapshot", None
                )
                if isinstance(_keyboard_snapshot, dict):
                    _primary_layout = _keyboard_snapshot.get(
                        "primary_layout", {}
                    )
            if not (
                isinstance(_primary_layout, dict)
                and _primary_layout.get("paired")
            ):
                _primary_layout = self._capture_primary_side_dock_relationship()
            entries[PROJECT_PRIMARY_DOCK_LAYOUT_KEY] = (
                [{"value": self._copy_primary_side_dock_descriptor(_primary_layout)}]
                if isinstance(_primary_layout, dict)
                and _primary_layout.get("paired")
                else []
            )
            return entries

        def project_has_entries(self) -> bool:
            entries = self.collect_project_entries()
            return any(
                bool(entries.get(key))
                for key, _title, _extensions in PROJECT_CATEGORIES
            ) or bool(entries.get(PROJECT_C_ARCHIVES_KEY)) or bool(
                entries.get(PROJECT_PROLOG_KNOWLEDGE_KEY)
            )

        # Stage 174: Zielgebundene Pascal-Einträge zählen ebenfalls als Projektinhalt.
        def project_has_entries(self) -> bool:
            entries = self.collect_project_entries()
            ordinary = any(
                bool(entries.get(key))
                for key, _title, _extensions in PROJECT_CATEGORIES
            )
            special = (
                bool(entries.get(PROJECT_C_ARCHIVES_KEY))
                or bool(entries.get(PROJECT_PROLOG_KNOWLEDGE_KEY))
                or bool(entries.get(PROJECT_BREAKPOINTS_KEY))
                or bool(entries.get(PROJECT_BOOKMARKS_KEY))
                or any(
                    bool(entries.get(_key))
                    for _key in PROJECT_PASCAL_TARGET_ENTRY_KEYS.values()
                )
                or any(
                    bool(entries.get(_key))
                    for _key in PROJECT_PASCAL_TABLE_ENTRY_KEYS.values()
                )
                or any(
                    bool(entries.get(_key))
                    for _key in PROJECT_DBASE_ENTRY_KEYS
                )
                or any(
                    bool(entries.get(_settings["input_key"]))
                    or bool(entries.get(_settings["output_key"]))
                    or _project_bool_entry(
                        entries,
                        _settings["link_with_ordinals_key"],
                        False,
                    )
                    for _settings in PROJECT_WINDOWS_TARGET_SETTINGS.values()
                )
            )
            return bool(ordinary or special)

        def set_project_modified(self, modified: bool) -> None:
            self.project_modified = bool(modified)
            if hasattr(self, "right_panel_tabs") and hasattr(self, "project_tab"):
                index = self.right_panel_tabs.indexOf(self.project_tab)
                if index >= 0:
                    self.right_panel_tabs.setTabText(
                        index,
                        "Projekt *" if self.project_modified else "Projekt",
                    )

        def choose_project_file(self) -> None:
            start_directory = (
                self.current_project_path.parent
                if self.current_project_path is not None
                else self.current_directory
            )
            filename, _selected_filter = QFileDialog.getOpenFileName(
                self,
                "Projekt öffnen",
                str(start_directory),
                "dBase2Many-Projekte (*.pro);;Alle Dateien (*)",
            )
            if filename:
                self.load_project_file(Path(filename))

        def load_project_from_path_edit(self) -> None:
            value = self.project_path_edit.text().strip()
            if value:
                self.load_project_file(Path(value))

        def _confirm_project_replacement(self, title: str) -> bool:
            if not self.project_modified and not self.project_has_entries():
                return True
            box = QMessageBox(self)
            box.setWindowTitle(title)
            box.setIcon(QMessageBox.Question)
            box.setText(
                "Sollen die gesammelten Projekt-Informationen vor dem "
                "Zurücksetzen gespeichert werden?"
            )
            save_button = box.addButton("Ja, speichern", QMessageBox.AcceptRole)
            discard_button = box.addButton(
                "Nein, nicht speichern", QMessageBox.DestructiveRole
            )
            cancel_button = box.addButton("Abbrechen", QMessageBox.RejectRole)
            box.setDefaultButton(save_button)
            # Stage 68: this is the project/save prompt reached from the main
            # window X button. It previously bypassed _create_message_box(),
            # so only the buttons followed dark mode while the message surface
            # could remain native/light. Preserve the save logic but apply the
            # same explicit dark/light palette and stylesheet.
            self._apply_message_box_theme(box)
            box.exec_()
            clicked = box.clickedButton()
            if clicked is cancel_button:
                return False
            if clicked is save_button:
                return bool(self.save_project())
            return clicked is discard_button

        def _save_project_before_new(self) -> bool:
            """Sichert ein vorhandenes Projekt, bevor der Baum geleert wird."""
            if self.current_project_path is not None:
                return bool(self.save_project())
            if self.project_modified or self.project_has_entries():
                return bool(self.save_project_as())
            return True

        def new_project(self, project_kind: str = "generic") -> None:
            # Ein geöffnetes/gefülltes Projekt wird vor dem Neuanlegen immer
            # gesichert. Bei einem noch namenlosen Projekt fragt save_project_as
            # einmalig nach der gewünschten *.pro-Datei.
            if not self._save_project_before_new():
                return
            self.current_project_path = None
            self.project_path_edit.clear()
            # reset_project_tree() baut ausschließlich die geschützten
            # Hauptknoten aus PROJECT_CATEGORIES wieder auf.
            self.reset_project_tree()
            self.set_project_modified(False)
            kind = str(project_kind or "generic").strip().casefold()
            project_names = {
                "windows": "Windows PE32",
                "windows_pe32": "Windows PE32",
                "windows_pe64": "Windows PE32+",
                "amiga500": "Amiga 500 ADF",
                "c64": "C= 64 mk68x",
                "prolog": "PROLOG",
                "logo": "LOGO",
                "dbase": "dBase",
                "assembler": "Assembler",
            }
            self.current_project_kind = kind
            # Ein Klick auf "Projekt" legt nicht nur einen leeren Baum an,
            # sondern sofort auch eine neue speicherbare *.pro-Datei.
            # _save_project_before_new() hat das vorherige Projekt bereits
            # gesichert.
            new_project_path = self._ensure_project_for_new_document()
            self.right_panel_tabs.setCurrentWidget(self.project_tab)
            self.right_dock.show()
            self.right_dock.raise_()
            self.project_tree.setFocus(Qt.OtherFocusReason)
            description = project_names.get(kind, "leeres Projekt")
            self.statusBar().showMessage(
                f"Neues Projekt angelegt: {description} - {new_project_path.name}"
            )
            self.log(
                "Neues Projekt: Projektbaum auf Hauptknoten zurückgesetzt "
                f"[{description}] -> {new_project_path}"
            )

        def _capture_project_session_geometry(self) -> dict:
            """Stage ASM 70: explizite Projekt-Geometrien erfassen.

            Bei sichtbarer C64-Bildschirmtastatur stammen Projekt-/Dateisystem-
            Dockwerte aus dem Vor-Tastatur-Snapshot, damit ein temporärer Stack
            niemals als dauerhaftes Projektlayout gespeichert wird.
            """
            window_rect = self.geometry()
            try:
                _qt_geometry = base64.b64encode(bytes(self.saveGeometry())).decode("ascii")
            except Exception:
                _qt_geometry = ""
            result = {
                "MainWindow": {
                    "x": int(window_rect.x()),
                    "y": int(window_rect.y()),
                    "width": int(self.width()),
                    "height": int(self.height()),
                    "maximized": bool(self.isMaximized()),
                    "fullscreen": bool(self.isFullScreen()),
                    "qt_geometry": _qt_geometry,
                }
            }
            # Stage ASM 71: zentrale Editorfläche und die äußere Trennlinie
            # zum Projekt-/Dateisystem-Dock explizit sichern. QMainWindow
            # verwendet dafür intern Dock-Separatoren, keine öffentliche
            # QSplitter-Instanz; deshalb ist die Dockbereichsbreite separat nötig.
            _central = self.centralWidget()
            if _central is not None:
                _central_rect = _central.geometry()
                result["CentralArea"] = {
                    "x": int(_central_rect.x()),
                    "y": int(_central_rect.y()),
                    "width": max(1, int(_central.width())),
                    "height": max(1, int(_central.height())),
                }
            _primary = self._capture_primary_side_dock_relationship()
            if isinstance(_primary, dict) and _primary.get("paired"):
                result["PrimaryDockArea"] = {
                    "area": int(_primary.get("area", 0) or 0),
                    "orientation": int(
                        _primary.get("orientation", int(Qt.Vertical))
                        or int(Qt.Vertical)
                    ),
                    "first": str(_primary.get("first", "right_dock")),
                    "second": str(_primary.get("second", "left_dock")),
                    "sizes": [
                        max(1, int(v))
                        for v in list(_primary.get("sizes", ()))[:2]
                    ],
                    "area_width": max(
                        0, int(_primary.get("area_width", 0) or 0)
                    ),
                    "central_width": max(
                        0, int(_primary.get("central_width", 0) or 0)
                    ),
                    "separator_x": int(_primary.get("separator_x", 0) or 0),
                }
            keyboard_snapshot = getattr(self, "_c64_keyboard_layout_snapshot", None)
            snapshot_docks = (
                keyboard_snapshot.get("docks", {})
                if isinstance(keyboard_snapshot, dict) else {}
            )

            def dock_payload(name: str, dock) -> dict:
                if dock is None:
                    return {}
                saved = snapshot_docks.get(name, {}) if name in {"left_dock", "right_dock"} else {}
                if isinstance(saved, dict) and saved:
                    return {
                        "visible": bool(saved.get("visible", True)),
                        "floating": bool(saved.get("floating", False)),
                        "area": int(saved.get("area", int(self.dockWidgetArea(dock))) or 0),
                        "x": int(saved.get("x", dock.x()) or 0),
                        "y": int(saved.get("y", dock.y()) or 0),
                        "width": max(1, int(saved.get("width", dock.width()) or dock.width())),
                        "height": max(1, int(saved.get("height", dock.height()) or dock.height())),
                    }
                rect = dock.geometry()
                width = max(1, int(dock.width()))
                height = max(1, int(dock.height()))
                if dock is getattr(self, "bottom_dock", None):
                    if dock.isVisible():
                        self._protocol_dock_last_width = width
                        self._protocol_dock_last_height = height
                    else:
                        width = max(1, int(getattr(self, "_protocol_dock_last_width", width) or width))
                        height = max(1, int(getattr(self, "_protocol_dock_last_height", height) or height))
                return {
                    "visible": bool(dock.isVisible()),
                    "floating": bool(dock.isFloating()),
                    "area": int(self.dockWidgetArea(dock)),
                    "x": int(rect.x()),
                    "y": int(rect.y()),
                    "width": width,
                    "height": height,
                }

            result["FileSystemDock"] = dock_payload("left_dock", getattr(self, "left_dock", None))
            result["ProjectDock"] = dock_payload("right_dock", getattr(self, "right_dock", None))
            result["ProtocolDock"] = dock_payload("bottom_dock", getattr(self, "bottom_dock", None))
            return result

        @staticmethod
        def _project_geometry_payload(entries) -> dict:
            values = entries.get(PROJECT_SESSION_GEOMETRY_KEY, ())
            payload = values[0].get("value", {}) if values else {}
            if isinstance(payload, str):
                try:
                    payload = json.loads(payload)
                except json.JSONDecodeError:
                    payload = {}
            return payload if isinstance(payload, dict) else {}

        def _apply_saved_dock_geometry(self, dock, payload: dict) -> None:
            if dock is None or not isinstance(payload, dict) or not payload:
                return
            floating = bool(payload.get("floating", False))
            area_value = int(payload.get("area", int(Qt.NoDockWidgetArea)) or 0)
            valid_areas = {
                int(Qt.LeftDockWidgetArea): Qt.LeftDockWidgetArea,
                int(Qt.RightDockWidgetArea): Qt.RightDockWidgetArea,
                int(Qt.TopDockWidgetArea): Qt.TopDockWidgetArea,
                int(Qt.BottomDockWidgetArea): Qt.BottomDockWidgetArea,
            }
            area = valid_areas.get(area_value, Qt.NoDockWidgetArea)
            if dock in (getattr(self, "left_dock", None), getattr(self, "right_dock", None)):
                if area not in (Qt.LeftDockWidgetArea, Qt.RightDockWidgetArea):
                    area = self.dockWidgetArea(dock)
            if floating:
                dock.setFloating(True)
                x = int(payload.get("x", dock.x()) or 0)
                y = int(payload.get("y", dock.y()) or 0)
                width = max(1, int(payload.get("width", dock.width()) or dock.width()))
                height = max(1, int(payload.get("height", dock.height()) or dock.height()))
                dock.setGeometry(x, y, width, height)
            elif area != Qt.NoDockWidgetArea:
                if self.dockWidgetArea(dock) != area or dock.isFloating():
                    self.addDockWidget(area, dock)
                dock.setFloating(False)
                # Projekt/Dateisystem werden in PrimaryDockLayout exakt gesplittet.
                # Für das Protokoll ist Höhe/Breite hier explizit maßgeblich.
                if dock is getattr(self, "bottom_dock", None):
                    size = max(1, int(
                        payload.get("height" if area in (Qt.TopDockWidgetArea, Qt.BottomDockWidgetArea) else "width", 1) or 1
                    ))
                    orientation = (
                        Qt.Vertical if area in (Qt.TopDockWidgetArea, Qt.BottomDockWidgetArea)
                        else Qt.Horizontal
                    )
                    try:
                        self.resizeDocks([dock], [size], orientation)
                    except Exception:
                        pass
            if dock is getattr(self, "bottom_dock", None):
                self._protocol_dock_last_height = max(
                    1, int(payload.get("height", dock.height()) or dock.height())
                )
                self._protocol_dock_last_width = max(
                    1, int(payload.get("width", dock.width()) or dock.width())
                )
            dock.setVisible(bool(payload.get("visible", True)))

        def _restore_project_session_geometry(self, entries) -> bool:
            """Stage ASM 70: Hauptfenster-/Dockgeometrie aus dem Projekt laden."""
            payload = self._project_geometry_payload(entries)
            if not payload:
                self._project_session_geometry_restore_target = {}
                return False
            self._project_session_geometry_restore_target = payload

            main = payload.get("MainWindow", {})
            if isinstance(main, dict) and main:
                width = max(1, int(main.get("width", self.width()) or self.width()))
                height = max(1, int(main.get("height", self.height()) or self.height()))
                x = int(main.get("x", self.x()) or 0)
                y = int(main.get("y", self.y()) or 0)
                _qt_geometry = str(main.get("qt_geometry", "") or "").strip()
                if _qt_geometry:
                    try:
                        _raw_geometry = base64.b64decode(
                            _qt_geometry.encode("ascii"), validate=True
                        )
                        self.restoreGeometry(QByteArray(_raw_geometry))
                    except Exception:
                        pass
                # Projektladen darf exakt die zuvor vom Benutzer gespeicherte
                # Größe setzen; spätere Qt-Dock-/Keyboard-Pässe dürfen sie nicht
                # eigenmächtig verbreitern.
                if not bool(main.get("maximized", False)) and not bool(main.get("fullscreen", False)):
                    self.setGeometry(x, y, width, height)

            self._apply_saved_dock_geometry(
                getattr(self, "left_dock", None), payload.get("FileSystemDock", {})
            )
            self._apply_saved_dock_geometry(
                getattr(self, "right_dock", None), payload.get("ProjectDock", {})
            )
            self._apply_saved_dock_geometry(
                getattr(self, "bottom_dock", None), payload.get("ProtocolDock", {})
            )
            # Stage ASM 71: ViewState/PrimaryDockLayout stellen die Topologie
            # her; PrimaryDockArea setzt danach die tatsächliche Separatorposition
            # zwischen Dockstapel und zentralem Editor zurück.
            _dock_area = payload.get("PrimaryDockArea", {})
            if isinstance(_dock_area, dict) and _dock_area:
                _descriptor = self._capture_primary_side_dock_relationship()
                if isinstance(_descriptor, dict) and _descriptor.get("paired"):
                    for _name in ("area_width", "central_width", "separator_x"):
                        if _name in _dock_area:
                            _descriptor[_name] = _dock_area[_name]
                    self._apply_primary_side_dock_sizes(_descriptor)
                    self._set_authoritative_primary_side_dock_layout(_descriptor)
            self.log("Projekt-Geometrien wiederhergestellt")
            return True

        def _enforce_project_session_geometry(self) -> None:
            """Nach späten Qt-Layoutpässen die gespeicherte Fenstergröße fixieren."""
            payload = getattr(self, "_project_session_geometry_restore_target", {})
            main = payload.get("MainWindow", {}) if isinstance(payload, dict) else {}
            if not isinstance(main, dict) or not main:
                return
            width = max(1, int(main.get("width", self.width()) or self.width()))
            height = max(1, int(main.get("height", self.height()) or self.height()))
            if self.width() != width or self.height() != height:
                self.resize(width, height)
            protocol = payload.get("ProtocolDock", {})
            if isinstance(protocol, dict) and protocol:
                self._apply_saved_dock_geometry(getattr(self, "bottom_dock", None), protocol)
            _dock_area = payload.get("PrimaryDockArea", {})
            if (
                isinstance(_dock_area, dict)
                and _dock_area
                and getattr(self, "_c64_keyboard_layout_snapshot", None) is None
            ):
                _descriptor = self._capture_primary_side_dock_relationship()
                if isinstance(_descriptor, dict) and _descriptor.get("paired"):
                    for _name in ("area_width", "central_width", "separator_x"):
                        if _name in _dock_area:
                            _descriptor[_name] = _dock_area[_name]
                    self._apply_primary_side_dock_sizes(_descriptor)

        def _restore_project_view_state(self, entries) -> bool:
            """Stage ASM 65: projektbezogenes Dock-/Editor-Layout laden."""
            _values = entries.get(PROJECT_VIEW_STATE_KEY, ())
            if not _values:
                return False
            _encoded = str(_values[0].get("value", "") or "").strip()
            if not _encoded:
                return False
            try:
                _raw = base64.b64decode(_encoded.encode("ascii"), validate=True)
            except (ValueError, UnicodeError):
                self.log("Projekt-Ansicht: ungültiger ViewState; Standardlayout bleibt aktiv")
                return False
            if not _raw:
                return False
            try:
                _ok = bool(self.restoreState(QByteArray(_raw)))
            except Exception as exc:
                self.log(f"Projekt-Ansicht konnte nicht wiederhergestellt werden: {exc}")
                return False
            if not _ok:
                self.log("Projekt-Ansicht: Qt konnte den gespeicherten ViewState nicht anwenden")
                return False

            # Stage ASM 66: Projekt- und Dateisystem-Dock duerfen nur links
            # oder rechts vom Editor liegen. Ein alter ViewState, der eines der
            # Fenster oben/unten abgelegt hat, wird deshalb sanft normalisiert.
            for _dock, _fallback in (
                (getattr(self, "left_dock", None), Qt.LeftDockWidgetArea),
                (getattr(self, "right_dock", None), Qt.RightDockWidgetArea),
            ):
                if _dock is not None and not _dock.isFloating():
                    _area = self.dockWidgetArea(_dock)
                    if _area not in (Qt.LeftDockWidgetArea, Qt.RightDockWidgetArea):
                        self.addDockWidget(_fallback, _dock)

            # Stage ASM 69: Qt-ViewState allein ist fuer einen spaeteren
            # Keyboard-Toggle nicht autoritativ genug. Die explizit gespeicherte
            # Split-/Stack-Beziehung wird nach restoreState() deterministisch
            # angewendet und als einziger dauerhafter Layoutzustand gemerkt.
            _layout_values = entries.get(PROJECT_PRIMARY_DOCK_LAYOUT_KEY, ())
            _layout_descriptor = (
                _layout_values[0].get("value", {}) if _layout_values else {}
            )
            if isinstance(_layout_descriptor, str):
                try:
                    _layout_descriptor = json.loads(_layout_descriptor)
                except json.JSONDecodeError:
                    _layout_descriptor = {}
            if isinstance(_layout_descriptor, dict) and _layout_descriptor.get("paired"):
                self._restore_primary_side_dock_relationship(
                    _layout_descriptor, update_authoritative=True
                )
            else:
                # Rueckwaertskompatibilitaet fuer Stage-65..68-Projekte: einmal
                # nach einem Qt-Layout-Pass inferieren, danach wird nicht mehr
                # geraten. Beim naechsten Speichern landet die Relation explizit
                # in PrimaryDockLayout.
                try:
                    QApplication.processEvents()
                except Exception:
                    pass
                _inferred_layout = self._infer_primary_side_dock_relationship()
                if _inferred_layout.get("paired"):
                    self._set_authoritative_primary_side_dock_layout(
                        _inferred_layout
                    )

            # Die zentralen Dokument-Tabs sind kein Dock und bleiben daher
            # automatisch im von den Docks freigelassenen Bereich.
            if getattr(self, "document_tabs", None) is not None:
                self.document_tabs.updateGeometry()
            self.log("Projekt-Ansicht wiederhergestellt")
            return True

        def _apply_c64_basic_editor_session_geometry(
            self, document: DocumentEditor, entry: dict
        ) -> None:
            """Stage ASM 71: exakten BASIC-Splitter-/ScrollArea-Zustand setzen."""
            if not isinstance(document, DocumentEditor) or not isinstance(entry, dict):
                return
            splitter = getattr(document, "basic_editor_splitter", None)
            host = getattr(document, "basic_screen_keyboard_scroll", None)
            keyboard = getattr(document, "basic_screen_keyboard", None)

            last_sizes = list(entry.get("keyboard_last_sizes", ()) or ())[:2]
            host_height = max(0, int(entry.get("keyboard_host_height", 0) or 0))
            if len(last_sizes) >= 2:
                last_sizes = [max(0, int(last_sizes[0])), max(0, int(last_sizes[1]))]
                # Die gespeicherte ScrollArea-Höhe ist für den sichtbaren
                # Tastaturteil autoritativ. Sie darf nicht nur Metadatum sein.
                if host_height > 0:
                    last_sizes[1] = host_height
                document._basic_keyboard_last_sizes = list(last_sizes)

            if keyboard is not None:
                width = max(1, int(entry.get("keyboard_width", keyboard.width()) or keyboard.width()))
                height = max(1, int(entry.get("keyboard_height", keyboard.height()) or keyboard.height()))
                keyboard.resize(width, height)

            if splitter is not None:
                try:
                    handle_width = int(
                        entry.get("splitter_handle_width", splitter.handleWidth())
                        or splitter.handleWidth()
                    )
                    if handle_width > 0:
                        splitter.setHandleWidth(handle_width)
                except Exception:
                    pass

                # QSplitter.saveState zuerst; explizite Pixelgrößen danach.
                # Letztere gewinnen und korrigieren SizeHint-Abweichungen der
                # QScrollArea nach keyboard.adjustSize()/show().
                state_text = str(entry.get("splitter_state", "") or "").strip()
                if state_text and bool(entry.get("keyboard_visible", False)):
                    try:
                        raw = base64.b64decode(state_text.encode("ascii"), validate=True)
                        splitter.restoreState(QByteArray(raw))
                    except Exception:
                        pass

                splitter_sizes = list(entry.get("splitter_sizes", ()) or ())[:2]
                if bool(entry.get("keyboard_visible", False)):
                    if len(splitter_sizes) >= 2:
                        exact_sizes = [
                            max(1, int(splitter_sizes[0])),
                            max(1, int(splitter_sizes[1])),
                        ]
                    elif len(last_sizes) >= 2:
                        exact_sizes = [max(1, last_sizes[0]), max(1, last_sizes[1])]
                    else:
                        exact_sizes = []
                    if len(exact_sizes) == 2:
                        if host_height > 0:
                            exact_sizes[1] = host_height
                        splitter.setSizes(exact_sizes)

            if host is not None:
                # resize() ist bei einem QSplitter-Kind nur eine zusätzliche
                # Geometriehilfe; die eigentliche Höhe kommt aus setSizes().
                if host_height > 0 and bool(entry.get("keyboard_visible", False)):
                    try:
                        host.resize(max(1, host.width()), host_height)
                    except Exception:
                        pass
                try:
                    host.horizontalScrollBar().setValue(
                        int(entry.get("keyboard_scroll_x", 0) or 0)
                    )
                    host.verticalScrollBar().setValue(
                        int(entry.get("keyboard_scroll_y", 0) or 0)
                    )
                except Exception:
                    pass

        def _restore_project_c64_open_editors(self, entries) -> None:
            """Stage ASM 71: C64-BASIC-Editor-Session inklusive exakter Layoutdaten."""
            values = entries.get(PROJECT_C64_OPEN_EDITORS_KEY, ())
            _last_values = entries.get(PROJECT_C64_LAST_BASIC_FILE_KEY, ())
            _last_path = (
                str(_last_values[0].get("path", "") or "").strip()
                if _last_values else ""
            )
            if _last_path:
                self._last_opened_c64_basic_path = Path(_last_path).expanduser()
            if not values:
                return

            active_document = None
            restored_entries = []
            restored = 0

            # open_document() wendet normalerweise die Profil-Vorgabe sofort an.
            # Während Session-Restore würde das bei mehreren BASIC-Tabs bereits
            # Zwischen-Snapshots erzeugen. Daher kurz deaktivieren und danach
            # die pro Datei gespeicherte Sichtbarkeit deterministisch anwenden.
            _default_keyboard_enabled, _keyboard_profile = (
                self._project_c64_screen_keyboard_configuration()
            )
            self.project_c64_screen_keyboard[_keyboard_profile] = False
            try:
                for entry in values:
                    path_value = str(entry.get("path", "") or "").strip()
                    if not path_value:
                        continue
                    editor_path = Path(path_value).expanduser()
                    if editor_path.suffix.casefold() not in DocumentEditor.BASIC_EXTENSIONS:
                        continue
                    if not editor_path.is_file():
                        self.log(
                            "C64 BASIC Editor-Session: Datei nicht gefunden: "
                            f"{editor_path}"
                        )
                        continue
                    if self.open_document(editor_path):
                        restored += 1
                        document = self._find_open_document(editor_path)
                        if document is None:
                            continue
                        restored_entries.append((document, entry))
                        if bool(entry.get("active", False)):
                            active_document = document
            finally:
                self.project_c64_screen_keyboard[_keyboard_profile] = bool(
                    _default_keyboard_enabled
                )

            # Layoutdaten erst anwenden, wenn alle Tabs existieren. So kann kein
            # Zwischen-Tab die gespeicherte Hauptfenster-/Dockgeometrie verfälschen.
            # Vor der Sichtbarkeit wird nur die zuletzt gültige Tastaturhöhe
            # vorgemerkt, damit set_basic_screen_keyboard_visible() bereits mit
            # den Projektwerten statt mit dem Default [650, 220] arbeitet.
            for document, entry in restored_entries:
                last_sizes = list(entry.get("keyboard_last_sizes", ()) or ())[:2]
                host_height = max(0, int(entry.get("keyboard_host_height", 0) or 0))
                if len(last_sizes) >= 2:
                    last_sizes = [max(0, int(last_sizes[0])), max(0, int(last_sizes[1]))]
                    if host_height > 0:
                        last_sizes[1] = host_height
                    document._basic_keyboard_last_sizes = last_sizes

            if active_document is not None:
                self.document_tabs.setCurrentWidget(active_document)
                active_document.focus_preferred_editor()

            # Sichtbarkeit zuletzt setzen, nachdem der aktive Tab feststeht.
            # Nur der aktive Editor darf dabei das äußere Dock-Snapshot auslösen.
            for document, entry in restored_entries:
                visible = bool(entry.get("keyboard_visible", False))
                document.set_basic_screen_keyboard_visible(
                    visible, notify=(document is active_document)
                )
                self._apply_c64_basic_editor_session_geometry(document, entry)
                # show()/adjustSize() und der TabWidget-Layoutpass können die
                # QScrollArea unmittelbar danach noch einmal umrechnen. Deshalb
                # wird derselbe gespeicherte Zustand nach dem Eventloop erneut
                # autoritativ angewendet.
                _entry_copy = dict(entry)
                QTimer.singleShot(
                    0,
                    lambda d=document, e=_entry_copy:
                        self._apply_c64_basic_editor_session_geometry(d, e),
                )
                QTimer.singleShot(
                    75,
                    lambda d=document, e=_entry_copy:
                        self._apply_c64_basic_editor_session_geometry(d, e),
                )

            # open_document() aktualisiert die MRU während des Wiederherstellens;
            # anschließend gilt wieder ausdrücklich der im Projekt gespeicherte Wert.
            if _last_path:
                self._last_opened_c64_basic_path = Path(_last_path).expanduser()
            if restored:
                self.log(
                    f"C64 BASIC Editor-Session wiederhergestellt: {restored} Datei(en)"
                )

        def load_project_file(
            self,
            path: Path,
            *,
            ask_before_replace: bool = True,
        ) -> bool:
            if ask_before_replace and not self._confirm_project_replacement(
                "Projekt öffnen"
            ):
                return False
            try:
                resolved = Path(path).expanduser().resolve()
                entries = load_project_ini(resolved)
            except (OSError, UnicodeError, configparser.Error, ValueError) as exc:
                self.show_error(
                    "Projekt konnte nicht geöffnet werden",
                    f"Die Projektdatei konnte nicht geladen werden:\n{path}\n\n{exc}",
                )
                return False
            self.current_project_path = resolved
            self.project_path_edit.setText(str(resolved))
            # Stage ASM 29: Ein geladenes Projekt mit dBase-Ressourcen behält
            # den dBase-Kontext. Dadurch werden später manuell hinzugefügte
            # *.prg/*.o/*.a-Dateien ebenfalls den festen dBase-Unterknoten
            # zugeordnet und *.prg als dBase-Text statt als C64-Binärdatei
            # behandelt.
            self.current_project_kind = (
                "dbase"
                if (
                    bool(entries.get("dbase"))
                    or any(bool(entries.get(_key)) for _key in PROJECT_DBASE_ENTRY_KEYS)
                )
                else "generic"
            )
            self.reset_project_tree(entries)

            # Stage ASM 63: zuerst die gespeicherte Root-Wurzel der TreeList,
            # danach das im Dateisystem-Dock angezeigte Arbeitsverzeichnis
            # wiederherstellen. Beim Laden darf dies das Projekt weder als
            # geändert markieren noch einen Autosave auslösen.
            _workspace_entries = entries.get(PROJECT_WORKSPACE_ROOT_KEY, ())
            _working_entries = entries.get(PROJECT_WORKING_DIRECTORY_KEY, ())
            _workspace_value = (
                str(_workspace_entries[0].get("path", "") or "").strip()
                if _workspace_entries else ""
            )
            _working_value = (
                str(_working_entries[0].get("path", "") or "").strip()
                if _working_entries else ""
            )

            _workspace_restored = False
            if _workspace_value:
                _workspace_path = Path(_workspace_value).expanduser()
                if _workspace_path.is_dir():
                    self.set_workspace_root(
                        _workspace_path,
                        select=False,
                        mark_project_modified=False,
                        persist_project=False,
                    )
                    _workspace_restored = True
                else:
                    self.log(
                        "Projekt-WorkspaceRoot nicht gefunden; "
                        f"Dateisystem-TreeList bleibt unverändert: {_workspace_path}"
                    )

            if _working_value:
                _working_path = Path(_working_value).expanduser()
                if _working_path.is_dir():
                    self.set_current_directory(
                        _working_path,
                        select_tree=True,
                        mark_project_modified=False,
                        persist_project=False,
                    )
                else:
                    self.log(
                        "Projekt-Arbeitsverzeichnis nicht gefunden; "
                        f"aktuelles Verzeichnis bleibt unverändert: {_working_path}"
                    )
                    self.statusBar().showMessage(
                        f"Projekt geladen, Arbeitsverzeichnis fehlt: {_working_path}",
                        8000,
                    )
            elif _workspace_restored:
                self.set_current_directory(
                    Path(self.workspace_root),
                    select_tree=True,
                    mark_project_modified=False,
                    persist_project=False,
                )
            self.set_project_modified(False)
            self.right_panel_tabs.setCurrentWidget(self.project_tab)

            # Stage ASM 65: Das gespeicherte Projektlayout wird NACH den
            # Projekt-/Workspace-Daten angewendet und überschreibt damit den
            # globalen QSettings-Fensterzustand. Fehlt ein Projekt-ViewState,
            # bleibt das bisherige Verhalten (Projekt-Dock sichtbar) erhalten.
            _view_restored = self._restore_project_view_state(entries)
            _geometry_restored = self._restore_project_session_geometry(entries)
            if not _view_restored:
                if not _geometry_restored:
                    self.right_dock.show()
                    self.right_dock.raise_()
            else:
                # Sichtbare Docks nach restoreState() sicher neu layouten.
                for _dock_name in ("left_dock", "right_dock", "bottom_dock"):
                    _dock = getattr(self, _dock_name, None)
                    if _dock is not None and _dock.isVisible():
                        _dock.updateGeometry()
                QTimer.singleShot(0, self.updateGeometry)

            # Stage ASM 67: Erst nach Workspace und Dock-ViewState die beim
            # letzten Projekt-Speichern offenen C64-BASIC-Dateien wieder öffnen.
            # Ist die Bildschirmtastatur im Projektprofil standardmäßig aktiv,
            # kann sie nun vom bereits restaurierten Layout einen temporären
            # Snapshot nehmen und das Dateisystem-Dock ausblenden.
            self._restore_project_c64_open_editors(entries)
            if _geometry_restored:
                # Qt kann nach Tab-/Splitteraufbau noch einen späten Layoutpass
                # ausführen. Die gespeicherte Projektgröße bleibt autoritativ.
                self._enforce_project_session_geometry()
                QTimer.singleShot(0, self._enforce_project_session_geometry)

            self.statusBar().showMessage(f"Projekt geöffnet: {resolved.name}")
            self.log(f"Projekt geöffnet: {resolved}")
            self._remember_recent_project(resolved)
            return True

        def save_project(self) -> bool:
            if self.current_project_path is None:
                return self.save_project_as()
            try:
                save_project_ini(
                    self.current_project_path,
                    self.collect_project_entries(),
                )
            except OSError as exc:
                self.show_error(
                    "Projekt konnte nicht gespeichert werden",
                    str(exc),
                )
                return False
            self.project_path_edit.setText(str(self.current_project_path))
            self.set_project_modified(False)
            self.statusBar().showMessage(
                f"Projekt gespeichert: {self.current_project_path.name}"
            )
            self.log(f"Projekt gespeichert: {self.current_project_path}")
            self._remember_recent_project(self.current_project_path)
            return True

        def save_project_as(self) -> bool:
            start_path = (
                self.current_project_path
                if self.current_project_path is not None
                else self.current_directory / "project.pro"
            )
            filename, _selected_filter = QFileDialog.getSaveFileName(
                self,
                "Projekt speichern unter",
                str(start_path),
                "dBase2Many-Projekte (*.pro);;Alle Dateien (*)",
            )
            if not filename:
                return False
            target = Path(filename)
            if target.suffix.casefold() != ".pro":
                target = target.with_suffix(".pro")
            try:
                self.current_project_path = target.expanduser().resolve()
            except OSError:
                self.current_project_path = target.expanduser()
            return self.save_project()

        def _project_new_file_directory(self) -> Path:
            """Zielordner fuer neue, ueber das Projekt erzeugte Dateien."""
            if self.current_project_path is not None:
                directory = self.current_project_path.parent
            else:
                directory = self.current_directory
            directory = Path(directory).expanduser()
            directory.mkdir(parents=True, exist_ok=True)
            return directory

        def _project_existing_names(self) -> List[str]:
            names: List[str] = []
            for root in self.project_root_items.values():
                iterator = QTreeWidgetItemIterator(root)
                while iterator.value() is not None:
                    child = iterator.value()
                    if child is not root:
                        names.append(child.text(0))
                        path_value = str(child.data(0, Qt.UserRole + 302) or "")
                        if path_value:
                            path = Path(path_value)
                            names.extend((path.name, path.stem))
                    iterator += 1
            return names

        def _write_new_project_file(
            self,
            category_key: str,
            path: Path,
            *,
            use_template: bool = True,
        ) -> None:
            """Erzeugt eine neue Projektdatei.

            Binäre Spezialeditor-Dateien behalten immer ihre bisherige gültige
            Initialstruktur. Bei Quelltextkategorien steuert ``use_template``,
            ob die vorhandene Vorlage oder eine komplett leere Datei entsteht.
            """
            path.parent.mkdir(parents=True, exist_ok=True)
            if category_key == "character_maps":
                path.write_bytes(bytes(C64_CHARACTER_FILE_SIZE))
                return
            if category_key == "palettes":
                path.write_bytes(encode_c64_palette_data(C64_CHARACTER_PALETTE))
                return
            if category_key == "char_screens":
                path.write_bytes(
                    encode_c64_text_screen_data(
                        bytearray([32] * C64_TEXT_SCREEN_CELL_COUNT),
                        bytearray([1] * C64_TEXT_SCREEN_CELL_COUNT),
                    )
                )
                return
            if category_key == "pixel_screens":
                path.write_bytes(
                    encode_c64_pixel_screen_data(
                        bytearray(C64_PIXEL_SCREEN_PIXEL_COUNT)
                    )
                )
                return
            if category_key == "images":
                image = QImage(320, 200, QImage.Format_ARGB32)
                image.fill(QColor(0, 0, 0))
                if not image.save(str(path), "PNG"):
                    raise OSError(f"Die Bilddatei konnte nicht erzeugt werden: {path}")
                return
            if category_key == "sid_files":
                # Minimale, syntaktisch gueltige PSID-v2-Datei mit einer RTS-
                # Routine bei $1000. Sie kann danach in einem SID-Werkzeug
                # weiterbearbeitet werden.
                payload = bytearray(0x7C)
                payload[0:4] = b"PSID"
                payload[4:6] = (2).to_bytes(2, "big")
                payload[6:8] = (0x7C).to_bytes(2, "big")
                payload[8:10] = (0).to_bytes(2, "big")
                payload[10:12] = (0x1000).to_bytes(2, "big")
                payload[12:14] = (0x1000).to_bytes(2, "big")
                payload[14:16] = (1).to_bytes(2, "big")
                payload[16:18] = (1).to_bytes(2, "big")
                payload[22:54] = b"Unbenannter SID".ljust(32, b"\0")
                payload[54:86] = b"dBase2Many".ljust(32, b"\0")
                payload[86:118] = b"2026".ljust(32, b"\0")
                payload.extend(b"\x00\x10\x60")
                path.write_bytes(payload)
                return
            source_categories = {
                "basic", "assembler", "pascal", "c", "lisp",
                "prolog", "logo", "dbase", "text_files",
            }
            if category_key in source_categories and not use_template:
                path.write_text("", encoding="utf-8", newline="\n")
                return

            source_templates = {
                "basic": (
                    "10 REM NEUES C64 BASIC-PROGRAMM\n"
                    "20 PRINT \"HALLO C64\"\n"
                    "30 END\n"
                ),
                "assembler": (
                    "; Neues MOS-6510-Assemblerprogramm\n"
                    ".org $080D\n"
                    ".entry start\n\n"
                    "start:\n"
                    "    rts\n"
                ),
                "pascal": (
                    "program Unbenannt;\n\n"
                    "begin\n"
                    "end.\n"
                ),
                "c": (
                    "int main(void)\n"
                    "{\n"
                    "    return 0;\n"
                    "}\n"
                ),
                "lisp": (
                    "; Neues LISP-Programm fuer Windows PE32/PE32+\n"
                    "(defun main ()\n"
                    "  (println \"Hallo LISP\"))\n"
                    "(start main)\n"
                ),
                "prolog": (
                    "% Neues PROLOG-Programm fuer Windows PE32/PE32+\n"
                    "message('Hallo PROLOG').\n\n"
                    "main :-\n"
                    "    message(Text),\n"
                    "    writeln(Text).\n"
                ),
                "dbase": (
                    "// Neues dBase-Programm fuer Windows PE32/PE32+\n"
                    "** Variablen sind dynamisch typisiert; ? mit, ?? ohne NewLine\n"
                    "X = 2 + 3 * 4\n"
                    "Text = \"Hallo \" + 'dBase'\n"
                    "? \"Wert von X = \" + X\n"
                    "?? Text\n"
                    "? \"!\"\n"
                    "\n"
                    "** Eingebetteter DEBUG-Tab fuer folgende Ausgabe:\n"
                    "SET FORMAT TO CONSOLE\n"
                    "SET DEBUG ON\n"
                    "? \"Debug: X = \" + X\n"
                    "SET DEBUG OFF\n"
                ),
                "logo": (
                    "; Neues LOGO-Programm fuer Windows PE32\n"
                    "; Startpunkt: X=160, Y=100\n"
                    "east\n"
                    "steps 50\n"
                    "south\n"
                    "steps 30\n"
                    "west\n"
                    "steps 50\n"
                    "north\n"
                    "steps 30\n"
                ),
                "text_files": "",
            }
            path.write_text(
                source_templates.get(category_key, ""),
                encoding="utf-8",
                newline="\n",
            )

        def _open_new_project_file(self, category_key: str, path: Path) -> None:
            if category_key == "character_maps":
                self.show_character_editor(initial_path=path)
            elif category_key == "palettes":
                self.show_palette_editor(initial_path=path)
            elif category_key == "char_screens":
                self.show_text_screen_editor(initial_path=path)
            elif category_key == "pixel_screens":
                self.show_pixel_screen_editor(initial_path=path)
            elif category_key in {"images", "sid_files"}:
                self.open_path(path)
            else:
                self.open_document(path)

        def create_new_project_item(
            self,
            item: QTreeWidgetItem,
            *,
            use_template: bool = True,
        ) -> Optional[QTreeWidgetItem]:
            root = item if item.parent() is None else item.parent()
            category_key = str(root.data(0, Qt.UserRole + 301) or "other")
            directory = self._project_new_file_directory()
            filename = project_untitled_filename(
                category_key,
                self._project_existing_names(),
                directory=directory,
            )
            path = directory / filename
            try:
                self._write_new_project_file(
                    category_key,
                    path,
                    use_template=use_template,
                )
            except (OSError, ValueError) as exc:
                self.show_error(
                    "Neue Projektdatei konnte nicht angelegt werden",
                    f"Die Datei konnte nicht erzeugt werden:\n{path}\n\n{exc}",
                )
                return None
            child = self._add_project_entry(
                category_key,
                path,
                title=filename,
            )
            if child is None:
                return None
            self.project_tree.setCurrentItem(child)
            self.statusBar().showMessage(f"Neue Projektdatei angelegt: {filename}")
            self.log(f"Neue Projektdatei angelegt: {path}")
            if self.current_project_path is not None:
                self.save_project()
            self._open_new_project_file(category_key, path)
            return child

        # -------------------------------------------------------------------
        # Stage 174: Pascal target tree / build orchestration.
        # Stage 190: Unit-Eintraege werden unter einem Namespace-Knoten
        # (System, Crypto, ...) einsortiert. Der echte Pfad bleibt am Blatt.
        # -------------------------------------------------------------------
        def _project_pascal_source_items(
            self,
            root_item: QTreeWidgetItem,
        ):
            for _index in range(root_item.childCount()):
                _child = root_item.child(_index)
                _kind = self._project_item_kind(_child)
                if _kind == PROJECT_NODE_PASCAL_TARGET_SOURCE:
                    yield _child
                elif _kind == PROJECT_NODE_PASCAL_UNIT_NAMESPACE:
                    yield from self._project_pascal_source_items(_child)

        def _project_pascal_source_items_ordered(
            self,
            root_item: QTreeWidgetItem,
        ) -> Tuple[QTreeWidgetItem, ...]:
            _items = list(self._project_pascal_source_items(root_item))
            _ordered = sorted(
                enumerate(_items),
                key=lambda pair: (
                    int(pair[1].data(0, Qt.UserRole + 308) or 0),
                    pair[0],
                ),
            )
            return tuple(pair[1] for pair in _ordered)

        def _project_pascal_unit_namespace_item(
            self,
            group_item: QTreeWidgetItem,
            namespace: str,
        ) -> Optional[QTreeWidgetItem]:
            if self._project_item_kind(group_item) != PROJECT_NODE_PASCAL_UNIT_ROOT:
                return None
            target = str(group_item.data(0, Qt.UserRole + 305) or "").casefold()
            role = str(group_item.data(0, Qt.UserRole + 306) or "").casefold()
            namespace_text = str(namespace or "Units").strip() or "Units"
            cache = getattr(self, "project_pascal_unit_namespace_nodes", {})
            cache_key = (target, role, namespace_text.casefold())
            cached = cache.get(cache_key)
            if (
                cached is not None
                and cached.parent() is group_item
                and self._project_item_kind(cached) == PROJECT_NODE_PASCAL_UNIT_NAMESPACE
            ):
                return cached
            for _index in range(group_item.childCount()):
                _child = group_item.child(_index)
                if self._project_item_kind(_child) != PROJECT_NODE_PASCAL_UNIT_NAMESPACE:
                    continue
                _name = str(_child.data(0, Qt.UserRole + 307) or _child.text(0)).strip()
                if _name.casefold() == namespace_text.casefold():
                    cache[cache_key] = _child
                    self.project_pascal_unit_namespace_nodes = cache
                    return _child
            _item = QTreeWidgetItem(group_item, [namespace_text])
            _item.setData(0, Qt.UserRole + 301, "pascal")
            _item.setData(0, Qt.UserRole + 303, PROJECT_NODE_PASCAL_UNIT_NAMESPACE)
            _item.setData(0, Qt.UserRole + 305, target)
            _item.setData(0, Qt.UserRole + 306, role)
            _item.setData(0, Qt.UserRole + 307, namespace_text)
            _item.setIcon(0, self.style().standardIcon(QStyle.SP_DirClosedIcon))
            _item.setToolTip(0, f"Pascal-Unit-Namespace: {namespace_text}")
            _item.setExpanded(True)
            cache[cache_key] = _item
            self.project_pascal_unit_namespace_nodes = cache
            return _item

        def _add_project_pascal_target_entry(
            self,
            group_item: QTreeWidgetItem,
            path: Path,
            *,
            title: str = "",
            mark_modified: bool = True,
        ) -> Optional[QTreeWidgetItem]:
            kind = self._project_item_kind(group_item)
            if kind not in {
                PROJECT_NODE_PASCAL_MODULE_ROOT,
                PROJECT_NODE_PASCAL_UNIT_ROOT,
            }:
                return None
            target = str(group_item.data(0, Qt.UserRole + 305) or "").casefold()
            role = str(group_item.data(0, Qt.UserRole + 306) or "").casefold()
            if target not in {"pe32", "pe64"} or role not in {"modules", "units"}:
                return None
            try:
                resolved = Path(path).expanduser().resolve()
            except OSError:
                resolved = Path(path).expanduser()
            path_text = str(resolved)
            for child in self._project_pascal_source_items(group_item):
                existing = str(child.data(0, Qt.UserRole + 302) or "")
                if existing.casefold() == path_text.casefold():
                    self.project_tree.setCurrentItem(child)
                    return child

            parent_item = group_item
            display_title = title.strip() or resolved.name or path_text
            if role == "units":
                namespace, leaf_title = project_pascal_unit_tree_parts(
                    resolved, display_title
                )
                namespace_item = self._project_pascal_unit_namespace_item(
                    group_item, namespace
                )
                if namespace_item is None:
                    return None
                parent_item = namespace_item
                display_title = leaf_title

            child = QTreeWidgetItem(parent_item, [display_title])
            child.setData(0, Qt.UserRole + 301, "pascal")
            child.setData(0, Qt.UserRole + 302, path_text)
            child.setData(0, Qt.UserRole + 303, PROJECT_NODE_PASCAL_TARGET_SOURCE)
            child.setData(0, Qt.UserRole + 305, target)
            child.setData(0, Qt.UserRole + 306, role)
            # Der sichtbare Blattname darf verkürzt sein; in der *.pro-Datei
            # bleibt der bisherige/originale Titel erhalten.
            child.setData(0, Qt.UserRole + 309, title.strip() or resolved.name or path_text)
            sequence_key = (target, role)
            sequence = int(
                getattr(self, "_project_pascal_entry_sequence", {}).get(
                    sequence_key, 0
                )
            )
            child.setData(0, Qt.UserRole + 308, sequence)
            self._project_pascal_entry_sequence[sequence_key] = sequence + 1
            child.setToolTip(0, path_text)
            child.setIcon(0, self.icon_provider.icon(QFileInfo(path_text)))
            parent_item.setExpanded(True)
            group_item.setExpanded(True)
            parent = group_item.parent()
            if parent is not None:
                parent.setExpanded(True)
            if mark_modified:
                self.set_project_modified(True)
            return child

        def _add_project_pascal_table_entry(
            self,
            table_root: QTreeWidgetItem,
            path: Path,
            *,
            title: str = "",
            mark_modified: bool = True,
        ) -> Optional[QTreeWidgetItem]:
            """Stage 236: fügt eine vorhandene *.DBF in einen Pascal-Tabellenzweig ein."""
            if self._project_item_kind(table_root) != PROJECT_NODE_PASCAL_TABLE_ROOT:
                return None
            target = str(table_root.data(0, Qt.UserRole + 305) or "").casefold()
            if target not in {"pe32", "pe64"}:
                return None
            try:
                resolved = Path(path).expanduser().resolve()
            except OSError:
                resolved = Path(path).expanduser()
            if resolved.suffix.casefold() != ".dbf":
                return None
            path_text = str(resolved)
            for index in range(table_root.childCount()):
                child = table_root.child(index)
                existing = str(child.data(0, Qt.UserRole + 302) or "")
                if existing.casefold() == path_text.casefold():
                    self.project_tree.setCurrentItem(child)
                    return child
            child = QTreeWidgetItem(table_root, [title.strip() or resolved.name])
            child.setData(0, Qt.UserRole + 301, "pascal")
            child.setData(0, Qt.UserRole + 302, path_text)
            child.setData(0, Qt.UserRole + 303, PROJECT_NODE_PASCAL_TABLE_FILE)
            child.setData(0, Qt.UserRole + 305, target)
            child.setData(0, Qt.UserRole + 306, "tables")
            child.setToolTip(0, path_text)
            child.setIcon(0, self.icon_provider.icon(QFileInfo(path_text)))
            table_root.setExpanded(True)
            parent = table_root.parent()
            if parent is not None:
                parent.setExpanded(True)
            if mark_modified:
                self.set_project_modified(True)
            return child

        def add_project_pascal_tables(
            self,
            table_root: QTreeWidgetItem,
        ) -> None:
            if self._project_item_kind(table_root) != PROJECT_NODE_PASCAL_TABLE_ROOT:
                return
            target = str(table_root.data(0, Qt.UserRole + 305) or "").casefold()
            if target not in {"pe32", "pe64"}:
                return
            filenames, _selected = QFileDialog.getOpenFileNames(
                self,
                "DBF-Tabellen hinzufügen",
                str(self._project_new_file_directory()),
                "dBase DBF (*.dbf);;Alle Dateien (*)",
            )
            added = 0
            for filename in filenames:
                if self._add_project_pascal_table_entry(
                    table_root, Path(filename), title=Path(filename).name
                ) is not None:
                    added += 1
            if added:
                if self.current_project_path is not None:
                    self.save_project()
                target_name = "Windows PE32" if target == "pe32" else "Windows PE32+"
                self.statusBar().showMessage(
                    f"{added} DBF-Tabelle(n) zu {target_name} hinzugefügt"
                )

        def clear_project_pascal_tables(
            self,
            table_root: QTreeWidgetItem,
        ) -> None:
            if self._project_item_kind(table_root) != PROJECT_NODE_PASCAL_TABLE_ROOT:
                return
            count = table_root.childCount()
            if count <= 0:
                return
            answer = self._show_message_box(
                QMessageBox.Question,
                "Pascal-Tabellenreferenzen entfernen",
                f"Sollen alle {count} DBF-Referenzen aus '{table_root.text(0)}' "
                "entfernt werden?\n\nDie DBF-Dateien auf dem Datenträger bleiben erhalten.",
                buttons=QMessageBox.Yes | QMessageBox.No,
                default_button=QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return
            while table_root.childCount():
                table_root.takeChild(0)
            self.set_project_modified(True)
            if self.current_project_path is not None:
                self.save_project()

        def _show_project_pascal_table_root_menu(
            self,
            item: QTreeWidgetItem,
            position,
        ) -> None:
            menu = QMenu(self.project_tree)
            add_action = menu.addAction("Hinzufügen …")
            menu.addSeparator()
            clear_action = menu.addAction("Einträge löschen")
            clear_action.setEnabled(item.childCount() > 0)
            selected = menu.exec_(
                self.project_tree.viewport().mapToGlobal(position)
            )
            if selected is add_action:
                self.add_project_pascal_tables(item)
            elif selected is clear_action:
                self.clear_project_pascal_tables(item)

        def _show_project_pascal_table_file_menu(
            self,
            item: QTreeWidgetItem,
            position,
        ) -> None:
            menu = QMenu(self.project_tree)
            open_action = menu.addAction("Öffnen")
            menu.addSeparator()
            remove_action = menu.addAction("Aus Knoten entfernen")
            selected = menu.exec_(
                self.project_tree.viewport().mapToGlobal(position)
            )
            if selected is open_action:
                self.open_project_item(item)
            elif selected is remove_action:
                self.delete_selected_project_leaves(preferred_item=item)

        def _project_pascal_group_paths(
            self,
            target: str,
            role: str,
        ) -> Tuple[Path, ...]:
            group = getattr(self, "project_pascal_group_nodes", {}).get(
                (str(target).casefold(), str(role).casefold())
            )
            if group is None:
                return ()
            result = []
            seen = set()
            for child in self._project_pascal_source_items_ordered(group):
                path_text = str(child.data(0, Qt.UserRole + 302) or "").strip()
                if not path_text:
                    continue
                path = Path(path_text).expanduser()
                try:
                    path = path.resolve()
                except OSError:
                    pass
                key = str(path).casefold()
                if key not in seen:
                    seen.add(key)
                    result.append(path)
            return tuple(result)

        def add_project_pascal_target_entries(
            self,
            group_item: QTreeWidgetItem,
        ) -> None:
            target = str(group_item.data(0, Qt.UserRole + 305) or "").casefold()
            role = str(group_item.data(0, Qt.UserRole + 306) or "").casefold()
            if target not in {"pe32", "pe64"} or role not in {"modules", "units"}:
                return
            filenames, _selected = QFileDialog.getOpenFileNames(
                self,
                "Pascal-Module hinzufügen" if role == "modules" else "Pascal-Units hinzufügen",
                str(self._project_new_file_directory()),
                (
                    "Pascal/COFF (*.pas *.pp *.o *.obj *.a *.lib);;"
                    "Pascal (*.pas *.pp);;COFF/Archive (*.o *.obj *.a *.lib);;"
                    "Alle Dateien (*)"
                ),
            )
            added = 0
            for filename in filenames:
                if self._add_project_pascal_target_entry(
                    group_item,
                    Path(filename),
                    title=Path(filename).name,
                ) is not None:
                    added += 1
            if added:
                if self.current_project_path is not None:
                    self.save_project()
                self.statusBar().showMessage(
                    f"{added} Pascal-{role} für {target.upper()} hinzugefügt"
                )

        def clear_project_pascal_target_entries(
            self,
            group_item: QTreeWidgetItem,
        ) -> None:
            count = sum(1 for _item in self._project_pascal_source_items(group_item))
            if count <= 0:
                return
            answer = self._show_message_box(
                QMessageBox.Question,
                "Pascal-Zielreferenzen entfernen",
                f"Sollen alle {count} Referenzen aus '{group_item.text(0)}' "
                "entfernt werden?\n\nDie Dateien auf dem Datenträger bleiben erhalten.",
                buttons=QMessageBox.Yes | QMessageBox.No,
                default_button=QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return
            while group_item.childCount():
                group_item.takeChild(0)
            _target = str(group_item.data(0, Qt.UserRole + 305) or "").casefold()
            _role = str(group_item.data(0, Qt.UserRole + 306) or "").casefold()
            self.project_pascal_unit_namespace_nodes = {
                key: value
                for key, value in getattr(
                    self, "project_pascal_unit_namespace_nodes", {}
                ).items()
                if key[:2] != (_target, _role)
            }
            self._project_pascal_entry_sequence[(_target, _role)] = 0
            self.set_project_modified(True)
            if self.current_project_path is not None:
                self.save_project()

        def remove_project_pascal_target_entry(
            self,
            item: QTreeWidgetItem,
        ) -> None:
            if self._project_item_kind(item) != PROJECT_NODE_PASCAL_TARGET_SOURCE:
                return
            parent = item.parent()
            if parent is None:
                return
            parent.takeChild(parent.indexOfChild(item))
            if (
                self._project_item_kind(parent) == PROJECT_NODE_PASCAL_UNIT_NAMESPACE
                and parent.childCount() == 0
            ):
                group = parent.parent()
                if group is not None:
                    target = str(parent.data(0, Qt.UserRole + 305) or "").casefold()
                    role = str(parent.data(0, Qt.UserRole + 306) or "").casefold()
                    namespace = str(
                        parent.data(0, Qt.UserRole + 307) or parent.text(0)
                    ).casefold()
                    group.takeChild(group.indexOfChild(parent))
                    getattr(self, "project_pascal_unit_namespace_nodes", {}).pop(
                        (target, role, namespace), None
                    )
            self.set_project_modified(True)
            if self.current_project_path is not None:
                self.save_project()

        @staticmethod
        def _project_pascal_declared_kind(path: Path) -> str:
            if Path(path).suffix.casefold() not in {".pas", ".pp"}:
                return "object"
            try:
                text = Path(path).read_text(encoding="utf-8-sig")
            except UnicodeError:
                try:
                    text = Path(path).read_text(encoding="cp1252")
                except OSError:
                    return ""
            except OSError:
                return ""
            cleaned = re.sub(r"\(\*.*?\*\)", " ", text, flags=re.DOTALL)
            cleaned = re.sub(r"\{.*?\}", " ", cleaned, flags=re.DOTALL)
            cleaned = re.sub(r"//[^\r\n]*", " ", cleaned)
            match = re.search(
                r"\b(program|library|unit)\b",
                cleaned,
                re.IGNORECASE,
            )
            return match.group(1).casefold() if match else ""

        def _project_pascal_document(
            self,
            path: Path,
            target: str,
        ) -> Optional[DocumentEditor]:
            try:
                resolved = Path(path).expanduser().resolve()
            except OSError:
                resolved = Path(path).expanduser()
            if not resolved.is_file():
                self.show_error(
                    "Pascal-Projektdatei fehlt",
                    f"Datei nicht gefunden:\n{resolved}",
                )
                return None
            document = self._find_open_document(resolved)
            if document is None:
                if not self.open_document(resolved):
                    return None
                document = self._find_open_document(resolved)
            if not isinstance(document, DocumentEditor) or not document.is_pascal_document:
                self.show_error(
                    "Kein Pascal-Modul",
                    f"Die Datei ist kein Pascal-Dokument:\n{resolved}",
                )
                return None
            document.set_build_target(target)
            return document

        def _project_pascal_object_input(
            self,
            path: Path,
            target: str,
            *,
            require_unit: bool,
        ) -> Optional[Path]:
            try:
                resolved = Path(path).expanduser().resolve()
            except OSError:
                resolved = Path(path).expanduser()
            suffix = resolved.suffix.casefold()
            if suffix in {".o", ".obj", ".a", ".lib"}:
                if not resolved.is_file():
                    self.show_error(
                        "Pascal-Linkeingabe fehlt",
                        f"Datei nicht gefunden:\n{resolved}",
                    )
                    return None
                if suffix in {".o", ".obj"} and not _pascal_unit_coff_matches_target(
                    resolved, target
                ):
                    self.show_error(
                        "Falsche COFF-Architektur",
                        f"'{resolved.name}' passt nicht zu {target.upper()}.",
                    )
                    return None
                return resolved
            if suffix not in {".pas", ".pp"}:
                self.show_error(
                    "Ungültiger Pascal-Projekteintrag",
                    f"Erwartet wird Pascal/COFF, erhalten:\n{resolved}",
                )
                return None

            document = self._project_pascal_document(resolved, target)
            if document is None or not self.assemble_document(document):
                return None
            source_kind = str(
                getattr(document, "generated_source_kind", "program") or "program"
            ).strip().casefold()
            if require_unit and source_kind != "unit":
                self.show_error(
                    "Pascal-Unit erwartet",
                    f"'{resolved.name}' ist '{source_kind}', wurde aber unter Units eingefügt.",
                )
                return None
            if source_kind != "unit":
                self.show_error(
                    "Zusätzliches Pascal-Modul ist kein Unit",
                    f"'{resolved.name}' ist '{source_kind}'. Nur das Hauptmodul darf PROGRAM/LIBRARY sein.",
                )
                return None
            if not self.create_coff32_object_document(document):
                return None
            companion = _pascal_unit_coff_output_path(
                resolved,
                target,
                output_directory=self._project_windows_output_path(target),
            )
            if companion.is_file():
                return companion.resolve()
            legacy = self._project_generated_object_path(resolved, target)
            if legacy.is_file():
                return legacy.resolve()
            self.show_error(
                "Pascal-Unit-COFF fehlt",
                f"Für '{resolved.name}' wurde kein COFF-Objekt erzeugt.",
            )
            return None

        def _project_pascal_main_source(
            self,
            target: str,
            desired_kind: str,
            *,
            report_error: bool = True,
        ) -> Optional[Path]:
            modules = self._project_pascal_group_paths(target, "modules")
            sources = [
                path for path in modules
                if path.suffix.casefold() in {".pas", ".pp"}
            ]
            matches = [
                path for path in sources
                if self._project_pascal_declared_kind(path) == desired_kind
            ]
            if len(matches) == 1:
                return matches[0]
            if len(matches) > 1:
                if report_error:
                    self.show_error(
                        "Mehrere Pascal-Hauptmodule",
                        f"Unter {target.upper()} / Module befinden sich mehrere "
                        f"{desired_kind.upper()}-Quellen:\n\n"
                        + "\n".join(str(path) for path in matches),
                    )
                return None
            if len(sources) == 1:
                return sources[0]
            if report_error:
                self.show_error(
                    "Pascal-Hauptmodul fehlt",
                    (
                        "Füge unter Pascal-Programme -> "
                        + ("Windows PE32" if target == "pe32" else "Windows PE32+")
                        + " -> Module genau eine "
                        + desired_kind.upper()
                        + "-Quelle ein."
                    ),
                )
            return None

        def build_project_pascal_target(
            self,
            target: str,
            *,
            build_kind: str,
        ) -> bool:
            target = str(target).casefold()
            desired_kind = str(build_kind).casefold()
            if target not in {"pe32", "pe64"} or desired_kind not in {"program", "library"}:
                return False
            main_path = self._project_pascal_main_source(target, desired_kind)
            if main_path is None:
                return False

            extra_inputs: List[Path] = []
            seen = set()

            def add_input(path: Path) -> bool:
                try:
                    resolved = Path(path).expanduser().resolve()
                except OSError:
                    resolved = Path(path).expanduser()
                key = str(resolved).casefold()
                if key in seen:
                    return True
                if not resolved.is_file():
                    return False
                seen.add(key)
                extra_inputs.append(resolved)
                return True

            # Units zuerst: PUI und architekturspezifische COFFs sind damit
            # aktuell, bevor das Hauptmodul kompiliert wird.
            for unit_path in self._project_pascal_group_paths(target, "units"):
                object_path = self._project_pascal_object_input(
                    unit_path,
                    target,
                    require_unit=True,
                )
                if object_path is None or not add_input(object_path):
                    return False

            # Weitere Module dürfen COFF/Archive oder Pascal-UNITs sein.
            for module_path in self._project_pascal_group_paths(target, "modules"):
                try:
                    same_as_main = module_path.resolve() == main_path.resolve()
                except OSError:
                    same_as_main = module_path == main_path
                if same_as_main:
                    continue
                # Ein PROGRAM- und ein LIBRARY-Hauptmodul dürfen gemeinsam
                # unter Module liegen. Für die jeweils andere Buildaktion ist
                # das Gegenstück kein zusätzliches Linkobjekt.
                _other_kind = self._project_pascal_declared_kind(module_path)
                if _other_kind in {"program", "library"}:
                    continue
                object_path = self._project_pascal_object_input(
                    module_path,
                    target,
                    require_unit=False,
                )
                if object_path is None or not add_input(object_path):
                    return False

            main_document = self._project_pascal_document(main_path, target)
            if main_document is None or not self.assemble_document(main_document):
                return False
            actual_kind = str(
                getattr(main_document, "generated_source_kind", "program") or "program"
            ).strip().casefold()
            if actual_kind != desired_kind:
                self.show_error(
                    "Pascal-Hauptmodul passt nicht zur Aktion",
                    f"'{main_path.name}' wurde als {actual_kind.upper()} erkannt; "
                    f"für diese Aktion wird {desired_kind.upper()} benötigt.",
                )
                return False
            if not self.assemble_generated_document(
                main_document,
                extra_link_inputs=tuple(extra_inputs),
            ):
                return False

            output = main_document.assembled_program_path
            expected_suffix = ".exe" if desired_kind == "program" else ".dll"
            if (
                output is None
                or output.suffix.casefold() != expected_suffix
                or not output.is_file()
            ):
                self.show_error(
                    "Pascal-Build ohne erwartete Ausgabe",
                    f"Erwartet wurde {expected_suffix}, erhalten: {output}",
                )
                return False

            if desired_kind == "program":
                self.project_pascal_last_programs[target] = output.resolve()
                action_name = "Programm"
            else:
                self.project_pascal_last_dlls[target] = output.resolve()
                action_name = "DLL"
            target_name = "Windows PE32" if target == "pe32" else "Windows PE32+"
            self.log(
                f"PASCAL PROJECT {target_name} {action_name.upper()}: "
                f"{main_path.name} + {len(extra_inputs)} Modul/Unit-Input(s) -> {output}"
            )
            self.statusBar().showMessage(
                f"{target_name}: {action_name} erstellt: {output.name}",
                8000,
            )
            if output.parent.resolve() == self.current_directory.resolve():
                self.populate_file_list()
            return True

        def _project_pascal_existing_program(self, target: str) -> Optional[Path]:
            target = str(target).casefold()
            remembered = getattr(self, "project_pascal_last_programs", {}).get(target)
            if remembered is not None and Path(remembered).is_file():
                return Path(remembered).resolve()
            main = self._project_pascal_main_source(
                target,
                "program",
                report_error=False,
            )
            if main is None:
                return None
            candidate = main.with_suffix(".exe")
            return candidate.resolve() if candidate.is_file() else None

        def start_project_pascal_target(self, target: str) -> bool:
            target = str(target).casefold()
            output = self._project_pascal_existing_program(target)
            if output is None:
                self.show_error(
                    "Pascal-Programm nicht vorhanden",
                    "Erstelle zuerst über das Kontextmenü 'Programm erstellen' eine EXE.",
                )
                return False
            main = self._project_pascal_main_source(
                target,
                "program",
                report_error=False,
            )
            if main is None:
                self.show_error(
                    "Pascal-Hauptmodul fehlt",
                    "Das zu startende PROGRAM-Modul ist nicht mehr im Module-Knoten vorhanden.",
                )
                return False
            document = self._project_pascal_document(main, target)
            if document is None:
                return False
            document.assembled_program_path = output
            document.assembled_target = target
            return self._launch_assembled_document(document)

        def _show_project_pascal_target_menu(
            self,
            item: QTreeWidgetItem,
            position,
        ) -> None:
            target = str(item.data(0, Qt.UserRole + 305) or "").casefold()
            if target not in {"pe32", "pe64"}:
                return
            menu = QMenu(self.project_tree)
            program_action = menu.addAction("Programm erstellen")
            dll_action = menu.addAction("DLL erstellen")
            menu.addSeparator()
            start_action = menu.addAction("Starten")
            selected = menu.exec_(
                self.project_tree.viewport().mapToGlobal(position)
            )
            if selected is program_action:
                self.build_project_pascal_target(target, build_kind="program")
            elif selected is dll_action:
                self.build_project_pascal_target(target, build_kind="library")
            elif selected is start_action:
                self.start_project_pascal_target(target)

        def sort_project_pascal_unit_entries(
            self,
            group_item: QTreeWidgetItem,
            *,
            descending: bool,
        ) -> None:
            """Sort Windows Pascal Unit namespace/leaves and persist the order.

            Stage 190 stores the authoritative build/project order in
            Qt.UserRole+308.  Merely calling QTreeWidgetItem.sortChildren()
            would therefore change only the display and collect_project_entries()
            would still write the old sequence.  Stage 191 sorts the visible
            namespace tree, then renumbers every source leaf in that exact
            visual order before save_project().
            """
            if self._project_item_kind(group_item) != PROJECT_NODE_PASCAL_UNIT_ROOT:
                return
            target = str(group_item.data(0, Qt.UserRole + 305) or "").casefold()
            role = str(group_item.data(0, Qt.UserRole + 306) or "").casefold()
            if target not in {"pe32", "pe64"} or role != "units":
                return

            order = Qt.DescendingOrder if descending else Qt.AscendingOrder
            # Keep namespace grouping while making the complete Units branch
            # deterministic in the requested direction.
            group_item.sortChildren(0, order)
            for index in range(group_item.childCount()):
                namespace_item = group_item.child(index)
                if self._project_item_kind(namespace_item) == PROJECT_NODE_PASCAL_UNIT_NAMESPACE:
                    namespace_item.sortChildren(0, order)

            sequence = 0
            for namespace_index in range(group_item.childCount()):
                namespace_item = group_item.child(namespace_index)
                if self._project_item_kind(namespace_item) != PROJECT_NODE_PASCAL_UNIT_NAMESPACE:
                    continue
                for leaf_index in range(namespace_item.childCount()):
                    leaf = namespace_item.child(leaf_index)
                    if self._project_item_kind(leaf) != PROJECT_NODE_PASCAL_TARGET_SOURCE:
                        continue
                    leaf.setData(0, Qt.UserRole + 308, sequence)
                    sequence += 1
            self._project_pascal_entry_sequence[(target, role)] = sequence
            self.set_project_modified(True)

            # The requested sort order is project state, not a transient view
            # preference.  save_project() also opens Save As for an unnamed
            # project, matching all other project mutations.
            if self.save_project():
                direction = "absteigend" if descending else "aufsteigend"
                self.statusBar().showMessage(
                    f"Pascal-Units {direction} sortiert und Projekt gespeichert"
                )

        def _show_project_pascal_group_menu(
            self,
            item: QTreeWidgetItem,
            position,
        ) -> None:
            menu = QMenu(self.project_tree)
            add_action = menu.addAction("Hinzufügen …")
            clear_action = menu.addAction("Einträge löschen")
            clear_action.setEnabled(item.childCount() > 0)
            ascending_action = None
            descending_action = None
            if self._project_item_kind(item) == PROJECT_NODE_PASCAL_UNIT_ROOT:
                menu.addSeparator()
                descending_action = menu.addAction("absteigend sortieren")
                ascending_action = menu.addAction("aufsteigend sortieren")
                has_units = any(self._project_pascal_source_items(item))
                descending_action.setEnabled(has_units)
                ascending_action.setEnabled(has_units)
            selected = menu.exec_(
                self.project_tree.viewport().mapToGlobal(position)
            )
            if selected is add_action:
                self.add_project_pascal_target_entries(item)
            elif selected is clear_action:
                self.clear_project_pascal_target_entries(item)
            elif ascending_action is not None and selected is ascending_action:
                self.sort_project_pascal_unit_entries(item, descending=False)
            elif descending_action is not None and selected is descending_action:
                self.sort_project_pascal_unit_entries(item, descending=True)

        def _show_project_pascal_source_menu(
            self,
            item: QTreeWidgetItem,
            position,
        ) -> None:
            menu = QMenu(self.project_tree)
            compile_action = menu.addAction("Kompilieren")
            compile_action.setShortcut(QKeySequence("F2"))
            open_action = menu.addAction("Öffnen")
            menu.addSeparator()
            remove_action = menu.addAction("Aus Knoten entfernen")
            selected = menu.exec_(
                self.project_tree.viewport().mapToGlobal(position)
            )
            if selected is compile_action:
                self.compile_selected_project_sources(preferred_item=item)
            elif selected is open_action:
                self.open_project_item(item)
            elif selected is remove_action:
                self.remove_project_pascal_target_entry(item)

        @staticmethod
        def _project_source_extensions() -> set[str]:
            return set().union(
                DocumentEditor.BASIC_EXTENSIONS,
                DocumentEditor.ASSEMBLER_EXTENSIONS,
                DocumentEditor.PASCAL_EXTENSIONS,
                DocumentEditor.C_EXTENSIONS,
                DocumentEditor.LISP_EXTENSIONS,
                DocumentEditor.PROLOG_EXTENSIONS,
                DocumentEditor.LOGO_EXTENSIONS,
                DocumentEditor.DBASE_EXTENSIONS,
            )

        def _project_source_path(
            self,
            item: Optional[QTreeWidgetItem],
        ) -> Optional[Path]:
            if item is None or item.childCount() != 0:
                return None
            value = str(item.data(0, Qt.UserRole + 302) or "").strip()
            if not value:
                return None
            path = Path(value).expanduser()
            if path.suffix.casefold() not in self._project_source_extensions():
                return None
            try:
                return path.resolve()
            except OSError:
                return path.absolute()

        def _project_compilable_selection(
            self,
            preferred_item: Optional[QTreeWidgetItem] = None,
        ) -> List[QTreeWidgetItem]:
            selected = list(self.project_tree.selectedItems())
            if preferred_item is not None and preferred_item not in selected:
                selected = [preferred_item]
            if not selected and self.project_tree.currentItem() is not None:
                selected = [self.project_tree.currentItem()]
            return [
                item for item in selected
                if self._project_source_path(item) is not None
            ]

        def compile_selected_project_sources(
            self,
            *,
            preferred_item: Optional[QTreeWidgetItem] = None,
        ) -> bool:
            """Kompiliert markierte Projektblätter ohne EXE-Start."""
            items = self._project_compilable_selection(preferred_item)
            if not items:
                self.statusBar().showMessage(
                    "F2: Kein kompilierbares Modul/Unit-Blatt markiert", 5000
                )
                return False

            succeeded = 0
            failed = 0
            for item in items:
                path = self._project_source_path(item)
                if path is None or not path.is_file():
                    failed += 1
                    self.show_error(
                        "Projektquelle nicht gefunden",
                        f"Datei nicht gefunden:\n{path or item.text(0)}",
                    )
                    continue

                target = str(
                    item.data(0, Qt.UserRole + 305) or ""
                ).casefold()
                document = self._find_open_document(path)
                if document is None:
                    if not self.open_document(path):
                        failed += 1
                        continue
                    document = self._find_open_document(path)
                if not isinstance(document, DocumentEditor):
                    failed += 1
                    continue
                if target in {"pe32", "pe64"}:
                    document.set_build_target(target)
                else:
                    target = str(document.build_target or "").casefold()

                if target in {"pe32", "pe64"}:
                    output_directory = path.parent / target
                    document.project_tree_compile_output_directory = (
                        output_directory.resolve()
                    )
                else:
                    document.project_tree_compile_output_directory = None

                if not self.assemble_document(document):
                    failed += 1
                    continue

                needs_object = (
                    target in {"pe32", "pe64"}
                    and not (
                        document.is_pascal_document
                        and str(
                            getattr(document, "generated_source_kind", "")
                        ).casefold() == "unit"
                    )
                    and not document.is_assembler_document
                )
                if needs_object and not self.create_coff32_object_document(document):
                    failed += 1
                    continue
                succeeded += 1

            if succeeded:
                self.statusBar().showMessage(
                    f"F2: {succeeded} Projektblatt/-blätter kompiliert"
                    + (f", {failed} fehlgeschlagen" if failed else ""),
                    8000,
                )
            return failed == 0 and succeeded == len(items)

        def _show_project_source_menu(
            self,
            item: QTreeWidgetItem,
            position,
        ) -> None:
            menu = QMenu(self.project_tree)
            compile_action = menu.addAction("Kompilieren")
            compile_action.setShortcut(QKeySequence("F2"))
            open_action = menu.addAction("Öffnen")
            menu.addSeparator()
            remove_action = menu.addAction("Aus Projekt entfernen")
            selected = menu.exec_(
                self.project_tree.viewport().mapToGlobal(position)
            )
            if selected is compile_action:
                self.compile_selected_project_sources(preferred_item=item)
            elif selected is open_action:
                self.open_project_item(item)
            elif selected is remove_action:
                self.delete_selected_project_leaves(preferred_item=item)

        def add_project_dbase_entries(self, group_item: QTreeWidgetItem) -> None:
            role = str(group_item.data(0, Qt.UserRole + 306) or "").casefold()
            spec = PROJECT_DBASE_GROUP_BY_ROLE.get(role)
            if spec is None:
                return
            title, extensions, _entry_key = spec
            patterns = " ".join(f"*{ext}" for ext in extensions)
            initial = str(
                self.current_project_path.parent
                if self.current_project_path is not None
                else self.current_directory
            )
            filenames, _selected = QFileDialog.getOpenFileNames(
                self,
                f"dBase {title} hinzufügen",
                initial,
                f"{title} ({patterns});;Alle Dateien (*)",
            )
            added = 0
            for filename in filenames:
                child = self._add_project_dbase_entry(
                    role, Path(filename), title=Path(filename).name
                )
                if child is not None:
                    added += 1
            if added and self.current_project_path is not None:
                self.save_project()
            if added:
                group_item.setExpanded(True)
                self.statusBar().showMessage(
                    f"{added} dBase-{title}-Datei(en) hinzugefügt", 6000
                )

        def clear_project_dbase_group(self, group_item: QTreeWidgetItem) -> None:
            count = group_item.childCount()
            if count <= 0:
                return
            answer = self._show_message_box(
                QMessageBox.Question,
                "dBase-Projekteinträge entfernen",
                f"Sollen alle {count} Einträge aus '{group_item.text(0)}' entfernt werden?\n\n"
                "Die Dateien auf dem Datenträger bleiben erhalten.",
                buttons=QMessageBox.Yes | QMessageBox.No,
                default_button=QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return
            while group_item.childCount():
                group_item.takeChild(0)
            self.set_project_modified(True)
            if self.current_project_path is not None:
                self.save_project()

        def _show_project_dbase_group_menu(self, item: QTreeWidgetItem, position) -> None:
            role = str(item.data(0, Qt.UserRole + 306) or "").casefold()
            menu = QMenu(self.project_tree)
            # Stage ASM 76: Der Etikettenknoten verwendet die vom Benutzer
            # gewünschte kurze Aktion "Hinzufügen". Die übrigen dBase-
            # Ressourcenknoten behalten ihre bisherige Beschriftung.
            add_action = menu.addAction("Hinzufügen" if role == "labels" else "Hinzufügen …")
            clear_action = None
            if role != "labels":
                clear_action = menu.addAction("Einträge löschen")
                clear_action.setEnabled(item.childCount() > 0)
            menu.addSeparator()
            toggle_action = menu.addAction(
                "Knoten schließen" if item.isExpanded() else "Knoten öffnen"
            )
            selected = menu.exec_(
                self.project_tree.viewport().mapToGlobal(position)
            )
            if selected is add_action:
                self.add_project_dbase_entries(item)
            elif clear_action is not None and selected is clear_action:
                self.clear_project_dbase_group(item)
            elif selected is toggle_action:
                item.setExpanded(not item.isExpanded())

        def _show_project_dbase_file_menu(self, item: QTreeWidgetItem, position) -> None:
            role = str(item.data(0, Qt.UserRole + 306) or "").casefold()
            menu = QMenu(self.project_tree)
            open_action = menu.addAction("Öffnen")
            add_action = None
            if role == "labels":
                # Auch auf einem Etiketten-Blatt kann direkt ein weiteres
                # Etikett in denselben Knoten aufgenommen werden.
                add_action = menu.addAction("Hinzufügen")
                remove_action = menu.addAction("Entfernen")
            else:
                remove_action = menu.addAction("Aus Projekt entfernen")
            selected = menu.exec_(
                self.project_tree.viewport().mapToGlobal(position)
            )
            if selected is open_action:
                self.open_project_item(item)
            elif add_action is not None and selected is add_action:
                parent = item.parent()
                if parent is not None:
                    self.add_project_dbase_entries(parent)
            elif selected is remove_action:
                self.delete_selected_project_leaves(preferred_item=item)

        def show_project_context_menu(self, position) -> None:
            item = self.project_tree.itemAt(position)
            if item is None:
                return
            previous_selection = list(self.project_tree.selectedItems())
            item_was_selected = item in previous_selection
            self.project_tree.setCurrentItem(item)
            if item_was_selected:
                for selected_item in previous_selection:
                    selected_item.setSelected(True)
            else:
                self.project_tree.clearSelection()
                item.setSelected(True)
            kind = self._project_item_kind(item)
            if kind in {PROJECT_NODE_MARKER_ROOT, PROJECT_NODE_MARKER_FILE, PROJECT_NODE_MARKER_LINE}:
                menu = QMenu(self.project_tree)
                if kind == PROJECT_NODE_MARKER_LINE:
                    goto_action = menu.addAction("Zu Zeile gehen")
                    remove_action = menu.addAction("Marker entfernen")
                    selected = menu.exec_(
                        self.project_tree.viewport().mapToGlobal(position)
                    )
                    if selected is goto_action:
                        self._jump_to_project_marker(item)
                    elif selected is remove_action:
                        marker_kind = str(item.data(0, Qt.UserRole + 310) or "")
                        path_value = str(item.data(0, Qt.UserRole + 302) or "")
                        try:
                            line_number = int(item.data(0, Qt.UserRole + 311) or item.text(0))
                        except (TypeError, ValueError):
                            line_number = 0
                        remaining = [
                            value
                            for value in self._project_marker_lines_for_path(marker_kind, path_value)
                            if value != line_number
                        ]
                        if self._replace_project_marker_file(
                            marker_kind, path_value, remaining, persist=True
                        ):
                            document = self._find_open_document(Path(path_value))
                            if isinstance(document, DocumentEditor):
                                document.raw_editor.replace_gutter_markers(
                                    marker_kind, remaining, emit_change=False
                                )
                                if marker_kind == "breakpoint":
                                    document.invalidate_assembly_result("Breakpoint entfernt")
                                else:
                                    self._refresh_favorites_menu()
                    return
                toggle_action = menu.addAction(
                    "Knoten schließen" if item.isExpanded() else "Knoten öffnen"
                )
                selected = menu.exec_(
                    self.project_tree.viewport().mapToGlobal(position)
                )
                if selected is toggle_action:
                    item.setExpanded(not item.isExpanded())
                return
            if kind == PROJECT_NODE_PASCAL_TARGET:
                self._show_project_pascal_target_menu(item, position)
                return
            if kind in {
                PROJECT_NODE_PASCAL_MODULE_ROOT,
                PROJECT_NODE_PASCAL_UNIT_ROOT,
            }:
                self._show_project_pascal_group_menu(item, position)
                return
            if kind == PROJECT_NODE_PASCAL_TABLE_ROOT:
                self._show_project_pascal_table_root_menu(item, position)
                return
            if kind == PROJECT_NODE_PASCAL_TABLE_FILE:
                self._show_project_pascal_table_file_menu(item, position)
                return
            if kind == PROJECT_NODE_DBASE_GROUP:
                self._show_project_dbase_group_menu(item, position)
                return
            if kind == PROJECT_NODE_DBASE_FILE:
                self._show_project_dbase_file_menu(item, position)
                return
            if (
                item.parent() is None
                and str(item.data(0, Qt.UserRole + 301) or "").casefold() == "dbase"
            ):
                menu = QMenu(self.project_tree)
                toggle_action = menu.addAction(
                    "Knoten schließen" if item.isExpanded() else "Knoten öffnen"
                )
                selected = menu.exec_(
                    self.project_tree.viewport().mapToGlobal(position)
                )
                if selected is toggle_action:
                    item.setExpanded(not item.isExpanded())
                return
            if kind == PROJECT_NODE_PASCAL_UNIT_NAMESPACE:
                menu = QMenu(self.project_tree)
                add_action = menu.addAction("Unit hinzufügen …")
                toggle_action = menu.addAction(
                    "Knoten schließen" if item.isExpanded() else "Knoten öffnen"
                )
                selected = menu.exec_(
                    self.project_tree.viewport().mapToGlobal(position)
                )
                if selected is add_action and item.parent() is not None:
                    self.add_project_pascal_target_entries(item.parent())
                elif selected is toggle_action:
                    item.setExpanded(not item.isExpanded())
                return
            if kind == PROJECT_NODE_PASCAL_TARGET_SOURCE:
                self._show_project_pascal_source_menu(item, position)
                return
            if not kind and self._project_source_path(item) is not None:
                self._show_project_source_menu(item, position)
                return
            if kind == PROJECT_NODE_ARCHIVE_ROOT:
                self._show_project_archive_root_menu(item, position)
                return
            if kind == PROJECT_NODE_PROLOG_KNOWLEDGE_ROOT:
                self._show_project_prolog_knowledge_root_menu(item, position)
                return
            if kind == PROJECT_NODE_PROLOG_KNOWLEDGE_FILE:
                self._show_project_prolog_knowledge_file_menu(item, position)
                return
            if kind in {PROJECT_NODE_ARCHIVE, PROJECT_NODE_ARCHIVE_OBJECT}:
                self._show_project_archive_item_menu(item, position)
                return

            menu = QMenu(self.project_tree)
            help_action = menu.addAction("Hilfe")
            add_action = menu.addAction("Hinzufügen")
            clear_action = menu.addAction("Einträge löschen")
            root = item if item.parent() is None else item.parent()
            removable_count = sum(
                1
                for index in range(root.childCount())
                if self._project_item_kind(root.child(index)) not in {
                    PROJECT_NODE_ARCHIVE_ROOT,
                    PROJECT_NODE_PROLOG_KNOWLEDGE_ROOT,
                    PROJECT_NODE_PASCAL_TARGET,
                    PROJECT_NODE_PASCAL_TABLE_ROOT,
                }
            )
            clear_action.setEnabled(removable_count > 0)
            selected = menu.exec_(
                self.project_tree.viewport().mapToGlobal(position)
            )
            if selected is help_action:
                self.show_project_item_help(item)
            elif selected is add_action:
                self.add_project_entries(item)
            elif selected is clear_action:
                self.clear_project_entries(item)

        def _project_knowledge_paths(self) -> Tuple[Path, ...]:
            root = getattr(self, "project_prolog_knowledge_root", None)
            if root is None:
                return ()
            result = []
            for index in range(root.childCount()):
                child = root.child(index)
                if self._project_item_kind(child) != PROJECT_NODE_PROLOG_KNOWLEDGE_FILE:
                    continue
                path_text = str(child.data(0, Qt.UserRole + 302) or "").strip()
                if path_text:
                    result.append(Path(path_text))
            return tuple(result)

        def add_project_knowledge_databases(self) -> None:
            root = getattr(self, "project_prolog_knowledge_root", None)
            if root is None:
                return
            initial = str(
                self.current_project_path.parent
                if self.current_project_path is not None
                else self.current_directory
            )
            filenames, _selected = QFileDialog.getOpenFileNames(
                self,
                "PROLOG-Wissen-Datenbanken hinzufügen",
                initial,
                "PROLOG-Wissen-Datenbanken (*.pl *.prolog);;Alle Dateien (*)",
            )
            added = 0
            for filename in filenames:
                path = Path(filename)
                item = self._add_project_knowledge_database(path, title=path.name)
                if item is not None:
                    added += 1
            if added and self.current_project_path is not None:
                self.save_project()
            if added:
                root.setExpanded(True)
                self.statusBar().showMessage(
                    f"{added} Wissen-Datenbank(en) zum Projekt hinzugefügt"
                )

        def clear_project_knowledge_databases(self) -> None:
            root = getattr(self, "project_prolog_knowledge_root", None)
            if root is None or root.childCount() <= 0:
                return
            count = root.childCount()
            answer = self._show_message_box(
                QMessageBox.Question,
                "Wissen-Datenbanken entfernen",
                f"Sollen alle {count} Wissen-Datenbank-Referenzen aus dem Projekt "
                "entfernt werden?\n\nDie Dateien auf dem Datenträger bleiben erhalten.",
                buttons=QMessageBox.Yes | QMessageBox.No,
                default_button=QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return
            while root.childCount():
                root.takeChild(0)
            self.set_project_modified(True)
            if self.current_project_path is not None:
                self.save_project()
            self.statusBar().showMessage(
                f"{count} Wissen-Datenbank-Referenz(en) entfernt"
            )

        def remove_project_knowledge_database(self, item: QTreeWidgetItem) -> None:
            if self._project_item_kind(item) != PROJECT_NODE_PROLOG_KNOWLEDGE_FILE:
                return
            parent = item.parent()
            if parent is None:
                return
            answer = self._show_message_box(
                QMessageBox.Question,
                "Wissen-Datenbank entfernen",
                f"'{item.text(0)}' aus dem Projekt entfernen?\n\n"
                "Die Datei auf dem Datenträger bleibt erhalten.",
                buttons=QMessageBox.Yes | QMessageBox.No,
                default_button=QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return
            parent.takeChild(parent.indexOfChild(item))
            self.set_project_modified(True)
            if self.current_project_path is not None:
                self.save_project()

        def open_prolog_knowledge_source(self, item: QTreeWidgetItem) -> None:
            path_text = str(item.data(0, Qt.UserRole + 302) or "").strip()
            if not path_text:
                return
            path = Path(path_text)
            if not path.exists():
                self.show_error(
                    "Wissen-Datenbank nicht gefunden",
                    f"Die Datei wurde nicht gefunden:\n{path}",
                )
                return
            self.open_document(path)

        def _prolog_knowledge_dock_visibility_changed(self, visible: bool) -> None:
            """Let the knowledge dock consume the complete free work area.

            The filesystem dock is replaced as before. Stage 67 additionally
            hides the normal document-tab central widget while the knowledge
            browser is active; otherwise QMainWindow reserves a central strip
            which cannot be occupied by a side QDockWidget (visible in the
            Stage-66 screenshot as unused space between knowledge and project
            docks). Hiding the central widget lets the dock layout use all free
            horizontal/vertical space.
            """
            if visible:
                if hasattr(self, "left_dock") and self.left_dock.isVisible():
                    self._knowledge_replaced_filesystem_dock = True
                    self.left_dock.hide()
                central = self.centralWidget()
                if central is not None and central.isVisible():
                    self._knowledge_replaced_central_widget = True
                    central.hide()
                QTimer.singleShot(0, self._expand_prolog_knowledge_dock)
            else:
                dialog = getattr(self, "prolog_knowledge_dialog", None)
                if dialog is not None:
                    dialog._save_query_state()
                if (
                    self._knowledge_replaced_filesystem_dock
                    and hasattr(self, "left_dock")
                ):
                    self.left_dock.show()
                self._knowledge_replaced_filesystem_dock = False
                if self._knowledge_replaced_central_widget:
                    central = self.centralWidget()
                    if central is not None:
                        central.show()
                self._knowledge_replaced_central_widget = False

        def _expand_prolog_knowledge_dock(self) -> None:
            dock = getattr(self, "prolog_knowledge_dock", None)
            if dock is None or not dock.isVisible():
                return
            # A very large requested width is intentionally used here: Qt still
            # respects the right/bottom docks, but gives the knowledge dock all
            # remaining space after the central widget has been hidden.
            self.resizeDocks([dock], [100000], Qt.Horizontal)
            self.resizeDocks([dock], [100000], Qt.Vertical)
            dialog = getattr(self, "prolog_knowledge_dialog", None)
            if dialog is not None:
                dialog.setMinimumSize(0, 0)
                dialog.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
                dialog.updateGeometry()
            self._assign_widget_property_ids(dock)

        def _ensure_prolog_knowledge_dock(
            self,
            *,
            initial_directory: Path,
            project_paths,
            selected_path: Optional[Path] = None,
        ):
            dock = getattr(self, "prolog_knowledge_dock", None)
            dialog = getattr(self, "prolog_knowledge_dialog", None)
            if dock is not None and dialog is not None:
                return dock, dialog

            dock = QDockWidget("PROLOG – Wissen-Datenbanken", self)
            dock.setObjectName("prolog_knowledge_dock")
            dock.setFeatures(self._dock_features())
            dock.setAllowedAreas(Qt.LeftDockWidgetArea | Qt.RightDockWidgetArea)
            # Stage 67: no artificial minimum width; the dock is expanded to
            # the complete available work area when shown.
            dock.setMinimumWidth(0)
            dock.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)

            dialog = PrologKnowledgeDialog(
                dock,
                directory=initial_directory,
                project_paths=project_paths,
                selected_path=selected_path,
                dark_mode=self.dark_mode_enabled,
                embedded=True,
            )
            dialog.dock_close_requested.connect(dock.hide)
            dock.setWidget(dialog)
            self.addDockWidget(Qt.LeftDockWidgetArea, dock)
            dock.visibilityChanged.connect(
                self._prolog_knowledge_dock_visibility_changed
            )

            self.prolog_knowledge_dock = dock
            self.prolog_knowledge_dialog = dialog
            return dock, dialog

        def open_prolog_knowledge_browser(
            self, selected_path: Optional[Path] = None
        ) -> None:
            localize_dock = getattr(self, "localize_dock", None)
            if localize_dock is not None and localize_dock.isVisible():
                localize_dock.hide()

            project_paths = self._project_knowledge_paths()
            if selected_path is not None:
                initial_directory = Path(selected_path).parent
            elif project_paths:
                initial_directory = project_paths[0].parent
            elif self.current_project_path is not None:
                initial_directory = self.current_project_path.parent
            else:
                initial_directory = self.current_directory

            dock, dialog = self._ensure_prolog_knowledge_dock(
                initial_directory=initial_directory,
                project_paths=project_paths,
                selected_path=selected_path,
            )
            dialog.set_project_paths(project_paths)
            dialog.set_directory(initial_directory, selected_path=selected_path)
            if selected_path is not None:
                dialog.select_database_path(selected_path)
                dialog.open_selected_database()
            dialog.set_dark_mode(self.dark_mode_enabled)

            # Stage 66: the knowledge browser takes over the left docking area.
            # Remember whether the filesystem dock was visible so it can be
            # restored when the knowledge dock is closed.
            if hasattr(self, "left_dock"):
                if self.left_dock.isVisible():
                    self._knowledge_replaced_filesystem_dock = True
                self.left_dock.hide()
            dock.show()
            dock.raise_()
            self._expand_prolog_knowledge_dock()
            QTimer.singleShot(0, self._expand_prolog_knowledge_dock)
            dialog.setFocus(Qt.OtherFocusReason)

        def _show_project_prolog_knowledge_root_menu(
            self, item: QTreeWidgetItem, position
        ) -> None:
            menu = QMenu(self.project_tree)
            add_action = menu.addAction("Wissensdatenbank hinzufügen …")
            browser_action = menu.addAction("Wissensdatenbank-Browser öffnen")
            menu.addSeparator()
            clear_action = menu.addAction("Alle Referenzen entfernen")
            clear_action.setEnabled(item.childCount() > 0)
            menu.addSeparator()
            help_action = menu.addAction("Hilfe")
            selected = menu.exec_(
                self.project_tree.viewport().mapToGlobal(position)
            )
            if selected is add_action:
                self.add_project_knowledge_databases()
            elif selected is browser_action:
                self.open_prolog_knowledge_browser()
            elif selected is clear_action:
                self.clear_project_knowledge_databases()
            elif selected is help_action:
                self._show_message_box(
                    QMessageBox.Information,
                    "PROLOG Wissen-Datenbanken",
                    "Hier werden externe PROLOG-Wissen-Datenbanken getrennt vom "
                    "Programmcode gesammelt. Rechtsklick → 'Wissensdatenbank "
                    "hinzufügen …' fügt vorhandene *.pl/*.prolog-Dateien ein.\n\n"
                    "Der Browser kann Fakten und Regeln schrittweise abfragen; "
                    "die Dateien werden dadurch nicht verändert.",
                )

        def _show_project_prolog_knowledge_file_menu(
            self, item: QTreeWidgetItem, position
        ) -> None:
            menu = QMenu(self.project_tree)
            compile_action = menu.addAction("Kompilieren")
            compile_action.setShortcut(QKeySequence("F2"))
            browser_action = menu.addAction("Im Wissensdatenbank-Browser öffnen")
            source_action = menu.addAction("Quelltext öffnen")
            menu.addSeparator()
            remove_action = menu.addAction("Aus Projekt entfernen")
            selected = menu.exec_(
                self.project_tree.viewport().mapToGlobal(position)
            )
            if selected is compile_action:
                self.compile_selected_project_sources(preferred_item=item)
            elif selected is browser_action:
                path_text = str(item.data(0, Qt.UserRole + 302) or "").strip()
                if path_text:
                    self.open_prolog_knowledge_browser(Path(path_text))
            elif selected is source_action:
                self.open_prolog_knowledge_source(item)
            elif selected is remove_action:
                self.remove_project_knowledge_database(item)

        def _show_project_archive_root_menu(
            self, item: QTreeWidgetItem, position
        ) -> None:
            menu = QMenu(self.project_tree)
            new_action = menu.addAction("Neues Archiv …")
            remove_action = menu.addAction("Ausgewählte entfernen")
            remove_action.setEnabled(self._archive_scope_has_checked_items(item))
            menu.addSeparator()
            help_action = menu.addAction("Hilfe")
            selected = menu.exec_(
                self.project_tree.viewport().mapToGlobal(position)
            )
            if selected is new_action:
                self.create_project_archive_entry()
            elif selected is remove_action:
                self.remove_checked_project_archive_items(item)
            elif selected is help_action:
                self._show_project_archive_help()

        def _show_project_archive_item_menu(
            self, item: QTreeWidgetItem, position
        ) -> None:
            archive_item = (
                item if self._project_item_kind(item) == PROJECT_NODE_ARCHIVE
                else item.parent()
            )
            if archive_item is None:
                return
            menu = QMenu(self.project_tree)
            add_objects_action = menu.addAction("Objektdateien hinzufügen …")
            build_action = menu.addAction("Archiv erstellen")
            rename_action = menu.addAction("Umbenennen")
            menu.addSeparator()
            remove_action = menu.addAction("Ausgewählte entfernen")
            remove_action.setEnabled(self._archive_scope_has_checked_items(archive_item))
            build_action.setEnabled(archive_item.childCount() > 0)
            selected = menu.exec_(
                self.project_tree.viewport().mapToGlobal(position)
            )
            if selected is add_objects_action:
                self.add_project_archive_objects(archive_item)
            elif selected is build_action:
                self.build_project_archive(archive_item)
            elif selected is rename_action:
                self.rename_project_archive(archive_item)
            elif selected is remove_action:
                self.remove_checked_project_archive_items(archive_item)

        def _show_project_archive_help(self) -> None:
            self._show_message_box(
                QMessageBox.Information,
                "C-Archive im Projekt",
                "Unter C-Programme -> Archive können COFF32-/COFF64-Archive "
                "verwaltet werden. Ein Archivknoten besitzt eine Checkbox; "
                "sie markiert oder entmarkiert alle untergeordneten Objektdateien.\n\n"
                "'Archiv erstellen' schreibt aus den aufgeführten .o/.obj-Dateien "
                "eine .a-Datei. Beim Löschen werden ausschließlich Referenzen "
                "im aktuell gewählten Archivzweig entfernt; Dateien auf dem "
                "Datenträger bleiben erhalten.",
            )

        def create_project_archive_entry(self) -> Optional[QTreeWidgetItem]:
            directory = self._project_new_file_directory()
            filename, _selected = QFileDialog.getSaveFileName(
                self,
                "Archivknoten anlegen",
                str(directory / "library.a"),
                "Statisches Archiv (*.a);;Alle Dateien (*)",
            )
            if not filename:
                return None
            target = Path(filename)
            if target.suffix.casefold() != ".a":
                target = target.with_suffix(".a")
            item = self._add_project_archive(target, title=target.name)
            if item is not None:
                self.project_tree.setCurrentItem(item)
                item.setExpanded(True)
                if self.current_project_path is not None:
                    self.save_project()
                self.statusBar().showMessage(
                    f"Archivknoten angelegt: {target.name}"
                )
            return item

        def add_project_archive_objects(
            self, archive_item: QTreeWidgetItem
        ) -> None:
            if self._project_item_kind(archive_item) != PROJECT_NODE_ARCHIVE:
                return
            archive_path = str(archive_item.data(0, Qt.UserRole + 302) or "")
            initial = (
                str(Path(archive_path).parent)
                if archive_path else str(self._project_new_file_directory())
            )
            filenames, _selected = QFileDialog.getOpenFileNames(
                self,
                f"Objektdateien zu '{archive_item.text(0)}' hinzufügen",
                initial,
                "COFF-Objektdateien (*.o *.obj);;Alle Dateien (*)",
            )
            added = 0
            for filename in filenames:
                child = self._add_project_archive_object(
                    archive_item, Path(filename), title=Path(filename).name
                )
                if child is not None:
                    added += 1
            if added:
                self._refresh_archive_check_state(archive_item)
                if self.current_project_path is not None:
                    self.save_project()
                self.statusBar().showMessage(
                    f"{added} Objektdatei(en) zu {archive_item.text(0)} hinzugefügt"
                )

        def _project_archive_object_items(
            self, archive_item: QTreeWidgetItem
        ) -> List[QTreeWidgetItem]:
            return [
                archive_item.child(index)
                for index in range(archive_item.childCount())
                if self._project_item_kind(archive_item.child(index))
                == PROJECT_NODE_ARCHIVE_OBJECT
            ]

        def _archive_scope_has_checked_items(
            self, scope_item: QTreeWidgetItem
        ) -> bool:
            kind = self._project_item_kind(scope_item)
            if kind == PROJECT_NODE_ARCHIVE:
                if bool(scope_item.data(0, Qt.UserRole + 304)):
                    return True
                return any(
                    child.checkState(0) == Qt.Checked
                    for child in self._project_archive_object_items(scope_item)
                )
            if kind == PROJECT_NODE_ARCHIVE_ROOT:
                for index in range(scope_item.childCount()):
                    archive_item = scope_item.child(index)
                    if bool(archive_item.data(0, Qt.UserRole + 304)):
                        return True
                    if any(
                        child.checkState(0) == Qt.Checked
                        for child in self._project_archive_object_items(archive_item)
                    ):
                        return True
            return False

        def remove_checked_project_archive_items(
            self, scope_item: QTreeWidgetItem
        ) -> None:
            kind = self._project_item_kind(scope_item)
            if kind == PROJECT_NODE_ARCHIVE_OBJECT:
                scope_item = scope_item.parent()
                kind = self._project_item_kind(scope_item)
            if kind not in {PROJECT_NODE_ARCHIVE, PROJECT_NODE_ARCHIVE_ROOT}:
                return

            archives_to_remove: List[QTreeWidgetItem] = []
            objects_to_remove: List[Tuple[QTreeWidgetItem, QTreeWidgetItem]] = []
            archive_items = (
                [scope_item]
                if kind == PROJECT_NODE_ARCHIVE
                else [scope_item.child(i) for i in range(scope_item.childCount())]
            )
            for archive_item in archive_items:
                if self._project_item_kind(archive_item) != PROJECT_NODE_ARCHIVE:
                    continue
                if bool(archive_item.data(0, Qt.UserRole + 304)):
                    archives_to_remove.append(archive_item)
                    continue
                for child in self._project_archive_object_items(archive_item):
                    if child.checkState(0) == Qt.Checked:
                        objects_to_remove.append((archive_item, child))

            total = len(archives_to_remove) + len(objects_to_remove)
            if total <= 0:
                return
            answer = self._show_message_box(
                QMessageBox.Question,
                "Archiv-Einträge entfernen",
                f"Sollen {total} markierte Archiv-/Objekteinträge aus dem "
                "aktuellen Zweig entfernt werden?\n\n"
                "Dateien auf dem Datenträger werden nicht gelöscht.",
                buttons=QMessageBox.Yes | QMessageBox.No,
                default_button=QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return

            touched_archives = set()
            for archive_item, child in objects_to_remove:
                if archive_item in archives_to_remove:
                    continue
                archive_item.takeChild(archive_item.indexOfChild(child))
                touched_archives.add(archive_item)
            for archive_item in archives_to_remove:
                parent = archive_item.parent()
                if parent is not None:
                    parent.takeChild(parent.indexOfChild(archive_item))
            for archive_item in touched_archives:
                self._refresh_archive_check_state(archive_item)
            self.set_project_modified(True)
            if self.current_project_path is not None:
                self.save_project()
            self.statusBar().showMessage(
                f"{total} Archiv-/Objekteintrag(e) entfernt"
            )

        def rename_project_archive(self, archive_item: QTreeWidgetItem) -> None:
            if self._project_item_kind(archive_item) != PROJECT_NODE_ARCHIVE:
                return
            current_name = archive_item.text(0) or "library.a"
            value, accepted = QInputDialog.getText(
                self,
                "Archiv umbenennen",
                "Neuer Archivname:",
                QLineEdit.Normal,
                current_name,
            )
            if not accepted:
                return
            value = value.strip()
            if not value or Path(value).name != value:
                self.show_error(
                    "Ungültiger Archivname",
                    "Bitte nur einen Dateinamen ohne Verzeichnis angeben.",
                )
                return
            if Path(value).suffix.casefold() != ".a":
                value += ".a"
            old_path_text = str(archive_item.data(0, Qt.UserRole + 302) or "")
            if old_path_text:
                old_path = Path(old_path_text)
                target = old_path.with_name(value)
            else:
                target = self._project_new_file_directory() / value
            if old_path_text and old_path.exists() and target != old_path:
                if target.exists():
                    self.show_error(
                        "Archiv existiert bereits",
                        f"Die Zieldatei existiert bereits:\n{target}",
                    )
                    return
                try:
                    old_path.rename(target)
                except OSError as exc:
                    self.show_error("Archiv konnte nicht umbenannt werden", str(exc))
                    return
            archive_item.setText(0, value)
            archive_item.setData(0, Qt.UserRole + 302, str(target))
            archive_item.setToolTip(0, str(target))
            self.set_project_modified(True)
            if self.current_project_path is not None:
                self.save_project()
            self.statusBar().showMessage(f"Archiv umbenannt: {value}")

        def build_project_archive(self, archive_item: QTreeWidgetItem) -> None:
            if self._project_item_kind(archive_item) != PROJECT_NODE_ARCHIVE:
                return
            object_items = self._project_archive_object_items(archive_item)
            if not object_items:
                self.show_error(
                    "Archiv erstellen",
                    "Dem Archiv sind noch keine Objektdateien zugeordnet.",
                )
                return
            members = []
            machine = None
            for child in object_items:
                path_text = str(child.data(0, Qt.UserRole + 302) or "")
                path = Path(path_text)
                if not path.exists():
                    self.show_error(
                        "Objektdatei fehlt",
                        f"Die Objektdatei wurde nicht gefunden:\n{path}",
                    )
                    return
                try:
                    payload = path.read_bytes()
                except OSError as exc:
                    self.show_error("Objektdatei konnte nicht gelesen werden", str(exc))
                    return
                if len(payload) < 2:
                    self.show_error("Ungültige Objektdatei", str(path))
                    return
                current_machine = struct.unpack_from("<H", payload, 0)[0]
                try:
                    if current_machine == IMAGE_FILE_MACHINE_I386:
                        parse_coff32_object(payload)
                    elif current_machine == IMAGE_FILE_MACHINE_AMD64:
                        parse_coff64_object(payload)
                    else:
                        raise ValueError(
                            f"Unbekannte COFF-Machine 0x{current_machine:04X}"
                        )
                except (PE32AssemblerError, PE64AssemblerError, ValueError) as exc:
                    self.show_error(
                        "Ungültige COFF-Objektdatei",
                        f"{path.name}: {exc}",
                    )
                    return
                if machine is None:
                    machine = current_machine
                elif machine != current_machine:
                    self.show_error(
                        "Gemischte COFF-Architekturen",
                        "Ein Archiv darf nicht gleichzeitig COFF32-i386- und "
                        "COFF64-AMD64-Objekte enthalten.",
                    )
                    return
                members.append((path.name, payload))

            target_text = str(archive_item.data(0, Qt.UserRole + 302) or "")
            if target_text:
                target = Path(target_text)
            else:
                target = self._project_new_file_directory() / archive_item.text(0)
            if target.suffix.casefold() != ".a":
                target = target.with_suffix(".a")
            try:
                target.parent.mkdir(parents=True, exist_ok=True)
                archive_data = (
                    create_coff64_archive(members)
                    if machine == IMAGE_FILE_MACHINE_AMD64
                    else create_coff32_archive(members)
                )
                target.write_bytes(archive_data)
            except (OSError, PE32AssemblerError, PE64AssemblerError) as exc:
                self.show_error("Archiv konnte nicht erstellt werden", str(exc))
                return
            archive_item.setText(0, target.name)
            archive_item.setData(0, Qt.UserRole + 302, str(target))
            archive_item.setToolTip(0, str(target))
            self.set_project_modified(True)
            if self.current_project_path is not None:
                self.save_project()
            self.log(
                f"PROJEKT ARCHIV: {len(members)} Objekt(e) -> {target}"
            )
            self.statusBar().showMessage(
                f"Archiv erstellt: {target.name} ({len(members)} Objekt(e))"
            )
            if target.parent.resolve() == self.current_directory:
                self.populate_file_list()

        def add_project_entries(self, item: QTreeWidgetItem) -> None:
            """Fügt vorhandene Dateien in die angewählte Projektkategorie ein."""
            root = item if item.parent() is None else item.parent()
            category_key = str(root.data(0, Qt.UserRole + 301) or "other")
            extensions = PROJECT_CATEGORY_EXTENSIONS.get(category_key, ())
            if extensions:
                patterns = " ".join(f"*{extension}" for extension in extensions)
                file_filter = (
                    f"{root.text(0)} ({patterns});;Alle Dateien (*)"
                )
            else:
                file_filter = "Alle Dateien (*)"
            initial = str(
                self.current_project_path.parent
                if self.current_project_path is not None
                else self.current_directory
            )
            filenames, _selected = QFileDialog.getOpenFileNames(
                self,
                f"Dateien zu '{root.text(0)}' hinzufügen",
                initial,
                file_filter,
            )
            added = 0
            for filename in filenames:
                path = Path(filename)
                child = self._add_project_entry(
                    category_key, path, title=path.name
                )
                if child is not None:
                    added += 1
            if added and self.current_project_path is not None:
                self.save_project()
            if added:
                root.setExpanded(True)
                self.statusBar().showMessage(
                    f"{added} Projekteintrag/Projekteinträge hinzugefügt"
                )

        def clear_project_entries(self, item: QTreeWidgetItem) -> None:
            """Entfernt nur normale Kategorie-Referenzen; Archive bleiben geschützt."""
            root = item if item.parent() is None else item.parent()
            removable = [
                root.child(index)
                for index in range(root.childCount())
                if self._project_item_kind(root.child(index)) not in {
                    PROJECT_NODE_ARCHIVE_ROOT,
                    PROJECT_NODE_PROLOG_KNOWLEDGE_ROOT,
                    PROJECT_NODE_PASCAL_TARGET,
                }
            ]
            count = len(removable)
            if count <= 0:
                return
            answer = self._show_message_box(
                QMessageBox.Question,
                "Projekteinträge löschen",
                f"Sollen alle {count} normalen Einträge aus '{root.text(0)}' "
                "entfernt werden?\n\n"
                "Die Dateien auf dem Datenträger werden nicht gelöscht oder "
                "umbenannt. Der geschützte Archivknoten bleibt erhalten.",
                buttons=QMessageBox.Yes | QMessageBox.No,
                default_button=QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return
            for child in removable:
                root.takeChild(root.indexOfChild(child))
            self.set_project_modified(True)
            if self.current_project_path is not None:
                self.save_project()
            self.statusBar().showMessage(
                f"{count} Projekteinträge aus '{root.text(0)}' entfernt"
            )

        def show_project_item_help(self, item: QTreeWidgetItem) -> None:
            root = item if item.parent() is None else item.parent()
            key = str(root.data(0, Qt.UserRole + 301) or "other")
            extensions = PROJECT_CATEGORY_EXTENSIONS.get(key, ())
            extension_text = ", ".join(extensions) if extensions else "beliebige Dateien"
            self._show_message_box(
                QMessageBox.Information,
                f"Projektkategorie: {root.text(0)}",
                "Diese Kategorie sammelt Projektdateien des entsprechenden "
                f"Typs. Unterstützte Erweiterungen: {extension_text}.\n\n"
                "Ein Eintrag wird mit einem Klick geöffnet. "
                "Löschen entfernt nur die Referenz aus dem Projekt, nicht die "
                "Datei vom Datenträger.",
            )

        def rename_project_item(self, item: QTreeWidgetItem) -> None:
            if item.parent() is None:
                return
            value, accepted = QInputDialog.getText(
                self,
                "Projekteintrag umbenennen",
                "Anzeigename:",
                QLineEdit.Normal,
                item.text(0),
            )
            value = value.strip()
            if accepted and value and value != item.text(0):
                item.setText(0, value)
                self.set_project_modified(True)

        def copy_project_item(self, item: QTreeWidgetItem) -> None:
            if item.parent() is None:
                return
            payload = {
                "title": item.text(0),
                "path": str(item.data(0, Qt.UserRole + 302) or ""),
            }
            QApplication.clipboard().setText(
                "D64PROJECTITEM:" + json.dumps(payload, ensure_ascii=False)
            )
            self.statusBar().showMessage("Projekteintrag kopiert")

        def paste_project_item(self, item: QTreeWidgetItem) -> None:
            root = item if item.parent() is None else item.parent()
            category_key = str(root.data(0, Qt.UserRole + 301) or "other")
            clipboard_text = QApplication.clipboard().text().strip()
            if not clipboard_text:
                return
            title = ""
            path_value = clipboard_text
            if clipboard_text.startswith("D64PROJECTITEM:"):
                try:
                    payload = json.loads(
                        clipboard_text[len("D64PROJECTITEM:"):]
                    )
                    title = str(payload.get("title", ""))
                    path_value = str(payload.get("path", ""))
                except json.JSONDecodeError:
                    return
            candidate = Path(path_value.strip().strip('"'))
            if not str(candidate):
                return
            child = self._add_project_entry(
                category_key,
                candidate,
                title=title,
            )
            if child is not None:
                self.project_tree.setCurrentItem(child)

        def _project_removable_leaf_selection(
            self,
            preferred_item: Optional[QTreeWidgetItem] = None,
        ) -> List[QTreeWidgetItem]:
            selected = list(self.project_tree.selectedItems())
            if preferred_item is not None and preferred_item not in selected:
                selected = [preferred_item]
            if not selected and self.project_tree.currentItem() is not None:
                selected = [self.project_tree.currentItem()]
            protected_kinds = {
                PROJECT_NODE_ARCHIVE_ROOT,
                PROJECT_NODE_ARCHIVE,
                PROJECT_NODE_PROLOG_KNOWLEDGE_ROOT,
                PROJECT_NODE_PASCAL_TARGET,
                PROJECT_NODE_PASCAL_MODULE_ROOT,
                PROJECT_NODE_PASCAL_UNIT_ROOT,
                PROJECT_NODE_PASCAL_UNIT_NAMESPACE,
                PROJECT_NODE_PASCAL_TABLE_ROOT,
                PROJECT_NODE_DBASE_GROUP,
            }
            return [
                item for item in selected
                if item.parent() is not None
                and item.childCount() == 0
                and self._project_item_kind(item) not in protected_kinds
                and bool(str(item.data(0, Qt.UserRole + 302) or "").strip())
            ]

        def delete_selected_project_leaves(
            self,
            *,
            preferred_item: Optional[QTreeWidgetItem] = None,
        ) -> bool:
            leaves = self._project_removable_leaf_selection(preferred_item)
            if not leaves:
                self.statusBar().showMessage(
                    "Entf: Keine entfernbaren Projektblätter markiert", 5000
                )
                return False

            names = "\n".join(f"  • {item.text(0)}" for item in leaves[:12])
            if len(leaves) > 12:
                names += f"\n  • … und {len(leaves) - 12} weitere"
            box = QMessageBox(self)
            box.setWindowIcon(self.windowIcon())
            box.setWindowTitle("Projektblätter entfernen")
            box.setIcon(QMessageBox.Question)
            box.setText(
                "Sollen die markierten Blätter aus der Projekt-TreeList "
                "entfernt werden?\n\n"
                + names
                + "\n\nDie Dateien auf dem Datenträger bleiben erhalten."
            )
            delete_button = box.addButton(
                "OK - Löschen", QMessageBox.DestructiveRole
            )
            cancel_button = box.addButton(
                "Abbrechen", QMessageBox.RejectRole
            )
            box.setDefaultButton(cancel_button)
            self._apply_message_box_theme(box)
            box.exec_()
            if box.clickedButton() is not delete_button:
                return False

            removed = 0
            archive_parents: List[QTreeWidgetItem] = []
            for item in leaves:
                parent = item.parent()
                if parent is None:
                    continue
                kind = self._project_item_kind(item)
                parent.takeChild(parent.indexOfChild(item))
                removed += 1
                if kind == PROJECT_NODE_ARCHIVE_OBJECT:
                    archive_parents.append(parent)
                if (
                    kind == PROJECT_NODE_PASCAL_TARGET_SOURCE
                    and self._project_item_kind(parent)
                    == PROJECT_NODE_PASCAL_UNIT_NAMESPACE
                    and parent.childCount() == 0
                ):
                    group = parent.parent()
                    if group is not None:
                        target = str(
                            parent.data(0, Qt.UserRole + 305) or ""
                        ).casefold()
                        role = str(
                            parent.data(0, Qt.UserRole + 306) or ""
                        ).casefold()
                        namespace = str(
                            parent.data(0, Qt.UserRole + 307)
                            or parent.text(0)
                        ).casefold()
                        group.takeChild(group.indexOfChild(parent))
                        getattr(
                            self, "project_pascal_unit_namespace_nodes", {}
                        ).pop((target, role, namespace), None)

            for archive_parent in archive_parents:
                self._refresh_archive_check_state(archive_parent)
            if removed:
                self.set_project_modified(True)
                if self.current_project_path is not None:
                    self.save_project()
                self.statusBar().showMessage(
                    f"{removed} Projektblatt/-blätter entfernt", 7000
                )
            return removed > 0

        def delete_project_item(self, item: QTreeWidgetItem) -> None:
            parent = item.parent()
            if parent is None:
                return
            answer = self._show_message_box(
                QMessageBox.Question,
                "Projekteintrag löschen",
                f"Soll '{item.text(0)}' aus dem Projekt entfernt werden?\n\n"
                "Die Datei auf dem Datenträger bleibt erhalten.",
                buttons=QMessageBox.Yes | QMessageBox.No,
                default_button=QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return
            parent.takeChild(parent.indexOfChild(item))
            self.set_project_modified(True)

        def open_project_item(
            self,
            item: QTreeWidgetItem,
            _column: int = 0,
        ) -> None:
            kind = self._project_item_kind(item)
            if kind == PROJECT_NODE_MARKER_LINE:
                self._jump_to_project_marker(item)
                return
            if kind in {PROJECT_NODE_MARKER_ROOT, PROJECT_NODE_MARKER_FILE}:
                item.setExpanded(not item.isExpanded())
                return
            if kind in {
                PROJECT_NODE_PASCAL_TARGET,
                PROJECT_NODE_PASCAL_MODULE_ROOT,
                PROJECT_NODE_PASCAL_UNIT_ROOT,
                PROJECT_NODE_PASCAL_UNIT_NAMESPACE,
                PROJECT_NODE_PASCAL_TABLE_ROOT,
                PROJECT_NODE_DBASE_GROUP,
            }:
                item.setExpanded(not item.isExpanded())
                return
            if kind == PROJECT_NODE_DBASE_FILE:
                path_value = str(item.data(0, Qt.UserRole + 302) or "").strip()
                role = str(item.data(0, Qt.UserRole + 306) or "").casefold()
                if not path_value:
                    return
                path = Path(path_value)
                if not path.is_file():
                    self.show_error(
                        "dBase-Projektdatei nicht gefunden",
                        f"Datei nicht gefunden:\n{path}",
                    )
                    return
                if role == "programs":
                    if self.open_document(path, language_override="dbase"):
                        self._remember_recent_file(path)
                        self.statusBar().showMessage(
                            f"{path.name}: dBase-Texteditor geöffnet", 6000
                        )
                elif role == "forms":
                    if self.open_dbase_form_file(path):
                        self._remember_recent_file(path)
                        self.statusBar().showMessage(
                            f"{path.name}: Formular-Designer geöffnet", 6000
                        )
                elif role == "tables":
                    if self.open_dbase_table_file(path):
                        self._remember_recent_file(path)
                        self.statusBar().showMessage(
                            f"{path.name}: Tabellen-Designer geöffnet", 6000
                        )
                elif role == "queries":
                    self.show_dbase_sql_builder()
                    if self.dbase_sql_builder_widget is not None:
                        self.dbase_sql_builder_widget.load_project(path)
                        self.statusBar().showMessage(
                            f"{path.name}: SQL Builder geöffnet", 6000
                        )
                elif role == "reports":
                    if self.open_dbase_report_file(path):
                        self._remember_recent_file(path)
                        self.statusBar().showMessage(
                            f"{path.name}: Bericht Builder geöffnet", 6000
                        )
                elif role == "labels":
                    self.open_dbase_label_file(path)
                elif role == "objects":
                    # Objektdateien sind Linkerressourcen; Doppelklick zeigt
                    # die vorhandene Objekt-Information statt Binärtext.
                    self.show_project_object_information(item)
                elif role == "archives":
                    # Archive werden beim Linken als Symbolquellen verwendet;
                    # Doppelklick zeigt zugleich die vorhandene Archivanalyse.
                    self.show_project_archive_information(item)
                return
            if kind == PROJECT_NODE_PASCAL_TABLE_FILE:
                path_value = str(item.data(0, Qt.UserRole + 302) or "").strip()
                if not path_value:
                    return
                path = Path(path_value)
                if not path.is_file():
                    self.show_error(
                        "Pascal-Projekttabelle nicht gefunden",
                        f"DBF-Datei nicht gefunden:\n{path}",
                    )
                    return
                if self.open_dbase_table_file(path):
                    self._remember_recent_file(path)
                    target = str(item.data(0, Qt.UserRole + 305) or "").casefold()
                    target_name = "Windows PE32" if target == "pe32" else "Windows PE32+"
                    self.statusBar().showMessage(
                        f"{path.name}: Tabellen-Designer und Tabellen-Editor geöffnet ({target_name})",
                        6000,
                    )
                return
            if kind == PROJECT_NODE_PASCAL_TARGET_SOURCE:
                path_value = str(item.data(0, Qt.UserRole + 302) or "")
                target = str(item.data(0, Qt.UserRole + 305) or "").casefold()
                if path_value:
                    path = Path(path_value)
                    if path.exists():
                        if (
                            path.suffix.casefold() in {".pas", ".pp"}
                            and target in {"pe32", "pe64"}
                        ):
                            document = self._project_pascal_document(path, target)
                            if document is not None:
                                target_name = (
                                    "Windows PE32"
                                    if target == "pe32"
                                    else "Windows PE32+"
                                )
                                self.statusBar().showMessage(
                                    f"{path.name}: Compilerziel {target_name}",
                                    5000,
                                )
                        else:
                            self.open_document(path)
                    else:
                        self.show_error(
                            "Pascal-Projektdatei nicht gefunden",
                            f"Datei nicht gefunden:\n{path}",
                        )
                return
            if kind == PROJECT_NODE_ARCHIVE_ROOT:
                item.setExpanded(not item.isExpanded())
                return
            if kind == PROJECT_NODE_PROLOG_KNOWLEDGE_ROOT:
                self.open_prolog_knowledge_browser()
                return
            if kind == PROJECT_NODE_PROLOG_KNOWLEDGE_FILE:
                path_value = str(item.data(0, Qt.UserRole + 302) or "")
                if path_value:
                    self.open_prolog_knowledge_browser(Path(path_value))
                return
            if kind == PROJECT_NODE_ARCHIVE:
                item.setExpanded(True)
                self.show_project_archive_information(item)
                return
            if kind == PROJECT_NODE_ARCHIVE_OBJECT:
                self.show_project_object_information(item)
                return
            if item.parent() is None:
                item.setExpanded(not item.isExpanded())
                return
            path_value = str(item.data(0, Qt.UserRole + 302) or "")
            if not path_value:
                return
            path = Path(path_value)
            if not path.exists():
                self.show_error(
                    "Projektdatei nicht gefunden",
                    f"Der Projekteintrag verweist auf eine nicht vorhandene Datei:\n{path}",
                )
                return
            category_key = str(
                item.data(0, Qt.UserRole + 301) or ""
            ).casefold()
            # Stage 256: .prg ist auch im Commodore-C64-Projektzweig ein
            # Binärprogramm. open_document() erzeugt daraus das Disassembly
            # für den Rohdaten-Tab und legt die unveränderten Bytes in den
            # Hex-Editor (4 Byte links + Trennlinie + 4 Byte rechts).
            if category_key == "c64" and path.suffix.casefold() == ".prg":
                self.open_document(path)
                return
            if path.suffix.casefold() in self.EDITOR_EXTENSIONS:
                self.open_document(path)
            else:
                self.open_path(path)

